class _CookieRefreshCallable(Protocol):
    def __call__(
        self,
        *,
        username: str,
        password: str,
        cookie_file: str | Path,
        headless: bool,
        timeout_seconds: int,
    ) -> dict[str, str]: ...


class _ExecuteReturningWithPool(Protocol):
    def __call__(
        self,
        query: str,
        params: Iterable[Any] | None = None,
        *,
        conn: Any | None = None,
        pool_name: str = "default",
    ) -> list[dict[str, Any]]: ...


class _IncrementRunCountersOnJobFinishWithConn(Protocol):
    def __call__(
        self,
        *,
        run_id: str,
        stage: str,
        prior_status: str,
        new_status: str,
        prior_items_found: int,
        new_items_found: int,
        conn: Any | None = None,
    ) -> None: ...


