def _normalize_youtube_source_mode(value: str | None) -> str:
    normalized = str(value or "").strip().lower() or DEFAULT_YOUTUBE_SOURCE_MODE
    if normalized not in SUPPORTED_YOUTUBE_SOURCE_MODES:
        return DEFAULT_YOUTUBE_SOURCE_MODE
    return normalized


def _normalize_youtube_catalog_surfaces(value: Any) -> list[str]:
    if value is None or value == "":
        raw_items: Sequence[Any] = ("videos", "shorts", "posts")
    elif isinstance(value, str):
        raw_items = [item for item in re.split(r"[,|]", value) if item.strip()]
    elif isinstance(value, Sequence) and not isinstance(value, (bytes, bytearray)):
        raw_items = value
    else:
        raw_items = [value]

    normalized: list[str] = []
    for item in raw_items:
        surface = str(item or "").strip().lower()
        if surface in {"video", "channel_videos"}:
            surface = "videos"
        elif surface in {"short", "reels"}:
            surface = "shorts"
        elif surface in {"community", "community_posts", "post"}:
            surface = "posts"
        if surface not in {"videos", "shorts", "posts"} or surface in normalized:
            continue
        normalized.append(surface)
    return normalized or ["videos", "shorts", "posts"]


def _expand_youtube_surface_job_configs(platform: Any, job_config: Mapping[str, Any]) -> list[dict[str, Any]]:
    base_config = dict(job_config)
    if _normalize_platform_name(platform) != "youtube":
        return [base_config]
    surfaces = _normalize_youtube_catalog_surfaces(
        base_config.get("youtube_surfaces")
        or base_config.get("youtube_surface")
        or base_config.get("surfaces")
        or base_config.get("surface")
    )
    if len(surfaces) <= 1:
        surface = surfaces[0] if surfaces else "videos"
        return [
            {
                **base_config,
                "youtube_surfaces": [surface],
                "youtube_surface": surface,
                "youtube_worker_set": f"youtube_{surface}",
            }
        ]
    return [
        {
            **base_config,
            "youtube_surfaces": [surface],
            "youtube_surface": surface,
            "youtube_worker_set": f"youtube_{surface}",
        }
        for surface in surfaces
    ]


def _resolve_runner_count(value: int | None) -> int:
    if value is None:
        return DEFAULT_RUNNER_COUNT
    return max(1, min(int(value), 2))


def _catalog_backfill_run_scheduler_lanes(runner_count: int) -> list[str]:
    safe_runner_count = max(1, int(runner_count or 1))
    return [chr(65 + index) for index in range(min(safe_runner_count, 26))]


def _catalog_full_history_partition_supported(platform: str | None) -> bool:
    return (_normalize_platform_name(platform) or "") in {"instagram", "tiktok"}


def _shared_account_catalog_frontier_supported(
    *,
    platform: str | None,
    pipeline_ingest_mode: str | None,
    bounded_window: bool = False,
) -> bool:
    del bounded_window
    return (
        _normalize_platform_name(platform) == "instagram"
        and str(pipeline_ingest_mode or "").strip().lower() == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
    )


def _shared_account_prefers_frontier_strategy(
    *,
    platform: str | None,
    pipeline_ingest_mode: str | None,
    bounded_window: bool = False,
    resume_frontier_requested: bool = False,
    expected_total_posts: int | None = None,
    catalog_total_posts: int | None = None,
) -> bool:
    if not _shared_account_catalog_frontier_supported(
        platform=platform,
        pipeline_ingest_mode=pipeline_ingest_mode,
        bounded_window=bounded_window,
    ):
        return False
    if bounded_window:
        return True
    if resume_frontier_requested:
        return True
    expected_total = _normalize_non_negative_int(expected_total_posts)
    catalog_total = _normalize_non_negative_int(catalog_total_posts)
    return expected_total > 0 and catalog_total < expected_total


def _shared_account_uses_frontier_strategy(config: Mapping[str, Any] | None, *, platform: str | None = None) -> bool:
    metadata = _metadata_dict(config)
    if _shared_account_catalog_frontier_supported(
        platform=platform or metadata.get("platform"),
        pipeline_ingest_mode=metadata.get("pipeline_ingest_mode"),
        bounded_window=bool(
            _catalog_backfill_has_bounded_window(
                date_start=_coerce_dt(metadata.get("date_start")),
                date_end=_coerce_dt(metadata.get("date_end")),
            )
        ),
    ):
        strategy = str(metadata.get("partition_strategy") or metadata.get("runner_strategy") or "").strip().lower()
        return strategy == CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
    return False


def _shared_account_prefers_partitioned_backfill_recovery(
    config: Mapping[str, Any] | None,
    *,
    platform: str | None = None,
) -> bool:
    metadata = _metadata_dict(config)
    normalized_platform = _normalize_platform_name(platform or metadata.get("platform"))
    if normalized_platform != "instagram":
        return False
    if str(metadata.get("pipeline_ingest_mode") or "").strip().lower() != SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
        return False
    if _catalog_backfill_has_bounded_window(
        date_start=_coerce_dt(metadata.get("date_start")),
        date_end=_coerce_dt(metadata.get("date_end")),
    ):
        return False
    if str(metadata.get("catalog_action") or "").strip().lower() == "resume_tail":
        return False
    if str(metadata.get("resume_frontier_cursor") or "").strip():
        return False
    # Single-hop recovery: allow only one discovery recovery requeue before
    # forcing direct shared-account posts fallback.
    recovery_depth = _normalize_non_negative_int(metadata.get("recovery_depth"))
    if recovery_depth >= 1:
        return False
    return _catalog_full_history_partition_supported(normalized_platform)


def _shared_account_error_is_database_capacity(error_class: Any = None, message: Any = None) -> bool:
    normalized_class = str(error_class or "").strip().lower()
    normalized_message = str(message or "").strip().lower()
    if normalized_class == "databaseserviceunavailableerror":
        return True
    return any(
        token in normalized_message
        for token in (
            "emaxconnsession",
            "max clients reached",
            "pool exhausted",
            "database pool",
            "ssl connection has been closed unexpectedly",
            "server closed the connection unexpectedly",
            "connection already closed",
            "connection is closed",
        )
    )


