class SocialWorkerUnavailableError(ValueError):
    """Raised when queue mode is enabled but no healthy social worker is active."""

    def __init__(self, message: str, *, worker_health: dict[str, Any]):
        super().__init__(message)
        self.worker_health = worker_health


# ---------------------------------------------------------------------------
# General helpers


def _now_utc() -> datetime:
    return datetime.now(tz=UTC)


def _env_truthy(name: str, *, default: bool = False) -> bool:
    raw = (os.getenv(name) or "").strip().lower()
    if not raw:
        return default
    return raw in {"1", "true", "yes", "on"}


def is_queue_enabled() -> bool:
    return _env_truthy("SOCIAL_QUEUE_ENABLED", default=False)


def _resolve_positive_int_env(name: str, default: int, *, minimum: int = 1) -> int:
    raw = (os.getenv(name) or "").strip()
    if not raw:
        return max(minimum, default)
    try:
        return max(minimum, int(raw))
    except ValueError:
        return max(minimum, default)


def _resolve_int_env_with_bounds(name: str, default: int, *, minimum: int, maximum: int) -> int:
    value = _resolve_positive_int_env(name, default, minimum=minimum)
    return max(minimum, min(maximum, value))


def _resolve_non_negative_float_env(name: str, default: float) -> float:
    raw = (os.getenv(name) or "").strip()
    if not raw:
        return max(0.0, float(default))
    try:
        return max(0.0, float(raw))
    except ValueError:
        return max(0.0, float(default))


def _normalize_worker_stage(stage: str | None) -> str:
    value = (stage or "").strip().lower()
    if not value:
        return "any"
    if value in {
        "posts",
        "comments",
        INSTAGRAM_MEDIA_MIRROR_STAGE,
        COMMENT_MEDIA_MIRROR_STAGE,
        SHARED_ACCOUNT_DISCOVERY_STAGE,
        SHARED_ACCOUNT_POSTS_STAGE,
        POST_CLASSIFY_STAGE,
        SEASON_MATERIALIZE_STAGE,
        ANALYTICS_REFRESH_STAGE,
        "any",
    }:
        return value
    return "any"


def _normalize_worker_status(status: str | None) -> str:
    value = (status or "").strip().lower()
    if value in {"starting", "idle", "working", "stopped"}:
        return value
    return "idle"


def _configured_execution_metadata() -> dict[str, Any]:
    return dict(execution_metadata())


def _shared_account_expected_total_posts_key(platform: Any, account_handle: Any) -> str:
    normalized_platform = _normalize_platform_name(platform) or str(platform or "").strip().lower()
    normalized_account = _normalize_account_handle(account_handle) or str(account_handle or "").strip().lower()
    return f"{normalized_platform}:{normalized_account}"


def _catalog_backfill_has_bounded_window(*, date_start: datetime | None, date_end: datetime | None) -> bool:
    bounded_start = _coerce_dt(date_start)
    bounded_end = _coerce_dt(date_end)
    return bounded_start is not None and bounded_end is not None and bounded_end >= bounded_start


def _normalize_catalog_backfill_window(
    *,
    date_start: datetime | None,
    date_end: datetime | None,
) -> tuple[datetime | None, datetime | None]:
    start_supplied = date_start is not None and str(date_start).strip() != ""
    end_supplied = date_end is not None and str(date_end).strip() != ""
    if start_supplied != end_supplied:
        raise ValueError("date_start and date_end must be supplied together for a bounded catalog backfill.")
    if not start_supplied:
        return None, None
    bounded_start = _coerce_dt(date_start)
    bounded_end = _coerce_dt(date_end)
    if bounded_start is None or bounded_end is None:
        raise ValueError("date_start and date_end must be valid timestamps for a bounded catalog backfill.")
    if bounded_end <= bounded_start:
        raise ValueError("date_end must be later than date_start for a bounded catalog backfill.")
    return bounded_start, bounded_end


def _shared_account_catalog_requires_modal_executor(
    *,
    platform: Any,
    pipeline_ingest_mode: str | None,
) -> bool:
    normalized_platform = _normalize_platform_name(platform)
    normalized_ingest_mode = str(pipeline_ingest_mode or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    return (
        normalized_platform in set(CATALOG_SUPPORTED_PLATFORMS)
        and normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
    )


def _shared_account_catalog_requires_trusted_local_worker_lane(
    *,
    platform: Any,
    pipeline_ingest_mode: str | None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> bool:
    del platform, pipeline_ingest_mode, date_start, date_end
    return False


def _job_required_execution_backend(job_config: Mapping[str, Any] | None, *, platform: Any = None) -> str | None:
    if not isinstance(job_config, Mapping):
        return None
    explicit_backend = str(job_config.get("required_execution_backend") or "").strip().lower()
    if explicit_backend:
        return explicit_backend
    if bool(job_config.get("allow_local_dev_inline_bypass")):
        return None
    if _shared_account_catalog_requires_modal_executor(
        platform=platform or job_config.get("platform"),
        pipeline_ingest_mode=str(job_config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE),
    ):
        return "modal"
    return None


def _job_requires_modal_executor(job_config: Mapping[str, Any] | None, *, platform: Any = None) -> bool:
    return _job_required_execution_backend(job_config, platform=platform) == "modal"


def _job_has_modal_dispatch_contract(job_config: Mapping[str, Any] | None, *, platform: Any = None) -> bool:
    if not isinstance(job_config, Mapping):
        return False
    if _job_required_execution_backend(job_config, platform=platform) == "modal":
        return True
    candidates: list[Mapping[str, Any]] = [job_config]
    for key in ("required_runtime_version", "created_by_runtime_version", "runtime_version"):
        value = job_config.get(key)
        if isinstance(value, Mapping):
            candidates.append(value)
    for candidate in candidates:
        backend = (
            str(
                candidate.get("required_execution_backend")
                or candidate.get("execution_backend_canonical")
                or candidate.get("execution_backend")
                or ""
            )
            .strip()
            .lower()
        )
        if backend == "modal":
            return True
        if str(candidate.get("modal_function") or "").strip():
            return True
    return False


def _job_required_lane_blocks_modal_dispatch(
    job_config: Mapping[str, Any] | None,
    *,
    platform: Any = None,
) -> bool:
    return _job_requires_dedicated_worker_lane(job_config, platform=platform) and not _job_has_modal_dispatch_contract(
        job_config,
        platform=platform,
    )


def _job_allows_parallel_same_account_dispatch(job_config: Mapping[str, Any] | None) -> bool:
    config = _metadata_dict(job_config)
    if str(config.get("runner_strategy") or "").strip().lower() != "parallel_detail_refresh":
        return False
    configured_posts_cap = max(
        _normalize_non_negative_int(config.get("details_refresh_shard_count")),
        _normalize_non_negative_int(config.get("details_refresh_worker_count")),
        _normalize_non_negative_int(config.get("runner_count")),
    )
    return configured_posts_cap > 1


def _inline_fallback_followup_worker_id(
    job_config: Mapping[str, Any] | None,
    *,
    worker_id: str | None,
) -> str | None:
    if not isinstance(job_config, Mapping) or not bool(job_config.get("allow_local_dev_inline_bypass")):
        return None
    normalized_worker_id = str(worker_id or "").strip()
    if not normalized_worker_id or normalized_worker_id.startswith("modal:"):
        return None
    return normalized_worker_id


def _normalize_required_worker_lane(value: Any) -> str | None:
    normalized = str(value or "").strip().lower()
    return normalized or None


def _job_required_worker_lane(job_config: Mapping[str, Any] | None) -> str | None:
    if not isinstance(job_config, Mapping):
        return None
    return _normalize_required_worker_lane(job_config.get("required_worker_lane"))


def _job_requires_dedicated_worker_lane(job_config: Mapping[str, Any] | None, *, platform: Any = None) -> bool:
    required_lane = _job_required_worker_lane(job_config)
    if required_lane:
        return True
    return _shared_account_catalog_requires_trusted_local_worker_lane(
        platform=platform or (job_config or {}).get("platform"),
        pipeline_ingest_mode=str((job_config or {}).get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE),
        date_start=_coerce_dt((job_config or {}).get("date_start")),
        date_end=_coerce_dt((job_config or {}).get("date_end")),
    )


def _job_requires_trusted_local_worker_lane(job_config: Mapping[str, Any] | None, *, platform: Any = None) -> bool:
    required_lane = _job_required_worker_lane(job_config or {})
    if required_lane == TRUSTED_LOCAL_WORKER_LANE:
        return True
    config = job_config or {}
    return _shared_account_catalog_requires_trusted_local_worker_lane(
        platform=platform or config.get("platform"),
        pipeline_ingest_mode=str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE),
        date_start=_coerce_dt(config.get("date_start")),
        date_end=_coerce_dt(config.get("date_end")),
    )


def _shared_account_expected_total_posts_from_config(
    config: Mapping[str, Any] | None,
    *,
    platform: Any,
    account_handle: Any,
) -> int:
    metadata = _metadata_dict(config)
    direct_total = _normalize_non_negative_int(metadata.get("expected_total_posts"))
    if direct_total > 0:
        return direct_total
    by_account = _metadata_dict(metadata.get("expected_total_posts_by_account"))
    keyed_total = _normalize_non_negative_int(
        by_account.get(_shared_account_expected_total_posts_key(platform, account_handle))
    )
    return keyed_total


def _modal_social_dispatcher_worker_id() -> str:
    return "modal:social-dispatcher"


def _modal_dispatch_retry_delay_seconds() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_MODAL_DISPATCH_RETRY_DELAY_SECONDS",
        SOCIAL_MODAL_DISPATCH_RETRY_DELAY_SECONDS_DEFAULT,
        minimum=15,
    )


def _modal_dispatch_stage_global_cap(stage: str | None) -> int:
    normalized_stage = _modal_dispatch_capacity_stage(stage)
    env_map = {
        "posts": ("SOCIAL_WORKER_POOL_POSTS", 8),
        "comments": ("SOCIAL_WORKER_POOL_COMMENTS", 4),
        SHARED_ACCOUNT_DISCOVERY_STAGE: ("SOCIAL_WORKER_POOL_SHARED_ACCOUNT_DISCOVERY", 3),
        SHARED_ACCOUNT_POSTS_STAGE: ("SOCIAL_WORKER_POOL_SHARED_ACCOUNT_POSTS", 5),
        POST_CLASSIFY_STAGE: ("SOCIAL_WORKER_POOL_POST_CLASSIFY", 10),
        SEASON_MATERIALIZE_STAGE: ("SOCIAL_WORKER_POOL_SEASON_MATERIALIZE", 10),
        ANALYTICS_REFRESH_STAGE: ("SOCIAL_WORKER_POOL_ANALYTICS_REFRESH", 4),
        INSTAGRAM_MEDIA_MIRROR_STAGE: ("SOCIAL_WORKER_POOL_MEDIA_MIRROR", 6),
        COMMENT_MEDIA_MIRROR_STAGE: ("SOCIAL_WORKER_POOL_COMMENT_MEDIA_MIRROR", 6),
    }
    env_name, default = env_map.get(normalized_stage, ("SOCIAL_WORKER_POOL_POSTS", 8))
    return _resolve_positive_int_env(env_name, default, minimum=1)


def _modal_dispatch_platform_cap(stage: str | None, platform: str | None) -> int | None:
    normalized_stage = _modal_dispatch_capacity_stage(stage)
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform not in SUPPORTED_PLATFORMS:
        return None
    if normalized_stage in {"posts", "comments"}:
        defaults = {
            "instagram": 10,
            "tiktok": 1,
            "twitter": 1,
            "youtube": 1,
            "facebook": 1,
            "threads": 1,
        }
        env_name = f"SOCIAL_POSTS_COMMENTS_PLATFORM_CAP_{normalized_platform.upper()}"
        return _resolve_positive_int_env(env_name, defaults.get(normalized_platform, 1), minimum=1)
    if normalized_stage == SHARED_ACCOUNT_POSTS_STAGE:
        defaults = {
            "instagram": 1,
            "tiktok": 1,
            "twitter": 1,
            "threads": 1,
            "youtube": 1,
            "facebook": 1,
        }
        env_name = f"SOCIAL_SHARED_ACCOUNT_POSTS_PLATFORM_CAP_{normalized_platform.upper()}"
        return _resolve_positive_int_env(env_name, defaults.get(normalized_platform, 1), minimum=1)
    if normalized_stage == SHARED_ACCOUNT_DISCOVERY_STAGE:
        defaults = {
            "instagram": 1,
            "tiktok": 1,
            "twitter": 1,
            "threads": 1,
            "youtube": 1,
            "facebook": 1,
        }
        env_name = f"SOCIAL_SHARED_ACCOUNT_DISCOVERY_PLATFORM_CAP_{normalized_platform.upper()}"
        return _resolve_positive_int_env(env_name, defaults.get(normalized_platform, 1), minimum=1)
    if normalized_stage in {INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE}:
        return _resolve_positive_int_env("SOCIAL_MIRROR_PLATFORM_CAP", 2, minimum=1)
    return None


def _modal_dispatch_capacity_stage(stage: Any) -> str:
    normalized = _normalize_social_job_stage_for_stale(stage) or "unknown"
    if normalized == INSTAGRAM_COMMENTS_SCRAPLING_STAGE:
        return "comments"
    if normalized in {TIKTOK_POSTS_SCRAPLING_STAGE, THREADS_POSTS_SCRAPLING_STAGE}:
        return SHARED_ACCOUNT_POSTS_STAGE
    return normalized


def _resolve_dispatch_account_handle(config: dict[str, Any]) -> str | None:
    """Extract the canonical account handle from a job config dict.

    Resolution order matches existing shared-account precedence used across
    the dispatch, progress, and catalog subsystems.
    """
    for key in ("account", "account_handle", "source_account", "username"):
        value = str(config.get(key) or "").strip()
        if value:
            return value.lower().lstrip("@")
    # Fallback: shared_account_source_id (opaque id, but still unique per account)
    fallback = str(config.get("shared_account_source_id") or "").strip()
    return fallback.lower().lstrip("@") if fallback else None


def _job_is_posts_auth_cooldown_scoped(
    *,
    platform: Any,
    stage: Any = None,
    job_type: Any = None,
    config: Mapping[str, Any] | None = None,
    metadata: Mapping[str, Any] | None = None,
) -> bool:
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform not in {"instagram", "facebook", "threads"}:
        return False
    normalized_config = _metadata_dict(config)
    normalized_metadata = _metadata_dict(metadata)
    normalized_stage = (
        str(stage or normalized_config.get("stage") or normalized_metadata.get("stage") or job_type or "")
        .strip()
        .lower()
    )
    if normalized_platform == "instagram":
        return normalized_stage in {
            "posts",
            SHARED_ACCOUNT_DISCOVERY_STAGE,
            SHARED_ACCOUNT_POSTS_STAGE,
            INSTAGRAM_POSTS_SCRAPLING_STAGE,
        }
    if normalized_platform == "facebook":
        return normalized_stage in {"posts", SHARED_ACCOUNT_POSTS_STAGE}
    return normalized_stage in {
        "posts",
        SHARED_ACCOUNT_POSTS_STAGE,
        TIKTOK_POSTS_SCRAPLING_STAGE,
        THREADS_POSTS_SCRAPLING_STAGE,
    }


def _job_is_instagram_posts_auth_cooldown_scoped(
    *,
    platform: Any,
    stage: Any = None,
    job_type: Any = None,
    config: Mapping[str, Any] | None = None,
    metadata: Mapping[str, Any] | None = None,
) -> bool:
    return _job_is_posts_auth_cooldown_scoped(
        platform=platform,
        stage=stage,
        job_type=job_type,
        config=config,
        metadata=metadata,
    )


def _job_posts_auth_cooldown_sql_exclusion(table_alias: str = "j") -> str:
    account_expr = (
        f"lower(ltrim(coalesce(nullif({table_alias}.config->>'account', ''), "
        f"nullif({table_alias}.config->>'account_handle', ''), "
        f"nullif({table_alias}.config->>'source_account', ''), "
        f"nullif({table_alias}.config->>'username', ''), ''), '@'))"
    )
    stage_expr = (
        f"lower(coalesce({table_alias}.config->>'stage', {table_alias}.metadata->>'stage', {table_alias}.job_type, ''))"
    )
    return f"""
            (
              lower(coalesce({table_alias}.platform, '')) not in ('instagram', 'facebook', 'threads')
              or case
                when lower(coalesce({table_alias}.platform, '')) = 'instagram'
                  then {stage_expr} not in (
                    'posts',
                    '{SHARED_ACCOUNT_DISCOVERY_STAGE}',
                    '{SHARED_ACCOUNT_POSTS_STAGE}',
                    '{INSTAGRAM_POSTS_SCRAPLING_STAGE}'
                  )
                when lower(coalesce({table_alias}.platform, '')) = 'facebook'
                  then {stage_expr} not in ('posts', '{SHARED_ACCOUNT_POSTS_STAGE}')
                when lower(coalesce({table_alias}.platform, '')) = 'threads'
                  then {stage_expr} not in ('posts', '{SHARED_ACCOUNT_POSTS_STAGE}', '{THREADS_POSTS_SCRAPLING_STAGE}')
                else true
              end
              or nullif({account_expr}, '') is null
              or not exists (
                select 1
                from social.account_auth_cooldown ac
                where ac.platform = lower(coalesce({table_alias}.platform, ''))
                  and ac.account_handle = {account_expr}
                  and ac.cooldown_until is not null
                  and ac.cooldown_until > now()
              )
            )
    """


def _job_blocked_by_posts_auth_cooldown(job: Mapping[str, Any]) -> dict[str, Any] | None:
    config = _metadata_dict(job.get("config"))
    if not _job_is_posts_auth_cooldown_scoped(
        platform=job.get("platform"),
        job_type=job.get("job_type"),
        config=config,
        metadata=_metadata_dict(job.get("metadata")),
    ):
        return None
    account = _resolve_dispatch_account_handle(dict(config))
    if not account:
        return None
    return _active_posts_auth_cooldown(job.get("platform"), account)


def _defer_retry_until_posts_auth_cooldown(
    *,
    platform: Any,
    stage: Any,
    job_type: Any = None,
    account_handle: Any,
    next_available_at: datetime | None,
    metadata: MutableMapping[str, Any] | None = None,
) -> datetime | None:
    if not _job_is_posts_auth_cooldown_scoped(platform=platform, stage=stage, job_type=job_type):
        return next_available_at
    cooldown = _active_posts_auth_cooldown(platform, account_handle)
    if cooldown is None:
        return next_available_at
    cooldown_until = _coerce_dt(cooldown.get("cooldown_until"))
    if cooldown_until is None:
        return next_available_at
    if metadata is not None:
        metadata["auth_cooldown"] = cooldown
        metadata["retry_deferred_by_auth_cooldown"] = True
    if next_available_at is None or cooldown_until > next_available_at:
        return cooldown_until
    return next_available_at


def _shared_instagram_cursor_auth_repair_threshold() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_INSTAGRAM_CURSOR_AUTH_REPAIR_THRESHOLD",
        3,
        minimum=1,
    )


def _shared_instagram_cursor_auth_repair_required(
    *,
    platform: Any,
    stage: Any,
    error_code: Any,
    config: Mapping[str, Any] | None,
    retry_config_updates: Mapping[str, Any] | None,
) -> bool:
    if _normalize_platform_name(platform) != "instagram":
        return False
    normalized_stage = str(stage or "").strip().lower()
    if normalized_stage != SHARED_ACCOUNT_POSTS_STAGE:
        return False
    normalized_error = str(error_code or "").strip().lower()
    if normalized_error not in {
        "instagram_graphql_cursor_unauthorized",
        "instagram_graphql_cursor_forbidden",
    }:
        return False
    metadata = _metadata_dict(config)
    updates = _metadata_dict(retry_config_updates)
    retry_count = max(
        _normalize_non_negative_int(metadata.get("retry_transport_escalation_count")),
        _normalize_non_negative_int(updates.get("retry_transport_escalation_count")),
    )
    return retry_count >= _shared_instagram_cursor_auth_repair_threshold()


def _record_shared_account_frontier_retry_details(
    *,
    run_id: str,
    platform: str,
    account_handle: str,
    stage: str,
    job_id: str,
    attempt_count: int,
    max_attempts: int,
    error_code: str | None,
    error_class: str | None,
    error_message: str | None,
    can_retry: bool,
    next_available_at: datetime | None,
    metadata: Mapping[str, Any] | None,
) -> None:
    if _normalize_platform_name(platform) != "instagram":
        return
    if str(stage or "").strip().lower() != SHARED_ACCOUNT_POSTS_STAGE:
        return
    normalized_metadata = _metadata_dict(metadata)
    frontier = _metadata_dict(normalized_metadata.get("frontier"))
    retrieval_meta = _metadata_dict(normalized_metadata.get("retrieval_meta"))
    if not frontier and not retrieval_meta.get("graphql_cursor"):
        return
    auth_cooldown = _metadata_dict(normalized_metadata.get("auth_cooldown"))
    auth_repair_required = bool(normalized_metadata.get("instagram_auth_repair_required"))
    status = "retrying" if can_retry else "failed"
    metadata_updates = {
        "last_error_code": str(error_code or "").strip().lower() or None,
        "last_error_class": str(error_class or "").strip() or None,
        "last_error_message": str(error_message or "").strip() or None,
        "frontier_stop_reason": str(error_code or "").strip().lower() or "request_failed",
        "graphql_cursor": retrieval_meta.get("graphql_cursor")
        or frontier.get("graphql_cursor")
        or _metadata_dict(frontier.get("metadata")).get("graphql_cursor"),
        "retry_available_at": _iso(next_available_at),
        "job_available_at": _iso(next_available_at),
        "job_id": str(job_id or "").strip() or None,
        "job_attempt_count": max(0, int(attempt_count)),
        "job_max_attempts": max(0, int(max_attempts)),
        "retry_deferred_by_auth_cooldown": bool(normalized_metadata.get("retry_deferred_by_auth_cooldown")),
        "auth_cooldown": auth_cooldown or None,
        "auth_cooldown_until": auth_cooldown.get("cooldown_until") if auth_cooldown else None,
        "instagram_auth_repair_required": auth_repair_required,
        "auth_repair_required_at": _iso(_now_utc()) if auth_repair_required else None,
    }
    if next_available_at is not None:
        metadata_updates["cooldown_until"] = _iso(next_available_at)
    try:
        _update_shared_account_run_frontier(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            status=status,
            metadata_updates=metadata_updates,
        )
    except Exception:
        logger.debug(
            "[shared-account] failed recording frontier retry details: run=%s account=%s job=%s",
            run_id,
            account_handle,
            job_id,
            exc_info=True,
        )


def _record_stalled_frontier_recovery_details(
    *,
    run_id: str,
    platform: str,
    account_handle: str,
    job_id: str,
    prior_worker_id: str | None,
    recovery_status: str,
    frontier: Mapping[str, Any] | None,
    prior_lease_owner: str | None = None,
) -> None:
    normalized_frontier = _metadata_dict(frontier)
    details = {
        "run_id": str(run_id or "").strip() or None,
        "platform": _normalize_platform_name(platform),
        "account_handle": _normalize_account_handle(account_handle),
        "job_id": str(job_id or "").strip() or None,
        "prior_worker_id": str(prior_worker_id or "").strip() or None,
        "prior_lease_owner": str(prior_lease_owner or prior_worker_id or "").strip() or None,
        "recovery_status": str(recovery_status or "").strip().lower() or None,
        "recovered_at": _iso(_now_utc()),
        "frontier_status_before_recovery": str(normalized_frontier.get("status") or "").strip().lower() or None,
        "frontier_id": str(normalized_frontier.get("id") or "").strip() or None,
        "graphql_cursor": str(normalized_frontier.get("next_cursor") or "").strip()
        or _metadata_dict(normalized_frontier.get("metadata")).get("graphql_cursor"),
        "pages_scanned": _normalize_non_negative_int(normalized_frontier.get("pages_scanned")),
        "posts_checked": _normalize_non_negative_int(normalized_frontier.get("posts_checked")),
        "posts_saved": _normalize_non_negative_int(normalized_frontier.get("posts_saved")),
        "last_error_code": _metadata_dict(normalized_frontier.get("metadata")).get("last_error_code"),
    }
    try:
        _update_shared_account_run_frontier(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            metadata_updates={
                "stalled_frontier_recovery": details,
                "stalled_frontier_recovered_at": details["recovered_at"],
            },
        )
    except Exception:
        logger.debug(
            "[shared-account] failed recording frontier stalled recovery metadata: run=%s account=%s",
            run_id,
            account_handle,
            exc_info=True,
        )
    try:
        pg.fetch_one(
            """
            update social.scrape_runs
            set summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object(
              'stalled_frontier_recovery', %s::jsonb,
              'stalled_frontier_recoveries',
              coalesce(summary->'stalled_frontier_recoveries', '[]'::jsonb) || jsonb_build_array(%s::jsonb)
            )
            where id = %s::uuid
            returning id::text
            """,
            [_json_dumps(details), _json_dumps(details), run_id],
        )
    except Exception:
        logger.debug(
            "[shared-account] failed recording stalled frontier recovery on run summary: run=%s",
            run_id,
            exc_info=True,
        )


def _platform_cap_per_account_scaling_enabled() -> bool:
    raw = (os.getenv("SOCIAL_PLATFORM_CAP_PER_ACCOUNT_SCALING") or "false").strip().lower()
    return raw not in {"0", "false", "off", "no"}


def _modal_dispatch_effective_platform_cap(
    stage: str | None,
    platform: str | None,
    *,
    active_account_count: int = 1,
    job_config: Mapping[str, Any] | None = None,
) -> int | None:
    """Return the effective platform cap, scaled by the number of distinct active accounts.

    When per-account scaling is enabled (default), the base per-platform cap is
    multiplied by the number of distinct accounts with active jobs for this
    (stage, platform) pair. The result is capped by the stage global cap so that
    the total never exceeds the stage-wide ceiling.
    """
    base_cap = _modal_dispatch_platform_cap(stage, platform)
    if base_cap is None:
        return None
    normalized_stage = _modal_dispatch_capacity_stage(stage)
    if normalized_stage == "comments":
        config = _metadata_dict(job_config)
        configured_comments_cap = max(
            _normalize_non_negative_int(config.get("comments_shard_count")),
            _normalize_non_negative_int(config.get("recommended_comments_shard_count")),
        )
        if configured_comments_cap > 0:
            base_cap = max(base_cap, min(configured_comments_cap, _modal_dispatch_stage_global_cap(stage)))
    if normalized_stage == SHARED_ACCOUNT_POSTS_STAGE:
        config = _metadata_dict(job_config)
        configured_posts_cap = max(
            _normalize_non_negative_int(config.get("details_refresh_shard_count")),
            _normalize_non_negative_int(config.get("details_refresh_worker_count")),
            _normalize_non_negative_int(config.get("runner_count")),
        )
        if (
            configured_posts_cap > 0
            and str(config.get("runner_strategy") or "").strip().lower() == "parallel_detail_refresh"
        ):
            base_cap = max(base_cap, min(configured_posts_cap, _modal_dispatch_stage_global_cap(stage)))
    if not _platform_cap_per_account_scaling_enabled():
        return base_cap
    scaled = base_cap * max(1, active_account_count)
    ceiling = _modal_dispatch_stage_global_cap(stage)
    return min(scaled, ceiling)


def _modal_dispatch_limit() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_DISPATCH_LIMIT",
        SOCIAL_MODAL_DISPATCH_LIMIT_DEFAULT,
        minimum=1,
        maximum=SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX,
    )


def _modal_social_dispatch_resolution() -> dict[str, Any]:
    function_names = modal_social_job_function_names()
    primary_name = function_names[0] if function_names else modal_social_job_function_name()
    resolutions = [resolve_modal_function(name) for name in function_names] or [resolve_modal_function(primary_name)]
    first_failure = next((payload for payload in resolutions if not bool(payload.get("resolved"))), None)
    if first_failure is not None:
        payload = dict(first_failure)
        payload.setdefault("function_name", primary_name)
        payload["function_names"] = function_names
        return payload
    payload = dict(resolutions[0]) if resolutions else resolve_modal_function(primary_name)
    payload["function_names"] = function_names
    return payload


def _modal_social_dispatch_ready() -> tuple[bool, str | None]:
    resolution = _modal_social_dispatch_resolution()
    return bool(resolution.get("resolved")), str(resolution.get("reason") or "").strip() or None


def _resolve_modal_dispatch_no_progress_seconds() -> int:
    return _resolve_positive_int_env(
        "SOCIAL_MODAL_DISPATCH_NO_PROGRESS_SECONDS",
        SOCIAL_MODAL_DISPATCH_NO_PROGRESS_SECONDS_DEFAULT,
        minimum=300,
    )


def _resolve_modal_dispatch_blocked_failure_limit() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_DISPATCH_BLOCKED_FAILURE_LIMIT",
        SOCIAL_MODAL_DISPATCH_BLOCKED_FAILURE_LIMIT_DEFAULT,
        minimum=1,
        maximum=10,
    )


def _touch_modal_social_dispatcher_heartbeat(
    *,
    status: str = "idle",
    metadata_updates: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    existing_metadata: dict[str, Any] = {}
    if _worker_heartbeat_schema_ready():
        try:
            row = pg.fetch_one(
                """
                select metadata
                  from social.scrape_workers
                 where worker_id = %s
                """,
                [_modal_social_dispatcher_worker_id()],
            )
            existing_metadata = _metadata_dict((row or {}).get("metadata"))
        except Exception:  # noqa: BLE001
            existing_metadata = {}
    metadata = {
        **existing_metadata,
        "dispatcher_name": "social",
        "dispatch_enabled": modal_dispatch_enabled(),
        "execution_backend_canonical": "modal",
        "execution_mode_canonical": "remote",
        "runtime_version": dict(_resolve_runtime_version_stamp()),
        **dict(metadata_updates or {}),
    }
    return update_worker_heartbeat(
        _modal_social_dispatcher_worker_id(),
        stage="any",
        status=status,
        metadata=metadata,
        supported_platforms=list(SUPPORTED_PLATFORMS),
    )


def _resolve_stale_seconds_for_job(
    *,
    platform: Any = None,
    stage: Any = None,
    has_queue_fields: bool = True,  # noqa: ARG001
) -> int:
    return _resolve_social_job_stale_seconds(platform=platform, stage=stage)


def _oldest_queued_age_seconds() -> int | None:
    row = (
        pg.fetch_one(
            """
        select extract(epoch from now() - min(created_at))::int as oldest_seconds
        from social.scrape_jobs
        where status in ('queued', 'pending', 'retrying')
        """,
        )
        or {}
    )
    value = row.get("oldest_seconds")
    if value is None:
        return None
    return max(0, int(value))


def _stale_running_count() -> int:
    row = (
        pg.fetch_one(
            """
        select count(*)::int as total
        from social.scrape_jobs j
        where j.status = 'running'
          and coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)
            < now() - (
              case
                when lower(coalesce(j.platform, '')) = 'youtube'
                  and lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '')) = 'posts'
                  then make_interval(secs => %s)
                when lower(coalesce(j.platform, '')) = 'youtube'
                  and lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '')) = 'comments'
                  then make_interval(secs => %s)
                else make_interval(secs => %s)
              end
            )
        """,
            [
                _resolve_social_job_stale_seconds(platform="youtube", stage="posts"),
                _resolve_social_job_stale_seconds(platform="youtube", stage="comments"),
                _resolve_social_job_stale_seconds(),
            ],
        )
        or {}
    )
    return max(0, int(row.get("total") or 0))


def _build_modal_executor_health_payload(
    *,
    reason: str | None = None,
    platform: str | None = None,
    account_handle: str | None = None,
) -> dict[str, Any]:
    workers_payload = _query_worker_health()
    dispatcher_id = _modal_social_dispatcher_worker_id()
    dispatcher_readiness = _modal_social_dispatch_resolution()
    dispatcher_row = next(
        (
            worker
            for worker in (workers_payload.get("workers") or [])
            if str(worker.get("worker_id") or "") == dispatcher_id
        ),
        None,
    )
    dispatcher_metadata = _metadata_dict((dispatcher_row or {}).get("metadata"))
    remote_auth_capabilities = workers_payload.get("remote_auth_capabilities")
    target_platform = _normalize_platform_name(platform) or "instagram"
    target_account = _normalize_account_handle(account_handle) or str(account_handle or "").strip().lower().lstrip("@")
    remote_probe_cache: dict[str, dict[str, Any] | None] = {}

    def _resolved_remote_auth_capability(candidate_platform: str, *, allow_probe: bool = False) -> dict[str, Any]:
        if candidate_platform == "instagram" and _instagram_public_first_scrape_mode_enabled():
            return _instagram_public_auth_capability()
        capability = (
            _metadata_dict(remote_auth_capabilities.get(candidate_platform))
            if isinstance(remote_auth_capabilities, dict)
            else {}
        )
        if not _platform_requires_remote_auth(candidate_platform):
            return capability
        if bool(capability.get("ready")):
            return capability
        if capability and not allow_probe:
            return capability
        if isinstance(remote_auth_capabilities, dict) and not allow_probe:
            return capability
        if candidate_platform not in remote_probe_cache:
            remote_probe_cache[candidate_platform] = _probe_modal_remote_auth_health(candidate_platform)
        probe_payload = remote_probe_cache.get(candidate_platform)
        if not isinstance(probe_payload, Mapping):
            return capability
        resolved = dict(capability)
        if not bool(probe_payload.get("ready")):
            resolved.update(
                {
                    "required": True,
                    "executor_backend": "modal",
                    "ready": False,
                    "reason": str(probe_payload.get("reason") or "").strip()
                    or str(capability.get("reason") or "").strip()
                    or f"{candidate_platform}_remote_auth_unavailable",
                    "detail": _metadata_dict(probe_payload.get("detail")) or None,
                    "missing_hints": list(capability.get("missing_hints") or []),
                    "probe_source": "modal_remote_auth_probe",
                }
            )
            return resolved
        resolved.update(
            {
                "required": True,
                "executor_backend": "modal",
                "ready": True,
                "reason": None,
                "detail": _metadata_dict(probe_payload.get("detail")) or None,
                "missing_hints": [],
                "probe_source": "modal_remote_auth_probe",
            }
        )
        return resolved

    target_remote_auth = _resolved_remote_auth_capability(
        target_platform,
        allow_probe=_platform_requires_remote_auth(target_platform),
    )
    if target_platform == "instagram" and target_account and not bool(target_remote_auth.get("ready")):
        posts_probe = probe_modal_instagram_posts_auth_health(target_account)
        if bool(posts_probe.get("ready")):
            target_remote_auth = {
                **dict(target_remote_auth),
                "required": True,
                "executor_backend": "modal",
                "ready": True,
                "reason": None,
                "detail": {
                    "phase": "posts_auth_probe",
                    "account_handle": target_account,
                    "posts_seen": posts_probe.get("posts_seen"),
                    "has_next_page": posts_probe.get("has_next_page"),
                    "generic_remote_auth_reason": str(target_remote_auth.get("reason") or "").strip() or None,
                    "generic_remote_auth_detail": (
                        _metadata_dict(target_remote_auth.get("detail")) or None
                        if isinstance(target_remote_auth.get("detail"), Mapping)
                        else None
                    ),
                },
                "missing_hints": [],
                "probe_source": "modal_instagram_posts_auth_probe",
            }
    instagram_remote_auth = (
        target_remote_auth if target_platform == "instagram" else _resolved_remote_auth_capability("instagram")
    )
    if isinstance(remote_auth_capabilities, dict):
        remote_auth_capabilities[target_platform] = target_remote_auth
        remote_auth_capabilities["instagram"] = instagram_remote_auth
    modal_capacity = _collect_modal_capacity(
        [worker for worker in (workers_payload.get("workers") or []) if isinstance(worker, Mapping)]
    )
    oldest_queued_age_seconds = _oldest_queued_age_seconds()
    stale_running_count = _stale_running_count()
    active_invocations_raw = dispatcher_metadata.get("active_invocations")
    active_invocations = (
        active_invocations_raw if active_invocations_raw is not None else workers_payload.get("active_workers")
    )
    dispatch_enabled = bool(dispatcher_metadata.get("dispatch_enabled")) if dispatcher_row else modal_dispatch_enabled()
    dispatcher_heartbeat_fresh = bool(dispatcher_row.get("is_fresh")) if dispatcher_row else False
    dispatcher_resolved = bool(dispatcher_readiness.get("resolved"))
    target_platform_requires_auth = _platform_requires_remote_auth(target_platform)
    target_remote_auth_ready = bool(target_remote_auth.get("ready")) if target_platform_requires_auth else True
    instagram_remote_auth_ready = bool(instagram_remote_auth.get("ready"))
    shared_account_backfill_ready_reason = None
    if not dispatcher_resolved:
        shared_account_backfill_ready_reason = (
            str(dispatcher_readiness.get("reason") or "").strip() or "modal_dispatch_unavailable"
        )
    elif not dispatcher_heartbeat_fresh:
        shared_account_backfill_ready_reason = "modal_dispatcher_heartbeat_missing"
    elif target_platform_requires_auth and not target_remote_auth_ready:
        shared_account_backfill_ready_reason = (
            str(target_remote_auth.get("reason") or "").strip() or f"{target_platform}_remote_auth_unavailable"
        )
    platform_backfill_readiness = {}
    for candidate_platform in CATALOG_SUPPORTED_PLATFORMS:
        candidate_requires_auth = _platform_requires_remote_auth(candidate_platform)
        candidate_remote_auth = (
            target_remote_auth
            if candidate_platform == target_platform
            else _resolved_remote_auth_capability(candidate_platform)
        )
        if isinstance(remote_auth_capabilities, dict):
            remote_auth_capabilities[candidate_platform] = candidate_remote_auth
        candidate_auth_ready = bool(candidate_remote_auth.get("ready")) if candidate_requires_auth else True
        candidate_reason = None
        if not dispatcher_resolved:
            candidate_reason = str(dispatcher_readiness.get("reason") or "").strip() or "modal_dispatch_unavailable"
        elif not dispatcher_heartbeat_fresh:
            candidate_reason = "modal_dispatcher_heartbeat_missing"
        elif candidate_requires_auth and not candidate_auth_ready:
            candidate_reason = (
                str(candidate_remote_auth.get("reason") or "").strip()
                or f"{candidate_platform}_remote_auth_unavailable"
            )
        platform_backfill_readiness[candidate_platform] = {
            "requires_remote_auth": candidate_requires_auth,
            "ready": dispatcher_resolved and dispatcher_heartbeat_fresh and candidate_auth_ready,
            "reason": candidate_reason,
        }
    workers_payload.update(
        {
            "healthy": True,
            "healthy_workers": max(1, int(workers_payload.get("healthy_workers") or 0)),
            "reason": reason,
            "executor_backend": "modal",
            "dispatch_enabled": dispatch_enabled,
            "dispatcher_heartbeat_fresh": dispatcher_heartbeat_fresh,
            "modal_capacity": modal_capacity,
            "active_invocations": max(0, int(active_invocations or 0)),
            "oldest_queued_age_seconds": oldest_queued_age_seconds,
            "stale_running_count": stale_running_count,
            "last_dispatch_success_at": str(dispatcher_metadata.get("last_dispatch_success_at") or "").strip() or None,
            "last_dispatch_error": str(dispatcher_metadata.get("last_dispatch_error") or "").strip() or None,
            "last_dispatch_blocked_reason": (
                str(dispatcher_metadata.get("last_dispatch_blocked_reason") or "").strip()
                or str(dispatcher_readiness.get("reason") or "").strip()
                or None
            ),
            "dispatcher_readiness": dispatcher_readiness,
            "shared_account_backfill_readiness": {
                "ready": dispatcher_resolved and dispatcher_heartbeat_fresh and target_remote_auth_ready,
                "reason": shared_account_backfill_ready_reason,
                "dispatcher_ready": dispatcher_resolved,
                "dispatcher_heartbeat_fresh": dispatcher_heartbeat_fresh,
                "platform": target_platform,
                "instagram_scrape_mode": (
                    "public_first"
                    if target_platform == "instagram" and _instagram_public_first_scrape_mode_enabled()
                    else None
                ),
                "auth_state": (
                    "public"
                    if target_platform == "instagram" and _instagram_public_first_scrape_mode_enabled()
                    else None
                ),
                "proxy_state": (
                    "none" if target_platform == "instagram" and _instagram_public_first_scrape_mode_enabled() else None
                ),
                "platform_requires_remote_auth": target_platform_requires_auth,
                "platform_remote_auth_ready": target_remote_auth_ready,
                "platform_remote_auth_reason": (
                    str(target_remote_auth.get("reason") or "").strip() or None
                    if target_platform_requires_auth
                    else None
                ),
                "platform_remote_auth_detail": (
                    dict(target_remote_auth.get("detail") or {})
                    if target_platform_requires_auth and isinstance(target_remote_auth.get("detail"), dict)
                    else None
                ),
                "platform_backfill_readiness": platform_backfill_readiness,
                "instagram_remote_auth_ready": instagram_remote_auth_ready,
            },
        }
    )
    workers_payload["alerts"] = _build_worker_health_alerts(workers_payload)
    return workers_payload


