_SOCIAL_HOT_PATH_CACHE_TTL_SECONDS = max(
    1,
    int((os.getenv("TRR_SOCIAL_HOT_PATH_CACHE_TTL_SECONDS") or "").strip() or "5"),
)


def _alert_threshold_seconds(env_name: str, default: int, *, minimum: int = 60, maximum: int = 86_400) -> int:
    return max(minimum, min(_resolve_positive_int_env(env_name, default, minimum=minimum), maximum))


def _new_alert(*, code: str, severity: str, message: str, **details: Any) -> dict[str, Any]:
    payload = {
        "code": str(code or "").strip().lower(),
        "severity": str(severity or "warning").strip().lower(),
        "message": str(message or "").strip(),
    }
    for key, value in details.items():
        if value is None or value == "":
            continue
        payload[key] = value
    return payload


def _append_alert(target: list[dict[str, Any]], *, code: str, severity: str, message: str, **details: Any) -> None:
    normalized_code = str(code or "").strip().lower()
    if not normalized_code or any(str(item.get("code") or "").strip().lower() == normalized_code for item in target):
        return
    target.append(_new_alert(code=normalized_code, severity=severity, message=message, **details))


def _build_worker_health_alerts(payload: Mapping[str, Any]) -> list[dict[str, Any]]:
    alerts: list[dict[str, Any]] = []
    shared_readiness = _metadata_dict(payload.get("shared_account_backfill_readiness"))
    if shared_readiness:
        dispatcher_ready = bool(shared_readiness.get("dispatcher_ready"))
        dispatcher_heartbeat_fresh = bool(shared_readiness.get("dispatcher_heartbeat_fresh"))
        instagram_remote_auth_ready = bool(shared_readiness.get("instagram_remote_auth_ready"))
        readiness_reason = str(shared_readiness.get("reason") or "").strip() or None
        if not dispatcher_ready:
            _append_alert(
                alerts,
                code="dispatcher_not_ready",
                severity="error",
                message=(
                    "Modal shared-account dispatch is not resolved yet. "
                    "Block new shared-profile backfills until dispatcher readiness is green."
                ),
                reason=readiness_reason,
            )
        elif not dispatcher_heartbeat_fresh:
            _append_alert(
                alerts,
                code="dispatcher_heartbeat_stale",
                severity="error",
                message=(
                    "Modal dispatcher heartbeat is stale or missing. "
                    "Shared-profile backfills should not start until a fresh dispatcher heartbeat is visible."
                ),
                reason=readiness_reason,
            )
        elif not instagram_remote_auth_ready:
            _append_alert(
                alerts,
                code="auth_preflight_not_ready",
                severity="error",
                message=(
                    "Remote Instagram auth is not ready in the Modal worker plane. "
                    "Shared-profile backfills should stay blocked until auth preflight turns green."
                ),
                reason=readiness_reason,
            )

    stale_running_count = _normalize_non_negative_int(payload.get("stale_running_count"))
    if stale_running_count > 0:
        _append_alert(
            alerts,
            code="stale_running_jobs",
            severity="error",
            message=(
                f"{stale_running_count} social job{'s are' if stale_running_count != 1 else ' is'} stale "
                "and need operator attention or recovery."
            ),
            count=stale_running_count,
        )

    oldest_queued_age_seconds = _normalize_non_negative_int(payload.get("oldest_queued_age_seconds"))
    queue_wait_threshold = _alert_threshold_seconds(
        "SOCIAL_QUEUE_ALERT_OLDEST_QUEUED_SECONDS",
        900,
        minimum=60,
        maximum=86_400,
    )
    if oldest_queued_age_seconds >= queue_wait_threshold:
        _append_alert(
            alerts,
            code="queue_wait_exceeded",
            severity="warning",
            message="The social queue has been waiting longer than the healthy backlog threshold.",
            oldest_queued_age_seconds=oldest_queued_age_seconds,
            threshold_seconds=queue_wait_threshold,
        )

    return alerts


_TIKTOK_SINGLE_PATH_TOPOLOGY_DEFAULT: dict[str, Any] = {
    "platform": "tiktok",
    "primary_live_path": "ytdlp",
    "browser_intercept_proven_live": False,
}


def _tiktok_recent_failure_looks_ytdlp_related(row: Mapping[str, Any]) -> bool:
    if str(row.get("platform") or "").strip().lower() != "tiktok":
        return False
    joined_fields = " ".join(
        str(row.get(field) or "").strip().lower()
        for field in ("job_type", "status", "last_error_code", "last_error_class", "error_message")
    )
    return "ytdlp" in joined_fields.replace("-", "")


def _build_tiktok_single_path_alerts(queue_payload: Mapping[str, Any]) -> list[dict[str, Any]]:
    alerts: list[dict[str, Any]] = []
    topology = dict(_TIKTOK_SINGLE_PATH_TOPOLOGY_DEFAULT)
    primary_live_path = str(topology.get("primary_live_path") or "").strip().lower() or "ytdlp"
    browser_intercept_proven_live = bool(topology.get("browser_intercept_proven_live"))

    if primary_live_path == "ytdlp" and not browser_intercept_proven_live:
        _append_alert(
            alerts,
            code="tiktok_single_path_risk",
            severity="warning",
            message=(
                "TikTok posts currently rely on yt-dlp as the only proven live path. "
                "Browser intercept is not yet proven live, so this is a single-path topology."
            ),
            primary_live_path="yt-dlp",
            browser_intercept_proven_live=browser_intercept_proven_live,
            topology=topology,
        )

    recent_failures = [
        row
        for row in list(queue_payload.get("recent_failures") or [])
        if isinstance(row, dict) and _tiktok_recent_failure_looks_ytdlp_related(row)
    ]
    if recent_failures:
        _append_alert(
            alerts,
            code="tiktok_single_path_degraded",
            severity="critical",
            message=(
                "Recent TikTok queue failures include yt-dlp-related rows, so the primary TikTok path "
                "should be treated as degraded until recovery clears."
            ),
            recent_failure_count=len(recent_failures),
            recent_failure_codes=[
                str(row.get("last_error_code") or "").strip() or str(row.get("error_message") or "").strip()
                for row in recent_failures
                if str(row.get("last_error_code") or "").strip() or str(row.get("error_message") or "").strip()
            ][:5],
            primary_live_path="yt-dlp",
            browser_intercept_proven_live=browser_intercept_proven_live,
            topology=topology,
        )

    return alerts


def _build_queue_status_alerts(
    *,
    workers_payload: Mapping[str, Any],
    queue_payload: Mapping[str, Any],
) -> list[dict[str, Any]]:
    alerts = [dict(item) for item in list(workers_payload.get("alerts") or []) if isinstance(item, dict)]
    alerts.extend(_build_tiktok_single_path_alerts(queue_payload))
    silent_drop_warnings = [
        row for row in list(queue_payload.get("silent_drop_warnings") or []) if isinstance(row, dict)
    ]
    silent_drop_total = _normalize_non_negative_int(queue_payload.get("silent_drop_warnings_total")) or len(
        silent_drop_warnings
    )
    if silent_drop_total > 0:
        _append_alert(
            alerts,
            code="silent_data_loss_watch",
            severity="critical",
            message=(
                f"{silent_drop_total} recent social post job"
                f"{'s completed' if silent_drop_total != 1 else ' completed'} with zero saved posts after checking "
                "live posts. Treat this as possible silent data loss until the account repair flow is run."
            ),
            count=silent_drop_total,
            recent_jobs=silent_drop_warnings[:5],
        )
    dispatch_blocked_total = _normalize_non_negative_int(queue_payload.get("dispatch_blocked_jobs_total"))
    if dispatch_blocked_total > 0:
        _append_alert(
            alerts,
            code="dispatch_blocked_jobs",
            severity="error",
            message=(
                f"{dispatch_blocked_total} queued social job{'s are' if dispatch_blocked_total != 1 else ' is'} "
                "blocked before any Modal worker could claim them."
            ),
            count=dispatch_blocked_total,
        )
    retrying_dispatch_total = _normalize_non_negative_int(queue_payload.get("retrying_dispatch_jobs_total"))
    if retrying_dispatch_total > 0:
        _append_alert(
            alerts,
            code="retry_loop_detected",
            severity="warning",
            message=(
                f"{retrying_dispatch_total} social job{'s are' if retrying_dispatch_total != 1 else ' is'} "
                "retrying remote dispatch after a stale or unclaimed lease."
            ),
            count=retrying_dispatch_total,
        )
    return alerts


def _get_social_hot_path_cache(cache_key: tuple[Any, ...]) -> Any | None:
    now = time_module.monotonic()
    with _SOCIAL_HOT_PATH_CACHE_LOCK:
        cached = _SOCIAL_HOT_PATH_CACHE.get(cache_key)
        if not cached:
            return None
        expires_at, payload = cached
        if expires_at <= now:
            _SOCIAL_HOT_PATH_CACHE.pop(cache_key, None)
            return None
        return copy.deepcopy(payload)


def _set_social_hot_path_cache(cache_key: tuple[Any, ...], payload: Any) -> None:
    with _SOCIAL_HOT_PATH_CACHE_LOCK:
        _SOCIAL_HOT_PATH_CACHE[cache_key] = (
            time_module.monotonic() + _SOCIAL_HOT_PATH_CACHE_TTL_SECONDS,
            copy.deepcopy(payload),
        )


def _clear_social_hot_path_caches() -> None:
    with _SOCIAL_HOT_PATH_CACHE_LOCK:
        _SOCIAL_HOT_PATH_CACHE.clear()


def _worker_heartbeat_schema_ready() -> bool:
    global _schema_ready_cache
    now = time_module.monotonic()
    if _schema_ready_cache and (now - _schema_ready_cache[0]) < 60:
        return _schema_ready_cache[1]
    result = _relation_exists("social.scrape_workers")
    _schema_ready_cache = (now, result)
    return result


def get_worker_auth_capabilities(platforms: Sequence[Any] | None = None) -> dict[str, Any]:
    """Describe platform auth capabilities for the current worker environment."""
    requested_platforms = {
        normalized
        for normalized in (_normalize_platform_name(item) for item in (platforms or []))
        if normalized in SUPPORTED_PLATFORMS
    }
    check_all = not requested_platforms

    instagram_cookies = (
        _load_instagram_cookies_from_sources() if check_all or "instagram" in requested_platforms else {}
    )
    tiktok_cookies = _load_tiktok_cookies() if check_all or "tiktok" in requested_platforms else {}
    if check_all or "twitter" in requested_platforms:
        twitter_cookies, twitter_bearer = _load_twitter_auth()
        twikit_creds = _load_twikit_credentials(twitter_cookies)
    else:
        twitter_cookies, twitter_bearer, twikit_creds = {}, None, None
    facebook_cookies = _load_facebook_cookies() if check_all or "facebook" in requested_platforms else {}
    threads_cookies = _load_threads_cookies() if check_all or "threads" in requested_platforms else {}
    instagram_validation = (
        _inspect_instagram_cookie_health(instagram_cookies)
        if check_all or "instagram" in requested_platforms
        else {"valid": False, "reason": "not_checked", "detail": {"scope": "unsupported_for_worker"}}
    )
    instagram_authenticated = bool(instagram_validation.get("valid"))
    instagram_auth_reason = str(instagram_validation.get("reason") or "").strip() or None
    instagram_auth_detail = (
        dict(instagram_validation.get("detail") or {}) if isinstance(instagram_validation.get("detail"), dict) else None
    )
    return {
        "instagram_authenticated": instagram_authenticated,
        "instagram_auth_reason": None if instagram_authenticated else instagram_auth_reason,
        "instagram_auth_detail": None if instagram_authenticated else instagram_auth_detail,
        "tiktok_authenticated": bool(tiktok_cookies.get("sessionid") or tiktok_cookies.get("sid_tt")),
        "twitter_authenticated": bool(
            (twitter_cookies.get("auth_token") and twitter_cookies.get("ct0")) or twitter_bearer or twikit_creds
        ),
        "facebook_authenticated": bool(facebook_cookies.get("c_user") and facebook_cookies.get("xs")),
        "threads_authenticated": bool(threads_cookies.get("sessionid") and threads_cookies.get("csrftoken")),
    }


def _instagram_public_first_scrape_mode_enabled(config: Mapping[str, Any] | None = None) -> bool:
    metadata = _metadata_dict(config)
    raw_mode = (
        metadata.get("instagram_scrape_mode")
        or metadata.get("scrape_mode")
        or os.getenv("SOCIAL_INSTAGRAM_SCRAPE_MODE")
        or SOCIAL_INSTAGRAM_SCRAPE_MODE_DEFAULT
    )
    return str(raw_mode or "").strip().lower() in SOCIAL_INSTAGRAM_PUBLIC_FIRST_MODE_ALIASES


def _instagram_public_auth_capability() -> dict[str, Any]:
    return {
        "required": False,
        "executor_backend": "modal",
        "ready": True,
        "reason": None,
        "detail": {
            "instagram_scrape_mode": "public_first",
            "auth_state": "public",
            "proxy_state": "none",
            "auth_probe_skipped": True,
            "fallback_policy": {
                "auth_fallback": "requires_approval",
                "proxy_fallback": "requires_approval",
            },
        },
        "missing_hints": [],
        "probe_source": "public_first_mode",
    }


def _platform_requires_remote_auth(platform: Any) -> bool:
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform == "instagram" and _instagram_public_first_scrape_mode_enabled():
        return False
    return normalized_platform in set(REMOTE_AUTH_REQUIRED_PLATFORMS)


def _remote_auth_safe_structure_flags(
    platform: str,
    *,
    cookies: Mapping[str, Any] | None = None,
    bearer_token: str | None = None,
    twikit_credentials: Mapping[str, Any] | None = None,
) -> dict[str, bool]:
    normalized_platform = _normalize_platform_name(platform)
    cookie_map = cookies or {}
    if normalized_platform == "twitter":
        return {
            "has_auth_token": bool(str(cookie_map.get("auth_token") or "").strip()),
            "has_ct0": bool(str(cookie_map.get("ct0") or "").strip()),
            "has_bearer_token": bool(str(bearer_token or "").strip()),
            "has_twikit_credentials": bool(twikit_credentials),
        }
    if normalized_platform == "facebook":
        return {
            "has_c_user": bool(str(cookie_map.get("c_user") or "").strip()),
            "has_xs": bool(str(cookie_map.get("xs") or "").strip()),
        }
    if normalized_platform == "threads":
        return {
            "has_sessionid": bool(str(cookie_map.get("sessionid") or "").strip()),
            "has_csrftoken": bool(str(cookie_map.get("csrftoken") or "").strip()),
        }
    return {}


def probe_remote_auth_health(platform: str) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform == "instagram":
        if _instagram_public_first_scrape_mode_enabled():
            return {
                "platform": normalized_platform,
                "ready": True,
                "reason": None,
                "instagram_scrape_mode": "public_first",
                "auth_state": "public",
                "proxy_state": "none",
                "auth_probe_skipped": True,
                "fallback_policy": {
                    "auth_fallback": "requires_approval",
                    "proxy_fallback": "requires_approval",
                },
            }
        cookies = _load_instagram_cookies_from_sources()
        validation = _inspect_instagram_cookie_health(cookies)
        detail = dict(validation.get("detail") or {}) if isinstance(validation.get("detail"), dict) else None
        structure = _instagram_cookie_structure_detail(cookies)
        cookie_fingerprint = _instagram_cookie_fingerprint(cookies)[:16] if cookies else None
        return {
            "platform": normalized_platform,
            "ready": bool(validation.get("valid")),
            "reason": str(validation.get("reason") or "").strip() or None,
            "detail": detail,
            "has_sessionid": bool(structure.get("has_sessionid")),
            "has_csrftoken": bool(structure.get("has_csrftoken")),
            "has_ds_user_id": bool(structure.get("has_ds_user_id")),
            "cookie_fingerprint": cookie_fingerprint,
            "cookie_fingerprint_algorithm": "sha256:16" if cookie_fingerprint else None,
        }
    if normalized_platform == "tiktok":
        cookies = _load_tiktok_cookies_from_sources()
        is_valid, reason = _validate_tiktok_cookie_health(cookies)
        return {
            "platform": normalized_platform,
            "ready": bool(is_valid),
            "reason": str(reason or "").strip() or None,
            "has_sessionid": bool(cookies.get("sessionid") or cookies.get("sessionid_ss")),
            "has_sid_tt": bool(cookies.get("sid_tt")),
            "has_ms_token": bool(cookies.get("msToken") or cookies.get("ms_token")),
        }
    if normalized_platform == "twitter":
        cookies, bearer_token = _load_twitter_auth_from_sources()
        twikit_credentials = _load_twikit_credentials(cookies)
        is_valid, reason = _validate_twitter_cookie_health(cookies)
        structure = _remote_auth_safe_structure_flags(
            normalized_platform,
            cookies=cookies,
            bearer_token=bearer_token,
            twikit_credentials=twikit_credentials,
        )
        ready = bool(is_valid or structure.get("has_bearer_token") or structure.get("has_twikit_credentials"))
        return {
            "platform": normalized_platform,
            "ready": ready,
            "reason": None if ready else (str(reason or "").strip() or "missing_twitter_auth"),
            **structure,
        }
    if normalized_platform == "facebook":
        cookies = _load_facebook_cookies_from_sources()
        is_valid, reason = _validate_facebook_cookie_health(cookies)
        return {
            "platform": normalized_platform,
            "ready": bool(is_valid),
            "reason": str(reason or "").strip() or None,
            **_remote_auth_safe_structure_flags(normalized_platform, cookies=cookies),
        }
    if normalized_platform == "threads":
        cookies = _load_threads_cookies_from_sources()
        is_valid, reason = _validate_threads_cookie_health(cookies)
        try:
            from trr_backend.socials.threads.posts_scrapling.proxy import select_threads_posts_proxy

            proxy_config = select_threads_posts_proxy()
        except Exception:  # noqa: BLE001
            proxy_config = None
        return {
            "platform": normalized_platform,
            "ready": bool(is_valid),
            "reason": str(reason or "").strip() or None,
            **_remote_auth_safe_structure_flags(normalized_platform, cookies=cookies),
            "threads_posts_proxy_ready": bool(proxy_config),
            "threads_posts_proxy_fingerprint": proxy_config.fingerprint if proxy_config else "none",
            "threads_posts_proxy_provider": str(os.getenv("SOCIAL_THREADS_POSTS_PROXY_PROVIDER") or "").strip() or None,
            "decodo_username_present": bool(str(os.getenv("DECODO_USERNAME") or "").strip()),
            "decodo_password_present": bool(str(os.getenv("DECODO_PASSWORD") or "").strip()),
            "decodo_gateway_present": bool(str(os.getenv("DECODO_GATEWAY") or "").strip()),
        }
    if not normalized_platform:
        raise ValueError(f"Unsupported remote auth probe platform: {platform}")
    raise ValueError(f"Unsupported remote auth probe platform: {platform}")


def _modal_remote_auth_probe_cache_ttl_seconds(*, ready: bool) -> float:
    if not ready:
        return float(SOCIAL_MODAL_REMOTE_AUTH_PROBE_FAILURE_CACHE_TTL_SECONDS)
    return float(
        _resolve_positive_int_env(
            "TRR_MODAL_REMOTE_AUTH_PROBE_CACHE_TTL_SECONDS",
            SOCIAL_MODAL_REMOTE_AUTH_PROBE_CACHE_TTL_SECONDS_DEFAULT,
        )
    )


def _probe_modal_remote_auth_health(platform: str) -> dict[str, Any] | None:
    normalized_platform = _normalize_platform_name(platform)
    if not normalized_platform or not _platform_requires_remote_auth(normalized_platform):
        return None

    # Cache across requests so repeated gate rolls do not each spawn a Modal probe.
    cache_key = (
        normalized_platform,
        str(modal_app_name() or ""),
        str(modal_environment_name() or ""),
    )
    now = time_module.monotonic()
    with _MODAL_REMOTE_AUTH_PROBE_CACHE_LOCK:
        cached = _MODAL_REMOTE_AUTH_PROBE_CACHE.get(cache_key)
        if cached:
            expires_at, cached_payload = cached
            if expires_at > now:
                return copy.deepcopy(cached_payload)
            _MODAL_REMOTE_AUTH_PROBE_CACHE.pop(cache_key, None)

    payload = _probe_modal_remote_auth_health_uncached(normalized_platform)
    if isinstance(payload, dict):
        ttl_seconds = _modal_remote_auth_probe_cache_ttl_seconds(ready=bool(payload.get("ready")))
        with _MODAL_REMOTE_AUTH_PROBE_CACHE_LOCK:
            _MODAL_REMOTE_AUTH_PROBE_CACHE[cache_key] = (
                time_module.monotonic() + ttl_seconds,
                copy.deepcopy(payload),
            )
    return payload


def _probe_modal_remote_auth_health_uncached(platform: str) -> dict[str, Any] | None:
    normalized_platform = _normalize_platform_name(platform)
    if not normalized_platform or not _platform_requires_remote_auth(normalized_platform):
        return None
    try:
        import modal  # noqa: F401
    except Exception:  # noqa: BLE001
        return None

    probe_function_name = str(os.getenv("TRR_MODAL_SOCIAL_AUTH_PROBE_FUNCTION") or "probe_social_remote_auth").strip()
    if not probe_function_name:
        return None

    timeout_seconds = 8.0
    try:
        handle = get_trr_modal_function_handle(
            probe_function_name,
            app_name=modal_app_name(),
            environment_name=modal_environment_name(),
        )
        timeout_seconds = _modal_instagram_auth_probe_timeout_seconds(
            env_name=f"TRR_MODAL_{normalized_platform.upper()}_REMOTE_AUTH_PROBE_TIMEOUT_SECONDS",
            default_seconds=8.0,
            maximum_seconds=30.0,
        )
        payload = _invoke_modal_auth_probe_with_timeout(
            handle,
            normalized_platform,
            timeout_seconds=timeout_seconds,
        )
    except (TimeoutError, FuturesTimeoutError):
        return {
            "platform": normalized_platform,
            "ready": False,
            "reason": "probe_invocation_timeout",
            "detail": {
                "phase": "remote_probe",
                "modal_function": probe_function_name,
                "timeout_seconds": timeout_seconds,
            },
        }
    except Exception as exc:  # noqa: BLE001
        return {
            "platform": normalized_platform,
            "ready": False,
            "reason": "probe_invocation_failed",
            "detail": {
                "phase": "remote_probe",
                "exception_class": type(exc).__name__,
                "message": str(exc)[:240],
            },
        }

    if not isinstance(payload, Mapping):
        return {
            "platform": normalized_platform,
            "ready": False,
            "reason": "probe_invalid_payload",
            "detail": {"phase": "remote_probe", "payload_type": type(payload).__name__},
        }

    return {
        "platform": normalized_platform,
        "ready": bool(payload.get("ready")),
        "reason": str(payload.get("reason") or "").strip() or None,
        "detail": _metadata_dict(payload.get("detail")) or None,
    }


def _modal_instagram_auth_probe_timeout_seconds(
    *,
    env_name: str,
    default_seconds: float = 8.0,
    maximum_seconds: float = 30.0,
) -> float:
    raw = str(
        os.getenv(env_name) or os.getenv("TRR_MODAL_INSTAGRAM_AUTH_PROBE_TIMEOUT_SECONDS") or str(default_seconds)
    ).strip()
    try:
        parsed = float(raw)
    except ValueError:
        return default_seconds
    if parsed <= 0:
        return default_seconds
    return min(parsed, maximum_seconds)


def _invoke_modal_auth_probe_with_timeout(handle: Any, *args: Any, timeout_seconds: float, **kwargs: Any) -> Any:
    # One retry on timeout absorbs Modal cold-start spikes while keeping the
    # worst case bounded at ~2x timeout_seconds.
    for attempt in range(2):
        function_call = handle.spawn(*args, **kwargs)
        try:
            return function_call.get(timeout=timeout_seconds)
        except (TimeoutError, FuturesTimeoutError):
            try:
                function_call.cancel()
            except Exception:  # noqa: BLE001
                logger.debug("Failed to cancel timed-out Modal auth probe", exc_info=True)
            if attempt == 0:
                logger.warning(
                    "Modal auth probe timed out after %.1fs; retrying once",
                    timeout_seconds,
                )
                continue
            raise
    raise TimeoutError("Modal auth probe timed out")  # pragma: no cover - loop always returns or raises


def probe_modal_instagram_posts_auth_health(account_handle: str) -> dict[str, Any]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_account:
        return {
            "platform": "instagram",
            "account_handle": account_handle,
            "ready": False,
            "reason": "account_handle_required",
            "execution_backend": "modal",
        }

    try:
        import modal  # noqa: F401
    except Exception as exc:  # noqa: BLE001
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "ready": False,
            "reason": "modal_sdk_unavailable",
            "execution_backend": "modal",
            "detail": {"exception_class": type(exc).__name__, "message": str(exc)[:240]},
        }

    probe_function_name = str(
        os.getenv("TRR_MODAL_INSTAGRAM_POSTS_AUTH_PROBE_FUNCTION") or "probe_instagram_posts_auth"
    ).strip()
    if not probe_function_name:
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "ready": False,
            "reason": "probe_function_not_configured",
            "execution_backend": "modal",
        }

    timeout_seconds = 12.0
    try:
        handle = get_trr_modal_function_handle(
            probe_function_name,
            app_name=modal_app_name(),
            environment_name=modal_environment_name(),
        )
        timeout_seconds = _modal_instagram_auth_probe_timeout_seconds(
            env_name="TRR_MODAL_INSTAGRAM_POSTS_AUTH_PROBE_TIMEOUT_SECONDS",
            default_seconds=12.0,
            maximum_seconds=90.0,
        )
        payload = _invoke_modal_auth_probe_with_timeout(handle, normalized_account, timeout_seconds=timeout_seconds)
    except (TimeoutError, FuturesTimeoutError):
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "ready": False,
            "status": "transport_blocked",
            "result": "transport_blocked",
            "reason": "probe_timeout",
            "execution_backend": "modal",
            "detail": {
                "phase": "posts_auth_probe",
                "timeout_seconds": timeout_seconds,
            },
        }
    except Exception as exc:  # noqa: BLE001
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "ready": False,
            "reason": "probe_invocation_failed",
            "execution_backend": "modal",
            "detail": {
                "phase": "posts_auth_probe",
                "exception_class": type(exc).__name__,
                "message": str(exc)[:240],
            },
        }

    if not isinstance(payload, Mapping):
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "ready": False,
            "reason": "probe_invalid_payload",
            "execution_backend": "modal",
            "detail": {"payload_type": type(payload).__name__},
        }

    result = dict(payload)
    status = str(result.get("status") or result.get("result") or "").strip().lower()
    result["platform"] = "instagram"
    result["account_handle"] = str(result.get("account_handle") or normalized_account).strip() or normalized_account
    result["execution_backend"] = str(result.get("execution_backend") or "modal").strip().lower() or "modal"
    result["ready"] = bool(result.get("ready")) or status == "valid"
    result["reason"] = str(result.get("reason") or "").strip() or None
    return result


def _instagram_comments_auth_probe_shortcode(account_handle: str) -> str | None:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_account:
        return None
    try:
        row = pg.fetch_one(
            """
            select p.shortcode
            from social.instagram_posts p
            where lower(coalesce(p.source_account, p.username, p.owner_username, '')) = %s
              and nullif(p.shortcode, '') is not null
              and greatest(coalesce(p.comments_count, 0), 0) > 0
              and not coalesce(p.comments_disabled, p.is_comments_disabled, false)
            order by p.posted_at desc nulls last, p.scraped_at desc nulls last
            limit 1
            """,
            [normalized_account],
        )
    except Exception:  # noqa: BLE001
        logger.warning(
            "Failed selecting Instagram comments auth probe shortcode for %s",
            normalized_account,
            exc_info=True,
        )
        return None
    shortcode = str((row or {}).get("shortcode") or "").strip()
    return shortcode or None


def _instagram_comments_auth_probe_cache_seconds() -> float:
    raw = str(os.getenv("TRR_MODAL_INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE_SECONDS") or "").strip()
    if not raw:
        return _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE_DEFAULT_SECONDS
    try:
        value = float(raw)
    except ValueError:
        return _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE_DEFAULT_SECONDS
    return min(max(value, 0.0), 1_800.0)


def _instagram_comments_auth_probe_is_rate_limited(payload: Mapping[str, Any]) -> bool:
    reason = str(payload.get("reason") or payload.get("comments_auth_blocker") or "").strip().lower()
    status = str(payload.get("status") or payload.get("result") or "").strip().lower()
    return (
        bool(payload.get("rate_limited"))
        or reason in {"http_429", "rate_limited"}
        or "429" in reason
        or status == "rate_limited"
    )


def _instagram_comments_auth_rate_limit_action(cooldown_seconds: int) -> str:
    return (
        f"Instagram comments auth probe is rate-limited. Wait at least {cooldown_seconds} seconds, "
        "then rerun the strict comments auth probe before launching hidden-comments recovery."
    )


def _cached_instagram_comments_auth_rate_limit_probe(
    key: tuple[str, str, bool],
    *,
    now: float,
    ttl_seconds: float,
) -> dict[str, Any] | None:
    if ttl_seconds <= 0:
        return None
    with _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE_LOCK:
        cached = _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE.get(key)
        if not cached:
            return None
        cached_at, payload = cached
        age_seconds = max(0.0, now - cached_at)
        if age_seconds >= ttl_seconds:
            _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE.pop(key, None)
            return None
        result = dict(payload)
        remaining = max(1, int(round(ttl_seconds - age_seconds)))
        result["cache_hit"] = True
        result["cache_ttl_seconds"] = remaining
        result["cooldown_recommended_seconds"] = int(result.get("cooldown_recommended_seconds") or remaining)
        return result


def _store_instagram_comments_auth_rate_limit_probe(
    key: tuple[str, str, bool],
    payload: Mapping[str, Any],
    *,
    now: float,
    ttl_seconds: float,
) -> None:
    if ttl_seconds <= 0:
        return
    with _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE_LOCK:
        _INSTAGRAM_COMMENTS_AUTH_RATE_LIMIT_CACHE[key] = (now, dict(payload))


def probe_modal_instagram_comments_auth_health(
    account_handle: str,
    *,
    shortcode: str | None = None,
    strict_authenticated: bool = False,
) -> dict[str, Any]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_account:
        return {
            "platform": "instagram",
            "account_handle": account_handle,
            "ready": False,
            "reason": "account_handle_required",
            "execution_backend": "modal",
        }
    probe_shortcode = str(shortcode or "").strip() or _instagram_comments_auth_probe_shortcode(normalized_account)
    if not probe_shortcode:
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "ready": False,
            "reason": "comments_probe_shortcode_unavailable",
            "execution_backend": "modal",
            "status": "fetch_blocked",
            "result": "fetch_blocked",
        }
    cache_ttl_seconds = _instagram_comments_auth_probe_cache_seconds()
    cache_key = (normalized_account, probe_shortcode, bool(strict_authenticated))
    if strict_authenticated:
        cached_rate_limit = _cached_instagram_comments_auth_rate_limit_probe(
            cache_key,
            now=time_module.monotonic(),
            ttl_seconds=cache_ttl_seconds,
        )
        if cached_rate_limit is not None:
            return cached_rate_limit

    try:
        import modal  # noqa: F401
    except Exception as exc:  # noqa: BLE001
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "shortcode": probe_shortcode,
            "ready": False,
            "reason": "modal_sdk_unavailable",
            "execution_backend": "modal",
            "detail": {"exception_class": type(exc).__name__, "message": str(exc)[:240]},
        }

    probe_function_name = str(
        os.getenv("TRR_MODAL_INSTAGRAM_COMMENTS_AUTH_PROBE_FUNCTION") or "probe_instagram_comments_auth"
    ).strip()
    if not probe_function_name:
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "shortcode": probe_shortcode,
            "ready": False,
            "reason": "probe_function_not_configured",
            "execution_backend": "modal",
        }

    timeout_seconds = 30.0
    try:
        handle = get_trr_modal_function_handle(
            probe_function_name,
            app_name=modal_app_name(),
            environment_name=modal_environment_name(),
        )
        timeout_seconds = _modal_instagram_auth_probe_timeout_seconds(
            env_name="TRR_MODAL_INSTAGRAM_COMMENTS_AUTH_PROBE_TIMEOUT_SECONDS",
            default_seconds=30.0,
            maximum_seconds=90.0,
        )
        probe_args = (
            (normalized_account, probe_shortcode, True)
            if strict_authenticated
            else (normalized_account, probe_shortcode)
        )
        payload = _invoke_modal_auth_probe_with_timeout(
            handle,
            *probe_args,
            timeout_seconds=timeout_seconds,
        )
    except (TimeoutError, FuturesTimeoutError):
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "shortcode": probe_shortcode,
            "ready": False,
            "status": "transport_blocked",
            "result": "transport_blocked",
            "reason": "probe_timeout",
            "execution_backend": "modal",
            "detail": {
                "phase": "comments_auth_probe",
                "timeout_seconds": timeout_seconds,
            },
        }
    except Exception as exc:  # noqa: BLE001
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "shortcode": probe_shortcode,
            "ready": False,
            "reason": "probe_invocation_failed",
            "execution_backend": "modal",
            "detail": {
                "phase": "comments_auth_probe",
                "exception_class": type(exc).__name__,
                "message": str(exc)[:240],
            },
        }

    if not isinstance(payload, Mapping):
        return {
            "platform": "instagram",
            "account_handle": normalized_account,
            "shortcode": probe_shortcode,
            "ready": False,
            "reason": "probe_invalid_payload",
            "execution_backend": "modal",
            "detail": {"payload_type": type(payload).__name__},
        }

    result = dict(payload)
    status = str(result.get("status") or result.get("result") or "").strip().lower()
    public_ready = bool(result.get("public_ready")) or status == "public"
    auth_probe_skipped = bool(result.get("auth_probe_skipped"))
    authenticated_ready = bool(result.get("authenticated_ready")) or (
        status == "valid" and not auth_probe_skipped and status != "public"
    )
    result["platform"] = "instagram"
    result["account_handle"] = str(result.get("account_handle") or normalized_account).strip() or normalized_account
    result["shortcode"] = str(result.get("shortcode") or probe_shortcode).strip() or probe_shortcode
    result["execution_backend"] = str(result.get("execution_backend") or "modal").strip().lower() or "modal"
    result["public_ready"] = public_ready
    result["authenticated_ready"] = authenticated_ready
    result["ready"] = authenticated_ready if strict_authenticated else bool(result.get("ready")) or authenticated_ready
    result["auth_probe_skipped"] = auth_probe_skipped
    result["auth_required_for_hidden_comments"] = (
        bool(result.get("auth_required_for_hidden_comments")) or not authenticated_ready
    )
    result["comments_auth_blocker"] = (
        str(result.get("comments_auth_blocker") or result.get("reason") or "").strip() or None
    )
    if _instagram_comments_auth_probe_is_rate_limited(result):
        cooldown_seconds = int(result.get("cooldown_recommended_seconds") or cache_ttl_seconds or 300)
        result["rate_limited"] = True
        result["cooldown_recommended_seconds"] = cooldown_seconds
        result["operator_action"] = _instagram_comments_auth_rate_limit_action(cooldown_seconds)
    else:
        result["operator_action"] = str(result.get("operator_action") or "").strip() or (
            None
            if authenticated_ready
            else "Repair Instagram comments auth, then rerun the strict comments auth probe."
        )
    if strict_authenticated:
        result["strict_authenticated"] = True
    result["reason"] = str(result.get("reason") or "").strip() or None
    if strict_authenticated and _instagram_comments_auth_probe_is_rate_limited(result):
        _store_instagram_comments_auth_rate_limit_probe(
            cache_key,
            result,
            now=time_module.monotonic(),
            ttl_seconds=cache_ttl_seconds,
        )
    return result


def _remote_auth_capability_from_workers(
    *,
    platform: str,
    workers: list[dict[str, Any]],
) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform)
    auth_key = f"{normalized_platform}_authenticated"
    counts = {
        "total_authenticated_workers": 0,
        "fresh_authenticated_workers": 0,
        "healthy_authenticated_workers": 0,
    }
    auth_failure_reasons: Counter[str] = Counter()
    auth_failure_details: dict[str, dict[str, Any]] = {}
    for worker in workers:
        metadata = _metadata_dict(worker.get("metadata"))
        auth_capabilities = _metadata_dict(metadata.get("auth_capabilities"))
        execution_backend = str(metadata.get("execution_backend_canonical") or "").strip().lower() or (
            "modal" if str(worker.get("worker_id") or "").strip().lower().startswith("modal:") else "local"
        )
        if execution_backend != "modal":
            continue
        supported_platforms = {
            _normalize_platform_name(item)
            for item in (worker.get("supported_platforms") or CATALOG_SUPPORTED_PLATFORMS)
            if _normalize_platform_name(item)
        }
        if normalized_platform not in supported_platforms:
            continue
        if not bool(auth_capabilities.get(auth_key)):
            auth_reason = str(auth_capabilities.get(f"{normalized_platform}_auth_reason") or "").strip().lower()
            if auth_reason:
                auth_failure_reasons[auth_reason] += 1
                auth_detail = _metadata_dict(auth_capabilities.get(f"{normalized_platform}_auth_detail"))
                if auth_detail and auth_reason not in auth_failure_details:
                    auth_failure_details[auth_reason] = auth_detail
            continue
        counts["total_authenticated_workers"] += 1
        if bool(worker.get("is_fresh")):
            counts["fresh_authenticated_workers"] += 1
        if bool(worker.get("is_healthy")):
            counts["healthy_authenticated_workers"] += 1

    reason: str | None = None
    if counts["total_authenticated_workers"] <= 0:
        reason = (
            auth_failure_reasons.most_common(1)[0][0]
            if auth_failure_reasons
            else (f"no_remote_authenticated_{normalized_platform}_workers")
        )
    elif counts["fresh_authenticated_workers"] <= 0:
        reason = f"no_recent_remote_authenticated_{normalized_platform}_workers"
    elif counts["healthy_authenticated_workers"] <= 0:
        reason = f"no_healthy_remote_authenticated_{normalized_platform}_workers"

    return {
        "required": True,
        "executor_backend": "modal",
        **counts,
        "ready": counts["healthy_authenticated_workers"] > 0,
        "reason": reason,
        "detail": auth_failure_details.get(reason) if reason else None,
        "missing_hints": list(REMOTE_AUTH_MISSING_HINTS.get(normalized_platform) or []) if reason else [],
    }


def _build_remote_auth_capabilities(workers: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    return {
        platform: _remote_auth_capability_from_workers(platform=platform, workers=workers)
        for platform in REMOTE_AUTH_REQUIRED_PLATFORMS
    }


def update_worker_heartbeat(
    worker_id: str,
    *,
    stage: str | None,
    status: str,
    run_id: str | None = None,
    current_job_id: str | None = None,
    metadata: dict[str, Any] | None = None,
    supported_platforms: list[str] | None = None,
) -> dict[str, Any] | None:
    global _worker_health_cache, _queue_status_cache
    if not _worker_heartbeat_schema_ready():
        return None

    _cleaned = sorted({p.strip().lower() for p in (supported_platforms or []) if p.strip()})
    normalized_platforms = _cleaned if _cleaned else None

    row = pg.fetch_one(
        """
        insert into social.scrape_workers (
          worker_id,
          stage,
          status,
          run_id,
          current_job_id,
          metadata,
          started_at,
          last_seen_at,
          updated_at,
          supported_platforms
        )
        values (
          %s,
          %s,
          %s,
          %s,
          %s,
          %s::jsonb,
          now(),
          now(),
          now(),
          %s
        )
        on conflict (worker_id)
        do update set
          stage = excluded.stage,
          status = excluded.status,
          run_id = excluded.run_id,
          current_job_id = excluded.current_job_id,
          metadata = excluded.metadata,
          last_seen_at = now(),
          updated_at = now(),
          supported_platforms = CASE
            WHEN excluded.supported_platforms IS NOT NULL THEN excluded.supported_platforms
            ELSE social.scrape_workers.supported_platforms
          END
        returning
          worker_id,
          stage,
          status,
          run_id::text as run_id,
          current_job_id::text as current_job_id,
          metadata,
          started_at,
          last_seen_at,
          updated_at,
          supported_platforms
        """,
        [
            worker_id,
            _normalize_worker_stage(stage),
            _normalize_worker_status(status),
            run_id,
            current_job_id,
            json.dumps(metadata or {}),
            normalized_platforms,
        ],
        pool_name=SOCIAL_CATALOG_PROGRESS_POOL_NAME,
    )
    with _worker_health_cache_lock:
        _worker_health_cache = None
    with _queue_status_cache_lock:
        _queue_status_cache = None
    return row


def mark_worker_stopped(
    worker_id: str,
    *,
    stage: str | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    return update_worker_heartbeat(
        worker_id,
        stage=stage,
        status="stopped",
        run_id=None,
        current_job_id=None,
        metadata=metadata,
        supported_platforms=None,
    )


def execute_run_with_inline_worker_registration(
    run_id: str,
    *,
    worker_id: str,
    stage: str | None = None,
    platform: str | None = None,
    supported_platforms: list[str] | None = None,
    metadata_updates: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    effective_supported_platforms = supported_platforms or list(SUPPORTED_PLATFORMS)
    metadata = {
        "inline_worker": True,
        "execution_backend_canonical": "local",
        "execution_mode_canonical": "inline_fallback",
        "auth_capabilities": get_worker_auth_capabilities(effective_supported_platforms),
        "runtime_version": dict(_resolve_runtime_version_stamp()),
        **dict(metadata_updates or {}),
    }
    update_worker_heartbeat(
        worker_id,
        stage=stage or "any",
        status="working",
        run_id=run_id,
        metadata=metadata,
        supported_platforms=effective_supported_platforms,
    )
    try:
        return execute_run(run_id, worker_id=worker_id, stage=stage, platform=platform)
    finally:
        mark_worker_stopped(
            worker_id,
            stage=stage or "any",
            metadata={"inline_worker": True, "cleanup_reason": "inline_run_complete"},
        )


def _query_worker_health(*, stale_after_seconds: int | None = None) -> dict[str, Any]:
    stale_seconds = stale_after_seconds or _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    payload: dict[str, Any] = {
        "healthy": False,
        "healthy_workers": 0,
        "fresh_workers": 0,
        "stale_workers": 0,
        "stale_hidden_count": 0,
        "active_workers": 0,
        "total_workers": 0,
        "stale_after_seconds": stale_seconds,
        "by_stage": {},
        "by_platform": {},
        "remote_auth_capabilities": {},
        "workers": [],
        "reason": None,
    }

    if not _worker_heartbeat_schema_ready():
        payload["reason"] = "worker_heartbeat_schema_missing"
        return payload

    summary_row: dict[str, Any] = {}
    workers: list[dict[str, Any]] = []
    try:
        with pg.db_connection() as conn:
            with pg.db_cursor(conn=conn) as cur:
                cur.execute("set local statement_timeout = '5000'")
                summary_row = (
                    pg.fetch_one_with_cursor(
                        cur,
                        """
                        select
                          count(*)::int as total_workers,
                          count(*) filter (where status != 'stopped')::int as active_workers,
                          count(*) filter (
                            where status in ('starting', 'idle', 'working')
                              and last_seen_at >= now() - (%s * interval '1 second')
                          )::int as healthy_workers,
                          count(*) filter (
                            where last_seen_at >= now() - (%s * interval '1 second')
                          )::int as fresh_workers
                        from social.scrape_workers
                        """,
                        [stale_seconds, stale_seconds],
                    )
                    or {}
                )
                workers = pg.fetch_all_with_cursor(
                    cur,
                    """
                    select
                      worker_id,
                      stage,
                      status,
                      run_id::text as run_id,
                      current_job_id::text as current_job_id,
                      metadata,
                      started_at,
                      last_seen_at,
                      updated_at,
                      supported_platforms,
                      (
                        last_seen_at >= now() - (%s * interval '1 second')
                      ) as is_fresh,
                      (
                        status in ('starting', 'idle', 'working')
                        and last_seen_at >= now() - (%s * interval '1 second')
                      ) as is_healthy
                    from social.scrape_workers
                    order by last_seen_at desc
                    limit 120
                    """,
                    [stale_seconds, stale_seconds],
                )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Worker health query timed out or failed: %s", exc)
        payload["reason"] = "health_query_failed"
        return payload
    healthy_workers = int(summary_row.get("healthy_workers") or 0)
    fresh_workers = int(summary_row.get("fresh_workers") or 0)
    total_workers = int(summary_row.get("total_workers") or 0)
    active_workers = int(summary_row.get("active_workers") or 0)
    stale_workers = max(0, total_workers - fresh_workers)
    visible_stale_workers = sum(1 for worker in workers if not bool(worker.get("is_fresh")))
    stale_hidden_count = max(0, stale_workers - visible_stale_workers)
    by_stage: dict[str, dict[str, int]] = {}
    by_platform: dict[str, dict[str, int]] = {}
    for worker in workers:
        stage = str(worker.get("stage") or "any").strip().lower() or "any"
        stage_bucket = by_stage.setdefault(stage, {"total": 0, "healthy": 0, "fresh": 0})
        stage_bucket["total"] += 1
        if bool(worker.get("is_healthy")):
            stage_bucket["healthy"] += 1
        if bool(worker.get("is_fresh")):
            stage_bucket["fresh"] += 1
        for platform in worker.get("supported_platforms") or []:
            normalized_platform = _normalize_platform_name(platform) or "unknown"
            platform_bucket = by_platform.setdefault(normalized_platform, {"total": 0, "healthy": 0, "fresh": 0})
            platform_bucket["total"] += 1
            if bool(worker.get("is_healthy")):
                platform_bucket["healthy"] += 1
            if bool(worker.get("is_fresh")):
                platform_bucket["fresh"] += 1
    reason: str | None = None
    if total_workers <= 0:
        reason = "no_workers"
    elif healthy_workers <= 0:
        reason = "no_healthy_workers"
    remote_auth_capabilities = _build_remote_auth_capabilities(workers)
    payload.update(
        {
            "healthy": healthy_workers > 0,
            "healthy_workers": healthy_workers,
            "fresh_workers": fresh_workers,
            "stale_workers": stale_workers,
            "stale_hidden_count": stale_hidden_count,
            "active_workers": active_workers,
            "total_workers": total_workers,
            "by_stage": by_stage,
            "by_platform": by_platform,
            "remote_auth_capabilities": remote_auth_capabilities,
            "workers": workers,
            "reason": reason,
        }
    )
    return payload


def get_worker_health(*, stale_after_seconds: int | None = None) -> dict[str, Any]:
    global _worker_health_cache
    modal_executor_reason: str | None = None
    modal_executor_enabled = is_queue_enabled() and is_modal_remote_executor_enabled()
    if modal_executor_enabled:
        ready, reason = _modal_social_dispatch_ready()
        modal_executor_reason = None if ready else reason
    cache_ttl_seconds = _resolve_positive_int_env(
        "SOCIAL_WORKER_HEALTH_CACHE_TTL_SECONDS",
        SOCIAL_WORKER_HEALTH_CACHE_TTL_SECONDS_DEFAULT,
        minimum=0,
    )
    if cache_ttl_seconds <= 0:
        payload = _query_worker_health(stale_after_seconds=stale_after_seconds)
        if modal_executor_enabled:
            return _build_modal_executor_health_payload(reason=modal_executor_reason)
        return payload

    if modal_executor_enabled:
        return _build_modal_executor_health_payload(reason=modal_executor_reason)

    executor_cache_context = (modal_executor_enabled, modal_executor_reason)
    now = time_module.monotonic()
    with _worker_health_cache_lock:
        if _worker_health_cache is not None:
            cache_entry = _worker_health_cache
            cached_context = None
            if len(cache_entry) == 4:
                cached_at, cached_stale_after, cached_context, cached_payload = cache_entry
            else:
                cached_at, cached_stale_after, cached_payload = cache_entry
                if (
                    isinstance(cached_payload, Mapping)
                    and str(cached_payload.get("executor_backend") or "").strip().lower() == "modal"
                ):
                    cached_context = (True, None)
            if (
                cached_stale_after == stale_after_seconds
                and cached_context in {None, executor_cache_context}
                and (now - cached_at) < cache_ttl_seconds
            ):
                return copy.deepcopy(cached_payload)

    payload = _query_worker_health(stale_after_seconds=stale_after_seconds)
    if modal_executor_enabled:
        payload = _build_modal_executor_health_payload(reason=modal_executor_reason)
    else:
        payload["alerts"] = _build_worker_health_alerts(payload)
    with _worker_health_cache_lock:
        _worker_health_cache = (time_module.monotonic(), stale_after_seconds, executor_cache_context, payload)
    return copy.deepcopy(payload)


def _worker_uses_modal_backend(worker: Mapping[str, Any]) -> bool:
    worker_id = str(worker.get("worker_id") or "").strip().lower()
    metadata = _metadata_dict(worker.get("metadata"))
    execution_backend = str(metadata.get("execution_backend_canonical") or "").strip().lower()
    dispatcher_name = str(metadata.get("dispatcher_name") or "").strip().lower()
    return worker_id.startswith("modal:") or execution_backend == "modal" or dispatcher_name == "social"


def get_trusted_local_worker_health(
    *,
    platform: str | None = None,
    stale_after_seconds: int | None = None,
) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform) if platform else None
    base_payload = _query_worker_health(stale_after_seconds=stale_after_seconds)
    workers = [
        worker
        for worker in list(base_payload.get("workers") or [])
        if not _worker_uses_modal_backend(worker)
        and (
            normalized_platform is None
            or normalized_platform
            in {
                _normalize_platform_name(item)
                for item in (worker.get("supported_platforms") or [])
                if _normalize_platform_name(item)
            }
        )
    ]
    healthy_workers = sum(1 for worker in workers if bool(worker.get("is_healthy")))
    fresh_workers = sum(1 for worker in workers if bool(worker.get("is_fresh")))
    active_workers = sum(1 for worker in workers if str(worker.get("status") or "").strip().lower() == "working")
    payload = {
        **base_payload,
        "healthy": healthy_workers > 0,
        "healthy_workers": healthy_workers,
        "fresh_workers": fresh_workers,
        "stale_workers": max(0, len(workers) - fresh_workers),
        "stale_hidden_count": 0,
        "active_workers": active_workers,
        "total_workers": len(workers),
        "workers": workers,
        "executor_backend": "local",
        "required_worker_lane": TRUSTED_LOCAL_WORKER_LANE,
        "platform_filter": normalized_platform,
    }
    if len(workers) <= 0:
        payload["reason"] = "no_local_workers"
    elif healthy_workers <= 0:
        payload["reason"] = "no_healthy_local_workers"
    else:
        payload["reason"] = None
    return payload


def get_worker_health_for_lane(
    *,
    required_worker_lane: str,
    platform: str | None = None,
    stale_after_seconds: int | None = None,
) -> dict[str, Any]:
    normalized_lane = _normalize_required_worker_lane(required_worker_lane)
    if not normalized_lane:
        return get_worker_health(stale_after_seconds=stale_after_seconds)
    if normalized_lane == TRUSTED_LOCAL_WORKER_LANE:
        return get_trusted_local_worker_health(platform=platform, stale_after_seconds=stale_after_seconds)

    normalized_platform = _normalize_platform_name(platform) if platform else None
    base_payload = _query_worker_health(stale_after_seconds=stale_after_seconds)
    workers = []
    for worker in list(base_payload.get("workers") or []):
        metadata = _metadata_dict(worker.get("metadata"))
        worker_lane = _normalize_required_worker_lane(metadata.get("worker_lane"))
        if worker_lane != normalized_lane:
            continue
        supported_platforms = {
            _normalize_platform_name(item)
            for item in (worker.get("supported_platforms") or [])
            if _normalize_platform_name(item)
        }
        if normalized_platform is not None and normalized_platform not in supported_platforms:
            continue
        workers.append(worker)

    healthy_workers = sum(1 for worker in workers if bool(worker.get("is_healthy")))
    fresh_workers = sum(1 for worker in workers if bool(worker.get("is_fresh")))
    active_workers = sum(1 for worker in workers if str(worker.get("status") or "").strip().lower() == "working")
    payload = {
        **base_payload,
        "healthy": healthy_workers > 0,
        "healthy_workers": healthy_workers,
        "fresh_workers": fresh_workers,
        "stale_workers": max(0, len(workers) - fresh_workers),
        "stale_hidden_count": 0,
        "active_workers": active_workers,
        "total_workers": len(workers),
        "workers": workers,
        "executor_backend": "local",
        "required_worker_lane": normalized_lane,
        "platform_filter": normalized_platform,
    }
    if len(workers) <= 0:
        payload["reason"] = "no_lane_workers"
    elif healthy_workers <= 0:
        payload["reason"] = "no_healthy_lane_workers"
    else:
        payload["reason"] = None
    return payload


def _metadata_dict(value: Any) -> dict[str, Any]:
    return dict(value) if isinstance(value, dict) else {}


def _as_string_mapping(value: Any) -> dict[str, Any]:
    return cast(dict[str, Any], value) if isinstance(value, dict) else {}


def _metadata_value_truthy(value: Any) -> bool:
    if isinstance(value, str):
        return value.strip().lower() in {"1", "true", "yes", "on"}
    return bool(value)


def _collect_modal_capacity(workers: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    entries: list[dict[str, Any]] = []
    seen_functions: set[str] = set()
    total_max_containers = 0
    total_min_containers = 0

    def add_entry(raw_entry: Any) -> None:
        nonlocal total_max_containers, total_min_containers
        entry = _metadata_dict(raw_entry)
        modal_function = str(entry.get("modal_function") or "").strip()
        if not modal_function or modal_function in seen_functions:
            return
        seen_functions.add(modal_function)
        max_containers = _normalize_non_negative_int(entry.get("max_containers"))
        min_containers = _normalize_non_negative_int(entry.get("min_containers"))
        timeout_seconds = _normalize_non_negative_int(entry.get("timeout_seconds"))
        total_max_containers += max_containers
        total_min_containers += min_containers
        entries.append(
            {
                "worker_family": str(entry.get("worker_family") or "").strip() or None,
                "modal_app": str(entry.get("modal_app") or "").strip() or None,
                "modal_function": modal_function,
                "image_family": str(entry.get("image_family") or "").strip() or None,
                "timeout_seconds": timeout_seconds,
                "min_containers": min_containers,
                "max_containers": max_containers,
            }
        )

    for worker in workers:
        metadata = _metadata_dict(worker.get("metadata"))
        add_entry(metadata.get("modal_capacity"))
        for item in list(metadata.get("modal_capacity_by_function") or []):
            add_entry(item)

    return {
        "entries": entries,
        "total_min_containers": total_min_containers,
        "total_max_containers": total_max_containers,
    }


def _instagram_posts_feature_flag_enabled(name: str) -> bool:
    return str(os.getenv(name) or "").strip().lower() in {"1", "true", "yes", "on"}


def instagram_posts_acceleration_flags() -> dict[str, Any]:
    flags = {
        "bidirectional_walk_enabled": _instagram_posts_feature_flag_enabled(
            "SOCIAL_INSTAGRAM_POSTS_BIDIRECTIONAL_WALK_ENABLED"
        ),
        "per_ip_pacing_enabled": _instagram_posts_feature_flag_enabled("SOCIAL_INSTAGRAM_POSTS_PER_IP_PACING_ENABLED"),
        "page_proxy_rotation_enabled": _instagram_posts_feature_flag_enabled(
            "SOCIAL_INSTAGRAM_POSTS_PAGE_PROXY_ROTATION_ENABLED"
        ),
        "shared_warmup_enabled": _instagram_posts_feature_flag_enabled("SOCIAL_INSTAGRAM_POSTS_SHARED_WARMUP_ENABLED"),
    }
    return {
        "flags": flags,
        "disabled_by_default": True,
        "disable_guidance": {
            "SOCIAL_INSTAGRAM_POSTS_BIDIRECTIONAL_WALK_ENABLED": "Set to 0/false to force serial forward walking.",
            "SOCIAL_INSTAGRAM_POSTS_PER_IP_PACING_ENABLED": "Set to 0/false to use the legacy global pacing slot.",
            "SOCIAL_INSTAGRAM_POSTS_PAGE_PROXY_ROTATION_ENABLED": "Set to 0/false to pin the shard proxy.",
            "SOCIAL_INSTAGRAM_POSTS_SHARED_WARMUP_ENABLED": "Set to 0/false to warm each posts job independently.",
        },
    }


def _instagram_profile_pagination_table_ready() -> bool:
    return _relation_exists("social.instagram_profile_pagination_state")


def _normalize_instagram_pagination_direction(value: Any) -> str:
    normalized = str(value or "").strip().lower()
    return normalized if normalized in {"forward", "reverse"} else "forward"


def _format_instagram_pagination_state_row(row: Mapping[str, Any] | None) -> dict[str, Any]:
    if not row:
        return {}
    return {
        "id": str(row.get("id") or "").strip() or None,
        "run_id": str(row.get("run_id") or "").strip() or None,
        "job_id": str(row.get("job_id") or "").strip() or None,
        "account_handle": str(row.get("account_handle") or "").strip().lower().lstrip("@") or None,
        "source_scope": str(row.get("source_scope") or "").strip().lower() or None,
        "direction": _normalize_instagram_pagination_direction(row.get("direction")),
        "cursor_in": str(row.get("cursor_in") or "").strip() or None,
        "end_cursor": str(row.get("end_cursor") or "").strip() or None,
        "page_index": _normalize_non_negative_int(row.get("page_index")),
        "posts_seen": _normalize_non_negative_int(row.get("posts_seen")),
        "posts_upserted": _normalize_non_negative_int(row.get("posts_upserted")),
        "doc_id_used": str(row.get("doc_id_used") or "").strip() or None,
        "doc_ids_attempted": row.get("doc_ids_attempted") if isinstance(row.get("doc_ids_attempted"), list) else [],
        "proxy_fingerprint": str(row.get("proxy_fingerprint") or "").strip() or None,
        "proxy_session_key": str(row.get("proxy_session_key") or "").strip() or None,
        "stop_reason": str(row.get("stop_reason") or "").strip().lower() or None,
        "partial": bool(row.get("partial")),
        "metadata": _metadata_dict(row.get("metadata")),
        "updated_at": _iso(_coerce_dt(row.get("updated_at"))),
        "completed_at": _iso(_coerce_dt(row.get("completed_at"))),
    }


def latest_instagram_profile_pagination_state(
    *,
    account_handle: str,
    source_scope: str = "network",
    run_id: str | None = None,
    direction: str = "forward",
) -> dict[str, Any]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_scope = str(source_scope or "network").strip().lower() or "network"
    normalized_direction = _normalize_instagram_pagination_direction(direction)
    if not normalized_account or not _instagram_profile_pagination_table_ready():
        return {}
    params: list[Any] = [normalized_account, normalized_scope, normalized_direction]
    run_clause = ""
    normalized_run_id = str(run_id or "").strip()
    if normalized_run_id:
        run_clause = "and run_id = %s::uuid"
        params.append(normalized_run_id)
    try:
        row = pg.fetch_one(
            f"""
            select
              id::text as id,
              run_id::text as run_id,
              job_id,
              account_handle,
              source_scope,
              direction,
              cursor_in,
              end_cursor,
              page_index,
              posts_seen,
              posts_upserted,
              doc_id_used,
              doc_ids_attempted,
              proxy_fingerprint,
              proxy_session_key,
              stop_reason,
              partial,
              metadata,
              updated_at,
              completed_at
            from social.instagram_profile_pagination_state
            where lower(account_handle) = %s
              and source_scope = %s
              and direction = %s
              {run_clause}
            order by updated_at desc, page_index desc
            limit 1
            """,
            params,
        )
    except Exception:
        logger.debug(
            "Failed to load Instagram pagination state for @%s",
            normalized_account,
            exc_info=True,
        )
        return {}
    return _format_instagram_pagination_state_row(row)


def persist_instagram_profile_pagination_state(
    *,
    run_id: str | None,
    job_id: str | None,
    account_handle: str,
    source_scope: str = "network",
    direction: str = "forward",
    cursor_in: str | None = None,
    end_cursor: str | None = None,
    page_index: int = 0,
    posts_seen: int = 0,
    posts_upserted: int = 0,
    doc_id_used: str | None = None,
    doc_ids_attempted: Sequence[Any] | None = None,
    proxy_fingerprint: str | None = None,
    proxy_session_key: str | None = None,
    stop_reason: str | None = None,
    partial: bool = True,
    completed: bool = False,
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_scope = str(source_scope or "network").strip().lower() or "network"
    normalized_direction = _normalize_instagram_pagination_direction(direction)
    normalized_run_id = str(run_id or "").strip()
    if not normalized_account:
        return {"skipped": True, "reason": "missing_account_handle"}
    if not _instagram_profile_pagination_table_ready():
        return {"skipped": True, "reason": "pagination_state_table_missing"}

    attempted_doc_ids = [str(value).strip() for value in (doc_ids_attempted or []) if str(value).strip()]
    normalized_stop_reason = str(stop_reason or "").strip().lower() or None
    metadata_payload = _metadata_dict(metadata)
    params = [
        str(job_id or "").strip() or None,
        cursor_in,
        end_cursor,
        max(0, int(page_index or 0)),
        max(0, int(posts_seen or 0)),
        max(0, int(posts_upserted or 0)),
        str(doc_id_used or "").strip() or None,
        json.dumps(attempted_doc_ids),
        str(proxy_fingerprint or "").strip() or None,
        str(proxy_session_key or "").strip() or None,
        normalized_stop_reason,
        bool(partial),
        json.dumps(metadata_payload),
        bool(completed),
        normalized_run_id,
        normalized_account,
        normalized_scope,
        normalized_direction,
    ]
    try:
        updated_rows = pg.execute_returning(
            """
            update social.instagram_profile_pagination_state
            set
              job_id = %s,
              cursor_in = %s,
              end_cursor = %s,
              page_index = %s,
              posts_seen = %s,
              posts_upserted = %s,
              doc_id_used = %s,
              doc_ids_attempted = %s::jsonb,
              proxy_fingerprint = %s,
              proxy_session_key = %s,
              stop_reason = %s,
              partial = %s,
              metadata = coalesce(metadata, '{}'::jsonb) || %s::jsonb,
              updated_at = now(),
              completed_at = case when %s then now() else null end
            where run_id is not distinct from nullif(%s, '')::uuid
              and lower(account_handle) = %s
              and source_scope = %s
              and direction = %s
              and completed_at is null
            returning
              id::text as id,
              run_id::text as run_id,
              job_id,
              account_handle,
              source_scope,
              direction,
              cursor_in,
              end_cursor,
              page_index,
              posts_seen,
              posts_upserted,
              doc_id_used,
              doc_ids_attempted,
              proxy_fingerprint,
              proxy_session_key,
              stop_reason,
              partial,
              metadata,
              updated_at,
              completed_at
            """,
            params,
        )
    except Exception:
        logger.debug(
            "Failed to persist Instagram pagination state for @%s",
            normalized_account,
            exc_info=True,
        )
        return {"skipped": True, "reason": "pagination_state_persist_failed"}
    if updated_rows:
        return _format_instagram_pagination_state_row(updated_rows[0])

    try:
        inserted_rows = pg.execute_returning(
            """
            insert into social.instagram_profile_pagination_state (
              run_id,
              job_id,
              account_handle,
              source_scope,
              direction,
              cursor_in,
              end_cursor,
              page_index,
              posts_seen,
              posts_upserted,
              doc_id_used,
              doc_ids_attempted,
              proxy_fingerprint,
              proxy_session_key,
              stop_reason,
              partial,
              metadata,
              completed_at
            )
            values (
              nullif(%s, '')::uuid,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s::jsonb,
              %s,
              %s,
              %s,
              %s,
              %s::jsonb,
              case when %s then now() else null end
            )
            returning
              id::text as id,
              run_id::text as run_id,
              job_id,
              account_handle,
              source_scope,
              direction,
              cursor_in,
              end_cursor,
              page_index,
              posts_seen,
              posts_upserted,
              doc_id_used,
              doc_ids_attempted,
              proxy_fingerprint,
              proxy_session_key,
              stop_reason,
              partial,
              metadata,
              updated_at,
              completed_at
            """,
            [
                normalized_run_id,
                str(job_id or "").strip() or None,
                normalized_account,
                normalized_scope,
                normalized_direction,
                cursor_in,
                end_cursor,
                max(0, int(page_index or 0)),
                max(0, int(posts_seen or 0)),
                max(0, int(posts_upserted or 0)),
                str(doc_id_used or "").strip() or None,
                json.dumps(attempted_doc_ids),
                str(proxy_fingerprint or "").strip() or None,
                str(proxy_session_key or "").strip() or None,
                normalized_stop_reason,
                bool(partial),
                json.dumps(metadata_payload),
                bool(completed),
            ],
        )
    except Exception:
        logger.debug(
            "Failed to insert Instagram pagination state for @%s",
            normalized_account,
            exc_info=True,
        )
        return {"skipped": True, "reason": "pagination_state_persist_failed"}
    return _format_instagram_pagination_state_row(inserted_rows[0] if inserted_rows else {})


def _compute_currently_scraping(*, worker: dict[str, Any], job: dict[str, Any] | None) -> str | None:
    if not job:
        stage = str(worker.get("stage") or "").strip()
        return stage or None
    metadata = _metadata_dict(job.get("metadata"))
    activity = _metadata_dict(metadata.get("activity"))
    phase = str(activity.get("phase") or "").strip()
    if phase:
        return phase
    stage = str(job.get("stage") or "").strip()
    platform = str(job.get("platform") or "").strip()
    account_handle = str(job.get("account_handle") or "").strip().lstrip("@")
    parts = [part for part in [platform, stage, account_handle] if part]
    return " · ".join(parts) if parts else None


def _compute_progress_made(*, job: dict[str, Any] | None) -> dict[str, Any]:
    if not job:
        return {
            "items_found": 0,
            "posts_upserted": 0,
            "comments_upserted": 0,
            "stage_counters": {},
            "phase": None,
        }
    metadata = _metadata_dict(job.get("metadata"))
    persist_counters = _metadata_dict(metadata.get("persist_counters"))
    stage_counters = _metadata_dict(metadata.get("stage_counters"))
    activity = _metadata_dict(metadata.get("activity"))
    return {
        "items_found": _normalize_non_negative_int(job.get("items_found")),
        "posts_upserted": _normalize_non_negative_int(persist_counters.get("posts_upserted")),
        "comments_upserted": _normalize_non_negative_int(persist_counters.get("comments_upserted")),
        "stage_counters": stage_counters,
        "phase": str(activity.get("phase") or "").strip() or None,
    }


def get_worker_detail(worker_id: str, *, stale_after_seconds: int | None = None) -> dict[str, Any]:
    normalized_worker_id = str(worker_id or "").strip()
    if not normalized_worker_id:
        raise ValueError("worker_not_found")
    if not _worker_heartbeat_schema_ready():
        raise ValueError("worker_heartbeat_schema_missing")

    stale_seconds = stale_after_seconds or _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    worker_row = pg.fetch_one(
        """
        select
          worker_id,
          stage,
          status,
          run_id::text as run_id,
          current_job_id::text as current_job_id,
          metadata,
          started_at,
          last_seen_at,
          updated_at,
          supported_platforms,
          (
            status in ('starting', 'idle', 'working')
            and last_seen_at >= now() - (%s * interval '1 second')
          ) as is_healthy
        from social.scrape_workers
        where worker_id = %s
        limit 1
        """,
        [stale_seconds, normalized_worker_id],
    )
    if not worker_row:
        raise ValueError("worker_not_found")

    features = _scrape_jobs_features()
    has_run_id = bool(features.get("has_run_id"))
    has_queue_fields = bool(features.get("has_queue_fields"))
    current_job_id = str(worker_row.get("current_job_id") or "").strip()
    job_row: dict[str, Any] | None = None
    if current_job_id and _relation_exists("social.scrape_jobs"):
        select_run_id = "j.run_id::text as run_id" if has_run_id else "null::text as run_id"
        select_attempt_count = "j.attempt_count" if has_queue_fields else "0::int as attempt_count"
        select_max_attempts = "j.max_attempts" if has_queue_fields else "0::int as max_attempts"
        select_heartbeat_at = "j.heartbeat_at" if has_queue_fields else "null::timestamptz as heartbeat_at"
        select_last_error_code = "j.last_error_code" if has_queue_fields else "null::text as last_error_code"
        job_row = pg.fetch_one(
            f"""
            select
              j.id::text as id,
              {select_run_id},
              j.platform,
              j.job_type,
              j.status,
              coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) as stage,
              j.config,
              j.metadata,
              j.items_found,
              {select_attempt_count},
              {select_max_attempts},
              j.started_at,
              {select_heartbeat_at},
              j.error_message,
              {select_last_error_code}
            from social.scrape_jobs j
            where j.id = %s::uuid
            limit 1
            """,
            [current_job_id],
        )

    run_id = str((job_row or {}).get("run_id") or worker_row.get("run_id") or "").strip() or None
    run_row: dict[str, Any] | None = None
    if run_id and _relation_exists("social.scrape_runs"):
        run_row = pg.fetch_one(
            """
            select
              id::text as run_id,
              status,
              source_scope,
              config,
              created_at,
              started_at,
              completed_at,
              summary
            from social.scrape_runs
            where id = %s::uuid
            limit 1
            """,
            [run_id],
        )

    job_payload: dict[str, Any] | None = None
    if isinstance(job_row, dict):
        job_config = _metadata_dict(job_row.get("config"))
        account_handle = (
            str(job_config.get("account") or "").strip()
            or str(job_config.get("username") or "").strip()
            or str(job_config.get("source_account") or "").strip()
            or None
        )
        job_payload = {
            "id": str(job_row.get("id") or ""),
            "run_id": str(job_row.get("run_id") or "").strip() or None,
            "platform": str(job_row.get("platform") or ""),
            "job_type": str(job_row.get("job_type") or ""),
            "status": str(job_row.get("status") or ""),
            "stage": str(job_row.get("stage") or ""),
            "account_handle": account_handle,
            "items_found": _normalize_non_negative_int(job_row.get("items_found")),
            "attempt_count": _normalize_non_negative_int(job_row.get("attempt_count")),
            "max_attempts": _normalize_non_negative_int(job_row.get("max_attempts")),
            "started_at": _iso(_coerce_dt(job_row.get("started_at"))),
            "heartbeat_at": _iso(_coerce_dt(job_row.get("heartbeat_at"))),
            "error_message": str(job_row.get("error_message") or "").strip() or None,
            "last_error_code": str(job_row.get("last_error_code") or "").strip() or None,
            "metadata": _metadata_dict(job_row.get("metadata")),
        }

    run_payload: dict[str, Any] | None = None
    if isinstance(run_row, dict):
        run_config = _metadata_dict(run_row.get("config"))
        run_payload = {
            "run_id": str(run_row.get("run_id") or "").strip() or None,
            "status": str(run_row.get("status") or "").strip() or None,
            "source_scope": str(run_row.get("source_scope") or "").strip() or None,
            "execution_owner": str(run_config.get("execution_owner") or "").strip() or None,
            "execution_mode_canonical": (str(run_config.get("execution_mode_canonical") or "").strip() or None),
            "execution_backend_canonical": (str(run_config.get("execution_backend_canonical") or "").strip() or None),
            "created_at": _iso(_coerce_dt(run_row.get("created_at"))),
            "started_at": _iso(_coerce_dt(run_row.get("started_at"))),
            "completed_at": _iso(_coerce_dt(run_row.get("completed_at"))),
            "summary": _metadata_dict(run_row.get("summary")),
        }

    worker_payload = {
        "worker_id": str(worker_row.get("worker_id") or ""),
        "stage": str(worker_row.get("stage") or ""),
        "status": str(worker_row.get("status") or ""),
        "run_id": str(worker_row.get("run_id") or "").strip() or None,
        "current_job_id": str(worker_row.get("current_job_id") or "").strip() or None,
        "started_at": _iso(_coerce_dt(worker_row.get("started_at"))),
        "last_seen_at": _iso(_coerce_dt(worker_row.get("last_seen_at"))),
        "supported_platforms": list(worker_row.get("supported_platforms") or []),
        "metadata": _metadata_dict(worker_row.get("metadata")),
        "is_healthy": bool(worker_row.get("is_healthy")),
    }

    return {
        "worker": worker_payload,
        "current_job": job_payload,
        "run": run_payload,
        "currently_scraping": _compute_currently_scraping(worker=worker_payload, job=job_payload),
        "progress_made": _compute_progress_made(job=job_payload),
    }


def purge_inactive_workers(*, stale_after_seconds: int | None = None) -> dict[str, Any]:
    global _worker_health_cache
    stale_seconds = stale_after_seconds or _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    if not _worker_heartbeat_schema_ready():
        return {
            "stale_after_seconds": stale_seconds,
            "active_workers": 0,
            "total_workers_before": 0,
            "total_workers_after": 0,
            "deleted_workers": 0,
            "reason": "worker_heartbeat_schema_missing",
        }

    active_clause = "status in ('starting', 'idle', 'working') and last_seen_at >= now() - (%s * interval '1 second')"
    snapshot_row = (
        pg.fetch_one(
            f"""
            select
              count(*) filter (where {active_clause})::int as active_workers,
              count(*)::int as total_workers
            from social.scrape_workers
            """,
            [stale_seconds],
        )
        or {}
    )
    deleted_rows = pg.execute_returning(
        f"""
        delete from social.scrape_workers
        where not ({active_clause})
        returning worker_id
        """,
        [stale_seconds],
    )

    active_workers = int(snapshot_row.get("active_workers") or 0)
    total_workers_before = int(snapshot_row.get("total_workers") or 0)
    deleted_workers = len(deleted_rows or [])
    with _worker_health_cache_lock:
        _worker_health_cache = None
    return {
        "stale_after_seconds": stale_seconds,
        "active_workers": active_workers,
        "total_workers_before": total_workers_before,
        "total_workers_after": max(0, total_workers_before - deleted_workers),
        "deleted_workers": deleted_workers,
        "reason": None,
    }


def assert_worker_available_when_queue_enabled(
    *,
    required_worker_lane: str | None = None,
    required_execution_backend: str | None = None,
    platform: str | None = None,
    account_handle: str | None = None,
) -> dict[str, Any]:
    normalized_required_lane = _normalize_required_worker_lane(required_worker_lane)
    if not is_queue_enabled():
        return {
            "healthy": True,
            "healthy_workers": 0,
            "active_workers": 0,
            "total_workers": 0,
            "workers": [],
            "reason": "queue_disabled",
        }

    if normalized_required_lane:
        health = get_worker_health_for_lane(
            required_worker_lane=normalized_required_lane,
            platform=platform,
        )
        if bool(health.get("healthy")):
            return health
        raise SocialWorkerUnavailableError(
            (
                "No healthy trusted-local social ingest workers are reporting heartbeats."
                if normalized_required_lane == TRUSTED_LOCAL_WORKER_LANE
                else f"No healthy {normalized_required_lane} social ingest workers are reporting heartbeats."
            ),
            worker_health=health,
        )

    if str(required_execution_backend or "").strip().lower() == "modal":
        ready, reason = _modal_social_dispatch_ready()
        if not (is_modal_remote_executor_enabled() and ready):
            payload = _build_modal_executor_health_payload(
                reason=reason or "modal_executor_required",
                platform=platform,
                account_handle=account_handle,
            )
            raise SocialWorkerUnavailableError(
                "Modal social dispatch is required for this social ingest job.",
                worker_health=payload,
            )
        _touch_modal_social_dispatcher_heartbeat(
            metadata_updates={
                "dispatch_enabled": True,
                "last_dispatch_success_at": _iso(_now_utc()),
            }
        )
        payload = _build_modal_executor_health_payload(
            reason="modal_executor_ready",
            platform=platform,
            account_handle=account_handle,
        )
        platform_readiness = _metadata_dict(payload.get("shared_account_backfill_readiness"))
        if platform and not bool(platform_readiness.get("ready")):
            normalized_platform = _normalize_platform_name(platform) or str(platform).strip().lower()
            raise SocialWorkerUnavailableError(
                f"Modal social dispatch auth preflight is not ready for {normalized_platform}.",
                worker_health=payload,
            )
        return payload

    if is_modal_remote_executor_enabled():
        ready, reason = _modal_social_dispatch_ready()
        if not ready:
            payload = _build_modal_executor_health_payload(
                reason=reason, platform=platform, account_handle=account_handle
            )
            raise SocialWorkerUnavailableError(
                "Modal social dispatch is not configured for remote execution.",
                worker_health=payload,
            )
        _touch_modal_social_dispatcher_heartbeat(
            metadata_updates={
                "dispatch_enabled": True,
                "last_dispatch_success_at": _iso(_now_utc()),
            }
        )
        return _build_modal_executor_health_payload(
            reason="modal_executor_ready",
            platform=platform,
            account_handle=account_handle,
        )

    health = get_worker_health()
    if bool(health.get("healthy")):
        return health

    reason = str(health.get("reason") or "no_healthy_workers")
    if reason == "worker_heartbeat_schema_missing":
        message = "Social worker heartbeat schema is missing. Apply migration 0130 before enabling queue mode."
    else:
        message = "No healthy social ingest workers are reporting heartbeats."
    raise SocialWorkerUnavailableError(message, worker_health=health)


def _empty_queue_status_counts() -> dict[str, int]:
    return dict.fromkeys(QUEUE_STATUS_STAGES, 0)


def _stuck_jobs_filter_clause(
    *,
    has_queue_fields: bool,
    table_alias: str = "j",
) -> tuple[str, list[Any]]:
    stale_seconds_expr, stale_seconds_params = _build_social_job_stale_seconds_sql_expr(
        table_alias=table_alias,
        has_queue_fields=has_queue_fields,
    )
    running_reference_with_queue = (
        f"coalesce({table_alias}.heartbeat_at, {table_alias}.started_at, "
        f"{table_alias}.claimed_at, {table_alias}.created_at)"
    )
    running_reference = (
        running_reference_with_queue
        if has_queue_fields
        else f"coalesce({table_alias}.started_at, {table_alias}.created_at)"
    )
    retrying_reference_with_queue = (
        f"coalesce({table_alias}.available_at, {table_alias}.heartbeat_at, "
        f"{table_alias}.started_at, {table_alias}.claimed_at, {table_alias}.created_at)"
    )
    retrying_reference = retrying_reference_with_queue if has_queue_fields else f"{table_alias}.created_at"
    stale_timeout_signal_clause = (
        f"""
        (
          coalesce({table_alias}.last_error_code, '') = 'stale_heartbeat_timeout'
          or lower(coalesce({table_alias}.metadata->>'error_code', '')) = 'stale_heartbeat_timeout'
          or coalesce({table_alias}.error_message, '') ilike 'stale_heartbeat_timeout:%%'
        )
        """
        if has_queue_fields
        else f"""
        (
          lower(coalesce({table_alias}.metadata->>'error_code', '')) = 'stale_heartbeat_timeout'
          or coalesce({table_alias}.error_message, '') ilike 'stale_heartbeat_timeout:%%'
        )
        """
    )
    return (
        f"""
        (
          (
            {table_alias}.status = 'running'
            and {running_reference} < now() - (({stale_seconds_expr}) * interval '1 second')
          )
          or (
            {table_alias}.status = 'retrying'
            and {retrying_reference} < now() - (({stale_seconds_expr}) * interval '1 second')
            and {stale_timeout_signal_clause}
          )
        )
        """,
        [*stale_seconds_params, *stale_seconds_params],
    )


def _list_stuck_jobs(
    *,
    limit: int = SOCIAL_QUEUE_STATUS_STUCK_JOBS_LIMIT_DEFAULT,
) -> tuple[list[dict[str, Any]], int]:
    safe_limit = max(1, min(int(limit), 500))
    features = _scrape_jobs_features()
    has_queue_fields = bool(features.get("has_queue_fields"))
    has_run_id = bool(features.get("has_run_id"))
    where_clause, where_params = _stuck_jobs_filter_clause(
        has_queue_fields=has_queue_fields,
        table_alias="j",
    )

    select_run_id = "j.run_id::text as run_id" if has_run_id else "null::text as run_id"
    select_worker_id = "j.worker_id as worker_id" if has_queue_fields else "null::text as worker_id"
    select_heartbeat_at = "j.heartbeat_at as heartbeat_at" if has_queue_fields else "null::timestamptz as heartbeat_at"
    select_available_at = "j.available_at as available_at" if has_queue_fields else "null::timestamptz as available_at"
    select_last_error_code = (
        "j.last_error_code as last_error_code" if has_queue_fields else "null::text as last_error_code"
    )
    stuck_for_reference = (
        "coalesce(j.available_at, j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)"
        if has_queue_fields
        else "coalesce(j.started_at, j.created_at)"
    )
    rows = pg.fetch_all(
        f"""
        with stuck_jobs as (
          select
            j.id::text as id,
            {select_run_id},
            j.platform,
            j.job_type,
            j.status,
            {select_worker_id},
            j.created_at,
            {select_heartbeat_at},
            {select_available_at},
            j.error_message,
            {select_last_error_code},
            case
              when j.status = 'running' then 'running_stale_heartbeat'
              else 'retrying_stale_timeout'
            end as stuck_reason,
            greatest(0, floor(extract(epoch from (now() - {stuck_for_reference}))))::int as stuck_for_seconds
          from social.scrape_jobs j
          where {where_clause}
          order by stuck_for_seconds desc, j.created_at asc
          limit %s
        )
        select
          id,
          run_id,
          platform,
          job_type,
          status,
          worker_id,
          created_at,
          heartbeat_at,
          available_at,
          error_message,
          last_error_code,
          stuck_reason,
          stuck_for_seconds
        from stuck_jobs
        """,
        [*where_params, safe_limit],
    )
    total_row = (
        pg.fetch_one(
            f"""
        select count(*)::int as total
        from social.scrape_jobs j
        where {where_clause}
        """,
            where_params,
        )
        or {}
    )
    entries = [
        {
            "id": str(row.get("id") or ""),
            "run_id": str(row.get("run_id") or "") or None,
            "platform": str(row.get("platform") or ""),
            "job_type": str(row.get("job_type") or ""),
            "status": str(row.get("status") or ""),
            "worker_id": str(row.get("worker_id") or "") or None,
            "created_at": _iso(_coerce_dt(row.get("created_at"))),
            "heartbeat_at": _iso(_coerce_dt(row.get("heartbeat_at"))),
            "available_at": _iso(_coerce_dt(row.get("available_at"))),
            "error_message": str(row.get("error_message") or "") or None,
            "last_error_code": str(row.get("last_error_code") or "") or None,
            "stuck_reason": str(row.get("stuck_reason") or ""),
            "stuck_for_seconds": int(row.get("stuck_for_seconds") or 0),
        }
        for row in rows
        if str(row.get("id") or "").strip()
    ]
    return entries, int(total_row.get("total") or 0)


def _count_stuck_jobs() -> int:
    features = _scrape_jobs_features()
    has_queue_fields = bool(features.get("has_queue_fields"))
    where_clause, where_params = _stuck_jobs_filter_clause(has_queue_fields=has_queue_fields, table_alias="j")
    row = (
        pg.fetch_one(
            f"""
        select count(*)::int as total
        from social.scrape_jobs j
        where {where_clause}
        """,
            where_params,
        )
        or {}
    )
    return int(row.get("total") or 0)


def _list_dispatch_blocked_jobs(
    *,
    limit: int = SOCIAL_QUEUE_STATUS_DISPATCH_BLOCKED_JOBS_LIMIT_DEFAULT,
) -> tuple[list[dict[str, Any]], int]:
    safe_limit = max(1, min(int(limit), 500))
    where_clause, where_params = _dispatch_blocked_jobs_filter_clause(table_alias="j")
    rows = pg.fetch_all(
        f"""
        select
          j.id::text as id,
          j.run_id::text as run_id,
          j.platform,
          j.job_type,
          j.status,
          j.worker_id,
          j.created_at,
          j.heartbeat_at,
          j.available_at,
          j.error_message,
          j.last_error_code,
          j.metadata
        from social.scrape_jobs j
        where {where_clause}
        order by coalesce(
          nullif(j.metadata->'dispatch'->>'dispatch_blocked_first_seen_at', '')::timestamptz,
          nullif(j.metadata->'dispatch'->>'last_dispatch_error_at', '')::timestamptz,
          nullif(j.metadata->'dispatch'->>'remote_invocation_checked_at', '')::timestamptz,
          nullif(j.metadata->'dispatch'->>'dispatch_requested_at', '')::timestamptz,
          j.available_at,
          j.created_at
        ) asc nulls last,
        j.created_at asc
        limit %s
        """,
        [*where_params, safe_limit],
    )
    total_row = (
        pg.fetch_one(
            f"""
            select count(*)::int as total
            from social.scrape_jobs j
            where {where_clause}
            """,
            where_params,
        )
        or {}
    )
    entries = []
    for row in rows:
        dispatch = _job_dispatch_metadata(row)
        reason = _normalize_dispatch_blocked_reason(
            remote_blocked_reason=dispatch.get("remote_blocked_reason"),
            last_dispatch_error_code=dispatch.get("last_dispatch_error_code"),
            last_dispatch_error=dispatch.get("last_dispatch_error"),
        )
        entries.append(
            {
                "id": str(row.get("id") or ""),
                "run_id": str(row.get("run_id") or "") or None,
                "platform": str(row.get("platform") or ""),
                "job_type": str(row.get("job_type") or ""),
                "status": str(row.get("status") or ""),
                "worker_id": str(row.get("worker_id") or "") or None,
                "created_at": _iso(_coerce_dt(row.get("created_at"))),
                "heartbeat_at": _iso(_coerce_dt(row.get("heartbeat_at"))),
                "available_at": _iso(_coerce_dt(row.get("available_at"))),
                "error_message": str(row.get("error_message") or "") or None,
                "last_error_code": str(row.get("last_error_code") or "") or None,
                "stuck_reason": reason,
                "stuck_for_seconds": _dispatch_blocked_seconds(dispatch, row),
            }
        )
    return entries, int(total_row.get("total") or 0)


def _count_dispatch_blocked_jobs() -> int:
    where_clause, where_params = _dispatch_blocked_jobs_filter_clause(table_alias="j")
