def _resolve_recent_failure_auto_dismiss_seconds() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_RECENT_FAILURE_AUTO_DISMISS_SECONDS",
        _RECENT_FAILURE_AUTO_DISMISS_SECONDS_DEFAULT,
        minimum=60,
        maximum=86_400,
    )


def _recent_failure_not_dismissed_sql(table_alias: str = "j") -> str:
    visible_for_seconds = _resolve_recent_failure_auto_dismiss_seconds()
    return f"""
    nullif(coalesce({table_alias}.metadata->>'{_RECENT_FAILURE_DISMISSED_AT_KEY}', ''), '') is null
    and coalesce({table_alias}.completed_at, {table_alias}.created_at)
      >= now() - make_interval(secs => {visible_for_seconds})
    """


def _run_failure_not_dismissed_sql(table_alias: str = "r") -> str:
    return f"nullif(coalesce({table_alias}.config->>'{_RUN_FAILURE_DISMISSED_AT_KEY}', ''), '') is null"


def _catalog_run_auth_repair_command(*, modal_environment: str | None = None) -> str:
    command = ["python", "scripts/modal/repair_instagram_auth.py", "--json"]
    normalized_environment = str(modal_environment or "").strip()
    if normalized_environment:
        command.extend(["--modal-environment", normalized_environment])
    return " ".join(shlex.quote(part) for part in command)


def _catalog_run_auth_repair_action(platform: str) -> str | None:
    normalized_platform = _normalize_platform_name(platform) or ""
    if normalized_platform == "instagram":
        return "repair_instagram_auth"
    if normalized_platform in _COOKIE_REFRESH_SUPPORTED_PLATFORMS:
        return "cookie_refresh"
    return None


def _catalog_run_auth_repair_environment(platform: str) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform) or ""
    runtime = execution_metadata()
    execution_mode = str(runtime.get("execution_mode_canonical") or "").strip().lower() or "local"
    execution_owner = str(runtime.get("execution_owner") or "").strip() or "local_api"
    modal_environment = modal_environment_name()
    repair_action = _catalog_run_auth_repair_action(normalized_platform)
    supported = repair_action is not None and execution_mode == "local"
    unsupported_reason: str | None = None
    if repair_action is None:
        unsupported_reason = "unsupported_platform"
    elif execution_mode != "local":
        unsupported_reason = "interactive_browser_requires_local_api"
    return {
        "supported": supported,
        "repair_action": repair_action,
        "execution_mode": execution_mode,
        "execution_owner": execution_owner,
        "modal_environment": modal_environment or None,
        "unsupported_reason": unsupported_reason,
        "repair_command": (
            _catalog_run_auth_repair_command(modal_environment=modal_environment)
            if repair_action == "repair_instagram_auth"
            else None
        ),
    }


def _instagram_auth_repair_module():
    from scripts.modal import repair_instagram_auth

    return repair_instagram_auth


def _merge_catalog_run_config(
    *,
    run_id: str,
    metadata_updates: Mapping[str, Any],
    conn: Any | None = None,
) -> dict[str, Any]:
    query = """
        update social.scrape_runs
        set config = coalesce(config, '{}'::jsonb) || %s::jsonb
        where id = %s::uuid
        returning
          id::text as id,
          status,
          config
        """
    params = [_json_dumps(_metadata_dict(metadata_updates)), run_id]
    if conn is not None:
        with pg.db_cursor(conn=conn, label="merge_catalog_run_config") as cur:
            row = pg.fetch_one_with_cursor(cur, query, params)
    else:
        row = pg.fetch_one(query, params)
    _invalidate_queue_status_cache()
    return {
        "id": str((row or {}).get("id") or "").strip(),
        "status": str((row or {}).get("status") or "").strip().lower(),
        "config": _metadata_dict((row or {}).get("config")),
    }


def _reactivate_catalog_run(run_id: str) -> None:
    pg.fetch_one(
        """
        update social.scrape_runs
        set
          status = 'running',
          started_at = coalesce(started_at, now()),
          completed_at = null,
          cancelled_at = null
        where id = %s::uuid
        returning id::text
        """,
        [run_id],
    )
    _invalidate_queue_status_cache()


def _active_posts_auth_cooldown(platform: Any, account_handle: Any) -> dict[str, Any] | None:
    """Return active auth-cooldown metadata for the account, or None.

    Lazy import (matches the module's other instagram imports) so the heavy
    instagram package is not pulled in at module load. Fails open: any error means
    "no cooldown" so the cooldown subsystem can never wedge dispatch.
    """
    normalized_account = str(account_handle or "").strip().lower().lstrip("@")
    if not normalized_account:
        return None
    try:
        from trr_backend.socials.instagram.auth_cooldown import get_active_cooldown
    except Exception:  # noqa: BLE001
        return None
    try:
        cooldown = get_active_cooldown(str(platform or "instagram").strip().lower(), normalized_account)
    except Exception:  # noqa: BLE001
        return None
    return cooldown.to_metadata() if cooldown is not None else None


_META_AUTH_BLOCK_ERROR_TOKENS = (
    "auth",
    "checkpoint",
    "challenge",
    "cookie",
    "csrf",
    "forbidden",
    "login",
    "permission",
    "redirect_to_login",
    "session",
    "two_step",
    "unauthorized",
)


def _error_code_is_meta_auth_block(error_code: Any, *, error_message: Any = None) -> bool:
    token = f"{error_code or ''} {error_message or ''}".strip().lower()
    if not token:
        return False
    return any(part in token for part in _META_AUTH_BLOCK_ERROR_TOKENS) or token in {"401", "403"}


def _record_posts_auth_cooldown_if_applicable(
    *,
    platform: Any,
    stage: Any,
    job_type: Any = None,
    account_handle: Any,
    error_code: Any,
    error_message: Any = None,
    metadata: MutableMapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    if not _job_is_posts_auth_cooldown_scoped(platform=platform, stage=stage, job_type=job_type):
        return None
    if not _error_code_is_meta_auth_block(error_code, error_message=error_message):
        return None
    normalized_platform = _normalize_platform_name(platform)
    normalized_account = _normalize_account_handle(account_handle)
    if not normalized_platform or not normalized_account:
        return None
    try:
        from trr_backend.socials.instagram.auth_cooldown import record_auth_block

        cooldown = record_auth_block(normalized_platform, normalized_account, str(error_code or "auth_block"))
    except Exception:  # noqa: BLE001
        logger.debug(
            "Failed to record posts auth cooldown: platform=%s account=%s error_code=%s",
            normalized_platform,
            normalized_account,
            error_code,
            exc_info=True,
        )
        return None
    if cooldown is None:
        return None
    payload = cooldown.to_metadata()
    if metadata is not None:
        metadata["auth_cooldown"] = payload
        metadata["auth_cooldown_recorded"] = True
    return payload


def _clear_posts_auth_cooldown_after_success(
    *,
    platform: Any,
    stage: Any,
    job_type: Any = None,
    account_handle: Any,
    metadata: MutableMapping[str, Any] | None = None,
) -> None:
    if not _job_is_posts_auth_cooldown_scoped(platform=platform, stage=stage, job_type=job_type):
        return
    normalized_platform = _normalize_platform_name(platform)
    normalized_account = _normalize_account_handle(account_handle)
    if not normalized_platform or not normalized_account:
        return
    try:
        from trr_backend.socials.instagram.auth_cooldown import clear_cooldown

        cleared = clear_cooldown(normalized_platform, normalized_account)
    except Exception:  # noqa: BLE001
        logger.debug(
            "Failed to clear posts auth cooldown: platform=%s account=%s",
            normalized_platform,
            normalized_account,
            exc_info=True,
        )
        return
    if metadata is not None:
        metadata["auth_cooldown_cleared"] = bool(cleared)


@dataclass(slots=True, frozen=True)
class _SharedPostsEnqueueResult:
    status: Literal["queued", "deferred_by_cooldown", "failed"]
    job_id: str | None = None
    cooldown: dict[str, Any] | None = None
    error: str | None = None

    @property
    def queued(self) -> bool:
        return self.status == "queued" and bool(self.job_id)


def _coerce_shared_posts_enqueue_result(value: Any) -> _SharedPostsEnqueueResult:
    if isinstance(value, _SharedPostsEnqueueResult):
        return value
    if isinstance(value, Mapping):
        status = str(value.get("status") or "").strip().lower()
        if status in {"queued", "deferred_by_cooldown", "failed"}:
            return _SharedPostsEnqueueResult(
                status=cast(Literal["queued", "deferred_by_cooldown", "failed"], status),
                job_id=str(value.get("job_id") or "").strip() or None,
                cooldown=_metadata_dict(value.get("cooldown")) or None,
                error=str(value.get("error") or "").strip() or None,
            )
    job_id = str(value or "").strip()
    if job_id:
        return _SharedPostsEnqueueResult(status="queued", job_id=job_id)
    return _SharedPostsEnqueueResult(status="failed", error="enqueue_returned_empty_job_id")


def _enqueue_shared_posts_job(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    shared_account_source_id: Any,
    pipeline_ingest_mode: str,
    runner_count: int,
    expected_total_posts: int | None = None,
    runner_strategy: str | None = None,
    partition_strategy: str | None = None,
    required_worker_lane: str | None = None,
    required_execution_backend: str | None = None,
    allow_local_dev_inline_bypass: bool = False,
    frontier_auth_allowed: bool | None = None,
    frontier_auth_reason: str | None = None,
    frontier_transport: str | None = None,
    transport_preference: str | None = None,
    allow_public_transport_fallback: bool | None = None,
    selected_tasks: Sequence[Any] | None = None,
    effective_selected_tasks: Sequence[Any] | None = None,
    details_refresh_skip_detail_fetch: bool | None = None,
    details_refresh_force_detail_fetch: bool | None = None,
    details_refresh_worker_count: int | None = None,
    comments_worker_count: int | None = None,
    details_refresh_skip_media_followups: bool | None = None,
    tiktok_comments_in_posts_stage: bool = False,
    tiktok_direct_comment_api_override: bool = False,
    twitter_comments_in_posts_stage: bool = False,
    initiated_by: str | None = None,
    worker_id: str | None = None,
    priority: int = 101,
) -> _SharedPostsEnqueueResult:
    # A4 DISPATCH GUARD: do not spawn another posts partition job for an account
    # while a cross-process auth cooldown is active. The guard is at this single
    # spawn chokepoint so every caller is covered. Fails open (spawns) if the
    # cooldown subsystem is unavailable.
    cooldown = _active_posts_auth_cooldown(platform, account_handle)
    if cooldown is not None:
        logger.warning(
            "shared_posts_dispatch deferred by auth cooldown platform=%s account=%s blocker=%s until=%s",
            str(platform or "").strip().lower(),
            str(account_handle or "").strip().lower(),
            cooldown.get("blocker_kind"),
            cooldown.get("cooldown_until"),
        )
        return _SharedPostsEnqueueResult(status="deferred_by_cooldown", cooldown=cooldown)
    normalized_selected_tasks = _normalize_optional_social_account_catalog_backfill_selected_tasks(selected_tasks)
    normalized_effective_tasks = (
        _normalize_optional_social_account_catalog_backfill_selected_tasks(effective_selected_tasks)
        or normalized_selected_tasks
    )
    normalized_partition_strategy = str(partition_strategy or CATALOG_FULL_HISTORY_FRONTIER_STRATEGY).strip().lower()
    try:
        job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            config={
                "stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "shared_account_source_id": shared_account_source_id,
                "pipeline_ingest_mode": pipeline_ingest_mode,
                "partition_strategy": normalized_partition_strategy,
                "runner_strategy": str(runner_strategy or CATALOG_FULL_HISTORY_FRONTIER_STRATEGY).strip().lower(),
                "runner_count": max(
                    1,
                    _normalize_non_negative_int(runner_count) or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                ),
                "max_posts_per_target": 0,
                "expected_total_posts": _normalize_non_negative_int(expected_total_posts) or None,
                "required_worker_lane": str(required_worker_lane or "").strip().lower() or None,
                "required_execution_backend": str(required_execution_backend or "").strip().lower() or None,
                "allow_local_dev_inline_bypass": bool(allow_local_dev_inline_bypass),
                "frontier_auth_allowed": frontier_auth_allowed,
                "frontier_auth_reason": str(frontier_auth_reason or "").strip().lower() or None,
                "frontier_transport": str(frontier_transport or "").strip().lower() or None,
                "transport_preference": str(transport_preference or "").strip().lower() or None,
                "allow_public_transport_fallback": allow_public_transport_fallback,
                "selected_tasks": normalized_selected_tasks or None,
                "effective_selected_tasks": normalized_effective_tasks or None,
                "details_refresh_skip_detail_fetch": (
                    bool(details_refresh_skip_detail_fetch) if details_refresh_skip_detail_fetch is not None else None
                ),
                "details_refresh_force_detail_fetch": (
                    bool(details_refresh_force_detail_fetch) if details_refresh_force_detail_fetch is not None else None
                ),
                "details_refresh_skip_media_followups": (
                    bool(details_refresh_skip_media_followups)
                    if details_refresh_skip_media_followups is not None
                    else None
                ),
                "comments_worker_count": _normalize_non_negative_int(comments_worker_count) or None,
                "tiktok_comments_in_posts_stage": bool(tiktok_comments_in_posts_stage),
                "tiktok_direct_comment_api_override": bool(tiktok_direct_comment_api_override),
                "twitter_comments_in_posts_stage": bool(twitter_comments_in_posts_stage),
            },
            initiated_by=initiated_by,
            status="queued" if is_queue_enabled() else "pending",
            priority=priority,
            worker_id=worker_id,
            preclaim=bool(worker_id),
            max_attempts=(
                _shared_posts_frontier_max_attempts()
                if normalized_partition_strategy == CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
                else None
            ),
        )
    except Exception as exc:  # noqa: BLE001
        logger.exception(
            "shared_posts_dispatch enqueue failed platform=%s account=%s run_id=%s",
            str(platform or "").strip().lower(),
            str(account_handle or "").strip().lower(),
            run_id,
        )
        return _SharedPostsEnqueueResult(status="failed", error=str(exc) or exc.__class__.__name__)
    normalized_job_id = str(job_id or "").strip()
    if not normalized_job_id:
        return _SharedPostsEnqueueResult(status="failed", error="enqueue_returned_empty_job_id")
    return _SharedPostsEnqueueResult(status="queued", job_id=normalized_job_id)


def _count_recent_failures() -> int:
    row = (
        pg.fetch_one(
            f"""
        select count(*)::int as total
        from social.scrape_jobs j
        where j.status = any(%s::text[])
          and {_recent_failure_not_dismissed_sql("j")}
        """,
            [list(_RECENT_FAILURE_TERMINAL_STATUSES)],
        )
        or {}
    )
    return int(row.get("total") or 0)


def _count_visible_failed_runs() -> int:
    run_failure_not_dismissed_sql = _run_failure_not_dismissed_sql("r")
    row = (
        pg.fetch_one(
            f"""
        select count(*)::int as total
        from social.scrape_runs r
        where r.status = 'failed'
          and {run_failure_not_dismissed_sql}
        """
        )
        or {}
    )
    return int(row.get("total") or 0)


def _invalidate_queue_status_cache() -> None:
    from trr_backend.socials.control_plane.queue_status import invalidate_queue_status_cache

    invalidate_queue_status_cache()


def _reconcile_active_queue_runs(*, limit: int = 100) -> list[str]:
    if not _relation_exists("social.scrape_runs"):
        return []

    safe_limit = max(1, min(int(limit), 500))
    grace_seconds = _resolve_positive_int_env(
        "SOCIAL_QUEUE_STATUS_RECONCILE_GRACE_SECONDS",
        60,
        minimum=5,
    )
    cutoff = _now_utc() - timedelta(seconds=grace_seconds)
    candidate_rows = pg.fetch_all(
        """
        select
          id::text as id,
          created_at,
          started_at
        from social.scrape_runs
        where status = any(%s::text[])
        order by created_at desc
        limit %s
        """,
        [list(_RUN_PROGRESS_ACTIVE_JOB_STATUSES), safe_limit],
    )

    reconciled: list[str] = []
    for row in candidate_rows:
        run_id = str(row.get("id") or "").strip()
        if not run_id:
            continue
        activity_anchor = _coerce_dt(row.get("started_at") or row.get("created_at"))
        if activity_anchor is not None and activity_anchor > cutoff:
            continue
        _finalize_run_status(run_id, force_recompute=True)
        reconciled.append(run_id)
    return reconciled


def recover_dispatch_blocked_no_progress_jobs(*, limit: int = 100) -> list[dict[str, Any]]:
    from trr_backend.socials.control_plane.dispatch_runtime import (
        recover_dispatch_blocked_no_progress_jobs as impl,
    )

    return impl(limit=limit)


cast(Any, recover_dispatch_blocked_no_progress_jobs).__trr_delegates_to_control_plane__ = True


def recover_failed_instagram_comments_capacity_jobs(
    *,
    run_id: str | None = None,
    limit: int = 25,
) -> list[dict[str, Any]]:
    """Requeue retryable Instagram comments shards that failed before exhausting job attempts."""

    safe_limit = max(1, min(int(limit or 25), 250))
    try:
        normalized_run_id = str(UUID(str(run_id))) if str(run_id or "").strip() else None
    except (TypeError, ValueError):
        return []
    rows = pg.fetch_all(
        """
        with candidates as (
          select
            j.id,
            case
              when lower(coalesce(j.last_error_code, '')) = 'stale_modal_dispatch_unclaimed'
                or (
                  lower(coalesce(j.error_message, '')) like '%%modal dispatch lease expired%%'
                  and lower(coalesce(j.error_message, '')) like '%%before any worker claimed%%'
                )
                then 'stale_modal_dispatch_unclaimed'
              when lower(coalesce(j.last_error_code, '')) in (
                  'instagram_comments_transport_error',
                  'instagram_comments_warmup_transport_error',
                  'transport_error'
                )
                or lower(coalesce(j.last_error_class, '')) = 'sslerror'
                or lower(coalesce(j.last_error_class, '')) = 'closedresourceerror'
                or lower(coalesce(j.error_message, '')) like '%%wrong_version_number%%'
                or lower(coalesce(j.error_message, '')) like '%%wrong version number%%'
                or lower(coalesce(j.error_message, '')) like '%%[ssl]%%'
                or lower(coalesce(j.error_message, '')) like '%%ssl.c%%'
                or lower(coalesce(j.error_message, '')) like '%%record layer failure%%'
                or lower(coalesce(j.error_message, '')) like '%%ssl:%%'
                or lower(coalesce(j.error_message, '')) like '%%ssl connection%%'
                or lower(coalesce(j.error_message, '')) like '%%closed unexpectedly%%'
                or lower(coalesce(j.error_message, '')) like '%%client has been closed%%'
                or lower(coalesce(j.error_message, '')) like '%%connection has been closed%%'
                or lower(coalesce(j.error_message, '')) like '%%proxy error%%'
                or lower(coalesce(j.error_message, '')) like '%%net::err_connection_closed%%'
                or lower(coalesce(j.error_message, '')) like '%%net::err_connection_reset%%'
                or lower(coalesce(j.error_message, '')) like '%%connecterror%%'
                or lower(coalesce(j.error_message, '')) like '%%readerror%%'
                or lower(coalesce(j.error_message, '')) like '%%connection reset%%'
                or lower(coalesce(j.error_message, '')) like '%%server disconnected%%'
                then 'transport_error'
              when lower(coalesce(j.last_error_code, '')) = 'instagram_comments_public_retryable'
                then 'instagram_comments_public_retryable'
              else 'database_capacity'
            end as recovery_reason
          from social.scrape_jobs j
          where j.status = 'failed'
            and j.platform = 'instagram'
            and coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s
            and (%s::uuid is null or j.run_id = %s::uuid)
            and coalesce(j.attempt_count, 0) < coalesce(j.max_attempts, 1)
            and (
              (
                coalesce(j.items_found, 0) = 0
                and (
                  lower(coalesce(j.error_message, '')) like '%%emaxconnsession%%'
                  or lower(coalesce(j.error_message, '')) like '%%max clients reached%%'
                  or lower(coalesce(j.error_message, '')) like '%%pool exhausted%%'
                  or lower(coalesce(j.error_message, '')) like '%%database pool%%'
                )
              )
              or lower(coalesce(j.last_error_code, '')) = 'stale_modal_dispatch_unclaimed'
              or (
                lower(coalesce(j.error_message, '')) like '%%modal dispatch lease expired%%'
                and lower(coalesce(j.error_message, '')) like '%%before any worker claimed%%'
              )
              or lower(coalesce(j.last_error_code, '')) in (
                'instagram_comments_transport_error',
                'instagram_comments_warmup_transport_error',
                'transport_error'
              )
              or lower(coalesce(j.last_error_class, '')) = 'sslerror'
              or lower(coalesce(j.last_error_class, '')) = 'closedresourceerror'
              or lower(coalesce(j.error_message, '')) like '%%wrong_version_number%%'
              or lower(coalesce(j.error_message, '')) like '%%wrong version number%%'
              or lower(coalesce(j.error_message, '')) like '%%[ssl]%%'
              or lower(coalesce(j.error_message, '')) like '%%ssl.c%%'
              or lower(coalesce(j.error_message, '')) like '%%record layer failure%%'
              or lower(coalesce(j.error_message, '')) like '%%ssl:%%'
              or lower(coalesce(j.error_message, '')) like '%%ssl connection%%'
              or lower(coalesce(j.error_message, '')) like '%%closed unexpectedly%%'
              or lower(coalesce(j.error_message, '')) like '%%client has been closed%%'
              or lower(coalesce(j.error_message, '')) like '%%connection has been closed%%'
              or lower(coalesce(j.error_message, '')) like '%%proxy error%%'
              or lower(coalesce(j.error_message, '')) like '%%net::err_connection_closed%%'
              or lower(coalesce(j.error_message, '')) like '%%net::err_connection_reset%%'
              or lower(coalesce(j.error_message, '')) like '%%connecterror%%'
              or lower(coalesce(j.error_message, '')) like '%%readerror%%'
              or lower(coalesce(j.error_message, '')) like '%%connection reset%%'
              or lower(coalesce(j.error_message, '')) like '%%server disconnected%%'
              or lower(coalesce(j.last_error_code, '')) = 'instagram_comments_public_retryable'
            )
          order by coalesce(j.completed_at, j.created_at) asc
          limit %s
        )
        update social.scrape_jobs j
        set
          status = 'retrying',
          available_at = case
            when candidates.recovery_reason = 'instagram_comments_public_retryable'
              then now() + (
                greatest(60, least(900, 60 * power(2, greatest(0, coalesce(j.attempt_count, 0) - 1))))
                * interval '1 second'
              )
            else now()
          end,
          completed_at = null,
          error_message = null,
          last_error_code = null,
          last_error_class = null,
          metadata = coalesce(j.metadata, '{}'::jsonb)
            || jsonb_build_object(
              'capacity_recovery',
              jsonb_build_object(
                'reason', candidates.recovery_reason,
                'recovered_at', to_jsonb(now()),
                'source', 'recover_failed_instagram_comments_capacity_jobs'
              ),
              'retryable_failure_recovery',
              jsonb_build_object(
                'reason', candidates.recovery_reason,
                'recovered_at', to_jsonb(now()),
                'source', 'recover_failed_instagram_comments_capacity_jobs'
              ),
              'dispatch',
              coalesce(j.metadata->'dispatch', '{}'::jsonb)
                || jsonb_build_object(
                  'remote_invocation_id', null,
                  'remote_invocation_status', null,
                  'remote_invocation_checked_at', null,
                  'remote_task_id', null,
                  'remote_pending_since', null,
                  'remote_blocked_reason', null,
                  'lease_expires_at', null,
                  'last_dispatch_error', null,
                  'last_dispatch_error_code', null,
                  'last_dispatch_error_at', null,
                  'dispatch_attempt_count', 0,
                  'dispatch_blocked_failure_count', 0,
                  'dispatch_blocked_terminalized_at', null,
                  'stale_unclaimed_dispatch_exhausted', false
                ),
              'activity',
              coalesce(j.metadata->'activity', '{}'::jsonb)
                || jsonb_build_object(
                  'phase',
                  case
                    when candidates.recovery_reason = 'database_capacity' then 'capacity_recovered'
                    when candidates.recovery_reason = 'transport_error' then 'transport_recovered'
                    when candidates.recovery_reason = 'instagram_comments_public_retryable'
                      then 'public_retry_recovered'
                    else 'stale_dispatch_recovered'
                  end,
                  'last_progress_at',
                  to_jsonb(now())
                )
            )
        from candidates
        where j.id = candidates.id
        returning
          j.id::text as id,
          j.run_id::text as run_id,
          j.platform,
          j.status,
          candidates.recovery_reason
        """,
        [INSTAGRAM_COMMENTS_SCRAPLING_STAGE, normalized_run_id, normalized_run_id, safe_limit],
    )
    finalized_run_ids: set[str] = set()
    for row in rows:
        recovered_run_id = str(row.get("run_id") or "").strip()
        if recovered_run_id and recovered_run_id not in finalized_run_ids:
            _finalize_run_status(recovered_run_id, force_recompute=True)
            finalized_run_ids.add(recovered_run_id)
    return rows


def recover_failed_media_mirror_transient_jobs(
    *,
    run_id: str | None = None,
    limit: int = 25,
) -> list[dict[str, Any]]:
    """Requeue media mirror jobs that old workers misclassified as fatal."""

    safe_limit = max(1, min(int(limit or 25), 250))
    try:
        normalized_run_id = str(UUID(str(run_id))) if str(run_id or "").strip() else None
    except (TypeError, ValueError):
        return []
    rows = pg.fetch_all(
        """
        with candidates as (
          select
            j.id,
            case
              when lower(coalesce(j.error_message, '')) like '%%http_429%%' then 'http_429'
              when lower(coalesce(j.error_message, '')) like '%%http_500%%' then 'http_500'
              when lower(coalesce(j.error_message, '')) like '%%http_502%%' then 'http_502'
              when lower(coalesce(j.error_message, '')) like '%%http_503%%' then 'http_503'
              when lower(coalesce(j.error_message, '')) like '%%http_504%%' then 'http_504'
              when lower(coalesce(j.error_message, '')) like '%%request_timeout%%' then 'request_timeout'
              when lower(coalesce(j.error_message, '')) like '%%connection_error%%' then 'connection_error'
              when lower(coalesce(j.error_message, '')) like '%%request_error%%' then 'request_error'
              else 'transient_media_mirror'
            end as recovery_reason
          from social.scrape_jobs j
          where j.status = 'failed'
            and coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) in (%s, %s)
            and (%s::uuid is null or j.run_id = %s::uuid)
            and coalesce(j.attempt_count, 0) < coalesce(j.max_attempts, 1)
            and (
              lower(coalesce(j.last_error_code, '')) = 'transient_error'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:%%http_429%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:%%http_500%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:%%http_502%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:%%http_503%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:%%http_504%%'
              or lower(coalesce(j.error_message, '')) like '%%upload_failed:%%http_429%%'
              or lower(coalesce(j.error_message, '')) like '%%upload_failed:%%http_500%%'
              or lower(coalesce(j.error_message, '')) like '%%upload_failed:%%http_502%%'
              or lower(coalesce(j.error_message, '')) like '%%upload_failed:%%http_503%%'
              or lower(coalesce(j.error_message, '')) like '%%upload_failed:%%http_504%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:request_timeout%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:connection_error%%'
              or lower(coalesce(j.error_message, '')) like '%%download_failed:request_error%%'
            )
          order by coalesce(j.completed_at, j.created_at) asc
          limit %s
        )
        update social.scrape_jobs j
        set
          status = 'retrying',
          available_at = now(),
          completed_at = null,
          error_message = null,
          last_error_code = null,
          last_error_class = null,
          claimed_at = null,
          worker_id = null,
          metadata = coalesce(j.metadata, '{}'::jsonb)
            || jsonb_build_object(
              'retryable_failure_recovery',
              jsonb_build_object(
                'reason', candidates.recovery_reason,
                'recovered_at', to_jsonb(now()),
                'source', 'recover_failed_media_mirror_transient_jobs'
              ),
              'activity',
              coalesce(j.metadata->'activity', '{}'::jsonb)
                || jsonb_build_object(
                  'phase', 'media_mirror_transient_recovered',
                  'last_progress_at', to_jsonb(now())
                ),
              'dispatch',
              coalesce(j.metadata->'dispatch', '{}'::jsonb)
                || jsonb_build_object(
                  'remote_invocation_id', null,
                  'remote_invocation_status', null,
                  'remote_invocation_checked_at', null,
                  'remote_task_id', null,
                  'remote_pending_since', null,
                  'remote_blocked_reason', null,
                  'lease_expires_at', null,
                  'last_dispatch_error', null,
                  'last_dispatch_error_code', null,
                  'last_dispatch_error_at', null,
                  'dispatch_attempt_count', 0,
                  'dispatch_blocked_failure_count', 0,
                  'dispatch_blocked_terminalized_at', null,
                  'stale_unclaimed_dispatch_exhausted', false
                )
            )
        from candidates
        where j.id = candidates.id
        returning
          j.id::text as id,
          j.run_id::text as run_id,
          j.platform,
          j.status,
          candidates.recovery_reason
        """,
        [INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE, normalized_run_id, normalized_run_id, safe_limit],
    )
    finalized_run_ids: set[str] = set()
    for row in rows:
        recovered_run_id = str(row.get("run_id") or "").strip()
        if recovered_run_id and recovered_run_id not in finalized_run_ids:
            _finalize_run_status(recovered_run_id, force_recompute=True)
            finalized_run_ids.add(recovered_run_id)
    return rows


