def _instagram_posts_has_column(column: str, *, conn: Any | None = None) -> bool:
    """Best-effort schema guard for additive instagram_posts columns."""
    try:
        return _column_exists("social", "instagram_posts", column, conn=conn)
    except Exception:
        # Fall back to existing behavior if schema introspection is unavailable.
        return True


def _platform_posts_has_column(platform: str, column: str, *, conn: Any | None = None) -> bool:
    table = PLATFORM_POST_TABLES.get((platform or "").strip().lower())
    if not table:
        return False
    try:
        return _column_exists("social", table, column, conn=conn)
    except Exception:
        return True


def _platform_post_sort_anchor_expr(platform: str, posted_at_column: str, *, table_alias: str | None = None) -> str:
    normalized_platform = _normalize_platform_name(platform)
    prefix = f"{table_alias}." if table_alias else ""
    fallback_column = (
        "scraped_at" if _platform_posts_has_column(normalized_platform, "scraped_at") else posted_at_column
    )
    return f"coalesce({prefix}{posted_at_column}, {prefix}{fallback_column})"


def _platform_post_sort_tiebreaker_expr(platform: str, posted_at_column: str, *, table_alias: str | None = None) -> str:
    normalized_platform = _normalize_platform_name(platform)
    prefix = f"{table_alias}." if table_alias else ""
    if _platform_posts_has_column(normalized_platform, "scraped_at"):
        return f"{prefix}scraped_at"
    if _platform_posts_has_column(normalized_platform, "created_at"):
        return f"{prefix}created_at"
    return f"{prefix}{posted_at_column}"


def _platform_comments_has_column(platform: str, column: str, *, conn: Any | None = None) -> bool:
    table = PLATFORM_COMMENT_TABLES.get((platform or "").strip().lower())
    if not table:
        return False
    try:
        return _column_exists("social", table, column, conn=conn)
    except Exception:
        return True


def _tiktok_comments_has_column(column: str, *, conn: Any | None = None) -> bool:
    return _platform_comments_has_column("tiktok", column, conn=conn)


def _tiktok_raw_saves_expr(alias: str) -> str:
    return (
        f"case when coalesce({alias}.raw_data ->> 'saves', '') ~ '^-?[0-9]+$' "
        f"then greatest((({alias}.raw_data ->> 'saves')::int), 0) else 0 end"
    )


def _tiktok_saves_expr(alias: str) -> str:
    raw_expr = _tiktok_raw_saves_expr(alias)
    if _platform_posts_has_column("tiktok", "saves"):
        return f"coalesce({alias}.saves, {raw_expr}, 0)"
    return f"coalesce({raw_expr}, 0)"


def _tiktok_canonical_url_expr(alias: str) -> str:
    url_candidates = [f"nullif({alias}.raw_data ->> 'url', '')"]
    if _platform_posts_has_column("tiktok", "url"):
        url_candidates.append(f"nullif({alias}.url, '')")
    url_candidates.append(
        f"case when coalesce({alias}.video_id, '') <> '' "
        f"then 'https://www.tiktok.com/@_/video/' || {alias}.video_id else null end"
    )
    return f"coalesce({', '.join(url_candidates)})"


def _resolve_tiktok_canonical_url(*, source_id: str, row_json: Mapping[str, Any], account: str | None = None) -> str:
    raw_data = _metadata_dict(row_json.get("raw_data"))
    candidates = [
        raw_data.get("url"),
        row_json.get("url"),
        (f"https://www.tiktok.com/@_/video/{source_id}" if str(source_id or "").strip() else None),
    ]
    username = str(row_json.get("username") or account or "").strip().lstrip("@")
    if username and str(source_id or "").strip():
        candidates.append(f"https://www.tiktok.com/@{username}/video/{source_id}")
    for candidate in candidates:
        normalized = str(candidate or "").strip()
        if normalized:
            return normalized
    return ""


def _youtube_is_short_expr(alias: str) -> str:
    if _platform_posts_has_column("youtube", "is_short"):
        return f"coalesce({alias}.is_short, false)"
    return "false"


_HOSTED_MEDIA_HEALTHY_MIRROR_STATUSES = {"mirrored", "complete", "ready", "up_to_date"}
_HOSTED_MEDIA_BAD_REPAIR_REASON_TOKENS = (
    "asset_wrong_content_type",
    "wrong_content_type",
    "hosted_content",
    "legacy_hosted_url",
    "legacy_host",
    "bad_host",
    "cdn_host",
    "non_cdn",
    "page_like",
    "text/html",
    "html",
    "non_media",
)


def _hosted_media_sql_usable_condition(alias: str) -> str:
    status_expr = f"nullif(lower(coalesce(to_jsonb({alias}) ->> 'media_mirror_status', '')), '')"
    error_expr = f"lower(coalesce(to_jsonb({alias}) ->> 'media_mirror_error', ''))"
    bad_error_expr = " or ".join(f"{error_expr} like '%%{token}%%'" for token in _HOSTED_MEDIA_BAD_REPAIR_REASON_TOKENS)
    healthy_statuses = ", ".join(f"'{status}'" for status in sorted(_HOSTED_MEDIA_HEALTHY_MIRROR_STATUSES))
    return f"(not ({bad_error_expr}) and (({status_expr}) in ({healthy_statuses}) or ({status_expr}) is null))"


def _hosted_thumbnail_sql_expr(alias: str) -> str:
    return (
        f"(case when {_hosted_media_sql_usable_condition(alias)} "
        f"then nullif(to_jsonb({alias}) ->> 'hosted_thumbnail_url', '') end)"
    )


def _hosted_media_first_sql_expr(alias: str) -> str:
    return (
        f"(case when {_hosted_media_sql_usable_condition(alias)} "
        f"then nullif(to_jsonb({alias}) -> 'hosted_media_urls' ->> 0, '') end)"
    )


def _platform_thumbnail_expr(alias: str, platform: str) -> str:
    normalized = (platform or "").strip().lower()
    if normalized == "instagram":
        return _instagram_posts_thumbnail_expr(alias)
    if normalized == "tiktok":
        return (
            "coalesce("
            f"{_hosted_thumbnail_sql_expr(alias)}, "
            f"nullif({alias}.thumbnail_url, ''), "
            f"{_hosted_media_first_sql_expr(alias)}"
            ")"
        )
    if normalized == "youtube":
        return (
            "coalesce("
            f"{_hosted_thumbnail_sql_expr(alias)}, "
            f"{_hosted_media_first_sql_expr(alias)}, "
            f"nullif({alias}.thumbnail_url, '')"
            ")"
        )
    if normalized == "twitter":
        return (
            "coalesce("
            f"{_hosted_thumbnail_sql_expr(alias)}, "
            f"{_hosted_media_first_sql_expr(alias)}, "
            f"nullif({alias}.media_urls ->> 0, '')"
            ")"
        )
    if normalized in {"facebook", "threads"}:
        return (
            "coalesce("
            f"{_hosted_thumbnail_sql_expr(alias)}, "
            f"{_hosted_media_first_sql_expr(alias)}, "
            f"nullif({alias}.thumbnail_url, ''), "
            f"nullif({alias}.media_urls ->> 0, '')"
            ")"
        )
    return f"nullif({alias}.thumbnail_url, '')"


def _platform_hosted_media_expr(alias: str) -> str:
    return (
        f"(case when {_hosted_media_sql_usable_condition(alias)} "
        f"then coalesce(to_jsonb({alias}) -> 'hosted_media_urls', '[]'::jsonb) else '[]'::jsonb end)"
    )


def _instagram_metadata_confidence_rank(source: Any) -> int:
    normalized = str(source or "").strip().lower()
    if normalized in {"api_permalink", "permalink_api", "graphql_permalink"}:
        return 4
    if normalized in {"stored", "existing"}:
        return 3
    if normalized in {"ldjson", "open_graph", "og", "html_meta"}:
        return 2
    if normalized in {"heuristic", "fallback"}:
        return 1
    return 0


def _select_instagram_post_format(
    *,
    existing_post_format: Any,
    existing_metadata_source: Any,
    fallback_post_format: str,
    metadata_post_format: Any,
    metadata_source: Any,
) -> str:
    existing_format = str(existing_post_format or "").strip().lower()
    candidate_format = str(metadata_post_format or fallback_post_format or "").strip().lower() or "post"
    if not existing_format or existing_format == candidate_format:
        return candidate_format
    existing_rank = _instagram_metadata_confidence_rank(existing_metadata_source or "stored")
    candidate_rank = _instagram_metadata_confidence_rank(metadata_source)
    if existing_format == "reel" and candidate_format == "post" and candidate_rank < existing_rank:
        return existing_format
    if candidate_rank < existing_rank:
        return existing_format
    return candidate_format


def _social_account_catalog_lock_key(*, platform: str, account_handle: str, run_family: str) -> int:
    digest = hashlib.sha256(
        f"{CATALOG_START_LOCK_NAMESPACE}:{_normalize_platform_name(platform)}:{_normalize_account_handle(account_handle)}:{run_family}".encode()
    ).digest()
    return int.from_bytes(digest[:8], "big", signed=False)


@contextmanager
def _social_account_catalog_start_lock(*, platform: str, account_handle: str, run_family: str):
    lock_key = _social_account_catalog_lock_key(
        platform=platform,
        account_handle=account_handle,
        run_family=run_family,
    )
    with pg.db_connection(label="catalog-start-lock", pool_name="social_control") as conn:
        with pg.db_cursor(conn=conn, label="catalog-start-lock") as cur:
            locked_row = pg.fetch_one_with_cursor(cur, "select pg_try_advisory_lock(%s) as locked", [lock_key]) or {}
        locked = bool(locked_row.get("locked"))
        try:
            yield locked
        finally:
            if locked:
                try:
                    with pg.db_cursor(conn=conn, label="catalog-start-lock") as cur:
                        pg.fetch_one_with_cursor(cur, "select pg_advisory_unlock(%s) as unlocked", [lock_key])
                except Exception:  # noqa: BLE001
                    logger.debug(
                        "[catalog-start-lock] advisory unlock failed platform=%s account=%s run_family=%s",
                        platform,
                        account_handle,
                        run_family,
                        exc_info=True,
                    )


