def _platform_env_json_refresh_autosync_supported(platform: str) -> bool:
    return (_normalize_platform_name(platform) or "") in {"tiktok", "twitter"}


def _platform_auth_credentials(username_env: str, password_env: str) -> tuple[str | None, str | None]:
    username = (os.getenv(username_env) or "").strip() or None
    password = (os.getenv(password_env) or "").strip() or None
    return username, password


def _platform_cookie_auto_refresh_enabled(toggle_env: str, username_env: str, password_env: str) -> bool:
    raw = (os.getenv(toggle_env) or "").strip().lower()
    if raw:
        return raw not in {"0", "false", "off", "no"}
    username, password = _platform_auth_credentials(username_env, password_env)
    return bool(username and password)


def _load_cookie_map_from_json_or_file(
    *,
    label: str,
    raw_json_env_keys: tuple[str, ...],
    file_env_keys: tuple[str, ...],
    default_path: Path,
    required_cookie_names_any: tuple[str, ...] = (),
    required_cookie_names_all: tuple[str, ...] = (),
) -> dict[str, str]:
    candidates: list[dict[str, str]] = []
    raw_json = ""
    for key in raw_json_env_keys:
        raw_json = str(os.getenv(key) or "").strip()
        if raw_json:
            break
    if raw_json:
        try:
            parsed = json.loads(raw_json)
            cookies = _coerce_cookie_map(parsed)
            if cookies:
                candidates.append(cookies)
        except json.JSONDecodeError:
            cookies = _parse_cookie_header(raw_json)
            if cookies:
                candidates.append(cookies)
            else:
                logger.warning("Invalid %s cookies JSON from env", label)

    for path in _platform_cookie_file_candidates(default_path, *file_env_keys):
        if not path.is_file():
            continue
        try:
            with open(path) as f:
                parsed = json.load(f)
        except Exception as exc:
            logger.warning("Failed to load %s cookies from %s: %s", label, path, exc)
            continue
        cookies = _coerce_cookie_map(parsed)
        if cookies:
            candidates.append(cookies)
    return _select_preferred_cookie_candidate(
        candidates,
        required_cookie_names_any=required_cookie_names_any,
        required_cookie_names_all=required_cookie_names_all,
    )


def _validate_browser_cookie_health_cached(
    *,
    platform_label: str,
    cookies: dict[str, str],
    cache_entry: tuple[float, str, bool, str | None] | None,
    validation_url: str,
    cookie_domains: tuple[str, ...],
    required_cookie_names_any: tuple[str, ...] = (),
    required_cookie_names_all: tuple[str, ...] = (),
    invalid_url_markers: tuple[str, ...] = (),
    invalid_body_patterns: tuple[str, ...] = (),
) -> tuple[tuple[float, str, bool, str | None], bool, str | None]:
    fingerprint = _instagram_cookie_fingerprint(cookies)
    ttl_seconds = _resolve_positive_int_env(
        f"SOCIAL_{platform_label.upper()}_COOKIE_VALIDATION_TTL_SECONDS",
        SOCIAL_INSTAGRAM_COOKIE_VALIDATION_TTL_SECONDS_DEFAULT,
        minimum=30,
    )
    now = time_module.monotonic()
    if cache_entry and cache_entry[1] == fingerprint and (now - cache_entry[0]) < ttl_seconds:
        return cache_entry, cache_entry[2], cache_entry[3]

    from trr_backend.socials.browser_cookie_refresh import validate_browser_cookie_session

    is_valid, reason = validate_browser_cookie_session(
        cookies=cookies,
        validation_url=validation_url,
        cookie_domains=cookie_domains,
        required_cookie_names_any=required_cookie_names_any,
        required_cookie_names_all=required_cookie_names_all,
        invalid_url_markers=invalid_url_markers,
        invalid_body_patterns=invalid_body_patterns,
        timeout_seconds=45,
    )
    new_cache = (now, fingerprint, is_valid, reason)
    return new_cache, is_valid, reason


def _load_twitter_auth_from_sources() -> tuple[dict[str, str], str | None]:
    """
    Resolve Twitter auth for season ingest.

    Returns (cookies_dict, bearer_token | None).
    Resolution:
    1) SOCIAL_TWITTER_COOKIES_JSON / TWITTER_COOKIES_JSON (inline JSON)
    2) SOCIAL_TWITTER_COOKIES_FILE / TWITTER_COOKIES_FILE (path to JSON file)
    3) SOCIAL_TWITTER_BEARER_TOKEN / TWITTER_BEARER_TOKEN (bearer token)
    """

    cookie_candidates: list[dict[str, str]] = []
    raw_cookie_header = (os.getenv("SOCIAL_TWITTER_COOKIES_HEADER") or "").strip() or (
        os.getenv("TWITTER_COOKIES_HEADER") or ""
    ).strip()
    if raw_cookie_header:
        parsed_header = _parse_cookie_header(raw_cookie_header)
        if parsed_header:
            cookie_candidates.append(parsed_header)

    raw_json = (os.getenv("SOCIAL_TWITTER_COOKIES_JSON") or "").strip() or (
        os.getenv("TWITTER_COOKIES_JSON") or ""
    ).strip()
    if raw_json:
        try:
            parsed = json.loads(raw_json)
            cookies = _coerce_cookie_map(parsed)
            if cookies:
                cookie_candidates.append(cookies)
        except json.JSONDecodeError:
            # Allow passing a raw "Cookie:" header string in *_COOKIES_JSON vars.
            parsed_header = _parse_cookie_header(raw_json)
            if parsed_header:
                cookie_candidates.append(parsed_header)
            else:
                logger.warning("Invalid Twitter cookies JSON from env")

    for p in _platform_cookie_file_candidates(
        _default_twitter_cookie_file_path(),
        "SOCIAL_TWITTER_COOKIES_FILE",
        "TWITTER_COOKIES_FILE",
    ):
        if p.is_file():
            try:
                with open(p) as f:
                    parsed = json.load(f)
                cookies = _coerce_cookie_map(parsed)
                if cookies:
                    cookie_candidates.append(cookies)
            except Exception as exc:
                logger.warning("Failed to load Twitter cookies from %s: %s", p, exc)

    browser_cookies = _load_twitter_browser_cookies()
    if browser_cookies:
        cookie_candidates.append(browser_cookies)

    def _is_complete_cookie_candidate(candidate: dict[str, str]) -> bool:
        return bool(str(candidate.get("auth_token") or "").strip() and str(candidate.get("ct0") or "").strip())

    cookies: dict[str, str] = {}
    for candidate in cookie_candidates:
        if _is_complete_cookie_candidate(candidate):
            cookies = dict(candidate)
            break
    if not cookies:
        cookies = _select_preferred_cookie_candidate(
            cookie_candidates,
            required_cookie_names_any=("auth_token",),
            required_cookie_names_all=("ct0",),
        )

    bearer_token = (
        (os.getenv("SOCIAL_TWITTER_BEARER_TOKEN") or "").strip()
        or (os.getenv("TWITTER_BEARER_TOKEN") or "").strip()
        or None
    )

    return cookies, bearer_token


def _coerce_cookie_map(payload: Any) -> dict[str, str]:
    out: dict[str, str] = {}
    if isinstance(payload, dict):
        # Playwright/Chrome export shape: {"cookies": [{name, value, ...}, ...]}
        nested = payload.get("cookies")
        if isinstance(nested, list):
            return _coerce_cookie_map(nested)
        # Single cookie object shape.
        name = payload.get("name")
        value = payload.get("value")
        if name is not None and value is not None:
            out[str(name)] = str(value)
            return out
        # Flat cookie map shape.
        for key, value in payload.items():
            if value is None:
                continue
            key_str = str(key)
            if key_str.startswith("_"):
                continue
            if isinstance(value, (str, int, float, bool)):
                out[key_str] = str(value)
        return out
    if isinstance(payload, list):
        for item in payload:
            if not isinstance(item, dict):
                continue
            name = item.get("name")
            value = item.get("value")
            if name is None or value is None:
                continue
            out[str(name)] = str(value)
    return out


def _parse_cookie_header(raw: str) -> dict[str, str]:
    cookies: dict[str, str] = {}
    value = str(raw or "").strip()
    if not value:
        return cookies
    if value.lower().startswith("cookie:"):
        value = value.split(":", 1)[1].strip()
    for token in value.split(";"):
        pair = token.strip()
        if not pair or "=" not in pair:
            continue
        key, val = pair.split("=", 1)
        key = key.strip()
        if not key or key.startswith("_"):
            continue
        cookies[key] = val.strip()
    return cookies


def _load_twitter_browser_cookies() -> dict[str, str]:
    """
    Best-effort local browser cookie fallback for X/Twitter auth.

    Disabled unless SOCIAL_TWITTER_BROWSER_COOKIE_FALLBACK is truthy.
    """
    if not _env_truthy("SOCIAL_TWITTER_BROWSER_COOKIE_FALLBACK", default=False):
        return {}
    try:
        import browser_cookie3  # type: ignore[import-not-found]
    except Exception:
        return {}

    browser = (os.getenv("SOCIAL_TWITTER_BROWSER") or "auto").strip().lower()
    domains = [
        token.strip().lower()
        for token in (os.getenv("SOCIAL_TWITTER_COOKIE_DOMAINS") or "x.com,twitter.com").split(",")
        if token.strip()
    ]
    preferred_names = {
        token.strip()
        for token in (os.getenv("SOCIAL_TWITTER_COOKIE_NAMES") or "auth_token,ct0,twid").split(",")
        if token.strip()
    }

    browser_loader_candidates: list[Any] = []
    browser_order = ["chrome", "chromium", "brave", "edge", "opera", "vivaldi", "firefox", "safari"]
    if browser != "auto":
        browser_order = [browser]
    for browser_name in browser_order:
        browser_loader_candidates.append(getattr(browser_cookie3, browser_name, None))
    loaders = [loader for loader in browser_loader_candidates if callable(loader)]

    cookies: dict[str, str] = {}
    for loader in loaders:
        for domain in domains:
            try:
                jar = loader(domain_name=domain)
            except TypeError:
                try:
                    jar = loader()
                except Exception:
                    continue
            except Exception:
                continue
            for cookie in cast(Iterable[Any], jar):
                name = str(getattr(cookie, "name", "") or "")
                value = str(getattr(cookie, "value", "") or "")
                cookie_domain = str(getattr(cookie, "domain", "") or "").lower()
                if not name or not value:
                    continue
                if preferred_names and name not in preferred_names:
                    continue
                if domain and not cookie_domain.endswith(domain):
                    continue
                cookies[name] = value
            if cookies.get("auth_token") and cookies.get("ct0"):
                return cookies
    return cookies


def _load_twikit_credentials(twitter_cookies: Mapping[str, Any] | None = None) -> dict[str, str] | None:
    """
    Load twikit auth from env vars, cookie file, or Twitter cookie sources.

    Resolution order (first match wins):
    1) TWIKIT_COOKIES_JSON – inline JSON cookie payload
    2) TWIKIT_COOKIES_FILE – JSON file with auth_token + ct0 keys
    3) TWIKIT_AUTH_TOKEN + TWIKIT_CT0 – inline cookie values
    4) TWIKIT_USERNAME + TWIKIT_PASSWORD (+ TWIKIT_EMAIL) – login creds
    5) Twitter cookie sources (preloaded cookies/header/JSON/file)
    6) Browser cookie fallback
    """

    def _extract_auth_ct0(payload: Any) -> tuple[str | None, str | None]:
        auth_token: str | None = None
        ct0: str | None = None
        if isinstance(payload, dict):
            if payload.get("auth_token") and payload.get("ct0"):
                return str(payload.get("auth_token")), str(payload.get("ct0"))
            nested = payload.get("cookies")
            if isinstance(nested, list):
                return _extract_auth_ct0(nested)
            name = payload.get("name")
            value = payload.get("value")
            if name == "auth_token" and value is not None:
                auth_token = str(value)
            if name == "ct0" and value is not None:
                ct0 = str(value)
            return auth_token, ct0
        if isinstance(payload, list):
            for item in payload:
                if not isinstance(item, dict):
                    continue
                name = item.get("name")
                value = item.get("value")
                if name == "auth_token" and value is not None:
                    auth_token = str(value)
                elif name == "ct0" and value is not None:
                    ct0 = str(value)
            return auth_token, ct0
        return None, None

    def _from_cookie_map(cookies: Mapping[str, Any] | None) -> dict[str, str] | None:
        if not cookies:
            return None
        auth_token = str(cookies.get("auth_token") or "").strip()
        ct0 = str(cookies.get("ct0") or "").strip()
        if auth_token and ct0:
            return {"auth_token": auth_token, "ct0": ct0}
        return None

    # 1) TWIKIT_COOKIES_JSON
    raw_cookie_json = (os.getenv("TWIKIT_COOKIES_JSON") or "").strip()
    if raw_cookie_json:
        try:
            parsed = json.loads(raw_cookie_json)
            auth_token, ct0 = _extract_auth_ct0(parsed)
            if auth_token and ct0:
                return {"auth_token": auth_token, "ct0": ct0}
        except Exception:
            logger.warning("Invalid TWIKIT_COOKIES_JSON payload; expected JSON cookie object/list")

    # 2) TWIKIT_COOKIES_FILE
    cookie_file = (os.getenv("TWIKIT_COOKIES_FILE") or "").strip()
    if cookie_file:
        p = Path(cookie_file).expanduser()
        if p.is_file():
            try:
                with open(p) as f:
                    parsed = json.load(f)
                auth_token, ct0 = _extract_auth_ct0(parsed)
                if auth_token and ct0:
                    return {"auth_token": auth_token, "ct0": ct0}
            except Exception as exc:
                logger.warning("Failed to load twikit cookies from %s: %s", p, exc)
        else:
            logger.debug("TWIKIT_COOKIES_FILE does not exist: %s", p)

    # 3) Inline TWIKIT cookie env vars
    auth_token = (os.getenv("TWIKIT_AUTH_TOKEN") or "").strip()
    ct0 = (os.getenv("TWIKIT_CT0") or "").strip()
    if auth_token and ct0:
        return {"auth_token": auth_token, "ct0": ct0}

    # 4) TWIKIT login credentials
    username = (os.getenv("TWIKIT_USERNAME") or "").strip()
    password = (os.getenv("TWIKIT_PASSWORD") or "").strip()
    email = (os.getenv("TWIKIT_EMAIL") or "").strip()
    if username and password:
        return {"username": username, "email": email or username, "password": password}

    # 5a) Preloaded Twitter cookies from caller.
    from_preloaded = _from_cookie_map(twitter_cookies)
    if from_preloaded:
        return from_preloaded

    # 5b) Twitter cookie header env vars.
    raw_cookie_header = (os.getenv("SOCIAL_TWITTER_COOKIES_HEADER") or "").strip() or (
        os.getenv("TWITTER_COOKIES_HEADER") or ""
    ).strip()
    if raw_cookie_header:
        parsed = _parse_cookie_header(raw_cookie_header)
        from_header = _from_cookie_map(parsed)
        if from_header:
            return from_header

    # 5c) Twitter JSON cookie env vars.
    raw_twitter_cookie_json = (os.getenv("SOCIAL_TWITTER_COOKIES_JSON") or "").strip() or (
        os.getenv("TWITTER_COOKIES_JSON") or ""
    ).strip()
    if raw_twitter_cookie_json:
        try:
            parsed = json.loads(raw_twitter_cookie_json)
            from_twitter_json = _from_cookie_map(_coerce_cookie_map(parsed))
            if from_twitter_json:
                return from_twitter_json
        except json.JSONDecodeError:
            parsed_header = _parse_cookie_header(raw_twitter_cookie_json)
            from_twitter_header = _from_cookie_map(parsed_header)
            if from_twitter_header:
                return from_twitter_header

    # 5d) Twitter cookie file env vars.
    twitter_cookie_file = (os.getenv("SOCIAL_TWITTER_COOKIES_FILE") or "").strip() or (
        os.getenv("TWITTER_COOKIES_FILE") or ""
    ).strip()
    if twitter_cookie_file:
        p = Path(twitter_cookie_file).expanduser()
        if p.is_file():
            try:
                with open(p) as f:
                    parsed = json.load(f)
                from_twitter_file = _from_cookie_map(_coerce_cookie_map(parsed))
                if from_twitter_file:
                    return from_twitter_file
            except Exception as exc:
                logger.debug("Failed to derive twikit credentials from Twitter cookie file %s: %s", p, exc)

    # 6) Browser cookie fallback.
    browser_cookies = _load_twitter_browser_cookies()
    from_browser = _from_cookie_map(browser_cookies)
    if from_browser:
        return from_browser

    return None


def _default_twitter_cookie_file_path() -> Path:
    return _default_platform_cookie_file_path("twitter")


def _validate_twitter_cookie_health(cookies: dict[str, str]) -> tuple[bool, str | None]:
    global _twitter_cookie_validation_cache
    _twitter_cookie_validation_cache, is_valid, reason = _validate_browser_cookie_health_cached(
        platform_label="twitter",
        cookies=cookies,
        cache_entry=_twitter_cookie_validation_cache,
        validation_url="https://x.com/home",
        cookie_domains=(".x.com", "x.com", ".twitter.com", "twitter.com"),
        required_cookie_names_any=("auth_token",),
        required_cookie_names_all=("ct0",),
        invalid_url_markers=("/i/flow/login", "/login"),
        invalid_body_patterns=(r"Something went wrong", r"Log in to X"),
    )
    return is_valid, reason


def _store_refreshed_twitter_cookies(cookies: Mapping[str, Any]) -> dict[str, Any]:
    global _twitter_cookie_validation_cache, _twitter_cookie_runtime_override
    refreshed = {str(key): str(value) for key, value in cookies.items() if str(key).strip() and value is not None}
    if not refreshed:
        return {"synced": False, "reason": "empty_cookie_payload"}
    _twitter_cookie_runtime_override = dict(refreshed)
    _twitter_cookie_validation_cache = None
    return _sync_twitter_cookie_json_env_source(refreshed)


def _refresh_twitter_cookies(stale_reason: str | None = None) -> dict[str, str]:
    username, password = _platform_auth_credentials("SOCIAL_AUTH_X_USERNAME", "SOCIAL_AUTH_X_PASSWORD")
    if not username or not password:
        return {}
    from trr_backend.socials.twitter.cookie_refresh import refresh_twitter_cookies

    try:
        refreshed = refresh_twitter_cookies(
            username=username,
            password=password,
            cookie_file=_platform_cookie_refresh_target_path(
                _default_twitter_cookie_file_path(),
                "SOCIAL_TWITTER_COOKIES_FILE",
                "TWITTER_COOKIES_FILE",
            ),
            headless=(os.getenv("SOCIAL_TWITTER_COOKIE_REFRESH_HEADLESS") or "true").strip().lower()
            not in {"0", "false", "off", "no"},
            timeout_seconds=_resolve_positive_int_env(
                "SOCIAL_TWITTER_COOKIE_REFRESH_TIMEOUT_SECONDS",
                SOCIAL_INSTAGRAM_COOKIE_REFRESH_TIMEOUT_SECONDS_DEFAULT,
                minimum=30,
            ),
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning("Twitter cookie refresh failed%s: %s", f" ({stale_reason})" if stale_reason else "", exc)
        return {}
    if refreshed:
        sync_result = _store_refreshed_twitter_cookies(refreshed)
        if sync_result.get("error"):
            logger.warning("Twitter cookie refresh could not sync env JSON source: %s", sync_result.get("error"))
    return refreshed


def _ensure_twitter_cookies_fresh(cookies: dict[str, str]) -> dict[str, str]:
    global _twitter_cookie_runtime_override
    if _twitter_cookie_runtime_override:
        return dict(_twitter_cookie_runtime_override)
    if not _platform_cookie_auto_refresh_enabled(
        "SOCIAL_TWITTER_COOKIE_AUTO_REFRESH",
        "SOCIAL_AUTH_X_USERNAME",
        "SOCIAL_AUTH_X_PASSWORD",
    ):
        return cookies
    is_valid, reason = _validate_twitter_cookie_health(cookies)
    if is_valid:
        return cookies
    with _twitter_cookie_refresh_lock:
        latest, _ = _load_twitter_auth_from_sources()
        latest = _twitter_cookie_runtime_override or latest
        latest_valid, _ = _validate_twitter_cookie_health(dict(latest))
        if latest_valid:
            _twitter_cookie_runtime_override = dict(latest)
            return dict(latest)
        refreshed = _refresh_twitter_cookies(reason)
        if refreshed:
            refreshed_valid, refreshed_reason = _validate_twitter_cookie_health(refreshed)
            if refreshed_valid:
                return refreshed
            logger.warning("Twitter cookies refreshed but validation still failed (%s)", refreshed_reason or "unknown")
        return cookies


def _load_twitter_auth() -> tuple[dict[str, str], str | None]:
    cookies, bearer_token = _load_twitter_auth_from_sources()
    return _ensure_twitter_cookies_fresh(cookies), bearer_token


