def _default_platform_accounts(platform: str) -> list[str]:
    """Return default accounts for a platform when none are configured."""
    return list(_DEFAULT_PLATFORM_ACCOUNTS.get(platform, []))


def _season_identity(season_id: str) -> dict[str, Any]:
    season = pg.fetch_one(
        """
        select
          s.id::text as season_id,
          s.show_id::text as show_id,
          s.season_number,
          sh.name as show_name
        from core.seasons s
        join core.shows sh on sh.id = s.show_id
        where s.id = %s
        """,
        [season_id],
    )
    if not season:
        raise ValueError(f"Season {season_id} not found")
    return season


@lru_cache(maxsize=256)
def _get_targets_cached(season_id: str, source_scope: str) -> dict[str, Any]:
    rows = pg.fetch_all(
        """
        select
          t.season_id::text as season_id,
          t.show_id::text as show_id,
          s.season_number,
          sh.name as show_name,
          t.platform,
          t.source_scope,
          t.timezone,
          t.accounts,
          t.hashtags,
          t.keywords,
          t.is_active,
          t.config,
          t.updated_by,
          t.updated_at,
          t.created_at
        from social.season_targets t
        join core.seasons s on s.id = t.season_id
        join core.shows sh on sh.id = t.show_id
        where t.season_id = %s
          and t.source_scope = %s
        order by t.platform asc
        """,
        [season_id, source_scope],
    )
    using_defaults = False
    if rows:
        season_number = int(rows[0].get("season_number") or 0)
        show_name = rows[0].get("show_name")
        enforce_rhoslc_floor = _source_scope_is_network_family(source_scope) and _show_name_is_rhoslc(show_name)
        targets: list[dict[str, Any]] = []
        for row in rows:
            target = {key: value for key, value in row.items() if key not in {"season_number", "show_name"}}
            platform = _normalize_platform_name(target.get("platform"))
            normalized_accounts = _normalize_unique_terms(
                [
                    normalized
                    for normalized in (_normalize_account_handle(item) for item in (target.get("accounts") or []))
                    if normalized
                ]
            )
            normalized_hashtags = _normalize_terms(target.get("hashtags"), strip_prefix="#")
            if enforce_rhoslc_floor:
                if platform == "instagram":
                    normalized_accounts = _normalize_unique_terms([*normalized_accounts, "bravotv", "bravowwhl"])
                normalized_hashtags = _ensure_rhoslc_platform_hashtags(
                    SeasonContext(
                        season_id=str(target.get("season_id") or season_id),
                        show_id=str(target.get("show_id") or ""),
                        show_name=str(show_name or ""),
                        show_slug=None,
                        season_number=season_number,
                        anchor_date=cast(date, None),
                    ),
                    normalized_hashtags,
                )
            normalized_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=normalized_accounts,
            )
            target["accounts"] = normalized_accounts
            target["hashtags"] = normalized_hashtags
            targets.append(target)
        return {
            "season_id": str(rows[0].get("season_id") or season_id),
            "show_id": str(rows[0].get("show_id") or ""),
            "season_number": season_number,
            "show_name": show_name,
            "source_scope": source_scope,
            "targets": targets,
            "using_defaults": False,
        }

    context = get_season_context(season_id)
    if not rows:
        rows = _default_targets(context, source_scope=source_scope)
        using_defaults = len(rows) > 0

    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "show_name": context.show_name,
        "source_scope": source_scope,
        "targets": rows,
        "using_defaults": using_defaults,
    }


def get_targets(season_id: str, *, source_scope: str = "network") -> dict[str, Any]:
    source_scope = _normalize_source_scope_input(source_scope)
    return copy.deepcopy(_get_targets_cached(season_id, source_scope))


@lru_cache(maxsize=64)
def _list_matchable_seasons_cached(source_scope: str, platform: str) -> tuple[dict[str, Any], ...]:
    rows = pg.fetch_all(
        """
        select
          s.id::text as season_id,
          s.show_id::text as show_id,
          s.season_number,
          s.air_date,
          sh.name as show_name,
          lower(
            trim(
              both '-'
              from regexp_replace(
                regexp_replace(coalesce(sh.name, ''), '&', ' and ', 'gi'),
                '[^a-z0-9]+',
                '-',
                'gi'
              )
            )
          ) as show_slug
        from core.seasons s
        join core.shows sh on sh.id = s.show_id
        order by coalesce(s.air_date, current_date) desc, s.season_number desc
        """
    )
    candidates: list[dict[str, Any]] = []
    normalized_platform = _normalize_platform_name(platform)
    for row in rows:
        season_id = str(row.get("season_id") or "").strip()
        if not season_id:
            continue
        try:
            context = get_season_context(season_id)
        except ValueError:
            continue
        targets_payload = get_targets(season_id, source_scope=source_scope)
        target_rule = None
        for target in targets_payload.get("targets", []):
            if not target.get("is_active", True):
                continue
            if _normalize_platform_name(target.get("platform")) != normalized_platform:
                continue
            target_rule = dict(target)
            break
        if not target_rule:
            continue
        candidates.append(
            {
                "context": context,
                "platform": normalized_platform,
                "accounts": [
                    normalized
                    for normalized in (_normalize_account_handle(item) for item in (target_rule.get("accounts") or []))
                    if normalized
                ],
                "hashtags": _normalize_terms(target_rule.get("hashtags"), strip_prefix="#"),
                "keywords": _normalize_terms(target_rule.get("keywords")),
            }
        )
    return tuple(candidates)


def _list_matchable_seasons(*, source_scope: str, platform: str) -> list[dict[str, Any]]:
    return cast(
        list[dict[str, Any]],
        copy.deepcopy(
            _list_matchable_seasons_cached(
                str(source_scope or "").strip().lower(),
                _normalize_platform_name(platform),
            )
        ),
    )


def _invalidate_context_and_target_caches() -> None:
    _get_season_context_cached.cache_clear()
    _get_targets_cached.cache_clear()
    _list_matchable_seasons_cached.cache_clear()


def _normalize_account_handle(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""

    candidate = raw
    if "://" in raw or raw.lower().startswith("www."):
        url_value = raw if "://" in raw else f"https://{raw}"
        parsed = urlparse(url_value)
        path_parts = [segment for segment in str(parsed.path or "").split("/") if segment]
        if path_parts:
            candidate = path_parts[0]
        else:
            candidate = str(parsed.netloc or "")

    candidate = candidate.strip().lstrip("@")
    candidate = candidate.split("?")[0].split("#")[0].split("/")[0].strip().lower()
    if not candidate:
        return ""
    if not GENERIC_ACCOUNT_HANDLE_RE.fullmatch(candidate):
        return ""
    return candidate


def _shared_account_handle_from_source_id(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    parts = [segment.strip() for segment in raw.split(":") if str(segment).strip()]
    if not parts:
        return ""
    return _normalize_account_handle(parts[-1])


def _resolve_shared_account_handle(job: Mapping[str, Any], config: Mapping[str, Any]) -> str:
    metadata = _metadata_dict(job.get("metadata"))
    for candidate in (
        config.get("account"),
        metadata.get("account"),
        config.get("account_handle"),
        metadata.get("account_handle"),
        config.get("source_account"),
        metadata.get("source_account"),
    ):
        normalized = _normalize_account_handle(candidate)
        if normalized:
            return normalized
        fallback = str(candidate or "").strip().lower().lstrip("@")
        if fallback:
            return fallback
    for candidate in (
        config.get("shared_account_source_id"),
        metadata.get("shared_account_source_id"),
        job.get("shared_account_source_id"),
    ):
        normalized = _shared_account_handle_from_source_id(candidate)
        if normalized:
            return normalized
    return ""


def _is_valid_instagram_account_handle(value: str) -> bool:
    normalized = str(value or "").strip().lower().lstrip("@")
    if not normalized:
        return False
    return bool(INSTAGRAM_ACCOUNT_HANDLE_RE.fullmatch(normalized))


def _normalize_terms(values: list[Any] | None, *, strip_prefix: str | None = None) -> list[str]:
    if not values:
        return []
    normalized: list[str] = []
    for item in values:
        value = str(item or "").strip()
        if not value:
            continue
        if strip_prefix:
            value = value.lstrip(strip_prefix)
        if value:
            normalized.append(value)
    return _normalize_unique_terms(normalized)


def _extract_youtube_handle_from_value(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    match = YOUTUBE_HANDLE_URL_RE.search(raw)
    if match:
        return _normalize_account_handle(match.group(1))
    if raw.startswith("@"):
        return _normalize_account_handle(raw)
    if re.fullmatch(r"[A-Za-z0-9._-]+", raw):
        return _normalize_account_handle(raw)
    return ""


def _youtube_handles_match(expected_handle: str, candidate_handle: str) -> bool:
    expected = _normalize_account_handle(expected_handle)
    candidate = _normalize_account_handle(candidate_handle)
    if not expected or not candidate:
        return False
    if expected == candidate:
        return True
    if expected == f"{candidate}tv" or candidate == f"{expected}tv":
        return True
    if expected.startswith(candidate) or candidate.startswith(expected):
        return True
    return False


def _youtube_video_matches_owner_identity(
    video: Any,
    *,
    expected_handle: str,
    expected_channel_id: str | None,
) -> bool:
    normalized_expected_handle = _normalize_account_handle(expected_handle)
    normalized_expected_channel_id = str(expected_channel_id or "").strip()

    video_channel_id = str(getattr(video, "channel_id", "") or "").strip()
    if normalized_expected_channel_id and video_channel_id:
        return video_channel_id == normalized_expected_channel_id

    if not normalized_expected_handle:
        return True

    candidate_values = [
        getattr(video, "channel_title", None),
        getattr(video, "url", None),
    ]
    raw_data = getattr(video, "raw_data", None)
    if isinstance(raw_data, dict):
        candidate_values.extend(
            [
                raw_data.get("uploader_id"),
                raw_data.get("channel"),
                raw_data.get("uploader"),
                raw_data.get("channel_url"),
                raw_data.get("uploader_url"),
                raw_data.get("webpage_url"),
            ]
        )
    owner_candidates = {
        handle for handle in (_extract_youtube_handle_from_value(value) for value in candidate_values) if handle
    }
    if owner_candidates:
        return any(_youtube_handles_match(normalized_expected_handle, handle) for handle in owner_candidates)
    return True


def _target_accounts_by_platform(
    season_id: str,
    *,
    source_scope: str,
    context: SeasonContext | None = None,
) -> dict[str, set[str]]:
    rows = pg.fetch_all(
        """
        select platform, accounts, is_active
        from social.season_targets
        where season_id = %s
          and source_scope = %s
        """,
        [season_id, source_scope],
    )

    target_rows: list[dict[str, Any]]
    if rows:
        target_rows = list(rows)
        present_platforms = {
            str(row.get("platform") or "").strip().lower()
            for row in target_rows
            if str(row.get("platform") or "").strip()
        }
        resolved_context = context
        if _source_scope_is_network_family(source_scope):
            if resolved_context is None:
                resolved_context = get_season_context(season_id)
            for default_target in _default_targets(resolved_context, source_scope=source_scope):
                platform = str(default_target.get("platform") or "").strip().lower()
                if not platform or platform in present_platforms:
                    continue
                target_rows.append(default_target)
                present_platforms.add(platform)
    else:
        resolved_context = context or get_season_context(season_id)
        target_rows = _default_targets(resolved_context, source_scope=source_scope)

    accounts_by_platform: dict[str, set[str]] = {platform: set() for platform in SUPPORTED_PLATFORMS}

    for target in target_rows:
        if not bool(target.get("is_active", True)):
            continue
        platform = str(target.get("platform") or "").strip().lower()
        if platform not in accounts_by_platform:
            continue
        for account in target.get("accounts") or []:
            normalized = _normalize_account_handle(account)
            if normalized:
                accounts_by_platform[platform].add(normalized)

    if _source_scope_is_network_family(source_scope):
        for platform, required_accounts in _BRAVO_CORE_PLATFORM_ACCOUNTS.items():
            accounts_by_platform[platform].update(required_accounts)

    if _source_scope_is_network_family(source_scope) and _show_is_rhoslc(resolved_context):
        accounts_by_platform["instagram"].update({"bravotv", "bravowwhl"})
        accounts_by_platform["twitter"].update({"bravotv", "bravowwhl"})

    return accounts_by_platform


def put_targets(
    season_id: str,
    *,
    source_scope: str,
    targets: list[dict[str, Any]],
    updated_by: str | None,
) -> dict[str, Any]:
    context = get_season_context(season_id)

    source_scope = _normalize_source_scope_input(source_scope)

    upserted: list[dict[str, Any]] = []
    for target in targets:
        platform = str(target.get("platform") or "").strip().lower()
        if platform not in {"instagram", "tiktok", "twitter", "youtube", "facebook", "threads", "reddit"}:
            raise ValueError(f"Unsupported platform: {platform}")

        accounts = _normalize_unique_terms(
            [
                normalized
                for normalized in (_normalize_account_handle(item) for item in (target.get("accounts") or []))
                if normalized
            ]
        )
        accounts = _ensure_bravo_core_platform_accounts(
            source_scope=source_scope,
            platform=platform,
            accounts=accounts,
        )
        hashtags = _normalize_terms(target.get("hashtags"), strip_prefix="#")
        keywords = _normalize_terms(target.get("keywords"))
        hashtags = _ensure_rhoslc_platform_hashtags(context, hashtags)
        if platform == "instagram":
            accounts = _ensure_rhoslc_instagram_accounts(context, accounts)
        elif platform == "twitter":
            accounts = _ensure_rhoslc_twitter_accounts(context, accounts)
        timezone = str(target.get("timezone") or "America/New_York")
        is_active = bool(target.get("is_active", True))
        config = target.get("config") or {}

        row = pg.fetch_one(
            """
            insert into social.season_targets (
              season_id,
              show_id,
              platform,
              source_scope,
              timezone,
              accounts,
              hashtags,
              keywords,
              is_active,
              config,
              updated_by,
              updated_at
            )
            values (
              %s,
              %s,
              %s,
              %s,
              %s,
              %s::jsonb,
              %s::jsonb,
              %s::jsonb,
              %s,
              %s::jsonb,
              %s,
              now()
            )
            on conflict (season_id, platform, source_scope)
            do update set
              show_id = excluded.show_id,
              timezone = excluded.timezone,
              accounts = excluded.accounts,
              hashtags = excluded.hashtags,
              keywords = excluded.keywords,
              is_active = excluded.is_active,
              config = excluded.config,
              updated_by = excluded.updated_by,
              updated_at = now()
            returning
              season_id::text,
              show_id::text,
              platform,
              source_scope,
              timezone,
              accounts,
              hashtags,
              keywords,
              is_active,
              config,
              updated_by,
              updated_at,
              created_at
            """,
            [
                season_id,
                context.show_id,
                platform,
                source_scope,
                timezone,
                json.dumps(accounts),
                json.dumps(hashtags),
                json.dumps(keywords),
                is_active,
                json.dumps(config),
                updated_by,
            ],
        )
        if row:
            upserted.append(row)

    _invalidate_context_and_target_caches()
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "show_name": context.show_name,
        "source_scope": source_scope,
        "targets": sorted(upserted, key=lambda item: str(item.get("platform") or "")),
    }


# ---------------------------------------------------------------------------
# Shared account ingest helpers


def _resolve_pipeline_ingest_mode(value: str | None = None) -> str:
    explicit = str(value or "").strip().lower()
    if explicit in SUPPORTED_PIPELINE_INGEST_MODES:
        return explicit
    configured_default = (
        str(os.getenv("SOCIAL_PIPELINE_DEFAULT_INGEST_MODE") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    )
    if configured_default in SUPPORTED_PIPELINE_INGEST_MODES:
        return configured_default
    return SHARED_ACCOUNT_ASYNC_INGEST_MODE


def _shared_source_defaults(*, source_scope: str = "network") -> list[dict[str, Any]]:
    source_scope = _normalize_source_scope_input(source_scope)
    rows: list[dict[str, Any]] = []
    if source_scope != "network":
        return rows
    for platform in sorted(SUPPORTED_PLATFORMS):
        for rank, account_handle in enumerate(_default_platform_accounts(platform), start=1):
            profile_contract = _shared_profile_contract(
                source_scope=source_scope,
                platform=platform,
                account_handle=account_handle,
                metadata={
                    "is_default": True,
                    "network_key": "bravo-tv",
                    "display_name": "Bravo TV",
                    "network_name": "Bravo TV",
                },
            )
            rows.append(
                {
                    "id": f"default:{platform}:{account_handle}",
                    "platform": platform,
                    "source_scope": source_scope,
                    "account_handle": account_handle,
                    "is_active": True,
                    "scrape_priority": rank * 10,
                    "metadata": {
                        "is_default": True,
                        "network_key": "bravo-tv",
                        "display_name": "Bravo TV",
                        "network_name": "Bravo TV",
                        **profile_contract,
                    },
                    "last_scrape_status": None,
                    "last_scrape_run_id": None,
                    "last_scrape_job_id": None,
                    "last_scrape_at": None,
                    "last_classified_at": None,
                    "updated_by": None,
                    "created_at": None,
                    "updated_at": None,
                    "is_default": True,
                    "profile_kind": profile_contract["profile_kind"],
                    "assignment_mode": profile_contract["assignment_mode"],
                    "assignment_rules": profile_contract["assignment_rules"],
                }
            )
    return rows


def _build_ephemeral_shared_account_override_sources(
    *,
    source_scope: str,
    platform_account_pairs: Sequence[tuple[str, str]],
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    rank = 0
    for raw_platform, raw_account_handle in platform_account_pairs:
        platform = _normalize_platform_name(raw_platform)
        account_handle = _normalize_account_handle(raw_account_handle)
        if not platform or not account_handle:
            continue
        key = (platform, account_handle)
        if key in seen:
            continue
        seen.add(key)
        rank += 1
        profile_contract = _shared_profile_contract(
            source_scope=source_scope,
            platform=platform,
            account_handle=account_handle,
            metadata={"is_ephemeral_override": True},
        )
        rows.append(
            {
                "id": f"ephemeral:{platform}:{source_scope}:{account_handle}",
                "platform": platform,
                "source_scope": source_scope,
                "account_handle": account_handle,
                "is_active": True,
                "scrape_priority": rank * 10,
                "metadata": {
                    "is_ephemeral_override": True,
                    "ephemeral_reason": "direct_profile_backfill",
                    **profile_contract,
                },
                "last_scrape_status": None,
                "last_scrape_run_id": None,
                "last_scrape_job_id": None,
                "last_scrape_at": None,
                "last_classified_at": None,
                "updated_by": None,
                "created_at": None,
                "updated_at": None,
                "is_default": False,
                "profile_kind": profile_contract["profile_kind"],
                "assignment_mode": profile_contract["assignment_mode"],
                "assignment_rules": profile_contract["assignment_rules"],
            }
        )
    return rows


def get_shared_account_sources(
    *,
    source_scope: str = "network",
    include_inactive: bool = True,
    platforms: list[str] | None = None,
) -> dict[str, Any]:
    source_scope = normalize_source_scope(source_scope)
    requested_platforms = _resolve_requested_platforms(platforms) if platforms else None
    sql = """
        select
          id::text as id,
          platform,
          source_scope,
          account_handle,
          is_active,
          scrape_priority,
          metadata,
          last_scrape_status,
          last_scrape_run_id::text as last_scrape_run_id,
          last_scrape_job_id::text as last_scrape_job_id,
          last_scrape_at,
          last_classified_at,
          updated_by,
          created_at,
          updated_at
        from social.shared_account_sources
        where source_scope = %s
    """
    params: list[Any] = [source_scope]
    if not include_inactive:
        sql += " and is_active = true"
    if requested_platforms is not None:
        sql += " and platform = any(%s)"
        params.append(requested_platforms)
    sql += " order by scrape_priority asc, platform asc, account_handle asc"
    rows = pg.fetch_all(sql, params)
    payload_rows: list[dict[str, Any]] = []
    for row in rows:
        platform = _normalize_platform_name(row.get("platform"))
        if not platform:
            continue
        if requested_platforms is not None and platform not in requested_platforms:
            continue
        payload = dict(row)
        payload["platform"] = platform
        payload["account_handle"] = (
            _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip()
        )
        payload["metadata"] = dict(row.get("metadata") or {})
        payload.update(
            _shared_profile_contract(
                source_scope=str(row.get("source_scope") or source_scope),
                platform=platform,
                account_handle=payload["account_handle"],
                metadata=payload["metadata"],
            )
        )
        payload["is_default"] = bool(payload["metadata"].get("is_default"))
        payload_rows.append(payload)
    if payload_rows:
        return {
            "source_scope": source_scope,
            "sources": payload_rows,
            "using_defaults": False,
        }

    fallback_rows = _shared_source_defaults(source_scope=source_scope)
    if requested_platforms is not None:
        fallback_rows = [row for row in fallback_rows if row.get("platform") in requested_platforms]
    return {
        "source_scope": source_scope,
        "sources": fallback_rows,
        "using_defaults": True,
    }


def put_shared_account_sources(
    *,
    source_scope: str,
    sources: list[dict[str, Any]],
    updated_by: str | None = None,
) -> dict[str, Any]:
    source_scope = normalize_source_scope(source_scope)

    normalized_sources: list[dict[str, Any]] = []
    seen_pairs: set[tuple[str, str]] = set()
    for source in sources:
        platform = _normalize_platform_name(source.get("platform"))
        if platform not in SUPPORTED_PLATFORMS:
            raise ValueError(f"Unsupported platform: {source.get('platform')}")
        account_handle = _normalize_account_handle(source.get("account_handle"))
        if not account_handle:
            raise ValueError("Shared account source requires account_handle")
        key = (platform, account_handle)
        if key in seen_pairs:
            continue
        seen_pairs.add(key)
        metadata = dict(source.get("metadata") or {})
        metadata.update(
            _shared_profile_contract(
                source_scope=source_scope,
                platform=platform,
                account_handle=account_handle,
                metadata=metadata,
            )
        )
        normalized_sources.append(
            {
                "platform": platform,
                "account_handle": account_handle,
                "is_active": bool(source.get("is_active", True)),
                "scrape_priority": max(1, int(source.get("scrape_priority") or 100)),
                "metadata": metadata,
            }
        )

    active_pairs = {(row["platform"], row["account_handle"]) for row in normalized_sources}
    with pg.db_connection() as conn:
        with pg.db_cursor(conn=conn) as cur:
            for row in normalized_sources:
                pg.fetch_one_with_cursor(
                    cur,
                    """
                    insert into social.shared_account_sources (
                      platform,
                      source_scope,
                      account_handle,
                      is_active,
                      scrape_priority,
                      metadata,
                      updated_by,
                      updated_at
                    )
                    values (%s, %s, %s, %s, %s, %s::jsonb, %s, now())
                    on conflict (platform, source_scope, account_handle)
                    do update set
                      is_active = excluded.is_active,
                      scrape_priority = excluded.scrape_priority,
                      metadata = excluded.metadata,
                      updated_by = excluded.updated_by,
                      updated_at = now()
                    returning id::text
                    """,
                    [
                        row["platform"],
                        source_scope,
                        row["account_handle"],
                        row["is_active"],
                        row["scrape_priority"],
                        _json_dumps(_metadata_dict(row["metadata"])),
                        updated_by,
                    ],
                )
            if active_pairs:
                pair_clauses = " or ".join(["(platform = %s and account_handle = %s)"] * len(active_pairs))
                pair_params: list[Any] = []
                for platform, account_handle in sorted(active_pairs):
                    pair_params.extend([platform, account_handle])
                cur.execute(
                    f"""
                    update social.shared_account_sources
                    set
                      is_active = false,
                      updated_by = %s,
                      updated_at = now()
                    where source_scope = %s
                      and not ({pair_clauses})
                    """,
                    [updated_by, source_scope, *pair_params],
                )
            else:
                cur.execute(
                    """
                    update social.shared_account_sources
                    set
                      is_active = false,
                      updated_by = %s,
                      updated_at = now()
                    where source_scope = %s
                    """,
                    [updated_by, source_scope],
                )

    return get_shared_account_sources(source_scope=source_scope, include_inactive=True)


def _shared_post_text_for_match(platform: str, row: Mapping[str, Any]) -> tuple[str, list[str], dict[str, Any]]:
    normalized_platform = _normalize_platform_name(platform)
    payload = dict(row)
    if normalized_platform == "instagram":
        text = _build_post_filter_text(
            primary_text=str(row.get("caption") or ""),
            hashtags=_as_text_list(row.get("hashtags"), strip_prefix="#"),
            mentions=_as_text_list(row.get("mentions"), prefix="@", strip_prefix="@"),
            collaborators=_as_text_list(row.get("collaborators")),
            profile_tags=_as_text_list(row.get("profile_tags")),
        )
        return text, _as_text_list(row.get("hashtags"), strip_prefix="#"), payload
    if normalized_platform == "tiktok":
        text = _build_post_filter_text(
            primary_text=str(row.get("description") or ""),
            hashtags=_as_text_list(row.get("hashtags"), strip_prefix="#"),
            mentions=_as_text_list(row.get("mentions"), prefix="@", strip_prefix="@"),
        )
        return text, _as_text_list(row.get("hashtags"), strip_prefix="#"), payload
    if normalized_platform == "twitter":
        text = _build_post_filter_text(
            primary_text=str(row.get("text") or ""),
            hashtags=_as_text_list(row.get("hashtags"), strip_prefix="#"),
            mentions=_as_text_list(row.get("mentions"), prefix="@", strip_prefix="@"),
        )
        return text, _as_text_list(row.get("hashtags"), strip_prefix="#"), payload
    if normalized_platform == "youtube":
        text = "\n".join(
            part for part in [str(row.get("title") or "").strip(), str(row.get("description") or "").strip()] if part
        )
        return text, _as_text_list(row.get("hashtags"), strip_prefix="#"), payload
    if normalized_platform == "facebook":
        text = _build_post_filter_text(
            primary_text=str(row.get("caption") or row.get("text") or ""),
            hashtags=_as_text_list(row.get("hashtags"), strip_prefix="#"),
            mentions=_as_text_list(row.get("mentions"), prefix="@", strip_prefix="@"),
        )
        return text, _as_text_list(row.get("hashtags"), strip_prefix="#"), payload
    if normalized_platform == "threads":
        text = str(row.get("text") or "")
        return text, _as_text_list(row.get("hashtags"), strip_prefix="#"), payload
    return "", [], payload


def _social_post_source_id(platform: str, row: Mapping[str, Any]) -> str:
    normalized_platform = _normalize_platform_name(platform)
    source_column = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    candidate_keys = [
        "source_id",
        source_column,
        "post_id",
        "shortcode",
        "video_id",
        "tweet_id",
        "id",
    ]
    seen: set[str] = set()
    for key in candidate_keys:
        normalized_key = str(key or "").strip()
        if not normalized_key or normalized_key in seen:
            continue
        seen.add(normalized_key)
        value = str(row.get(normalized_key) or "").strip()
        if value:
            return value
    return ""


def _social_post_permalink(platform: str, row: Mapping[str, Any]) -> str | None:
    normalized_platform = _normalize_platform_name(platform)
    raw_data = row.get("raw_data") if isinstance(row.get("raw_data"), Mapping) else {}
    for value in (
        row.get("permalink"),
        row.get("url"),
        row.get("post_url"),
        row.get("webpage_url"),
        row.get("canonical_url"),
        raw_data.get("permalink") if isinstance(raw_data, Mapping) else None,
        raw_data.get("url") if isinstance(raw_data, Mapping) else None,
        raw_data.get("post_url") if isinstance(raw_data, Mapping) else None,
        raw_data.get("webpage_url") if isinstance(raw_data, Mapping) else None,
    ):
        normalized = str(value or "").strip()
        if normalized.startswith(("http://", "https://")):
            return normalized

    source_id = _social_post_source_id(normalized_platform, row)
    if normalized_platform == "youtube" and source_id:
        if source_id.startswith("Ug"):
            return f"https://www.youtube.com/post/{source_id}"
        return f"https://www.youtube.com/watch?v={source_id}"
    return None


def _social_post_account(row: Mapping[str, Any]) -> str | None:
    return _first_non_empty_str(
        row.get("source_account"),
        row.get("username"),
        row.get("channel_title"),
        row.get("author"),
        row.get("account_handle"),
    )


def _social_post_posted_at(row: Mapping[str, Any]) -> datetime | None:
    return _coerce_dt(
        row.get("posted_at")
        or row.get("published_at")
        or row.get("created_at")
        or row.get("timestamp")
        or row.get("datePublished")
    )


def _social_post_media_urls(row: Mapping[str, Any]) -> list[str]:
    urls: list[str] = []

    def _add(value: Any) -> None:
        normalized = str(value or "").strip()
        if normalized.startswith(("http://", "https://")) and normalized not in urls:
            urls.append(normalized)

    for key in ("thumbnail_url", "hosted_thumbnail_url"):
        _add(row.get(key))
    for key in ("media_urls", "hosted_media_urls"):
        for item in _as_text_list(row.get(key)):
            _add(item)
    raw_data = row.get("raw_data") if isinstance(row.get("raw_data"), Mapping) else {}
    if isinstance(raw_data, Mapping):
        for key in ("thumbnail_url", "hosted_thumbnail_url"):
            _add(raw_data.get(key))
        for key in ("media_urls", "hosted_media_urls"):
            for item in _as_text_list(raw_data.get(key)):
                _add(item)
    return urls


def _social_post_text_preview(platform: str, row: Mapping[str, Any], *, text: str | None = None) -> str:
    source_text = text
    if source_text is None:
        source_text, _, _ = _shared_post_text_for_match(platform, row)
    normalized = " ".join(str(source_text or "").split())
    return normalized[:500]


def _social_hash_algorithm(key: str) -> str:
    normalized = str(key or "").strip().lower()
    if normalized in {"phash", "perceptual_hash"}:
        return "phash"
    if normalized in {"dhash", "difference_hash"}:
        return "dhash"
    if normalized in {"ahash", "average_hash"}:
        return "ahash"
    if normalized in {"sha256", "hosted_sha256", "content_hash"}:
        return "sha256"
    if normalized == "sha1":
        return "sha1"
    if normalized == "md5":
        return "md5"
    return normalized or "hash"


def _looks_like_social_image_hash(value: Any) -> bool:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return False
    return bool(SOCIAL_IMAGE_HASH_RE.fullmatch(normalized))


def _social_hash_walk_allowed(key: str, parent_key: str) -> bool:
    normalized = str(key or "").strip().lower()
    parent = str(parent_key or "").strip().lower()
    if any(token in normalized for token in ("cookie", "csrf", "session", "token", "signature", "fb_dtsg", "lsd")):
        return False
    if normalized in SOCIAL_IMAGE_HASH_KEYS:
        return True
    if normalized in SOCIAL_IMAGE_HASH_CONTAINER_KEYS:
        return True
    if parent in SOCIAL_IMAGE_HASH_CONTAINER_KEYS:
        return True
    return False


def _collect_social_image_hashes_from_value(value: Any, *, max_nodes: int = 1200) -> list[dict[str, str]]:
    hashes: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    stack: list[tuple[str, str, Any]] = [("", "", value)]
    visited = 0

    def _add(key: str, candidate: Any) -> None:
        normalized = str(candidate or "").strip().lower()
        if not _looks_like_social_image_hash(normalized):
            return
        algorithm = _social_hash_algorithm(key)
        dedupe_key = (algorithm, normalized)
        if dedupe_key in seen:
            return
        seen.add(dedupe_key)
        hashes.append({"algorithm": algorithm, "value": normalized})

    while stack and visited < max_nodes:
        parent_key, key, node = stack.pop()
        visited += 1
        normalized_key = str(key or "").strip().lower()
        if normalized_key in SOCIAL_IMAGE_HASH_KEYS:
            if isinstance(node, list):
                for item in node:
                    _add(normalized_key, item)
            else:
                _add(normalized_key, node)
            continue
        if isinstance(node, Mapping):
            explicit_value = node.get("value") or node.get("hash_value")
            if explicit_value and (normalized_key in SOCIAL_IMAGE_HASH_CONTAINER_KEYS or parent_key == "image_hashes"):
                _add(str(node.get("algorithm") or node.get("kind") or normalized_key or "hash"), explicit_value)
            for child_key, child_value in node.items():
                if _social_hash_walk_allowed(str(child_key), normalized_key):
                    stack.append((normalized_key, str(child_key), child_value))
        elif isinstance(node, list):
            for item in node:
                stack.append((parent_key, normalized_key, item))
    return hashes


def _collect_social_post_image_hashes(row: Mapping[str, Any]) -> list[dict[str, str]]:
    payload = {
        "asset_manifest": row.get("asset_manifest"),
        "image_hashes": row.get("image_hashes"),
        "media_asset_meta": row.get("media_asset_meta"),
        "raw_data": row.get("raw_data"),
    }
    return _collect_social_image_hashes_from_value(payload)


def _target_social_image_hashes(target: Mapping[str, Any]) -> list[dict[str, str]]:
    config = _as_string_mapping(target.get("config"))
    evidence = target.get("evidence") if isinstance(target.get("evidence"), Mapping) else {}
    return _collect_social_image_hashes_from_value(
        {
            "image_hashes": target.get("image_hashes") or target.get("media_hashes"),
            "media_asset_meta": target.get("media_asset_meta"),
            "config": config,
            "evidence": evidence,
        }
    )


def _social_image_hash_values(items: Sequence[Mapping[str, Any]]) -> set[str]:
    return {str(item.get("value") or "").strip().lower() for item in items if str(item.get("value") or "").strip()}


def _social_match_timing_payload(posted_at: datetime | None, target: Mapping[str, Any]) -> dict[str, Any]:
    context = target.get("context")
    anchor_date = context.anchor_date if isinstance(context, SeasonContext) else None
    config = _as_string_mapping(target.get("config"))
    anchor_dt = _coerce_dt(
        target.get("anchor_datetime")
        or target.get("posted_at")
        or target.get("published_at")
        or config.get("anchor_datetime")
        or config.get("posted_at")
    )
    posted_date = posted_at.date() if posted_at is not None else None
    day_delta = abs((posted_date - anchor_date).days) if posted_date is not None and anchor_date is not None else None
    delayed_hours: float | None = None
    if posted_at is not None and anchor_dt is not None:
        delayed_hours = round((posted_at.astimezone(UTC) - anchor_dt.astimezone(UTC)).total_seconds() / 3600.0, 3)
    same_day = day_delta == 0 if day_delta is not None else False
    later_same_day = bool(
        same_day
        and (
            (delayed_hours is not None and delayed_hours > 0.25)
            or (delayed_hours is None and posted_at is not None and posted_at.timetz() > time(12, 0, tzinfo=UTC))
        )
    )
    return {
        "anchor_date": anchor_date.isoformat() if anchor_date is not None else None,
        "anchor_datetime": _iso(anchor_dt),
        "posted_at": _iso(posted_at),
        "posted_date": posted_date.isoformat() if posted_date is not None else None,
        "day_delta": day_delta,
        "delayed_hours": delayed_hours,
        "same_day": same_day,
        "later_same_day": later_same_day,
        "same_campaign_delayed_window": bool(
            day_delta is not None and 0 <= day_delta <= SOCIAL_SAME_CAMPAIGN_DELAYED_MAX_DAYS
        ),
    }


def _social_reason_flags(reason: str | None) -> list[str]:
    flags: list[str] = []
    for part in str(reason or "").split(","):
        flag = part.strip()
        if flag and flag not in flags:
            flags.append(flag)
    return flags


def _social_post_confidence_tier(
    *,
    score: int,
    reason: str | None,
    image_hashes: Sequence[Mapping[str, Any]],
    timing: Mapping[str, Any],
) -> str:
    flags = set(_social_reason_flags(reason))
    if "image_hash_match" in flags:
        return "image_hash_match"
    if image_hashes and int(score or 0) > 0:
        return "image_hash_strong"
    if timing.get("later_same_day") or "near_day_repost_allowed" in flags:
        return "same_campaign_delayed"
    if timing.get("same_day") or "same_day_repost_allowed" in flags:
        return "same_day_text_match"
    if int(score or 0) >= 120:
        return "strong_text_match"
    if int(score or 0) >= 100:
        return "text_match"
    return "low_confidence"


def _normalized_social_post_evidence_payload(
    *,
    platform: str,
    row: Mapping[str, Any],
    target: Mapping[str, Any] | None = None,
    status: str,
    score: int = 0,
    reason: str | None = None,
    candidate_matches: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform)
    target_payload = target or {}
    posted_at = _social_post_posted_at(row)
    timing = _social_match_timing_payload(posted_at, target_payload) if target_payload else {}
    image_hashes = _collect_social_post_image_hashes(row)
    flags = _social_reason_flags(reason)
    signals = list(flags)
    if image_hashes and "has_image_hash" not in signals:
        signals.append("has_image_hash")
    confidence_tier = _social_post_confidence_tier(
        score=score,
        reason=reason,
        image_hashes=image_hashes,
        timing=timing,
    )
    context = target_payload.get("context")
    display_hashtags = _as_text_list(row.get("hashtags"), strip_prefix="#")
    return {
        "schema_version": SOCIAL_POST_EVIDENCE_SCHEMA_VERSION,
        "platform": normalized_platform,
        "source_id": _social_post_source_id(normalized_platform, row),
        "source_account": _social_post_account(row),
        "permalink": _social_post_permalink(normalized_platform, row),
        "posted_at": _iso(posted_at),
        "text_preview": _social_post_text_preview(normalized_platform, row),
        "hashtags": display_hashtags,
        "hashtags_normalized": sorted(_normalized_social_hashtag_keys(display_hashtags)),
        "media": {
            "urls": _social_post_media_urls(row),
            "thumbnail_url": _first_non_empty_str(row.get("thumbnail_url"), row.get("hosted_thumbnail_url")),
            "image_hashes": image_hashes,
            "has_image_hash": bool(image_hashes),
        },
        "match": {
            "status": status,
            "score": max(0, int(score or 0)),
            "reason": reason or "",
            "confidence_tier": confidence_tier,
            "signals": signals,
            "timing": timing,
            "target": (
                {
                    "show_id": context.show_id,
                    "season_id": context.season_id,
                    "show_name": context.show_name,
                    "season_number": context.season_number,
                    "anchor_date": context.anchor_date.isoformat(),
                }
                if isinstance(context, SeasonContext)
                else None
            ),
            "candidate_matches": candidate_matches or [],
        },
    }


def _compact_social_candidate_match(match: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "season_id": match.get("season_id"),
        "show_id": match.get("show_id"),
        "show_name": match.get("show_name"),
        "season_number": match.get("season_number"),
        "score": max(0, int(match.get("score") or 0)),
        "reason": str(match.get("reason") or ""),
        "confidence_tier": str(match.get("confidence_tier") or ""),
        "signals": list(match.get("signals") or []),
    }


def _shared_row_matches_target(
    *,
    platform: str,
    row: Mapping[str, Any],
    target: Mapping[str, Any],
) -> tuple[bool, int, str]:
    context = target.get("context")
    if not isinstance(context, SeasonContext):
        return False, 0, "missing_context"
    normalized_platform = _normalize_platform_name(platform)
    source_account = _normalize_account_handle(
        row.get("source_account") or row.get("username") or row.get("channel_title")
    )
    target_accounts = [
        normalized
        for normalized in (_normalize_account_handle(item) for item in (target.get("accounts") or []))
        if normalized
    ]
    if target_accounts and source_account and source_account not in set(target_accounts):
        return False, 0, "account_filtered"

    text, post_hashtags, raw_payload = _shared_post_text_for_match(normalized_platform, row)
    hashtags = _normalize_terms(target.get("hashtags"), strip_prefix="#")
    keywords = _normalize_terms(target.get("keywords"))
    row_image_hashes = _collect_social_post_image_hashes(row)
    target_image_hashes = _target_social_image_hashes(target)
    row_hash_values = _social_image_hash_values(row_image_hashes)
    target_hash_values = _social_image_hash_values(target_image_hashes)
    image_hash_match = bool(row_hash_values and target_hash_values and row_hash_values.intersection(target_hash_values))
    matched = False
    if normalized_platform == "instagram":
        matched = _instagram_post_matches_show_terms(
            context=context,
            text=text,
            post_hashtags=post_hashtags,
            hashtags=hashtags,
            keywords=keywords,
        )
    elif normalized_platform == "twitter":
        matched = _twitter_post_matches_show_terms(
            context=context,
            text=text,
            post_hashtags=post_hashtags,
            hashtags=hashtags,
            keywords=keywords,
        )
    elif normalized_platform == "youtube":
        matched = _youtube_post_matches_show_terms(
            context=context,
            title=str(row.get("title") or ""),
            description=str(row.get("description") or ""),
            post_hashtags=post_hashtags,
        )
    elif normalized_platform == "threads":
        matched = _threads_post_matches_show_terms(
            text=str(row.get("text") or ""),
            raw_data=raw_payload.get("raw_data"),
            hashtags=hashtags,
            keywords=keywords,
        )
    else:
        matched = _text_contains_any_term(text=text, hashtags=hashtags, keywords=keywords)
    if not matched and image_hash_match:
        matched = True
    if not matched:
        return False, 0, "show_terms_filtered"

    score = 100
    reason_parts = ["image_hash_match"] if image_hash_match else ["show_terms_matched"]
    if source_account and source_account in set(target_accounts):
        score += 20
        reason_parts.append("account_match")
    if image_hash_match:
        score += 120
    elif row_image_hashes:
        score += 55
        reason_parts.append("image_hash_signal")
    posted_at = _social_post_posted_at(row)
    if posted_at is not None:
        day_delta = abs((posted_at.date() - context.anchor_date).days)
        if day_delta == 0:
            score += 45
            reason_parts.append("same_day_repost_allowed")
            timing = _social_match_timing_payload(posted_at, target)
            if timing.get("later_same_day"):
                reason_parts.append("later_same_day_repost")
        elif 0 < day_delta <= SOCIAL_SAME_CAMPAIGN_DELAYED_MAX_DAYS:
            score += 25
            reason_parts.append("near_day_repost_allowed")
        else:
            score += max(0, 20 - min(20, day_delta // 7))
        reason_parts.append(f"anchor_delta_days:{day_delta}")
    return True, score, ",".join(reason_parts)


def _upsert_shared_post_match_record(
    *,
    platform: str,
    source_scope: str,
    post_row_id: str,
    source_id: str,
    source_account: str | None,
    status: str,
    run_id: str | None,
    matched_show_id: str | None = None,
    matched_season_id: str | None = None,
    score: int = 0,
    reason: str | None = None,
    candidate_matches: list[dict[str, Any]] | None = None,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    return pg.fetch_one(
        """
        insert into social.shared_post_matches (
          platform,
          source_scope,
          post_row_id,
          source_id,
          source_account,
          matched_show_id,
          matched_season_id,
          status,
          score,
          reason,
          candidate_matches,
          metadata,
          run_id,
          matched_at,
          updated_at
        )
        values (
          %s,
          %s,
          %s::uuid,
          %s,
          %s,
          %s::uuid,
          %s::uuid,
          %s,
          %s,
          %s,
          %s::jsonb,
          %s::jsonb,
          %s::uuid,
          case when %s = 'matched' then now() else null end,
          now()
        )
        on conflict (platform, source_scope, source_id)
        do update set
          post_row_id = excluded.post_row_id,
          source_account = excluded.source_account,
          matched_show_id = excluded.matched_show_id,
          matched_season_id = excluded.matched_season_id,
          status = excluded.status,
          score = excluded.score,
          reason = excluded.reason,
          candidate_matches = excluded.candidate_matches,
          metadata = excluded.metadata,
          run_id = excluded.run_id,
          matched_at = case when excluded.status = 'matched' then now() else social.shared_post_matches.matched_at end,
          updated_at = now()
        returning
          id::text,
          platform,
          source_scope,
          post_row_id::text as post_row_id,
          source_id,
          source_account,
          matched_show_id::text as matched_show_id,
          matched_season_id::text as matched_season_id,
          status,
          score,
          reason,
          candidate_matches,
          metadata,
          run_id::text as run_id
        """,
        [
            platform,
            source_scope,
            post_row_id,
            source_id,
            source_account,
            matched_show_id,
            matched_season_id,
            status,
            max(0, int(score)),
            reason,
            json.dumps(candidate_matches or []),
            json.dumps(metadata or {}),
            run_id,
            status,
        ],
    )


def _upsert_shared_review_queue_record(
    *,
    platform: str,
    source_scope: str,
    post_row_id: str,
    source_id: str,
    source_account: str | None,
    review_reason: str,
    run_id: str | None,
    payload: dict[str, Any],
) -> dict[str, Any] | None:
    return pg.fetch_one(
        """
        insert into social.shared_post_review_queue (
          platform,
          source_scope,
          post_row_id,
          source_id,
          source_account,
          review_status,
          review_reason,
          payload,
          run_id,
          updated_at
        )
        values (%s, %s, %s::uuid, %s, %s, 'open', %s, %s::jsonb, %s::uuid, now())
        on conflict (platform, source_scope, source_id)
        do update set
          post_row_id = excluded.post_row_id,
          source_account = excluded.source_account,
          review_status = 'open',
          review_reason = excluded.review_reason,
          payload = excluded.payload,
          run_id = excluded.run_id,
          updated_at = now(),
          resolved_at = null,
          resolution_action = null,
          resolved_show_id = null,
          resolved_season_id = null
        returning
          id::text,
          platform,
          source_scope,
          post_row_id::text as post_row_id,
          source_id,
          source_account,
          review_status,
          review_reason,
          payload,
          run_id::text as run_id
        """,
        [platform, source_scope, post_row_id, source_id, source_account, review_reason, json.dumps(payload), run_id],
    )


def _resolve_shared_review_queue_record(
    *,
    platform: str,
    source_scope: str,
    source_id: str,
    resolution_action: str,
    resolved_show_id: str | None = None,
    resolved_season_id: str | None = None,
) -> None:
    pg.execute(
        """
        update social.shared_post_review_queue
        set
          review_status = 'resolved',
          resolution_action = %s,
          resolved_show_id = %s::uuid,
          resolved_season_id = %s::uuid,
          resolved_at = now(),
          updated_at = now()
        where platform = %s
          and source_scope = %s
          and source_id = %s
        """,
        [resolution_action, resolved_show_id, resolved_season_id, platform, source_scope, source_id],
    )


def list_shared_review_queue(
    *,
    source_scope: str = "network",
    review_status: str = "open",
    limit: int = 100,
) -> dict[str, Any]:
    safe_limit = max(1, min(int(limit), 500))
    count_row = pg.fetch_one(
        """
        select count(*)::int as count
        from social.shared_post_review_queue
        where source_scope = %s
          and (%s = '' or review_status = %s)
        """,
        [source_scope, str(review_status or "").strip(), str(review_status or "").strip()],
    ) or {"count": 0}
    rows = pg.fetch_all(
        """
        select
          id::text as id,
          platform,
          source_scope,
          post_row_id::text as post_row_id,
          source_id,
          source_account,
          review_status,
          review_reason,
          resolution_action,
          resolved_show_id::text as resolved_show_id,
          resolved_season_id::text as resolved_season_id,
          payload,
          run_id::text as run_id,
          created_at,
          updated_at,
          resolved_at
        from social.shared_post_review_queue
        where source_scope = %s
          and (%s = '' or review_status = %s)
        order by created_at desc
        limit %s
        """,
        [source_scope, str(review_status or "").strip(), str(review_status or "").strip(), safe_limit],
    )
    return {
        "source_scope": source_scope,
        "review_status": review_status,
        "items": rows,
        "count": _normalize_non_negative_int(count_row.get("count")),
    }


def resolve_shared_review_queue_item(
    item_id: str,
    *,
    resolution_action: str,
    resolved_show_id: str | None = None,
    resolved_season_id: str | None = None,
) -> dict[str, Any]:
    row = pg.fetch_one(
        """
        update social.shared_post_review_queue
        set
          review_status = case when %s = 'ignore' then 'ignored' else 'resolved' end,
          resolution_action = %s,
          resolved_show_id = %s::uuid,
          resolved_season_id = %s::uuid,
          resolved_at = now(),
          updated_at = now()
        where id = %s::uuid
        returning
          id::text as id,
          platform,
          source_scope,
          source_id,
          review_status,
          review_reason,
          resolution_action,
          resolved_show_id::text as resolved_show_id,
          resolved_season_id::text as resolved_season_id,
          payload,
          run_id::text as run_id
        """,
        [resolution_action, resolution_action, resolved_show_id, resolved_season_id, item_id],
    )
    if not row:
        raise ValueError("Shared review queue item not found")
    return row


def _shared_stage_status_summary(stage_counts: Mapping[str, Any] | None, stage: str) -> dict[str, Any] | None:
    if not isinstance(stage_counts, Mapping):
        return None
    bucket = stage_counts.get(stage)
    if not isinstance(bucket, Mapping):
        return None
    total_jobs = _normalize_non_negative_int(bucket.get("total"))
    completed_jobs = _normalize_non_negative_int(bucket.get("completed"))
    failed_jobs = _normalize_non_negative_int(bucket.get("failed"))
    active_jobs = _normalize_non_negative_int(bucket.get("active"))
    if active_jobs > 0:
        status = "running"
    elif failed_jobs > 0 and completed_jobs > 0:
        status = "partial"
    elif failed_jobs > 0:
        status = "failed"
    elif total_jobs > 0 and completed_jobs >= total_jobs:
        status = "complete"
    elif total_jobs > 0:
        status = "queued"
    else:
        status = "idle"
    return {
        "status": status,
        "job_count": total_jobs,
        "active_jobs": active_jobs,
        "completed_jobs": completed_jobs,
        "failed_jobs": failed_jobs,
    }


def get_season_shared_status(
    season_id: str,
    *,
    source_scope: str = "network",
) -> dict[str, Any]:
    from trr_backend.socials.control_plane.shared_accounts import get_season_shared_status as impl

    source_scope = normalize_source_scope(source_scope)
    return impl(season_id, source_scope=source_scope)


