# Ingest helpers


def _touch_worker_heartbeat_for_job(
    *,
    job_id: str,
    status: str,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not _worker_heartbeat_schema_ready():
        return
    pg.fetch_one(
        """
        update social.scrape_workers as w
        set
          stage = coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, w.stage),
          status = %s,
          run_id = coalesce(j.run_id, w.run_id),
          current_job_id = j.id,
          metadata = coalesce(w.metadata, '{}'::jsonb) || %s::jsonb,
          last_seen_at = now(),
          updated_at = now()
        from social.scrape_jobs as j
        where j.id = %s::uuid
          and j.worker_id is not null
          and w.worker_id = j.worker_id
        returning w.worker_id
        """,
        [_normalize_worker_status(status), _json_dumps(_metadata_dict(metadata)), job_id],
        pool_name=SOCIAL_CATALOG_PROGRESS_POOL_NAME,
    )


def _clear_worker_heartbeat_for_job(
    *,
    job_id: str,
    status: str = "idle",
    metadata: dict[str, Any] | None = None,
) -> None:
    if not _worker_heartbeat_schema_ready():
        return
    pg.fetch_one(
        """
        update social.scrape_workers as w
        set
          status = %s,
          run_id = null,
          current_job_id = null,
          metadata = coalesce(w.metadata, '{}'::jsonb) || %s::jsonb,
          last_seen_at = now(),
          updated_at = now()
        from social.scrape_jobs as j
        where j.id = %s::uuid
          and j.worker_id is not null
          and w.worker_id = j.worker_id
        returning w.worker_id
        """,
        [_normalize_worker_status(status), _json_dumps(_metadata_dict(metadata)), job_id],
        pool_name=SOCIAL_CATALOG_PROGRESS_POOL_NAME,
    )


def _load_current_job_row(job_id: str) -> dict[str, Any]:
    return (
        pg.fetch_one(
            """
            select
              id::text,
              run_id::text as run_id,
              platform,
              job_type,
              status,
              items_found,
              error_message,
              metadata
            from social.scrape_jobs
            where id = %s
            """,
            [job_id],
        )
        or {}
    )


def _abort_claimed_job_if_cancelled(
    *,
    job_id: str,
    run_id: str,
    stage: str,
    platform: str,
    account: str,
) -> dict[str, Any] | None:
    job_state = pg.fetch_one("select status from social.scrape_jobs where id = %s", [job_id]) or {}
    job_is_cancelled = str(job_state.get("status") or "").strip().lower() in {"cancelled", "cancelling"}
    run_is_cancelled = False
    if run_id:
        run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
        run_is_cancelled = str(run_state.get("status") or "").strip().lower() in {"cancelled", "cancelling"}
    if not job_is_cancelled and not run_is_cancelled:
        return None

    existing_job = _load_current_job_row(job_id)
    _finish_job(
        job_id,
        status="cancelled",
        items_found=_normalize_non_negative_int(existing_job.get("items_found")),
        error_message="Cancelled by user request",
        metadata={
            "stage": stage,
            "platform": platform,
            "account": account,
            "cancelled_before_execution": True,
            "cancel_scope": "run" if run_is_cancelled else "job",
        },
    )
    if run_id:
        _finalize_run_status(run_id)
    return _load_current_job_row(job_id)


def cancel_claimed_job_before_processing(claimed_job: dict[str, Any]) -> dict[str, Any] | None:
    job_id = str(claimed_job.get("id") or "").strip()
    if not job_id:
        return None
    run_id = str(claimed_job.get("run_id") or "").strip()
    config = dict(claimed_job.get("config") or {})
    metadata = dict(claimed_job.get("metadata") or {})
    stage = str(config.get("stage") or metadata.get("stage") or claimed_job.get("job_type") or "posts")
    platform = _normalize_platform_name(claimed_job.get("platform")) or "unknown"
    account = str(config.get("account") or metadata.get("account") or "").strip()
    return _abort_claimed_job_if_cancelled(
        job_id=job_id,
        run_id=run_id,
        stage=stage,
        platform=platform,
        account=account,
    )


def _maybe_auto_supersede_catalog_runtime_for_job(
    *,
    run_id: str,
    platform: str,
    account_handle: str,
    source_scope: str,
) -> dict[str, Any] | None:
    if not run_id or not account_handle:
        return None
    try:
        run_row = _load_social_account_catalog_run_row(
            platform=platform,
            account_handle=account_handle,
            run_id=run_id,
        )
    except RuntimeError as exc:
        from trr_backend.db.pg import is_database_service_unavailable_error

        if is_database_service_unavailable_error(exc):
            return None
        raise
    run_config = _metadata_dict(run_row.get("config"))
    required_runtime_version = _metadata_dict(run_config.get("required_runtime_version"))
    required_execution_backend = str(run_config.get("required_execution_backend") or "").strip().lower() or None
    if required_execution_backend != "modal" or not required_runtime_version:
        return None
    authoritative_runtime = _resolve_authoritative_catalog_runtime_version(
        required_execution_backend=required_execution_backend
    )
    if not authoritative_runtime or _runtime_version_satisfies_requirement(
        required_runtime_version,
        authoritative_runtime,
    ):
        return None
    return remediate_social_account_catalog_runtime_supersession(
        platform=platform,
        account_handle=account_handle,
        run_id=run_id,
        requeue_canary=True,
        source_scope=source_scope,
        initiated_by="runtime-supersession",
        cancelled_by="runtime-supersession",
        superseded_by_runtime_version=authoritative_runtime,
        limit=1,
    )


def _create_job(
    context: SeasonContext | None,
    *,
    run_id: str | None,
    platform: str,
    source_scope: str,
    job_type: str,
    stage: str,
    config: dict[str, Any],
    initiated_by: str | None,
    status: str,
    priority: int = 100,
    worker_id: str | None = None,
    preclaim: bool = False,
    available_at: datetime | None = None,
    max_attempts: int | None = None,
    conn: Any | None = None,
    track_run_counters: bool = True,
) -> str:
    effective_status = status
    if preclaim and worker_id:
        effective_status = "running"
    config_payload = _metadata_dict(config)
    required_execution_backend = _job_required_execution_backend(config_payload, platform=platform)
    creator_runtime_version = dict(_resolve_runtime_version_stamp())
    effective_runtime_version = _resolve_effective_runtime_version(
        required_execution_backend=required_execution_backend,
        stage=stage,
    )
    if required_execution_backend:
        config_payload.setdefault("required_execution_backend", required_execution_backend)
    if effective_runtime_version:
        config_payload.setdefault("required_runtime_version", effective_runtime_version)
    elif required_execution_backend != "modal":
        config_payload.setdefault("required_runtime_version", creator_runtime_version)
    if creator_runtime_version:
        config_payload.setdefault("created_by_runtime_version", creator_runtime_version)
    requested_max_attempts = max(1, int(max_attempts)) if max_attempts is not None else None
    supports_queue_fields = bool(_scrape_jobs_features().get("has_queue_fields"))
    insert_max_attempts_sql = ", max_attempts" if (requested_max_attempts is not None and supports_queue_fields) else ""
    value_max_attempts_sql = ", %s" if (requested_max_attempts is not None and supports_queue_fields) else ""
    insert_params: list[Any] = [
        run_id,
        platform,
        job_type,
        _json_dumps(config_payload),
        effective_status,
        _coerce_dt(available_at),
        priority,
        context.show_id if context is not None else None,
        context.season_id if context is not None else None,
        source_scope,
        initiated_by,
        _json_dumps(
            _job_runtime_metadata(
                stage,
                runtime_version=effective_runtime_version,
                created_by_runtime_version=creator_runtime_version,
            )
        ),
        worker_id,
        preclaim,
        preclaim,
        preclaim,
        preclaim,
    ]
    if requested_max_attempts is not None and supports_queue_fields:
        insert_params.append(requested_max_attempts)
    with pg.db_cursor(conn=conn) as cur:
        row = pg.fetch_one_with_cursor(
            cur,
            f"""
        insert into social.scrape_jobs (
          run_id,
          platform,
          job_type,
          config,
          status,
          available_at,
          priority,
          show_id,
          season_id,
          source_scope,
          initiated_by,
          metadata,
          worker_id,
          started_at,
          claimed_at,
          heartbeat_at,
          attempt_count
          {insert_max_attempts_sql}
        )
        values (
          %s,
          %s,
          %s,
          %s::jsonb,
          %s,
          coalesce(%s::timestamptz, now()),
          %s,
          %s,
          %s,
          %s,
          %s,
          %s::jsonb,
          %s,
          case when %s then now() else null end,
          case when %s then now() else null end,
          case when %s then now() else null end,
          case when %s then 1 else 0 end
          {value_max_attempts_sql}
        )
        returning id::text
        """,
            insert_params,
        )
    if not row:
        raise RuntimeError("Failed to create scrape job")
    job_id = str(row["id"])
    if run_id and track_run_counters:
        _increment_run_counters_on_job_create(run_id=run_id, stage=stage, status=effective_status)
    return job_id


def _insert_job_with_conflict_target(
    context: SeasonContext | None,
    *,
    run_id: str | None,
    platform: str,
    source_scope: str,
    job_type: str,
    stage: str,
    config: dict[str, Any],
    status: str,
    priority: int,
    conflict_target_sql: str,
    existing_lookup_sql: str,
    existing_lookup_params: Sequence[Any],
    conn: Any | None = None,
) -> str | None:
    config_payload = _metadata_dict(config)
    required_execution_backend = _job_required_execution_backend(config_payload, platform=platform)
    creator_runtime_version = dict(_resolve_runtime_version_stamp_for_stage(stage))
    effective_runtime_version = _resolve_effective_runtime_version(
        required_execution_backend=required_execution_backend,
        stage=stage,
    )
    if required_execution_backend:
        config_payload.setdefault("required_execution_backend", required_execution_backend)
    if effective_runtime_version:
        config_payload.setdefault("required_runtime_version", effective_runtime_version)
    elif required_execution_backend != "modal":
        config_payload.setdefault("required_runtime_version", creator_runtime_version)
    if creator_runtime_version:
        config_payload.setdefault("created_by_runtime_version", creator_runtime_version)

    insert_params: list[Any] = [
        run_id,
        platform,
        job_type,
        _json_dumps(config_payload),
        status,
        priority,
        context.show_id if context is not None else None,
        context.season_id if context is not None else None,
        source_scope,
        _json_dumps(
            _job_runtime_metadata(
                stage,
                runtime_version=effective_runtime_version,
                created_by_runtime_version=creator_runtime_version,
            )
        ),
    ]
    with pg.db_cursor(conn=conn) as cur:
        inserted = pg.fetch_one_with_cursor(
            cur,
            f"""
            insert into social.scrape_jobs (
              run_id,
              platform,
              job_type,
              config,
              status,
              available_at,
              priority,
              show_id,
              season_id,
              source_scope,
              metadata,
              attempt_count
            )
            values (
              %s,
              %s,
              %s,
              %s::jsonb,
              %s,
              now(),
              %s,
              %s,
              %s,
              %s,
              %s::jsonb,
              0
            )
            {conflict_target_sql}
            returning id::text as id
            """,
            insert_params,
        )
        if inserted and inserted.get("id"):
            job_id = str(inserted["id"])
            if run_id:
                _increment_run_counters_on_job_create(run_id=run_id, stage=stage, status=status, conn=conn)
            return job_id
        existing = pg.fetch_one_with_cursor(cur, existing_lookup_sql, list(existing_lookup_params))
        return str(existing["id"]) if existing and existing.get("id") else None


def _set_job_running(job_id: str, *, worker_id: str | None = None) -> None:
    pg.fetch_one(
        """
        update social.scrape_jobs
        set
          status = 'running',
          started_at = coalesce(started_at, now()),
          claimed_at = now(),
          heartbeat_at = now(),
          worker_id = coalesce(%s, worker_id),
          attempt_count = attempt_count + 1,
          error_message = null,
          last_error_code = null,
          last_error_class = null
        where id = %s
        returning id::text
        """,
        [worker_id, job_id],
    )


def _touch_job_heartbeat(job_id: str, *, worker_id: str | None = None) -> bool:
    row = pg.fetch_one(
        """
        update social.scrape_jobs
        set
          heartbeat_at = now(),
          worker_id = coalesce(%s, worker_id)
        where id = %s
          and status = 'running'
          and claimed_at is not null
          and (
            %s::text is null
            or worker_id is null
            or worker_id = %s::text
            or %s::text like worker_id || '%%'
          )
        returning id::text
        """,
        [worker_id, job_id, worker_id, worker_id, worker_id],
        pool_name=SOCIAL_CATALOG_PROGRESS_POOL_NAME,
    )
    if not row:
        return False
    _touch_worker_heartbeat_for_job(
        job_id=job_id,
        status="working",
        metadata={"source": "job_heartbeat"},
    )
    return True


def _job_dispatch_metadata(job_row: Mapping[str, Any] | None) -> dict[str, Any]:
    if not isinstance(job_row, Mapping):
        return {}
    metadata = dict(job_row.get("metadata") or {})
    dispatch = metadata.get("dispatch")
    return dict(dispatch) if isinstance(dispatch, dict) else {}


def _touch_job_dispatch_metadata(
    job_id: str,
    *,
    dispatch_backend: str,
    dispatch_requested_at: datetime | None | object = FIELD_UNSET,
    dispatch_attempt_count: int | None | object = FIELD_UNSET,
    remote_invocation_id: str | None | object = FIELD_UNSET,
    remote_function_name: str | None | object = FIELD_UNSET,
    lease_expires_at: datetime | None | object = FIELD_UNSET,
    last_dispatch_error: str | None | object = FIELD_UNSET,
    last_dispatch_error_code: str | None | object = FIELD_UNSET,
    last_dispatch_error_at: datetime | None | object = FIELD_UNSET,
    remote_invocation_status: str | None | object = FIELD_UNSET,
    remote_invocation_checked_at: datetime | None | object = FIELD_UNSET,
    remote_task_id: str | None | object = FIELD_UNSET,
    remote_pending_since: datetime | None | object = FIELD_UNSET,
    remote_blocked_reason: str | None | object = FIELD_UNSET,
    dispatch_blocked_failure_count: int | None | object = FIELD_UNSET,
    dispatch_blocked_first_seen_at: datetime | None | object = FIELD_UNSET,
) -> None:
    existing_row = pg.fetch_one("select metadata from social.scrape_jobs where id = %s::uuid", [job_id]) or {}
    existing_dispatch = _job_dispatch_metadata(existing_row)

    if dispatch_attempt_count is FIELD_UNSET:
        dispatch_attempt_count = int(existing_dispatch.get("dispatch_attempt_count") or 0) + 1

    def _resolve_text(value: str | None | object, existing_key: str) -> str | None:
        if value is FIELD_UNSET:
            resolved = existing_dispatch.get(existing_key)
        else:
            resolved = value
        return str(resolved or "").strip() or None

    def _resolve_dt(value: datetime | None | object, existing_key: str) -> str | None:
        if value is FIELD_UNSET:
            return _iso(_coerce_dt(existing_dispatch.get(existing_key)))
        return _iso(_coerce_dt(value))

    if dispatch_requested_at is FIELD_UNSET:
        dispatch_requested_at = _coerce_dt(existing_dispatch.get("dispatch_requested_at")) or _now_utc()

    dispatch_payload = {
        **existing_dispatch,
        "dispatch_backend": dispatch_backend,
        "dispatch_requested_at": _iso(_coerce_dt(dispatch_requested_at) or _now_utc()),
        "dispatch_attempt_count": max(1, int(cast(Any, dispatch_attempt_count))),
        "remote_invocation_id": _resolve_text(remote_invocation_id, "remote_invocation_id"),
        "remote_function_name": _resolve_text(remote_function_name, "remote_function_name"),
        "lease_expires_at": _resolve_dt(lease_expires_at, "lease_expires_at"),
        "last_dispatch_error": _resolve_text(last_dispatch_error, "last_dispatch_error"),
        "last_dispatch_error_code": _resolve_text(last_dispatch_error_code, "last_dispatch_error_code"),
        "last_dispatch_error_at": _resolve_dt(last_dispatch_error_at, "last_dispatch_error_at"),
        "remote_invocation_status": _resolve_text(remote_invocation_status, "remote_invocation_status"),
        "remote_invocation_checked_at": _resolve_dt(remote_invocation_checked_at, "remote_invocation_checked_at"),
        "remote_task_id": _resolve_text(remote_task_id, "remote_task_id"),
        "remote_pending_since": _resolve_dt(remote_pending_since, "remote_pending_since"),
        "remote_blocked_reason": _resolve_text(remote_blocked_reason, "remote_blocked_reason"),
        "dispatch_blocked_failure_count": (
            _normalize_non_negative_int(existing_dispatch.get("dispatch_blocked_failure_count"))
            if dispatch_blocked_failure_count is FIELD_UNSET
            else _normalize_non_negative_int(dispatch_blocked_failure_count)
        ),
        "dispatch_blocked_first_seen_at": _resolve_dt(
            dispatch_blocked_first_seen_at,
            "dispatch_blocked_first_seen_at",
        ),
    }
    pg.fetch_one(
        """
        update social.scrape_jobs
        set
          metadata = jsonb_set(coalesce(metadata, '{}'::jsonb), '{dispatch}', %s::jsonb, true)
        where id = %s::uuid
        returning id::text
        """,
        [_json_dumps(dispatch_payload), job_id],
    )


def _resolve_stale_modal_dispatch_recovery_limit() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_STALE_UNCLAIMED_RECOVERY_LIMIT",
        SOCIAL_MODAL_STALE_UNCLAIMED_RECOVERY_LIMIT_DEFAULT,
        minimum=1,
        maximum=10,
    )


def _dispatch_metadata_recovery_count(dispatch: Mapping[str, Any] | None) -> int:
    return _normalize_non_negative_int(_metadata_dict(dispatch).get("stale_unclaimed_recovery_count"))


def _dispatch_metadata_error_code(dispatch: Mapping[str, Any] | None) -> str:
    return str(_metadata_dict(dispatch).get("last_dispatch_error_code") or "").strip().lower()


def _dispatch_metadata_attempt_count(dispatch: Mapping[str, Any] | None) -> int:
    return max(1, _normalize_non_negative_int(_metadata_dict(dispatch).get("dispatch_attempt_count")) or 1)


def _dispatch_metadata_blocked_failure_count(dispatch: Mapping[str, Any] | None) -> int:
    return _normalize_non_negative_int(_metadata_dict(dispatch).get("dispatch_blocked_failure_count"))


def _normalize_dispatch_blocked_reason(
    *,
    remote_blocked_reason: Any = None,
    last_dispatch_error_code: Any = None,
    last_dispatch_error: Any = None,
) -> str:
    explicit_reason = str(remote_blocked_reason or "").strip().lower()
    if explicit_reason:
        return explicit_reason
    error_code = str(last_dispatch_error_code or "").strip().lower()
    error_message = str(last_dispatch_error or "").strip().lower()
    if error_code and error_code != "modal_dispatch_failed":
        return error_code
    if "no module named 'modal'" in error_message:
        return "modal_sdk_unavailable"
    if "function" in error_message and "not found" in error_message:
        return "modal_function_not_found"
    if "app" in error_message and "not found" in error_message:
        return "modal_app_not_found"
    if "modal" in error_message and "unavailable" in error_message:
        return "modal_sdk_unavailable"
    if error_code:
        return error_code
    return "dispatch_blocked"


def _dispatch_blocked_reference_at(
    dispatch: Mapping[str, Any] | None,
    row: Mapping[str, Any] | None = None,
) -> datetime | None:
    dispatch_payload = _metadata_dict(dispatch)
    for key in (
        "dispatch_blocked_first_seen_at",
        "last_dispatch_error_at",
        "remote_invocation_checked_at",
        "dispatch_requested_at",
    ):
        resolved = _coerce_dt(dispatch_payload.get(key))
        if resolved is not None:
            return resolved
    if isinstance(row, Mapping):
        return _coerce_dt(row.get("available_at") or row.get("created_at"))
    return None


def _dispatch_blocked_seconds(
    dispatch: Mapping[str, Any] | None,
    row: Mapping[str, Any] | None = None,
) -> int:
    reference_at = _dispatch_blocked_reference_at(dispatch, row)
    if reference_at is None:
        return 0
    return max(0, int((_now_utc() - reference_at).total_seconds()))


def _job_is_dispatch_blocked(row: Mapping[str, Any] | None) -> bool:
    if not isinstance(row, Mapping):
        return False
    status = str(row.get("status") or "").strip().lower()
    if status not in {"queued", "pending", "retrying"}:
        return False
    if str(row.get("worker_id") or "").strip():
        return False
    dispatch = _job_dispatch_metadata(row)
    if str(dispatch.get("dispatch_backend") or "").strip().lower() != "modal":
        return False
    if str(dispatch.get("remote_invocation_id") or "").strip():
        return False
    return bool(
        str(dispatch.get("last_dispatch_error") or "").strip()
        or str(dispatch.get("remote_blocked_reason") or "").strip()
        or _dispatch_metadata_error_code(dispatch) == "modal_dispatch_failed"
    )


def _dispatch_blocked_jobs_filter_clause(*, table_alias: str = "j") -> tuple[str, list[Any]]:
    dispatch_backend_expr = f"lower(coalesce({table_alias}.metadata->'dispatch'->>'dispatch_backend', ''))"
    remote_invocation_expr = f"nullif(coalesce({table_alias}.metadata->'dispatch'->>'remote_invocation_id', ''), '')"
    last_dispatch_error_expr = f"nullif(coalesce({table_alias}.metadata->'dispatch'->>'last_dispatch_error', ''), '')"
    last_dispatch_error_code_expr = (
        f"lower(coalesce({table_alias}.metadata->'dispatch'->>'last_dispatch_error_code', ''))"
    )
    remote_blocked_reason_expr = (
        f"nullif(coalesce({table_alias}.metadata->'dispatch'->>'remote_blocked_reason', ''), '')"
    )
    return (
        f"""
        {table_alias}.status in ('queued', 'pending', 'retrying')
        and coalesce({table_alias}.worker_id, '') = ''
        and {dispatch_backend_expr} = 'modal'
        and {remote_invocation_expr} is null
        and (
          {last_dispatch_error_code_expr} = 'modal_dispatch_failed'
          or {remote_blocked_reason_expr} is not null
          or {last_dispatch_error_expr} is not null
        )
        """,
        [],
    )


def _modal_invocation_status(dispatch: Mapping[str, Any] | None) -> str:
    return str(_metadata_dict(dispatch).get("remote_invocation_status") or "").strip().lower()


def _modal_invocation_is_nonterminal(status: str | None) -> bool:
    return str(status or "").strip().lower() in {"pending", "running"}


def _resolve_modal_comment_recovery_priority_cutoff() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_COMMENT_RECOVERY_PRIORITY_CUTOFF",
        SOCIAL_MODAL_COMMENT_RECOVERY_PRIORITY_CUTOFF_DEFAULT,
        minimum=1,
        maximum=999,
    )


def _modal_comment_recovery_priority_override_slots() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_COMMENT_RECOVERY_PRIORITY_OVERRIDE_SLOTS",
        SOCIAL_MODAL_COMMENT_RECOVERY_PRIORITY_OVERRIDE_SLOTS_DEFAULT,
        minimum=0,
        maximum=10,
    )


def _modal_pending_capacity_stale_seconds() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_MODAL_PENDING_CAPACITY_STALE_SECONDS",
        SOCIAL_MODAL_PENDING_CAPACITY_STALE_SECONDS_DEFAULT,
        minimum=60,
        maximum=3600,
    )


def _job_is_priority_comment_recovery(
    job: Mapping[str, Any] | None,
    job_config: Mapping[str, Any] | None = None,
    *,
    stage: str | None = None,
) -> bool:
    if not isinstance(job, Mapping):
        return False
    config = _metadata_dict(job_config if job_config is not None else job.get("config"))
    if not bool(config.get("comments_audit_cursor_retry")):
        return False
    if not _job_config_allows_priority_comment_recovery_override(config):
        return False
    normalized_stage = _modal_dispatch_capacity_stage(stage or _job_stage_from_row(job))
    if normalized_stage != "comments":
        return False
    priority = _normalize_non_negative_int(job.get("priority")) or 999
    return priority <= _resolve_modal_comment_recovery_priority_cutoff()


def _job_config_allows_priority_comment_recovery_override(config: Mapping[str, Any] | None) -> bool:
    metadata = _metadata_dict(config)
    return any(
        _metadata_value_truthy(metadata.get(key)) for key in SOCIAL_MODAL_COMMENT_RECOVERY_PRIORITY_OVERRIDE_CONFIG_KEYS
    )


def _current_modal_priority_comment_recovery_running_count() -> int:
    try:
        row = pg.fetch_one(
            """
            select count(*)::int as total
            from social.scrape_jobs
            where status = 'running'
              and lower(coalesce(platform, '')) = 'instagram'
              and coalesce(config->>'stage', metadata->>'stage', job_type) = %s
              and lower(coalesce(config->>'comments_audit_cursor_retry', '')) in ('1', 'true', 'yes', 'on')
              and (
                lower(coalesce(config->>'comments_priority_recovery_override', '')) in ('1', 'true', 'yes', 'on')
                or lower(coalesce(config->>'priority_recovery_override', '')) in ('1', 'true', 'yes', 'on')
                or lower(coalesce(config->>'respect_priority_override', '')) in ('1', 'true', 'yes', 'on')
              )
              and priority <= %s
            """,
            [
                INSTAGRAM_COMMENTS_SCRAPLING_STAGE,
                _resolve_modal_comment_recovery_priority_cutoff(),
            ],
        )
    except Exception:
        logger.debug("Failed to count running priority comment recovery jobs", exc_info=True)
        return 0
    return _normalize_non_negative_int((row or {}).get("total"))


def _modal_pending_capacity_invocation_is_stale(
    job_dispatch: Mapping[str, Any] | None,
    inspection: Mapping[str, Any] | None = None,
    *,
    now: datetime | None = None,
) -> bool:
    dispatch = _metadata_dict(job_dispatch)
    remote_status = (
        str(_metadata_dict(inspection).get("status") or dispatch.get("remote_invocation_status") or "").strip().lower()
    )
    if remote_status != "pending":
        return False
    reason = (
        str(_metadata_dict(inspection).get("reason") or dispatch.get("remote_blocked_reason") or "").strip().lower()
    )
    if reason and reason != "modal_capacity_pending":
        return False
    pending_since = _coerce_dt(dispatch.get("remote_pending_since")) or _coerce_dt(
        dispatch.get("dispatch_requested_at")
    )
    if pending_since is None:
        return False
    if pending_since.tzinfo is None:
        pending_since = pending_since.replace(tzinfo=UTC)
    reference_now = now or _now_utc()
    return (reference_now - pending_since).total_seconds() >= _modal_pending_capacity_stale_seconds()


def _clear_stale_pending_modal_dispatch(
    job_id: str,
    job_dispatch: Mapping[str, Any] | None,
    *,
    reason: str = "stale_modal_pending_capacity_cleared",
) -> dict[str, Any]:
    dispatch = _metadata_dict(job_dispatch)
    now_utc = _now_utc()
    clear_count = _normalize_non_negative_int(dispatch.get("stale_pending_modal_clear_count")) + 1
    _touch_job_dispatch_metadata(
        job_id,
        dispatch_backend=str(dispatch.get("dispatch_backend") or "modal"),
        dispatch_requested_at=_coerce_dt(dispatch.get("dispatch_requested_at")),
        dispatch_attempt_count=_dispatch_metadata_attempt_count(dispatch),
        remote_invocation_id=None,
        lease_expires_at=None,
        remote_invocation_status="unknown",
        remote_invocation_checked_at=now_utc,
        remote_task_id=None,
        remote_pending_since=None,
        remote_blocked_reason=reason,
        last_dispatch_error=None,
        last_dispatch_error_code=None,
        last_dispatch_error_at=None,
        dispatch_blocked_failure_count=0,
        dispatch_blocked_first_seen_at=None,
    )
    return {
        **dispatch,
        "remote_invocation_id": None,
        "remote_invocation_status": "unknown",
        "remote_invocation_checked_at": _iso(now_utc),
        "remote_task_id": None,
        "remote_pending_since": None,
        "remote_blocked_reason": reason,
        "lease_expires_at": None,
        "stale_pending_modal_clear_count": clear_count,
        "stale_pending_modal_cleared_at": _iso(now_utc),
    }


def _refresh_remote_modal_invocation_state(
    job: Mapping[str, Any],
    *,
    lease_expires_at: datetime | None | object = FIELD_UNSET,
) -> dict[str, Any]:
    dispatch = _job_dispatch_metadata(job)
    job_id = str(job.get("id") or "").strip()
    call_id = str(dispatch.get("remote_invocation_id") or "").strip()
    if not job_id or not call_id:
        return {
            "function_call_id": call_id or None,
            "status": "unknown",
            "reason": "modal_call_id_missing",
            "nonterminal": False,
            "terminal": False,
            "task_id": None,
            "checked_at": None,
        }

    inspection = inspect_modal_function_call(call_id)
    inspection_status = str(inspection.get("status") or "").strip().lower() or "unknown"
    checked_at = _coerce_dt(inspection.get("checked_at"))
    requested_at = _coerce_dt(dispatch.get("dispatch_requested_at"))
    pending_since_existing = _coerce_dt(dispatch.get("remote_pending_since"))
    remote_pending_since: datetime | None
    if inspection_status == "pending":
        remote_pending_since = pending_since_existing or requested_at or checked_at
    else:
        remote_pending_since = None

    clear_dispatch_error = _modal_invocation_is_nonterminal(inspection_status)
    refreshed_lease_value = lease_expires_at if clear_dispatch_error else FIELD_UNSET
    _touch_job_dispatch_metadata(
        job_id,
        dispatch_backend=str(dispatch.get("dispatch_backend") or "modal"),
        dispatch_requested_at=requested_at,
        dispatch_attempt_count=_dispatch_metadata_attempt_count(dispatch),
        remote_invocation_id=call_id,
        lease_expires_at=refreshed_lease_value,
        last_dispatch_error=None if clear_dispatch_error else FIELD_UNSET,
        last_dispatch_error_code=None if clear_dispatch_error else FIELD_UNSET,
        remote_invocation_status=inspection_status,
        remote_invocation_checked_at=checked_at,
        remote_task_id=str(inspection.get("task_id") or "").strip() or None,
        remote_pending_since=remote_pending_since,
        remote_blocked_reason=str(inspection.get("reason") or "").strip() or None,
    )
    return inspection


def _update_job_config(job_id: str, *, config_updates: Mapping[str, Any] | None = None) -> dict[str, Any]:
    updates = _metadata_dict(config_updates)
    if not job_id or not updates:
        return {}
    row = (
        pg.fetch_one(
            """
            update social.scrape_jobs
            set
              config = coalesce(config, '{}'::jsonb) || %s::jsonb,
              heartbeat_at = now()
            where id = %s::uuid
            returning config
            """,
            [_json_dumps(updates), job_id],
        )
        or {}
    )
    return _metadata_dict(row.get("config"))


def _mark_claimed_modal_dispatch_running(claimed_job: Mapping[str, Any] | None) -> None:
    if not isinstance(claimed_job, Mapping):
        return
    job_id = str(claimed_job.get("id") or "").strip()
    if not job_id:
        return
    dispatch = _job_dispatch_metadata(claimed_job)
    dispatch_backend = str(dispatch.get("dispatch_backend") or "").strip().lower()
    remote_invocation_id = str(dispatch.get("remote_invocation_id") or "").strip()
    if dispatch_backend != "modal" and not remote_invocation_id:
        return
    _touch_job_dispatch_metadata(
        job_id,
        dispatch_backend=dispatch_backend or "modal",
        dispatch_requested_at=_coerce_dt(dispatch.get("dispatch_requested_at")),
        dispatch_attempt_count=_dispatch_metadata_attempt_count(dispatch),
        remote_invocation_id=remote_invocation_id or None,
        lease_expires_at=None,
        last_dispatch_error=None,
        last_dispatch_error_code=None,
        last_dispatch_error_at=None,
        remote_invocation_status="running",
        remote_invocation_checked_at=_now_utc(),
        remote_task_id=str(dispatch.get("remote_task_id") or "").strip() or None,
        remote_pending_since=None,
        remote_blocked_reason=None,
        dispatch_blocked_failure_count=0,
        dispatch_blocked_first_seen_at=None,
    )


def _claimed_media_runtime_versions() -> tuple[str, str]:
    media_runtime = _resolve_effective_runtime_version(
        required_execution_backend="modal",
        stage=INSTAGRAM_MEDIA_MIRROR_STAGE,
    )
    comment_media_runtime = _resolve_effective_runtime_version(
        required_execution_backend="modal",
        stage=COMMENT_MEDIA_MIRROR_STAGE,
    )
    return _json_dumps(media_runtime), _json_dumps(comment_media_runtime)


def _claim_job_by_id(*, job_id: str, worker_id: str) -> dict[str, Any] | None:
    media_runtime_json, comment_media_runtime_json = _claimed_media_runtime_versions()
    return pg.fetch_one(
        """
        update social.scrape_jobs as j
        set
          status = 'running',
          started_at = coalesce(started_at, now()),
          claimed_at = now(),
          heartbeat_at = now(),
          worker_id = %s,
          attempt_count = attempt_count + 1,
          error_message = null,
          last_error_code = null,
          last_error_class = null,
          config = case
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'media_mirror'
              then coalesce(j.config, '{}'::jsonb) || jsonb_build_object(
                'required_runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'comment_media_mirror'
              then coalesce(j.config, '{}'::jsonb) || jsonb_build_object(
                'required_runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            else j.config
          end,
          metadata = case
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'media_mirror'
              then coalesce(j.metadata, '{}'::jsonb) || jsonb_build_object(
                'runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'comment_media_mirror'
              then coalesce(j.metadata, '{}'::jsonb) || jsonb_build_object(
                'runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            else j.metadata
          end
        where j.id = %s::uuid
          and j.status in ('queued', 'pending', 'retrying')
          and j.available_at <= now()
          and not (
            coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) in (
              'shared_account_discovery',
              'shared_account_posts'
            )
            and not (
              lower(coalesce(j.config->>'runner_strategy', '')) = 'parallel_detail_refresh'
              and greatest(
                case
                  when coalesce(j.config->>'details_refresh_shard_count', '') ~ '^[0-9]+$'
                    then (j.config->>'details_refresh_shard_count')::int
                  else 0
                end,
                case
                  when coalesce(j.config->>'details_refresh_worker_count', '') ~ '^[0-9]+$'
                    then (j.config->>'details_refresh_worker_count')::int
                  else 0
                end,
                case
                  when coalesce(j.config->>'runner_count', '') ~ '^[0-9]+$'
                    then (j.config->>'runner_count')::int
                  else 0
                end
              ) > 1
            )
            and exists (
              select 1
              from social.scrape_jobs active
              where active.id <> j.id
                and active.status = 'running'
                and coalesce(active.config->>'stage', active.metadata->>'stage', active.job_type) in (
                  'shared_account_discovery',
                  'shared_account_posts'
                )
                and lower(coalesce(active.platform, '')) = lower(coalesce(j.platform, ''))
                and lower(coalesce(
                  nullif(trim(active.config->>'account'), ''),
                  nullif(trim(active.config->>'account_handle'), ''),
                  nullif(trim(active.metadata->>'account'), ''),
                  ''
                )) <> ''
                and lower(coalesce(
                  nullif(trim(active.config->>'account'), ''),
                  nullif(trim(active.config->>'account_handle'), ''),
                  nullif(trim(active.metadata->>'account'), ''),
                  ''
                )) = lower(coalesce(
                  nullif(trim(j.config->>'account'), ''),
                  nullif(trim(j.config->>'account_handle'), ''),
                  nullif(trim(j.metadata->>'account'), ''),
                  ''
                ))
            )
          )
        returning
          id::text,
          run_id::text as run_id,
          platform,
          job_type,
          status,
          config,
          metadata,
          attempt_count,
          max_attempts,
          source_scope,
          season_id::text as season_id,
          last_error_code
        """,
        [
            worker_id,
            media_runtime_json,
            media_runtime_json,
            comment_media_runtime_json,
            comment_media_runtime_json,
            media_runtime_json,
            media_runtime_json,
            comment_media_runtime_json,
            comment_media_runtime_json,
            job_id,
        ],
    )


def _update_job_progress(
    job_id: str,
    *,
    items_found: int,
    metadata: dict[str, Any] | None = None,
    worker_id: str | None = None,
) -> bool:
    row = pg.fetch_one(
        """
        update social.scrape_jobs
        set
          items_found = %s,
          metadata = coalesce(metadata, '{}'::jsonb) || %s::jsonb,
          heartbeat_at = now()
        where id = %s
          and status = 'running'
          and claimed_at is not null
          and (
            %s::text is null
            or worker_id is null
            or worker_id = %s::text
            or %s::text like worker_id || '%%'
          )
        returning id::text
        """,
        [items_found, _json_dumps(_metadata_dict(metadata)), job_id, worker_id, worker_id, worker_id],
        pool_name=SOCIAL_CATALOG_PROGRESS_POOL_NAME,
    )
    if not row:
        return False
    _touch_worker_heartbeat_for_job(
        job_id=job_id,
        status="working",
        metadata={"source": "job_progress"},
    )
    return True


def _completed_facebook_shared_posts_save_count(metadata: Mapping[str, Any] | None, items_found: Any) -> int:
    normalized_metadata = _metadata_dict(metadata)
    persist_counters = _metadata_dict(normalized_metadata.get("persist_counters"))
    save_proof = _metadata_dict(normalized_metadata.get("save_proof"))
    activity = _metadata_dict(normalized_metadata.get("activity"))
    return max(
        _normalize_non_negative_int(persist_counters.get("posts_upserted")),
        _normalize_non_negative_int(persist_counters.get("catalog_posts_upserted")),
        _normalize_non_negative_int(save_proof.get("upserted_count")),
        _normalize_non_negative_int(save_proof.get("catalog_rows")),
        _normalize_non_negative_int(activity.get("saved_posts")),
        _normalize_non_negative_int(items_found),
    )


def _cancel_duplicate_active_facebook_shared_post_jobs_after_completed_save(
    *,
    job_id: str,
    run_id: str,
    status: str,
    items_found: Any,
    metadata: Mapping[str, Any] | None,
) -> list[str]:
    normalized_metadata = _metadata_dict(metadata)
    platform = _normalize_platform_name(normalized_metadata.get("platform"))
    stage = str(normalized_metadata.get("stage") or "").strip().lower()
    account = _normalize_account_handle(normalized_metadata.get("account") or normalized_metadata.get("account_handle"))
    if (
        status != "completed"
        or platform != "facebook"
        or stage != SHARED_ACCOUNT_POSTS_STAGE
        or not account
        or not run_id
        or _completed_facebook_shared_posts_save_count(normalized_metadata, items_found) <= 0
    ):
        return []

    rows = cast(_ExecuteReturningWithPool, pg.execute_returning)(
        """
        update social.scrape_jobs j
        set
          status = 'cancelled',
          completed_at = coalesce(completed_at, now()),
          heartbeat_at = now(),
          error_message = coalesce(
            error_message,
            'Duplicate Facebook shared-account posts job cancelled after a completed save.'
          ),
          last_error_code = coalesce(last_error_code, 'duplicate_facebook_shared_posts_completed_save'),
          last_error_class = coalesce(last_error_class, 'DuplicateFacebookSharedPostsJob'),
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'duplicate_cleanup', true,
            'duplicate_cleanup_reason', 'facebook_shared_posts_completed_save',
            'duplicate_completed_job_id', %s::text,
            'duplicate_cleanup_at', now()
          )
        where j.run_id = %s::uuid
          and j.id <> %s::uuid
          and lower(coalesce(j.platform, '')) = 'facebook'
          and lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '')) = %s
          and lower(ltrim(coalesce(
            nullif(j.config->>'account', ''),
            nullif(j.config->>'account_handle', ''),
            nullif(j.config->>'source_account', ''),
            nullif(j.config->>'username', ''),
            ''
          ), '@')) = %s
          and j.status in ('queued', 'pending', 'retrying', 'running', 'cancelling')
          and coalesce(j.config->>'partition_strategy', '') = ''
          and coalesce(j.config->>'runner_strategy', '') not in ('parallel_detail_refresh', 'adaptive_dual_runner')
          and coalesce(j.config->>'shard_index', '') = ''
          and coalesce(j.config->>'details_refresh_shard_index', '') = ''
        returning j.id::text as id
        """,
        [job_id, run_id, job_id, SHARED_ACCOUNT_POSTS_STAGE, account],
        pool_name=SOCIAL_CATALOG_PROGRESS_POOL_NAME,
    )
    cancelled_ids = [str(row.get("id") or "").strip() for row in rows if str(row.get("id") or "").strip()]
    for duplicate_id in cancelled_ids:
        _clear_worker_heartbeat_for_job(
            job_id=duplicate_id,
            status="idle",
            metadata={
                "source": "facebook_duplicate_cleanup",
                "job_status": "cancelled",
                "duplicate_completed_job_id": job_id,
            },
        )
    if cancelled_ids:
        logger.info(
            "[facebook_duplicate_shared_posts_cleanup] run=%s account=%s completed_job=%s cancelled=%s",
            run_id,
            account,
            job_id,
            len(cancelled_ids),
        )
    return cancelled_ids


def _finish_job(
    job_id: str,
    *,
    status: str,
    items_found: int,
    error_message: str | None = None,
    metadata: dict[str, Any] | None = None,
    last_error_code: str | None = None,
    last_error_class: str | None = None,
    next_available_at: datetime | None = None,
    expected_worker_id: str | None = None,
) -> None:
    is_terminal = status in {"completed", "failed", "cancelled"}
    completed_expr = "now()" if is_terminal else "completed_at"
    with pg.db_connection(label="finish_social_scrape_job") as conn:
        with pg.db_cursor(conn=conn, label="finish_social_scrape_job") as cur:
            row = pg.fetch_one_with_cursor(
                cur,
                """
            with prior as (
              select
                id,
                run_id::text as run_id,
                status as prior_status,
                items_found as prior_items_found,
                coalesce(config->>'stage', metadata->>'stage', job_type, 'unknown') as stage,
                metadata as prior_metadata
              from social.scrape_jobs
              where id = %s
              for update
            )
            update social.scrape_jobs
            set
              status = %s,
              items_found = %s,
              error_message = %s,
              completed_at = """
                + completed_expr
                + """,
              metadata = case
                when %s = 'retrying'
                  then (coalesce(prior.prior_metadata, '{}'::jsonb) - 'dispatch') || coalesce(%s::jsonb, '{}'::jsonb)
                when %s = 'completed'
                  then (
                    coalesce(prior.prior_metadata, '{}'::jsonb)
                    - 'error'
                    - 'error_code'
                    - 'error_class'
                    - 'error_message'
                    - 'retryable'
                  ) || coalesce(%s::jsonb, '{}'::jsonb)
                else coalesce(prior.prior_metadata, '{}'::jsonb) || coalesce(%s::jsonb, '{}'::jsonb)
              end,
              heartbeat_at = now(),
              last_error_code = %s,
              last_error_class = %s,
              available_at = coalesce(%s, available_at),
              worker_id = case when %s = 'retrying' then null else worker_id end,
              claimed_at = case when %s = 'retrying' then null else claimed_at end
            from prior
            where social.scrape_jobs.id = prior.id
              and (
                %s::text is null
                or (
                  prior.prior_status = 'running'
                  and social.scrape_jobs.claimed_at is not null
                  and (
                    social.scrape_jobs.worker_id = %s::text
                    or %s::text like social.scrape_jobs.worker_id || '%%'
                  )
                )
              )
            returning
              social.scrape_jobs.id::text as id,
              prior.run_id as run_id,
              prior.prior_status,
              prior.prior_items_found,
              prior.stage
            """,
                [
                    job_id,
                    status,
                    items_found,
                    error_message,
                    status,
                    _json_dumps(_metadata_dict(metadata)),
                    status,
                    _json_dumps(_metadata_dict(metadata)),
                    _json_dumps(_metadata_dict(metadata)),
                    last_error_code,
                    last_error_class,
                    next_available_at,
                    status,
                    status,
                    expected_worker_id,
                    expected_worker_id,
                    expected_worker_id,
                ],
            )
        if row and row.get("run_id"):
            counter_savepoint = "finish_job_counter_sync"
            _create_savepoint(conn, counter_savepoint)
            try:
                cast(_IncrementRunCountersOnJobFinishWithConn, _increment_run_counters_on_job_finish)(
                    run_id=str(row.get("run_id")),
                    stage=str(row.get("stage") or "unknown"),
                    prior_status=str(row.get("prior_status") or ""),
                    new_status=status,
                    prior_items_found=_normalize_non_negative_int(row.get("prior_items_found")),
                    new_items_found=_normalize_non_negative_int(items_found),
                    conn=conn,
                )
            except Exception as exc:  # noqa: BLE001
                if not (pg._is_statement_timeout_error(exc) or isinstance(exc, pg.DatabaseServiceUnavailableError)):
                    raise
                _rollback_to_savepoint(conn, counter_savepoint)
                _release_savepoint(conn, counter_savepoint)
                logger.warning(
                    "[finish_job] run counter sync deferred after job=%s run=%s status=%s error=%s",
                    job_id,
                    str(row.get("run_id") or ""),
                    status,
                    exc,
                )
            else:
                _release_savepoint(conn, counter_savepoint)
    if not row:
        logger.warning(
            "[finish_job] skipped stale finish for job=%s status=%s expected_worker_id=%s",
            job_id,
            status,
            expected_worker_id,
        )
        return
    if status == "completed" and row.get("run_id"):
        try:
            _cancel_duplicate_active_facebook_shared_post_jobs_after_completed_save(
                job_id=job_id,
                run_id=str(row.get("run_id")),
                status=status,
                items_found=items_found,
                metadata=metadata,
            )
        except Exception as exc:  # noqa: BLE001
            if pg._is_statement_timeout_error(exc) or isinstance(exc, pg.DatabaseServiceUnavailableError):
                logger.warning(
                    "[finish_job] facebook duplicate cleanup deferred after job=%s run=%s error=%s",
                    job_id,
                    str(row.get("run_id") or ""),
                    exc,
                )
            else:
                raise
    if is_terminal:
        _clear_worker_heartbeat_for_job(
            job_id=job_id,
            status="idle",
            metadata={"source": "job_finish", "job_status": status},
        )
    else:
        _touch_worker_heartbeat_for_job(
            job_id=job_id,
            status="working",
            metadata={"source": "job_finish", "job_status": status},
        )
    if status in {"retrying", "running", "completed", "failed", "cancelled"}:
        _update_shared_account_partition_status_for_job(
            job_id=job_id,
            status="queued" if status == "retrying" else status,
            metadata_updates={"source": "job_finish", "job_status": status},
        )
    if is_terminal and row.get("run_id"):
        parent_run_id = str(row.get("run_id"))
        try:
            finalize_result = _finalize_run_status(parent_run_id, force_recompute=True)
        except Exception as exc:  # noqa: BLE001
            logger.exception(
                "[finish_job] parent run finalization deferred after job=%s run=%s status=%s",
                job_id,
                parent_run_id,
                status,
            )
            # B3: surface the stuck finalize so it is observable and the
            # recover_unfinalized_terminal_runs sweep can re-drive it.
            _mark_run_finalize_pending(parent_run_id, error_message=str(exc))
        else:
            if isinstance(finalize_result, dict) and finalize_result.get("finalize_deferred"):
                _mark_run_finalize_pending(
                    parent_run_id,
                    error_message=str(finalize_result.get("error") or "finalize_deferred"),
                )
    _invalidate_queue_status_cache()


