def _mark_run_finalize_pending(run_id: str, *, error_message: str | None = None) -> None:
    """B3: persist a visible marker when a parent run's finalization was deferred or
    raised inside _finish_job, so a run stuck non-terminal is observable and the
    recover_unfinalized_terminal_runs sweep can re-drive it. Best-effort — never let
    marker bookkeeping break job completion."""
    normalized = str(run_id or "").strip()
    if not normalized:
        return
    try:
        _merge_catalog_run_config(
            run_id=normalized,
            metadata_updates={
                "finalize_pending": True,
                "finalize_failed_at": _iso(_now_utc()),
                "finalize_error": (str(error_message or "").strip()[:500] or None),
            },
        )
    except Exception:  # noqa: BLE001
        logger.debug("[finish_job] could not persist finalize_pending marker run=%s", normalized[:8])


def _normalize_non_negative_int(value: Any) -> int:
    try:
        return max(0, int(value or 0))
    except (TypeError, ValueError):
        return 0


def _coerce_instagram_reported_comment_candidate(value: Any) -> int:
    if value is None or isinstance(value, bool):
        return 0
    if isinstance(value, (int, float)):
        return _normalize_non_negative_int(value)
    if isinstance(value, Mapping):
        return max(
            _coerce_instagram_reported_comment_candidate(value.get("count")),
            _coerce_instagram_reported_comment_candidate(value.get("total_count")),
        )
    text = str(value or "").strip()
    if not text:
        return 0
    digits = re.sub(r"[^0-9]", "", text)
    return _normalize_non_negative_int(digits) if digits else 0


def _instagram_reported_comment_count_from_payload(payload: Any) -> int:
    if not isinstance(payload, Mapping):
        return 0

    candidates: list[int] = []

    def add(value: Any) -> None:
        candidates.append(_coerce_instagram_reported_comment_candidate(value))

    for key in ("comments_count", "comments", "comment_count", "commentsCount"):
        add(payload.get(key))
    for key in ("edge_media_to_comment", "edge_media_to_parent_comment", "edge_media_preview_comment"):
        add(payload.get(key))
    for nested_key in ("media", "node", "graphql", "metrics"):
        nested = payload.get(nested_key)
        if isinstance(nested, Mapping):
            for key in ("comments_count", "comments", "comment_count", "commentsCount"):
                add(nested.get(key))
            add(nested.get("edge_media_to_comment"))

    return max(candidates or [0])


def _sql_json_text_non_negative_int(expr: str) -> str:
    return f"coalesce(nullif(regexp_replace(coalesce({expr}, ''), '[^0-9]', '', 'g'), '')::bigint, 0)"


def _instagram_reported_comments_sql(alias: str = "p") -> str:
    safe_alias = str(alias or "p").strip() or "p"
    raw = f"coalesce({safe_alias}.raw_data, '{{}}'::jsonb)"
    raw_candidates = [
        f"{raw} ->> 'comments_count'",
        f"{raw} ->> 'comments'",
        f"{raw} ->> 'comment_count'",
        f"{raw} ->> 'commentsCount'",
        f"{raw} -> 'edge_media_to_comment' ->> 'count'",
        f"{raw} -> 'edge_media_to_parent_comment' ->> 'count'",
        f"{raw} -> 'edge_media_preview_comment' ->> 'count'",
        f"{raw} -> 'media' ->> 'comments_count'",
        f"{raw} -> 'media' ->> 'comments'",
        f"{raw} -> 'media' ->> 'comment_count'",
        f"{raw} -> 'media' ->> 'commentsCount'",
        f"{raw} -> 'metrics' ->> 'comments_count'",
        f"{raw} -> 'metrics' ->> 'comments'",
    ]
    raw_expr = ", ".join(_sql_json_text_non_negative_int(expr) for expr in raw_candidates)
    return f"greatest(coalesce({safe_alias}.comments_count, 0), {raw_expr}, 0)"


def _instagram_external_facebook_comments_sql(
    alias: str = "p",
    *,
    fb_comment_count_expr: str | None = None,
) -> str:
    safe_alias = str(alias or "p").strip() or "p"
    raw = f"coalesce({safe_alias}.raw_data, '{{}}'::jsonb)"
    raw_candidates = [
        fb_comment_count_expr if fb_comment_count_expr is not None else f"{safe_alias}.fb_comment_count::text",
        f"{raw} -> 'facebook_crosspost' ->> 'comments_count'",
        f"{raw} -> 'facebook_crosspost' ->> 'fb_comment_count'",
        f"{raw} ->> 'fb_comment_count'",
    ]
    raw_expr = ", ".join(_sql_json_text_non_negative_int(expr) for expr in raw_candidates)
    return f"greatest({raw_expr})"


def _instagram_fetchable_comments_sql(
    alias: str = "p",
    *,
    fb_comment_count_expr: str | None = None,
) -> str:
    reported = _instagram_reported_comments_sql(alias)
    facebook_comments = _instagram_external_facebook_comments_sql(
        alias,
        fb_comment_count_expr=fb_comment_count_expr,
    )
    return f"greatest(({reported}) - ({facebook_comments}), 0)"


def _new_job_progress_state() -> dict[str, Any]:
    return {
        "last_items_found": -1,
        "last_progress_at": None,
    }


def _build_progress_activity_payload(activity: dict[str, Any] | None, *, now: datetime) -> dict[str, Any]:
    payload: dict[str, Any] = {"last_progress_at": _iso(now)}
    if not activity:
        return payload
    if activity.get("phase"):
        payload["phase"] = str(activity.get("phase"))
    for field in (
        "pages_scanned",
        "posts_checked",
        "matched_posts",
        "saved_posts",
        "total_posts",
        "scraped_comments",
        "comments_upserted",
    ):
        if field in activity and activity.get(field) is not None:
            payload[field] = _normalize_non_negative_int(activity.get(field))
    if activity.get("current_source_id") is not None:
        current_source_id = str(activity.get("current_source_id") or "").strip()
        if current_source_id:
            payload["current_source_id"] = current_source_id
    return payload


def _emit_job_progress(
    *,
    job_id: str,
    stage: str,
    platform: str,
    account: str,
    scraped_posts: int,
    scraped_comments: int,
    posts_upserted: int,
    comments_upserted: int,
    activity: dict[str, Any] | None,
    progress_state: dict[str, Any],
    worker_id: str | None = None,
    force: bool = False,
    extra_metadata: dict[str, Any] | None = None,
) -> bool:
    now = _now_utc()
    scraped_posts_value = _normalize_non_negative_int(scraped_posts)
    scraped_comments_value = _normalize_non_negative_int(scraped_comments)
    items_found = scraped_posts_value + scraped_comments_value
    last_items_found = _normalize_non_negative_int(progress_state.get("last_items_found"))
    last_progress_at = _coerce_dt(progress_state.get("last_progress_at"))
    elapsed_seconds = (
        float("inf")
        if last_progress_at is None
        else (
            now - (last_progress_at if last_progress_at.tzinfo else last_progress_at.replace(tzinfo=UTC))
        ).total_seconds()
    )
    delta = abs(items_found - last_items_found)
    if not force:
        if delta < JOB_PROGRESS_MIN_DELTA and elapsed_seconds < JOB_PROGRESS_MAX_INTERVAL_SECONDS:
            return False

    metadata = {
        "stage": stage,
        "platform": platform,
        "account": account,
        "stage_counters": {
            "posts": scraped_posts_value,
            "comments": scraped_comments_value,
        },
        "persist_counters": {
            "posts_upserted": _normalize_non_negative_int(posts_upserted),
            "comments_upserted": _normalize_non_negative_int(comments_upserted),
        },
        "activity": _build_progress_activity_payload(activity, now=now),
    }
    if extra_metadata:
        metadata.update(_metadata_dict(extra_metadata))
    update_kwargs: dict[str, Any] = {"items_found": items_found, "metadata": metadata}
    if worker_id is not None:
        update_kwargs["worker_id"] = worker_id
    updated = _update_job_progress(job_id, **update_kwargs)
    if updated is False:
        return False
    progress_state["last_items_found"] = items_found
    progress_state["last_progress_at"] = now
    return True


def _normalize_social_job_stage_for_stale(stage: Any) -> str:
    normalized = str(stage or "").strip().lower()
    if not normalized:
        return ""
    if normalized in {
        "posts",
        "comments",
        INSTAGRAM_COMMENTS_SCRAPLING_STAGE,
        TIKTOK_POSTS_SCRAPLING_STAGE,
        THREADS_POSTS_SCRAPLING_STAGE,
        "media_mirror",
        "comment_media_mirror",
        SHARED_ACCOUNT_DISCOVERY_STAGE,
        SHARED_ACCOUNT_POSTS_STAGE,
        POST_CLASSIFY_STAGE,
        SEASON_MATERIALIZE_STAGE,
        ANALYTICS_REFRESH_STAGE,
    }:
        return normalized
    if normalized.endswith("_comment_media_mirror"):
        return "comment_media_mirror"
    if normalized.endswith("_media_mirror"):
        return "media_mirror"
    if normalized == "comments" or normalized.endswith("_comments"):
        return "comments"
    if normalized == "posts" or normalized.endswith("_posts"):
        return "posts"
    return normalized


def _resolve_social_job_stale_seconds(*, stage: Any = None, platform: Any = None) -> int:
    base_seconds = _resolve_positive_int_env(
        "SOCIAL_JOB_STALE_SECONDS",
        SOCIAL_JOB_STALE_SECONDS_DEFAULT,
        minimum=30,
    )
    normalized_platform = _normalize_platform_name(platform)
    normalized_stage = _normalize_social_job_stage_for_stale(stage)
    if normalized_platform == "youtube" and normalized_stage == "posts":
        return _resolve_positive_int_env(
            "SOCIAL_JOB_STALE_SECONDS_YOUTUBE_POSTS",
            SOCIAL_JOB_STALE_SECONDS_YOUTUBE_POSTS_DEFAULT,
            minimum=30,
        )
    if normalized_platform == "youtube" and normalized_stage == "comments":
        return _resolve_positive_int_env(
            "SOCIAL_JOB_STALE_SECONDS_YOUTUBE_COMMENTS",
            SOCIAL_JOB_STALE_SECONDS_YOUTUBE_COMMENTS_DEFAULT,
            minimum=30,
        )
    if normalized_stage in SHARED_ACCOUNT_POST_FETCH_STAGES:
        return _resolve_positive_int_env(
            "SOCIAL_JOB_STALE_SECONDS_SHARED_ACCOUNT_POSTS",
            max(base_seconds, 900),
            minimum=30,
        )
    if normalized_platform == "instagram" and normalized_stage == INSTAGRAM_COMMENTS_SCRAPLING_STAGE:
        return _resolve_positive_int_env(
            "SOCIAL_JOB_STALE_SECONDS_INSTAGRAM_COMMENTS_SCRAPLING",
            max(base_seconds, 1800),
            minimum=300,
        )
    if normalized_stage == POST_CLASSIFY_STAGE:
        return _resolve_positive_int_env(
            "SOCIAL_JOB_STALE_SECONDS_POST_CLASSIFY",
            max(base_seconds, 900),
            minimum=30,
        )
    return base_seconds


def _build_social_job_stale_seconds_sql_expr(
    *,
    table_alias: str,
    has_queue_fields: bool = True,
) -> tuple[str, list[Any]]:
    default_seconds = _resolve_social_job_stale_seconds()
    youtube_posts_seconds = _resolve_social_job_stale_seconds(stage="posts", platform="youtube")
    youtube_comments_seconds = _resolve_social_job_stale_seconds(stage="comments", platform="youtube")
    instagram_comments_seconds = _resolve_social_job_stale_seconds(
        stage=INSTAGRAM_COMMENTS_SCRAPLING_STAGE,
        platform="instagram",
    )
    shared_account_posts_seconds = _resolve_social_job_stale_seconds(stage=SHARED_ACCOUNT_POSTS_STAGE)
    post_classify_seconds = _resolve_social_job_stale_seconds(stage=POST_CLASSIFY_STAGE)
    if (
        youtube_posts_seconds == default_seconds
        and youtube_comments_seconds == default_seconds
        and instagram_comments_seconds == default_seconds
        and shared_account_posts_seconds == default_seconds
        and post_classify_seconds == default_seconds
    ):
        return "%s", [default_seconds]

    stage_expr = (
        f"lower(coalesce({table_alias}.config->>'stage', {table_alias}.metadata->>'stage', {table_alias}.job_type, ''))"
        if has_queue_fields
        else f"lower(coalesce({table_alias}.metadata->>'stage', {table_alias}.job_type, ''))"
    )
    platform_expr = f"lower(coalesce({table_alias}.platform, ''))"
    return (
        (
            "case "
            f"when {platform_expr} = 'youtube' and ({stage_expr} = 'posts' or {stage_expr} like '%%_posts') then %s "
            f"when {platform_expr} = 'youtube' and "
            f"({stage_expr} = 'comments' or {stage_expr} like '%%_comments') then %s "
            f"when {platform_expr} = 'instagram' and {stage_expr} = '{INSTAGRAM_COMMENTS_SCRAPLING_STAGE}' then %s "
            f"when {stage_expr} in ("
            f"'{SHARED_ACCOUNT_POSTS_STAGE}', "
            f"'{TIKTOK_POSTS_SCRAPLING_STAGE}', "
            f"'{THREADS_POSTS_SCRAPLING_STAGE}'"
            f") then %s "
            f"when {stage_expr} = '{POST_CLASSIFY_STAGE}' then %s "
            "else %s end"
        ),
        [
            youtube_posts_seconds,
            youtube_comments_seconds,
            instagram_comments_seconds,
            shared_account_posts_seconds,
            post_classify_seconds,
            default_seconds,
        ],
    )


def _resolve_stale_recovery_interval_seconds() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_STALE_RECOVERY_INTERVAL_SEC",
        SOCIAL_STALE_RECOVERY_INTERVAL_SECONDS_DEFAULT,
        minimum=5,
        maximum=600,
    )


def _resolve_run_summary_reconcile_interval_seconds() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_RUN_SUMMARY_RECONCILE_INTERVAL_SEC",
        SOCIAL_RUN_SUMMARY_RECONCILE_INTERVAL_SECONDS_DEFAULT,
        minimum=10,
        maximum=3600,
    )


def _default_job_claim_batch_size_for_stage(stage: Any) -> int:
    normalized_stage = _normalize_social_job_stage_for_stale(stage)
    # Claimed jobs are marked running immediately; claiming multiple post jobs per
    # worker causes later jobs in the batch to age into false stale-heartbeat rows
    # before execution reaches them. Keep queue workers single-claim by default.
    if normalized_stage in {"posts", *SHARED_ACCOUNT_POST_FETCH_STAGES, INSTAGRAM_COMMENTS_SCRAPLING_STAGE}:
        return 1
    return SOCIAL_JOB_CLAIM_BATCH_SIZE_DEFAULT


def _resolve_job_claim_batch_size(default: int | None = None, *, stage: Any = None) -> int:
    fallback = _default_job_claim_batch_size_for_stage(stage) if default is None else int(default)
    return _resolve_int_env_with_bounds(
        "SOCIAL_JOB_CLAIM_BATCH_SIZE",
        fallback,
        minimum=1,
        maximum=SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX,
    )


def _resolve_comment_upsert_batch_size() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_DB_UPSERT_BATCH_SIZE_COMMENTS",
        SOCIAL_DB_UPSERT_BATCH_SIZE_COMMENTS_DEFAULT,
        minimum=1,
        maximum=SOCIAL_DB_UPSERT_BATCH_SIZE_MAX,
    )


def _resolve_post_upsert_batch_size() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_DB_UPSERT_BATCH_SIZE_POSTS",
        SOCIAL_DB_UPSERT_BATCH_SIZE_POSTS_DEFAULT,
        minimum=1,
        maximum=SOCIAL_DB_UPSERT_BATCH_SIZE_MAX,
    )


def _resolve_run_in_flight_cap() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_RUN_IN_FLIGHT_CAP",
        SOCIAL_RUN_IN_FLIGHT_CAP_DEFAULT,
        minimum=1,
        maximum=32,
    )


def _resolve_catalog_run_in_flight_cap() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_CATALOG_RUN_IN_FLIGHT_CAP",
        SOCIAL_CATALOG_RUN_IN_FLIGHT_CAP_DEFAULT,
        minimum=2,
        maximum=32,
    )


def _resolve_youtube_run_in_flight_cap() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_RUN_YOUTUBE_IN_FLIGHT_CAP",
        4,
        minimum=1,
        maximum=32,
    )


def recover_stale_running_jobs(
    *,
    run_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
    account_handle: str | None = None,
    stale_after_seconds: int | None = None,
    limit: int = 50,
) -> list[dict[str, Any]]:
    normalized_account_filter = (
        _normalize_account_handle(account_handle) or str(account_handle or "").strip().lower().lstrip("@") or None
    )
    if stale_after_seconds is not None:
        stale_seconds_expr = "%s"
        stale_seconds_params: list[Any] = [max(30, int(stale_after_seconds))]
    else:
        stale_seconds_expr, stale_seconds_params = _build_social_job_stale_seconds_sql_expr(
            table_alias="j",
            has_queue_fields=True,
        )
    stale_limit = max(1, min(int(limit), 250))
    post_classify_stale_retry_limit = _post_classify_stale_heartbeat_retry_limit()
    terminal_modal_invocation_sql = """
              (
                lower(coalesce(j.metadata #>> '{dispatch,dispatch_backend}', '')) = 'modal'
                AND nullif(j.metadata #>> '{dispatch,remote_invocation_id}', '') IS NOT NULL
                AND lower(coalesce(j.metadata #>> '{dispatch,remote_invocation_status}', ''))
                  NOT IN ('', 'pending', 'running', 'unknown')
              )
    """
    worker_stale_seconds = _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    if stale_after_seconds is not None:
        worker_stale_seconds = max(worker_stale_seconds, max(30, int(stale_after_seconds)))
    stale_worker_claim_sql = f"""
              (
                nullif(coalesce(j.worker_id, ''), '') is not null
                and coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)
                  < now() - (({stale_seconds_expr}) * interval '1 second')
                and not exists (
                  select 1
                  from social.scrape_workers owning_worker
                  where owning_worker.worker_id = j.worker_id
                    and owning_worker.status <> 'stopped'
                    and owning_worker.last_seen_at >= now() - (%s * interval '1 second')
                )
              )
    """

    # Early-exit: cheap EXISTS check avoids the heavier UPDATE+CTE when no
    # stale jobs exist.  With N workers polling every 30 s this turns N full
    # scans into N lightweight probes for the common (no-stale) case.
    has_stale = pg.fetch_one(
        f"""
        SELECT EXISTS(
            SELECT 1 FROM social.scrape_jobs j
            WHERE j.status in ('running', 'cancelling')
              AND (
                coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)
                  < now() - (({stale_seconds_expr}) * interval '1 second')
                OR {terminal_modal_invocation_sql}
                OR {stale_worker_claim_sql}
              )
              AND NOT (
                lower(coalesce(j.metadata #>> '{{dispatch,dispatch_backend}}', '')) = 'modal'
                AND nullif(j.metadata #>> '{{dispatch,remote_invocation_id}}', '') IS NOT NULL
                AND (
                  lower(coalesce(j.metadata #>> '{{dispatch,remote_invocation_status}}', '')) = 'pending'
                  OR (
                    lower(coalesce(j.metadata #>> '{{dispatch,remote_invocation_status}}', ''))
                      IN ('running', 'unknown')
                    AND nullif(j.metadata #>> '{{dispatch,lease_expires_at}}', '') IS NOT NULL
                    AND (j.metadata #>> '{{dispatch,lease_expires_at}}') ~ '^[0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}}'
                    AND (j.metadata #>> '{{dispatch,lease_expires_at}}')::timestamptz > now()
                  )
                )
              )
              AND (%s::uuid is null or j.run_id = %s::uuid)
              AND (
                %s::text is null
                OR coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s::text
              )
              AND (%s::text is null or j.platform = %s::text)
              AND (
                %s::text is null
                OR lower(coalesce(
                  nullif(trim(j.config->>'account'), ''),
                  nullif(trim(j.config->>'account_handle'), ''),
                  nullif(trim(j.config->>'source_account'), ''),
                  nullif(trim(j.config->>'username'), ''),
                  nullif(trim(j.metadata->>'account'), ''),
                  nullif(trim(j.metadata->>'account_handle'), ''),
                  nullif(trim(j.metadata->>'source_account'), ''),
                  nullif(trim(j.metadata->>'username'), ''),
                  ''
                )) = %s::text
              )
            LIMIT 1
        ) AS has_stale
        """,
        [
            *stale_seconds_params,
            *stale_seconds_params,
            worker_stale_seconds,
            run_id,
            run_id,
            stage,
            stage,
            platform,
            platform,
            normalized_account_filter,
            normalized_account_filter,
        ],
    )
    if not (has_stale and has_stale.get("has_stale")):
        return []

    recovered_rows = pg.fetch_all(
        f"""
        with stale_candidates as (
          select
            j.id,
            j.run_id::text as run_id,
            j.platform,
            coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, '') as stage,
            (j.status = 'cancelling') as was_cancelling,
            lower(coalesce(
              nullif(trim(j.config->>'account'), ''),
              nullif(trim(j.config->>'account_handle'), ''),
              nullif(trim(j.config->>'source_account'), ''),
              nullif(trim(j.config->>'username'), ''),
              nullif(trim(j.metadata->>'account'), ''),
              nullif(trim(j.metadata->>'account_handle'), ''),
              nullif(trim(j.metadata->>'source_account'), ''),
              nullif(trim(j.metadata->>'username'), ''),
              ''
            )) as account_handle,
            j.worker_id as prior_worker_id,
            j.attempt_count,
            j.max_attempts,
            coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at) as stale_sort_at,
            {terminal_modal_invocation_sql} as terminal_modal_invocation,
            {stale_worker_claim_sql} as stale_worker_claim,
            case
              when coalesce(j.metadata->>'post_classify_stale_heartbeat_retry_count', '') ~ '^[0-9]+$'
              then (j.metadata->>'post_classify_stale_heartbeat_retry_count')::int
              else 0
            end as post_classify_stale_heartbeat_retry_count,
            case
              when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type)
                = '{INSTAGRAM_COMMENTS_SCRAPLING_STAGE}'
              then
                case
                  when jsonb_typeof(j.config->'target_source_ids') = 'array'
                  then (
                    select coalesce(jsonb_agg(target.value order by target.ordinality), '[]'::jsonb)
                    from jsonb_array_elements(j.config->'target_source_ids') with ordinality
                      as target(value, ordinality)
                    where
                      target.ordinality > greatest(
                        0,
                        case
                          when coalesce(
                            j.metadata #>> '{{activity,posts_checked}}',
                            j.metadata #>> '{{activity,saved_posts}}',
                            '0'
                          ) ~ '^[0-9]+$'
                          then coalesce(
                            j.metadata #>> '{{activity,posts_checked}}',
                            j.metadata #>> '{{activity,saved_posts}}',
                            '0'
                          )::int
                          else 0
                        end
                      )
                      or target.value #>> '{{}}' in (
                        select skipped.value
                        from (
                          select value
                          from jsonb_array_elements_text(
                            case
                              when jsonb_typeof(j.metadata->'incomplete_target_source_ids') = 'array'
                                then j.metadata->'incomplete_target_source_ids'
                              else '[]'::jsonb
                            end
                          )
                          union
                          select value
                          from jsonb_array_elements_text(
                            case
                              when jsonb_typeof(j.metadata #> '{{activity,incomplete_target_source_ids}}') = 'array'
                                then j.metadata #> '{{activity,incomplete_target_source_ids}}'
                              else '[]'::jsonb
                            end
                          )
                          union
                          select value
                          from jsonb_array_elements_text(
                            case
                              when jsonb_typeof(j.metadata->'auth_failed_target_source_ids') = 'array'
                                then j.metadata->'auth_failed_target_source_ids'
                              else '[]'::jsonb
                            end
                          )
                          union
                          select value
                          from jsonb_array_elements_text(
                            case
                              when jsonb_typeof(j.metadata #> '{{activity,auth_failed_target_source_ids}}') = 'array'
                                then j.metadata #> '{{activity,auth_failed_target_source_ids}}'
                              else '[]'::jsonb
                            end
                          )
                          union
                          select value
                          from jsonb_array_elements_text(
                            case
                              when jsonb_typeof(j.metadata #> '{{post_auth_failures,target_source_ids}}') = 'array'
                                then j.metadata #> '{{post_auth_failures,target_source_ids}}'
                              else '[]'::jsonb
                            end
                          )
                        ) as skipped(value)
                        where nullif(btrim(skipped.value), '') is not null
                      )
                  )
                  when jsonb_array_length(
                    case
                      when jsonb_typeof(j.metadata #> '{{retry_rebalance,remaining_target_source_ids}}') = 'array'
                        then j.metadata #> '{{retry_rebalance,remaining_target_source_ids}}'
                      else '[]'::jsonb
                    end
                  ) > 0
                  then
                    case
                      when jsonb_typeof(j.metadata #> '{{retry_rebalance,remaining_target_source_ids}}') = 'array'
                        then j.metadata #> '{{retry_rebalance,remaining_target_source_ids}}'
                      else '[]'::jsonb
                    end
                  else '[]'::jsonb
                end
              else '[]'::jsonb
            end as comments_recovery_target_source_ids
          from social.scrape_jobs j
          where j.status in ('running', 'cancelling')
            and (
              coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at) <
                now() - (({stale_seconds_expr}) * interval '1 second')
              or {terminal_modal_invocation_sql}
              or {stale_worker_claim_sql}
            )
            and not (
              lower(coalesce(j.metadata #>> '{{dispatch,dispatch_backend}}', '')) = 'modal'
              and nullif(j.metadata #>> '{{dispatch,remote_invocation_id}}', '') is not null
              and (
                lower(coalesce(j.metadata #>> '{{dispatch,remote_invocation_status}}', '')) = 'pending'
                or (
                  lower(coalesce(j.metadata #>> '{{dispatch,remote_invocation_status}}', ''))
                    in ('running', 'unknown')
                  and nullif(j.metadata #>> '{{dispatch,lease_expires_at}}', '') is not null
                  and (j.metadata #>> '{{dispatch,lease_expires_at}}') ~ '^[0-9]{{4}}-[0-9]{{2}}-[0-9]{{2}}'
                  and (j.metadata #>> '{{dispatch,lease_expires_at}}')::timestamptz > now()
                )
              )
            )
            and (%s::uuid is null or j.run_id = %s::uuid)
            and (
              %s::text is null
              or coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s::text
            )
            and (%s::text is null or j.platform = %s::text)
            and (
              %s::text is null
              or lower(coalesce(
                nullif(trim(j.config->>'account'), ''),
                nullif(trim(j.config->>'account_handle'), ''),
                nullif(trim(j.config->>'source_account'), ''),
                nullif(trim(j.config->>'username'), ''),
                nullif(trim(j.metadata->>'account'), ''),
                nullif(trim(j.metadata->>'account_handle'), ''),
                nullif(trim(j.metadata->>'source_account'), ''),
                nullif(trim(j.metadata->>'username'), ''),
                ''
              )) = %s::text
            )
          for update skip locked
        ),
        stale_jobs as (
          select
            stale_candidates.*,
            (
              stale_candidates.was_cancelling = false
              and stale_candidates.attempt_count < stale_candidates.max_attempts
              or (
                stale_candidates.was_cancelling = false
                and
                stale_candidates.stage = %s
                and stale_candidates.post_classify_stale_heartbeat_retry_count < %s
              )
            ) as should_retry
          from stale_candidates
          order by stale_sort_at asc
          limit %s
        )
        update social.scrape_jobs as j
        set
          status = case
            when stale_jobs.was_cancelling then 'cancelled'
            when stale_jobs.should_retry then 'retrying'
            else 'failed'
          end,
          config = case
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s
              and jsonb_array_length(stale_jobs.comments_recovery_target_source_ids) > 0
            then coalesce(j.config, '{{}}'::jsonb) || jsonb_build_object(
              'target_source_ids',
              stale_jobs.comments_recovery_target_source_ids,
              'comments_retry_rebalance',
              true,
              'comments_retry_rebalance_source_job_id',
              j.id::text,
              'comments_shard_target_count',
              jsonb_array_length(stale_jobs.comments_recovery_target_source_ids)
            )
            else j.config
          end,
          completed_at = case
            when stale_jobs.should_retry then j.completed_at
            else now()
          end,
          available_at = case
            when stale_jobs.should_retry
              then now() + (
                greatest(5, least(300, 5 * power(2, greatest(0, j.attempt_count - 1))))
                * interval '1 second'
              )
            else j.available_at
          end,
          error_message = case
            when stale_jobs.was_cancelling then format(
              'cancelled_stale_timeout: cancellation not observed for >= %%s seconds',
              ({stale_seconds_expr})::int
            )
            when stale_jobs.terminal_modal_invocation then format(
              'modal_invocation_terminal: remote invocation status=%%s',
              lower(coalesce(j.metadata #>> '{{dispatch,remote_invocation_status}}', 'unknown'))
            )
            when stale_jobs.stale_worker_claim then format(
              'stale_worker_claim: claimed worker heartbeat missing or stale for >= %%s seconds',
              %s::int
            )
            else format(
              'stale_heartbeat_timeout: no heartbeat for >= %%s seconds',
              ({stale_seconds_expr})::int
            )
          end,
          claimed_at = null,
          worker_id = null,
          heartbeat_at = now(),
          last_error_code = case
            when stale_jobs.was_cancelling then 'cancelled_stale_timeout'
            when stale_jobs.terminal_modal_invocation then 'modal_invocation_terminal'
            when stale_jobs.stale_worker_claim then 'stale_worker_claim'
            else 'stale_heartbeat_timeout'
          end,
          last_error_class = case
            when stale_jobs.was_cancelling then 'CancelledStaleTimeout'
            when stale_jobs.terminal_modal_invocation then 'ModalInvocationTerminal'
            when stale_jobs.stale_worker_claim then 'StaleWorkerClaim'
            else 'HeartbeatTimeout'
          end,
          metadata = coalesce(j.metadata, '{{}}'::jsonb) || jsonb_build_object(
            'error_code', case
              when stale_jobs.was_cancelling then 'cancelled_stale_timeout'
              when stale_jobs.terminal_modal_invocation then 'modal_invocation_terminal'
              when stale_jobs.stale_worker_claim then 'stale_worker_claim'
              else 'stale_heartbeat_timeout'
            end,
            'error_class', case
              when stale_jobs.was_cancelling then 'CancelledStaleTimeout'
              when stale_jobs.terminal_modal_invocation then 'ModalInvocationTerminal'
              when stale_jobs.stale_worker_claim then 'StaleWorkerClaim'
              else 'HeartbeatTimeout'
            end,
            'retryable', case when stale_jobs.was_cancelling then false else (j.attempt_count < j.max_attempts) end,
            'cancelled', stale_jobs.was_cancelling,
            'cancel_scope', case when stale_jobs.was_cancelling then 'job' else null end,
            'stale_heartbeat_timeout_seconds', case
              when stale_jobs.terminal_modal_invocation or stale_jobs.stale_worker_claim then null
              else ({stale_seconds_expr})::int
            end,
            'stale_worker_claim_timeout_seconds', case
              when stale_jobs.stale_worker_claim then %s::int
              else null
            end,
            'terminal_modal_invocation_status', case
              when stale_jobs.terminal_modal_invocation
              then lower(coalesce(j.metadata #>> '{{dispatch,remote_invocation_status}}', 'unknown'))
              else null
            end,
            'stale_recovered_at', now()
          ) || case
            when stale_jobs.stage = %s
              and j.attempt_count >= j.max_attempts
              and stale_jobs.post_classify_stale_heartbeat_retry_count < %s
            then jsonb_build_object(
              'post_classify_stale_heartbeat_retry_count',
              stale_jobs.post_classify_stale_heartbeat_retry_count + 1,
              'post_classify_stale_heartbeat_retry_limit',
              %s
            )
            else '{{}}'::jsonb
          end
        from stale_jobs
        where j.id = stale_jobs.id
        returning
          j.id::text as id,
          stale_jobs.run_id as run_id,
          stale_jobs.platform as platform,
          stale_jobs.stage as stage,
          stale_jobs.account_handle as account_handle,
          stale_jobs.prior_worker_id as prior_worker_id,
          j.status,
          j.attempt_count,
          j.max_attempts
        """,
        [
            *stale_seconds_params,
            worker_stale_seconds,
            *stale_seconds_params,
            *stale_seconds_params,
            worker_stale_seconds,
            run_id,
            run_id,
            stage,
            stage,
            platform,
            platform,
            normalized_account_filter,
            normalized_account_filter,
            POST_CLASSIFY_STAGE,
            post_classify_stale_retry_limit,
            stale_limit,
            INSTAGRAM_COMMENTS_SCRAPLING_STAGE,
            *stale_seconds_params,
            worker_stale_seconds,
            *stale_seconds_params,
            *stale_seconds_params,
            worker_stale_seconds,
            POST_CLASSIFY_STAGE,
            post_classify_stale_retry_limit,
            post_classify_stale_retry_limit,
        ],
    )
    if not recovered_rows:
        return []

    for row in recovered_rows:
        if row.get("id"):
            _clear_worker_heartbeat_for_job(
                job_id=str(row.get("id")),
                status="idle",
                metadata={"source": "stale_recovery", "job_status": row.get("status")},
            )
        normalized_stage = str(row.get("stage") or "").strip().lower()
        normalized_platform = _normalize_platform_name(row.get("platform"))
        normalized_account = _normalize_account_handle(row.get("account_handle"))
        prior_worker_id = str(row.get("prior_worker_id") or "").strip() or None
        prior_lease_owner = prior_worker_id or str(row.get("id") or "").strip() or None
        if (
            normalized_stage in SHARED_ACCOUNT_POST_FETCH_STAGES
            and normalized_platform
            and normalized_account
            and prior_lease_owner
        ):
            frontier = _get_shared_account_run_frontier(
                run_id=str(row.get("run_id") or "").strip(),
                platform=normalized_platform,
                account_handle=normalized_account,
            )
            if str(frontier.get("lease_owner") or "").strip() == prior_lease_owner:
                recovery_status = "retrying" if str(row.get("status") or "").strip().lower() == "retrying" else "failed"
                _record_stalled_frontier_recovery_details(
                    run_id=str(row.get("run_id") or "").strip(),
                    platform=normalized_platform,
                    account_handle=normalized_account,
                    job_id=str(row.get("id") or "").strip(),
                    prior_worker_id=prior_worker_id,
                    prior_lease_owner=prior_lease_owner,
                    recovery_status=recovery_status,
                    frontier=frontier,
                )
                _release_shared_account_run_frontier(
                    run_id=str(row.get("run_id") or "").strip(),
                    platform=normalized_platform,
                    account_handle=normalized_account,
                    lease_owner=prior_lease_owner,
                    status=recovery_status,
                )

    affected_run_ids = sorted({str(row.get("run_id") or "") for row in recovered_rows if row.get("run_id")})
    for stale_run_id in affected_run_ids:
        if any(
            str(row.get("run_id") or "").strip() == stale_run_id
            and _normalize_platform_name(row.get("platform")) == "instagram"
            for row in recovered_rows
        ):
            repair_instagram_canonical_metrics_for_run(stale_run_id)
        _finalize_run_status(stale_run_id, force_recompute=True)
    return recovered_rows


def recover_stale_unclaimed_dispatched_jobs(
    *,
    run_id: str | None = None,
    platform: str | None = None,
    account_handle: str | None = None,
    limit: int = 50,
) -> list[dict[str, Any]]:
    from trr_backend.socials.control_plane.dispatch_runtime import (
        recover_stale_unclaimed_dispatched_jobs as impl,
    )

    return impl(
        run_id=run_id,
        platform=platform,
        account_handle=account_handle,
        limit=limit,
    )


cast(Any, recover_stale_unclaimed_dispatched_jobs).__trr_delegates_to_control_plane__ = True


def _parse_platform_time(ts: Any) -> datetime | None:
    """Parse a platform timestamp (unix int/float or ISO string) to UTC datetime."""
    if isinstance(ts, int):
        return datetime.fromtimestamp(ts, tz=UTC)
    if isinstance(ts, float):
        return datetime.fromtimestamp(int(ts), tz=UTC)
    return _coerce_dt(ts)


# Backwards-compatible aliases
_parse_instagram_time = _parse_platform_time
_parse_tiktok_time = _parse_platform_time


def _youtube_duration_iso(duration_seconds: int | None) -> str:
    seconds = max(0, int(duration_seconds or 0))
    return f"PT{seconds}S"


def _youtube_parse_iso_duration_seconds(value: Any) -> int:
    raw = str(value or "").strip().upper()
    if not raw:
        return 0
    match = re.fullmatch(r"PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?", raw)
    if not match:
        return 0
    hours = int(match.group(1) or 0)
    minutes = int(match.group(2) or 0)
    seconds = int(match.group(3) or 0)
    return max(0, hours * 3600 + minutes * 60 + seconds)


def _youtube_transcript_ingest_enabled() -> bool:
    return _env_truthy(
        "SOCIAL_YOUTUBE_TRANSCRIPT_INGEST_ENABLED",
        default=SOCIAL_YOUTUBE_TRANSCRIPT_INGEST_ENABLED_DEFAULT,
    )


def _extract_media_asset_meta_from_raw_data(value: Any) -> dict[str, Any]:
    if isinstance(value, dict):
        payload = value.get("media_asset_meta")
        if isinstance(payload, dict):
            return dict(payload)
    return {}


def _youtube_fetch_single_video_metadata(video_id: str) -> dict[str, Any] | None:
    normalized_video_id = str(video_id or "").strip()
    if not normalized_video_id:
        return None
    watch_url = f"https://www.youtube.com/watch?v={normalized_video_id}"
    try:
        proc = subprocess.run(
            [
                "yt-dlp",
                "--dump-single-json",
                "--no-playlist",
                "--skip-download",
                watch_url,
            ],
            capture_output=True,
            text=True,
            timeout=60,
            check=False,
        )
    except Exception:
        return None
    if proc.returncode != 0:
        return None
    try:
        payload = json.loads(proc.stdout or "{}")
    except json.JSONDecodeError:
        return None
    return payload if isinstance(payload, dict) else None


def _youtube_channel_sync_state_supported() -> bool:
    return _relation_exists("social.youtube_channel_sync_state")


def _youtube_video_sync_state_supported() -> bool:
    return _relation_exists("social.youtube_video_sync_state")


def _load_youtube_channel_sync_state(
    *,
    season_id: str,
    source_scope: str,
    account_handle: str,
) -> dict[str, Any] | None:
    if not _youtube_channel_sync_state_supported():
        return None
    normalized_account = _normalize_account_handle(account_handle)
    if not normalized_account:
        return None
    try:
        normalized_season_id = str(UUID(str(season_id)))
    except (TypeError, ValueError, AttributeError):
        return None
    try:
        return pg.fetch_one(
            """
            select
              id::text,
              season_id::text,
              show_id::text,
              source_scope,
              account_handle,
              channel_id,
              youtube_source_mode,
              last_discovery_source,
              last_page_token,
              last_cursor_published_at,
              last_discovery_started_at,
              last_discovery_completed_at,
              last_stats_refresh_at,
              last_failure_reason,
              diagnostics,
              updated_at
            from social.youtube_channel_sync_state
            where season_id = %s::uuid
              and source_scope = %s
              and account_handle = %s
            """,
            [normalized_season_id, source_scope, normalized_account],
        )
    except Exception:
        logger.debug(
            "Failed loading youtube channel sync state for season=%s scope=%s account=%s",
            season_id,
            source_scope,
            normalized_account,
            exc_info=True,
        )
        return None


def _save_youtube_channel_sync_state(
    context: SeasonContext,
    *,
    source_scope: str,
    account_handle: str,
    youtube_source_mode: str,
    channel_id: str | None = None,
    last_discovery_source: str | None = None,
    last_page_token: str | None = None,
    last_cursor_published_at: datetime | None = None,
    last_discovery_started_at: datetime | None = None,
    last_discovery_completed_at: datetime | None = None,
    last_stats_refresh_at: datetime | None = None,
    last_failure_reason: str | None = None,
    diagnostics: dict[str, Any] | None = None,
    conn: Any | None = None,
) -> None:
    if not _youtube_channel_sync_state_supported():
        return
    normalized_account = _normalize_account_handle(account_handle)
    if not normalized_account:
        return
    with pg.db_cursor(conn=conn) as cur:
        pg.fetch_one_with_cursor(
            cur,
            """
            insert into social.youtube_channel_sync_state (
              season_id,
              show_id,
              source_scope,
              account_handle,
              channel_id,
              youtube_source_mode,
              last_discovery_source,
              last_page_token,
              last_cursor_published_at,
              last_discovery_started_at,
              last_discovery_completed_at,
              last_stats_refresh_at,
              last_failure_reason,
              diagnostics,
              updated_at
            )
            values (
              %s::uuid,
              %s::uuid,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s,
              %s::jsonb,
              now()
            )
            on conflict (season_id, source_scope, account_handle) do update
            set
              show_id = excluded.show_id,
              channel_id = excluded.channel_id,
              youtube_source_mode = excluded.youtube_source_mode,
              last_discovery_source = excluded.last_discovery_source,
              last_page_token = excluded.last_page_token,
              last_cursor_published_at = excluded.last_cursor_published_at,
              last_discovery_started_at = excluded.last_discovery_started_at,
              last_discovery_completed_at = excluded.last_discovery_completed_at,
              last_stats_refresh_at = excluded.last_stats_refresh_at,
              last_failure_reason = excluded.last_failure_reason,
              diagnostics = excluded.diagnostics,
              updated_at = now()
            returning id::text
            """,
            [
                context.season_id,
                context.show_id,
                source_scope,
                normalized_account,
                str(channel_id or "").strip() or None,
                _normalize_youtube_source_mode(youtube_source_mode),
                str(last_discovery_source or "").strip() or None,
                str(last_page_token or "").strip() or None,
                _coerce_dt(last_cursor_published_at),
                _coerce_dt(last_discovery_started_at),
                _coerce_dt(last_discovery_completed_at),
                _coerce_dt(last_stats_refresh_at),
                str(last_failure_reason or "").strip() or None,
                json.dumps(dict(diagnostics or {})),
            ],
        )


