def _twitter_catalog_row_to_tweet(row: Mapping[str, Any], *, account_handle: str) -> Tweet | None:
    source_id = str(row.get("source_id") or "").strip()
    if not source_id:
        return None

    raw_data = _metadata_dict(row.get("raw_data"))
    posted_at = _coerce_dt(row.get("posted_at")) or _coerce_dt(raw_data.get("date_time"))
    created_at = int(posted_at.timestamp()) if posted_at else 0
    text = str(row.get("text") or raw_data.get("text") or "").strip()
    account = _normalize_account_handle(row.get("source_account") or raw_data.get("username") or account_handle)
    account = account or _normalize_account_handle(account_handle) or str(account_handle or "").strip().lstrip("@")
    permalink = _first_non_empty_str(row.get("permalink"), raw_data.get("url"), raw_data.get("permalink"))
    media_urls = _as_text_list(row.get("media_urls") or raw_data.get("media_urls"))
    hosted_media_urls = _as_text_list(raw_data.get("hosted_media_urls"))
    hashtags = _normalize_unique_terms(
        [*_as_text_list(row.get("hashtags") or raw_data.get("hashtags"), strip_prefix="#"), *_parse_hashtags(text)]
    )
    mentions = _normalize_unique_terms(
        [
            *_as_text_list(row.get("mentions") or raw_data.get("mentions"), prefix="@", strip_prefix="@"),
            *_parse_mentions(text),
        ]
    )
    display_name = str(
        raw_data.get("display_name")
        or raw_data.get("name")
        or raw_data.get("full_name")
        or row.get("source_account")
        or account
        or ""
    ).strip()
    user_profile_url = _first_non_empty_str(
        raw_data.get("user_profile_url"),
        raw_data.get("profile_url"),
        _platform_profile_url_for_handle("twitter", account),
    )
    user_avatar_url = _best_profile_avatar_url(
        [
            raw_data.get("user_avatar_url"),
            raw_data.get("avatar_url"),
            raw_data.get("profile_image_url"),
        ]
    )
    replies_count = max(
        _normalize_non_negative_int(row.get("replies_count")),
        _normalize_non_negative_int(row.get("comments_count")),
        _normalize_non_negative_int(raw_data.get("replies")),
        _normalize_non_negative_int(raw_data.get("replies_count")),
    )
    retweets = max(
        _normalize_non_negative_int(row.get("retweets")),
        _normalize_non_negative_int(raw_data.get("retweets")),
    )
    shares = max(
        _normalize_non_negative_int(row.get("shares")),
        _normalize_non_negative_int(raw_data.get("shares")),
        retweets,
    )
    thread_root = (
        str(row.get("thread_root_source_id") or raw_data.get("thread_root_tweet_id") or "").strip() or source_id
    )
    thread_position: int | None = None
    raw_thread_position = row.get("thread_position", raw_data.get("thread_position"))
    if raw_thread_position is not None:
        try:
            thread_position = int(raw_thread_position)
        except (TypeError, ValueError):
            thread_position = None

    return Tweet(
        tweet_id=source_id,
        date_time=posted_at.strftime("%Y-%m-%d %H:%M:%S") if posted_at else str(raw_data.get("date_time") or ""),
        created_at=created_at,
        text=text,
        hashtags=hashtags,
        mentions=mentions,
        likes=max(_normalize_non_negative_int(row.get("likes")), _normalize_non_negative_int(raw_data.get("likes"))),
        retweets=retweets,
        replies=replies_count,
        quotes=max(_normalize_non_negative_int(row.get("quotes")), _normalize_non_negative_int(raw_data.get("quotes"))),
        views=max(_normalize_non_negative_int(row.get("views")), _normalize_non_negative_int(raw_data.get("views"))),
        url=(
            permalink
            or _shared_catalog_post_url("twitter", account_handle=account, source_id=source_id, explicit=None)
            or ""
        ),
        username=account,
        display_name=display_name,
        user_verified=bool(raw_data.get("user_verified") or raw_data.get("is_verified")),
        is_reply=False,
        is_retweet=bool(raw_data.get("is_retweet")),
        is_quote=bool(raw_data.get("is_quote")),
        reply_to_tweet_id=None,
        quoted_tweet_id=str(raw_data.get("quoted_tweet_id") or "").strip() or None,
        media_urls=media_urls,
        hosted_media_urls=hosted_media_urls,
        link_preview_media_count=_normalize_non_negative_int(raw_data.get("link_preview_media_count")),
        user_id=str(raw_data.get("user_id") or "").strip() or None,
        user_profile_url=user_profile_url,
        user_avatar_url=user_avatar_url,
        bookmarks=max(
            _normalize_non_negative_int(row.get("bookmarks")),
            _normalize_non_negative_int(raw_data.get("bookmarks")),
        ),
        shares=shares,
        thread_root_tweet_id=thread_root,
        thread_position=thread_position if thread_position is not None else 0,
        is_thread_part=bool(row.get("is_thread_part") or raw_data.get("is_thread_part") or thread_root != source_id),
        twitter_context_role=str(raw_data.get("twitter_context_role") or "").strip() or "account_post",
    )


def _load_existing_twitter_account_catalog_posts(
    *,
    account_handle: str,
    date_start: datetime | None,
    date_end: datetime | None,
    **_kwargs: Any,
) -> list[Tweet]:
    normalized_account = _normalize_account_handle(account_handle)
    if not normalized_account:
        return []

    config = _metadata_dict(_kwargs.get("config"))
    raw_anchor_source_ids = config.get("comment_anchor_source_ids")
    if isinstance(raw_anchor_source_ids, Mapping):
        platform_anchor_source_ids = None
        for key, value in raw_anchor_source_ids.items():
            if str(key or "").strip().lower() in {"twitter", "x"}:
                platform_anchor_source_ids = value
                break
        raw_anchor_source_ids = platform_anchor_source_ids
    if isinstance(raw_anchor_source_ids, str):
        anchor_source_candidates = [raw_anchor_source_ids]
    elif isinstance(raw_anchor_source_ids, (list, tuple, set)):
        anchor_source_candidates = list(raw_anchor_source_ids)
    else:
        anchor_source_candidates = []
    anchor_source_ids = list(
        dict.fromkeys(str(item or "").strip() for item in anchor_source_candidates if str(item or "").strip())
    )
    conditions = ["ltrim(lower(coalesce(nullif(source_account, ''), '')), '@') = %s"]
    params: list[Any] = [normalized_account]
    if anchor_source_ids:
        conditions.append("source_id = any(%s::text[])")
        params.append(anchor_source_ids)
    if date_start is not None:
        conditions.append("posted_at >= %s")
        params.append(date_start)
    if date_end is not None:
        conditions.append("posted_at < %s")
        params.append(date_end)
    where = " and ".join(conditions)
    rows = pg.fetch_all(
        f"""
        select
          source_id,
          source_account,
          posted_at,
          permalink,
          text,
          media_urls,
          hashtags,
          mentions,
          likes,
          comments_count,
          views,
          shares,
          retweets,
          replies_count,
          quotes,
          raw_data,
          bookmarks,
          thread_root_source_id,
          thread_position,
          is_thread_part
        from social.twitter_account_catalog_posts
        where {where}
        order by posted_at asc nulls last, source_id asc
        """,
        params,
    )
    tweets: list[Tweet] = []
    seen_source_ids: set[str] = set()
    for row in rows:
        tweet = _twitter_catalog_row_to_tweet(row, account_handle=normalized_account)
        if tweet is None or tweet.tweet_id in seen_source_ids:
            continue
        seen_source_ids.add(tweet.tweet_id)
        tweets.append(tweet)
    return tweets


def _post_identity_from_row(platform: str, row: dict[str, Any]) -> str:
    normalized_platform = (platform or "").strip().lower()
    if normalized_platform == "instagram":
        return str(row.get("shortcode") or "")
    if normalized_platform == "tiktok":
        return str(row.get("video_id") or "")
    if normalized_platform == "youtube":
        return str(row.get("video_id") or "")
    if normalized_platform == "twitter":
        return str(row.get("tweet_id") or "")
    if normalized_platform in {"facebook", "threads"}:
        return str(row.get("post_id") or "")
    return ""


def _build_existing_post_lookup(platform: str, rows: list[dict[str, Any]]) -> dict[str, dict[str, Any]]:
    normalized_platform = (platform or "").strip().lower()
    lookup: dict[str, dict[str, Any]] = {}
    for row in rows:
        if normalized_platform == "twitter" and bool(row.get("is_reply")):
            continue
        identity = _post_identity_from_row(normalized_platform, row)
        if identity:
            lookup[identity] = row
    return lookup


def _normalize_conflict_columns(conflict_col: str | Sequence[str]) -> tuple[str, ...]:
    if isinstance(conflict_col, str):
        candidates = [conflict_col]
    else:
        candidates = list(conflict_col)
    normalized = tuple(dict.fromkeys(str(column).strip() for column in candidates if str(column).strip()))
    if not normalized:
        raise ValueError("conflict_col must include at least one column")
    return normalized


def _expected_comment_count_for_platform(
    platform: str,
    row_or_post: dict[str, Any],
    *,
    snapshot: CommentLifecycleSnapshot | None = None,
) -> int:
    normalized_platform = (platform or "").strip().lower()
    if normalized_platform == "twitter":
        replies = _normalize_non_negative_int(row_or_post.get("replies_count"))
        quotes = _normalize_non_negative_int(row_or_post.get("quotes"))
        return replies + quotes
    if normalized_platform == "threads":
        replies = _normalize_non_negative_int(row_or_post.get("replies_count"))
        quotes = _normalize_non_negative_int(row_or_post.get("quotes"))
        return replies + quotes
    expected = _normalize_non_negative_int(row_or_post.get("comments_count"))
    if normalized_platform == "instagram":
        expected = max(expected, _instagram_reported_comment_count_from_payload(row_or_post.get("raw_data")))
    if normalized_platform == "youtube" and expected <= 0 and snapshot is not None:
        return _normalize_non_negative_int(snapshot.active_count)
    return expected


def _pg_upsert(
    table: str,
    payload: dict[str, Any],
    *,
    conflict_col: str | Sequence[str],
    conn: Any | None = None,
    include_inserted_flag: bool = False,
) -> dict[str, Any] | None:
    """Upsert a row into social.{table} using direct SQL (psycopg2).

    This avoids Supabase PostgREST schema-cache (PGRST002) errors that
    occur intermittently with the ``social`` schema.
    """
    adapted = _adapt_payload_json_values(payload)

    cols = list(adapted.keys())
    conflict_cols = _normalize_conflict_columns(conflict_col)
    missing_conflict_cols = [column for column in conflict_cols if column not in cols]
    if missing_conflict_cols:
        raise ValueError(f"conflict columns {missing_conflict_cols!r} missing in payload for table {table}")
    col_list = ", ".join(cols)
    placeholders = ", ".join(["%s"] * len(cols))
    updates = ", ".join(f"{c} = EXCLUDED.{c}" for c in cols if c not in conflict_cols)
    if not updates:
        raise ValueError(f"table {table} upsert payload must include at least one non-conflict column")
    conflict_list = ", ".join(conflict_cols)

    returning_sql = "*, (xmax = 0) as __trr_inserted" if include_inserted_flag else "*"
    sql = f"""
        INSERT INTO social.{table} ({col_list})
        VALUES ({placeholders})
        ON CONFLICT ({conflict_list}) DO UPDATE SET {updates}
        RETURNING {returning_sql}
    """
    with pg.db_cursor(conn=conn) as cur:
        return pg.fetch_one_with_cursor(cur, sql, list(adapted.values()))


def _json_serializer(obj: Any) -> Any:
    if isinstance(obj, Decimal):
        return int(obj) if obj == obj.to_integral_value() else float(obj)
    if hasattr(obj, "isoformat"):
        return obj.isoformat()
    raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")


def _json_dumps(value: Any) -> str:
    return json.dumps(value, default=_json_serializer)


def _adapt_payload_json_values(payload: Mapping[str, Any]) -> dict[str, Any]:
    from psycopg2.extras import Json as PgJson

    adapted: dict[str, Any] = {}
    for key, value in payload.items():
        if isinstance(value, (dict, list)):
            adapted[key] = PgJson(value, dumps=_json_dumps)
        else:
            adapted[key] = value
    return adapted


@lru_cache(maxsize=1)
def _resolve_runtime_version_stamp() -> dict[str, Any]:
    return build_runtime_version_stamp(
        getenv=os.getenv,
        modal_environment=modal_environment_name() or None,
        modal_function=modal_social_job_function_name() or None,
        execution_backend=execution_backend_canonical(),
    )


def _resolve_runtime_version_stamp_for_stage(stage: str | None = None) -> dict[str, Any]:
    payload = dict(_resolve_runtime_version_stamp())
    modal_function = modal_social_job_function_name_for_stage(stage) or payload.get("modal_function")
    if modal_function:
        payload["modal_function"] = modal_function
    return payload


def _runtime_version_label(payload: Mapping[str, Any] | None = None) -> str | None:
    metadata = _metadata_dict(payload)
    label = str(metadata.get("label") or "").strip()
    return label or None


def _runtime_version_label_is_generic(label: str | None) -> bool:
    return str(label or "").strip().lower() in {"local", "modal"}


def _runtime_version_backend(payload: Mapping[str, Any] | None = None) -> str | None:
    metadata = _metadata_dict(payload)
    backend = str(metadata.get("execution_backend") or "").strip().lower()
    return backend or None


def _runtime_version_identity(payload: Mapping[str, Any] | None = None) -> dict[str, Any]:
    metadata = _metadata_dict(payload)
    return {
        "execution_backend": _runtime_version_backend(metadata),
        "modal_image": str(metadata.get("modal_image") or "").strip() or None,
        "commit_sha": str(metadata.get("commit_sha") or "").strip() or None,
        "label": _runtime_version_label(metadata),
    }


def _runtime_versions_equivalent(
    left_runtime: Mapping[str, Any] | None,
    right_runtime: Mapping[str, Any] | None,
) -> bool:
    left = _runtime_version_identity(left_runtime)
    right = _runtime_version_identity(right_runtime)
    if not any(left.values()) or not any(right.values()):
        return False

    left_backend = str(left.get("execution_backend") or "").strip().lower() or None
    right_backend = str(right.get("execution_backend") or "").strip().lower() or None
    if left_backend and right_backend and left_backend != right_backend:
        return False

    left_modal_image = str(left.get("modal_image") or "").strip() or None
    right_modal_image = str(right.get("modal_image") or "").strip() or None
    if left_modal_image and right_modal_image:
        return left_modal_image == right_modal_image

    left_commit = str(left.get("commit_sha") or "").strip() or None
    right_commit = str(right.get("commit_sha") or "").strip() or None
    if left_commit and right_commit:
        return left_commit == right_commit

    if left_backend == "local" and right_backend == "local":
        return True

    left_label = str(left.get("label") or "").strip() or None
    right_label = str(right.get("label") or "").strip() or None
    if left_label and right_label:
        if _runtime_version_label_is_generic(left_label) or _runtime_version_label_is_generic(right_label):
            return bool(left_backend and right_backend and left_backend == right_backend)
        return left_label == right_label

    return bool(left_backend and right_backend and left_backend == right_backend)


def _runtime_version_satisfies_requirement(
    required_runtime: Mapping[str, Any] | None,
    observed_runtime: Mapping[str, Any] | None,
) -> bool:
    required = _runtime_version_identity(required_runtime)
    observed = _runtime_version_identity(observed_runtime)
    if not required or not observed:
        return False

    required_backend = str(required.get("execution_backend") or "").strip().lower() or None
    observed_backend = str(observed.get("execution_backend") or "").strip().lower() or None
    if required_backend and observed_backend and required_backend != observed_backend:
        return False

    required_modal_image = str(required.get("modal_image") or "").strip() or None
    observed_modal_image = str(observed.get("modal_image") or "").strip() or None
    if required_modal_image:
        return required_modal_image == observed_modal_image

    required_commit = str(required.get("commit_sha") or "").strip() or None
    observed_commit = str(observed.get("commit_sha") or "").strip() or None
    if required_commit:
        return required_commit == observed_commit

    required_label = _runtime_version_label(required)
    observed_label = _runtime_version_label(observed)
    if required_label:
        if _runtime_version_label_is_generic(required_label):
            return bool(required_backend and observed_backend and required_backend == observed_backend)
        return bool(observed_label and required_label == observed_label)

    if observed_modal_image or observed_commit:
        return bool(required_backend and observed_backend and required_backend == observed_backend)

    if required_backend == "local" and observed_backend == "local":
        return True

    return bool(required_backend and observed_backend and required_backend == observed_backend)


def _resolve_effective_runtime_version(
    *,
    required_execution_backend: str | None = None,
    stage: str | None = None,
) -> dict[str, Any]:
    authoritative_runtime_version = _resolve_authoritative_catalog_runtime_version(
        required_execution_backend=required_execution_backend
    )
    if authoritative_runtime_version:
        payload = dict(authoritative_runtime_version)
        runtime_backend = str(payload.get("execution_backend") or required_execution_backend or "").strip().lower()
        if runtime_backend == "modal":
            modal_function = modal_social_job_function_name_for_stage(stage)
            if modal_function:
                payload["modal_function"] = modal_function
        return payload
    if str(required_execution_backend or "").strip().lower() == "modal":
        modal_function = modal_social_job_function_name_for_stage(stage)
        return {"modal_function": modal_function} if modal_function else {}
    return dict(_resolve_runtime_version_stamp_for_stage(stage))


def _job_runtime_metadata(
    stage: str,
    *,
    runtime_version: Mapping[str, Any] | None = None,
    created_by_runtime_version: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    effective_runtime_version = _metadata_dict(runtime_version) or dict(_resolve_runtime_version_stamp_for_stage(stage))
    creator_runtime_version = _metadata_dict(created_by_runtime_version) or dict(_resolve_runtime_version_stamp())
    return {
        "stage": stage,
        "runtime_version": effective_runtime_version,
        "created_by_runtime_version": creator_runtime_version,
    }


def _resolve_authoritative_catalog_runtime_version(
    *,
    required_execution_backend: str | None = None,
) -> dict[str, Any]:
    normalized_backend = str(required_execution_backend or "").strip().lower() or None
    if normalized_backend != "modal":
        return dict(_resolve_runtime_version_stamp())

    worker_health = _query_worker_health()
    candidates: list[tuple[datetime, dict[str, Any]]] = []
    for worker in worker_health.get("workers") or []:
        if not bool(worker.get("is_fresh")) or not bool(worker.get("is_healthy")):
            continue
        metadata = _metadata_dict(worker.get("metadata"))
        worker_id = str(worker.get("worker_id") or "").strip().lower()
        dispatcher_name = str(metadata.get("dispatcher_name") or "").strip().lower()
        if normalized_backend == "modal":
            is_social_catalog_worker = dispatcher_name == "social" or worker_id == "modal:social-dispatcher"
            if not is_social_catalog_worker:
                continue
        runtime_version = _metadata_dict(metadata.get("runtime_version"))
        worker_backend = str(metadata.get("execution_backend_canonical") or "").strip().lower() or (
            "modal" if worker_id.startswith("modal:") else None
        )
        runtime_backend = str(runtime_version.get("execution_backend") or "").strip().lower() or None
        if worker_backend != "modal" and runtime_backend != "modal":
            continue
        effective_runtime = {
            **runtime_version,
            "execution_backend": runtime_backend or worker_backend or "modal",
        }
        if (
            str(effective_runtime.get("execution_backend") or "").strip().lower() == "modal"
            and str(effective_runtime.get("modal_image") or "").strip()
            and not str(effective_runtime.get("commit_sha") or "").strip()
        ):
            effective_runtime.pop("modal_image", None)
            effective_runtime["label"] = "modal"
        if not any(_runtime_version_identity(effective_runtime).values()):
            continue
        seen_at = _coerce_dt(worker.get("last_seen_at")) or datetime.fromtimestamp(0, tz=UTC)
        candidates.append((seen_at, effective_runtime))

    if not candidates:
        return {}

    candidates.sort(key=lambda item: item[0], reverse=True)
    return dict(candidates[0][1])


@lru_cache(maxsize=1)
def _shared_classify_batch_size() -> int:
    return _resolve_int_env_with_bounds(
        "SOCIAL_SHARED_CLASSIFY_BATCH_SIZE",
        SHARED_CLASSIFY_BATCH_SIZE_DEFAULT,
        minimum=1,
        maximum=1000,
    )


def _chunk_unique_source_ids(source_ids: Sequence[Any], *, chunk_size: int | None = None) -> list[list[str]]:
    normalized_chunk_size = max(1, int(chunk_size or _shared_classify_batch_size()))
    deduped = sorted({str(source_id).strip() for source_id in source_ids if str(source_id).strip()})
    if not deduped:
        return []
    return [deduped[index : index + normalized_chunk_size] for index in range(0, len(deduped), normalized_chunk_size)]


def _shared_profile_kind(source_scope: str, metadata: Mapping[str, Any] | None = None) -> str:
    metadata_dict = _metadata_dict(metadata)
    explicit_kind = str(metadata_dict.get("profile_kind") or "").strip().lower()
    if explicit_kind:
        return explicit_kind
    return SHARED_PROFILE_KIND_BY_SCOPE.get(normalize_source_scope(source_scope), "community")


def _shared_profile_network_name(source_scope: str, metadata: Mapping[str, Any] | None = None) -> str:
    metadata_dict = _metadata_dict(metadata)
    for key in ("network_name", "display_name", "brand_name", "publisher_name"):
        value = str(metadata_dict.get(key) or "").strip()
        if value:
            return value
    normalized_scope = normalize_source_scope(source_scope)
    return normalized_scope.replace("_", " ").title()


def _shared_profile_contract(
    *,
    source_scope: str,
    platform: str,
    account_handle: str,
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    source_scope = _normalize_source_scope_input(source_scope)
    metadata_dict = _metadata_dict(metadata)
    profile_kind = _shared_profile_kind(source_scope, metadata_dict)
    assignment_mode = str(
        metadata_dict.get("assignment_mode") or ""
    ).strip().lower() or SHARED_PROFILE_ASSIGNMENT_MODE_BY_KIND.get(profile_kind, "community_match")
    explicit_rules = metadata_dict.get("assignment_rules")
    assignment_rules = explicit_rules if isinstance(explicit_rules, dict) else {}
    if not assignment_rules:
        assignment_rules = {
            "use_hashtags": True,
            "use_mentions": True,
            "use_collaborators": str(platform or "").strip().lower() == "instagram",
            "use_configured_aliases": True,
            "allow_multi_show_candidates": profile_kind == "network_streaming",
        }
    return {
        "source_scope": source_scope,
        "profile_kind": profile_kind,
        "network_name": _shared_profile_network_name(source_scope, metadata_dict),
        "assignment_mode": assignment_mode,
        "assignment_rules": assignment_rules,
        "account_handle": _normalize_account_handle(account_handle) or str(account_handle or "").strip(),
        "platform": _normalize_platform_name(platform),
    }


def _shared_account_frontier_lease_deadline(platform: str) -> datetime:
    safe_lease_seconds = max(
        30,
        _resolve_social_job_stale_seconds(platform=platform, stage=SHARED_ACCOUNT_POSTS_STAGE),
    )
    return _now_utc() + timedelta(seconds=safe_lease_seconds)


# Author/url metadata columns that a later metadata-poor Instagram-comment pass
# must not clobber with NULL. Every name here is conditionally written by the
# Instagram comment payload builders (gated on column existence), so COALESCE
# preserves a previously-good value when the incoming pass omits it. Deliberately
# excludes media_mirror_* (intentionally reset to None) and the array columns
# media_urls/hosted_media_urls (which arrive as [] rather than NULL).
_INSTAGRAM_COMMENT_COALESCE_PRESERVE_COLS: tuple[str, ...] = (
    "author_profile_pic_url",
    "author_profile_pic_url_hd",
    "author_full_name",
    "author_is_verified",
    "author_fbid_v2",
    "author_is_mentionable",
    "author_is_private",
    "author_latest_reel_media",
    "author_profile_pic_id",
    "comment_url",
)


def _build_upsert_update_clause(
    table: str,
    updates: list[str],
    coalesce_preserve_cols: Sequence[str] | None,
) -> str:
    """Render the ``ON CONFLICT DO UPDATE SET`` clause for ``_pg_upsert_many``.

    For each update column, emit ``c = EXCLUDED.c`` by default. When ``c`` is in
    ``coalesce_preserve_cols`` emit ``c = COALESCE(EXCLUDED.c, social.<table>.c)``
    instead so a metadata-poor later pass cannot clobber a previously-good value
    with NULL. Passing ``None`` (the default) reproduces the legacy all-EXCLUDED
    behavior for every other caller.
    """
    preserve = {str(column).strip() for column in (coalesce_preserve_cols or []) if str(column).strip()}
    clauses: list[str] = []
    for column in updates:
        if column in preserve:
            clauses.append(f"{column} = COALESCE(EXCLUDED.{column}, social.{table}.{column})")
        else:
            clauses.append(f"{column} = EXCLUDED.{column}")
    return ", ".join(clauses)


def _pg_upsert_many(
    table: str,
    payloads: list[dict[str, Any]],
    *,
    conflict_col: str | Sequence[str],
    conn: Any | None = None,
    include_inserted_flag: bool = False,
    coalesce_preserve_cols: Sequence[str] | None = None,
) -> list[dict[str, Any]]:
    """Batch upsert rows into social.{table} using execute_values."""
    if not payloads:
        return []

    first = payloads[0]
    columns = list(first.keys())
    conflict_cols = _normalize_conflict_columns(conflict_col)
    if not columns:
        return []
    missing_conflict_cols = [column for column in conflict_cols if column not in columns]
    if missing_conflict_cols:
        raise ValueError(f"conflict columns {missing_conflict_cols!r} missing in payload for table {table}")

    deduped_payloads: dict[tuple[Any, ...], dict[str, Any]] = {}
    for payload in payloads:
        key = tuple(payload.get(column) for column in conflict_cols)
        if key in deduped_payloads:
            deduped_payloads.pop(key)
        deduped_payloads[key] = payload
    payloads = list(deduped_payloads.values())

    updates = [column for column in columns if column not in conflict_cols]
    if not updates:
        raise ValueError(f"table {table} upsert payload must include at least one non-conflict column")

    values: list[tuple[Any, ...]] = []
    for payload in payloads:
        adapted = _adapt_payload_json_values(payload)
        values.append(tuple(adapted.get(column) for column in columns))

    col_list = ", ".join(columns)
    update_sql = _build_upsert_update_clause(table, updates, coalesce_preserve_cols)
    conflict_list = ", ".join(conflict_cols)
    returning_sql = "*, (xmax = 0) as __trr_inserted" if include_inserted_flag else "*"
    sql = f"""
        INSERT INTO social.{table} ({col_list})
        VALUES %s
        ON CONFLICT ({conflict_list}) DO UPDATE SET {update_sql}
        RETURNING {returning_sql}
    """
    return pg.execute_values_returning(sql, values, conn=conn)


def _new_comment_persist_stats() -> dict[str, int]:
    return {
        "comments_fetched": 0,
        "comments_upserted": 0,
        "comments_inserted": 0,
        "comments_refreshed": 0,
        "comments_changed": 0,
        "comments_skipped_missing_id": 0,
        "comment_media_mirror_jobs_enqueued": 0,
        "comment_media_mirror_job_enqueue_errors": 0,
    }


def _comment_stats_payload(stats: dict[str, int]) -> dict[str, int]:
    return {
        "comments_fetched": int(stats.get("comments_fetched") or 0),
        "comments_upserted": int(stats.get("comments_upserted") or 0),
        "comments_inserted": int(stats.get("comments_inserted") or 0),
        "comments_refreshed": int(stats.get("comments_refreshed") or 0),
        "comments_changed": int(stats.get("comments_changed") or 0),
        "comments_skipped_missing_id": int(stats.get("comments_skipped_missing_id") or 0),
        "comment_media_mirror_jobs_enqueued": int(stats.get("comment_media_mirror_jobs_enqueued") or 0),
        "comment_media_mirror_job_enqueue_errors": int(stats.get("comment_media_mirror_job_enqueue_errors") or 0),
    }


def _merge_comment_persist_stats(target: dict[str, int], delta: dict[str, int]) -> None:
    for key in (
        "comments_fetched",
        "comments_upserted",
        "comments_inserted",
        "comments_refreshed",
        "comments_changed",
        "comments_skipped_missing_id",
        "comment_media_mirror_jobs_enqueued",
        "comment_media_mirror_job_enqueue_errors",
    ):
        target[key] = int(target.get(key) or 0) + int(delta.get(key) or 0)


def _upsert_write_counts(rows: list[dict[str, Any]]) -> tuple[int, int]:
    total = len(rows)
    inserted = 0
    for row in rows:
        if bool(row.pop("__trr_inserted", False)):
            inserted += 1
    return total, inserted


def _record_comment_write_counts(
    persist_stats: dict[str, int] | None,
    *,
    total: int,
    inserted: int,
    changed: int | None = None,
) -> None:
    if persist_stats is None or total <= 0:
        return
    refreshed = max(total - inserted, 0)
    changed_count = max(0, int(inserted if changed is None else changed))
    changed_count = min(total, changed_count)
    persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + total
    persist_stats["comments_inserted"] = int(persist_stats.get("comments_inserted") or 0) + inserted
    persist_stats["comments_refreshed"] = int(persist_stats.get("comments_refreshed") or 0) + refreshed
    persist_stats["comments_changed"] = int(persist_stats.get("comments_changed") or 0) + changed_count


def _savepoint_name(*, prefix: str, index: int) -> str:
    safe_prefix = re.sub(r"[^a-zA-Z0-9_]", "_", str(prefix or "sp")).strip("_") or "sp"
    return f"{safe_prefix}_{max(1, int(index))}"


def _create_savepoint(conn: Any, name: str) -> None:
    with pg.db_cursor(conn=conn) as cur:
        cur.execute(f"SAVEPOINT {name}")


def _rollback_to_savepoint(conn: Any, name: str) -> None:
    with pg.db_cursor(conn=conn) as cur:
        cur.execute(f"ROLLBACK TO SAVEPOINT {name}")


def _release_savepoint(conn: Any, name: str) -> None:
    with pg.db_cursor(conn=conn) as cur:
        cur.execute(f"RELEASE SAVEPOINT {name}")


class _SavepointScope:
    def __init__(self, *, conn: Any | None, prefix: str, index: int) -> None:
        self._conn = conn
        self._name = _savepoint_name(prefix=prefix, index=index)
        self._armed = bool(conn is not None)

    def __enter__(self) -> None:
        if self._armed:
            _create_savepoint(self._conn, self._name)
        return None

    def __exit__(self, exc_type, exc, _tb) -> bool:  # type: ignore[no-untyped-def]
        if not self._armed:
            return False
        if exc_type is not None:
            try:
                _rollback_to_savepoint(self._conn, self._name)
            except Exception:
                logger.debug("[social] Failed rolling back savepoint %s", self._name, exc_info=True)
        try:
            _release_savepoint(self._conn, self._name)
        except Exception:
            logger.debug("[social] Failed releasing savepoint %s", self._name, exc_info=True)
        return False


def _instagram_canonical_post_tables_ready(*, conn: Any | None = None) -> bool:
    try:
        return all(
            [
                _column_exists("social", "social_posts", "source_id", conn=conn),
                _column_exists("social", "social_post_legacy_refs", "legacy_pk", conn=conn),
                _column_exists("social", "social_post_observations", "raw_payload", conn=conn),
                _column_exists("social", "social_post_entities", "entity_type", conn=conn),
                _column_exists("social", "social_post_media_assets", "source_url", conn=conn),
            ]
        )
    except Exception:
        logger.debug("[instagram] Canonical social_post tables are not ready", exc_info=True)
        return False


def _instagram_post_owner_id(post: Any, raw_data: Mapping[str, Any]) -> str | None:
    owner_detail = getattr(post, "owner_detail", None)
    owner = _as_string_mapping(raw_data.get("owner"))
    user = _as_string_mapping(raw_data.get("user"))
    for candidate in (
        getattr(post, "owner_user_id", None),
        getattr(post, "owner_id", None),
        getattr(owner_detail, "user_id", None) if owner_detail is not None else None,
        raw_data.get("ownerId"),
        raw_data.get("owner_id"),
        owner.get("id"),
        user.get("id"),
        user.get("pk"),
    ):
        normalized = str(candidate or "").strip()
        if normalized:
            return normalized
    return None


def _instagram_post_canonical_url(
    shortcode: str, payload: Mapping[str, Any], raw_data: Mapping[str, Any]
) -> str | None:
    for candidate in (
        payload.get("permalink"),
        payload.get("source_input_url"),
        raw_data.get("url"),
        raw_data.get("permalink"),
        raw_data.get("inputUrl"),
    ):
        normalized = str(candidate or "").strip()
        if normalized:
            return normalized
    return f"https://www.instagram.com/p/{shortcode}/" if shortcode else None


def _instagram_entity_payload(value: Any) -> dict[str, Any]:
    if hasattr(value, "to_dict"):
        value = value.to_dict()
    if isinstance(value, Mapping):
        return dict(value)
    return {"value": str(value or "").strip()}


def _instagram_entity_key_from_user_payload(value: Any) -> str:
    payload = _instagram_entity_payload(value)
    for key in ("username", "ownerUsername"):
        normalized = str(payload.get(key) or "").strip().lstrip("@")
        if normalized:
            return normalized
    user = payload.get("user")
    if isinstance(user, Mapping):
        normalized = str(user.get("username") or "").strip().lstrip("@")
        if normalized:
            return normalized
    return str(payload.get("id") or payload.get("pk") or "").strip()


def _instagram_location_payload(
    payload: Mapping[str, Any], raw_data: Mapping[str, Any]
) -> tuple[str, dict[str, Any]] | None:
    location_raw = payload.get("location_raw")
    if isinstance(location_raw, Mapping) and location_raw:
        key = str(
            location_raw.get("id")
            or location_raw.get("location_id")
            or location_raw.get("pk")
            or location_raw.get("name")
            or ""
        ).strip()
        if key:
            return key, dict(location_raw)
    location = raw_data.get("location")
    if isinstance(location, Mapping) and location:
        key = str(location.get("id") or location.get("pk") or location.get("name") or "").strip()
        if key:
            return key, dict(location)
    location_id = str(payload.get("location_id") or raw_data.get("locationId") or "").strip()
    location_name = str(payload.get("location_name") or raw_data.get("locationName") or "").strip()
    if location_id or location_name:
        return location_id or location_name, {"id": location_id or None, "name": location_name or None}
    return None


def _sync_instagram_canonical_post_entities(
    *,
    canonical_post_id: str,
    payload: Mapping[str, Any],
    post: Any,
    raw_data: Mapping[str, Any],
    conn: Any | None,
) -> None:
    rows: list[dict[str, Any]] = []

    def add_entity(entity_type: str, key: Any, entity_payload: Mapping[str, Any] | None = None) -> None:
        normalized_key = str(key or "").strip()
        if not normalized_key:
            return
        if entity_type in {"hashtag", "mention", "collaborator", "tagged_user"}:
            normalized_key = normalized_key.lstrip("#@")
        if not normalized_key:
            return
        rows.append(
            {
                "platform": "instagram",
                "post_id": canonical_post_id,
                "entity_type": entity_type,
                "entity_key": normalized_key,
                "entity_key_norm": normalized_key.lower(),
                "entity_payload": dict(entity_payload or {}),
                "last_seen_at": _now_utc(),
            }
        )

    for value in _as_text_list(payload.get("hashtags")):
        add_entity("hashtag", value)
    for value in _as_text_list(payload.get("mentions")):
        add_entity("mention", value)
    for value in _as_text_list(payload.get("collaborators")):
        add_entity("collaborator", value)
    for value in getattr(post, "tagged_users_detail", None) or payload.get("tagged_users_detail") or []:
        add_entity("tagged_user", _instagram_entity_key_from_user_payload(value), _instagram_entity_payload(value))
    for value in getattr(post, "collaborators_detail", None) or payload.get("collaborators_detail") or []:
        add_entity("collaborator", _instagram_entity_key_from_user_payload(value), _instagram_entity_payload(value))
    location_payload = _instagram_location_payload(payload, raw_data)
    if location_payload is not None:
        add_entity("location", location_payload[0], location_payload[1])

    if not rows:
        return
    try:
        _pg_upsert_many(
            "social_post_entities",
            rows,
            conflict_col=["platform", "entity_type", "entity_key_norm", "post_id"],
            conn=conn,
        )
    except Exception:
        logger.debug("[instagram] Failed syncing canonical post entities", exc_info=True)


def _sync_instagram_canonical_post_media_assets(
    *,
    canonical_post_id: str,
    payload: Mapping[str, Any],
    raw_data: Mapping[str, Any],
    conn: Any | None,
) -> None:
    media_urls = _normalize_unique_terms(_as_text_list(payload.get("media_urls")))
    hosted_media_urls = _normalize_unique_terms(_as_text_list(payload.get("hosted_media_urls")))
    source_thumbnail_url = str(payload.get("thumbnail_url") or "").strip() or None
    hosted_thumbnail_url = str(payload.get("hosted_thumbnail_url") or "").strip() or None
    width = _normalize_non_negative_int(payload.get("width")) or None
    height = _normalize_non_negative_int(payload.get("height")) or None
    duration_raw = payload.get("duration_seconds")
    duration_seconds = _normalize_non_negative_int(duration_raw) if duration_raw is not None else None
    if not media_urls and source_thumbnail_url:
        media_urls = [source_thumbnail_url]

    rows: list[dict[str, Any]] = []
    max_len = max(len(media_urls), len(hosted_media_urls), 1 if source_thumbnail_url or hosted_thumbnail_url else 0)
    for index in range(max_len):
        source_url = media_urls[index] if index < len(media_urls) else (source_thumbnail_url if index == 0 else None)
        hosted_url = hosted_media_urls[index] if index < len(hosted_media_urls) else None
        if not source_url and not hosted_url and index > 0:
            continue
        rows.append(
            {
                "platform": "instagram",
                "post_id": canonical_post_id,
                "position": index,
                "media_type": payload.get("media_type"),
                "source_url": source_url,
                "hosted_url": hosted_url,
                "thumbnail_url": source_thumbnail_url if index == 0 else None,
                "hosted_thumbnail_url": hosted_thumbnail_url if index == 0 else None,
                "width": width,
                "height": height,
                "duration_seconds": duration_seconds,
                "mirror_status": payload.get("media_mirror_status"),
                "mirror_error": payload.get("media_mirror_error"),
                "mirror_last_attempt_at": payload.get("media_mirror_last_attempt_at"),
                "media_payload": {
                    "source": "instagram_posts",
                    "raw_child_posts": raw_data.get("childPosts") or raw_data.get("carousel_media") or [],
                },
            }
        )
    if not rows:
        return
    try:
        _pg_upsert_many(
            "social_post_media_assets",
            rows,
            conflict_col=["platform", "post_id", "position"],
            conn=conn,
        )
    except Exception:
        logger.debug("[instagram] Failed syncing canonical post media assets", exc_info=True)


def _canonical_catalog_metric_update_sql(column: str) -> str:
    return (
        f"{column} = case "
        f"when excluded.{column} > coalesce(social.social_posts.{column}, 0) then excluded.{column} "
        f"else coalesce(social.social_posts.{column}, excluded.{column}, 0) "
        "end"
    )


def _max_normalized_non_negative_int(*values: Any) -> int:
    return max(_normalize_non_negative_int(value) for value in values)


def _sync_instagram_canonical_catalog_post(
    *,
    catalog_row: Mapping[str, Any] | None,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    """Populate the canonical post model from a shared Instagram catalog row.

    Catalog rows can arrive before detail/comment materialization. This keeps
    ``social.social_posts`` queryable without downgrading richer detail metrics
    that may already exist on the canonical row.
    """
    if not catalog_row or not _instagram_canonical_post_tables_ready(conn=conn):
        return None
    source_id = str(catalog_row.get("source_id") or "").strip()
    if not source_id:
        return None
    raw_data = _metadata_dict(catalog_row.get("raw_data"))
    owner_handle = (
        str(catalog_row.get("owner_username") or catalog_row.get("source_account") or "").strip().lstrip("@") or None
    )
    owner_handle_norm = owner_handle.lower() if owner_handle else None
    now = _now_utc()
    canonical_url = str(catalog_row.get("permalink") or "").strip() or (
        f"https://www.instagram.com/p/{source_id}/" if source_id else None
    )
    payload = {
        "platform": "instagram",
        "source_id": source_id,
        "owner_handle": owner_handle,
        "owner_handle_norm": owner_handle_norm,
        "owner_id": _instagram_post_owner_id(SimpleNamespace(), raw_data),
        "canonical_url": canonical_url,
        "body": catalog_row.get("caption") or catalog_row.get("description") or catalog_row.get("text"),
        "media_type": catalog_row.get("media_type"),
        "posted_at": catalog_row.get("posted_at"),
        "like_count": _normalize_non_negative_int(catalog_row.get("likes")),
        "comment_count": _normalize_non_negative_int(catalog_row.get("comments_count")),
        "share_count": _normalize_non_negative_int(catalog_row.get("shares")),
        "view_count": _normalize_non_negative_int(catalog_row.get("views")),
        "last_seen_at": catalog_row.get("last_seen_at") or now,
        "last_scraped_at": catalog_row.get("metadata_scraped_at") or catalog_row.get("updated_at") or now,
    }
    adapted = _adapt_payload_json_values(payload)
    columns = list(adapted.keys())
    placeholders = ", ".join(["%s"] * len(columns))
    column_sql = ", ".join(columns)
    update_sql = ", ".join(
        [
            "owner_handle = coalesce(excluded.owner_handle, social.social_posts.owner_handle)",
            "owner_handle_norm = coalesce(excluded.owner_handle_norm, social.social_posts.owner_handle_norm)",
            "owner_id = coalesce(excluded.owner_id, social.social_posts.owner_id)",
            "canonical_url = coalesce(excluded.canonical_url, social.social_posts.canonical_url)",
            "body = coalesce(excluded.body, social.social_posts.body)",
            "media_type = coalesce(excluded.media_type, social.social_posts.media_type)",
            "posted_at = coalesce(excluded.posted_at, social.social_posts.posted_at)",
            _canonical_catalog_metric_update_sql("like_count"),
            _canonical_catalog_metric_update_sql("comment_count"),
            _canonical_catalog_metric_update_sql("share_count"),
            _canonical_catalog_metric_update_sql("view_count"),
            "last_seen_at = greatest(social.social_posts.last_seen_at, excluded.last_seen_at)",
            "last_scraped_at = greatest("
            "coalesce(social.social_posts.last_scraped_at, excluded.last_scraped_at), "
            "excluded.last_scraped_at"
            ")",
            "updated_at = now()",
        ]
    )
    try:
        with pg.db_cursor(conn=conn, label="instagram_canonical_catalog_post") as cur:
            canonical_row = pg.fetch_one_with_cursor(
                cur,
                f"""
                insert into social.social_posts ({column_sql})
                values ({placeholders})
                on conflict (platform, source_id)
                do update set {update_sql}
                returning *
                """,
                list(adapted.values()),
            )
    except Exception:
        logger.debug("[instagram] Failed syncing catalog-backed canonical social_posts row", exc_info=True)
        return None

    canonical_post_id = str((canonical_row or {}).get("id") or "").strip()
    catalog_pk = str(catalog_row.get("id") or "").strip()
    if not canonical_post_id:
        return canonical_row
    if catalog_pk:
        try:
            _pg_upsert(
                "social_post_legacy_refs",
                {
                    "platform": "instagram",
                    "post_id": canonical_post_id,
                    "legacy_schema": "social",
                    "legacy_table": "instagram_account_catalog_posts",
                    "legacy_pk": catalog_pk,
                    "legacy_source_id": source_id,
                },
                conflict_col=["platform", "legacy_table", "legacy_pk"],
                conn=conn,
            )
        except Exception:
            logger.debug("[instagram] Failed syncing canonical catalog legacy ref", exc_info=True)

    try:
        with pg.db_cursor(conn=conn, label="instagram_canonical_catalog_observation") as cur:
            pg.fetch_one_with_cursor(
                cur,
                """
                insert into social.social_post_observations (
                  platform,
                  post_id,
                  source_table,
                  source_pk,
                  source_url,
                  raw_payload,
                  normalized_payload
                )
                values (
                  'instagram',
                  %s::uuid,
                  'instagram_account_catalog_posts',
                  %s,
                  %s,
                  %s::jsonb,
                  %s::jsonb
                )
                returning id::text
                """,
                [
                    canonical_post_id,
                    catalog_pk or source_id,
                    canonical_url,
                    _json_dumps(raw_data),
                    _json_dumps({key: value for key, value in payload.items() if key != "platform"}),
                ],
            )
    except Exception:
        logger.debug("[instagram] Failed inserting canonical catalog observation", exc_info=True)

    entity_payload = {
        "hashtags": catalog_row.get("hashtags"),
        "mentions": catalog_row.get("mentions"),
        "collaborators": catalog_row.get("collaborators"),
        "profile_tags": catalog_row.get("profile_tags"),
        "media_urls": catalog_row.get("media_urls"),
        "thumbnail_url": catalog_row.get("thumbnail_url"),
        "media_type": catalog_row.get("media_type"),
    }
    _sync_instagram_canonical_post_entities(
        canonical_post_id=canonical_post_id,
        payload=entity_payload,
        post=SimpleNamespace(),
        raw_data=raw_data,
        conn=conn,
    )
    _sync_instagram_canonical_post_media_assets(
        canonical_post_id=canonical_post_id,
        payload=entity_payload,
        raw_data=raw_data,
        conn=conn,
    )
    return canonical_row


def _sync_instagram_canonical_catalog_posts(
    rows: Sequence[Mapping[str, Any]] | None,
    *,
    conn: Any | None = None,
    progress_callback: Callable[[dict[str, Any]], None] | None = None,
    progress_interval: int = 1,
) -> int:
    synced = 0
    total = len(rows or [])
    safe_progress_interval = max(1, int(progress_interval or 5))
    for index, row in enumerate(rows or [], start=1):
        if _sync_instagram_canonical_catalog_post(catalog_row=row, conn=conn):
            synced += 1
        if progress_callback is not None and (index == total or index % safe_progress_interval == 0):
            progress_callback({"phase": "catalog_canonical_sync", "processed": index, "total": total, "synced": synced})
    return synced


def repair_instagram_canonical_metrics_for_run(
    run_id: str,
    *,
    conn: Any | None = None,
) -> dict[str, Any]:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return {"run_id": None, "canonical_metric_rows_repaired": 0}
    repair_started_at = _now_utc()
    try:
        row = (
            pg.fetch_one(
                """
            with run_catalog as (
              select
                source_id,
                max(coalesce(likes, 0)) as likes,
                max(coalesce(comments_count, 0)) as comments_count,
                max(coalesce(shares, 0)) as shares,
                max(coalesce(views, 0)) as views
              from social.instagram_account_catalog_posts
              where last_backfill_run_id = %s::uuid
              group by source_id
            ),
            source_metrics as (
              select
                rc.source_id,
                greatest(coalesce(rc.likes, 0), coalesce(ip.likes, 0)) as like_count,
                greatest(coalesce(rc.comments_count, 0), coalesce(ip.comments_count, 0)) as comment_count,
                greatest(coalesce(rc.shares, 0), coalesce(ip.media_repost_count, 0)) as share_count,
                greatest(coalesce(rc.views, 0), coalesce(ip.views, 0)) as view_count
              from run_catalog rc
              left join social.instagram_posts ip on ip.shortcode = rc.source_id
            ),
            repaired as (
              update social.social_posts sp
              set
                like_count = greatest(coalesce(sp.like_count, 0), sm.like_count),
                comment_count = greatest(coalesce(sp.comment_count, 0), sm.comment_count),
                share_count = greatest(coalesce(sp.share_count, 0), sm.share_count),
                view_count = greatest(coalesce(sp.view_count, 0), sm.view_count),
                updated_at = now()
              from source_metrics sm
              where sp.platform = 'instagram'
                and sp.source_id = sm.source_id
                and (
                  coalesce(sp.like_count, 0) < sm.like_count
                  or coalesce(sp.comment_count, 0) < sm.comment_count
                  or coalesce(sp.share_count, 0) < sm.share_count
                  or coalesce(sp.view_count, 0) < sm.view_count
                )
              returning sp.id
            )
            select count(*)::int as canonical_metric_rows_repaired
            from repaired
            """,
                [normalized_run_id],
                conn=conn,
            )
            or {}
        )
    except Exception:
        logger.debug(
            "[instagram] failed repairing canonical metrics for run=%s",
            normalized_run_id,
            exc_info=True,
        )
        return {
            "run_id": normalized_run_id,
            "canonical_metric_rows_repaired": 0,
            "error": "repair_failed",
        }
    repaired_count = _normalize_non_negative_int(row.get("canonical_metric_rows_repaired"))
    summary = {
        "run_id": normalized_run_id,
        "platform": "instagram",
        "canonical_metric_rows_repaired": repaired_count,
        "repaired_at": _iso(repair_started_at),
        "source": "instagram_canonical_metric_repair",
    }
    if repaired_count > 0:
        try:
            pg.fetch_one(
                """
                update social.scrape_runs
                set summary = coalesce(summary, '{}'::jsonb)
                  || jsonb_build_object(
                    'latest_canonical_metric_repair',
                    %s::jsonb,
                    'canonical_metric_repairs',
                    coalesce(summary->'canonical_metric_repairs', '[]'::jsonb) || jsonb_build_array(%s::jsonb)
                  )
                where id = %s::uuid
                returning id::text
                """,
                [_json_dumps(summary), _json_dumps(summary), normalized_run_id],
                conn=conn,
            )
        except Exception:
            logger.debug(
                "[instagram] failed recording canonical metric repair summary for run=%s",
                normalized_run_id,
                exc_info=True,
            )
    return summary


def normalize_instagram_hosted_media_mirror_status_for_run(
    run_id: str,
    *,
    conn: Any | None = None,
    batch_size: int = 500,
) -> dict[str, Any]:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return {"run_id": None, "hosted_media_status_rows_normalized": 0}
    normalized_at = _now_utc()
    safe_batch_size = max(1, min(int(batch_size or 500), 5000))
    normalized_count = 0
    try:
        while True:
            row = (
                pg.fetch_one(
                    """
                with run_catalog as (
                  select distinct source_id
                  from social.instagram_account_catalog_posts
                  where last_backfill_run_id = %s::uuid
                ),
                eligible as (
                    select
                      ip.id,
                      nullif(ip.thumbnail_url, '') is not null as source_thumbnail_present,
                      nullif(ip.hosted_thumbnail_url, '') is not null as hosted_thumbnail_present,
                      coalesce(jsonb_array_length(
                        case
                          when jsonb_typeof(to_jsonb(ip.media_urls)) = 'array'
                          then to_jsonb(ip.media_urls)
                          else '[]'::jsonb
                        end
                      ), 0) as source_media_count,
                      coalesce(jsonb_array_length(
                        case
                          when jsonb_typeof(to_jsonb(ip.hosted_media_urls)) = 'array'
                          then to_jsonb(ip.hosted_media_urls)
                          else '[]'::jsonb
                        end
                      ), 0) as hosted_media_count
                    from social.instagram_posts ip
                    join run_catalog rc on rc.source_id = ip.shortcode
                    where nullif(ip.media_mirror_status, '') is null
                ),
                candidates as (
                  select ip.id
                  from social.instagram_posts ip
                  join eligible e on e.id = ip.id
                  where (e.hosted_thumbnail_present or e.hosted_media_count > 0)
                    and (
                      (
                        (e.source_thumbnail_present or e.source_media_count > 0)
                        and (not e.source_thumbnail_present or e.hosted_thumbnail_present or e.hosted_media_count > 0)
                        and e.hosted_media_count >= e.source_media_count
                      )
                      or (
                        not e.source_thumbnail_present
                        and e.source_media_count = 0
                        and (e.hosted_thumbnail_present or e.hosted_media_count > 0)
                      )
                    )
                  order by ip.id
                  limit %s
                  for update of ip skip locked
                ),
                normalized as (
                  update social.instagram_posts ip
                  set
                    media_mirror_status = 'mirrored',
                    media_mirror_error = null
                  from candidates c
                  where ip.id = c.id
                  returning ip.id
                )
                select count(*)::int as hosted_media_status_rows_normalized
                from normalized
                """,
                    [normalized_run_id, safe_batch_size],
                    conn=conn,
                )
                or {}
            )
            batch_count = _normalize_non_negative_int(row.get("hosted_media_status_rows_normalized"))
            normalized_count += batch_count
            if batch_count < safe_batch_size:
                break
    except Exception:
        logger.debug(
            "[instagram] failed normalizing hosted media mirror statuses for run=%s",
            normalized_run_id,
            exc_info=True,
        )
        return {
            "run_id": normalized_run_id,
            "hosted_media_status_rows_normalized": 0,
            "error": "normalization_failed",
        }
    summary = {
        "run_id": normalized_run_id,
        "platform": "instagram",
        "hosted_media_status_rows_normalized": normalized_count,
        "normalized_at": _iso(normalized_at),
        "source": "instagram_hosted_media_status_normalizer",
    }
    if normalized_count > 0:
        try:
            pg.fetch_one(
                """
                update social.scrape_runs
                set summary = coalesce(summary, '{}'::jsonb)
                  || jsonb_build_object(
                    'latest_hosted_media_status_normalization',
                    %s::jsonb,
                    'hosted_media_status_normalizations',
                    coalesce(summary->'hosted_media_status_normalizations', '[]'::jsonb)
                      || jsonb_build_array(%s::jsonb)
                  )
                where id = %s::uuid
                returning id::text
                """,
                [_json_dumps(summary), _json_dumps(summary), normalized_run_id],
                conn=conn,
            )
        except Exception:
            logger.debug(
                "[instagram] failed recording hosted media normalization summary for run=%s",
                normalized_run_id,
                exc_info=True,
            )
    return summary


def recover_orphaned_instagram_frontier_leases_for_run(
    run_id: str,
    *,
    conn: Any | None = None,
) -> dict[str, Any]:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return {"run_id": None, "released_frontier_leases": 0, "due_jobs": 0}
    recovered_at = _now_utc()
    release_rows = pg.fetch_all(
        """
        with candidates as (
          select
            f.id,
            f.run_id,
            f.platform,
            f.account_handle,
            f.status as prior_status,
            f.lease_owner as prior_lease_owner,
            f.pages_scanned,
            f.posts_checked,
            f.posts_saved,
            f.metadata
          from social.shared_account_run_frontiers f
          where f.run_id = %s::uuid
            and f.platform = 'instagram'
            and nullif(f.lease_owner, '') is not null
            and (
              f.status <> 'running'
              or f.lease_expires_at < now()
              or lower(coalesce(f.metadata->>'last_error_code', '')) = %s
              or lower(coalesce(f.metadata->>'frontier_stop_reason', '')) = %s
            )
            and not exists (
              select 1
              from social.scrape_jobs j
              where j.run_id = f.run_id
                and coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s
                and j.status = 'running'
                and j.worker_id = f.lease_owner
            )
          for update of f skip locked
        ),
        released as (
          update social.shared_account_run_frontiers f
          set
            status = case when f.status = 'running' then 'retrying' else f.status end,
            lease_owner = null,
            lease_expires_at = null,
            updated_at = now(),
            metadata = coalesce(f.metadata, '{}'::jsonb) || jsonb_build_object(
              'orphaned_frontier_lease_recovery',
              jsonb_build_object(
                'reason', 'leased_frontier_without_matching_running_job',
                'recovered_at', now(),
                'prior_status', candidates.prior_status,
                'prior_lease_owner', candidates.prior_lease_owner,
                'pages_scanned', candidates.pages_scanned,
                'posts_checked', candidates.posts_checked,
                'posts_saved', candidates.posts_saved
              )
            )
          from candidates
          where f.id = candidates.id
          returning
            f.id::text as frontier_id,
            f.run_id::text as run_id,
            f.platform,
            f.account_handle,
            candidates.prior_status,
            candidates.prior_lease_owner,
            f.status,
            f.pages_scanned,
            f.posts_checked,
            f.posts_saved
        )
        select *
        from released
        order by account_handle
        """,
        [
            normalized_run_id,
            SHARED_ACCOUNT_FRONTIER_LEASE_UNAVAILABLE_ERROR_CODE,
            SHARED_ACCOUNT_FRONTIER_LEASE_UNAVAILABLE_ERROR_CODE,
            SHARED_ACCOUNT_POSTS_STAGE,
        ],
        conn=conn,
    )
    due_rows: list[dict[str, Any]] = []
    if release_rows:
        released_accounts = sorted(
            {
                _normalize_account_handle(row.get("account_handle"))
                for row in release_rows
                if _normalize_account_handle(row.get("account_handle"))
            }
        )
        due_rows = pg.fetch_all(
            """
            with released_accounts(account_handle) as (
              select lower(value)
              from jsonb_array_elements_text(%s::jsonb) value
            )
            update social.scrape_jobs j
            set
              status = 'retrying',
              claimed_at = null,
              worker_id = null,
              heartbeat_at = now(),
              available_at = least(coalesce(j.available_at, now()), now()),
              last_error_code = null,
              last_error_class = null,
              error_message = null,
              metadata = (coalesce(j.metadata, '{}'::jsonb) - 'error_code' - 'error_class' - 'retryable')
                || jsonb_build_object(
                  'orphaned_frontier_lease_recovery',
                  jsonb_build_object(
                    'reason', 'frontier_lease_released_for_clean_redispatch',
                    'recovered_at', now()
                  )
                )
            where j.run_id = %s::uuid
              and j.platform = 'instagram'
              and coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s
              and j.status in ('queued', 'pending', 'retrying')
              and exists (
                select 1
                from released_accounts ra
                where ra.account_handle = lower(ltrim(coalesce(
                  nullif(j.config->>'account', ''),
                  nullif(j.config->>'account_handle', ''),
                  nullif(j.config->>'source_account', ''),
                  nullif(j.metadata->>'account', ''),
                  nullif(j.metadata->>'account_handle', ''),
                  nullif(j.metadata->>'source_account', ''),
                  ''
                ), '@'))
              )
            returning j.id::text as id, j.status, j.available_at
            """,
            [_json_dumps(released_accounts), normalized_run_id, SHARED_ACCOUNT_POSTS_STAGE],
            conn=conn,
        )
    summary = {
        "run_id": normalized_run_id,
        "platform": "instagram",
        "released_frontier_leases": len(release_rows),
        "due_jobs": len(due_rows),
        "recovered_at": _iso(recovered_at),
        "source": "instagram_orphaned_frontier_lease_recovery",
        "frontiers": release_rows,
        "jobs": due_rows,
    }
    if release_rows:
        try:
            pg.fetch_one(
                """
                update social.scrape_runs
                set summary = coalesce(summary, '{}'::jsonb)
                  || jsonb_build_object(
                    'latest_orphaned_frontier_lease_recovery',
                    %s::jsonb,
                    'orphaned_frontier_lease_recoveries',
                    coalesce(summary->'orphaned_frontier_lease_recoveries', '[]'::jsonb)
                      || jsonb_build_array(%s::jsonb)
                  )
                where id = %s::uuid
                returning id::text
                """,
                [_json_dumps(summary), _json_dumps(summary), normalized_run_id],
                conn=conn,
            )
        except Exception:
            logger.debug(
                "[instagram] failed recording orphaned frontier lease recovery summary for run=%s",
                normalized_run_id,
                exc_info=True,
            )
    return summary


def _sync_instagram_canonical_post(
    *,
    legacy_row: Mapping[str, Any] | None,
    payload: Mapping[str, Any],
    post: Any,
    conn: Any | None,
) -> dict[str, Any] | None:
    if not legacy_row or not _instagram_canonical_post_tables_ready(conn=conn):
        return None
    shortcode = str(payload.get("shortcode") or "").strip()
    if not shortcode:
        return None
    raw_data = _metadata_dict(payload.get("raw_data"))
    owner_handle = str(payload.get("username") or payload.get("source_account") or "").strip().lstrip("@") or None
    owner_handle_norm = owner_handle.lower() if owner_handle else None
    legacy_row = _metadata_dict(legacy_row)
    like_count = _max_normalized_non_negative_int(payload.get("likes"), legacy_row.get("likes"))
    comment_count = _max_normalized_non_negative_int(
        payload.get("comments_count"),
        legacy_row.get("comments_count"),
    )
    share_count = _max_normalized_non_negative_int(
        payload.get("media_repost_count"),
        payload.get("shares"),
        legacy_row.get("media_repost_count"),
        legacy_row.get("shares"),
    )
    view_count = _max_normalized_non_negative_int(payload.get("views"), legacy_row.get("views"))
    canonical_payload = {
        "platform": "instagram",
        "source_id": shortcode,
        "owner_handle": owner_handle,
        "owner_handle_norm": owner_handle_norm,
        "owner_id": _instagram_post_owner_id(post, raw_data),
        "canonical_url": _instagram_post_canonical_url(shortcode, payload, raw_data),
        "body": payload.get("caption"),
        "media_type": payload.get("media_type"),
        "posted_at": payload.get("posted_at"),
        "like_count": like_count,
        "comment_count": comment_count,
        "share_count": share_count,
        "view_count": view_count,
        "last_seen_at": _now_utc(),
        "last_scraped_at": payload.get("scraped_at"),
    }
    try:
        adapted = _adapt_payload_json_values(canonical_payload)
        columns = list(adapted.keys())
        placeholders = ", ".join(["%s"] * len(columns))
        column_sql = ", ".join(columns)
        update_sql = ", ".join(
            [
                "owner_handle = coalesce(excluded.owner_handle, social.social_posts.owner_handle)",
                "owner_handle_norm = coalesce(excluded.owner_handle_norm, social.social_posts.owner_handle_norm)",
                "owner_id = coalesce(excluded.owner_id, social.social_posts.owner_id)",
                "canonical_url = coalesce(excluded.canonical_url, social.social_posts.canonical_url)",
                "body = coalesce(excluded.body, social.social_posts.body)",
                "media_type = coalesce(excluded.media_type, social.social_posts.media_type)",
                "posted_at = coalesce(excluded.posted_at, social.social_posts.posted_at)",
                _canonical_catalog_metric_update_sql("like_count"),
                _canonical_catalog_metric_update_sql("comment_count"),
                _canonical_catalog_metric_update_sql("share_count"),
                _canonical_catalog_metric_update_sql("view_count"),
                "last_seen_at = greatest(social.social_posts.last_seen_at, excluded.last_seen_at)",
                "last_scraped_at = greatest(social.social_posts.last_scraped_at, excluded.last_scraped_at)",
                "updated_at = now()",
            ]
        )
        with pg.db_cursor(conn=conn, label="instagram_canonical_post") as cur:
            canonical_row = pg.fetch_one_with_cursor(
                cur,
                f"""
                insert into social.social_posts ({column_sql})
                values ({placeholders})
                on conflict (platform, source_id) do update set {update_sql}
                returning *
                """,
                [adapted[column] for column in columns],
            )
    except Exception:
        logger.debug("[instagram] Failed syncing canonical social_posts row", exc_info=True)
        return None
    canonical_post_id = str((canonical_row or {}).get("id") or "").strip()
    legacy_pk = str((legacy_row or {}).get("id") or "").strip()
    if not canonical_post_id or not legacy_pk:
        return canonical_row

    try:
        _pg_upsert(
            "social_post_legacy_refs",
            {
                "platform": "instagram",
                "post_id": canonical_post_id,
                "legacy_schema": "social",
                "legacy_table": "instagram_posts",
                "legacy_pk": legacy_pk,
                "legacy_source_id": shortcode,
            },
            conflict_col=["platform", "legacy_table", "legacy_pk"],
            conn=conn,
        )
    except Exception:
        logger.debug("[instagram] Failed syncing canonical legacy ref", exc_info=True)

    try:
        with pg.db_cursor(conn=conn, label="instagram_canonical_observation") as cur:
            pg.fetch_one_with_cursor(
                cur,
                """
                insert into social.social_post_observations (
                  platform,
                  post_id,
                  source_table,
                  source_pk,
                  source_url,
                  raw_payload,
                  normalized_payload
                )
                values (
                  'instagram',
                  %s::uuid,
                  'instagram_posts',
                  %s,
                  %s,
                  %s::jsonb,
                  %s::jsonb
                )
                returning id::text
                """,
                [
                    canonical_post_id,
                    legacy_pk,
                    canonical_payload.get("canonical_url"),
                    _json_dumps(raw_data),
                    _json_dumps({key: value for key, value in canonical_payload.items() if key != "platform"}),
                ],
            )
    except Exception:
        logger.debug("[instagram] Failed inserting canonical observation", exc_info=True)

    _sync_instagram_canonical_post_entities(
        canonical_post_id=canonical_post_id,
        payload=payload,
        post=post,
        raw_data=raw_data,
        conn=conn,
    )
    _sync_instagram_canonical_post_media_assets(
        canonical_post_id=canonical_post_id,
        payload=payload,
        raw_data=raw_data,
        conn=conn,
    )
    return canonical_row


def _upsert_instagram_post(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.catalog_ingest import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["_upsert_instagram_post"](*args, **kwargs)


def _batch_upsert_instagram_posts(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.catalog_ingest import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["_batch_upsert_instagram_posts"](*args, **kwargs)


def _instagram_post_source_urls(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.media_mirror import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["_instagram_post_source_urls"](*args, **kwargs)


def _platform_post_source_urls(platform: str, post_row: dict[str, Any]) -> tuple[str, list[str]]:
    normalized_platform = (platform or "").strip().lower()
    if normalized_platform == "instagram":
        return _instagram_post_source_urls(post_row)

    source_media_urls = _normalize_unique_terms(_as_text_list(post_row.get("media_urls")))
    source_thumbnail_url = str(post_row.get("thumbnail_url") or "").strip()
    if normalized_platform == "twitter":
        source_thumbnail_url = _select_thumbnail_candidate(source_media_urls, fallback=source_thumbnail_url)
    elif normalized_platform != "youtube" and not source_thumbnail_url and source_media_urls:
        # For Twitter (and other platforms without a dedicated thumbnail_url column),
        # prefer a non-video URL as the thumbnail/cover image.
        source_thumbnail_url = _select_thumbnail_candidate(source_media_urls)
    return source_thumbnail_url, source_media_urls


def _platform_source_id(platform: str, post_row: dict[str, Any]) -> str:
    normalized_platform = (platform or "").strip().lower()
    source_col = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    if not source_col:
        return ""
    return str(post_row.get(source_col) or post_row.get("source_id") or "").strip()


@lru_cache(maxsize=4)
def _expected_cdn_host(cdn_base_url: str) -> str | None:
    raw = str(cdn_base_url or "").strip()
    if raw == "":
        return None
    parsed = urlparse(raw)
    host = (parsed.netloc or "").strip().lower()
    if not host:
        return None
    return host


def _url_host(value: str) -> str:
    parsed = urlparse(str(value or "").strip())
    return (parsed.netloc or "").strip().lower()


def _hosted_urls_need_cdn_host_repair(*, hosted_thumbnail_url: str, hosted_media_urls: list[str]) -> bool:
    expected_host = _expected_cdn_host(str(os.getenv("OBJECT_STORAGE_PUBLIC_BASE_URL") or ""))
    if not expected_host:
        return False

    candidates: list[str] = []
    if hosted_thumbnail_url:
        candidates.append(hosted_thumbnail_url)
    candidates.extend([str(url).strip() for url in (hosted_media_urls or []) if str(url).strip()])

    for url in candidates:
        host = _url_host(url)
        if not host:
            # Malformed URL should be remirrored to restore a canonical hosted URL.
            return True
        if host != expected_host:
            return True
    return False


def _hosted_url_needs_cdn_host_repair(url: str) -> bool:
    return _hosted_urls_need_cdn_host_repair(hosted_thumbnail_url=str(url or "").strip(), hosted_media_urls=[])


def _hosted_media_urls_need_content_repair(*, hosted_media_urls: list[str]) -> bool:
    for url in hosted_media_urls or []:
        if _is_page_like_media_url(url):
            # HTML/page wrappers are not valid canonical hosted media assets.
            return True
    return False


def _media_mirror_error_has_bad_host_or_content_reason(value: Any) -> bool:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return False
    return any(token in normalized for token in _HOSTED_MEDIA_BAD_REPAIR_REASON_TOKENS)


def _hosted_media_has_known_bad_reason(
    *,
    hosted_thumbnail_url: str | None,
    hosted_media_urls: list[str],
    media_mirror_error: Any = None,
) -> bool:
    if _media_mirror_error_has_bad_host_or_content_reason(media_mirror_error):
        return True
    if hosted_thumbnail_url and _is_page_like_media_url(hosted_thumbnail_url):
        return True
    if _hosted_media_urls_need_content_repair(hosted_media_urls=hosted_media_urls):
        return True
    return _hosted_urls_need_cdn_host_repair(
        hosted_thumbnail_url=str(hosted_thumbnail_url or "").strip(),
        hosted_media_urls=hosted_media_urls,
    )


def _hosted_media_urls_usable_for_effective_selection(
    platform: str,
    post_row: Mapping[str, Any],
    *,
    hosted_thumbnail_url: str | None,
    hosted_media_urls: list[str],
) -> bool:
    del platform
    if not hosted_thumbnail_url and not hosted_media_urls:
        return False
    mirror_status = str(post_row.get("media_mirror_status") or "").strip().lower()
    media_mirror_error = post_row.get("media_mirror_error")
    if _media_mirror_error_has_bad_host_or_content_reason(media_mirror_error):
        return False
    if hosted_thumbnail_url and _is_page_like_media_url(hosted_thumbnail_url):
        return False
    if _hosted_media_urls_need_content_repair(hosted_media_urls=hosted_media_urls):
        return False
    if mirror_status and _hosted_urls_need_cdn_host_repair(
        hosted_thumbnail_url=str(hosted_thumbnail_url or "").strip(),
        hosted_media_urls=hosted_media_urls,
    ):
        return False
    return mirror_status in _HOSTED_MEDIA_HEALTHY_MIRROR_STATUSES or not mirror_status


def _effective_hosted_media_for_selection(
    platform: str,
    post_row: Mapping[str, Any],
    *,
    hosted_thumbnail_url: str | None,
    hosted_media_urls: list[str],
) -> tuple[str | None, list[str]]:
    if _hosted_media_urls_usable_for_effective_selection(
        platform,
        post_row,
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
    ):
        return hosted_thumbnail_url, hosted_media_urls
    return None, []


def _effective_post_media_selection(
    platform: str,
    post_row: Mapping[str, Any],
    *,
    source_thumbnail_url: str | None,
    source_media_urls: list[str],
    hosted_thumbnail_url: str | None,
    hosted_media_urls: list[str],
) -> dict[str, Any]:
    effective_hosted_thumbnail_url, effective_hosted_media_urls = _effective_hosted_media_for_selection(
        platform,
        post_row,
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
    )
    media_urls = effective_hosted_media_urls or source_media_urls
    thumbnail_url = (
        effective_hosted_thumbnail_url
        or source_thumbnail_url
        or _select_non_video_media_url(effective_hosted_media_urls)
        or _select_non_video_media_url(source_media_urls)
        or (media_urls[0] if media_urls else None)
    )
    return {
        "thumbnail_url": thumbnail_url,
        "media_urls": media_urls,
        "hosted_thumbnail_url": effective_hosted_thumbnail_url,
        "hosted_media_urls": effective_hosted_media_urls,
        "hosted_media_usable": bool(effective_hosted_thumbnail_url or effective_hosted_media_urls),
    }


def _repair_reasons_target_bad_hosted_media(repair_reasons: Sequence[Any]) -> bool:
    normalized = {str(reason or "").strip().lower() for reason in repair_reasons or []}
    return bool({"legacy_hosted_url", "hosted_content"} & normalized)


def _should_quarantine_hosted_media_after_mirror_result(
    *,
    result: Mapping[str, Any],
    repair_reasons: Sequence[Any],
) -> bool:
    status = str(result.get("status") or "").strip().lower()
    if status not in {"failed", "partial"}:
        return False
    targeted_bad_hosted_media = _repair_reasons_target_bad_hosted_media(repair_reasons)
    if targeted_bad_hosted_media:
        return True
    if _media_mirror_error_has_bad_host_or_content_reason(result.get("error")):
        return True
    if bool(result.get("retryable_error")):
        return False
    return False


def _source_media_urls_need_quality_repair(*, platform: str, source_media_urls: list[str]) -> bool:
    normalized_platform = (platform or "").strip().lower()
    urls = [str(url).strip() for url in (source_media_urls or []) if str(url).strip()]
    if not urls:
        return False
    if any(_is_page_like_media_url(url) for url in urls):
        return True
    if normalized_platform in {"tiktok", "youtube"} and not any(_is_video_like_media_url(url) for url in urls):
        return True
    return False


def _source_media_urls_support_ytdlp_mirror(*, platform: str, source_media_urls: list[str]) -> bool:
    normalized_platform = (platform or "").strip().lower()
    if normalized_platform not in {"tiktok", "youtube"}:
        return False
    urls = [str(url).strip() for url in (source_media_urls or []) if str(url).strip()]
    return bool(urls) and all(_is_page_like_media_url(url) for url in urls)


def _platform_post_avatar_columns(platform: str) -> tuple[str, str]:
    normalized_platform = (platform or "").strip().lower()
    if normalized_platform == "instagram":
        return ("owner_profile_pic_url", "hosted_owner_profile_pic_url")
    return ("user_avatar_url", "hosted_user_avatar_url")


def _platform_post_avatar_urls(platform: str, post_row: dict[str, Any]) -> tuple[str, str]:
    source_field, hosted_field = _platform_post_avatar_columns(platform)
    source_avatar_url = str(post_row.get(source_field) or "").strip()
    hosted_avatar_url = str(post_row.get(hosted_field) or "").strip()
    return source_avatar_url, hosted_avatar_url


def _extract_platform_post_asset_manifest(
    platform: str,
    post_row: dict[str, Any],
    *,
    conn: Any | None = None,
) -> dict[str, Any]:
    normalized_platform = (platform or "").strip().lower()
    asset_manifest = post_row.get("asset_manifest")
    if isinstance(asset_manifest, dict) and (
        not normalized_platform or _platform_posts_has_column(normalized_platform, "asset_manifest", conn=conn)
    ):
        return dict(asset_manifest)
    return _extract_media_asset_meta_from_raw_data(post_row.get("raw_data"))


def _platform_post_has_stale_media_asset_meta(post_row: dict[str, Any], *, conn: Any | None = None) -> bool:
    hosted_thumbnail_url = str(post_row.get("hosted_thumbnail_url") or "").strip()
    hosted_media_urls = _as_text_list(post_row.get("hosted_media_urls"))
    if not hosted_thumbnail_url and not hosted_media_urls:
        return False

    platform = str(post_row.get("platform") or post_row.get("_platform") or "").strip().lower()
    media_asset_meta = _extract_platform_post_asset_manifest(platform, post_row, conn=conn)
    if not media_asset_meta:
        return False
    hosted_assets = media_asset_meta.get("hosted_assets") if isinstance(media_asset_meta, dict) else None
    thumbnail_hosted = media_asset_meta.get("thumbnail_hosted") if isinstance(media_asset_meta, dict) else None

    hosted_asset_urls = []
    if isinstance(hosted_assets, list):
        hosted_asset_urls = [
            str(item.get("url") or "").strip()
            for item in hosted_assets
            if isinstance(item, dict) and str(item.get("url") or "").strip()
        ]

    thumbnail_hosted_url = str(thumbnail_hosted.get("url") or "").strip() if isinstance(thumbnail_hosted, dict) else ""

    if hosted_thumbnail_url and thumbnail_hosted_url != hosted_thumbnail_url:
        return True
    if hosted_media_urls and len(hosted_asset_urls) < len(hosted_media_urls):
        return True
    if hosted_media_urls and hosted_asset_urls != hosted_media_urls[: len(hosted_asset_urls)]:
        return True
    return False


def _platform_post_missing_display_variants(
    platform: str,
    post_row: dict[str, Any],
    *,
    conn: Any | None = None,
) -> bool:
    hosted_thumbnail_url = str(post_row.get("hosted_thumbnail_url") or "").strip()
    source_thumbnail_url, source_media_urls = _platform_post_source_urls(platform, post_row)
    if _is_video_like_media_url(hosted_thumbnail_url) and _select_non_video_media_url(source_media_urls):
        return True
    cover_url = hosted_thumbnail_url or source_thumbnail_url
    if not cover_url or _is_video_like_media_url(cover_url):
        return False
    asset_manifest = _extract_platform_post_asset_manifest(platform, post_row, conn=conn)
    if not asset_manifest:
        return False
    status = str(asset_manifest.get("display_variants_status") or "").strip().lower()
    if status == "unsupported":
        return False
    if status == "failed":
        return True
    variants = _display_thumbnail_variants_from_manifest(asset_manifest)
    if not status and not variants:
        return False
    return not any(variants.get(key) for key in _DISPLAY_THUMBNAIL_PRECEDENCE)


def _platform_post_avatar_repair_state(platform: str, post_row: dict[str, Any]) -> dict[str, Any]:
    normalized_platform = (platform or "").strip().lower()
    source_id = _platform_source_id(platform, post_row)
    source_avatar_url, hosted_avatar_url = _platform_post_avatar_urls(platform, post_row)
    resolved_source_avatar_url = str(
        _resolve_post_avatar_url(
            hosted_avatar_url=None,
            direct_avatar_url=source_avatar_url,
            raw_data=post_row.get("raw_data"),
        )
        or ""
    ).strip()
    can_re_resolve = normalized_platform in {"youtube", "tiktok"} and bool(source_id)
    needs_host_repair = bool(hosted_avatar_url) and _hosted_url_needs_cdn_host_repair(hosted_avatar_url)
    missing_source_avatar = not resolved_source_avatar_url
    missing_hosted_avatar = bool(resolved_source_avatar_url) and not hosted_avatar_url
    needs_repair = (
        needs_host_repair
        or missing_hosted_avatar
        or (missing_source_avatar and not hosted_avatar_url and can_re_resolve)
    )
    return {
        "source_field": _platform_post_avatar_columns(platform)[0],
        "hosted_field": _platform_post_avatar_columns(platform)[1],
        "source_avatar_url": resolved_source_avatar_url,
        "hosted_avatar_url": hosted_avatar_url,
        "missing_source_avatar": missing_source_avatar,
        "missing_hosted_avatar": missing_hosted_avatar,
        "needs_host_repair": needs_host_repair,
        "needs_repair": needs_repair,
    }


def _platform_post_repair_reasons(
    platform: str,
    post_row: dict[str, Any],
    *,
    conn: Any | None = None,
) -> list[str]:
    normalized_platform = (platform or "").strip().lower()
    hosted_thumbnail_url = str(post_row.get("hosted_thumbnail_url") or "").strip()
    hosted_media_urls = _as_text_list(post_row.get("hosted_media_urls"))
    mirror_status = str(post_row.get("media_mirror_status") or "").strip().lower()
    source_thumbnail_url, source_media_urls = _platform_post_source_urls(platform, post_row)
    source_id = _platform_source_id(platform, post_row)
    raw_data: dict[str, Any] = raw_data_value if isinstance((raw_data_value := post_row.get("raw_data")), dict) else {}
    avatar_state = _platform_post_avatar_repair_state(platform, post_row)
    reasons: list[str] = []

    if _terminal_media_mirror_has_cover(post_row):
        return []

    if _hosted_urls_need_cdn_host_repair(
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
    ):
        reasons.append("legacy_hosted_url")
    if avatar_state.get("needs_host_repair"):
        reasons.append("legacy_hosted_url")
    if normalized_platform == "instagram":
        hosted_tagged_pics = _as_json_string_map(post_row.get("hosted_tagged_profile_pics"))
        if any(_hosted_url_needs_cdn_host_repair(url) for url in hosted_tagged_pics.values()):
            reasons.append("legacy_hosted_url")
    if _hosted_media_urls_need_content_repair(hosted_media_urls=hosted_media_urls):
        reasons.append("hosted_content")
    if (
        source_media_urls
        and _source_media_urls_need_quality_repair(
            platform=normalized_platform,
            source_media_urls=source_media_urls,
        )
        and (not hosted_media_urls or mirror_status in {"failed", "partial"} or normalized_platform == "instagram")
    ):
        reasons.append("source_quality")
    if normalized_platform == "twitter" and hosted_thumbnail_url and _is_video_like_media_url(hosted_thumbnail_url):
        if _select_non_video_media_url(hosted_media_urls) or _select_non_video_media_url(source_media_urls):
            reasons.append("twitter_video_thumbnail")
    if normalized_platform == "instagram" and source_id:
        if mirror_status in {"failed", "partial", "pending"}:
            reasons.append("mirror_retry")
        if not source_thumbnail_url and not source_media_urls:
            reasons.append("mirror_retry")
    if normalized_platform == "threads" and source_id and raw_data:
        if mirror_status in {"failed", "partial", "pending"}:
            reasons.append("mirror_retry")
        if not source_thumbnail_url and not source_media_urls:
            reasons.append("missing_source_media")
    if normalized_platform in {"tiktok", "youtube"} and not hosted_media_urls:
        reasons.append("missing_hosted_media")
    if (
        normalized_platform in {"tiktok", "youtube"}
        and hosted_media_urls
        and not any(_is_video_like_media_url(url) for url in hosted_media_urls)
    ):
        reasons.append("non_video_hosted_media")
    if source_thumbnail_url and not hosted_thumbnail_url:
        reasons.append("missing_hosted_thumbnail")
    if source_media_urls and len(hosted_media_urls) < len(source_media_urls):
        reasons.append("missing_hosted_media")
    if _platform_post_missing_display_variants(normalized_platform, post_row, conn=conn):
        reasons.append("missing_display_variants")
    if avatar_state.get("missing_source_avatar") and not avatar_state.get("hosted_avatar_url"):
        reasons.append("missing_source_avatar")
    if avatar_state.get("missing_hosted_avatar"):
        reasons.append("missing_hosted_avatar")
    if _platform_post_has_stale_media_asset_meta(post_row, conn=conn):
        reasons.append("stale_media_metadata")

    deduped: list[str] = []
    seen: set[str] = set()
    for reason in reasons:
        if reason in seen:
            continue
        seen.add(reason)
        deduped.append(reason)
    if not deduped and mirror_status in {"failed", "partial", "pending"}:
        deduped.append("mirror_retry")
    return deduped


def _platform_post_needs_media_asset_repair(
    platform: str,
    post_row: dict[str, Any],
    *,
    include_display_variants: bool = True,
) -> bool:
    normalized_platform = (platform or "").strip().lower()
    hosted_thumbnail_url = str(post_row.get("hosted_thumbnail_url") or "").strip()
    hosted_media_urls = _as_text_list(post_row.get("hosted_media_urls"))
    if _terminal_media_mirror_has_cover(post_row):
        return False

    if _hosted_urls_need_cdn_host_repair(
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
    ):
        return True
    if _hosted_media_urls_need_content_repair(hosted_media_urls=hosted_media_urls):
        return True

    source_thumbnail_url, source_media_urls = _platform_post_source_urls(platform, post_row)
    if normalized_platform == "twitter" and hosted_thumbnail_url and _is_video_like_media_url(hosted_thumbnail_url):
        if _select_non_video_media_url(hosted_media_urls) or _select_non_video_media_url(source_media_urls):
            return True

    source_id = _platform_source_id(platform, post_row)
    if normalized_platform == "instagram":
        if not source_id and not source_thumbnail_url and not source_media_urls:
            return False
    elif normalized_platform in {"youtube", "tiktok"}:
        if not source_id:
            return False
    elif normalized_platform == "threads":
        raw_data = post_row.get("raw_data") if isinstance(post_row.get("raw_data"), dict) else {}
        mirror_status = str(post_row.get("media_mirror_status") or "").strip().lower()
        if source_id and raw_data and mirror_status in {"failed", "partial", "pending"}:
            return True
        if not source_thumbnail_url and not source_media_urls:
            return False
    elif not source_thumbnail_url and not source_media_urls:
        return False

    mirror_status = str(post_row.get("media_mirror_status") or "").strip().lower()
    hosted_media_has_bad_reason = _hosted_media_has_known_bad_reason(
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
        media_mirror_error=post_row.get("media_mirror_error"),
    )
    status_marks_hosted_unhealthy = mirror_status in {"failed", "partial"} or (
        mirror_status == "pending" and hosted_media_has_bad_reason
    )
    if status_marks_hosted_unhealthy and not _hosted_media_urls_usable_for_effective_selection(
        normalized_platform,
        post_row,
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
    ):
        if source_id or source_thumbnail_url or source_media_urls:
            return True

    if normalized_platform == "instagram":
        if mirror_status in {"failed", "partial", "pending"}:
            return True
        if source_id and not source_thumbnail_url and not source_media_urls:
            return True

    if normalized_platform in {"tiktok", "youtube"} and not hosted_media_urls:
        return True
    if (
        normalized_platform in {"tiktok", "youtube"}
        and hosted_media_urls
        and not any(_is_video_like_media_url(url) for url in hosted_media_urls)
    ):
        return True
    if source_thumbnail_url and not hosted_thumbnail_url:
        return True
    if source_media_urls and len(hosted_media_urls) < len(source_media_urls):
        return True
    if include_display_variants and _platform_post_missing_display_variants(normalized_platform, post_row):
        return True
    return False


def _platform_post_needs_media_mirror(
    platform: str,
    post_row: dict[str, Any],
    *,
    conn: Any | None = None,
    include_auxiliary_repairs: bool = True,
) -> bool:
    if _terminal_media_mirror_has_cover(post_row):
        return False
    if _platform_post_needs_media_asset_repair(
        platform,
        post_row,
        include_display_variants=include_auxiliary_repairs,
    ):
        return True
    if not include_auxiliary_repairs:
        return False
    if _platform_post_avatar_repair_state(platform, post_row).get("needs_repair"):
        return True
    if _platform_post_has_stale_media_asset_meta(post_row, conn=conn):
        return True
    if _platform_post_missing_display_variants(platform, post_row, conn=conn):
        return True
    return False


def _instagram_post_needs_media_mirror(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.media_mirror import _LOCAL_ROOM_FUNCTIONS

