def _platform_comment_media_needs_mirror(platform: str, comment_row: dict[str, Any]) -> bool:
    normalized_platform = (platform or "").strip().lower()
    source_media_urls = _as_text_list(comment_row.get("media_urls"))
    hosted_media_urls = _as_text_list(comment_row.get("hosted_media_urls"))
    mirror_status = str(comment_row.get("media_mirror_status") or "").strip().lower()
    if not source_media_urls:
        if normalized_platform == "threads" and mirror_status in {"pending", "partial", "failed"}:
            return True
        return False
    if _hosted_urls_need_cdn_host_repair(hosted_thumbnail_url="", hosted_media_urls=hosted_media_urls):
        return True
    if _hosted_media_urls_need_content_repair(hosted_media_urls=hosted_media_urls):
        return True
    if mirror_status in {"pending", "partial", "failed"}:
        return True
    if hosted_media_urls and len(hosted_media_urls) >= len(source_media_urls):
        return False
    return True


def _tiktok_comment_needs_media_mirror(comment_row: dict[str, Any]) -> bool:
    return _platform_comment_media_needs_mirror("tiktok", comment_row)


def _twitter_comment_needs_media_mirror(comment_row: dict[str, Any]) -> bool:
    return _platform_comment_media_needs_mirror("twitter", comment_row)


def _update_platform_post_field(
    *,
    platform: str,
    post_id: str,
    field: str,
    value: Any,
    conn: Any | None = None,
) -> None:
    """Update a single column on a platform post row (safe: checks column existence)."""
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    if not table or not field:
        return
    if not _platform_posts_has_column(normalized_platform, field, conn=conn):
        return
    sql = f"update social.{table} set {field} = %s where id = %s::uuid"
    with pg.db_cursor(conn=conn) as cur:
        cur.execute(sql, [value, post_id])


def _update_platform_post_media_mirror_fields(
    *,
    platform: str,
    post_id: str,
    hosted_thumbnail_url: str | None | object = FIELD_UNSET,
    hosted_media_urls: list[str] | object = FIELD_UNSET,
    media_mirror_status: str | None | object = FIELD_UNSET,
    media_mirror_error: str | None | object = FIELD_UNSET,
    media_mirror_attempt_count: int | object = FIELD_UNSET,
    media_mirror_last_attempt_at: datetime | None | object = FIELD_UNSET,
    media_mirror_last_job_id: str | None | object = FIELD_UNSET,
    conn: Any | None = None,
) -> None:
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    if not table:
        return

    assignments: list[str] = []
    params: list[Any] = []

    def _add(column: str, value: Any, *, as_jsonb: bool = False) -> None:
        if as_jsonb:
            assignments.append(f"{column} = %s::jsonb")
            params.append(json.dumps(value))
            return
        assignments.append(f"{column} = %s")
        params.append(value)

    if hosted_thumbnail_url is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "hosted_thumbnail_url", conn=conn
    ):
        _add("hosted_thumbnail_url", hosted_thumbnail_url)
    if hosted_media_urls is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "hosted_media_urls", conn=conn
    ):
        _add("hosted_media_urls", list(cast(Iterable[Any], hosted_media_urls or [])), as_jsonb=True)
    if media_mirror_status is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "media_mirror_status", conn=conn
    ):
        _add("media_mirror_status", media_mirror_status)
    elif _platform_posts_has_column(normalized_platform, "media_mirror_status", conn=conn):
        hosted_thumbnail_supplied = hosted_thumbnail_url is not FIELD_UNSET and bool(
            str(hosted_thumbnail_url or "").strip()
        )
        hosted_media_supplied = hosted_media_urls is not FIELD_UNSET and bool(
            list(cast(Iterable[Any], hosted_media_urls or []))
        )
        if hosted_thumbnail_supplied or hosted_media_supplied:
            _add("media_mirror_status", "mirrored")
    if media_mirror_error is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "media_mirror_error", conn=conn
    ):
        _add("media_mirror_error", media_mirror_error)
    if media_mirror_attempt_count is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "media_mirror_attempt_count", conn=conn
    ):
        _add("media_mirror_attempt_count", max(0, int(cast(Any, media_mirror_attempt_count))))
    if media_mirror_last_attempt_at is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "media_mirror_last_attempt_at", conn=conn
    ):
        _add("media_mirror_last_attempt_at", media_mirror_last_attempt_at)
    if media_mirror_last_job_id is not FIELD_UNSET and _platform_posts_has_column(
        normalized_platform, "media_mirror_last_job_id", conn=conn
    ):
        _add("media_mirror_last_job_id", media_mirror_last_job_id)

    if not assignments:
        return

    sql = f"update social.{table} set {', '.join(assignments)} where id = %s::uuid returning id::text"
    params.append(post_id)
    with pg.db_cursor(conn=conn) as cur:
        pg.fetch_one_with_cursor(cur, sql, params)


def _update_instagram_post_media_mirror_fields(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.media_mirror import _LOCAL_ROOM_FUNCTIONS

