def _update_platform_post_media_asset_meta(
    *,
    platform: str,
    post_id: str,
    media_asset_meta: dict[str, Any],
    conn: Any | None = None,
) -> None:
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    if not table:
        return
    has_raw_data = _platform_posts_has_column(normalized_platform, "raw_data", conn=conn)
    has_asset_manifest = _platform_posts_has_column(normalized_platform, "asset_manifest", conn=conn)
    if not has_raw_data and not has_asset_manifest:
        return
    payload = dict(media_asset_meta or {})
    if not payload:
        return
    with pg.db_cursor(conn=conn) as cur:
        assignments: list[str] = []
        params: list[Any] = []
        if has_asset_manifest:
            assignments.append("asset_manifest = %s::jsonb")
            params.append(json.dumps(payload))
        if has_raw_data:
            assignments.append(
                """
                raw_data = case
                  when jsonb_typeof(raw_data) = 'object'
                    then jsonb_set(raw_data, '{media_asset_meta}', %s::jsonb, true)
                  else jsonb_build_object('media_asset_meta', %s::jsonb)
                end
                """.strip()
            )
            params.extend([json.dumps(payload), json.dumps(payload)])
        params.append(post_id)
        pg.fetch_one_with_cursor(
            cur,
            f"""
            update social.{table}
            set {", ".join(assignments)}
            where id = %s::uuid
            returning id::text
            """,
            params,
        )


