def _enqueue_platform_media_mirror_job(
    context: SeasonContext | None,
    *,
    platform: str,
    run_id: str | None,
    source_scope: str,
    account: str,
    post_row: dict[str, Any],
    week_index: int | None,
    parent_job_id: str | None,
    conn: Any | None = None,
) -> str | None:
    normalized_platform = (platform or "").strip().lower()
    job_type = PLATFORM_MEDIA_MIRROR_JOB_TYPES.get(normalized_platform)
    if not job_type:
        return None

    post_id = str(post_row.get("id") or "").strip()
    source_id = _platform_source_id(normalized_platform, dict(post_row))
    if not post_id:
        return None
    if not _platform_post_needs_media_mirror(normalized_platform, post_row, conn=conn):
        return None
    if not _run_allows_followup_job_enqueue(run_id, conn=conn):
        return None

    mirror_job_status = "queued" if is_queue_enabled() else "pending"
    config = {
        "run_id": run_id,
        "season_id": context.season_id if context else None,
        "show_id": context.show_id if context else None,
        "platform": normalized_platform,
        "source_scope": source_scope,
        "stage": INSTAGRAM_MEDIA_MIRROR_STAGE,
        "job_type": job_type,
        "account": account,
        "post_id": post_id,
        "source_id": source_id,
        "shortcode": source_id if normalized_platform == "instagram" else None,
        "week_index": week_index,
        "parent_job_id": parent_job_id,
    }
    mirror_job_id = _insert_job_with_conflict_target(
        context,
        run_id=run_id,
        platform=normalized_platform,
        source_scope=source_scope,
        job_type=job_type,
        stage=INSTAGRAM_MEDIA_MIRROR_STAGE,
        config=config,
        status=mirror_job_status,
        priority=250,
        conflict_target_sql="""
            on conflict (platform, (config->>'post_id'))
            where status in ('queued', 'pending', 'retrying', 'running')
              and coalesce(config->>'stage', metadata->>'stage', job_type) = 'media_mirror'
            do nothing
        """,
        existing_lookup_sql="""
            select id::text as id
            from social.scrape_jobs
            where platform = %s
              and status in ('queued', 'pending', 'retrying', 'running')
              and coalesce(config->>'stage', metadata->>'stage', job_type) = %s
              and config->>'post_id' = %s
            order by created_at desc
            limit 1
        """,
        existing_lookup_params=[normalized_platform, INSTAGRAM_MEDIA_MIRROR_STAGE, post_id],
        conn=conn,
    )
    if not mirror_job_id:
        return None
    _update_platform_post_media_mirror_fields(
        platform=normalized_platform,
        post_id=post_id,
        media_mirror_status="pending",
        media_mirror_error=None,
        media_mirror_last_job_id=mirror_job_id,
        conn=conn,
    )
    return mirror_job_id


def _bulk_update_platform_post_media_mirror_pending(
    *,
    platform: str,
    job_rows: Sequence[Mapping[str, Any]],
    conn: Any | None = None,
) -> None:
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    if not table:
        return
    if not job_rows:
        return
    if not _platform_posts_has_column(normalized_platform, "media_mirror_status", conn=conn):
        return

    assignments = ["media_mirror_status = 'pending'"]
    if _platform_posts_has_column(normalized_platform, "media_mirror_error", conn=conn):
        assignments.append("media_mirror_error = null")
    if _platform_posts_has_column(normalized_platform, "media_mirror_last_job_id", conn=conn):
        assignments.append("media_mirror_last_job_id = v.job_id::uuid")

    values = [
        (
            str(row.get("post_id") or "").strip(),
            str(row.get("job_id") or "").strip(),
        )
        for row in job_rows
        if str(row.get("post_id") or "").strip() and str(row.get("job_id") or "").strip()
    ]
    if not values:
        return

    pg.execute_values_no_return(
        f"""
        update social.{table} as p
        set {", ".join(assignments)}
        from (values %s) as v(post_id, job_id)
        where p.id = v.post_id::uuid
        """,
        values,
        conn=conn,
    )


def _active_platform_media_mirror_job_rows(
    *,
    platform: str,
    post_ids: Sequence[str],
    conn: Any | None = None,
) -> list[dict[str, str]]:
    normalized_platform = (platform or "").strip().lower()
    normalized_post_ids = [str(post_id or "").strip() for post_id in post_ids if str(post_id or "").strip()]
    if not normalized_platform or not normalized_post_ids:
        return []
    rows = pg.fetch_all(
        """
        select
          id::text as job_id,
          config->>'post_id' as post_id
        from social.scrape_jobs
        where platform = %s
          and status in ('queued', 'pending', 'retrying', 'running')
          and coalesce(config->>'stage', metadata->>'stage', job_type) = %s
          and config->>'post_id' = any(%s)
        order by created_at desc
        """,
        [normalized_platform, INSTAGRAM_MEDIA_MIRROR_STAGE, normalized_post_ids],
        conn=conn,
    )
    seen: set[str] = set()
    out: list[dict[str, str]] = []
    for row in rows:
        post_id = str(row.get("post_id") or "").strip()
        job_id = str(row.get("job_id") or "").strip()
        if not post_id or not job_id or post_id in seen:
            continue
        seen.add(post_id)
        out.append({"job_id": job_id, "post_id": post_id})
    return out


def _bulk_enqueue_platform_media_mirror_jobs(
    context: SeasonContext | None,
    *,
    platform: str,
    run_id: str | None,
    source_scope: str,
    account: str,
    post_rows: Sequence[Mapping[str, Any]],
    week_index: int | None,
    parent_job_id: str | None,
    conn: Any | None = None,
) -> list[str]:
    normalized_platform = (platform or "").strip().lower()
    job_type = PLATFORM_MEDIA_MIRROR_JOB_TYPES.get(normalized_platform)
    if not job_type:
        return []
    if not _run_allows_followup_job_enqueue(run_id, conn=conn):
        return []

    candidate_rows: dict[str, Mapping[str, Any]] = {}
    for post_row in post_rows:
        row = dict(post_row or {})
        post_id = str(row.get("id") or "").strip()
        if not post_id:
            continue
        if post_id in candidate_rows:
            continue
        if not _platform_post_needs_media_mirror(normalized_platform, row, conn=conn):
            continue
        candidate_rows[post_id] = row
    if not candidate_rows:
        return []

    mirror_job_status = "queued" if is_queue_enabled() else "pending"
    creator_runtime_version = dict(_resolve_runtime_version_stamp_for_stage(INSTAGRAM_MEDIA_MIRROR_STAGE))
    rows: list[tuple[Any, ...]] = []
    for post_id, post_row in candidate_rows.items():
        source_id = _platform_source_id(normalized_platform, dict(post_row))
        config_payload = {
            "run_id": run_id,
            "season_id": context.season_id if context else None,
            "show_id": context.show_id if context else None,
            "platform": normalized_platform,
            "source_scope": source_scope,
            "stage": INSTAGRAM_MEDIA_MIRROR_STAGE,
            "job_type": job_type,
            "account": account,
            "post_id": post_id,
            "source_id": source_id,
            "shortcode": source_id if normalized_platform == "instagram" else None,
            "week_index": week_index,
            "parent_job_id": parent_job_id,
            "media_mirror_provider": "cloudflare",
        }
        required_execution_backend = _job_required_execution_backend(config_payload, platform=normalized_platform)
        effective_runtime_version = _resolve_effective_runtime_version(
            required_execution_backend=required_execution_backend,
            stage=INSTAGRAM_MEDIA_MIRROR_STAGE,
        )
        if required_execution_backend:
            config_payload.setdefault("required_execution_backend", required_execution_backend)
        if effective_runtime_version:
            config_payload.setdefault("required_runtime_version", effective_runtime_version)
        elif required_execution_backend != "modal":
            config_payload.setdefault("required_runtime_version", creator_runtime_version)
        if creator_runtime_version:
            config_payload.setdefault("created_by_runtime_version", creator_runtime_version)
        runtime_metadata = _job_runtime_metadata(
            INSTAGRAM_MEDIA_MIRROR_STAGE,
            runtime_version=effective_runtime_version,
            created_by_runtime_version=creator_runtime_version,
        )
        runtime_metadata.update(
            {
                "activity": {
                    "phase": "media_mirror_queued",
                    "platform": normalized_platform,
                    "account": account,
                    "post_id": post_id,
                    "source_id": source_id or None,
                    "target": "cloudflare",
                    "queued_at": _iso(_now_utc()),
                },
                "media_mirror": {
                    "provider": "cloudflare",
                    "status": "queued",
                    "post_id": post_id,
                    "source_id": source_id or None,
                    "parent_job_id": parent_job_id,
                },
            }
        )

        rows.append(
            (
                run_id,
                normalized_platform,
                job_type,
                _json_dumps(config_payload),
                mirror_job_status,
                _now_utc(),
                250,
                context.show_id if context is not None else None,
                context.season_id if context is not None else None,
                source_scope,
                _json_dumps(runtime_metadata),
                0,
            )
        )

    inserted = pg.execute_values_returning(
        """
        insert into social.scrape_jobs (
          run_id,
          platform,
          job_type,
          config,
          status,
          available_at,
          priority,
          show_id,
          season_id,
          source_scope,
          metadata,
          attempt_count
        )
        values %s
        on conflict (platform, (config->>'post_id'))
        where status in ('queued', 'pending', 'retrying', 'running')
          and coalesce(config->>'stage', metadata->>'stage', job_type) = 'media_mirror'
        do nothing
        returning id::text as job_id, config->>'post_id' as post_id
        """,
        rows,
        conn=conn,
    )
    inserted_rows = [
        {
            "job_id": str(row.get("job_id") or "").strip(),
            "post_id": str(row.get("post_id") or "").strip(),
        }
        for row in inserted
        if str(row.get("job_id") or "").strip() and str(row.get("post_id") or "").strip()
    ]
    inserted_post_ids = {str(row["post_id"]) for row in inserted_rows}
    reused_rows = _active_platform_media_mirror_job_rows(
        platform=normalized_platform,
        post_ids=[post_id for post_id in candidate_rows if post_id not in inserted_post_ids],
        conn=conn,
    )
    job_rows_by_post_id: dict[str, dict[str, str]] = {}
    for row in [*inserted_rows, *reused_rows]:
        post_id = str(row.get("post_id") or "").strip()
        job_id = str(row.get("job_id") or "").strip()
        if post_id and job_id:
            job_rows_by_post_id[post_id] = {"job_id": job_id, "post_id": post_id}
    all_job_rows = [job_rows_by_post_id[post_id] for post_id in candidate_rows if post_id in job_rows_by_post_id]
    if not all_job_rows:
        return []
    if run_id and inserted_rows:
        _increment_run_counters_on_job_create_batch(
            run_id=run_id,
            stage=INSTAGRAM_MEDIA_MIRROR_STAGE,
            status=mirror_job_status,
            count=len(inserted_rows),
            conn=conn,
        )
    _bulk_update_platform_post_media_mirror_pending(
        platform=normalized_platform,
        job_rows=all_job_rows,
        conn=conn,
    )
    return [str(row["job_id"]) for row in all_job_rows]


def _enqueue_instagram_media_mirror_job(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.media_mirror import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["_enqueue_instagram_media_mirror_job"](*args, **kwargs)


def _run_allows_followup_job_enqueue(run_id: str | None, *, conn: Any | None = None) -> bool:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return True
    row = pg.fetch_one(
        """
        select status
        from social.scrape_runs
        where id = %s::uuid
        """,
        [normalized_run_id],
        conn=conn,
    )
    status = str((row or {}).get("status") or "").strip().lower()
    return status in {"queued", "pending", "running", "retrying"}


def _comment_media_platform_schema(platform: str) -> tuple[str, str, str] | None:
    normalized_platform = (platform or "").strip().lower()
    mapping = {
        "instagram": ("instagram_comments", "instagram_posts", "posted_at"),
        "facebook": ("facebook_comments", "facebook_posts", "posted_at"),
        "threads": ("meta_threads_comments", "meta_threads_posts", "posted_at"),
    }
    return mapping.get(normalized_platform)


def _update_platform_comment_media_mirror_fields(
    *,
    platform: str,
    comment_id: str,
    post_id: str = "",
    comment_db_id: str = "",
    hosted_media_urls: list[str] | object = FIELD_UNSET,
    media_mirror_status: str | None | object = FIELD_UNSET,
    media_mirror_error: str | None | object = FIELD_UNSET,
    media_mirror_attempt_count: int | object = FIELD_UNSET,
    media_mirror_last_attempt_at: datetime | None | object = FIELD_UNSET,
    media_mirror_last_job_id: str | None | object = FIELD_UNSET,
    conn: Any | None = None,
) -> None:
    schema = _comment_media_platform_schema(platform)
    if not schema:
        return
    comment_table, _, _ = schema
    assignments: list[str] = []
    params: list[Any] = []

    def _add(column: str, value: Any, *, as_jsonb: bool = False) -> None:
        if not _column_exists("social", comment_table, column):
            return
        if as_jsonb:
            assignments.append(f"{column} = %s::jsonb")
            params.append(json.dumps(value))
            return
        assignments.append(f"{column} = %s")
        params.append(value)

    if hosted_media_urls is not FIELD_UNSET:
        _add("hosted_media_urls", list(cast(Iterable[Any], hosted_media_urls or [])), as_jsonb=True)
    if media_mirror_status is not FIELD_UNSET:
        _add("media_mirror_status", media_mirror_status)
    if media_mirror_error is not FIELD_UNSET:
        _add("media_mirror_error", media_mirror_error)
    if media_mirror_attempt_count is not FIELD_UNSET:
        _add("media_mirror_attempt_count", max(0, int(cast(Any, media_mirror_attempt_count))))
    if media_mirror_last_attempt_at is not FIELD_UNSET:
        _add("media_mirror_last_attempt_at", media_mirror_last_attempt_at)
    if media_mirror_last_job_id is not FIELD_UNSET:
        _add("media_mirror_last_job_id", media_mirror_last_job_id)

    if not assignments:
        return

    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform == "instagram":
        identity_clauses: list[str] = []
        identity_params: list[Any] = []
        if comment_db_id:
            identity_clauses.append("(%s <> '' and id = nullif(%s, '')::uuid)")
            identity_params.extend([comment_db_id, comment_db_id])
        if comment_id and post_id:
            identity_clauses.append("(%s <> '' and %s <> '' and comment_id = %s and post_id = nullif(%s, '')::uuid)")
            identity_params.extend([comment_id, post_id, comment_id, post_id])
        if not identity_clauses:
            return
        params.extend(identity_params)
        where_sql = f"({' or '.join(identity_clauses)})"
    else:
        params.append(comment_id)
        where_sql = "comment_id = %s"
    with pg.db_cursor(conn=conn) as cur:
        pg.fetch_one_with_cursor(
            cur,
            f"update social.{comment_table} set {', '.join(assignments)} where {where_sql} returning id::text",
            params,
        )


def _enqueue_platform_comment_media_mirror_job(
    context: SeasonContext,
    *,
    platform: str,
    run_id: str | None,
    source_scope: str,
    account: str,
    comment_row: dict[str, Any],
    parent_job_id: str | None,
    conn: Any | None = None,
) -> str | None:
    schema = _comment_media_platform_schema(platform)
    if not schema:
        return None
    comment_table, _, _ = schema
    if not _column_exists("social", comment_table, "media_urls"):
        return None
    normalized_platform = (platform or "").strip().lower()
    comment_id = str(comment_row.get("comment_id") or "").strip()
    comment_db_id = str(comment_row.get("id") or "").strip()
    post_id = str(comment_row.get("post_id") or "").strip()
    if not comment_id or not post_id:
        return None
    if not _platform_comment_media_needs_mirror(normalized_platform, comment_row):
        return None

    job_type = PLATFORM_COMMENT_MEDIA_MIRROR_JOB_TYPES.get(normalized_platform)
    if not job_type:
        return None
    if not _run_allows_followup_job_enqueue(run_id, conn=conn):
        return None
    mirror_job_status = "queued" if is_queue_enabled() else "pending"
    config = {
        "run_id": run_id,
        "season_id": context.season_id,
        "show_id": context.show_id,
        "platform": normalized_platform,
        "source_scope": source_scope,
        "stage": COMMENT_MEDIA_MIRROR_STAGE,
        "job_type": job_type,
        "account": account,
        "comment_id": comment_id,
        "comment_db_id": comment_db_id,
        "post_id": post_id,
        "parent_job_id": parent_job_id,
    }
    existing_lookup_sql = """
        select id::text as id
        from social.scrape_jobs
        where platform = %s
          and status in ('queued', 'pending', 'retrying', 'running')
          and coalesce(config->>'stage', metadata->>'stage', job_type) = %s
    """
    existing_lookup_params: list[Any] = [normalized_platform, COMMENT_MEDIA_MIRROR_STAGE]
    if comment_db_id:
        existing_lookup_sql += "\n  and config->>'comment_db_id' = %s"
        existing_lookup_params.append(comment_db_id)
    else:
        existing_lookup_sql += "\n  and config->>'comment_id' = %s\n  and config->>'post_id' = %s"
        existing_lookup_params.extend([comment_id, post_id])
    existing_lookup_sql += "\norder by created_at desc\nlimit 1"

    mirror_job_id = _insert_job_with_conflict_target(
        context,
        run_id=run_id,
        platform=normalized_platform,
        source_scope=source_scope,
        job_type=job_type,
        stage=COMMENT_MEDIA_MIRROR_STAGE,
        config=config,
        status=mirror_job_status,
        priority=275,
        conflict_target_sql="""
            on conflict (
              platform,
              (
                coalesce(
                  nullif(config->>'comment_db_id', ''),
                  case
                    when coalesce(config->>'post_id', '') <> '' and coalesce(config->>'comment_id', '') <> ''
                      then concat(config->>'post_id', ':', config->>'comment_id')
                    else null
                  end
                )
              )
            )
            where status in ('queued', 'pending', 'retrying', 'running')
              and coalesce(config->>'stage', metadata->>'stage', job_type) = 'comment_media_mirror'
            do nothing
        """,
        existing_lookup_sql=existing_lookup_sql,
        existing_lookup_params=existing_lookup_params,
        conn=conn,
    )
    if not mirror_job_id:
        return None
    _update_platform_comment_media_mirror_fields(
        platform=normalized_platform,
        comment_id=comment_id,
        post_id=post_id,
        comment_db_id=comment_db_id,
        media_mirror_status="pending",
        media_mirror_error=None,
        media_mirror_last_job_id=mirror_job_id,
        conn=conn,
    )
    return mirror_job_id


