def _load_comment_media_rows_for_post(
    *,
    platform: str,
    post_row: dict[str, Any],
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = (platform or "").strip().lower()
    post_db_id = str(post_row.get("id") or "").strip()
    source_id = _platform_source_id(normalized_platform, dict(post_row))

    def _fetch(sql: str, params: list[Any]) -> list[dict[str, Any]]:
        if conn is None:
            return pg.fetch_all(sql, params)
        with pg.db_cursor(conn=conn) as cur:
            return pg.fetch_all_with_cursor(cur, sql, params)

    if normalized_platform == "instagram":
        if not post_db_id or not _column_exists("social", "instagram_comments", "media_urls"):
            return []
        return _fetch(
            """
            select *
            from social.instagram_comments
            where post_id = %s::uuid
              and jsonb_array_length(coalesce(media_urls, '[]'::jsonb)) > 0
            """,
            [post_db_id],
        )
    if normalized_platform == "facebook":
        if not post_db_id or not _column_exists("social", "facebook_comments", "media_urls"):
            return []
        return _fetch(
            """
            select *
            from social.facebook_comments
            where post_id = %s::uuid
              and jsonb_array_length(coalesce(media_urls, '[]'::jsonb)) > 0
            """,
            [post_db_id],
        )
    if normalized_platform == "threads":
        if not post_db_id or not _column_exists("social", "meta_threads_comments", "media_urls"):
            return []
        return _fetch(
            """
            select *
            from social.meta_threads_comments
            where post_id = %s::uuid
              and jsonb_array_length(coalesce(media_urls, '[]'::jsonb)) > 0
            """,
            [post_db_id],
        )
    if normalized_platform == "tiktok":
        if not post_db_id or not _tiktok_comments_has_column("media_urls", conn=conn):
            return []
        return _fetch(
            """
            select *
            from social.tiktok_comments
            where post_id = %s::uuid
              and jsonb_array_length(coalesce(media_urls, '[]'::jsonb)) > 0
            """,
            [post_db_id],
        )
    if normalized_platform == "twitter":
        if not source_id or not _platform_posts_has_column("twitter", "media_urls"):
            return []
        return _fetch(
            """
            select *
            from social.twitter_tweets
            where coalesce(reply_to_tweet_id, quoted_tweet_id) = %s
              and jsonb_array_length(coalesce(media_urls, '[]'::jsonb)) > 0
              and (is_reply = true or is_quote = true)
            """,
            [source_id],
        )
    return []


def _enqueue_comment_media_repairs_for_post(
    context: SeasonContext,
    *,
    platform: str,
    run_id: str | None,
    source_scope: str,
    account: str,
    post_row: dict[str, Any],
    parent_job_id: str | None,
    conn: Any | None = None,
) -> int:
    normalized_platform = (platform or "").strip().lower()
    enqueued = 0
    for comment_row in _load_comment_media_rows_for_post(platform=normalized_platform, post_row=post_row, conn=conn):
        if not _platform_comment_media_needs_mirror(normalized_platform, comment_row):
            continue
        mirror_job_id: str | None = None
        if normalized_platform in {"instagram", "facebook", "threads"}:
            mirror_job_id = _enqueue_platform_comment_media_mirror_job(
                context,
                platform=normalized_platform,
                run_id=run_id,
                source_scope=source_scope,
                account=account,
                comment_row=comment_row,
                parent_job_id=parent_job_id,
                conn=conn,
            )
        elif normalized_platform == "tiktok":
            mirror_job_id = _enqueue_tiktok_comment_media_mirror_job(
                context,
                run_id=run_id,
                source_scope=source_scope,
                account=account,
                comment_row=comment_row,
                parent_job_id=parent_job_id,
                conn=conn,
            )
        elif normalized_platform == "twitter":
            mirror_job_id = _enqueue_twitter_comment_media_mirror_job(
                context,
                run_id=run_id,
                source_scope=source_scope,
                account=account,
                comment_row=comment_row,
                parent_job_id=parent_job_id,
                conn=conn,
            )
        if mirror_job_id:
            enqueued += 1
    return enqueued


def _run_existing_post_details_refresh(
    context: SeasonContext,
    *,
    platform: str,
    run_id: str | None,
    account: str,
    opts: IngestOptions,
    job_id: str,
    activity: dict[str, Any],
    flush_progress: Callable[..., None],
) -> tuple[int, int, dict[str, Any]]:
    target_source_ids = _target_source_ids_for_platform(opts, platform)
    existing_posts = _load_existing_posts(
        platform,
        context,
        account,
        opts.date_start,
        opts.date_end,
        source_ids=target_source_ids,
    )
    repaired_posts = 0
    media_mirror_jobs_enqueued = 0
    comment_media_mirror_jobs_enqueued = 0
    youtube_media_resolution_attempts = 0
    youtube_media_resolution_updates = 0
    activity["phase"] = "details_refresh_existing_posts"
    flush_progress(force=True)
    for row in existing_posts:
        post_row = dict(row)
        post_id = str(post_row.get("id") or "").strip()
        if not post_id:
            continue
        repaired_posts += 1
        activity["posts_checked"] = repaired_posts
        activity["matched_posts"] = repaired_posts
        activity["phase"] = "details_refresh_enqueue_repairs"
        if platform == "youtube":
            video_id = str(post_row.get("video_id") or "").strip()
            if video_id:
                needs_source_refresh = bool(opts.youtube_force_media_refresh)
                if not needs_source_refresh:
                    source_thumbnail_url, source_media_urls = _platform_post_source_urls("youtube", post_row)
                    needs_source_refresh = not source_thumbnail_url or not source_media_urls
                if needs_source_refresh:
                    youtube_media_resolution_attempts += 1
                    try:
                        resolution = _resolve_youtube_media_for_video_id(video_id=video_id)
                        resolved_thumbnail_url = (
                            str((resolution or {}).get("thumbnail_url") or "").strip() or FIELD_UNSET
                        )
                        resolved_media_urls = [
                            str(url).strip() for url in ((resolution or {}).get("media_urls") or []) if str(url).strip()
                        ]
                        with pg.db_connection(label="youtube-details-refresh-update") as conn:
                            _update_youtube_post_source_media_fields(
                                post_id=post_id,
                                thumbnail_url=resolved_thumbnail_url,
                                media_urls=resolved_media_urls if resolved_media_urls else FIELD_UNSET,
                                conn=conn,
                            )
                            if isinstance((resolution or {}).get("media_asset_meta"), dict):
                                _update_platform_post_media_asset_meta(
                                    platform="youtube",
                                    post_id=post_id,
                                    media_asset_meta=dict((resolution or {}).get("media_asset_meta") or {}),
                                    conn=conn,
                                )
                            with pg.db_cursor(conn=conn) as cur:
                                refreshed = pg.fetch_one_with_cursor(
                                    cur,
                                    (
                                        "select to_jsonb(v) as post_json "
                                        "from social.youtube_videos v where v.id = %s::uuid"
                                    ),
                                    [post_id],
                                )
                        if isinstance(refreshed, dict) and isinstance(refreshed.get("post_json"), dict):
                            post_row = dict(refreshed.get("post_json") or {})
                            post_row["id"] = post_id
                        youtube_media_resolution_updates += 1
                    except Exception:  # noqa: BLE001
                        logger.exception(
                            "[youtube] Details refresh failed to resolve source media for %s",
                            video_id,
                        )
        with pg.db_connection(label=f"{platform}-details-refresh-enqueue") as conn:
            if not opts.details_refresh_skip_media_followups and _platform_post_needs_media_mirror(
                platform,
                post_row,
                conn=conn,
            ):
                try:
                    mirror_job_id = _enqueue_platform_media_mirror_job(
                        context,
                        platform=platform,
                        run_id=run_id,
                        source_scope=opts.source_scope,
                        account=account,
                        post_row=post_row,
                        week_index=None,
                        parent_job_id=job_id,
                        conn=conn,
                    )
                    if mirror_job_id:
                        media_mirror_jobs_enqueued += 1
                except Exception:  # noqa: BLE001
                    logger.exception(
                        "[%s] Failed to enqueue media repair during details refresh for post=%s",
                        platform,
                        post_id,
                    )
            if not opts.details_refresh_skip_media_followups:
                try:
                    comment_media_mirror_jobs_enqueued += _enqueue_comment_media_repairs_for_post(
                        context,
                        platform=platform,
                        run_id=run_id,
                        source_scope=opts.source_scope,
                        account=account,
                        post_row=post_row,
                        parent_job_id=job_id,
                        conn=conn,
                    )
                except Exception:  # noqa: BLE001
                    logger.exception(
                        "[%s] Failed to enqueue comment-media repairs during details refresh for post=%s",
                        platform,
                        post_id,
                    )
        flush_progress()
    activity["phase"] = "details_refresh_end"
    flush_progress(force=True)
    retrieval_meta: dict[str, Any] = {
        "source": "db_existing_posts",
        "details_refreshed_posts": repaired_posts,
        "media_mirror_jobs_enqueued": media_mirror_jobs_enqueued,
        "comment_media_mirror_jobs_enqueued": comment_media_mirror_jobs_enqueued,
        "scrape_counters": {"posts": repaired_posts, "comments": 0},
        "persist_counters": {"posts_upserted": repaired_posts, "comments_upserted": 0},
        "activity": _build_progress_activity_payload(activity, now=_now_utc()),
    }
    if platform == "youtube":
        retrieval_meta["details_refresh_media_resolution_attempts"] = youtube_media_resolution_attempts
        retrieval_meta["details_refresh_media_resolution_updates"] = youtube_media_resolution_updates
    if opts.details_refresh_skip_media_followups:
        retrieval_meta["details_refresh_skip_media_followups"] = True
    return repaired_posts, 0, retrieval_meta


def _instagram_comment_raw_payload(comment: Any) -> dict[str, Any]:
    if hasattr(comment, "to_dict"):
        value = comment.to_dict()
    else:
        value = getattr(comment, "raw_data", None)
    return dict(value) if isinstance(value, Mapping) else {}


def _instagram_comment_author_full_name(comment: Any, raw_data: Mapping[str, Any]) -> str | None:
    for candidate in (
        getattr(comment, "owner_full_name", None),
        getattr(comment, "author_full_name", None),
        raw_data.get("ownerFullName"),
    ):
        normalized = str(candidate or "").strip()
        if normalized:
            return normalized
    for key in ("owner", "user"):
        nested = raw_data.get(key)
        if isinstance(nested, Mapping):
            normalized = str(nested.get("full_name") or nested.get("fullName") or "").strip()
            if normalized:
                return normalized
    return None


def _instagram_comment_author_profile_pic_hd(comment: Any, raw_data: Mapping[str, Any]) -> str | None:
    for candidate in (
        getattr(comment, "owner_profile_pic_url_hd", None),
        getattr(comment, "author_profile_pic_url_hd", None),
        raw_data.get("ownerProfilePicUrlHd"),
    ):
        normalized = str(candidate or "").strip()
        if normalized:
            return normalized
    for key in ("owner", "user"):
        nested = raw_data.get(key)
        if isinstance(nested, Mapping):
            normalized = str(nested.get("profile_pic_url_hd") or nested.get("profilePicUrlHd") or "").strip()
            if normalized:
                return normalized
    return None


_INSTAGRAM_COMMENT_METADATA_WRITE_FLAG = "SOCIAL_INSTAGRAM_COMMENT_METADATA_WRITES_ENABLED"
_INSTAGRAM_COMMENT_METADATA_COLUMNS = (
    "is_covered",
    "is_ranked",
    "comment_index",
    "phase",
    "did_report_as_spam",
    "status",
    "is_edited",
    "is_pinned",
    "meta_ai_comment_type",
    "child_comment_count",
    "liked_by_media_coauthors",
    "cursor_min_id",
    "cursor_param",
    "cursor_payload",
    "comment_filter_param",
)
_INSTAGRAM_COMMENT_PHASES = {"ranked", "headload", "fb_crosspost", "child"}
_instagram_comment_metadata_column_cache: dict[tuple[int, str], bool] = {}
_instagram_comment_metadata_disabled_logged_jobs: set[str] = set()
_instagram_comment_metadata_disabled_log_lock = Lock()
_INSTAGRAM_COMMENT_METADATA_RAW_DATA_KEYS = frozenset(
    {
        *_INSTAGRAM_COMMENT_METADATA_COLUMNS,
        "api_phase",
        "comment_phase",
        "source_phase",
        "isCovered",
        "isRanked",
        "commentIndex",
        "didReportAsSpam",
        "isEdited",
        "isPinned",
        "metaAiCommentType",
        "childCommentCount",
        "likedByMediaCoauthors",
        "cursorMinId",
        "cursorParam",
        "cursorPayload",
        "commentFilterParam",
    }
)


def _instagram_comment_metadata_writes_enabled() -> bool:
    return _env_truthy(_INSTAGRAM_COMMENT_METADATA_WRITE_FLAG, default=True)


def _column_exists_in_context(schema: str, table: str, column: str, *, conn: Any | None = None) -> bool:
    if conn is None:
        return _column_exists(schema, table, column)
    return _column_exists(schema, table, column, conn=conn)


def _comment_lifecycle_supported_in_context(table: str, *, conn: Any | None = None) -> bool:
    if conn is None:
        return _comment_lifecycle_supported(table)
    return _comment_lifecycle_supported(table, conn=conn)


def _instagram_comment_metadata_column_exists(column: str, *, conn: Any | None = None) -> bool:
    cache_key = (id(_column_exists), column)
    cached = _instagram_comment_metadata_column_cache.get(cache_key)
    if cached is None:
        cached = _column_exists_in_context("social", "instagram_comments", column, conn=conn)
        _instagram_comment_metadata_column_cache[cache_key] = cached
    return cached


def _log_instagram_comment_metadata_writes_disabled_once(payload: Mapping[str, Any]) -> None:
    job_key = str(payload.get("job_id") or "__no_job__").strip() or "__no_job__"
    with _instagram_comment_metadata_disabled_log_lock:
        if job_key in _instagram_comment_metadata_disabled_logged_jobs:
            return
        _instagram_comment_metadata_disabled_logged_jobs.add(job_key)
    logger.info(
        "Instagram comment metadata writes disabled by %s for job_id=%s",
        _INSTAGRAM_COMMENT_METADATA_WRITE_FLAG,
        None if job_key == "__no_job__" else job_key,
    )


def _strip_instagram_comment_metadata_raw_data(value: Any) -> Any:
    if isinstance(value, Mapping):
        return {
            str(key): _strip_instagram_comment_metadata_raw_data(item)
            for key, item in value.items()
            if str(key) not in _INSTAGRAM_COMMENT_METADATA_RAW_DATA_KEYS
        }
    if isinstance(value, list):
        return [_strip_instagram_comment_metadata_raw_data(item) for item in value]
    return value


def _instagram_comment_raw_data_for_write(comment: Any) -> dict[str, Any]:
    raw_data = comment.to_dict() if hasattr(comment, "to_dict") else {}
    if not isinstance(raw_data, Mapping):
        return {}
    if _instagram_comment_metadata_writes_enabled():
        return dict(raw_data)
    return _strip_instagram_comment_metadata_raw_data(raw_data)


def _metadata_bool(value: Any, *, default: bool = False) -> bool:
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    normalized = str(value or "").strip().lower()
    if not normalized:
        return default
    if normalized in {"1", "true", "yes", "on", "y"}:
        return True
    if normalized in {"0", "false", "no", "off", "n"}:
        return False
    return default


def _metadata_int(value: Any) -> int | None:
    if value is None or isinstance(value, bool):
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _metadata_text(value: Any) -> str | None:
    normalized = str(value or "").strip()
    return normalized or None


def _metadata_mapping(value: Any) -> dict[str, Any] | None:
    return dict(value) if isinstance(value, Mapping) else None


def _comment_metadata_value(comment: Any, raw_data: Mapping[str, Any], *names: str) -> Any:
    for name in names:
        if hasattr(comment, name):
            value = getattr(comment, name)
            if value is not None:
                return value
    for name in names:
        if name in raw_data and raw_data.get(name) is not None:
            return raw_data.get(name)
    return None


def _instagram_comment_phase(
    comment: Any,
    raw_data: Mapping[str, Any],
    *,
    parent_external_id: str | None,
) -> str | None:
    raw_phase = _metadata_text(
        _comment_metadata_value(comment, raw_data, "phase", "api_phase", "comment_phase", "source_phase")
    )
    phase = raw_phase.lower() if raw_phase else None
    if phase in _INSTAGRAM_COMMENT_PHASES:
        return phase
    if parent_external_id or bool(getattr(comment, "is_reply", False)):
        return "child"
    is_ranked = _metadata_bool(
        _comment_metadata_value(comment, raw_data, "is_ranked", "isRanked"),
        default=False,
    )
    return "ranked" if is_ranked else None


def _apply_instagram_comment_api_metadata_columns(
    payload: dict[str, Any],
    comment: Any,
    *,
    raw_data: Mapping[str, Any],
    parent_external_id: str | None,
    conn: Any | None = None,
) -> None:
    if not _instagram_comment_metadata_writes_enabled():
        _log_instagram_comment_metadata_writes_disabled_once(payload)
        return

    phase = _instagram_comment_phase(comment, raw_data, parent_external_id=parent_external_id)
    is_ranked = _metadata_bool(
        _comment_metadata_value(comment, raw_data, "is_ranked", "isRanked"),
        default=phase == "ranked",
    )
    comment_index = _metadata_int(_comment_metadata_value(comment, raw_data, "comment_index", "commentIndex"))
    child_comment_count = _metadata_int(
        _comment_metadata_value(comment, raw_data, "child_comment_count", "childCommentCount")
    )
    cursor_payload = _metadata_mapping(_comment_metadata_value(comment, raw_data, "cursor_payload", "cursorPayload"))

    values: dict[str, Any] = {
        "is_covered": _metadata_bool(
            _comment_metadata_value(comment, raw_data, "is_covered", "isCovered"),
            default=False,
        ),
        "is_ranked": is_ranked,
        "comment_index": comment_index,
        "phase": phase,
        "did_report_as_spam": _metadata_bool(
            _comment_metadata_value(comment, raw_data, "did_report_as_spam", "didReportAsSpam"),
            default=False,
        ),
        "status": _metadata_text(_comment_metadata_value(comment, raw_data, "status")) or "Active",
        "is_edited": _metadata_bool(
            _comment_metadata_value(comment, raw_data, "is_edited", "isEdited"),
            default=False,
        ),
        "is_pinned": _metadata_bool(
            _comment_metadata_value(comment, raw_data, "is_pinned", "isPinned"),
            default=False,
        ),
        "meta_ai_comment_type": (
            _metadata_text(_comment_metadata_value(comment, raw_data, "meta_ai_comment_type", "metaAiCommentType"))
            or "NONE"
        ),
        "child_comment_count": max(0, child_comment_count or 0),
        "liked_by_media_coauthors": _metadata_bool(
            _comment_metadata_value(
                comment,
                raw_data,
                "liked_by_media_coauthors",
                "likedByMediaCoauthors",
            ),
            default=False,
        ),
        "cursor_min_id": _metadata_text(_comment_metadata_value(comment, raw_data, "cursor_min_id", "cursorMinId")),
        "cursor_param": _metadata_text(_comment_metadata_value(comment, raw_data, "cursor_param", "cursorParam")),
        "cursor_payload": cursor_payload or {},
        "comment_filter_param": _metadata_text(
            _comment_metadata_value(comment, raw_data, "comment_filter_param", "commentFilterParam")
        ),
    }
    for column in _INSTAGRAM_COMMENT_METADATA_COLUMNS:
        if _instagram_comment_metadata_column_exists(column, conn=conn):
            payload[column] = values[column]


def _apply_instagram_comment_queryable_columns(
    payload: dict[str, Any],
    comment: Any,
    *,
    parent_external_id: str | None = None,
    reply_depth: int | None = None,
    source_snapshot_type: str = "full_comments_scrape",
    conn: Any | None = None,
) -> None:
    raw_data = _instagram_comment_raw_payload(comment)
    if _column_exists_in_context("social", "instagram_comments", "author_full_name", conn=conn):
        payload["author_full_name"] = _instagram_comment_author_full_name(comment, raw_data)
    if _column_exists_in_context("social", "instagram_comments", "author_profile_pic_url_hd", conn=conn):
        payload["author_profile_pic_url_hd"] = _instagram_comment_author_profile_pic_hd(comment, raw_data)
    if _column_exists_in_context("social", "instagram_comments", "parent_comment_external_id", conn=conn):
        payload["parent_comment_external_id"] = str(parent_external_id or "").strip() or None
    if _column_exists_in_context("social", "instagram_comments", "reply_depth", conn=conn):
        payload["reply_depth"] = max(0, int(reply_depth or 0))
    if _column_exists_in_context("social", "instagram_comments", "source_snapshot_type", conn=conn):
        payload["source_snapshot_type"] = (
            str(getattr(comment, "source_snapshot_type", "") or source_snapshot_type).strip() or source_snapshot_type
        )
    _apply_instagram_comment_api_metadata_columns(
        payload,
        comment,
        raw_data=raw_data,
        parent_external_id=parent_external_id,
        conn=conn,
    )


def _merge_instagram_comment_cursor_payload(
    existing: Mapping[str, Any] | None,
    incoming: Mapping[str, Any] | None,
    *,
    existing_phase: Any = None,
    incoming_phase: Any = None,
) -> dict[str, Any]:
    merged: dict[str, Any] = {}
    if isinstance(existing, Mapping):
        merged.update(dict(existing))
    if isinstance(incoming, Mapping):
        merged.update(dict(incoming))
    phases = [str(value or "").strip() for value in [existing_phase, incoming_phase] if str(value or "").strip()]
    if len(set(phases)) > 1:
        observed = [
            str(item or "").strip() for item in list(merged.get("phase_observations") or []) if str(item or "").strip()
        ]
        for phase in phases:
            if phase not in observed:
                observed.append(phase)
        merged["phase_observations"] = observed
    return merged


def _merge_instagram_comment_payload_for_upsert(
    existing: dict[str, Any],
    incoming: dict[str, Any],
) -> dict[str, Any]:
    merged = {**existing, **incoming}
    existing_ranked = bool(existing.get("is_ranked"))
    incoming_ranked = bool(incoming.get("is_ranked"))
    if existing_ranked and not incoming_ranked:
        merged["is_ranked"] = True
        if existing.get("comment_index") is not None:
            merged["comment_index"] = existing.get("comment_index")
    elif incoming_ranked:
        merged["is_ranked"] = True
        if incoming.get("comment_index") is None and existing.get("comment_index") is not None:
            merged["comment_index"] = existing.get("comment_index")
    if "cursor_payload" in existing or "cursor_payload" in incoming:
        merged["cursor_payload"] = _merge_instagram_comment_cursor_payload(
            existing.get("cursor_payload") if isinstance(existing.get("cursor_payload"), Mapping) else None,
            incoming.get("cursor_payload") if isinstance(incoming.get("cursor_payload"), Mapping) else None,
            existing_phase=existing.get("phase"),
            incoming_phase=incoming.get("phase"),
        )
    return merged


def _dedupe_instagram_comment_payloads_for_upsert(payloads: list[dict[str, Any]]) -> list[dict[str, Any]]:
    deduped: list[dict[str, Any]] = []
    index_by_key: dict[tuple[str, str], int] = {}
    for payload in payloads:
        key = (
            str(payload.get("post_id") or "").strip(),
            str(payload.get("comment_id") or "").strip(),
        )
        if not all(key) or key not in index_by_key:
            index_by_key[key] = len(deduped)
            deduped.append(payload)
            continue
        existing_index = index_by_key[key]
        deduped[existing_index] = _merge_instagram_comment_payload_for_upsert(
            deduped[existing_index],
            payload,
        )
    return deduped


def _preserve_existing_ranked_instagram_comment_values(
    payloads: list[dict[str, Any]],
    baseline: Mapping[tuple[str, str], Mapping[str, Any]],
) -> None:
    for payload in payloads:
        key = (
            str(payload.get("post_id") or "").strip(),
            str(payload.get("comment_id") or "").strip(),
        )
        existing = baseline.get(key)
        if not existing or not bool(existing.get("is_ranked")) or bool(payload.get("is_ranked")):
            continue
        if "is_ranked" in payload:
            payload["is_ranked"] = True
        if "comment_index" in payload and existing.get("comment_index") is not None:
            payload["comment_index"] = existing.get("comment_index")


def _core_upsert_instagram_comment_tree_impl(
    context: SeasonContext,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    post_id: str,
    comment: Any,
    parent_comment_db_id: str | None = None,
    parent_comment_external_id: str | None = None,
    reply_depth: int = 0,
    observed_comment_ids: set[str] | None = None,
    persist_stats: dict[str, int] | None = None,
    source_scope: str = "network",
    enable_media_followups: bool = True,
    conn: Any | None = None,
) -> int:
    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1

    created_at = _parse_instagram_time(getattr(comment, "created_at", None))
    comment_external_id = str(getattr(comment, "comment_id", "") or "")
    if observed_comment_ids is not None and comment_external_id:
        observed_comment_ids.add(comment_external_id)
    if not comment_external_id.strip():
        if persist_stats is not None:
            persist_stats["comments_skipped_missing_id"] = (
                int(persist_stats.get("comments_skipped_missing_id") or 0) + 1
            )
        total = 0
        for reply in getattr(comment, "replies", []) or []:
            total += _core_upsert_instagram_comment_tree_impl(
                context,
                job_id=job_id,
                run_id=run_id,
                account=account,
                post_id=post_id,
                comment=reply,
                parent_comment_db_id=parent_comment_db_id,
                parent_comment_external_id=parent_comment_external_id,
                reply_depth=reply_depth + 1,
                observed_comment_ids=observed_comment_ids,
                persist_stats=persist_stats,
                source_scope=source_scope,
                enable_media_followups=enable_media_followups,
                conn=conn,
            )
        return total

    media_urls = [str(url).strip() for url in (getattr(comment, "media_urls", []) or []) if str(url).strip()]
    payload = {
        "comment_id": comment_external_id,
        "post_id": post_id,
        "parent_comment_id": parent_comment_db_id,
        "username": getattr(comment, "username", ""),
        "user_id": getattr(comment, "user_id", None),
        "text": getattr(comment, "text", ""),
        "likes": int(getattr(comment, "likes", 0) or 0),
        "is_reply": bool(getattr(comment, "is_reply", False)),
        "reply_count": int(getattr(comment, "reply_count", 0) or 0),
        "created_at": created_at,
        "scraped_at": _now_utc(),
        "raw_data": _instagram_comment_raw_data_for_write(comment),
        "season_id": context.season_id,
        "source_account": account,
    }
    if job_id:
        payload["job_id"] = job_id
    if _comment_lifecycle_supported_in_context("instagram_comments", conn=conn):
        payload["is_missing"] = False
        payload["missing_at"] = None
        payload["last_seen_at"] = _now_utc()
        if run_id is not None:
            payload["last_seen_run_id"] = run_id
    # Author detail columns (migration 0147)
    if _column_exists_in_context("social", "instagram_comments", "author_profile_pic_url", conn=conn):
        payload["author_profile_pic_url"] = str(getattr(comment, "owner_profile_pic_url", "") or "").strip() or None
    if _column_exists_in_context("social", "instagram_comments", "author_is_verified", conn=conn):
        payload["author_is_verified"] = getattr(comment, "owner_is_verified", None)
    if _column_exists_in_context("social", "instagram_comments", "media_urls", conn=conn):
        payload["media_urls"] = media_urls
    if _column_exists_in_context("social", "instagram_comments", "hosted_media_urls", conn=conn):
        payload["hosted_media_urls"] = [
            str(url).strip() for url in (getattr(comment, "hosted_media_urls", []) or []) if str(url).strip()
        ]
    if media_urls and _column_exists_in_context("social", "instagram_comments", "media_mirror_status", conn=conn):
        payload["media_mirror_status"] = "pending"
    if media_urls and _column_exists_in_context("social", "instagram_comments", "media_mirror_error", conn=conn):
        payload["media_mirror_error"] = None
    # Phase 2: Apify-source owner-metadata columns (migration
    # 20260501210512_instagram_comments_owner_metadata.sql).
    if _column_exists_in_context("social", "instagram_comments", "comment_url", conn=conn):
        payload["comment_url"] = str(getattr(comment, "comment_url", "") or "").strip() or None
    if _column_exists_in_context("social", "instagram_comments", "author_fbid_v2", conn=conn):
        payload["author_fbid_v2"] = str(getattr(comment, "owner_fbid_v2", "") or "").strip() or None
    if _column_exists_in_context("social", "instagram_comments", "author_is_mentionable", conn=conn):
        payload["author_is_mentionable"] = getattr(comment, "owner_is_mentionable", None)
    if _column_exists_in_context("social", "instagram_comments", "author_is_private", conn=conn):
        payload["author_is_private"] = getattr(comment, "owner_is_private", None)
    if _column_exists_in_context("social", "instagram_comments", "author_latest_reel_media", conn=conn):
        payload["author_latest_reel_media"] = getattr(comment, "owner_latest_reel_media", None)
    if _column_exists_in_context("social", "instagram_comments", "author_profile_pic_id", conn=conn):
        payload["author_profile_pic_id"] = str(getattr(comment, "owner_profile_pic_id", "") or "").strip() or None
    effective_reply_depth = _instagram_comment_effective_reply_depth(
        comment,
        parent_external_id=parent_comment_external_id,
        fallback=reply_depth,
    )
    _apply_instagram_comment_queryable_columns(
        payload,
        comment,
        parent_external_id=parent_comment_external_id,
        reply_depth=effective_reply_depth,
        conn=conn,
    )
    write_baseline = _load_instagram_comment_write_baseline([payload], conn=conn) if persist_stats is not None else {}
    if write_baseline:
        _preserve_existing_ranked_instagram_comment_values([payload], write_baseline)
    upsert_kwargs: dict[str, Any] = {
        "conflict_col": ["post_id", "comment_id"],
        "conn": conn,
    }
    if persist_stats is not None:
        upsert_kwargs["include_inserted_flag"] = True
    row = _pg_upsert("instagram_comments", payload, **upsert_kwargs)
    comment_db_id = (row or {}).get("id")
    if persist_stats is not None and row:
        inserted = 1 if bool(row.pop("__trr_inserted", False)) else 0
        _record_comment_write_counts(persist_stats, total=1, inserted=inserted)
    if row and media_urls and enable_media_followups:
        mirror_job_id: str | None = None
        try:
            with _SavepointScope(conn=conn, prefix="instagram_comment_media_mirror", index=1):
                mirror_job_id = _enqueue_platform_comment_media_mirror_job(
                    context,
                    platform="instagram",
                    run_id=run_id,
                    source_scope=source_scope,
                    account=account,
                    comment_row={**payload, **row},
                    parent_job_id=job_id,
                    conn=conn,
                )
            if mirror_job_id and persist_stats is not None:
                persist_stats["comment_media_mirror_jobs_enqueued"] = (
                    int(persist_stats.get("comment_media_mirror_jobs_enqueued") or 0) + 1
                )
        except Exception:  # noqa: BLE001
            if persist_stats is not None:
                persist_stats["comment_media_mirror_job_enqueue_errors"] = (
                    int(persist_stats.get("comment_media_mirror_job_enqueue_errors") or 0) + 1
                )

    total = 1 if row else 0
    for reply in getattr(comment, "replies", []) or []:
        total += _core_upsert_instagram_comment_tree_impl(
            context,
            job_id=job_id,
            run_id=run_id,
            account=account,
            post_id=post_id,
            comment=reply,
            parent_comment_db_id=comment_db_id,
            parent_comment_external_id=comment_external_id,
            reply_depth=reply_depth + 1,
            observed_comment_ids=observed_comment_ids,
            persist_stats=persist_stats,
            source_scope=source_scope,
            enable_media_followups=enable_media_followups,
            conn=conn,
        )
    return total


def _flatten_instagram_comment_tree(
    comment: Any,
    *,
    parent_external_id: str | None = None,
) -> list[tuple[Any, str | None]]:
    """Flatten a comment tree into a list of (comment, parent_external_id) tuples."""
    external_id = str(getattr(comment, "comment_id", "") or "").strip()
    result: list[tuple[Any, str | None]] = [(comment, parent_external_id)]
    for reply in getattr(comment, "replies", []) or []:
        result.extend(
            _flatten_instagram_comment_tree(
                reply,
                parent_external_id=external_id if external_id else parent_external_id,
            )
        )
    return result


_BATCH_UPSERT_COMMENT_SIZE = _resolve_positive_int_env(
    "SOCIAL_DB_UPSERT_BATCH_SIZE_COMMENTS",
    200,
    minimum=10,
)

# Cache column checks once per process to avoid repeated introspection queries.
_instagram_comment_has_profile_pic: bool | None = None
_instagram_comment_has_verified: bool | None = None
_instagram_comment_has_media: bool | None = None
_instagram_comment_has_hosted_media: bool | None = None
_instagram_comment_has_media_mirror_status: bool | None = None
_instagram_comment_has_media_mirror_error: bool | None = None
# Phase 2: Apify-source owner-metadata column flags
# (migration 20260501210512_instagram_comments_owner_metadata.sql).
_instagram_comment_has_comment_url: bool | None = None
_instagram_comment_has_author_fbid_v2: bool | None = None
_instagram_comment_has_author_is_mentionable: bool | None = None
_instagram_comment_has_author_is_private: bool | None = None
_instagram_comment_has_author_latest_reel_media: bool | None = None
_instagram_comment_has_author_profile_pic_id: bool | None = None


def _instagram_comment_effective_reply_depth(comment: Any, *, parent_external_id: str | None, fallback: int) -> int:
    try:
        parsed_depth = int(getattr(comment, "reply_depth", 0) or 0)
    except (TypeError, ValueError):
        parsed_depth = 0
    if parsed_depth > 0 or not parent_external_id:
        return max(0, parsed_depth)
    return max(0, int(fallback or 0))


def _core_batch_upsert_instagram_comments_impl(
    context: SeasonContext,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    post_id: str,
    comments: list[Any],
    observed_comment_ids: set[str] | None = None,
    persist_stats: dict[str, int] | None = None,
    source_scope: str = "network",
    enable_media_followups: bool = True,
    conn: Any | None = None,
) -> int:
    """Batch upsert Instagram comments for a single post.

    Flattens the comment tree, batch-upserts top-level comments first to get
    their DB IDs, then batch-upserts replies with parent references resolved.
    """
    global _instagram_comment_has_hosted_media  # noqa: PLW0603
    global _instagram_comment_has_media  # noqa: PLW0603
    global _instagram_comment_has_media_mirror_error  # noqa: PLW0603
    global _instagram_comment_has_media_mirror_status  # noqa: PLW0603
    global _instagram_comment_has_profile_pic  # noqa: PLW0603
    global _instagram_comment_has_verified  # noqa: PLW0603
    global _instagram_comment_has_comment_url  # noqa: PLW0603
    global _instagram_comment_has_author_fbid_v2  # noqa: PLW0603
    global _instagram_comment_has_author_is_mentionable  # noqa: PLW0603
    global _instagram_comment_has_author_is_private  # noqa: PLW0603
    global _instagram_comment_has_author_latest_reel_media  # noqa: PLW0603
    global _instagram_comment_has_author_profile_pic_id  # noqa: PLW0603

    if not comments:
        return 0

    # Resolve column existence once per process
    if _instagram_comment_has_profile_pic is None:
        _instagram_comment_has_profile_pic = _column_exists_in_context(
            "social", "instagram_comments", "author_profile_pic_url", conn=conn
        )
    if _instagram_comment_has_verified is None:
        _instagram_comment_has_verified = _column_exists_in_context(
            "social", "instagram_comments", "author_is_verified", conn=conn
        )
    if _instagram_comment_has_media is None:
        _instagram_comment_has_media = _column_exists_in_context(
            "social", "instagram_comments", "media_urls", conn=conn
        )
    if _instagram_comment_has_hosted_media is None:
        _instagram_comment_has_hosted_media = _column_exists_in_context(
            "social", "instagram_comments", "hosted_media_urls", conn=conn
        )
    if _instagram_comment_has_media_mirror_status is None:
        _instagram_comment_has_media_mirror_status = _column_exists_in_context(
            "social", "instagram_comments", "media_mirror_status", conn=conn
        )
    if _instagram_comment_has_media_mirror_error is None:
        _instagram_comment_has_media_mirror_error = _column_exists_in_context(
            "social", "instagram_comments", "media_mirror_error", conn=conn
        )
    if _instagram_comment_has_comment_url is None:
        _instagram_comment_has_comment_url = _column_exists_in_context(
            "social", "instagram_comments", "comment_url", conn=conn
        )
    if _instagram_comment_has_author_fbid_v2 is None:
        _instagram_comment_has_author_fbid_v2 = _column_exists_in_context(
            "social", "instagram_comments", "author_fbid_v2", conn=conn
        )
    if _instagram_comment_has_author_is_mentionable is None:
        _instagram_comment_has_author_is_mentionable = _column_exists_in_context(
            "social", "instagram_comments", "author_is_mentionable", conn=conn
        )
    if _instagram_comment_has_author_is_private is None:
        _instagram_comment_has_author_is_private = _column_exists_in_context(
            "social", "instagram_comments", "author_is_private", conn=conn
        )
    if _instagram_comment_has_author_latest_reel_media is None:
        _instagram_comment_has_author_latest_reel_media = _column_exists_in_context(
            "social", "instagram_comments", "author_latest_reel_media", conn=conn
        )
    if _instagram_comment_has_author_profile_pic_id is None:
        _instagram_comment_has_author_profile_pic_id = _column_exists_in_context(
            "social", "instagram_comments", "author_profile_pic_id", conn=conn
        )
    has_lifecycle = _comment_lifecycle_supported_in_context("instagram_comments", conn=conn)

    # Flatten all comment trees
    flat: list[tuple[Any, str | None]] = []
    for comment in comments:
        flat.extend(_flatten_instagram_comment_tree(comment))

    # Build payloads and track stats
    top_level_payloads: list[dict[str, Any]] = []
    reply_payloads: list[dict[str, Any]] = []  # parent_external_id stored temporarily

    for comment_obj, parent_ext_id in flat:
        if persist_stats is not None:
            persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1

        external_id = str(getattr(comment_obj, "comment_id", "") or "").strip()
        if observed_comment_ids is not None and external_id:
            observed_comment_ids.add(external_id)
        if not external_id:
            if persist_stats is not None:
                persist_stats["comments_skipped_missing_id"] = (
                    int(persist_stats.get("comments_skipped_missing_id") or 0) + 1
                )
            continue

        created_at = _parse_instagram_time(getattr(comment_obj, "created_at", None))
        now = _now_utc()
        payload: dict[str, Any] = {
            "comment_id": external_id,
            "post_id": post_id,
            "parent_comment_id": None,  # resolved below for replies
            "username": getattr(comment_obj, "username", ""),
            "user_id": getattr(comment_obj, "user_id", None),
            "text": getattr(comment_obj, "text", ""),
            "likes": int(getattr(comment_obj, "likes", 0) or 0),
            "is_reply": bool(getattr(comment_obj, "is_reply", False)),
            "reply_count": int(getattr(comment_obj, "reply_count", 0) or 0),
            "created_at": created_at,
            "scraped_at": now,
            "raw_data": _instagram_comment_raw_data_for_write(comment_obj),
            "season_id": context.season_id,
            "source_account": account,
        }
        if job_id:
            payload["job_id"] = job_id
        if has_lifecycle:
            payload["is_missing"] = False
            payload["missing_at"] = None
            payload["last_seen_at"] = now
            if run_id is not None:
                payload["last_seen_run_id"] = run_id
        if _instagram_comment_has_profile_pic:
            payload["author_profile_pic_url"] = (
                str(getattr(comment_obj, "owner_profile_pic_url", "") or "").strip() or None
            )
        if _instagram_comment_has_verified:
            payload["author_is_verified"] = getattr(comment_obj, "owner_is_verified", None)
        media_urls = [str(url).strip() for url in (getattr(comment_obj, "media_urls", []) or []) if str(url).strip()]
        if _instagram_comment_has_media:
            payload["media_urls"] = media_urls
        if _instagram_comment_has_hosted_media:
            payload["hosted_media_urls"] = [
                str(url).strip() for url in (getattr(comment_obj, "hosted_media_urls", []) or []) if str(url).strip()
            ]
        if _instagram_comment_has_media_mirror_status:
            payload["media_mirror_status"] = "pending" if media_urls else None
        if _instagram_comment_has_media_mirror_error:
            payload["media_mirror_error"] = None
        # Phase 2: Apify-source owner-metadata column writes.
        if _instagram_comment_has_comment_url:
            payload["comment_url"] = str(getattr(comment_obj, "comment_url", "") or "").strip() or None
        if _instagram_comment_has_author_fbid_v2:
            payload["author_fbid_v2"] = str(getattr(comment_obj, "owner_fbid_v2", "") or "").strip() or None
        if _instagram_comment_has_author_is_mentionable:
            payload["author_is_mentionable"] = getattr(comment_obj, "owner_is_mentionable", None)
        if _instagram_comment_has_author_is_private:
            payload["author_is_private"] = getattr(comment_obj, "owner_is_private", None)
        if _instagram_comment_has_author_latest_reel_media:
            payload["author_latest_reel_media"] = getattr(comment_obj, "owner_latest_reel_media", None)
        if _instagram_comment_has_author_profile_pic_id:
            payload["author_profile_pic_id"] = (
                str(getattr(comment_obj, "owner_profile_pic_id", "") or "").strip() or None
            )
        effective_reply_depth = _instagram_comment_effective_reply_depth(
            comment_obj,
            parent_external_id=parent_ext_id,
            fallback=1 if parent_ext_id else 0,
        )
        _apply_instagram_comment_queryable_columns(
            payload,
            comment_obj,
            parent_external_id=parent_ext_id,
            reply_depth=effective_reply_depth,
            conn=conn,
        )

        if parent_ext_id is None:
            top_level_payloads.append(payload)
        else:
            payload["_parent_external_id"] = parent_ext_id
            reply_payloads.append(payload)

    total_upserted = 0
    batch_size = _BATCH_UPSERT_COMMENT_SIZE

    # Phase 1: batch-upsert top-level comments
    ext_id_to_db_id: dict[str, str] = {}
    top_level_payloads = _dedupe_instagram_comment_payloads_for_upsert(top_level_payloads)
    reply_payloads = _dedupe_instagram_comment_payloads_for_upsert(reply_payloads)
    for i in range(0, len(top_level_payloads), batch_size):
        batch = top_level_payloads[i : i + batch_size]
        batch_by_comment_id = {str(item.get("comment_id") or ""): item for item in batch}
        load_baseline = _load_instagram_comment_write_baseline
        count_new_or_changed = _count_new_or_changed_instagram_comment_payloads
        write_baseline = load_baseline(batch, conn=conn) if persist_stats is not None and batch else {}
        if write_baseline:
            _preserve_existing_ranked_instagram_comment_values(batch, write_baseline)
        batch_changed = count_new_or_changed(batch, write_baseline) if persist_stats is not None else None
        rows = _pg_upsert_many(
            "instagram_comments",
            batch,
            conflict_col=["post_id", "comment_id"],
            conn=conn,
            include_inserted_flag=True,
            coalesce_preserve_cols=_INSTAGRAM_COMMENT_COALESCE_PRESERVE_COLS,
        )
        batch_total, batch_inserted = _upsert_write_counts(rows)
        for row_index, row in enumerate(rows, start=1):
            db_id = str(row.get("id") or "")
            ext_id = str(row.get("comment_id") or "")
            if db_id and ext_id:
                ext_id_to_db_id[ext_id] = db_id
                payload = batch_by_comment_id.get(ext_id) or {}
                media_urls = list(payload.get("media_urls") or [])
                if media_urls and enable_media_followups:
                    mirror_job_id: str | None = None
                    try:
                        with _SavepointScope(
                            conn=conn,
                            prefix="instagram_comment_media_mirror",
                            index=total_upserted + row_index,
                        ):
                            mirror_job_id = _enqueue_platform_comment_media_mirror_job(
                                context,
                                platform="instagram",
                                run_id=run_id,
                                source_scope=source_scope,
                                account=account,
                                comment_row={**payload, **row},
                                parent_job_id=job_id,
                                conn=conn,
                            )
                        if mirror_job_id and persist_stats is not None:
                            persist_stats["comment_media_mirror_jobs_enqueued"] = (
                                int(persist_stats.get("comment_media_mirror_jobs_enqueued") or 0) + 1
                            )
                    except Exception:  # noqa: BLE001
                        if persist_stats is not None:
                            persist_stats["comment_media_mirror_job_enqueue_errors"] = (
                                int(persist_stats.get("comment_media_mirror_job_enqueue_errors") or 0) + 1
                            )
        total_upserted += batch_total
        _record_comment_write_counts(persist_stats, total=batch_total, inserted=batch_inserted, changed=batch_changed)

    # Phase 2: resolve parent IDs and batch-upsert replies
    for payload in reply_payloads:
        parent_ext = payload.pop("_parent_external_id", None)
        if parent_ext and parent_ext in ext_id_to_db_id:
            payload["parent_comment_id"] = ext_id_to_db_id[parent_ext]

    for i in range(0, len(reply_payloads), batch_size):
        batch = reply_payloads[i : i + batch_size]
        batch_by_comment_id = {str(item.get("comment_id") or ""): item for item in batch}
        load_baseline = _load_instagram_comment_write_baseline
        count_new_or_changed = _count_new_or_changed_instagram_comment_payloads
        write_baseline = load_baseline(batch, conn=conn) if persist_stats is not None and batch else {}
        if write_baseline:
            _preserve_existing_ranked_instagram_comment_values(batch, write_baseline)
        batch_changed = count_new_or_changed(batch, write_baseline) if persist_stats is not None else None
        rows = _pg_upsert_many(
            "instagram_comments",
            batch,
            conflict_col=["post_id", "comment_id"],
            conn=conn,
            include_inserted_flag=True,
            coalesce_preserve_cols=_INSTAGRAM_COMMENT_COALESCE_PRESERVE_COLS,
        )
        batch_total, batch_inserted = _upsert_write_counts(rows)
        for row_index, row in enumerate(rows, start=1):
            db_id = str(row.get("id") or "")
            ext_id = str(row.get("comment_id") or "")
            if db_id and ext_id:
                ext_id_to_db_id[ext_id] = db_id
                payload = batch_by_comment_id.get(ext_id) or {}
                media_urls = list(payload.get("media_urls") or [])
                if media_urls and enable_media_followups:
                    mirror_job_id: str | None = None
                    try:
                        with _SavepointScope(
                            conn=conn,
                            prefix="instagram_comment_media_mirror",
                            index=total_upserted + row_index,
                        ):
                            mirror_job_id = _enqueue_platform_comment_media_mirror_job(
                                context,
                                platform="instagram",
                                run_id=run_id,
                                source_scope=source_scope,
                                account=account,
                                comment_row={**payload, **row},
                                parent_job_id=job_id,
                                conn=conn,
                            )
                        if mirror_job_id and persist_stats is not None:
                            persist_stats["comment_media_mirror_jobs_enqueued"] = (
                                int(persist_stats.get("comment_media_mirror_jobs_enqueued") or 0) + 1
                            )
                    except Exception:  # noqa: BLE001
                        if persist_stats is not None:
                            persist_stats["comment_media_mirror_job_enqueue_errors"] = (
                                int(persist_stats.get("comment_media_mirror_job_enqueue_errors") or 0) + 1
                            )
        total_upserted += batch_total
        _record_comment_write_counts(persist_stats, total=batch_total, inserted=batch_inserted, changed=batch_changed)

    return total_upserted


# Compatibility wrappers owned by trr_backend.socials.instagram.persistence;
# retained for legacy imports and repository-facade monkeypatch tests.
def _upsert_instagram_comment_tree(*args: Any, **kwargs: Any) -> Any:
    return _core_upsert_instagram_comment_tree_impl(*args, **kwargs)


def _batch_upsert_instagram_comments(*args: Any, **kwargs: Any) -> Any:
    return _core_batch_upsert_instagram_comments_impl(*args, **kwargs)


def _load_instagram_comment_write_baseline(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.persistence import _load_instagram_comment_write_baseline as _impl

    return _impl(*args, **kwargs)


def _count_new_or_changed_instagram_comment_payloads(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.persistence import _count_new_or_changed_instagram_comment_payloads as _impl

    return _impl(*args, **kwargs)


def _extract_instagram_post_detail_node(payload: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(payload, dict):
        return None
    items = payload.get("items")
    if isinstance(items, list):
        for item in items:
            if isinstance(item, dict):
                return item
    data = payload.get("data")
    if isinstance(data, dict):
        media = data.get("xdt_shortcode_media")
        if isinstance(media, dict):
            return media
    return None


def _refresh_instagram_post_metrics_only(
    *,
    post_db_id: str,
    likes: int,
    comments_count: int,
    views: int | None,
    views_source: str | None = None,
    views_raw_candidates: list[dict[str, Any]] | None = None,
    conn: Any,
) -> None:
    assignments = [
        "likes = greatest(0, %s)",
        "comments_count = greatest(0, %s)",
        "scraped_at = now()",
    ]
    params: list[Any] = [max(0, int(likes)), max(0, int(comments_count))]
    if views is not None:
        assignments.append("views = greatest(coalesce(views, 0), %s)")
        params.append(max(0, int(views)))
    view_metrics_payload: dict[str, Any] | None = None
    if views is not None or views_source or (views_raw_candidates and len(views_raw_candidates) > 0):
        view_metrics_payload = {
            "observed_at": _now_utc().isoformat(),
        }
        if views is not None:
            view_metrics_payload["observed_count"] = max(0, int(views))
        if views_source:
            view_metrics_payload["source"] = str(views_source).strip()
        if views_raw_candidates:
            compact_candidates: list[dict[str, Any]] = []
            for item in (views_raw_candidates or [])[:10]:
                if not isinstance(item, dict):
                    continue
                compact_candidates.append(
                    {
                        "source": str(item.get("source") or "").strip() or None,
                        "raw": item.get("raw"),
                        "parsed": (
                            _normalize_non_negative_int(item.get("parsed")) if item.get("parsed") is not None else None
                        ),
                    }
                )
            if compact_candidates:
                view_metrics_payload["raw_candidates"] = compact_candidates
    if view_metrics_payload and len(view_metrics_payload) > 1:
        assignments.append("raw_data = jsonb_set(coalesce(raw_data, '{}'::jsonb), '{view_metrics}', %s::jsonb, true)")
        params.append(json.dumps(view_metrics_payload))

    params.append(post_db_id)
    with pg.db_cursor(conn=conn) as cur:
        pg.fetch_one_with_cursor(
            cur,
            f"""
            update social.instagram_posts
            set {", ".join(assignments)}
            where id = %s::uuid
            returning id::text
            """,
            params,
        )


def _ingest_instagram(
    context: SeasonContext,
    *,
    run_id: str | None,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    stage: str = "posts",
) -> tuple[int, int, dict[str, Any]]:
    from trr_backend.socials.instagram import InstagramScraper, ScrapeConfig

    try:
        post_delay_seconds = float((os.getenv("SOCIAL_INSTAGRAM_DELAY_SEC") or "").strip() or "0.15")
    except ValueError:
        post_delay_seconds = 0.15
    try:
        comment_delay_seconds = float((os.getenv("SOCIAL_INSTAGRAM_COMMENT_DELAY_SEC") or "").strip() or "0.25")
    except ValueError:
        comment_delay_seconds = 0.25

    cookies = _load_instagram_cookies()
    instagram_authenticated = bool(cookies.get("sessionid"))
    if not instagram_authenticated:
        logger.warning("Instagram ingest running without sessionid cookie; results may be limited to ~12 recent posts")
    cache_scope = f"instagram:ingest:{account.strip().lower()}"
    scraper = _get_cached_scraper(
        cookies,
        cache_scope=cache_scope,
        expected_type=InstagramScraper,
    )
    if scraper is None:
        if getattr(InstagramScraper, "__module__", "") != "trr_backend.socials.instagram.scraper":
            scraper = InstagramScraper(
                cookies=cookies,
                browser_account_id=_sanitize_instagram_browser_account_id(account),
            )
        else:
            scraper = _build_instagram_scraper_with_auth_fallback(
                browser_account_id=account,
                caller_context=f"ingest:{account.strip().lower()}",
            )
        _cache_scraper(getattr(scraper, "cookies", cookies) or cookies, scraper, cache_scope=cache_scope)

    retrieval_meta: dict[str, Any] = {"instagram_authenticated": instagram_authenticated}
    matched_post_count = 0
    scraped_post_count = 0
    scraped_comment_count = 0
    comment_errors = 0
    comment_fail_reasons: set[str] = set()
    comment_fail_reason_counts: Counter[str] = Counter()
    comment_refresh_reasons: Counter[str] = Counter()
    missing_marked = 0
    incomplete_comment_fetches = 0
    comments_mark_missing_skipped = 0
    rolled_back_posts = 0
    rolled_back_comments = 0
    mirror_jobs_enqueued = 0
    mirror_job_enqueue_errors = 0
    comment_media_mirror_jobs_enqueued = 0
    comment_stats = _new_comment_persist_stats()
    skipped_keyword = 0
    skipped_synced = 0
    total_scraped = 0
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": f"{stage}_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
    }

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=stage,
            platform="instagram",
            account=account,
            scraped_posts=scraped_post_count,
            scraped_comments=scraped_comment_count,
            posts_upserted=matched_post_count,
            comments_upserted=int(comment_stats.get("comments_upserted") or 0),
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)

    if stage == "comments":
        # Comment-only stage: read existing posts from DB instead of re-scraping
        target_source_ids = _target_source_ids_for_platform(opts, "instagram")
        existing_posts = _load_existing_posts(
            "instagram",
            context,
            account,
            opts.date_start,
            opts.date_end,
            source_ids=target_source_ids,
        )
        if _show_is_rhoslc(context):
            existing_posts = [row for row in existing_posts if _instagram_row_has_required_rhoslc_hashtag(row)]
        logger.info(
            "[instagram] Comments stage: %d existing posts from DB for account=%s",
            len(existing_posts),
            account,
        )
        retrieval_meta["source"] = "db"
        snapshots = _load_comment_lifecycle_snapshots(
            [str(r["id"]) for r in existing_posts if r.get("id")],
            platform="instagram",
        )
        skipped_synced = 0
        for row in existing_posts:
            shortcode = str(row.get("shortcode") or "")
            post_db_id = str(row.get("id") or "")
            if not shortcode:
                continue
            expected = int(row.get("comments_count") or 0)
            decision = _decide_comment_refresh(
                sync_strategy=opts.sync_strategy,
                expected_count=expected,
                snapshot=snapshots.get(post_db_id),
                post_published_at=_coerce_dt(row.get("posted_at")),
                refresh_policy=opts.comment_refresh_policy,
            )
            comment_refresh_reasons[decision.reason] += 1
            if not decision.should_refresh:
                skipped_synced += 1
                continue
            scraped_post_count += 1
            activity["phase"] = "comments_fetch"
            activity["posts_checked"] = scraped_post_count
            activity["matched_posts"] = matched_post_count
            if scraped_post_count % 10 == 0:
                _touch_job_heartbeat(job_id)
            _flush_progress()
            comments: list[Any] = []
            fail_reason = ""
            observed_comment_ids: set[str] = set()
            local_comment_stats = _new_comment_persist_stats()
            fetch_failed = False
            try:
                comments = scraper.fetch_comments(
                    shortcode,
                    max_comments=opts.max_comments_per_post,
                    fetch_replies=opts.fetch_replies,
                    delay=comment_delay_seconds,
                )
                fail_reason = str(getattr(scraper, "last_comment_fetch_reason", "") or "")
                if fail_reason:
                    comment_fail_reasons.add(fail_reason)
                    comment_fail_reason_counts[fail_reason] += 1
                    if not comments:
                        comment_errors += 1
            except Exception:
                fetch_failed = True
                comment_errors += 1
                logger.exception(
                    "[instagram] Failed to fetch comments for post %s (shortcode=%s)",
                    post_db_id,
                    shortcode,
                )

            if not fetch_failed:
                try:
                    with pg.db_connection() as conn:
                        _batch_upsert_instagram_comments(
                            context,
                            job_id=job_id,
                            run_id=run_id,
                            account=account,
                            post_id=post_db_id,
                            comments=comments,
                            observed_comment_ids=observed_comment_ids,
                            persist_stats=local_comment_stats,
                            source_scope=opts.source_scope,
                            enable_media_followups=not not opts.comments_enable_media_followups,
                            conn=conn,
                        )

                        is_complete = _is_comment_fetch_complete(
                            fetch_failed=False,
                            fail_reason=fail_reason,
                            auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                            fetched_count=len(comments),
                            max_comments_per_post=opts.max_comments_per_post,
                        )
                        if is_complete:
                            missing_marked += _mark_missing_comments_for_anchor(
                                platform="instagram",
                                anchor_id=post_db_id,
                                observed_comment_ids=observed_comment_ids,
                                conn=conn,
                            )
                            _run_best_effort_db_step_in_savepoint(
                                conn=conn,
                                savepoint_name="instagram_comment_reconcile",
                                operation=lambda post_db_id=post_db_id, conn=conn: _reconcile_post_comment_count(
                                    platform="instagram",
                                    post_db_id=post_db_id,
                                    conn=conn,
                                ),
                                log_message=(
                                    "[instagram] Failed to reconcile comment count for post %s (shortcode=%s)"
                                ),
                                log_args=(post_db_id, shortcode),
                            )
                        else:
                            incomplete_comment_fetches += 1
                            comments_mark_missing_skipped += 1
                except Exception:
                    fetch_failed = True
                    comment_errors += 1
                    rolled_back_comments += int(local_comment_stats.get("comments_upserted") or 0)
                    logger.exception(
                        "[instagram] Failed to persist comments for post %s (shortcode=%s)",
                        post_db_id,
                        shortcode,
                    )

            if fetch_failed:
                incomplete_comment_fetches += 1
                comments_mark_missing_skipped += 1
                continue

            matched_post_count += 1
            activity["matched_posts"] = matched_post_count
            _merge_comment_persist_stats(comment_stats, local_comment_stats)
            scraped_comment_count = int(comment_stats.get("comments_fetched") or 0)
            _flush_progress()
        if skipped_synced:
            logger.info("[instagram] Skipped %d posts whose comments are already synced", skipped_synced)
    elif opts.ingest_mode == "details_refresh":
        target_source_ids = _target_source_ids_for_platform(opts, "instagram")
        existing_posts = _load_existing_posts(
            "instagram",
            context,
            account,
            opts.date_start,
            opts.date_end,
            source_ids=target_source_ids,
        )
        if _show_is_rhoslc(context):
            existing_posts = [row for row in existing_posts if _instagram_row_has_required_rhoslc_hashtag(row)]
        retrieval_meta["source"] = "db_metrics_refresh"
        activity["phase"] = "details_refresh_metrics_index"
        _touch_job_heartbeat(job_id)
        _flush_progress()
        detail_config = ScrapeConfig(
            username=account,
            hashtags=hashtags,
            date_start=opts.date_start,
            date_end=opts.date_end,
            delay_seconds=post_delay_seconds,
            max_pages=None,
            show_id=cast(Any, context.show_id),
            season_number=context.season_number,
        )
        metrics_pages_scanned = 0
        metrics_posts_checked = 0

        def _on_metrics_progress(payload: dict[str, Any]) -> None:
            nonlocal metrics_pages_scanned, metrics_posts_checked, scraped_post_count
            metrics_pages_scanned = max(
                metrics_pages_scanned, _normalize_non_negative_int(payload.get("pages_scanned"))
            )
            metrics_posts_checked = max(
                metrics_posts_checked, _normalize_non_negative_int(payload.get("posts_checked"))
            )
            activity["phase"] = str(payload.get("phase") or "details_refresh_metrics_index")
            activity["pages_scanned"] = metrics_pages_scanned
            activity["posts_checked"] = max(scraped_post_count, metrics_posts_checked)
            activity["matched_posts"] = matched_post_count
            _touch_job_heartbeat(job_id)
            _flush_progress()

        try:
            metrics_index = scraper.scrape_metrics_index(detail_config, progress_cb=_on_metrics_progress)
        except Exception:  # noqa: BLE001
            metrics_index = {}
            logger.exception(
                (
                    "[instagram] Failed to build gallery metrics index for account=%s; "
                    "falling back to per-post detail fetch"
                ),
                account,
            )
        retrieval_meta["details_refresh_metrics_index_size"] = len(metrics_index)
        retrieval_meta["details_refresh_metrics_pages_scanned"] = metrics_pages_scanned
        retrieval_meta["details_refresh_metrics_posts_checked"] = metrics_posts_checked
        details_refreshed_posts = 0
        details_refresh_errors = 0
        details_refresh_error_reasons: Counter[str] = Counter()
        details_refresh_views_updated = 0
        details_refresh_views_preserved_missing = 0
        details_refresh_views_sources: Counter[str] = Counter()
        details_refresh_detail_fetch_attempts = 0
        details_refresh_detail_fetch_skipped_limit = 0
        details_refresh_skipped_required_fields = 0
        raw_detail_fetch_cap = (os.getenv("SOCIAL_INSTAGRAM_DETAILS_REFRESH_MAX_DETAIL_FETCHES") or "").strip()
        try:
            details_refresh_detail_fetch_cap = max(0, int(raw_detail_fetch_cap or "150"))
        except ValueError:
            details_refresh_detail_fetch_cap = 150
        with pg.db_connection() as details_conn:
            for row in existing_posts:
                existing_row = dict(row)
                shortcode = str(row.get("shortcode") or "").strip()
                post_db_id = str(row.get("id") or "").strip()
                if not shortcode or not post_db_id:
                    continue
                scraped_post_count += 1
                activity["phase"] = "details_refresh_fetch"
                activity["posts_checked"] = scraped_post_count
                if scraped_post_count % 25 == 0:
                    _touch_job_heartbeat(job_id)
                _flush_progress()
                try:
                    existing_likes = _normalize_non_negative_int(row.get("likes"))
                    existing_comments = _normalize_non_negative_int(row.get("comments_count"))
                    existing_views = _normalize_non_negative_int(row.get("views"))
                    gallery_metrics = metrics_index.get(shortcode) if isinstance(metrics_index, dict) else None
                    gallery_likes = (
                        _normalize_non_negative_int((gallery_metrics or {}).get("likes"))
                        if isinstance((gallery_metrics or {}).get("likes"), (int, float))
                        else None
                    )
                    gallery_comments = (
                        _normalize_non_negative_int((gallery_metrics or {}).get("comments"))
                        if isinstance((gallery_metrics or {}).get("comments"), (int, float))
                        else None
                    )
                    gallery_views = (
                        _normalize_non_negative_int((gallery_metrics or {}).get("views_observed"))
                        if (gallery_metrics or {}).get("views_observed") is not None
                        else None
                    )
                    gallery_views_source = str((gallery_metrics or {}).get("views_source") or "").strip() or None
                    gallery_views_raw_candidates = (
                        (gallery_metrics or {}).get("views_raw_candidates")
                        if isinstance((gallery_metrics or {}).get("views_raw_candidates"), list)
                        else []
                    )
                    needs_media_repair = _instagram_post_needs_media_mirror(existing_row, conn=details_conn)
                    needs_detail_fetch = (
                        gallery_likes is None or gallery_comments is None or gallery_views is None or needs_media_repair
                    )
                    parsed_post = None
                    detail_fetch_skipped = False
                    if needs_detail_fetch:
                        if details_refresh_detail_fetch_cap == 0:
                            details_refresh_detail_fetch_skipped_limit += 1
                            detail_fetch_skipped = True
                        elif details_refresh_detail_fetch_attempts >= details_refresh_detail_fetch_cap:
                            details_refresh_detail_fetch_skipped_limit += 1
                            detail_fetch_skipped = True
                        else:
                            details_refresh_detail_fetch_attempts += 1
                            post_payload = scraper.fetch_post_info(shortcode, delay=post_delay_seconds)
                            node = _extract_instagram_post_detail_node(post_payload)
                            parsed_post = scraper._parse_post_node(node, detail_config) if node else None  # noqa: SLF001
                    if parsed_post is not None:
                        now_utc = _now_utc()
                        try:
                            _enrich_instagram_post_from_permalink(post=parsed_post, scraper=scraper, now_utc=now_utc)
                        except Exception:  # noqa: BLE001
                            logger.exception(
                                "[instagram] Metadata enrichment failed during details refresh for shortcode=%s",
                                shortcode,
                            )
                            cast(Any, parsed_post).metadata_source = None
                            _mark_instagram_metadata_attempt(
                                post=parsed_post,
                                now_utc=now_utc,
                                success=False,
                                error_code="metadata_enrichment_exception",
                            )
                            details_refresh_error_reasons["metadata_enrichment_exception"] += 1
                    unresolved_required_detail_fields = detail_fetch_skipped and (
                        gallery_likes is None or gallery_comments is None or gallery_views is None
                    )
                    if not parsed_post and gallery_views is None and not needs_media_repair:
                        if detail_fetch_skipped:
                            details_refresh_skipped_required_fields += 1
                            details_refresh_error_reasons["detail_fetch_skipped_limit_missing_required_fields"] += 1
                        else:
                            details_refresh_errors += 1
                            details_refresh_error_reasons["detail_metrics_unavailable"] += 1
                        continue
                    likes_candidate = max(
                        existing_likes,
                        gallery_likes if gallery_likes is not None else existing_likes,
                        _normalize_non_negative_int(getattr(parsed_post, "likes", 0)) if parsed_post is not None else 0,
                    )
                    comments_candidate = max(
                        existing_comments,
                        gallery_comments if gallery_comments is not None else existing_comments,
                        _normalize_non_negative_int(getattr(parsed_post, "comments", 0))
                        if parsed_post is not None
                        else 0,
                    )
                    detail_views_observed = (
                        _normalize_non_negative_int(getattr(parsed_post, "video_views_observed", 0))
                        if parsed_post is not None and getattr(parsed_post, "video_views_observed", None) is not None
                        else None
                    )
                    views_candidate = gallery_views if gallery_views is not None else detail_views_observed
                    views_source = (
                        gallery_views_source
                        if gallery_views is not None
                        else (
                            str(getattr(parsed_post, "video_views_source", "") or "").strip()
                            if parsed_post is not None
                            else None
                        )
                    )
                    views_raw_candidates = (
                        gallery_views_raw_candidates
                        if gallery_views is not None and gallery_views_raw_candidates
                        else (
                            list(getattr(parsed_post, "video_views_raw_candidates", []) or [])
                            if parsed_post is not None
                            else []
                        )
                    )
                    resolved_views = max(existing_views, views_candidate) if views_candidate is not None else None
                    _refresh_instagram_post_metrics_only(
                        post_db_id=post_db_id,
                        likes=likes_candidate,
                        comments_count=comments_candidate,
                        views=resolved_views,
                        views_source=views_source,
                        views_raw_candidates=views_raw_candidates,
                        conn=details_conn,
                    )
                    if parsed_post is not None:
                        parsed_post.likes = likes_candidate
                        parsed_post.comments = comments_candidate
                        parsed_post.video_views_observed = resolved_views
                        parsed_post.video_views_source = views_source
                        parsed_post.video_views_raw_candidates = views_raw_candidates
                        source_thumbnail_url, source_media_urls = _instagram_post_source_urls(
                            {
                                "thumbnail_url": getattr(parsed_post, "thumbnail_url", None),
                                "media_urls": getattr(parsed_post, "media_urls", []),
                            }
                        )
                        if source_thumbnail_url or source_media_urls or needs_media_repair:
                            cast(Any, parsed_post).media_mirror_status = "pending"
                            cast(Any, parsed_post).media_mirror_error = None
                        upserted = _upsert_instagram_post(
                            context,
                            job_id=job_id,
                            account=account,
                            post=parsed_post,
                            conn=details_conn,
                        )
                        if upserted and not opts.details_refresh_skip_media_followups:
                            try:
                                mirror_job_id = _enqueue_instagram_media_mirror_job(
                                    context,
                                    run_id=run_id,
                                    source_scope=opts.source_scope,
                                    account=account,
                                    post_row=upserted,
                                    week_index=None,
                                    parent_job_id=job_id,
                                    conn=details_conn,
                                )
                                if mirror_job_id:
                                    mirror_jobs_enqueued += 1
                            except Exception:  # noqa: BLE001
                                mirror_job_enqueue_errors += 1
                                logger.exception(
                                    (
                                        "[instagram] Failed to enqueue media mirror job during details "
                                        "refresh for post=%s shortcode=%s"
                                    ),
                                    str((upserted or {}).get("id") or ""),
                                    shortcode,
                                )
                            try:
                                comment_media_mirror_jobs_enqueued += _enqueue_comment_media_repairs_for_post(
                                    context,
                                    platform="instagram",
                                    run_id=run_id,
                                    source_scope=opts.source_scope,
                                    account=account,
                                    post_row=upserted,
                                    parent_job_id=job_id,
                                    conn=details_conn,
                                )
                            except Exception:  # noqa: BLE001
                                logger.exception(
                                    "[instagram] Failed to enqueue comment-media repairs during details refresh for %s",
                                    shortcode,
                                )
                    else:
                        if needs_media_repair and not opts.details_refresh_skip_media_followups:
                            try:
                                mirror_job_id = _enqueue_instagram_media_mirror_job(
                                    context,
                                    run_id=run_id,
                                    source_scope=opts.source_scope,
                                    account=account,
                                    post_row=existing_row,
                                    week_index=None,
                                    parent_job_id=job_id,
                                    conn=details_conn,
                                )
                                if mirror_job_id:
                                    mirror_jobs_enqueued += 1
                            except Exception:  # noqa: BLE001
                                mirror_job_enqueue_errors += 1
                                logger.exception(
                                    (
                                        "[instagram] Failed to enqueue fallback media mirror job during "
                                        "details refresh for post=%s shortcode=%s"
                                    ),
                                    post_db_id,
                                    shortcode,
                                )
                        if not opts.details_refresh_skip_media_followups:
                            try:
                                comment_media_mirror_jobs_enqueued += _enqueue_comment_media_repairs_for_post(
                                    context,
                                    platform="instagram",
                                    run_id=run_id,
                                    source_scope=opts.source_scope,
                                    account=account,
                                    post_row=existing_row,
                                    parent_job_id=job_id,
                                    conn=details_conn,
                                )
                            except Exception:  # noqa: BLE001
                                logger.exception(
                                    (
                                        "[instagram] Failed to enqueue fallback comment-media repairs "
                                        "during details refresh for %s"
                                    ),
                                    shortcode,
                                )
                    if resolved_views is None:
                        details_refresh_views_preserved_missing += 1
                    elif resolved_views > existing_views:
                        details_refresh_views_updated += 1
                    if views_source:
                        details_refresh_views_sources[views_source] += 1
                    if unresolved_required_detail_fields:
                        details_refresh_skipped_required_fields += 1
                        details_refresh_error_reasons["detail_fetch_skipped_limit_missing_required_fields"] += 1
                    else:
                        details_refreshed_posts += 1
                    matched_post_count += 1
                    activity["phase"] = "details_refresh_update"
                    activity["matched_posts"] = matched_post_count
                    _flush_progress()
                except Exception:  # noqa: BLE001
                    details_refresh_errors += 1
                    details_refresh_error_reasons["details_refresh_exception"] += 1
                    logger.exception(
                        "[instagram] Failed details refresh for post=%s shortcode=%s",
                        post_db_id,
                        shortcode,
                    )
        retrieval_meta["details_refreshed_posts"] = details_refreshed_posts
        retrieval_meta["details_refresh_views_updated"] = details_refresh_views_updated
        retrieval_meta["details_refresh_views_preserved_missing"] = details_refresh_views_preserved_missing
        retrieval_meta["details_refresh_detail_fetch_attempts"] = details_refresh_detail_fetch_attempts
        retrieval_meta["details_refresh_detail_fetch_skipped_limit"] = details_refresh_detail_fetch_skipped_limit
        retrieval_meta["details_refresh_skipped_required_fields"] = details_refresh_skipped_required_fields
        retrieval_meta["details_refresh_detail_fetch_cap"] = details_refresh_detail_fetch_cap
        if comment_media_mirror_jobs_enqueued:
            retrieval_meta["comment_media_mirror_jobs_enqueued"] = comment_media_mirror_jobs_enqueued
        if opts.details_refresh_skip_media_followups:
            retrieval_meta["details_refresh_skip_media_followups"] = True
        if details_refresh_views_sources:
            retrieval_meta["details_refresh_views_sources"] = dict(details_refresh_views_sources)
        if details_refresh_errors:
            retrieval_meta["details_refresh_errors"] = details_refresh_errors
        if details_refresh_error_reasons:
            retrieval_meta["details_refresh_error_reasons"] = dict(details_refresh_error_reasons)
    else:
        # Posts stage (or posts+comments): scrape from live API
        config = ScrapeConfig(
            username=account,
            hashtags=hashtags,
            date_start=opts.date_start,
            date_end=opts.date_end,
            delay_seconds=post_delay_seconds,
            max_pages=None,
            show_id=cast(Any, context.show_id),
            season_number=context.season_number,
        )
        logger.info("[instagram] Scraping account=%s date_range=%s..%s", account, opts.date_start, opts.date_end)
        post_limit = opts.max_posts_per_target if opts.max_posts_per_target > 0 else None

        def _on_scrape_progress(payload: dict[str, Any]) -> None:
            nonlocal scraped_post_count
            activity["phase"] = str(payload.get("phase") or "scrape_posts")
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
            if payload.get("total_posts") is not None:
                activity["total_posts"] = _normalize_non_negative_int(payload.get("total_posts"))
            if payload.get("matched_posts") is not None:
                activity["matched_posts"] = _normalize_non_negative_int(payload.get("matched_posts"))
            scraped_post_count = max(scraped_post_count, _normalize_non_negative_int(payload.get("posts_checked")))
            _flush_progress()

        posts = scraper.scrape(config, progress_cb=_on_scrape_progress)
        retrieval_meta.update(dict(getattr(scraper, "last_retrieval_meta", {}) or {}))
        try:
            instagram_week_windows, _ = _resolve_week_windows(
                context,
                timezone="America/New_York",
                source_scope=opts.source_scope,
                now_utc=_now_utc(),
            )
        except Exception:  # noqa: BLE001
            instagram_week_windows = []

        existing_post_lookup: dict[str, dict[str, Any]] = {}
        snapshots: dict[str, CommentLifecycleSnapshot] = {}
        if opts.sync_strategy == "incremental" and opts.max_comments_per_post > 0:
            existing_rows = _load_existing_posts("instagram", context, account, opts.date_start, opts.date_end)
            if _show_is_rhoslc(context):
                existing_rows = [row for row in existing_rows if _instagram_row_has_required_rhoslc_hashtag(row)]
            existing_post_lookup = _build_existing_post_lookup("instagram", existing_rows)
            snapshots = _load_comment_lifecycle_snapshots(
                [str(row.get("id")) for row in existing_post_lookup.values() if row.get("id")],
                platform="instagram",
            )

        skipped_synced = 0
        for post in posts:
            total_scraped += 1
            scraped_post_count = max(scraped_post_count, total_scraped)
            activity["phase"] = "posts_filter"
            activity["posts_checked"] = scraped_post_count
            caption = str(getattr(post, "caption", "") or "")
            post_hashtags = _as_text_list(getattr(post, "hashtags", []), strip_prefix="#")
            filter_text = _build_post_filter_text(
                primary_text=caption,
                hashtags=post_hashtags,
                mentions=_as_text_list(getattr(post, "mentions", []), prefix="@", strip_prefix="@"),
                collaborators=_as_text_list(getattr(post, "collaborators", [])),
                profile_tags=_as_text_list(getattr(post, "profile_tags", [])),
            )
            if not _instagram_post_matches_show_terms(
                context=context,
                text=filter_text,
                post_hashtags=post_hashtags,
                hashtags=hashtags,
                keywords=keywords,
            ):
                skipped_keyword += 1
                _flush_progress()
                continue
            if post_limit and matched_post_count >= post_limit:
                break

            existing_row = existing_post_lookup.get(str(getattr(post, "shortcode", "") or ""))
            if existing_row and opts.max_comments_per_post > 0:
                expected_comment_count = _expected_comment_count_for_platform(
                    "instagram",
                    {"comments_count": int(getattr(post, "comments", 0) or 0)},
                )
                decision = _decide_comment_refresh(
                    sync_strategy=opts.sync_strategy,
                    expected_count=expected_comment_count,
                    snapshot=snapshots.get(str(existing_row.get("id") or "")),
                    post_published_at=_coerce_dt(existing_row.get("posted_at")),
                    refresh_policy=opts.comment_refresh_policy,
                )
                comment_refresh_reasons[decision.reason] += 1
                if not decision.should_refresh:
                    skipped_synced += 1
                    activity["phase"] = "posts_skip_up_to_date"
                    _flush_progress()
                    continue

            now_utc = _now_utc()
            try:
                _enrich_instagram_post_from_permalink(post=post, scraper=scraper, now_utc=now_utc)
            except Exception:  # noqa: BLE001
                logger.exception(
                    "[instagram] Metadata enrichment failed for shortcode=%s",
                    getattr(post, "shortcode", "?"),
                )
                cast(Any, post).metadata_source = None
                cast(Any, post).metadata_scraped_at = now_utc
                cast(Any, post).metadata_error = "metadata_enrichment_exception"

            post_week_index = None
            post_ts = _parse_instagram_time(getattr(post, "taken_at", None))
            if post_ts and instagram_week_windows:
                window = _week_for_timestamp(post_ts, windows=instagram_week_windows, timezone="America/New_York")
                post_week_index = window.week_index if window else None

            source_thumbnail_url, source_media_urls = _instagram_post_source_urls(
                {
                    "thumbnail_url": getattr(post, "thumbnail_url", None),
                    "media_urls": getattr(post, "media_urls", []),
                }
            )
            if source_thumbnail_url or source_media_urls:
                cast(Any, post).media_mirror_status = "pending"
                cast(Any, post).media_mirror_error = None

            comments: list[Any] = []
            fail_reason = ""
            if opts.max_comments_per_post > 0:
                try:
                    comments = scraper.fetch_comments(
                        getattr(post, "shortcode", ""),
                        max_comments=opts.max_comments_per_post,
                        fetch_replies=opts.fetch_replies,
                        delay=comment_delay_seconds,
                    )
                    fail_reason = str(getattr(scraper, "last_comment_fetch_reason", "") or "")
                    if fail_reason:
                        comment_fail_reasons.add(fail_reason)
                        comment_fail_reason_counts[fail_reason] += 1
                        if not comments:
                            comment_errors += 1
                except Exception:
                    comment_errors += 1
                    incomplete_comment_fetches += 1
                    comments_mark_missing_skipped += 1
                    logger.exception(
                        "[instagram] Failed to fetch comments for shortcode=%s",
                        getattr(post, "shortcode", "?"),
                    )
                    continue

            local_comment_stats = _new_comment_persist_stats()
            observed_comment_ids: set[str] = set()
            mirror_job_id: str | None = None
            upserted: dict[str, Any] | None = None
            try:
                with pg.db_connection() as conn:
                    upserted = _upsert_instagram_post(context, job_id=job_id, account=account, post=post, conn=conn)
                    if not upserted:
                        _flush_progress()
                        continue

                    activity["phase"] = "posts_upsert"
                    _flush_progress()

                    if opts.max_comments_per_post > 0:
                        for comment in comments:
                            _upsert_instagram_comment_tree(
                                context,
                                job_id=job_id,
                                run_id=run_id,
                                account=account,
                                post_id=str(upserted["id"]),
                                comment=comment,
                                observed_comment_ids=observed_comment_ids,
                                persist_stats=local_comment_stats,
                                source_scope=opts.source_scope,
                                conn=conn,
                            )

                        is_complete = _is_comment_fetch_complete(
                            fetch_failed=False,
                            fail_reason=fail_reason,
                            auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                            fetched_count=len(comments),
                            max_comments_per_post=opts.max_comments_per_post,
                        )
                        if is_complete:
                            missing_marked += _mark_missing_comments_for_anchor(
                                platform="instagram",
                                anchor_id=str(upserted["id"]),
                                observed_comment_ids=observed_comment_ids,
                                conn=conn,
                            )
                            _reconcile_post_comment_count(
                                platform="instagram",
                                post_db_id=str(upserted["id"]),
                                conn=conn,
                            )
                        else:
                            incomplete_comment_fetches += 1
                            comments_mark_missing_skipped += 1

                    try:
                        mirror_job_id = _enqueue_instagram_media_mirror_job(
                            context,
                            run_id=run_id,
                            source_scope=opts.source_scope,
                            account=account,
                            post_row=upserted,
                            week_index=post_week_index,
                            parent_job_id=job_id,
                            conn=conn,
                        )
                    except Exception:  # noqa: BLE001
                        mirror_job_enqueue_errors += 1
                        logger.exception(
                            "[instagram] Failed to enqueue media mirror job for post=%s shortcode=%s",
                            str((upserted or {}).get("id") or ""),
                            getattr(post, "shortcode", "?"),
                        )
            except Exception:
                comment_errors += 1
                if upserted:
                    rolled_back_posts += 1
                rolled_back_comments += int(local_comment_stats.get("comments_upserted") or 0)
                logger.exception(
                    "[instagram] Failed to sync post/comment transaction for post %s (shortcode=%s)",
                    (upserted or {}).get("id"),
                    getattr(post, "shortcode", "?"),
                )
                continue

            matched_post_count += 1
            activity["matched_posts"] = matched_post_count
            if mirror_job_id:
                mirror_jobs_enqueued += 1
            _merge_comment_persist_stats(comment_stats, local_comment_stats)
            scraped_comment_count = int(comment_stats.get("comments_fetched") or 0)
            _flush_progress()

    activity["phase"] = f"{stage}_end"
    activity["matched_posts"] = matched_post_count
    _flush_progress(force=True)

    if skipped_synced:
        logger.info("[instagram] Skipped %d posts already up-to-date", skipped_synced)
    if comment_errors:
        retrieval_meta["comment_errors"] = comment_errors
    if comment_fail_reasons:
        retrieval_meta["comment_fail_reasons"] = sorted(comment_fail_reasons)
    if comment_fail_reason_counts:
        retrieval_meta["comment_fetch_failures_by_reason"] = dict(comment_fail_reason_counts)
    if comment_refresh_reasons:
        retrieval_meta["comment_refresh_decisions"] = dict(comment_refresh_reasons)
    if missing_marked:
        retrieval_meta["comments_marked_missing"] = missing_marked
    if incomplete_comment_fetches:
        retrieval_meta["incomplete_comment_fetches"] = incomplete_comment_fetches
    if comments_mark_missing_skipped:
        retrieval_meta["comments_mark_missing_skipped"] = comments_mark_missing_skipped
    if rolled_back_posts:
        retrieval_meta["rolled_back_posts"] = rolled_back_posts
    if rolled_back_comments:
        retrieval_meta["rolled_back_comments"] = rolled_back_comments
    if mirror_jobs_enqueued:
        retrieval_meta["media_mirror_jobs_enqueued"] = mirror_jobs_enqueued
    if mirror_job_enqueue_errors:
        retrieval_meta["media_mirror_job_enqueue_errors"] = mirror_job_enqueue_errors
    comment_media_mirror_jobs_enqueued = int(comment_stats.get("comment_media_mirror_jobs_enqueued") or 0)
    comment_media_mirror_job_enqueue_errors = int(comment_stats.get("comment_media_mirror_job_enqueue_errors") or 0)
    if comment_media_mirror_jobs_enqueued:
        retrieval_meta["comment_media_mirror_jobs_enqueued"] = comment_media_mirror_jobs_enqueued
    if comment_media_mirror_job_enqueue_errors:
        retrieval_meta["comment_media_mirror_job_enqueue_errors"] = comment_media_mirror_job_enqueue_errors
    retrieval_meta["comment_stats"] = _comment_stats_payload(comment_stats)
    if stage == "posts":
        retrieval_meta["posts_filter_counters"] = {
            "candidate_posts_found": total_scraped,
            "matched_posts": matched_post_count,
            "filtered_out_show_terms": skipped_keyword,
            "filtered_out_up_to_date": skipped_synced,
            "filtered_out_total": skipped_keyword + skipped_synced,
        }
    retrieval_meta["scrape_counters"] = {"posts": scraped_post_count, "comments": scraped_comment_count}
    retrieval_meta["persist_counters"] = {
        "posts_upserted": matched_post_count,
        "comments_upserted": int(comment_stats.get("comments_upserted") or 0),
    }
    retrieval_meta["activity"] = _build_progress_activity_payload(activity, now=_now_utc())
    if scraper.comments_auth_failed:
        retrieval_meta["comments_auth_failed"] = True
    logger.info(
        "[instagram] Done: scraped=%d matched=%d skipped_keyword=%d comments=%d comment_errors=%d auth_failed=%s",
        total_scraped,
        matched_post_count,
        skipped_keyword,
        scraped_comment_count,
        comment_errors,
        scraper.comments_auth_failed,
    )
    return scraped_post_count, scraped_comment_count, retrieval_meta


def _load_show_cast_people(show_id: str, *, conn: Any | None = None) -> list[dict[str, str]]:
    rows: list[dict[str, Any]]
    try:
        if conn is None:
            rows = pg.fetch_all(
                """
                select distinct
                  coalesce(v.person_id::text, '') as person_id,
                  coalesce(nullif(v.cast_member_name, ''), nullif(p.full_name, ''), '') as cast_member_name
                from core.v_show_cast v
                left join core.people p on p.id = v.person_id
                where v.show_id = %s
                  and lower(coalesce(v.credit_category, 'cast')) in ('cast', 'self')
                order by cast_member_name asc
                limit 500
                """,
                [show_id],
            )
        else:
            with pg.db_cursor(conn=conn) as cur:
                rows = pg.fetch_all_with_cursor(
                    cur,
                    """
                    select distinct
                      coalesce(v.person_id::text, '') as person_id,
                      coalesce(nullif(v.cast_member_name, ''), nullif(p.full_name, ''), '') as cast_member_name
                    from core.v_show_cast v
                    left join core.people p on p.id = v.person_id
                    where v.show_id = %s
                      and lower(coalesce(v.credit_category, 'cast')) in ('cast', 'self')
                    order by cast_member_name asc
                    limit 500
                    """,
                    [show_id],
                )
    except Exception:
        logger.debug("Failed to load show cast for show_id=%s", show_id, exc_info=True)
        return []

    out: list[dict[str, str]] = []
    seen: set[str] = set()
    for row in rows:
        name = str(row.get("cast_member_name") or "").strip()
        if not name:
            continue
        key = name.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append({"person_id": str(row.get("person_id") or "").strip(), "name": name})
    return out


def _extract_cast_mentions_from_text(text: str | None, cast_people: list[dict[str, str]]) -> list[dict[str, Any]]:
    blob = str(text or "")
    if not blob:
        return []
    mentions: list[dict[str, Any]] = []
    for person in cast_people:
        name = str(person.get("name") or "").strip()
        if not name:
            continue
        pattern = rf"(?<![A-Za-z0-9]){re.escape(name)}(?![A-Za-z0-9])"
        if not re.search(pattern, blob, re.IGNORECASE):
            continue
        mentions.append(
            {
                "person_id": str(person.get("person_id") or "").strip() or None,
                "name": name,
                "confidence": 0.85,
            }
        )
    return mentions


def _extract_keyword_tokens_from_text(text: str | None, keywords: list[str]) -> list[str]:
    blob = str(text or "").lower()
    if not blob:
        return []
    matched: list[str] = []
    for keyword in keywords:
        term = str(keyword or "").strip().lower()
        if not term:
            continue
        if term in blob:
            matched.append(term)
    return _normalize_unique_terms(matched)


def _compute_tiktok_post_quality(
    *,
    description: str | None,
    thumbnail_url: str | None,
    hashtags: list[str],
    mentions: list[str],
    media_urls: list[str],
    duration_seconds: int | None,
) -> tuple[float, list[str], list[str]]:
    score = 100.0
    missing_fields: list[str] = []
    flags: list[str] = []
    if not str(description or "").strip():
        score -= 25.0
        missing_fields.append("description")
    if not str(thumbnail_url or "").strip():
        score -= 20.0
        missing_fields.append("thumbnail_url")
    if not media_urls:
        score -= 20.0
        missing_fields.append("media_urls")
    if not hashtags:
        score -= 10.0
        flags.append("no_hashtags")
    if not mentions:
        flags.append("no_mentions")
    if not duration_seconds or int(duration_seconds) <= 0:
        score -= 5.0
        flags.append("duration_missing")
    return max(0.0, round(score, 2)), missing_fields, flags


def _compute_tiktok_velocity_metrics(*, views: int, posted_at: datetime | None) -> tuple[float, float, float]:
    if not posted_at:
        base = float(max(0, int(views or 0)))
        return base, base, base
    elapsed_hours = max(1.0, (_now_utc() - posted_at).total_seconds() / 3600.0)
    view_count = float(max(0, int(views or 0)))
    velocity_1h = round(view_count / min(elapsed_hours, 1.0), 3)
    velocity_24h = round(view_count / min(elapsed_hours, 24.0), 3)
    velocity_7d = round(view_count / min(elapsed_hours, 24.0 * 7.0), 3)
    return velocity_1h, velocity_24h, velocity_7d


def _persist_tiktok_post_enrichment(
    *,
    context: SeasonContext,
    run_id: str | None,
    post_row: dict[str, Any],
    description: str | None,
    hashtags: list[str],
    mentions: list[str],
    keywords: list[str],
    cast_mentions: list[dict[str, Any]],
    quality_score: float,
    quality_missing_fields: list[str],
    quality_flags: list[str],
    velocity_1h: float,
    velocity_24h: float,
    velocity_7d: float,
    conn: Any | None = None,
) -> None:
    if not _relation_exists("social.tiktok_post_tokens"):
        return
    post_id = str(post_row.get("id") or "").strip()
    if not post_id:
        return
    keyword_tokens = _extract_keyword_tokens_from_text(description, keywords)
    token_rows: list[tuple[str, str, str]] = []
    for token in hashtags:
        normalized = str(token or "").strip().lstrip("#").lower()
        if normalized:
            token_rows.append((f"#{normalized}", "hashtag", normalized))
    for token in mentions:
        normalized = str(token or "").strip().lstrip("@").lower()
        if normalized:
            token_rows.append((f"@{normalized}", "mention", normalized))
    for token in keyword_tokens:
        normalized = str(token or "").strip().lower()
        if normalized:
            token_rows.append((normalized, "keyword", normalized))
    deduped_token_rows: list[tuple[str, str, str]] = []
    seen_tokens: set[tuple[str, str]] = set()
    for token, token_type, normalized in token_rows:
        key = (token_type, normalized)
        if key in seen_tokens:
            continue
        seen_tokens.add(key)
        deduped_token_rows.append((token, token_type, normalized))

    with pg.db_cursor(conn=conn) as cur:
        pg.fetch_one_with_cursor(
            cur,
            """
            delete from social.tiktok_post_tokens
            where post_id = %s::uuid
            """,
            [post_id],
        )
        for token, token_type, normalized in deduped_token_rows:
            pg.fetch_one_with_cursor(
                cur,
                """
                insert into social.tiktok_post_tokens (post_id, token, token_type, normalized_token)
                values (%s::uuid, %s, %s, %s)
                on conflict (post_id, token_type, normalized_token) do update
                set token = excluded.token
                returning id::text
                """,
                [post_id, token, token_type, normalized],
            )

        pg.fetch_one_with_cursor(
            cur,
            """
            delete from social.tiktok_post_cast_members
            where post_id = %s::uuid and source = 'auto'
            """,
            [post_id],
        )
        for mention in cast_mentions:
            person_id = str(mention.get("person_id") or "").strip() or None
            pg.fetch_one_with_cursor(
                cur,
                """
                insert into social.tiktok_post_cast_members (
                  post_id,
                  cast_member_id,
                  cast_member_name,
                  confidence,
                  source,
                  run_id
                )
                values (
                  %s::uuid,
                  %s::uuid,
                  %s,
                  %s,
                  'auto',
                  %s::uuid
                )
                on conflict (post_id, cast_member_id, source) do update
                set
                  cast_member_name = excluded.cast_member_name,
                  confidence = excluded.confidence,
                  run_id = excluded.run_id,
                  updated_at = now()
                returning id::text
                """,
                [post_id, person_id, mention.get("name"), float(mention.get("confidence") or 0.85), run_id],
            )

        pg.fetch_one_with_cursor(
            cur,
            """
            insert into social.tiktok_post_quality (
              post_id,
              quality_score,
              missing_fields,
              confidence_flags,
              updated_at
            )
            values (%s::uuid, %s, %s::jsonb, %s::jsonb, now())
            on conflict (post_id) do update
            set
              quality_score = excluded.quality_score,
              missing_fields = excluded.missing_fields,
              confidence_flags = excluded.confidence_flags,
              updated_at = now()
            returning post_id::text
            """,
            [post_id, quality_score, json.dumps(quality_missing_fields), json.dumps(quality_flags)],
        )
        pg.fetch_one_with_cursor(
            cur,
            """
            insert into social.tiktok_post_velocity (
              post_id,
              velocity_1h,
              velocity_24h,
              velocity_7d,
              snapshot_at,
              updated_at
            )
            values (%s::uuid, %s, %s, %s, now(), now())
            on conflict (post_id) do update
            set
              velocity_1h = excluded.velocity_1h,
              velocity_24h = excluded.velocity_24h,
              velocity_7d = excluded.velocity_7d,
              snapshot_at = now(),
              updated_at = now()
            returning post_id::text
            """,
            [post_id, velocity_1h, velocity_24h, velocity_7d],
        )
        post_updates: dict[str, Any] = {}
        if _platform_posts_has_column("tiktok", "quality_score"):
            post_updates["quality_score"] = quality_score
        if _platform_posts_has_column("tiktok", "quality_flags"):
            post_updates["quality_flags"] = quality_flags
        if _platform_posts_has_column("tiktok", "velocity_1h"):
            post_updates["velocity_1h"] = velocity_1h
        if _platform_posts_has_column("tiktok", "velocity_24h"):
            post_updates["velocity_24h"] = velocity_24h
        if _platform_posts_has_column("tiktok", "velocity_7d"):
            post_updates["velocity_7d"] = velocity_7d
        if _platform_posts_has_column("tiktok", "cast_member_mentions"):
            post_updates["cast_member_mentions"] = [
                str(item.get("name") or "") for item in cast_mentions if str(item.get("name") or "")
            ]
        if post_updates:
            assignments: list[str] = []
            params: list[Any] = []
            for key, value in post_updates.items():
                if key in {"quality_flags", "cast_member_mentions"}:
                    assignments.append(f"{key} = %s::jsonb")
                    params.append(json.dumps(value))
                else:
                    assignments.append(f"{key} = %s")
                    params.append(value)
            with pg.db_cursor(conn=conn) as update_cur:
                pg.fetch_one_with_cursor(
                    update_cur,
                    f"""
                    update social.tiktok_posts
                    set {", ".join(assignments)}
                    where id = %s::uuid
                    returning id::text
                    """,
                    [*params, post_id],
                )


def _persist_tiktok_comment_enrichment(
    *,
    post_id: str,
    cast_names: list[str],
    conn: Any | None = None,
) -> None:
    if not _relation_exists("social.tiktok_post_comment_enrichment"):
        return
    comment_rows = pg.fetch_all(
        """
        select coalesce(text, '') as text
        from social.tiktok_comments
        where post_id = %s::uuid
          and coalesce(is_missing, false) = false
        """,
        [post_id],
    )
    positive = 0
    neutral = 0
    negative = 0
    toxicity = 0
    cast_mentions_count = 0
    cast_lower = [str(name or "").strip().lower() for name in cast_names if str(name or "").strip()]
    for row in comment_rows:
        text = str((row or {}).get("text") or "")
        label, _score = sentiment_for_text(text)
        if label == "positive":
            positive += 1
        elif label == "negative":
            negative += 1
        else:
            neutral += 1
        lowered = text.lower()
        if any(marker in lowered for marker in TOXICITY_MARKERS):
            toxicity += 1
        if cast_lower and any(name in lowered for name in cast_lower):
            cast_mentions_count += 1
    with pg.db_cursor(conn=conn) as cur:
        pg.fetch_one_with_cursor(
            cur,
            """
            insert into social.tiktok_post_comment_enrichment (
              post_id,
              positive_count,
              neutral_count,
              negative_count,
              toxicity_count,
              cast_mentions_count,
              updated_at
            )
            values (%s::uuid, %s, %s, %s, %s, %s, now())
            on conflict (post_id) do update
            set
              positive_count = excluded.positive_count,
              neutral_count = excluded.neutral_count,
              negative_count = excluded.negative_count,
              toxicity_count = excluded.toxicity_count,
              cast_mentions_count = excluded.cast_mentions_count,
              updated_at = now()
            returning post_id::text
            """,
            [post_id, positive, neutral, negative, toxicity, cast_mentions_count],
        )


def _load_ingest_checkpoint(*, platform: str, creator_id: str) -> dict[str, Any] | None:
    if not _relation_exists("social.social_ingest_checkpoints"):
        return None
    return pg.fetch_one(
        """
        select
          id::text,
          platform,
          creator_id,
          cursor,
          last_posted_at,
          metadata,
          updated_at
        from social.social_ingest_checkpoints
        where platform = %s and creator_id = %s
        """,
        [platform, creator_id],
    )


def _save_ingest_checkpoint(
    *,
    platform: str,
    creator_id: str,
    cursor: str | None,
    last_posted_at: datetime | None,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not _relation_exists("social.social_ingest_checkpoints"):
        return
    with pg.db_cursor() as cur:
        pg.fetch_one_with_cursor(
            cur,
            """
            insert into social.social_ingest_checkpoints (
              platform,
              creator_id,
              cursor,
              last_posted_at,
              metadata,
              updated_at
            )
            values (%s, %s, %s, %s, %s::jsonb, now())
            on conflict (platform, creator_id) do update
            set
              cursor = excluded.cursor,
              last_posted_at = excluded.last_posted_at,
              metadata = excluded.metadata,
              updated_at = now()
            returning id::text
            """,
            [platform, creator_id, cursor, last_posted_at, json.dumps(dict(metadata or {}))],
        )


def _record_tiktok_anomaly_event(
    *,
    season_id: str,
    post_id: str,
    account: str,
    event_type: str,
    event_value: float,
    baseline_value: float,
    metadata: dict[str, Any] | None = None,
) -> None:
    if not _relation_exists("social.tiktok_anomaly_events"):
        return
    severity = "warn"
    if baseline_value > 0 and event_value >= (3.0 * baseline_value):
        severity = "critical"
    with pg.db_cursor() as cur:
        pg.fetch_one_with_cursor(
            cur,
            """
            insert into social.tiktok_anomaly_events (
              season_id,
              post_id,
              account,
              event_type,
              severity,
              event_value,
              baseline_value,
              metadata
            )
            values (%s::uuid, %s::uuid, %s, %s, %s, %s, %s, %s::jsonb)
            returning id::text
            """,
            [
                season_id,
                post_id,
                account,
                event_type,
                severity,
                event_value,
                baseline_value,
                json.dumps(dict(metadata or {})),
            ],
        )


def _upsert_tiktok_post(
    context: SeasonContext | None, *, job_id: str | None, account: str, post: Any, conn: Any | None = None
) -> dict[str, Any] | None:
    posted_at = _parse_tiktok_time(getattr(post, "create_time", None))
    raw_data = post.to_dict() if hasattr(post, "to_dict") else {}
    if not isinstance(raw_data, dict):
        raw_data = {}
    media_urls = [str(url).strip() for url in (getattr(post, "media_urls", []) or []) if str(url).strip()]
    thumbnail_url = str(getattr(post, "thumbnail_url", "") or "").strip() or (media_urls[0] if media_urls else None)
    description = str(getattr(post, "description", "") or "")
    hashtags = _as_text_list(
        [
            *_as_text_list(getattr(post, "hashtags", []), strip_prefix="#"),
            *_parse_hashtags(description),
        ],
        strip_prefix="#",
    )
    mentions = _as_text_list(
        [
            *_as_text_list(getattr(post, "mentions", []), prefix="@", strip_prefix="@"),
            *_parse_mentions(description),
        ],
        prefix="@",
        strip_prefix="@",
    )
    sound_fields = _extract_tiktok_sound_fields(raw_data, post)
    payload = {
        "video_id": getattr(post, "video_id", ""),
        "aweme_id": getattr(post, "video_id", ""),
        "username": getattr(post, "username", account),
        "user_id": None,
        "nickname": getattr(post, "author_nickname", None),
        "description": getattr(post, "description", None),
        "hashtags": hashtags,
        "music_info": {
            "title": getattr(post, "music_title", None),
            "author": getattr(post, "music_author", None),
        },
        "likes": int(getattr(post, "likes", 0) or 0),
        "comments_count": int(getattr(post, "comments", 0) or 0),
        "shares": int(getattr(post, "shares", 0) or 0),
        "views": int(getattr(post, "views", 0) or 0),
        "duration_seconds": int(getattr(post, "duration", 0) or 0),
        "thumbnail_url": thumbnail_url,
        "posted_at": posted_at,
        "scraped_at": _now_utc(),
        "raw_data": raw_data,
        "source_account": account,
    }
    _apply_assignment_payload(payload, context)
    if job_id:
        payload["job_id"] = job_id
    if _platform_posts_has_column("tiktok", "saves", conn=conn):
        payload["saves"] = int(getattr(post, "saves", 0) or 0)
    if _platform_posts_has_column("tiktok", "mentions", conn=conn):
        payload["mentions"] = mentions
    if _platform_posts_has_column("tiktok", "media_urls", conn=conn):
        payload["media_urls"] = media_urls
    if _platform_posts_has_column("tiktok", "sound_id", conn=conn):
        payload["sound_id"] = sound_fields.get("sound_id")
    if _platform_posts_has_column("tiktok", "sound_title", conn=conn):
        payload["sound_title"] = sound_fields.get("sound_title")
    if _platform_posts_has_column("tiktok", "sound_author", conn=conn):
        payload["sound_author"] = sound_fields.get("sound_author")
    if _platform_posts_has_column("tiktok", "sound_usage_count", conn=conn):
        payload["sound_usage_count"] = _normalize_non_negative_int(sound_fields.get("sound_usage_count"))
    if _platform_posts_has_column("tiktok", "user_avatar_url", conn=conn):
        payload["user_avatar_url"] = str(getattr(post, "user_avatar_url", "") or "").strip() or None
    return _pg_upsert("tiktok_posts", payload, conflict_col="video_id", conn=conn)


def _upsert_tiktok_comment_tree(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    post_id: str,
    comment: Any,
    parent_comment_db_id: str | None = None,
    source_scope: str = "network",
    observed_comment_ids: set[str] | None = None,
    persist_stats: dict[str, int] | None = None,
    conn: Any | None = None,
) -> int:
    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1

    created_at = _parse_tiktok_time(getattr(comment, "created_at", None))
    comment_external_id = str(getattr(comment, "comment_id", "") or "")
    if observed_comment_ids is not None and comment_external_id:
        observed_comment_ids.add(comment_external_id)
    if not comment_external_id.strip():
        if persist_stats is not None:
            persist_stats["comments_skipped_missing_id"] = (
                int(persist_stats.get("comments_skipped_missing_id") or 0) + 1
            )
        total = 0
        for reply in getattr(comment, "replies", []) or []:
            total += _upsert_tiktok_comment_tree(
                context,
                job_id=job_id,
                run_id=run_id,
                account=account,
                post_id=post_id,
                comment=reply,
                parent_comment_db_id=parent_comment_db_id,
                observed_comment_ids=observed_comment_ids,
                persist_stats=persist_stats,
                source_scope=source_scope,
                conn=conn,
            )
        return total
    media_urls = [str(url).strip() for url in (getattr(comment, "media_urls", []) or []) if str(url).strip()]
    payload = {
        "comment_id": comment_external_id,
        "post_id": post_id,
        "parent_comment_id": parent_comment_db_id,
        "username": getattr(comment, "username", ""),
        "user_id": getattr(comment, "user_id", None),
        "nickname": getattr(comment, "nickname", None),
        "text": getattr(comment, "text", ""),
        "likes": int(getattr(comment, "likes", 0) or 0),
        "is_reply": bool(getattr(comment, "is_reply", False)),
        "reply_count": int(getattr(comment, "reply_count", 0) or 0),
        "created_at": created_at,
        "scraped_at": _now_utc(),
        "raw_data": comment.to_dict() if hasattr(comment, "to_dict") else {},
        "source_account": account,
    }
    if context is not None:
        payload["season_id"] = context.season_id
    if _tiktok_comments_has_column("comment_language", conn=conn):
        payload["comment_language"] = str(getattr(comment, "comment_language", "") or "").strip() or None
    if _tiktok_comments_has_column("is_author_liked", conn=conn):
        is_author_liked = getattr(comment, "is_author_liked", None)
        payload["is_author_liked"] = bool(is_author_liked) if isinstance(is_author_liked, (bool, int)) else None
    if _tiktok_comments_has_column("aweme_id", conn=conn):
        payload["aweme_id"] = str(getattr(comment, "aweme_id", "") or "").strip() or None
    if _tiktok_comments_has_column("parent_source_comment_id", conn=conn):
        payload["parent_source_comment_id"] = (
            str(getattr(comment, "parent_source_comment_id", "") or "").strip() or None
        )
    if _tiktok_comments_has_column("user_url", conn=conn):
        payload["user_url"] = str(getattr(comment, "user_url", "") or "").strip() or None
    if _tiktok_comments_has_column("user_bio", conn=conn):
        payload["user_bio"] = str(getattr(comment, "user_bio", "") or "").strip() or None
    if _tiktok_comments_has_column("user_avatar_url", conn=conn):
        payload["user_avatar_url"] = str(getattr(comment, "user_avatar_url", "") or "").strip() or None
    if _tiktok_comments_has_column("user_region", conn=conn):
        payload["user_region"] = str(getattr(comment, "user_region", "") or "").strip() or None
    if _tiktok_comments_has_column("user_language", conn=conn):
        payload["user_language"] = str(getattr(comment, "user_language", "") or "").strip() or None
    if _tiktok_comments_has_column("media_urls", conn=conn):
        payload["media_urls"] = media_urls
    if media_urls and _tiktok_comments_has_column("media_mirror_status", conn=conn):
        payload["media_mirror_status"] = "pending"
    if media_urls and _tiktok_comments_has_column("media_mirror_error", conn=conn):
        payload["media_mirror_error"] = None
    if job_id:
        payload["job_id"] = job_id
    if _comment_lifecycle_supported("tiktok_comments", conn=conn):
        payload["is_missing"] = False
        payload["missing_at"] = None
        payload["last_seen_at"] = _now_utc()
        if run_id is not None:
            payload["last_seen_run_id"] = run_id
    row = _pg_upsert("tiktok_comments", payload, conflict_col="comment_id", conn=conn)
    comment_db_id = (row or {}).get("id")
    if persist_stats is not None and row:
        persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + 1
    if row and media_urls and context is not None:
        try:
            mirror_job_id = _enqueue_tiktok_comment_media_mirror_job(
                context,
                run_id=run_id,
                account=account,
                comment_row=row,
                parent_job_id=job_id,
                source_scope=source_scope,
                conn=conn,
            )
            if mirror_job_id and persist_stats is not None:
                persist_stats["comment_media_mirror_jobs_enqueued"] = (
                    int(persist_stats.get("comment_media_mirror_jobs_enqueued") or 0) + 1
                )
        except Exception:  # noqa: BLE001
            if persist_stats is not None:
                persist_stats["comment_media_mirror_job_enqueue_errors"] = (
                    int(persist_stats.get("comment_media_mirror_job_enqueue_errors") or 0) + 1
                )

    total = 1 if row else 0
    for reply in getattr(comment, "replies", []) or []:
        total += _upsert_tiktok_comment_tree(
            context,
            job_id=job_id,
            run_id=run_id,
            account=account,
            post_id=post_id,
            comment=reply,
            parent_comment_db_id=comment_db_id,
            observed_comment_ids=observed_comment_ids,
            persist_stats=persist_stats,
            source_scope=source_scope,
            conn=conn,
        )
    return total


def _ingest_tiktok(
    context: SeasonContext,
    *,
    run_id: str | None,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    stage: str = "posts",
    job_config: dict[str, Any] | None = None,
) -> tuple[int, int, dict[str, Any]]:
    from trr_backend.socials.tiktok import TikTokScrapeConfig, TikTokScraper

    tiktok_cookies = _load_tiktok_cookies()
    direct_comment_api_override = (
        bool((job_config or {}).get("tiktok_direct_comment_api_override"))
        if _tiktok_catalog_comment_override_enabled()
        else False
    )
    scraper = TikTokScraper(
        cookies=tiktok_cookies,
        direct_comment_api_enabled_override=direct_comment_api_override if direct_comment_api_override else None,
    )

    retrieval_meta: dict[str, Any] = {
        "tiktok_direct_comment_api_override": direct_comment_api_override,
        "tiktok_direct_comment_api_override_enabled": _tiktok_catalog_comment_override_enabled(),
    }
    normalized_creator_id = _normalize_account_handle(account) or str(account or "").strip().lower()
    requested_sound_ids = _normalize_tiktok_sound_ids(opts.sound_ids or [])
    discovered_sound_ids: set[str] = set()
    sound_pages_attempted = 0
    sound_pages_succeeded = 0
    sound_posts_ingested = 0
    latest_posted_at_seen: datetime | None = None
    checkpoint_cursor: str | None = None
    checkpoint_last_posted_at: datetime | None = None
    skipped_checkpoint = 0
    cast_people = _load_show_cast_people(context.show_id)
    cast_names = [str(item.get("name") or "").strip() for item in cast_people if str(item.get("name") or "").strip()]
    if stage == "posts" and opts.sync_strategy == "incremental" and normalized_creator_id:
        checkpoint = _load_ingest_checkpoint(platform="tiktok", creator_id=normalized_creator_id) or {}
        checkpoint_cursor = str(checkpoint.get("cursor") or "").strip() or None
        checkpoint_last_posted_at = _coerce_dt(checkpoint.get("last_posted_at"))
        retrieval_meta["checkpoint"] = {
            "platform": "tiktok",
            "creator_id": normalized_creator_id,
            "cursor": checkpoint_cursor,
            "last_posted_at": _iso(checkpoint_last_posted_at),
        }
    matched_post_count = 0
    scraped_post_count = 0
    scraped_comment_count = 0
    comment_errors = 0
    comment_fail_reasons: set[str] = set()
    comment_refresh_reasons: Counter[str] = Counter()
    missing_marked = 0
    incomplete_comment_fetches = 0
    comments_mark_missing_skipped = 0
    mirror_jobs_enqueued = 0
    mirror_job_enqueue_errors = 0
    comment_stats = _new_comment_persist_stats()
    skipped_keyword = 0
    total_scraped = 0
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": f"{stage}_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
    }

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=stage,
            platform="tiktok",
            account=account,
            scraped_posts=scraped_post_count,
            scraped_comments=scraped_comment_count,
            posts_upserted=matched_post_count,
            comments_upserted=int(comment_stats.get("comments_upserted") or 0),
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)

    if stage == "posts" and opts.ingest_mode == "details_refresh":
        return _run_existing_post_details_refresh(
            context,
            platform="tiktok",
            run_id=run_id,
            account=account,
            opts=opts,
            job_id=job_id,
            activity=activity,
            flush_progress=_flush_progress,
        )

    if stage == "comments":
        target_source_ids = _target_source_ids_for_platform(opts, "tiktok")
        existing_posts = _load_existing_posts(
            "tiktok",
            context,
            account,
            opts.date_start,
            opts.date_end,
            source_ids=target_source_ids,
        )
        logger.info("[tiktok] Comments stage: %d existing posts from DB for account=%s", len(existing_posts), account)
        retrieval_meta["source"] = "db"
        snapshots = _load_comment_lifecycle_snapshots(
            [str(r["id"]) for r in existing_posts if r.get("id")],
            platform="tiktok",
        )
        skipped_synced = 0
        with pg.db_connection() as comments_conn:
            for post_index, row in enumerate(existing_posts, start=1):
                video_id = str(row.get("video_id") or "")
                post_db_id = str(row.get("id") or "")
                if not video_id:
                    continue
                expected = int(row.get("comments_count") or 0)
                decision = _decide_comment_refresh(
                    sync_strategy=opts.sync_strategy,
                    expected_count=expected,
                    snapshot=snapshots.get(post_db_id),
                    post_published_at=_coerce_dt(row.get("posted_at")),
                    refresh_policy=opts.comment_refresh_policy,
                )
                comment_refresh_reasons[decision.reason] += 1
                if not decision.should_refresh:
                    skipped_synced += 1
                    continue
                scraped_post_count += 1
                activity["phase"] = "comments_fetch"
                activity["posts_checked"] = scraped_post_count
                activity["matched_posts"] = matched_post_count
                if scraped_post_count % 10 == 0:
                    _touch_job_heartbeat(job_id)
                _flush_progress()
                fetch_failed = False
                comments: list[Any] = []
                fail_reason = ""
                observed_comment_ids: set[str] = set()
                local_comment_stats = _new_comment_persist_stats()
                try:
                    comments = scraper.fetch_comments(
                        video_id,
                        username=account,
                        max_comments=opts.max_comments_per_post,
                        fetch_replies=opts.fetch_replies,
                        delay=0.5,
                        max_replies_per_comment=_effective_reply_limit(opts),
                    )
                    _trim_nested_comment_replies(comments, max_replies_per_post=_effective_reply_limit(opts))
                    fail_reason = str(
                        getattr(scraper, "last_comment_fetch_reason", "")
                        or getattr(scraper, "_last_api_fail_reason", "")
                        or ""
                    )
                    if fail_reason:
                        comment_fail_reasons.add(fail_reason)
                        if not comments:
                            comment_errors += 1
                except Exception:
                    fetch_failed = True
                    comment_errors += 1
                    logger.exception(
                        "[tiktok] Failed to fetch comments for post %s (video_id=%s)",
                        post_db_id,
                        video_id,
                    )

                if not fetch_failed:
                    try:
                        with _SavepointScope(conn=comments_conn, prefix="tiktok_comments_stage", index=post_index):
                            for comment in comments:
                                _upsert_tiktok_comment_tree(
                                    context,
                                    job_id=job_id,
                                    run_id=run_id,
                                    account=account,
                                    post_id=post_db_id,
                                    comment=comment,
                                    source_scope=opts.source_scope,
                                    observed_comment_ids=observed_comment_ids,
                                    persist_stats=local_comment_stats,
                                    conn=comments_conn,
                                )

                            is_complete = _is_comment_fetch_complete(
                                fetch_failed=False,
                                fail_reason=fail_reason,
                                auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                                fetched_count=len(comments),
                                max_comments_per_post=opts.max_comments_per_post,
                            )
                            if is_complete:
                                missing_marked += _mark_missing_comments_for_anchor(
                                    platform="tiktok",
                                    anchor_id=post_db_id,
                                    observed_comment_ids=observed_comment_ids,
                                    conn=comments_conn,
                                )
                                _reconcile_post_comment_count(
                                    platform="tiktok",
                                    post_db_id=post_db_id,
                                    conn=comments_conn,
                                )
                            else:
                                incomplete_comment_fetches += 1
                                comments_mark_missing_skipped += 1
                    except Exception:
                        fetch_failed = True
                        comment_errors += 1
                        logger.exception(
                            "[tiktok] Failed to persist comments for post %s (video_id=%s)",
                            post_db_id,
                            video_id,
                        )

                if fetch_failed:
                    incomplete_comment_fetches += 1
                    comments_mark_missing_skipped += 1
                    continue

                matched_post_count += 1
                activity["matched_posts"] = matched_post_count
                _merge_comment_persist_stats(comment_stats, local_comment_stats)
                scraped_comment_count = int(comment_stats.get("comments_fetched") or 0)
                _flush_progress()
        if skipped_synced:
            logger.info("[tiktok] Skipped %d posts whose comments are already synced", skipped_synced)
    else:
        effective_date_start = opts.date_start
        if checkpoint_last_posted_at is not None and (
            effective_date_start is None or checkpoint_last_posted_at > effective_date_start
        ):
            # Only use the checkpoint if it falls within the requested date range.
            # If the checkpoint is beyond opts.date_end (e.g. a newer week was synced
            # previously), honour the explicit date_start so we actually scrape posts
            # in the requested window instead of returning nothing.
            if opts.date_end is None or checkpoint_last_posted_at <= opts.date_end:
                effective_date_start = checkpoint_last_posted_at
            else:
                logger.info(
                    "[tiktok] Ignoring checkpoint (last_posted_at=%s) because it is "
                    "beyond the requested date_end=%s; using date_start=%s",
                    checkpoint_last_posted_at,
                    opts.date_end,
                    opts.date_start,
                )
        config = TikTokScrapeConfig(
            username=account,
            hashtags=hashtags,
            date_start=effective_date_start,
            date_end=opts.date_end,
            delay_seconds=_resolve_platform_delay_seconds(
                platform="tiktok",
                attempt_count=int((job_config or {}).get("_attempt_count") or 1),
                last_error_code=(job_config or {}).get("_last_error_code"),
                default=0.35,
            ),
            max_pages=None,
            scrape_mode="ytdlp",
            show_id=cast(Any, context.show_id),
            season_number=context.season_number,
        )
        logger.info("[tiktok] Scraping account=%s date_range=%s..%s", account, effective_date_start, opts.date_end)
        post_limit = opts.max_posts_per_target if opts.max_posts_per_target > 0 else None

        def _on_scrape_progress(payload: dict[str, Any]) -> None:
            nonlocal scraped_post_count
            activity["phase"] = str(payload.get("phase") or "scrape_posts")
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
            if payload.get("matched_posts") is not None:
                activity["matched_posts"] = _normalize_non_negative_int(payload.get("matched_posts"))
            scraped_post_count = max(scraped_post_count, _normalize_non_negative_int(payload.get("posts_checked")))
            _flush_progress()

        posts = scraper.scrape(config, progress_cb=_on_scrape_progress)
        retrieval_meta.update(dict(getattr(scraper, "last_retrieval_meta", {}) or {}))

        existing_post_lookup: dict[str, dict[str, Any]] = {}
        snapshots: dict[str, CommentLifecycleSnapshot] = {}
        if opts.sync_strategy == "incremental" and opts.max_comments_per_post > 0:
            existing_rows = _load_existing_posts("tiktok", context, account, opts.date_start, opts.date_end)
            existing_post_lookup = _build_existing_post_lookup("tiktok", existing_rows)
            snapshots = _load_comment_lifecycle_snapshots(
                [str(row.get("id")) for row in existing_post_lookup.values() if row.get("id")],
                platform="tiktok",
            )

        skipped_synced = 0
        with pg.db_connection() as post_comments_conn:
            for post_index, post in enumerate(posts, start=1):
                total_scraped += 1
                scraped_post_count = max(scraped_post_count, total_scraped)
                activity["phase"] = "posts_filter"
                activity["posts_checked"] = scraped_post_count
                post_created_at = _parse_tiktok_time(getattr(post, "create_time", None))
                if (
                    checkpoint_last_posted_at
                    and post_created_at
                    and post_created_at <= checkpoint_last_posted_at
                    and (opts.date_end is None or checkpoint_last_posted_at <= opts.date_end)
                ):
                    skipped_checkpoint += 1
                    _flush_progress()
                    continue
                description = str(getattr(post, "description", "") or "")
                filter_text = _build_post_filter_text(
                    primary_text=description,
                    hashtags=_as_text_list(getattr(post, "hashtags", []), strip_prefix="#"),
                    mentions=_as_text_list(getattr(post, "mentions", []), prefix="@", strip_prefix="@"),
                )
                if not _text_contains_any_term(text=filter_text, hashtags=hashtags, keywords=keywords):
                    skipped_keyword += 1
                    _flush_progress()
                    continue
                if post_limit and matched_post_count >= post_limit:
                    break

                existing_row = existing_post_lookup.get(str(getattr(post, "video_id", "") or ""))
                if existing_row and opts.max_comments_per_post > 0:
                    expected_comment_count = _expected_comment_count_for_platform(
                        "tiktok",
                        {"comments_count": int(getattr(post, "comments", 0) or 0)},
                    )
                    decision = _decide_comment_refresh(
                        sync_strategy=opts.sync_strategy,
                        expected_count=expected_comment_count,
                        snapshot=snapshots.get(str(existing_row.get("id") or "")),
                        post_published_at=_coerce_dt(existing_row.get("posted_at")),
                        refresh_policy=opts.comment_refresh_policy,
                    )
                    comment_refresh_reasons[decision.reason] += 1
                    if not decision.should_refresh:
                        skipped_synced += 1
                        activity["phase"] = "posts_skip_up_to_date"
                        _flush_progress()
                        continue

                upserted: dict[str, Any] | None = None
                try:
                    with pg.db_connection() as conn:
                        upserted = _upsert_tiktok_post(context, job_id=job_id, account=account, post=post, conn=conn)
                        if upserted:
                            hashtag_terms = _as_text_list(getattr(post, "hashtags", []), strip_prefix="#")
                            mention_terms = _as_text_list(getattr(post, "mentions", []), prefix="@", strip_prefix="@")
                            cast_mentions = _extract_cast_mentions_from_text(
                                _build_post_filter_text(
                                    primary_text=description,
                                    hashtags=hashtag_terms,
                                    mentions=mention_terms,
                                ),
                                cast_people,
                            )
                            quality_score, missing_fields, quality_flags = _compute_tiktok_post_quality(
                                description=description,
                                thumbnail_url=str(getattr(post, "thumbnail_url", "") or "").strip() or None,
                                hashtags=hashtag_terms,
                                mentions=mention_terms,
                                media_urls=[
                                    str(url).strip()
                                    for url in (getattr(post, "media_urls", []) or [])
                                    if str(url).strip()
                                ],
                                duration_seconds=_normalize_non_negative_int(getattr(post, "duration", 0)),
                            )
                            velocity_1h, velocity_24h, velocity_7d = _compute_tiktok_velocity_metrics(
                                views=_normalize_non_negative_int(getattr(post, "views", 0)),
                                posted_at=post_created_at,
                            )
                            _persist_tiktok_post_enrichment(
                                context=context,
                                run_id=run_id,
                                post_row=upserted,
                                description=description,
                                hashtags=hashtag_terms,
                                mentions=mention_terms,
                                keywords=keywords,
                                cast_mentions=cast_mentions,
                                quality_score=quality_score,
                                quality_missing_fields=missing_fields,
                                quality_flags=quality_flags,
                                velocity_1h=velocity_1h,
                                velocity_24h=velocity_24h,
                                velocity_7d=velocity_7d,
                                conn=conn,
                            )

                            raw_data = post.to_dict() if hasattr(post, "to_dict") else {}
                            if not isinstance(raw_data, dict):
                                raw_data = {}
                            sound_fields = _extract_tiktok_sound_fields(raw_data, post)
                            sound_id = str(sound_fields.get("sound_id") or "").strip()
                            if sound_id:
                                discovered_sound_ids.add(sound_id)
                                _persist_tiktok_sound_snapshot(
                                    sound_id=sound_id,
                                    snapshot={
                                        "title": sound_fields.get("sound_title"),
                                        "artist_name": sound_fields.get("sound_author"),
                                        "usage_count": _normalize_non_negative_int(
                                            sound_fields.get("sound_usage_count")
                                        ),
                                        "source_url": _build_tiktok_sound_url(sound_id),
                                        "posts": [
                                            {
                                                "platform_post_id": str(getattr(post, "video_id", "") or "").strip(),
                                                "creator_handle": str(getattr(post, "username", "") or "").strip()
                                                or None,
                                                "posted_at": _iso(post_created_at),
                                                "views": _normalize_non_negative_int(getattr(post, "views", 0)),
                                                "likes": _normalize_non_negative_int(getattr(post, "likes", 0)),
                                                "comments": _normalize_non_negative_int(getattr(post, "comments", 0)),
                                                "shares": _normalize_non_negative_int(getattr(post, "shares", 0)),
                                                "thumbnail_url": str(getattr(post, "thumbnail_url", "") or "").strip()
                                                or None,
                                                "caption": description,
                                            }
                                        ],
                                    },
                                    conn=conn,
                                )
                except Exception:
                    comment_errors += 1
                    logger.exception(
                        "[tiktok] Failed to upsert post for video_id=%s",
                        getattr(post, "video_id", "?"),
                    )
                    _flush_progress()
                    continue

                if not upserted:
                    _flush_progress()
                    continue
                matched_post_count += 1
                if post_created_at and (latest_posted_at_seen is None or post_created_at > latest_posted_at_seen):
                    latest_posted_at_seen = post_created_at
                activity["phase"] = "posts_upsert"
                activity["matched_posts"] = matched_post_count
                _flush_progress()

                if stage == "posts":
                    try:
                        mirror_job_id = _enqueue_platform_media_mirror_job(
                            context,
                            platform="tiktok",
                            run_id=run_id,
                            source_scope=opts.source_scope,
                            account=account,
                            post_row=upserted,
                            week_index=None,
                            parent_job_id=job_id,
                            conn=None,
                        )
                        if mirror_job_id:
                            mirror_jobs_enqueued += 1
                    except Exception:  # noqa: BLE001
                        mirror_job_enqueue_errors += 1
                        logger.exception(
                            "[tiktok] Failed to enqueue media mirror job for post=%s video_id=%s",
                            str(upserted.get("id") or ""),
                            str(getattr(post, "video_id", "") or ""),
                        )

                if opts.max_comments_per_post > 0:
                    comments: list[Any] = []
                    fail_reason = ""
                    fetch_failed = False
                    observed_comment_ids: set[str] = set()
                    local_comment_stats = _new_comment_persist_stats()
                    try:
                        comments = scraper.fetch_comments(
                            getattr(post, "video_id", ""),
                            username=account,
                            max_comments=opts.max_comments_per_post,
                            fetch_replies=opts.fetch_replies,
                            delay=0.5,
                            max_replies_per_comment=_effective_reply_limit(opts),
                        )
                        _trim_nested_comment_replies(comments, max_replies_per_post=_effective_reply_limit(opts))
                        fail_reason = str(
                            getattr(scraper, "last_comment_fetch_reason", "")
                            or getattr(scraper, "_last_api_fail_reason", "")
                            or ""
                        )
                        if fail_reason:
                            comment_fail_reasons.add(fail_reason)
                            if not comments:
                                comment_errors += 1
                    except Exception:
                        fetch_failed = True
                        comment_errors += 1
                        logger.exception(
                            "[tiktok] Failed to fetch comments for post %s (video_id=%s)",
                            upserted.get("id"),
                            getattr(post, "video_id", "?"),
                        )
                        incomplete_comment_fetches += 1
                        comments_mark_missing_skipped += 1

                    if not fetch_failed:
                        try:
                            with _SavepointScope(
                                conn=post_comments_conn,
                                prefix="tiktok_post_comments",
                                index=post_index,
                            ):
                                for comment in comments:
                                    _upsert_tiktok_comment_tree(
                                        context,
                                        job_id=job_id,
                                        run_id=run_id,
                                        account=account,
                                        post_id=str(upserted["id"]),
                                        comment=comment,
                                        source_scope=opts.source_scope,
                                        observed_comment_ids=observed_comment_ids,
                                        persist_stats=local_comment_stats,
                                        conn=post_comments_conn,
                                    )

                                is_complete = _is_comment_fetch_complete(
                                    fetch_failed=False,
                                    fail_reason=fail_reason,
                                    auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                                    fetched_count=len(comments),
                                    max_comments_per_post=opts.max_comments_per_post,
                                )
                                if is_complete:
                                    missing_marked += _mark_missing_comments_for_anchor(
                                        platform="tiktok",
                                        anchor_id=str(upserted["id"]),
                                        observed_comment_ids=observed_comment_ids,
                                        conn=post_comments_conn,
                                    )
                                    _reconcile_post_comment_count(
                                        platform="tiktok",
                                        post_db_id=str(upserted["id"]),
                                        conn=post_comments_conn,
                                    )
                                else:
                                    incomplete_comment_fetches += 1
                                    comments_mark_missing_skipped += 1
                        except Exception:
                            fetch_failed = True
                            comment_errors += 1
                            logger.exception(
                                "[tiktok] Failed to persist comments for post %s (video_id=%s)",
                                upserted.get("id"),
                                getattr(post, "video_id", "?"),
                            )
                            incomplete_comment_fetches += 1
                            comments_mark_missing_skipped += 1

                    if not fetch_failed:
                        _merge_comment_persist_stats(comment_stats, local_comment_stats)
                        scraped_comment_count = int(comment_stats.get("comments_fetched") or 0)
                        try:
                            _persist_tiktok_comment_enrichment(
                                post_id=str(upserted["id"]),
                                cast_names=cast_names,
                            )
                        except Exception:
                            logger.debug(
                                "[tiktok] Failed to persist comment enrichment for post %s",
                                str(upserted.get("id") or ""),
                                exc_info=True,
                            )
                        activity["phase"] = "comments_fetch"
                        _flush_progress()

        if stage == "posts":
            sound_ids_to_fetch: list[str] = []
            seen_sound_ids: set[str] = set()
            for candidate in [*requested_sound_ids, *sorted(discovered_sound_ids)]:
                normalized_sound_id = _normalize_tiktok_sound_id(candidate)
                if not normalized_sound_id or normalized_sound_id in seen_sound_ids:
                    continue
                seen_sound_ids.add(normalized_sound_id)
                sound_ids_to_fetch.append(normalized_sound_id)

            for sound_id in sound_ids_to_fetch:
                sound_pages_attempted += 1
                try:
                    snapshot = _fetch_tiktok_sound_snapshot(sound_id)
                    _persist_tiktok_sound_snapshot(sound_id=sound_id, snapshot=snapshot)
                    sound_pages_succeeded += 1
                    sound_posts_ingested += len(snapshot.get("posts") or [])
                except Exception:
                    logger.debug("[tiktok] Failed to fetch/persist sound snapshot sound_id=%s", sound_id, exc_info=True)

            if normalized_creator_id and (latest_posted_at_seen or checkpoint_cursor):
                _save_ingest_checkpoint(
                    platform="tiktok",
                    creator_id=normalized_creator_id,
                    cursor=checkpoint_cursor,
                    last_posted_at=latest_posted_at_seen or checkpoint_last_posted_at,
                    metadata={
                        "stage": stage,
                        "account": account,
                        "job_id": job_id,
                        "run_id": run_id,
                        "sound_ids_requested": requested_sound_ids,
                        "sound_ids_discovered": sorted(discovered_sound_ids),
                    },
                )

    activity["phase"] = f"{stage}_end"
    activity["matched_posts"] = matched_post_count
    _flush_progress(force=True)

    if skipped_synced:
        logger.info("[tiktok] Skipped %d posts already up-to-date", skipped_synced)
    if comment_errors:
        retrieval_meta["comment_errors"] = comment_errors
    if comment_fail_reasons:
        retrieval_meta["comment_fail_reasons"] = sorted(comment_fail_reasons)
    if comment_refresh_reasons:
        retrieval_meta["comment_refresh_decisions"] = dict(comment_refresh_reasons)
    if missing_marked:
        retrieval_meta["comments_marked_missing"] = missing_marked
    if incomplete_comment_fetches:
        retrieval_meta["incomplete_comment_fetches"] = incomplete_comment_fetches
    if comments_mark_missing_skipped:
        retrieval_meta["comments_mark_missing_skipped"] = comments_mark_missing_skipped
    if mirror_jobs_enqueued:
        retrieval_meta["media_mirror_jobs_enqueued"] = mirror_jobs_enqueued
    if mirror_job_enqueue_errors:
        retrieval_meta["media_mirror_job_enqueue_errors"] = mirror_job_enqueue_errors
    retrieval_meta["comment_stats"] = _comment_stats_payload(comment_stats)
    if skipped_checkpoint:
        retrieval_meta["checkpoint_skipped_posts"] = skipped_checkpoint
    if requested_sound_ids:
        retrieval_meta["sound_ids_requested"] = requested_sound_ids
    if discovered_sound_ids:
        retrieval_meta["sound_ids_discovered"] = sorted(discovered_sound_ids)
    if sound_pages_attempted:
        retrieval_meta["sound_pages_attempted"] = sound_pages_attempted
    if sound_pages_succeeded:
        retrieval_meta["sound_pages_succeeded"] = sound_pages_succeeded
    if sound_posts_ingested:
        retrieval_meta["sound_posts_ingested"] = sound_posts_ingested
    if latest_posted_at_seen:
        retrieval_meta["latest_posted_at_seen"] = _iso(latest_posted_at_seen)
    if stage == "posts":
        retrieval_meta["posts_filter_counters"] = {
            "candidate_posts_found": total_scraped,
            "matched_posts": matched_post_count,
            "filtered_out_show_terms": skipped_keyword,
            "filtered_out_up_to_date": skipped_synced,
            "filtered_out_checkpoint": skipped_checkpoint,
            "filtered_out_total": skipped_keyword + skipped_synced + skipped_checkpoint,
        }
    retrieval_meta["scrape_counters"] = {"posts": scraped_post_count, "comments": scraped_comment_count}
    retrieval_meta["persist_counters"] = {
        "posts_upserted": matched_post_count,
        "comments_upserted": int(comment_stats.get("comments_upserted") or 0),
    }
    retrieval_meta["activity"] = _build_progress_activity_payload(activity, now=_now_utc())
    logger.info(
        "[tiktok] Done: scraped=%d matched=%d skipped_keyword=%d comments=%d comment_errors=%d",
        total_scraped,
        matched_post_count,
        skipped_keyword,
        scraped_comment_count,
        comment_errors,
    )
    return scraped_post_count, scraped_comment_count, retrieval_meta


def _upsert_youtube_video(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    account: str,
    video: Any,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    published_at = _parse_instagram_time(getattr(video, "published_at", None))
    source_surface_raw = str(getattr(video, "source_surface", "") or "").strip().lower()
    source_surface = source_surface_raw if source_surface_raw in {"videos", "shorts", "posts", "search"} else None
    is_short = bool(getattr(video, "is_short", False))
    title, description = _normalize_youtube_title_description(
        getattr(video, "title", ""),
        getattr(video, "description", ""),
        is_short=is_short,
    )
    token_text = f"{title}\n{description}".strip()
    tag_hashtags = [str(tag or "").strip().lstrip("#") for tag in (getattr(video, "tags", []) or [])]
    hashtags = _as_text_list([*_parse_hashtags(token_text), *tag_hashtags], strip_prefix="#")
    mentions = _as_text_list(_parse_mentions(token_text), prefix="@", strip_prefix="@")
    payload = {
        "video_id": getattr(video, "video_id", ""),
        "channel_id": getattr(video, "channel_id", None),
        "channel_title": getattr(video, "channel_title", None),
        "title": title,
        "description": description or None,
        "duration": getattr(video, "duration", None),
        "duration_seconds": int(getattr(video, "duration_seconds", 0) or 0),
        "views": int(getattr(video, "views", 0) or 0),
        "likes": int(getattr(video, "likes", 0) or 0),
        "comments_count": int(getattr(video, "comments", 0) or 0),
        "thumbnail_url": getattr(video, "thumbnail_url", None),
        "published_at": published_at,
        "scraped_at": _now_utc(),
        "raw_data": video.to_dict() if hasattr(video, "to_dict") else {},
        "source_account": account,
    }
    _apply_assignment_payload(payload, context)
    if job_id:
        payload["job_id"] = job_id
    if _platform_posts_has_column("youtube", "hashtags", conn=conn):
        payload["hashtags"] = hashtags
    if _platform_posts_has_column("youtube", "mentions", conn=conn):
        payload["mentions"] = mentions
    if _platform_posts_has_column("youtube", "is_short", conn=conn):
        payload["is_short"] = is_short
    if _platform_posts_has_column("youtube", "source_surface", conn=conn):
        payload["source_surface"] = source_surface
    if _platform_posts_has_column("youtube", "transcript_text", conn=conn):
        payload["transcript_text"] = str(getattr(video, "transcript_text", "") or "") or None
    if _platform_posts_has_column("youtube", "transcript_segments", conn=conn):
        transcript_segments = getattr(video, "transcript_segments", None)
        payload["transcript_segments"] = transcript_segments if isinstance(transcript_segments, list) else []
    if _platform_posts_has_column("youtube", "transcript_language", conn=conn):
        payload["transcript_language"] = str(getattr(video, "transcript_language", "") or "") or None
    if _platform_posts_has_column("youtube", "transcript_source", conn=conn):
        payload["transcript_source"] = str(getattr(video, "transcript_source", "") or "") or None
    if _platform_posts_has_column("youtube", "transcript_synced_at", conn=conn):
        payload["transcript_synced_at"] = _coerce_dt(getattr(video, "transcript_synced_at", None))
    if _platform_posts_has_column("youtube", "transcript_error", conn=conn):
        payload["transcript_error"] = str(getattr(video, "transcript_error", "") or "") or None
    if _platform_posts_has_column("youtube", "user_avatar_url", conn=conn):
        payload["user_avatar_url"] = str(getattr(video, "user_avatar_url", "") or "").strip() or None
    return _pg_upsert("youtube_videos", payload, conflict_col="video_id", conn=conn)


def _upsert_youtube_comment_tree(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    video_db_id: str,
    comment: Any,
    parent_comment_db_id: str | None = None,
    observed_comment_ids: set[str] | None = None,
    persist_stats: dict[str, int] | None = None,
    conn: Any | None = None,
) -> int:
    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1

    created_at = _parse_instagram_time(getattr(comment, "created_at", None))
    comment_external_id = str(getattr(comment, "comment_id", "") or "")
    if observed_comment_ids is not None and comment_external_id:
        observed_comment_ids.add(comment_external_id)
    if not comment_external_id.strip():
        if persist_stats is not None:
            persist_stats["comments_skipped_missing_id"] = (
                int(persist_stats.get("comments_skipped_missing_id") or 0) + 1
            )
        total = 0
        for reply in getattr(comment, "replies", []) or []:
            total += _upsert_youtube_comment_tree(
                context,
                job_id=job_id,
                run_id=run_id,
                account=account,
                video_db_id=video_db_id,
                comment=reply,
                parent_comment_db_id=parent_comment_db_id,
                observed_comment_ids=observed_comment_ids,
                persist_stats=persist_stats,
                conn=conn,
            )
        return total
    payload = {
        "comment_id": comment_external_id,
        "video_id": video_db_id,
        "parent_comment_id": parent_comment_db_id,
        "author": getattr(comment, "author", ""),
        "author_channel_id": getattr(comment, "author_channel_id", None),
        "text": getattr(comment, "text", ""),
        "likes": int(getattr(comment, "likes", 0) or 0),
        "is_reply": bool(getattr(comment, "is_reply", False)),
        "reply_count": int(getattr(comment, "reply_count", 0) or 0),
        "created_at": created_at,
        "scraped_at": _now_utc(),
        "raw_data": comment.to_dict() if hasattr(comment, "to_dict") else {},
        "season_id": context.season_id if context else None,
        "source_account": account,
    }
    if job_id:
        payload["job_id"] = job_id
    if _comment_lifecycle_supported("youtube_comments", conn=conn):
        payload["is_missing"] = False
        payload["missing_at"] = None
        payload["last_seen_at"] = _now_utc()
        if run_id is not None:
            payload["last_seen_run_id"] = run_id
    row = _pg_upsert("youtube_comments", payload, conflict_col="comment_id", conn=conn)
    comment_db_id = (row or {}).get("id")
    if persist_stats is not None and row:
        persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + 1

    total = 1 if row else 0
    for reply in getattr(comment, "replies", []) or []:
        total += _upsert_youtube_comment_tree(
            context,
            job_id=job_id,
            run_id=run_id,
            account=account,
            video_db_id=video_db_id,
            comment=reply,
            parent_comment_db_id=comment_db_id,
            observed_comment_ids=observed_comment_ids,
            persist_stats=persist_stats,
            conn=conn,
        )
    return total


def _ingest_youtube(
    context: SeasonContext,
    *,
    run_id: str | None,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    stage: str = "posts",
    job_config: dict[str, Any] | None = None,
) -> tuple[int, int, dict[str, Any]]:
    from trr_backend.socials.youtube import YouTubeDataApiClient, YouTubeScrapeConfig, YouTubeScraper

    scraper = YouTubeScraper()
    youtube_api = YouTubeDataApiClient()
    youtube_source_mode = _normalize_youtube_source_mode(getattr(opts, "youtube_source_mode", None))
    channel_sync_state = _load_youtube_channel_sync_state(
        season_id=context.season_id,
        source_scope=opts.source_scope,
        account_handle=account,
    )
    canonical_owner_handle = _normalize_account_handle(account)
    canonical_channel_id: str | None = None
    checkpoint_reused = False
    checkpoint_last_published_at: datetime | None = _coerce_dt(
        (channel_sync_state or {}).get("last_cursor_published_at")
    )
    saved_next_page_token = str((channel_sync_state or {}).get("last_page_token") or "").strip() or None
    discovery_started_at = _now_utc()
    resolve_channel_identity = getattr(scraper, "resolve_channel_identity", None)
    if youtube_api.enabled() and youtube_source_mode in {"hybrid", "api_only"}:
        api_identity = youtube_api.resolve_channel(account)
        if api_identity:
            resolved_handle = _normalize_account_handle((api_identity or {}).get("canonical_handle"))
            resolved_channel_id = str((api_identity or {}).get("channel_id") or "").strip() or None
            if resolved_handle:
                canonical_owner_handle = resolved_handle
            canonical_channel_id = resolved_channel_id
    if callable(resolve_channel_identity):
        try:
            resolved_identity = resolve_channel_identity(account, delay=0.25)
            resolved_identity_data = _as_string_mapping(resolved_identity)
            resolved_handle = _normalize_account_handle(resolved_identity_data.get("canonical_handle"))
            resolved_channel_id = str(resolved_identity_data.get("channel_id") or "").strip() or None
            if resolved_handle:
                canonical_owner_handle = resolved_handle
            canonical_channel_id = resolved_channel_id
        except Exception:  # noqa: BLE001
            logger.exception("[youtube] Failed to resolve canonical channel identity for @%s", account)
    cleanup_summary = {"videos_deleted": 0, "comments_deleted": 0}
    try:
        cleanup_summary = _cleanup_mismatched_youtube_rows(
            context=context,
            account=account,
            expected_handle=canonical_owner_handle or account,
            expected_channel_id=canonical_channel_id,
        )
    except Exception:  # noqa: BLE001
        logger.exception("[youtube] Ownership cleanup failed for @%s", account)
    if cleanup_summary["videos_deleted"] or cleanup_summary["comments_deleted"]:
        logger.info(
            "[youtube] Ownership cleanup removed mismatched rows season=%s account=%s videos=%d comments=%d",
            context.season_id,
            account,
            cleanup_summary["videos_deleted"],
            cleanup_summary["comments_deleted"],
        )

    retrieval_meta: dict[str, Any] = {}
    matched_video_count = 0
    scraped_video_count = 0
    scraped_comment_count = 0
    comment_errors = 0
    comment_fail_reasons: set[str] = set()
    comment_refresh_reasons: Counter[str] = Counter()
    missing_marked = 0
    incomplete_comment_fetches = 0
    comments_mark_missing_skipped = 0
    mirror_jobs_enqueued = 0
    mirror_job_enqueue_errors = 0
    comment_stats = _new_comment_persist_stats()
    skipped_keyword = 0
    total_scraped = 0
    videos_scanned = 0
    videos_matched_show_terms = 0
    videos_filtered_show_terms = 0
    videos_filtered_owner = 0
    videos_skipped_up_to_date = 0
    transcript_synced = 0
    transcript_failed = 0
    youtube_comment_count_synced = 0
    youtube_comment_count_sync_targets: set[str] = set()
    filter_samples: list[dict[str, str]] = []
    max_filter_samples = 8
    api_calls = 0
    api_candidate_videos = 0
    discovery_source = "scraper"
    matched_videos = 0
    matched_shorts = 0
    shorts_epoch_rows_repaired = 0
    shorts_undated_skipped = 0
    rows_missing_media = 0
    rows_missing_thumbnails = 0
    media_completion_failures = 0
    media_resolution_fallback_counts: Counter[str] = Counter()
    media_resolution_sources_used: Counter[str] = Counter()
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": f"{stage}_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
    }

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=stage,
            platform="youtube",
            account=account,
            scraped_posts=scraped_video_count,
            scraped_comments=scraped_comment_count,
            posts_upserted=matched_video_count,
            comments_upserted=int(comment_stats.get("comments_upserted") or 0),
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    def _record_filter_sample(*, reason: str, title: str | None, video_id: str | None) -> None:
        if len(filter_samples) >= max_filter_samples:
            return
        filter_samples.append(_youtube_filter_sample(reason=reason, title=title, video_id=video_id))

    _flush_progress(force=True)

    if stage == "posts" and opts.ingest_mode == "details_refresh":
        return _run_existing_post_details_refresh(
            context,
            platform="youtube",
            run_id=run_id,
            account=account,
            opts=opts,
            job_id=job_id,
            activity=activity,
            flush_progress=_flush_progress,
        )

    if stage == "comments":
        target_source_ids = _target_source_ids_for_platform(opts, "youtube")
        existing_posts = _load_existing_posts(
            "youtube",
            context,
            account,
            opts.date_start,
            opts.date_end,
            source_ids=target_source_ids,
        )
        videos_scanned = len([row for row in existing_posts if str(row.get("video_id") or "").strip()])
        videos_matched_show_terms = videos_scanned
        logger.info("[youtube] Comments stage: %d existing videos from DB for account=%s", len(existing_posts), account)
        retrieval_meta["source"] = "db"
        snapshots = _load_comment_lifecycle_snapshots(
            [str(r["id"]) for r in existing_posts if r.get("id")],
            platform="youtube",
        )
        skipped_synced = 0
        with pg.db_connection() as comments_conn:
            for video_index, row in enumerate(existing_posts, start=1):
                vid_id = str(row.get("video_id") or "")
                post_db_id = str(row.get("id") or "")
                if not vid_id:
                    continue
                snapshot = snapshots.get(post_db_id)
                expected = _expected_comment_count_for_platform("youtube", row, snapshot=snapshot)
                decision = _decide_comment_refresh(
                    sync_strategy=opts.sync_strategy,
                    expected_count=expected,
                    snapshot=snapshot,
                    post_published_at=_coerce_dt(row.get("published_at")),
                    refresh_policy=opts.comment_refresh_policy,
                )
                if opts.youtube_force_comment_refresh:
                    decision = CommentRefreshDecision(should_refresh=True, reason="youtube_force_comment_refresh")
                comment_refresh_reasons[decision.reason] += 1
                if not decision.should_refresh:
                    skipped_synced += 1
                    videos_skipped_up_to_date += 1
                    _record_filter_sample(
                        reason="up_to_date",
                        title=str(row.get("text") or ""),
                        video_id=vid_id,
                    )
                    continue
                matched_video_count += 1
                scraped_video_count += 1
                youtube_comment_count_sync_targets.add(post_db_id)
                activity["phase"] = "comments_fetch"
                activity["posts_checked"] = scraped_video_count
                activity["matched_posts"] = matched_video_count
                if matched_video_count % 10 == 0:
                    _touch_job_heartbeat(job_id)
                _flush_progress()
                fetch_failed = False
                comments: list[Any] = []
                fail_reason = ""
                observed_comment_ids: set[str] = set()
                local_comment_stats = _new_comment_persist_stats()
                try:
                    comments = scraper.fetch_comments(
                        vid_id,
                        max_comments=opts.max_comments_per_post,
                        fetch_replies=opts.fetch_replies,
                        delay=0.5,
                    )
                    _trim_nested_comment_replies(comments, max_replies_per_post=_effective_reply_limit(opts))
                    fail_reason = str(getattr(scraper, "last_comment_fetch_reason", "") or "")
                    if fail_reason:
                        comment_fail_reasons.add(fail_reason)
                        if not comments:
                            comment_errors += 1
                except Exception:
                    fetch_failed = True
                    comment_errors += 1
                    comment_fail_reasons.add("fetch_exception")
                    logger.exception(
                        "[youtube] Failed to fetch comments for video %s (video_id=%s)",
                        post_db_id,
                        vid_id,
                    )

                if not fetch_failed:
                    try:
                        with _SavepointScope(conn=comments_conn, prefix="youtube_comments_stage", index=video_index):
                            for comment in comments:
                                _upsert_youtube_comment_tree(
                                    context,
                                    job_id=job_id,
                                    run_id=run_id,
                                    account=account,
                                    video_db_id=post_db_id,
                                    comment=comment,
                                    observed_comment_ids=observed_comment_ids,
                                    persist_stats=local_comment_stats,
                                    conn=comments_conn,
                                )

                            is_complete = _is_comment_fetch_complete(
                                fetch_failed=False,
                                fail_reason=fail_reason,
                                auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                                fetched_count=len(comments),
                                max_comments_per_post=opts.max_comments_per_post,
                                expected_count=expected,
                            )
                            if is_complete:
                                missing_marked += _mark_missing_comments_for_anchor(
                                    platform="youtube",
                                    anchor_id=post_db_id,
                                    observed_comment_ids=observed_comment_ids,
                                    conn=comments_conn,
                                )
                                _reconcile_post_comment_count(
                                    platform="youtube",
                                    post_db_id=post_db_id,
                                    conn=comments_conn,
                                )
                            else:
                                incomplete_comment_fetches += 1
                                comments_mark_missing_skipped += 1
                    except Exception:
                        fetch_failed = True
                        comment_errors += 1
                        comment_fail_reasons.add("persist_exception")
                        logger.exception(
                            "[youtube] Failed to persist comments for video %s (video_id=%s)",
                            post_db_id,
                            vid_id,
                        )

                if fetch_failed:
                    incomplete_comment_fetches += 1
                    comments_mark_missing_skipped += 1
                    continue

                newest_comment_id, newest_comment_published_at, reply_checkpoint = (
                    _youtube_comment_checkpoint_from_comments(comments)
                )
                try:
                    _save_youtube_video_sync_state(
                        context,
                        post_id=post_db_id,
                        video_id=vid_id,
                        source_scope=opts.source_scope,
                        source_account=account,
                        last_seen_at=_now_utc(),
                        last_discovery_source="db",
                        last_comments_checked_at=_now_utc(),
                        newest_comment_external_id=newest_comment_id,
                        newest_comment_published_at=newest_comment_published_at,
                        reply_checkpoint=reply_checkpoint,
                        diagnostics={
                            "stage": "comments",
                            "comments_fetched": len(comments),
                            "force_comment_refresh": bool(opts.youtube_force_comment_refresh),
                        },
                        conn=comments_conn,
                    )
                except Exception:
                    logger.exception(
                        "[youtube] Failed to persist video sync state for video %s (video_id=%s)",
                        post_db_id,
                        vid_id,
                    )

                _merge_comment_persist_stats(comment_stats, local_comment_stats)
                scraped_comment_count = int(comment_stats.get("comments_fetched") or 0)
                _flush_progress()

        if youtube_comment_count_sync_targets:
            with pg.db_connection() as conn:
                youtube_comment_count_synced += _sync_youtube_video_comment_counts(
                    list(youtube_comment_count_sync_targets),
                    conn=conn,
                )
        if skipped_synced:
            logger.info("[youtube] Skipped %d videos whose comments are already synced", skipped_synced)
    else:

        def _youtube_video_surface(video_obj: Any) -> str:
            source_surface = str(getattr(video_obj, "source_surface", "") or "").strip().lower()
            if source_surface in {"videos", "shorts"}:
                return source_surface
            if bool(getattr(video_obj, "is_short", False)):
                return "shorts"
            video_url = str(getattr(video_obj, "url", "") or "").lower()
            return "shorts" if "/shorts/" in video_url else "videos"

        config = YouTubeScrapeConfig(
            channel_handle=account,
            keywords=keywords,
            date_start=opts.date_start,
            date_end=opts.date_end,
            delay_seconds=_resolve_platform_delay_seconds(
                platform="youtube",
                attempt_count=int((job_config or {}).get("_attempt_count") or 1),
                last_error_code=(job_config or {}).get("_last_error_code"),
                default=0.35,
            ),
            max_results=None if opts.max_posts_per_target <= 0 else max(1, opts.max_posts_per_target),
            enforce_keyword_filter=False,
            show_id=cast(Any, context.show_id),
            season_number=context.season_number,
        )
        effective_date_start = opts.date_start
        if (
            opts.sync_strategy == "incremental"
            and not opts.youtube_force_reindex
            and effective_date_start is not None
            and checkpoint_last_published_at is not None
            and checkpoint_last_published_at > effective_date_start
        ):
            effective_date_start = checkpoint_last_published_at
            checkpoint_reused = True
        window_page_cap = _resolve_youtube_narrow_window_page_cap(
            date_start=effective_date_start,
            date_end=opts.date_end,
        )
        if window_page_cap is not None:
            config.max_pages = window_page_cap
            retrieval_meta["narrow_window_page_cap"] = window_page_cap
        logger.info(
            "[youtube] Scraping channel=%s keywords=%s date_range=%s..%s",
            account,
            keywords,
            effective_date_start,
            opts.date_end,
        )
        post_limit = opts.max_posts_per_target if opts.max_posts_per_target > 0 else None
        existing_post_lookup: dict[str, dict[str, Any]] = {}
        snapshots: dict[str, CommentLifecycleSnapshot] = {}
        if opts.sync_strategy == "incremental":
            existing_rows = _load_existing_posts("youtube", context, account, effective_date_start, opts.date_end)
            if existing_rows:
                existing_post_lookup = _build_existing_post_lookup("youtube", existing_rows)
                if opts.max_comments_per_post > 0:
                    snapshots = _load_comment_lifecycle_snapshots(
                        [str(row.get("id")) for row in existing_post_lookup.values() if row.get("id")],
                        platform="youtube",
                    )
        if (
            opts.sync_strategy == "incremental"
            and post_limit is None
            and effective_date_start is not None
            and opts.date_end is not None
            and existing_post_lookup
        ):
            effective_date_start_value = cast(datetime, _coerce_dt(effective_date_start))
            date_end_value = cast(datetime, _coerce_dt(opts.date_end))
            window_days = max(
                1,
                int((date_end_value - effective_date_start_value).total_seconds() // 86400) + 1,
            )
            default_page_cap = 6 if window_days <= 45 else 10
            existing_window_page_cap = _resolve_positive_int_env(
                "SOCIAL_YOUTUBE_INCREMENTAL_EXISTING_WINDOW_MAX_PAGES",
                default_page_cap,
                minimum=1,
            )
            config.max_pages = min(config.max_pages or existing_window_page_cap, existing_window_page_cap)
            retrieval_meta["incremental_existing_window_page_cap"] = config.max_pages
            retrieval_meta["incremental_existing_window_videos"] = len(existing_post_lookup)

        def _on_scrape_progress(payload: dict[str, Any]) -> None:
            nonlocal scraped_video_count
            activity["phase"] = str(payload.get("phase") or "scrape_posts")
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
            matched_posts = payload.get("matched_posts")
            if matched_posts is not None:
                activity["matched_posts"] = _normalize_non_negative_int(matched_posts)
            else:
                activity["matched_posts"] = _normalize_non_negative_int(payload.get("posts_checked"))
            scraped_video_count = max(scraped_video_count, _normalize_non_negative_int(activity.get("matched_posts")))
            _flush_progress()

        api_videos: list[Any] = []
        api_next_page_token: str | None = saved_next_page_token
        if youtube_api.enabled() and youtube_source_mode in {"hybrid", "api_only"}:
            try:
                api_payload = youtube_api.list_channel_videos(
                    handle=account,
                    page_token=None if opts.youtube_force_reindex else saved_next_page_token,
                    published_after=effective_date_start,
                    published_before=opts.date_end,
                    max_pages=config.max_pages or 4,
                )
                api_calls += int(api_payload.get("api_calls") or 0)
                api_next_page_token = str(api_payload.get("next_page_token") or "").strip() or None
                api_channel = _as_string_mapping(api_payload.get("channel"))
                if not canonical_channel_id:
                    canonical_channel_id = str(api_channel.get("channel_id") or "").strip() or canonical_channel_id
                if api_channel and not canonical_owner_handle:
                    canonical_owner_handle = _normalize_account_handle(api_channel.get("canonical_handle")) or account
                for item in api_payload.get("items") or []:
                    if not isinstance(item, dict):
                        continue
                    built_video = _build_youtube_video_from_api_item(
                        item,
                        account=account,
                        fallback_channel_title=str(api_channel.get("title") or "").strip() or None,
                    )
                    if built_video is not None:
                        api_videos.append(built_video)
                api_candidate_videos = len(api_videos)
                if api_videos:
                    discovery_source = "api"
            except Exception:
                logger.exception("[youtube] API discovery failed for @%s", account)
                retrieval_meta["youtube_api_error"] = "discovery_failed"
                if youtube_source_mode == "api_only":
                    discovery_source = "api_only_failed"

        scraper_videos: list[Any] = []
        should_scrape = youtube_source_mode == "scraper_only"
        if youtube_source_mode == "hybrid":
            api_surfaces = {_youtube_video_surface(video) for video in api_videos}
            should_scrape = not api_videos or {"videos", "shorts"} - api_surfaces != set()
        if should_scrape:
            scraper_videos = scraper.scrape(config, progress_cb=_on_scrape_progress)
            retrieval_meta.update(dict(getattr(scraper, "last_retrieval_meta", {}) or {}))
            shorts_undated_skipped += int(retrieval_meta.get("shorts_undated_skipped") or 0)
            if api_videos:
                discovery_source = "hybrid"
            else:
                discovery_source = "scraper"

        videos = _merge_youtube_video_candidates(api_videos, scraper_videos)
        saved_next_page_token = api_next_page_token
        if opts.sync_strategy == "incremental" and videos:
            candidate_video_ids = sorted(
                {
                    str(getattr(video, "video_id", "") or "").strip()
                    for video in videos
                    if str(getattr(video, "video_id", "") or "").strip()
                }
            )
            if candidate_video_ids:
                repair_rows = _load_existing_posts(
                    "youtube",
                    context,
                    account,
                    None,
                    opts.date_end,
                    source_ids=set(candidate_video_ids),
                )
                if repair_rows:
                    existing_post_lookup.update(_build_existing_post_lookup("youtube", repair_rows))
        candidate_surfaces_available = {
            _youtube_video_surface(video) for video in videos if _youtube_video_surface(video) in {"videos", "shorts"}
        }
        require_both_surfaces = {"videos", "shorts"} <= candidate_surfaces_available
        matched_surfaces_persisted: set[str] = set()
        surface_cap_override_applied = False
        if videos:
            published_candidates = [
                published_at
                for video in videos
                if (published_at := _coerce_dt(getattr(video, "published_at", None))) is not None
            ]
            if published_candidates:
                checkpoint_last_published_at = max(published_candidates)
        _save_youtube_channel_sync_state(
            context,
            source_scope=opts.source_scope,
            account_handle=account,
            youtube_source_mode=youtube_source_mode,
            channel_id=canonical_channel_id,
            last_discovery_source=discovery_source,
            last_page_token=api_next_page_token,
            last_cursor_published_at=checkpoint_last_published_at,
            last_discovery_started_at=discovery_started_at,
            last_discovery_completed_at=_now_utc(),
            last_stats_refresh_at=_now_utc() if api_videos else None,
            diagnostics={
                "api_calls": api_calls,
                "api_candidate_videos": api_candidate_videos,
                "scraper_candidate_videos": len(scraper_videos),
                "merged_candidate_videos": len(videos),
                "checkpoint_reused": checkpoint_reused,
            },
        )

        skipped_synced = 0
        with pg.db_connection() as post_comments_conn:
            for video_index, video in enumerate(videos, start=1):
                total_scraped += 1
                videos_scanned += 1
                scraped_video_count = max(scraped_video_count, total_scraped)
                activity["phase"] = "posts_filter"
                activity["posts_checked"] = scraped_video_count
                video_title = str(getattr(video, "title", "") or "")
                video_id = str(getattr(video, "video_id", "") or "")
                if not _youtube_video_matches_show_terms(
                    title=video_title,
                    description=getattr(video, "description", ""),
                    tags=getattr(video, "tags", []),
                    hashtags=hashtags,
                    keywords=keywords,
                ):
                    skipped_keyword += 1
                    videos_filtered_show_terms += 1
                    _record_filter_sample(reason="show_terms_filtered", title=video_title, video_id=video_id)
                    _flush_progress()
                    continue
                if not _youtube_video_matches_owner_identity(
                    video,
                    expected_handle=canonical_owner_handle or account,
                    expected_channel_id=canonical_channel_id,
                ):
                    videos_filtered_owner += 1
                    _record_filter_sample(reason="ownership_filtered", title=video_title, video_id=video_id)
                    _flush_progress()
                    continue
                videos_matched_show_terms += 1
                if post_limit and matched_video_count >= post_limit:
                    if require_both_surfaces and {"videos", "shorts"} - matched_surfaces_persisted:
                        surface_cap_override_applied = True
                    else:
                        break

                existing_row = existing_post_lookup.get(video_id)
                if (
                    _youtube_video_surface(video) == "shorts"
                    and existing_row
                    and _youtube_epochish_published_at(existing_row.get("published_at"))
                    and not _youtube_epochish_published_at(getattr(video, "published_at", None))
                ):
                    shorts_epoch_rows_repaired += 1
                if existing_row and opts.max_comments_per_post > 0:
                    existing_post_id = str(existing_row.get("id") or "")
                    snapshot = snapshots.get(existing_post_id)
                    expected_comment_count = _expected_comment_count_for_platform(
                        "youtube",
                        {"comments_count": int(getattr(video, "comments", 0) or 0)},
                        snapshot=snapshot,
                    )
                    decision = _decide_comment_refresh(
                        sync_strategy=opts.sync_strategy,
                        expected_count=expected_comment_count,
                        snapshot=snapshot,
                        post_published_at=_coerce_dt(existing_row.get("published_at")),
                        refresh_policy=opts.comment_refresh_policy,
                    )
                    if opts.youtube_force_comment_refresh:
                        decision = CommentRefreshDecision(should_refresh=True, reason="youtube_force_comment_refresh")
                    comment_refresh_reasons[decision.reason] += 1
                    if not decision.should_refresh:
                        skipped_synced += 1
                        videos_skipped_up_to_date += 1
                        _record_filter_sample(reason="up_to_date", title=video_title, video_id=video_id)
                        activity["phase"] = "posts_skip_up_to_date"
                        _flush_progress()
                        continue

                existing_sync_state = _load_youtube_video_sync_state(video_id=video_id)
                existing_source_media = _as_text_list((existing_row or {}).get("media_urls"))
                existing_thumbnail_url = str((existing_row or {}).get("thumbnail_url") or "").strip() or None
                needs_media_resolution = bool(opts.youtube_force_media_refresh)
                if not needs_media_resolution:
                    needs_media_resolution = not existing_source_media or not existing_thumbnail_url
                if not needs_media_resolution:
                    needs_media_resolution = not str(getattr(video, "thumbnail_url", "") or "").strip()
                if not needs_media_resolution and existing_sync_state:
                    media_status = str((existing_sync_state or {}).get("media_resolution_status") or "").strip().lower()
                    needs_media_resolution = media_status in {"missing_media", "missing_thumbnail", "failed", "partial"}
                media_resolution_payload: dict[str, Any] | None = None
                if needs_media_resolution and video_id:
                    try:
                        media_resolution_payload = _resolve_youtube_media_for_video_id(video_id=video_id)
                        resolution_source = (
                            str((media_resolution_payload or {}).get("source") or "").strip() or "unknown"
                        )
                        media_resolution_sources_used[resolution_source] += 1
                        media_resolution_fallback_counts[resolution_source] += 1
                    except Exception:
                        logger.exception("[youtube] Media resolution failed for video_id=%s", video_id)
                        media_resolution_payload = {
                            "source": "resolve_exception",
                            "media_urls": [],
                            "thumbnail_url": str(getattr(video, "thumbnail_url", "") or "").strip() or None,
                            "attempts": [],
                            "media_asset_meta": {},
                        }
                resolved_media_urls = _normalize_unique_terms(
                    [
                        *existing_source_media,
                        *[
                            str(url).strip()
                            for url in ((media_resolution_payload or {}).get("media_urls") or [])
                            if str(url).strip()
                        ],
                    ]
                )
                resolved_thumbnail_url = (
                    str((media_resolution_payload or {}).get("thumbnail_url") or "").strip()
                    or str(getattr(video, "thumbnail_url", "") or "").strip()
                    or existing_thumbnail_url
                    or None
                )
                if resolved_thumbnail_url:
                    video.thumbnail_url = resolved_thumbnail_url
                if resolved_media_urls:
                    video.media_urls = resolved_media_urls
                    if _youtube_probable_short(
                        duration_seconds=int(getattr(video, "duration_seconds", 0) or 0),
                        url=str(getattr(video, "url", "") or ""),
                        title=str(getattr(video, "title", "") or ""),
                    ):
                        video.url = f"https://www.youtube.com/shorts/{video_id}"
                    elif not str(getattr(video, "url", "") or "").strip():
                        video.url = f"https://www.youtube.com/watch?v={video_id}"

                if _youtube_transcript_ingest_enabled() and _platform_posts_has_column("youtube", "transcript_text"):
                    try:
                        transcript_payload = scraper.fetch_transcript(video_id)
                    except Exception:  # noqa: BLE001
                        transcript_payload = {
                            "text": "",
                            "segments": [],
                            "language": None,
                            "source": None,
                            "error": "fetch_exception",
                        }
                    video.transcript_text = str(transcript_payload.get("text") or "").strip() or None
                    transcript_segments = transcript_payload.get("segments")
                    video.transcript_segments = transcript_segments if isinstance(transcript_segments, list) else []
                    video.transcript_language = transcript_payload.get("language")
                    video.transcript_source = transcript_payload.get("source")
                    video.transcript_error = transcript_payload.get("error")
                    video.transcript_synced_at = _now_utc()
                    if transcript_payload.get("error"):
                        transcript_failed += 1
                    else:
                        transcript_synced += 1

                upserted: dict[str, Any] | None = None
                try:
                    with pg.db_connection() as conn:
                        upserted = _upsert_youtube_video(
                            context, job_id=job_id, account=account, video=video, conn=conn
                        )
                        if upserted and (resolved_thumbnail_url or resolved_media_urls):
                            _update_youtube_post_source_media_fields(
                                post_id=str(upserted["id"]),
                                thumbnail_url=resolved_thumbnail_url if resolved_thumbnail_url else FIELD_UNSET,
                                media_urls=resolved_media_urls if resolved_media_urls else FIELD_UNSET,
                                conn=conn,
                            )
                            if media_resolution_payload and media_resolution_payload.get("media_asset_meta"):
                                _update_platform_post_media_asset_meta(
                                    platform="youtube",
                                    post_id=str(upserted["id"]),
                                    media_asset_meta=dict(media_resolution_payload.get("media_asset_meta") or {}),
                                    conn=conn,
                                )
                except Exception:
                    comment_errors += 1
                    comment_fail_reasons.add("persist_exception")
                    logger.exception(
                        "[youtube] Failed to upsert video video_id=%s",
                        getattr(video, "video_id", "?"),
                    )
                    _flush_progress()
                    continue

                if not upserted:
                    _flush_progress()
                    continue
                if not resolved_media_urls:
                    rows_missing_media += 1
                    media_completion_failures += 1
                if not resolved_thumbnail_url:
                    rows_missing_thumbnails += 1
                    media_completion_failures += 1
                matched_video_count += 1
                if _youtube_video_surface(video) == "shorts":
                    matched_shorts += 1
                else:
                    matched_videos += 1
                matched_surfaces_persisted.add(_youtube_video_surface(video))
                activity["phase"] = "posts_upsert"
                activity["matched_posts"] = matched_video_count
                youtube_comment_count_sync_targets.add(str(upserted["id"]))
                upserted_for_mirror = dict(upserted)
                if resolved_thumbnail_url:
                    upserted_for_mirror["thumbnail_url"] = resolved_thumbnail_url
                if resolved_media_urls:
                    upserted_for_mirror["media_urls"] = list(resolved_media_urls)
                _save_youtube_video_sync_state(
                    context,
                    post_id=str(upserted["id"]),
                    video_id=video_id,
                    source_scope=opts.source_scope,
                    source_account=account,
                    last_seen_at=_now_utc(),
                    last_discovery_source=discovery_source,
                    last_stats_checked_at=_now_utc(),
                    media_resolution_status=(
                        "ok"
                        if resolved_media_urls and resolved_thumbnail_url
                        else "missing_thumbnail"
                        if resolved_media_urls and not resolved_thumbnail_url
                        else "missing_media"
                    ),
                    media_resolution_source=str((media_resolution_payload or {}).get("source") or "").strip() or None,
                    media_resolved_at=_now_utc() if media_resolution_payload else None,
                    media_resolution_attempts=list((media_resolution_payload or {}).get("attempts") or []),
                    diagnostics={
                        "stage": "posts",
                        "source_surface": _youtube_video_surface(video),
                        "is_short": bool(getattr(video, "is_short", False)),
                        "has_thumbnail": bool(resolved_thumbnail_url),
                        "media_url_count": len(resolved_media_urls),
                        "force_media_refresh": bool(opts.youtube_force_media_refresh),
                    },
                )
                _flush_progress()

                if stage == "posts":
                    try:
                        mirror_job_id = _enqueue_platform_media_mirror_job(
                            context,
                            platform="youtube",
                            run_id=run_id,
                            source_scope=opts.source_scope,
                            account=account,
                            post_row=upserted_for_mirror,
                            week_index=None,
                            parent_job_id=job_id,
                            conn=None,
                        )
                        if mirror_job_id:
                            mirror_jobs_enqueued += 1
                    except Exception:  # noqa: BLE001
                        mirror_job_enqueue_errors += 1
                        logger.exception(
                            "[youtube] Failed to enqueue media mirror job for video=%s video_id=%s",
                            str(upserted.get("id") or ""),
                            str(getattr(video, "video_id", "") or ""),
                        )

                if opts.max_comments_per_post > 0:
                    comments: list[Any] = []
                    fail_reason = ""
                    fetch_failed = False
                    observed_comment_ids: set[str] = set()
                    local_comment_stats = _new_comment_persist_stats()
                    try:
                        comments = scraper.fetch_comments(
                            getattr(video, "video_id", ""),
                            max_comments=opts.max_comments_per_post,
                            fetch_replies=opts.fetch_replies,
                            delay=0.5,
                        )
                        _trim_nested_comment_replies(comments, max_replies_per_post=_effective_reply_limit(opts))
                        fail_reason = str(getattr(scraper, "last_comment_fetch_reason", "") or "")
                        if fail_reason:
                            comment_fail_reasons.add(fail_reason)
                            if not comments:
                                comment_errors += 1
                    except Exception:
                        fetch_failed = True
                        comment_errors += 1
                        comment_fail_reasons.add("fetch_exception")
                        logger.exception(
                            "[youtube] Failed to fetch comments for video %s (video_id=%s)",
                            upserted.get("id"),
                            getattr(video, "video_id", "?"),
                        )
                        incomplete_comment_fetches += 1
                        comments_mark_missing_skipped += 1

                    if not fetch_failed:
                        try:
                            with _SavepointScope(
                                conn=post_comments_conn,
                                prefix="youtube_post_comments",
                                index=video_index,
                            ):
                                for comment in comments:
                                    _upsert_youtube_comment_tree(
                                        context,
                                        job_id=job_id,
                                        run_id=run_id,
                                        account=account,
                                        video_db_id=str(upserted["id"]),
                                        comment=comment,
                                        observed_comment_ids=observed_comment_ids,
                                        persist_stats=local_comment_stats,
                                        conn=post_comments_conn,
                                    )

                                is_complete = _is_comment_fetch_complete(
                                    fetch_failed=False,
                                    fail_reason=fail_reason,
                                    auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                                    fetched_count=len(comments),
                                    max_comments_per_post=opts.max_comments_per_post,
                                    expected_count=int(getattr(video, "comments", 0) or 0),
                                )
                                if is_complete:
                                    missing_marked += _mark_missing_comments_for_anchor(
                                        platform="youtube",
                                        anchor_id=str(upserted["id"]),
                                        observed_comment_ids=observed_comment_ids,
                                        conn=post_comments_conn,
                                    )
                                    _reconcile_post_comment_count(
                                        platform="youtube",
                                        post_db_id=str(upserted["id"]),
                                        conn=post_comments_conn,
                                    )
                                else:
                                    incomplete_comment_fetches += 1
                                    comments_mark_missing_skipped += 1
                        except Exception:
                            fetch_failed = True
                            comment_errors += 1
                            comment_fail_reasons.add("persist_exception")
                            logger.exception(
                                "[youtube] Failed to persist comments for video %s (video_id=%s)",
                                upserted.get("id"),
                                getattr(video, "video_id", "?"),
                            )
                            incomplete_comment_fetches += 1
                            comments_mark_missing_skipped += 1

                    if not fetch_failed:
                        newest_comment_id, newest_comment_published_at, reply_checkpoint = (
                            _youtube_comment_checkpoint_from_comments(comments)
                        )
                        _save_youtube_video_sync_state(
                            context,
                            post_id=str(upserted["id"]),
                            video_id=video_id,
                            source_scope=opts.source_scope,
                            source_account=account,
                            last_seen_at=_now_utc(),
                            last_discovery_source=discovery_source,
                            last_comments_checked_at=_now_utc(),
                            newest_comment_external_id=newest_comment_id,
                            newest_comment_published_at=newest_comment_published_at,
                            reply_checkpoint=reply_checkpoint,
                            diagnostics={
                                "stage": "posts_comments",
                                "comments_fetched": len(comments),
                                "source_surface": _youtube_video_surface(video),
                            },
                            conn=post_comments_conn,
                        )
                        _merge_comment_persist_stats(comment_stats, local_comment_stats)
                        scraped_comment_count = int(comment_stats.get("comments_fetched") or 0)
                        activity["phase"] = "comments_fetch"
                        _flush_progress()

        if post_limit and matched_video_count > post_limit:
            surface_cap_override_applied = True
        retrieval_meta["surface_candidate_presence"] = sorted(candidate_surfaces_available)
        retrieval_meta["surface_match_presence"] = sorted(matched_surfaces_persisted)
        retrieval_meta["surface_cap_override_applied"] = bool(
            retrieval_meta.get("surface_cap_override_applied") or surface_cap_override_applied
        )
        retrieval_meta["surface_cap_target_dual"] = bool(require_both_surfaces)

        if youtube_comment_count_sync_targets:
            with pg.db_connection() as conn:
                youtube_comment_count_synced += _sync_youtube_video_comment_counts(
                    list(youtube_comment_count_sync_targets),
                    conn=conn,
                )

    activity["phase"] = f"{stage}_end"
    activity["matched_posts"] = matched_video_count
    _flush_progress(force=True)

    if skipped_synced:
        logger.info("[youtube] Skipped %d videos already up-to-date", skipped_synced)
    if comment_errors:
        retrieval_meta["comment_errors"] = comment_errors
    if comment_fail_reasons:
        retrieval_meta["comment_fail_reasons"] = sorted(comment_fail_reasons)
    if comment_refresh_reasons:
        retrieval_meta["comment_refresh_decisions"] = dict(comment_refresh_reasons)
    if missing_marked:
        retrieval_meta["comments_marked_missing"] = missing_marked
    if incomplete_comment_fetches:
        retrieval_meta["incomplete_comment_fetches"] = incomplete_comment_fetches
    if comments_mark_missing_skipped:
        retrieval_meta["comments_mark_missing_skipped"] = comments_mark_missing_skipped
    if mirror_jobs_enqueued:
        retrieval_meta["media_mirror_jobs_enqueued"] = mirror_jobs_enqueued
    if mirror_job_enqueue_errors:
        retrieval_meta["media_mirror_job_enqueue_errors"] = mirror_job_enqueue_errors
    retrieval_meta["discovery_source"] = discovery_source
    retrieval_meta["youtube_source_mode"] = youtube_source_mode
    retrieval_meta["api_calls"] = api_calls
    retrieval_meta["api_candidate_videos"] = api_candidate_videos
    retrieval_meta["matched_videos"] = matched_videos
    retrieval_meta["matched_shorts"] = matched_shorts
    retrieval_meta["shorts_epoch_rows_repaired"] = shorts_epoch_rows_repaired
    retrieval_meta["shorts_undated_skipped"] = shorts_undated_skipped
    retrieval_meta["rows_missing_media"] = rows_missing_media
    retrieval_meta["rows_missing_thumbnails"] = rows_missing_thumbnails
    retrieval_meta["media_completion_failures"] = media_completion_failures
    retrieval_meta["media_resolution_fallback_counts"] = dict(media_resolution_fallback_counts)
    retrieval_meta["media_resolution_sources_used"] = dict(media_resolution_sources_used)
    retrieval_meta["checkpoint_reused"] = checkpoint_reused
    retrieval_meta["checkpoint_last_published_at"] = _iso(checkpoint_last_published_at)
    retrieval_meta["videos_scanned"] = videos_scanned
    retrieval_meta["videos_matched_show_terms"] = videos_matched_show_terms
    retrieval_meta["videos_filtered_show_terms"] = videos_filtered_show_terms
    retrieval_meta["videos_filtered_owner"] = videos_filtered_owner
    retrieval_meta["videos_skipped_up_to_date"] = videos_skipped_up_to_date
    if _youtube_transcript_ingest_enabled() and _platform_posts_has_column("youtube", "transcript_text"):
        retrieval_meta["transcripts_synced"] = transcript_synced
        retrieval_meta["transcripts_failed"] = transcript_failed
    retrieval_meta["canonical_owner_handle"] = canonical_owner_handle or account
    retrieval_meta["canonical_channel_id"] = canonical_channel_id
    retrieval_meta["ownership_cleanup"] = cleanup_summary
    retrieval_meta["youtube_comment_count_sync_targets"] = len(youtube_comment_count_sync_targets)
    retrieval_meta["youtube_comment_count_synced"] = youtube_comment_count_synced
    retrieval_meta["filter_samples"] = filter_samples
    retrieval_meta["comment_stats"] = _comment_stats_payload(comment_stats)
    retrieval_meta["scrape_counters"] = {"posts": scraped_video_count, "comments": scraped_comment_count}
    retrieval_meta["persist_counters"] = {
        "posts_upserted": matched_video_count,
        "comments_upserted": int(comment_stats.get("comments_upserted") or 0),
    }
    retrieval_meta["activity"] = _build_progress_activity_payload(activity, now=_now_utc())
    if stage != "comments":
        _save_youtube_channel_sync_state(
            context,
            source_scope=opts.source_scope,
            account_handle=account,
            youtube_source_mode=youtube_source_mode,
            channel_id=canonical_channel_id,
            last_discovery_source=discovery_source,
            last_page_token=saved_next_page_token,
            last_cursor_published_at=checkpoint_last_published_at,
            last_discovery_started_at=discovery_started_at,
            last_discovery_completed_at=_now_utc(),
            last_stats_refresh_at=_now_utc() if api_calls else None,
            last_failure_reason="media_incomplete" if media_completion_failures else None,
            diagnostics={
                "retrieval_meta": {
                    "api_calls": api_calls,
                    "matched_videos": matched_videos,
                    "matched_shorts": matched_shorts,
                    "rows_missing_media": rows_missing_media,
                    "rows_missing_thumbnails": rows_missing_thumbnails,
                }
            },
        )
    logger.info(
        "[youtube] Done: scraped=%d matched=%d skipped_keyword=%d comments=%d comment_errors=%d",
        total_scraped,
        matched_video_count,
        skipped_keyword,
        scraped_comment_count,
        comment_errors,
    )
    retrieval_meta = _merge_source_runtime(retrieval_meta, scraper)
    return scraped_video_count, scraped_comment_count, retrieval_meta


def _upsert_tweet(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    tweet: Any,
    persist_stats: dict[str, int] | None = None,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1

    prepared = _build_twitter_tweet_payload(
        context=context,
        job_id=job_id,
        run_id=run_id,
        account=account,
        tweet=tweet,
    )
    if prepared is None:
        if persist_stats is not None:
            persist_stats["comments_skipped_missing_id"] = (
                int(persist_stats.get("comments_skipped_missing_id") or 0) + 1
            )
        return None

    _tweet_id, payload = prepared
    row = _pg_upsert("twitter_tweets", payload, conflict_col="tweet_id", conn=conn, include_inserted_flag=True)
    if persist_stats is not None and row:
        persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + 1
    return row


def _twitter_context_role_for_tweet(*, account: str, tweet: Any) -> str | None:
    if bool(getattr(tweet, "is_quote", False)):
        return "quote"
    normalized_account = _normalize_account_handle(account)
    normalized_username = _normalize_account_handle(getattr(tweet, "username", ""))
    is_reply = bool(getattr(tweet, "is_reply", False))
    if is_reply and normalized_account and normalized_username == normalized_account:
        return "account_reply"
    if is_reply:
        return "audience_reply"
    if normalized_account and normalized_username == normalized_account:
        return "account_post"
    return None


def _build_twitter_tweet_payload(
    *,
    context: SeasonContext | None,
    job_id: str | None,
    run_id: str | None,
    account: str,
    tweet: Any,
) -> tuple[str, dict[str, Any]] | None:
    tweet_id = str(getattr(tweet, "tweet_id", "") or "").strip()
    if not tweet_id:
        return None

    created_at = _parse_platform_time(getattr(tweet, "created_at", None))
    username = str(getattr(tweet, "username", "") or "").strip()
    user_profile_url = str(getattr(tweet, "user_profile_url", "") or "").strip()
    if not user_profile_url and username:
        user_profile_url = f"https://x.com/{username}"
    retweets = int(getattr(tweet, "retweets", 0) or 0)
    reply_to_tweet_id = getattr(tweet, "reply_to_tweet_id", None)
    thread_root_tweet_id = str(getattr(tweet, "thread_root_tweet_id", "") or "").strip() or (
        str(reply_to_tweet_id or "").strip() if bool(getattr(tweet, "is_reply", False)) else tweet_id
    )
    thread_position = getattr(tweet, "thread_position", None)
    if thread_position is None and thread_root_tweet_id == tweet_id:
        thread_position = 0
    elif thread_position is not None:
        try:
            thread_position = int(thread_position)
        except (TypeError, ValueError):
            thread_position = None
    now = _now_utc()
    payload = {
        "tweet_id": tweet_id,
        "username": username,
        "display_name": getattr(tweet, "display_name", None),
        "user_verified": bool(getattr(tweet, "user_verified", False)),
        "text": getattr(tweet, "text", ""),
        "hashtags": getattr(tweet, "hashtags", []) or [],
        "mentions": getattr(tweet, "mentions", []) or [],
        "media_urls": getattr(tweet, "media_urls", []) or [],
        "likes": int(getattr(tweet, "likes", 0) or 0),
        "retweets": retweets,
        "replies_count": int(getattr(tweet, "replies", 0) or 0),
        "quotes": int(getattr(tweet, "quotes", 0) or 0),
        "views": int(getattr(tweet, "views", 0) or 0),
        "is_reply": bool(getattr(tweet, "is_reply", False)),
        "is_retweet": bool(getattr(tweet, "is_retweet", False)),
        "is_quote": bool(getattr(tweet, "is_quote", False)),
        "reply_to_tweet_id": reply_to_tweet_id,
        "quoted_tweet_id": getattr(tweet, "quoted_tweet_id", None),
        "created_at": created_at,
        "scraped_at": now,
        "raw_data": tweet.to_dict() if hasattr(tweet, "to_dict") else {},
        "source_account": account,
    }
    _apply_assignment_payload(payload, context)
    if _platform_posts_has_column("twitter", "user_id"):
        payload["user_id"] = str(getattr(tweet, "user_id", "") or "").strip() or None
    if _platform_posts_has_column("twitter", "user_profile_url"):
        payload["user_profile_url"] = user_profile_url or None
    if _platform_posts_has_column("twitter", "user_avatar_url"):
        payload["user_avatar_url"] = str(getattr(tweet, "user_avatar_url", "") or "").strip() or None
    if _platform_posts_has_column("twitter", "hosted_media_urls"):
        payload["hosted_media_urls"] = [
            str(url).strip() for url in (getattr(tweet, "hosted_media_urls", []) or []) if str(url).strip()
        ]
    if _platform_posts_has_column("twitter", "bookmarks"):
        payload["bookmarks"] = int(getattr(tweet, "bookmarks", 0) or 0)
    if _platform_posts_has_column("twitter", "shares"):
        payload["shares"] = int(getattr(tweet, "shares", 0) or 0) or retweets
    if _platform_posts_has_column("twitter", "thread_root_tweet_id"):
        payload["thread_root_tweet_id"] = thread_root_tweet_id or None
    if _platform_posts_has_column("twitter", "thread_position"):
        payload["thread_position"] = thread_position
    if _platform_posts_has_column("twitter", "is_thread_part"):
        payload["is_thread_part"] = bool(
            getattr(tweet, "is_thread_part", False)
            or (thread_root_tweet_id and thread_root_tweet_id != tweet_id)
            or bool(getattr(tweet, "is_reply", False))
        )
    if _platform_posts_has_column("twitter", "twitter_context_role"):
        payload["twitter_context_role"] = str(
            getattr(tweet, "twitter_context_role", "") or ""
        ).strip() or _twitter_context_role_for_tweet(account=account, tweet=tweet)
    if job_id:
        payload["job_id"] = job_id
    if _comment_lifecycle_supported("twitter_tweets"):
        payload["is_missing"] = False
        payload["missing_at"] = None
        payload["last_seen_at"] = now
        if run_id is not None:
            payload["last_seen_run_id"] = run_id
    return tweet_id, payload


def _upsert_tweet_batch(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    tweets: list[Any],
    persist_stats: dict[str, int] | None = None,
    conn: Any | None = None,
    batch_size: int | None = None,
) -> dict[str, dict[str, Any]]:
    if not tweets:
        return {}
    if conn is None:
        persisted_by_tweet_id: dict[str, dict[str, Any]] = {}
        for tweet in tweets:
            tweet_id = str(getattr(tweet, "tweet_id", "") or "").strip()
            row = _upsert_tweet(
                context,
                job_id=job_id,
                run_id=run_id,
                account=account,
                tweet=tweet,
                persist_stats=persist_stats,
                conn=conn,
            )
            if row and tweet_id:
                persisted_by_tweet_id[tweet_id] = row
        return persisted_by_tweet_id

    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + len(tweets)

    payload_by_tweet_id: dict[str, dict[str, Any]] = {}
    ordered_tweet_ids: list[str] = []
    for tweet in tweets:
        prepared = _build_twitter_tweet_payload(
            context=context,
            job_id=job_id,
            run_id=run_id,
            account=account,
            tweet=tweet,
        )
        if prepared is None:
            if persist_stats is not None:
                persist_stats["comments_skipped_missing_id"] = (
                    int(persist_stats.get("comments_skipped_missing_id") or 0) + 1
                )
            continue
        tweet_id, payload = prepared
        if tweet_id not in payload_by_tweet_id:
            ordered_tweet_ids.append(tweet_id)
        payload_by_tweet_id[tweet_id] = payload

    if not ordered_tweet_ids:
        return {}

    safe_batch_size = max(1, int(batch_size or _resolve_comment_upsert_batch_size()))
    persisted_by_tweet_id: dict[str, dict[str, Any]] = {}
    payload_items = [payload_by_tweet_id[tweet_id] for tweet_id in ordered_tweet_ids]
    for offset in range(0, len(payload_items), safe_batch_size):
        chunk = payload_items[offset : offset + safe_batch_size]
        rows = _pg_upsert_many("twitter_tweets", chunk, conflict_col="tweet_id", conn=conn)
        for row in rows:
            row_tweet_id = str(row.get("tweet_id") or "").strip()
            if row_tweet_id:
                persisted_by_tweet_id[row_tweet_id] = row
    if persist_stats is not None:
        persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + len(
            persisted_by_tweet_id
        )
    return persisted_by_tweet_id


def _ingest_twitter(
    context: SeasonContext,
    *,
    run_id: str | None,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    include_reply_records: bool = True,
    hydrate_audience_replies: bool = False,
    stage: str = "posts",
    job_config: dict[str, Any] | None = None,
) -> tuple[int, int, dict[str, Any]]:
    from trr_backend.socials.twitter import TwitterScrapeConfig, TwitterScraper

    date_start = opts.date_start or datetime.combine(context.anchor_date, time.min, tzinfo=UTC)
    date_end = opts.date_end or _now_utc()
    keyword_list = [kw for kw in keywords if isinstance(kw, str) and kw.strip()]
    hashtag_list = [tag for tag in hashtags if isinstance(tag, str) and tag.strip()]
    hashtag_list = _ensure_rhoslc_twitter_hashtags(context, hashtag_list)

    twitter_cookies, twitter_bearer = _load_twitter_auth()
    twikit_creds = _load_twikit_credentials()
    # If no explicit Twitter cookies but twikit has auth_token/ct0, use them
    # so GraphQL endpoints (including TweetDetail for replies) get authenticated access.
    if not twitter_cookies.get("ct0") and twikit_creds:
        if twikit_creds.get("auth_token") and twikit_creds.get("ct0"):
            twitter_cookies = {**twitter_cookies, "auth_token": twikit_creds["auth_token"], "ct0": twikit_creds["ct0"]}
            logger.info("[twitter] Using twikit auth_token/ct0 cookies for GraphQL requests")
    scraper = TwitterScraper(cookies=twitter_cookies, bearer_token=twitter_bearer, twikit_credentials=twikit_creds)

    retrieval_meta: dict[str, Any] = {}
    scraped_post_count = 0
    scraped_reply_count = 0
    upserted_post_count = 0
    skipped_keyword = 0
    hydrated_replies = 0
    hydrated_quotes = 0
    comment_errors = 0
    quote_errors = 0
    comment_fail_reasons: set[str] = set()
    quote_fail_reasons: set[str] = set()
    comment_refresh_reasons: Counter[str] = Counter()
    missing_marked = 0
    incomplete_comment_fetches = 0
    comments_mark_missing_skipped = 0
    quote_stats: dict[str, int] = {"quotes_fetched": 0, "quotes_upserted": 0}
    link_preview_media_hits = 0
    link_preview_media_misses = 0
    mirror_jobs_enqueued = 0
    mirror_job_enqueue_errors = 0
    strict_rhoslc_hashtag_mode = _show_is_rhoslc(context)
    comment_stats = _new_comment_persist_stats()
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": f"{stage}_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
    }

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=stage,
            platform="twitter",
            account=account,
            scraped_posts=scraped_post_count,
            scraped_comments=scraped_reply_count,
            posts_upserted=upserted_post_count,
            comments_upserted=int(comment_stats.get("comments_upserted") or 0),
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)

    if stage == "posts" and opts.ingest_mode == "details_refresh":
        return _run_existing_post_details_refresh(
            context,
            platform="twitter",
            run_id=run_id,
            account=account,
            opts=opts,
            job_id=job_id,
            activity=activity,
            flush_progress=_flush_progress,
        )

    if stage == "comments":
        # Comment-only stage: read existing tweets from DB and hydrate replies
        target_source_ids = _target_source_ids_for_platform(opts, "twitter")
        existing_posts = _load_existing_posts(
            "twitter",
            context,
            account,
            date_start,
            date_end,
            source_ids=target_source_ids,
        )
        # Filter to non-reply tweets only (anchor posts)
        anchor_rows = [r for r in existing_posts if not r.get("is_reply")]
        logger.info("[twitter] Comments stage: %d anchor tweets from DB for account=%s", len(anchor_rows), account)
        retrieval_meta["source"] = "db"
        per_post_limit = _effective_reply_limit(opts)
        snapshots = _load_comment_lifecycle_snapshots(
            [str(r["tweet_id"]) for r in anchor_rows if r.get("tweet_id")],
            platform="twitter",
        )
        skipped_synced = 0
        if per_post_limit > 0:
            anchor_rows_iter = (
                anchor_rows if opts.max_posts_per_target <= 0 else anchor_rows[: opts.max_posts_per_target]
            )
            with pg.db_connection() as comments_conn:
                for anchor_index, row in enumerate(anchor_rows_iter, start=1):
                    tweet_id = str(row.get("tweet_id") or "")
                    if not tweet_id:
                        continue
                    merged_summary = _fetch_and_apply_twitter_metric_summary(
                        scraper=scraper,
                        tweet_id=tweet_id,
                        conn=None,
                    )
                    expected_replies = max(
                        int(row.get("replies_count") or 0),
                        _normalize_non_negative_int((merged_summary or {}).get("replies")),
                    )
                    expected_quotes = max(
                        int(row.get("quotes") or 0),
                        _normalize_non_negative_int((merged_summary or {}).get("quotes")),
                    )
                    expected = expected_replies + expected_quotes
                    reply_pages, quote_pages = _twitter_reply_quote_page_budgets(
                        expected_replies=expected_replies,
                        expected_quotes=expected_quotes,
                    )
                    decision = _decide_comment_refresh(
                        sync_strategy=opts.sync_strategy,
                        expected_count=expected,
                        snapshot=snapshots.get(tweet_id),
                        post_published_at=_coerce_dt(row.get("created_at")),
                        refresh_policy=opts.comment_refresh_policy,
                    )
                    comment_refresh_reasons[decision.reason] += 1
                    if not decision.should_refresh:
                        skipped_synced += 1
                        continue
                    scraped_post_count += 1
                    activity["phase"] = "comments_fetch"
                    activity["posts_checked"] = scraped_post_count
                    activity["matched_posts"] = scraped_post_count
                    if scraped_post_count % 10 == 0:
                        _touch_job_heartbeat(job_id)
                    _flush_progress()
                    fetch_failed = False
                    quote_fetch_failed = False
                    replies: list[Any] = []
                    quotes: list[Any] = []
                    fail_reason = ""
                    quote_fail_reason = ""
                    observed_comment_ids: set[str] = set()
                    local_comment_stats = _new_comment_persist_stats()
                    try:
                        replies = _fetch_twitter_replies_compat(
                            scraper=scraper,
                            tweet_id=tweet_id,
                            delay=0.5,
                            search_max_pages=reply_pages,
                            twikit_max_pages=reply_pages,
                        )[:per_post_limit]
                        fail_reason = str(getattr(scraper, "last_reply_fetch_reason", "") or "")
                        if fail_reason:
                            comment_fail_reasons.add(fail_reason)
                            if not replies:
                                comment_errors += 1
                    except Exception:
                        fetch_failed = True
                        comment_errors += 1
                        comment_fail_reasons.add("fetch_exception")
                        logger.exception("[twitter] Failed to fetch replies for tweet %s", tweet_id)

                    try:
                        quotes, missing_quote_method_reason = _fetch_twitter_quotes_compat(
                            scraper=scraper,
                            tweet_id=tweet_id,
                            delay=0.5,
                            max_pages=quote_pages,
                        )
                        quotes = quotes[:per_post_limit]
                        quote_fail_reason = str(getattr(scraper, "last_quote_fetch_reason", "") or "")
                        if missing_quote_method_reason:
                            quote_fail_reason = missing_quote_method_reason
                        if quote_fail_reason:
                            quote_fail_reasons.add(quote_fail_reason)
                            if not quotes:
                                quote_errors += 1
                    except Exception:
                        quote_fetch_failed = True
                        quote_errors += 1
                        quote_fail_reasons.add("fetch_exception")
                        logger.exception("[twitter] Failed to fetch quotes for tweet %s", tweet_id)
                    quote_stats["quotes_fetched"] += len(quotes)

                    if not fetch_failed:
                        try:
                            with _SavepointScope(
                                conn=comments_conn,
                                prefix="twitter_comments_stage",
                                index=anchor_index,
                            ):
                                for reply in replies:
                                    if not getattr(reply, "reply_to_tweet_id", None):
                                        reply.reply_to_tweet_id = tweet_id
                                    reply.is_reply = True
                                    reply_id = str(getattr(reply, "tweet_id", "") or "")
                                    if reply_id:
                                        observed_comment_ids.add(reply_id)
                                persisted_replies = _upsert_tweet_batch(
                                    context,
                                    job_id=job_id,
                                    run_id=run_id,
                                    account=account,
                                    tweets=replies,
                                    persist_stats=local_comment_stats,
                                    conn=comments_conn,
                                )
                                for reply in replies:
                                    reply_id = str(getattr(reply, "tweet_id", "") or "")
                                    upserted_reply = persisted_replies.get(reply_id)
                                    if upserted_reply:
                                        hydrated_replies += 1
                                        try:
                                            mirror_job_id = _enqueue_twitter_comment_media_mirror_job(
                                                context,
                                                run_id=run_id,
                                                source_scope=opts.source_scope,
                                                account=account,
                                                comment_row=upserted_reply,
                                                parent_job_id=job_id,
                                                conn=comments_conn,
                                            )
                                            if mirror_job_id:
                                                local_comment_stats["comment_media_mirror_jobs_enqueued"] = (
                                                    int(
                                                        local_comment_stats.get("comment_media_mirror_jobs_enqueued")
                                                        or 0
                                                    )
                                                    + 1
                                                )
                                        except Exception:
                                            local_comment_stats["comment_media_mirror_job_enqueue_errors"] = (
                                                int(
                                                    local_comment_stats.get("comment_media_mirror_job_enqueue_errors")
                                                    or 0
                                                )
                                                + 1
                                            )
                                            logger.exception(
                                                "[twitter] Failed to enqueue comment media mirror for reply %s",
                                                reply_id,
                                            )

                                filtered_quotes: list[Any] = []
                                for quote in quotes:
                                    quote.is_reply = False
                                    quote.reply_to_tweet_id = None
                                    quote.is_quote = True
                                    if not getattr(quote, "quoted_tweet_id", None):
                                        quote.quoted_tweet_id = tweet_id
                                    if str(getattr(quote, "quoted_tweet_id", "") or "") != tweet_id:
                                        continue
                                    quote_id = str(getattr(quote, "tweet_id", "") or "")
                                    if quote_id:
                                        observed_comment_ids.add(quote_id)
                                    filtered_quotes.append(quote)
                                persisted_quotes = _upsert_tweet_batch(
                                    context,
                                    job_id=job_id,
                                    run_id=run_id,
                                    account=account,
                                    tweets=filtered_quotes,
                                    persist_stats=None,
                                    conn=comments_conn,
                                )
                                for quote in filtered_quotes:
                                    quote_id = str(getattr(quote, "tweet_id", "") or "")
                                    upserted_quote = persisted_quotes.get(quote_id)
                                    if upserted_quote:
                                        hydrated_quotes += 1
                                        quote_stats["quotes_upserted"] += 1
                                        try:
                                            mirror_job_id = _enqueue_twitter_comment_media_mirror_job(
                                                context,
                                                run_id=run_id,
                                                source_scope=opts.source_scope,
                                                account=account,
                                                comment_row=upserted_quote,
                                                parent_job_id=job_id,
                                                conn=comments_conn,
                                            )
                                            if mirror_job_id:
                                                local_comment_stats["comment_media_mirror_jobs_enqueued"] = (
                                                    int(
                                                        local_comment_stats.get("comment_media_mirror_jobs_enqueued")
                                                        or 0
                                                    )
                                                    + 1
                                                )
                                        except Exception:
                                            local_comment_stats["comment_media_mirror_job_enqueue_errors"] = (
                                                int(
                                                    local_comment_stats.get("comment_media_mirror_job_enqueue_errors")
                                                    or 0
                                                )
                                                + 1
                                            )
                                            logger.exception(
                                                "[twitter] Failed to enqueue comment media mirror for quote %s",
                                                quote_id,
                                            )

                                is_complete = _is_comment_fetch_complete(
                                    fetch_failed=False,
                                    fail_reason=fail_reason,
                                    quote_fail_reason=quote_fail_reason,
                                    auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                                    fetched_count=(len(replies) + len(quotes)),
                                    quotes_fetched=len(quotes),
                                    max_comments_per_post=per_post_limit,
                                    expected_count=expected,
                                    expected_quotes=expected_quotes,
                                )
                                if is_complete:
                                    missing_marked += _mark_missing_comments_for_anchor(
                                        platform="twitter",
                                        anchor_id=tweet_id,
                                        observed_comment_ids=observed_comment_ids,
                                        conn=comments_conn,
                                    )
                                    _reconcile_post_comment_count(
                                        platform="twitter",
                                        post_db_id=tweet_id,
                                        conn=comments_conn,
                                    )
                                else:
                                    incomplete_comment_fetches += 1
                                    comments_mark_missing_skipped += 1
                        except Exception:
                            fetch_failed = True
                            comment_errors += 1
                            comment_fail_reasons.add("persist_exception")
                            logger.exception("[twitter] Failed to persist replies for tweet %s", tweet_id)

                    if fetch_failed:
                        incomplete_comment_fetches += 1
                        comments_mark_missing_skipped += 1
                        continue

                    if quote_fetch_failed:
                        quote_fail_reason = "fetch_exception"
                        if quote_fail_reason:
                            quote_fail_reasons.add(quote_fail_reason)

                    _merge_comment_persist_stats(comment_stats, local_comment_stats)
                    scraped_reply_count = int(comment_stats.get("comments_fetched") or 0)
                    _flush_progress()
        scraped_reply_count = int(comment_stats.get("comments_fetched") or 0)
        if skipped_synced:
            logger.info("[twitter] Skipped %d tweets whose replies are already synced", skipped_synced)
    else:
        # Posts stage: scrape from live API
        term_query = _build_twitter_or_query(hashtags=hashtag_list, keywords=keyword_list)
        query = f"from:{account} {term_query}".strip() if term_query else f"from:{account}"
        config = TwitterScrapeConfig(
            query=query or account,
            date_start=date_start,
            date_end=date_end,
            include_replies=True,
            include_links=True,
            delay_seconds=_resolve_platform_delay_seconds(
                platform="twitter",
                attempt_count=int((job_config or {}).get("_attempt_count") or 1),
                last_error_code=(job_config or {}).get("_last_error_code"),
                default=0.35,
            ),
            max_pages=10,
            show_id=cast(Any, context.show_id),
            season_number=context.season_number,
        )
        logger.info("[twitter] Searching query=%r date_range=%s..%s", config.query, date_start, date_end)
        post_limit = opts.max_posts_per_target if opts.max_posts_per_target > 0 else None

        def _on_scrape_progress(payload: dict[str, Any]) -> None:
            nonlocal scraped_post_count
            activity["phase"] = str(payload.get("phase") or "scrape_posts")
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
            if payload.get("matched_posts") is not None:
                activity["matched_posts"] = _normalize_non_negative_int(payload.get("matched_posts"))
            scraped_post_count = max(scraped_post_count, _normalize_non_negative_int(payload.get("posts_checked")))
            _flush_progress()

        scraped_tweets = scraper.scrape(config, progress_cb=_on_scrape_progress)
        tweets = scraped_tweets if not post_limit else scraped_tweets[:post_limit]
        retrieval_meta.update(dict(getattr(scraper, "last_retrieval_meta", {}) or {}))
        logger.info("[twitter] Scraper returned %d tweets", len(tweets))

        existing_post_lookup: dict[str, dict[str, Any]] = {}
        snapshots: dict[str, CommentLifecycleSnapshot] = {}
        if opts.sync_strategy == "incremental" and opts.max_comments_per_post > 0:
            existing_rows = _load_existing_posts("twitter", context, account, date_start, date_end)
            existing_post_lookup = _build_existing_post_lookup("twitter", existing_rows)
            snapshots = _load_comment_lifecycle_snapshots(
                list(existing_post_lookup.keys()),
                platform="twitter",
            )

        skipped_synced = 0
        anchor_posts: list[Any] = []
        for tweet_index, tweet in enumerate(tweets, start=1):
            scraped_post_count = max(scraped_post_count, tweet_index)
            activity["phase"] = "posts_filter"
            activity["posts_checked"] = scraped_post_count
            text = str(getattr(tweet, "text", "") or "")
            post_hashtags = _as_text_list(getattr(tweet, "hashtags", []), strip_prefix="#")
            if not _twitter_post_matches_show_terms(
                context=context,
                text=text,
                post_hashtags=post_hashtags,
                hashtags=hashtag_list,
                keywords=keyword_list,
            ):
                skipped_keyword += 1
                _flush_progress()
                continue
            is_reply = bool(getattr(tweet, "is_reply", False))
            if not is_reply:
                merged_summary: dict[str, Any] | None = None
                tweet_source_id = str(getattr(tweet, "tweet_id", "") or "")
                try:
                    detail_summary = scraper.fetch_tweet_detail_summary(tweet_source_id, delay=0.0)
                except Exception:
                    detail_summary = None
                try:
                    public_summary = scraper.fetch_public_tweet_summary(tweet_source_id, delay=0.0)
                except Exception:
                    public_summary = None
                if isinstance(detail_summary, dict):
                    detail_summary["_source"] = "tweet_detail"
                if isinstance(public_summary, dict):
                    public_summary["_source"] = "public_summary"
                merged_summary = _merge_twitter_metric_summaries(detail_summary, public_summary)
                if merged_summary:
                    current_replies = _normalize_non_negative_int(getattr(tweet, "replies", 0))
                    tweet.replies = max(current_replies, _normalize_non_negative_int(merged_summary.get("replies")))
                    current_likes = _normalize_non_negative_int(getattr(tweet, "likes", 0))
                    tweet.likes = max(current_likes, _normalize_non_negative_int(merged_summary.get("likes")))
                    current_retweets = _normalize_non_negative_int(getattr(tweet, "retweets", 0))
                    tweet.retweets = max(current_retweets, _normalize_non_negative_int(merged_summary.get("retweets")))
                    current_quotes = _normalize_non_negative_int(getattr(tweet, "quotes", 0))
                    tweet.quotes = max(current_quotes, _normalize_non_negative_int(merged_summary.get("quotes")))
                    current_views = _normalize_non_negative_int(getattr(tweet, "views", 0))
                    tweet.views = max(current_views, _normalize_non_negative_int(merged_summary.get("views")))
                    if not getattr(tweet, "username", None):
                        tweet.username = str(merged_summary.get("username") or "").strip()
                    if not getattr(tweet, "display_name", None):
                        tweet.display_name = str(merged_summary.get("display_name") or "").strip()
                    if not getattr(tweet, "user_id", None):
                        tweet.user_id = str(merged_summary.get("user_id") or "").strip() or None
                    if not getattr(tweet, "user_profile_url", None):
                        tweet.user_profile_url = str(merged_summary.get("user_profile_url") or "").strip() or None
                    if not getattr(tweet, "user_avatar_url", None):
                        tweet.user_avatar_url = str(merged_summary.get("user_avatar_url") or "").strip() or None
                    tweet.media_urls = _merge_twitter_media_urls(
                        list(getattr(tweet, "media_urls", []) or []),
                        list(merged_summary.get("media_urls") or []),
                    )
                preview_media_count = int(getattr(tweet, "link_preview_media_count", 0) or 0)
                if preview_media_count > 0:
                    link_preview_media_hits += preview_media_count
                elif "http" in text.lower() and not list(getattr(tweet, "media_urls", []) or []):
                    link_preview_media_misses += 1
                anchor_posts.append(tweet)
                existing_row = existing_post_lookup.get(str(getattr(tweet, "tweet_id", "") or ""))
                if existing_row and opts.max_comments_per_post > 0:
                    expected_comment_count = _expected_comment_count_for_platform(
                        "twitter",
                        {
                            "replies_count": int(getattr(tweet, "replies", 0) or 0),
                            "quotes": int(getattr(tweet, "quotes", 0) or 0),
                        },
                    )
                    decision = _decide_comment_refresh(
                        sync_strategy=opts.sync_strategy,
                        expected_count=expected_comment_count,
                        snapshot=snapshots.get(str(getattr(tweet, "tweet_id", "") or "")),
                        post_published_at=_coerce_dt(existing_row.get("created_at")),
                        refresh_policy=opts.comment_refresh_policy,
                    )
                    comment_refresh_reasons[decision.reason] += 1
                    if not decision.should_refresh:
                        skipped_synced += 1
                        activity["phase"] = "posts_skip_up_to_date"
                        _flush_progress()
                        continue
            if is_reply and not include_reply_records:
                _flush_progress()
                continue

            upserted = None
            try:
                with pg.db_connection() as conn:
                    upserted = _upsert_tweet(
                        context,
                        job_id=job_id,
                        run_id=run_id,
                        account=account,
                        tweet=tweet,
                        conn=conn,
                    )
            except Exception:
                comment_errors += 1
                comment_fail_reasons.add("persist_exception")
                logger.exception(
                    "[twitter] Failed to upsert tweet tweet_id=%s",
                    getattr(tweet, "tweet_id", "?"),
                )
                _flush_progress()
                continue

            if not upserted:
                _flush_progress()
                continue
            if is_reply:
                scraped_reply_count += 1
            else:
                upserted_post_count += 1
                activity["matched_posts"] = upserted_post_count
                if stage == "posts":
                    try:
                        mirror_job_id = _enqueue_platform_media_mirror_job(
                            context,
                            platform="twitter",
                            run_id=run_id,
                            source_scope=opts.source_scope,
                            account=account,
                            post_row=upserted,
                            week_index=None,
                            parent_job_id=job_id,
                            conn=None,
                        )
                        if mirror_job_id:
                            mirror_jobs_enqueued += 1
                    except Exception:  # noqa: BLE001
                        mirror_job_enqueue_errors += 1
                        logger.exception(
                            "[twitter] Failed to enqueue media mirror job for post=%s tweet_id=%s",
                            str((upserted or {}).get("id") or ""),
                            str(getattr(tweet, "tweet_id", "") or ""),
                        )
            activity["phase"] = "posts_upsert"
            _flush_progress()

        if hydrate_audience_replies and opts.max_comments_per_post > 0:
            per_post_limit = _effective_reply_limit(opts)
            if per_post_limit > 0:
                anchor_posts_iter = (
                    anchor_posts if opts.max_posts_per_target <= 0 else anchor_posts[: opts.max_posts_per_target]
                )
                with pg.db_connection() as comments_conn:
                    for anchor_index, tweet in enumerate(anchor_posts_iter, start=1):
                        tweet_id = str(getattr(tweet, "tweet_id", "") or "")
                        if not tweet_id:
                            continue
                        expected_replies = _normalize_non_negative_int(getattr(tweet, "replies", 0))
                        expected_quotes = _normalize_non_negative_int(getattr(tweet, "quotes", 0))
                        reply_pages, quote_pages = _twitter_reply_quote_page_budgets(
                            expected_replies=expected_replies,
                            expected_quotes=expected_quotes,
                        )
                        fetch_failed = False
                        quote_fetch_failed = False
                        fail_reason = ""
                        quote_fail_reason = ""
                        replies: list[Any] = []
                        quotes: list[Any] = []
                        observed_comment_ids: set[str] = set()
                        local_comment_stats = _new_comment_persist_stats()
                        try:
                            replies = _fetch_twitter_replies_compat(
                                scraper=scraper,
                                tweet_id=tweet_id,
                                delay=0.5,
                                search_max_pages=reply_pages,
                                twikit_max_pages=reply_pages,
                            )[:per_post_limit]
                            fail_reason = str(getattr(scraper, "last_reply_fetch_reason", "") or "")
                            if fail_reason:
                                comment_fail_reasons.add(fail_reason)
                                if not replies:
                                    comment_errors += 1
                        except Exception:
                            fetch_failed = True
                            comment_errors += 1
                            comment_fail_reasons.add("fetch_exception")
                            logger.exception("[twitter] Failed to fetch replies for tweet %s", tweet_id)
                            incomplete_comment_fetches += 1
                            comments_mark_missing_skipped += 1

                        try:
                            quotes, missing_quote_method_reason = _fetch_twitter_quotes_compat(
                                scraper=scraper,
                                tweet_id=tweet_id,
                                delay=0.5,
                                max_pages=quote_pages,
                            )
                            quotes = quotes[:per_post_limit]
                            quote_fail_reason = str(getattr(scraper, "last_quote_fetch_reason", "") or "")
                            if missing_quote_method_reason:
                                quote_fail_reason = missing_quote_method_reason
                            if quote_fail_reason:
                                quote_fail_reasons.add(quote_fail_reason)
                                if not quotes:
                                    quote_errors += 1
                        except Exception:
                            quote_fetch_failed = True
                            quote_errors += 1
                            quote_fail_reason = "fetch_exception"
                            quote_fail_reasons.add(quote_fail_reason)
                            logger.exception("[twitter] Failed to fetch quotes for tweet %s", tweet_id)
                        quote_stats["quotes_fetched"] += len(quotes)

                        if not fetch_failed:
                            try:
                                with _SavepointScope(
                                    conn=comments_conn,
                                    prefix="twitter_posts_comments",
                                    index=anchor_index,
                                ):
                                    for reply in replies:
                                        if not getattr(reply, "reply_to_tweet_id", None):
                                            reply.reply_to_tweet_id = tweet_id
                                        reply.is_reply = True
                                        reply_id = str(getattr(reply, "tweet_id", "") or "")
                                        if reply_id:
                                            observed_comment_ids.add(reply_id)
                                    persisted_replies = _upsert_tweet_batch(
                                        context,
                                        job_id=job_id,
                                        run_id=run_id,
                                        account=account,
                                        tweets=replies,
                                        persist_stats=local_comment_stats,
                                        conn=comments_conn,
                                    )
                                    for reply in replies:
                                        reply_id = str(getattr(reply, "tweet_id", "") or "")
                                        upserted_reply = persisted_replies.get(reply_id)
                                        if upserted_reply:
                                            hydrated_replies += 1
                                            try:
                                                mirror_job_id = _enqueue_twitter_comment_media_mirror_job(
                                                    context,
                                                    run_id=run_id,
                                                    source_scope=opts.source_scope,
                                                    account=account,
                                                    comment_row=upserted_reply,
                                                    parent_job_id=job_id,
                                                    conn=comments_conn,
                                                )
                                                if mirror_job_id:
                                                    local_comment_stats["comment_media_mirror_jobs_enqueued"] = (
                                                        int(
                                                            local_comment_stats.get(
                                                                "comment_media_mirror_jobs_enqueued"
                                                            )
                                                            or 0
                                                        )
                                                        + 1
                                                    )
                                            except Exception:
                                                local_comment_stats["comment_media_mirror_job_enqueue_errors"] = (
                                                    int(
                                                        local_comment_stats.get(
                                                            "comment_media_mirror_job_enqueue_errors"
                                                        )
                                                        or 0
                                                    )
                                                    + 1
                                                )
                                                logger.exception(
                                                    "[twitter] Failed to enqueue comment media mirror for reply %s",
                                                    reply_id,
                                                )

                                    filtered_quotes: list[Any] = []
                                    for quote in quotes:
                                        quote.is_reply = False
                                        quote.reply_to_tweet_id = None
                                        quote.is_quote = True
                                        if not getattr(quote, "quoted_tweet_id", None):
                                            quote.quoted_tweet_id = tweet_id
                                        if str(getattr(quote, "quoted_tweet_id", "") or "") != tweet_id:
                                            continue
                                        quote_id = str(getattr(quote, "tweet_id", "") or "")
                                        if quote_id:
                                            observed_comment_ids.add(quote_id)
                                        filtered_quotes.append(quote)
                                    persisted_quotes = _upsert_tweet_batch(
                                        context,
                                        job_id=job_id,
                                        run_id=run_id,
                                        account=account,
                                        tweets=filtered_quotes,
                                        persist_stats=None,
                                        conn=comments_conn,
                                    )
                                    for quote in filtered_quotes:
                                        quote_id = str(getattr(quote, "tweet_id", "") or "")
                                        upserted_quote = persisted_quotes.get(quote_id)
                                        if upserted_quote:
                                            hydrated_quotes += 1
                                            quote_stats["quotes_upserted"] += 1
                                            try:
                                                mirror_job_id = _enqueue_twitter_comment_media_mirror_job(
                                                    context,
                                                    run_id=run_id,
                                                    source_scope=opts.source_scope,
                                                    account=account,
                                                    comment_row=upserted_quote,
                                                    parent_job_id=job_id,
                                                    conn=comments_conn,
                                                )
                                                if mirror_job_id:
                                                    local_comment_stats["comment_media_mirror_jobs_enqueued"] = (
                                                        int(
                                                            local_comment_stats.get(
                                                                "comment_media_mirror_jobs_enqueued"
                                                            )
                                                            or 0
                                                        )
                                                        + 1
                                                    )
                                            except Exception:
                                                local_comment_stats["comment_media_mirror_job_enqueue_errors"] = (
                                                    int(
                                                        local_comment_stats.get(
                                                            "comment_media_mirror_job_enqueue_errors"
                                                        )
                                                        or 0
                                                    )
                                                    + 1
                                                )
                                                logger.exception(
                                                    "[twitter] Failed to enqueue comment media mirror for quote %s",
                                                    quote_id,
                                                )

                                    is_complete = _is_comment_fetch_complete(
                                        fetch_failed=False,
                                        fail_reason=fail_reason,
                                        quote_fail_reason=quote_fail_reason,
                                        auth_failed=bool(getattr(scraper, "comments_auth_failed", False)),
                                        fetched_count=(len(replies) + len(quotes)),
                                        quotes_fetched=len(quotes),
                                        max_comments_per_post=per_post_limit,
                                        expected_count=(expected_replies + expected_quotes),
                                        expected_quotes=expected_quotes,
                                    )
                                    if is_complete:
                                        missing_marked += _mark_missing_comments_for_anchor(
                                            platform="twitter",
                                            anchor_id=tweet_id,
                                            observed_comment_ids=observed_comment_ids,
                                            conn=comments_conn,
                                        )
                                        _reconcile_post_comment_count(
                                            platform="twitter",
                                            post_db_id=tweet_id,
                                            conn=comments_conn,
                                        )
                                    else:
                                        incomplete_comment_fetches += 1
                                        comments_mark_missing_skipped += 1
                            except Exception:
                                fetch_failed = True
                                comment_errors += 1
                                comment_fail_reasons.add("persist_exception")
                                logger.exception("[twitter] Failed to persist replies for tweet %s", tweet_id)
                                incomplete_comment_fetches += 1
                                comments_mark_missing_skipped += 1

                        if not fetch_failed:
                            _merge_comment_persist_stats(comment_stats, local_comment_stats)
                            scraped_reply_count = int(comment_stats.get("comments_fetched") or 0)
                            activity["phase"] = "comments_fetch"
                            _flush_progress()
                        if quote_fetch_failed and not quote_fail_reason:
                            quote_fail_reasons.add("fetch_exception")
            scraped_reply_count = int(comment_stats.get("comments_fetched") or 0)
        if skipped_synced:
            logger.info("[twitter] Skipped %d posts already up-to-date", skipped_synced)

    if comment_errors:
        retrieval_meta["comment_errors"] = comment_errors
    if comment_fail_reasons:
        retrieval_meta["comment_fail_reasons"] = sorted(comment_fail_reasons)
    if comment_refresh_reasons:
        retrieval_meta["comment_refresh_decisions"] = dict(comment_refresh_reasons)
    if missing_marked:
        retrieval_meta["comments_marked_missing"] = missing_marked
    if incomplete_comment_fetches:
        retrieval_meta["incomplete_comment_fetches"] = incomplete_comment_fetches
    if comments_mark_missing_skipped:
        retrieval_meta["comments_mark_missing_skipped"] = comments_mark_missing_skipped
    if mirror_jobs_enqueued:
        retrieval_meta["media_mirror_jobs_enqueued"] = mirror_jobs_enqueued
    if mirror_job_enqueue_errors:
        retrieval_meta["media_mirror_job_enqueue_errors"] = mirror_job_enqueue_errors
    if quote_errors:
        retrieval_meta["quote_errors"] = quote_errors
    if quote_fail_reasons:
        retrieval_meta["quote_fail_reasons"] = sorted(quote_fail_reasons)
    comment_media_mirror_jobs_enqueued = int(comment_stats.get("comment_media_mirror_jobs_enqueued") or 0)
    comment_media_mirror_job_enqueue_errors = int(comment_stats.get("comment_media_mirror_job_enqueue_errors") or 0)
    if comment_media_mirror_jobs_enqueued:
        retrieval_meta["comment_media_mirror_jobs_enqueued"] = comment_media_mirror_jobs_enqueued
    if comment_media_mirror_job_enqueue_errors:
        retrieval_meta["comment_media_mirror_job_enqueue_errors"] = comment_media_mirror_job_enqueue_errors
    retrieval_meta["quote_stats"] = {
        "quotes_fetched": int(quote_stats.get("quotes_fetched") or 0),
        "quotes_upserted": int(quote_stats.get("quotes_upserted") or 0),
    }
    retrieval_meta["twitter_link_preview_media"] = {
        "resolved": int(link_preview_media_hits),
        "missing": int(link_preview_media_misses),
    }
    retrieval_meta["strict_rhoslc_hashtag_mode"] = strict_rhoslc_hashtag_mode
    retrieval_meta["comment_stats"] = _comment_stats_payload(comment_stats)
    retrieval_meta["scrape_counters"] = {"posts": scraped_post_count, "comments": scraped_reply_count}
    retrieval_meta["persist_counters"] = {
        "posts_upserted": upserted_post_count,
        "comments_upserted": int(comment_stats.get("comments_upserted") or 0),
    }
    activity["phase"] = f"{stage}_end"
    retrieval_meta["activity"] = _build_progress_activity_payload(activity, now=_now_utc())

    _flush_progress(force=True)

    logger.info(
        (
            "[twitter] Done: posts=%d replies=%d quotes=%d hydrated_replies=%d "
            "hydrated_quotes=%d skipped_keyword=%d comment_errors=%d quote_errors=%d"
        ),
        scraped_post_count,
        scraped_reply_count,
        int(quote_stats.get("quotes_upserted") or 0),
        hydrated_replies,
        hydrated_quotes,
        skipped_keyword,
        comment_errors,
        quote_errors,
    )
    retrieval_meta["hydrated_replies"] = hydrated_replies
    retrieval_meta["hydrated_quotes"] = hydrated_quotes
    retrieval_meta = _merge_source_runtime(retrieval_meta, scraper)
    return scraped_post_count, scraped_reply_count, retrieval_meta


def _upsert_facebook_post(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    account: str,
    post: Any,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    scraped_at = _now_utc()
    posted_at = _parse_platform_time(getattr(post, "posted_at", None)) or scraped_at
    media_urls = [str(url).strip() for url in (getattr(post, "media_urls", []) or []) if str(url).strip()]
    thumbnail_url = str(getattr(post, "thumbnail_url", "") or "").strip() or (media_urls[0] if media_urls else None)
    caption = str(getattr(post, "caption", "") or "").strip() or None
    hashtags = _as_text_list(_parse_hashtags(caption), strip_prefix="#")
    mentions = _as_text_list(_parse_mentions(caption), prefix="@", strip_prefix="@")
    raw_payload = post.to_dict() if hasattr(post, "to_dict") else {}
    if isinstance(raw_payload, dict) and raw_payload.get("posted_at") is None:
        ingest_meta = dict(raw_payload.get("_ingest") or {})
        ingest_meta["posted_at_fallback"] = "scraped_at"
        raw_payload["_ingest"] = ingest_meta
    payload = {
        "post_id": str(getattr(post, "post_id", "") or "").strip(),
        "page_id": None,
        "username": str(getattr(post, "username", account) or "").strip() or account,
        "user_id": None,
        "caption": caption,
        "post_type": str(getattr(post, "post_type", "feed") or "feed").strip().lower(),
        "media_type": str(getattr(post, "post_type", "feed") or "feed").strip().lower(),
        "media_urls": media_urls,
        "thumbnail_url": thumbnail_url,
        "likes": int(getattr(post, "likes", 0) or 0),
        "comments_count": int(getattr(post, "comments", 0) or 0),
        "shares": int(getattr(post, "shares", 0) or 0),
        "views": int(getattr(post, "views", 0) or 0),
        "posted_at": posted_at,
        "scraped_at": scraped_at,
        "raw_data": raw_payload,
        "source_account": str(account or "").strip().lstrip("@").lower() or account,
    }
    _apply_assignment_payload(payload, context)
    if job_id:
        payload["job_id"] = job_id
    if _platform_posts_has_column("facebook", "hashtags", conn=conn):
        payload["hashtags"] = hashtags
    if _platform_posts_has_column("facebook", "mentions", conn=conn):
        payload["mentions"] = mentions
    if _platform_posts_has_column("facebook", "user_avatar_url", conn=conn):
        payload["user_avatar_url"] = str(getattr(post, "user_avatar_url", "") or "").strip() or None
    if media_urls or thumbnail_url:
        payload["media_mirror_status"] = "pending"
        payload["media_mirror_error"] = None
    return _pg_upsert("facebook_posts", payload, conflict_col="post_id", conn=conn)


def _upsert_facebook_comment_tree(
    context: SeasonContext,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    post_id: str,
    comment: Any,
    source_scope: str = "network",
    parent_comment_db_id: str | None = None,
    observed_comment_ids: set[str] | None = None,
    persist_stats: dict[str, int] | None = None,
    conn: Any | None = None,
) -> int:
    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1
    comment_external_id = str(getattr(comment, "comment_id", "") or "").strip()
    if observed_comment_ids is not None and comment_external_id:
        observed_comment_ids.add(comment_external_id)
    if not comment_external_id:
        return 0

    media_urls = [str(url).strip() for url in (getattr(comment, "media_urls", []) or []) if str(url).strip()]
    scraped_at = _now_utc()
    created_at = _parse_platform_time(getattr(comment, "created_at", None)) or scraped_at
    raw_payload = comment.to_dict() if hasattr(comment, "to_dict") else {}
    interaction_type = _threads_interaction_type(
        is_reply=getattr(comment, "is_reply", None),
        raw_data=raw_payload,
    )
    is_reply_interaction = interaction_type != "quote"
    if isinstance(raw_payload, dict):
        raw_payload["_interaction_type"] = interaction_type
        raw_payload["interaction_type"] = interaction_type
        raw_payload["is_quote"] = interaction_type == "quote"
        raw_payload["is_reply"] = is_reply_interaction
    if isinstance(raw_payload, dict) and raw_payload.get("created_at") is None:
        ingest_meta = dict(raw_payload.get("_ingest") or {})
        ingest_meta["created_at_fallback"] = "scraped_at"
        raw_payload["_ingest"] = ingest_meta
    payload = {
        "comment_id": comment_external_id,
        "post_id": post_id,
        "parent_comment_id": parent_comment_db_id,
        "parent_source_comment_id": str(getattr(comment, "parent_source_comment_id", "") or "").strip() or None,
        "username": str(getattr(comment, "username", "") or "").strip() or account,
        "user_id": None,
        "text": str(getattr(comment, "text", "") or ""),
        "likes": int(getattr(comment, "likes", 0) or 0),
        "is_reply": bool(getattr(comment, "is_reply", False)),
        "reply_count": int(getattr(comment, "reply_count", 0) or 0),
        "created_at": created_at,
        "scraped_at": scraped_at,
        "raw_data": raw_payload,
        "season_id": context.season_id,
        "source_account": account,
        "media_urls": media_urls,
    }
    if job_id:
        payload["job_id"] = job_id
    if media_urls:
        payload["media_mirror_status"] = "pending"
        payload["media_mirror_error"] = None
    if _comment_lifecycle_supported("facebook_comments"):
        payload["is_missing"] = False
        payload["missing_at"] = None
        payload["last_seen_at"] = scraped_at
        if run_id is not None:
            payload["last_seen_run_id"] = run_id

    row = _pg_upsert("facebook_comments", payload, conflict_col="comment_id", conn=conn)
    comment_db_id = (row or {}).get("id")
    if persist_stats is not None and row:
        persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + 1
    if row:
        try:
            mirror_job_id = _enqueue_facebook_comment_media_mirror_job(
                context,
                run_id=run_id,
                source_scope=source_scope,
                account=account,
                comment_row=row,
                parent_job_id=job_id,
                conn=conn,
            )
            if mirror_job_id and persist_stats is not None:
                persist_stats["comment_media_mirror_jobs_enqueued"] = (
                    int(persist_stats.get("comment_media_mirror_jobs_enqueued") or 0) + 1
                )
        except Exception:
            if persist_stats is not None:
                persist_stats["comment_media_mirror_job_enqueue_errors"] = (
                    int(persist_stats.get("comment_media_mirror_job_enqueue_errors") or 0) + 1
                )
            logger.exception(
                "[facebook] Failed to enqueue comment media mirror for comment %s",
                comment_external_id,
            )
    total = 1 if row else 0
    for reply in getattr(comment, "replies", []) or []:
        total += _upsert_facebook_comment_tree(
            context,
            job_id=job_id,
            run_id=run_id,
            account=account,
            post_id=post_id,
            comment=reply,
            source_scope=source_scope,
            parent_comment_db_id=comment_db_id,
            observed_comment_ids=observed_comment_ids,
            persist_stats=persist_stats,
            conn=conn,
        )
    return total


def _ingest_facebook(
    context: SeasonContext,
    *,
    run_id: str | None,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    stage: str = "posts",
) -> tuple[int, int, dict[str, Any]]:
    from trr_backend.socials.facebook import FacebookScrapeConfig, FacebookScraper

    scraper = FacebookScraper(cookies=_load_facebook_cookies())
    retrieval_meta: dict[str, Any] = {"facebook_authenticated": bool(scraper.cookies)}
    post_count = 0
    comment_count = 0
    matched_posts = 0
    mirror_jobs_enqueued = 0
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {"phase": f"{stage}_start", "pages_scanned": 0, "posts_checked": 0, "matched_posts": 0}

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=stage,
            platform="facebook",
            account=account,
            scraped_posts=post_count,
            scraped_comments=comment_count,
            posts_upserted=matched_posts,
            comments_upserted=comment_count,
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)

    if stage == "posts" and opts.ingest_mode == "details_refresh":
        return _run_existing_post_details_refresh(
            context,
            platform="facebook",
            run_id=run_id,
            account=account,
            opts=opts,
            job_id=job_id,
            activity=activity,
            flush_progress=_flush_progress,
        )

    if stage == "comments":
        target_source_ids = _target_source_ids_for_platform(opts, "facebook")
        existing_posts = _load_existing_posts(
            "facebook",
            context,
            account,
            opts.date_start,
            opts.date_end,
            source_ids=target_source_ids,
        )
        for row in existing_posts:
            source_id = str(row.get("post_id") or "")
            post_db_id = str(row.get("id") or "")
            if not source_id or not post_db_id:
                continue
            fetch_target = _facebook_primary_post_fetch_target(
                source_id=source_id,
                account=account,
                raw_data=row.get("raw_data"),
            )
            comments = scraper.fetch_comments(
                fetch_target,
                max_comments=opts.max_comments_per_post,
                fetch_replies=opts.fetch_replies,
            )
            local_stats = _new_comment_persist_stats()
            observed_comment_ids: set[str] = set()
            with pg.db_connection() as conn:
                for comment in comments:
                    _upsert_facebook_comment_tree(
                        context,
                        job_id=job_id,
                        run_id=run_id,
                        account=account,
                        post_id=post_db_id,
                        comment=comment,
                        source_scope=opts.source_scope,
                        observed_comment_ids=observed_comment_ids,
                        persist_stats=local_stats,
                        conn=conn,
                    )
            post_count += 1
            matched_posts += 1
            comment_count += int(local_stats.get("comments_upserted") or 0)
            activity["phase"] = "comments_fetch"
            activity["posts_checked"] = post_count
            activity["matched_posts"] = matched_posts
            _flush_progress()
    else:
        config = FacebookScrapeConfig(
            page_handle=account,
            date_start=opts.date_start,
            date_end=opts.date_end,
            delay_seconds=max(0.5, float(os.getenv("SOCIAL_FACEBOOK_DELAY_SEC", "1.0"))),
            max_pages=opts.max_posts_per_target if opts.max_posts_per_target > 0 else None,
            include_feed=True,
            include_reels=True,
            include_photos=True,
            max_scroll_iterations=int(os.getenv("SOCIAL_FACEBOOK_MAX_SCROLL_ITERATIONS", "50")),
        )

        def _on_progress(payload: dict[str, Any]) -> None:
            activity["phase"] = str(payload.get("phase") or "scrape_posts")
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
            activity["matched_posts"] = _normalize_non_negative_int(payload.get("matched_posts"))
            _flush_progress()

        posts = scraper.scrape(config, progress_cb=_on_progress)
        retrieval_meta.update(dict(getattr(scraper, "last_retrieval_meta", {}) or {}))
        for post in posts:
            post_count += 1
            text = str(getattr(post, "caption", "") or "")
            if not _text_contains_any_term(text=text, hashtags=hashtags, keywords=keywords):
                _flush_progress()
                continue
            local_stats = _new_comment_persist_stats()
            observed_comment_ids: set[str] = set()
            mirror_job_id: str | None = None
            comments: list[Any] = []
            if opts.max_comments_per_post > 0:
                fetch_target = _facebook_primary_post_fetch_target(
                    source_id=str(getattr(post, "post_id", "") or "").strip(),
                    account=account,
                    post_url=str(getattr(post, "url", "") or "").strip(),
                    raw_data=getattr(post, "raw_data", None),
                )
                comments = scraper.fetch_comments(
                    fetch_target,
                    max_comments=opts.max_comments_per_post,
                    fetch_replies=opts.fetch_replies,
                )
            with pg.db_connection(label="facebook-post-sync") as conn:
                upserted = _upsert_facebook_post(context, job_id=job_id, account=account, post=post, conn=conn)
                if not upserted:
                    continue
                for comment in comments:
                    _upsert_facebook_comment_tree(
                        context,
                        job_id=job_id,
                        run_id=run_id,
                        account=account,
                        post_id=str(upserted["id"]),
                        comment=comment,
                        source_scope=opts.source_scope,
                        observed_comment_ids=observed_comment_ids,
                        persist_stats=local_stats,
                        conn=conn,
                    )
                mirror_job_id = _enqueue_platform_media_mirror_job(
                    context,
                    platform="facebook",
                    run_id=run_id,
                    source_scope=opts.source_scope,
                    account=account,
                    post_row=upserted,
                    week_index=None,
                    parent_job_id=job_id,
                    conn=conn,
                )
            matched_posts += 1
            comment_count += int(local_stats.get("comments_upserted") or 0)
            if mirror_job_id:
                mirror_jobs_enqueued += 1
            activity["phase"] = "posts_upsert"
            activity["matched_posts"] = matched_posts
            _flush_progress()

    activity["phase"] = f"{stage}_end"
    _flush_progress(force=True)
    retrieval_meta["media_mirror_jobs_enqueued"] = mirror_jobs_enqueued
    retrieval_meta["scrape_counters"] = {"posts": post_count, "comments": comment_count}
    retrieval_meta["persist_counters"] = {"posts_upserted": matched_posts, "comments_upserted": comment_count}
    retrieval_meta = _merge_source_runtime(retrieval_meta, scraper)
    return post_count, comment_count, retrieval_meta


def _upsert_meta_threads_post(
    context: SeasonContext | None,
    *,
    job_id: str | None,
    account: str,
    post: Any,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    post_external_id = str(getattr(post, "post_id", "") or "").strip()
    post_raw_data = getattr(post, "raw_data", None)
    degraded_source = isinstance(post_raw_data, dict) and post_raw_data.get("source") == "public_meta_fallback"
    if degraded_source and post_external_id:
        # OG-tag fallback posts carry zeroed metrics and a fabricated
        # posted_at; never let them overwrite an existing row.
        with pg.db_cursor(conn=conn, label="threads-degraded-guard") as cur:
            cur.execute(
                "select * from social.meta_threads_posts where post_id = %s",
                (post_external_id,),
            )
            existing = cur.fetchone()
        if existing:
            logger.warning(
                "[threads] skipping public_meta_fallback upsert for existing post %s "
                "(account=%s); preserving stored metrics/posted_at",
                post_external_id,
                account,
            )
            return dict(existing)
    scraped_at = _now_utc()
    posted_at = _parse_platform_time(getattr(post, "posted_at", None)) or scraped_at
    media_urls = [str(url).strip() for url in (getattr(post, "media_urls", []) or []) if str(url).strip()]
    thumbnail_url = str(getattr(post, "thumbnail_url", "") or "").strip() or (media_urls[0] if media_urls else None)
    text = str(getattr(post, "text", "") or "").strip() or None
    hashtags = _as_text_list(_parse_hashtags(text), strip_prefix="#")
    mentions = _as_text_list(_parse_mentions(text), prefix="@", strip_prefix="@")
    raw_payload = post.to_dict() if hasattr(post, "to_dict") else {}
    if isinstance(raw_payload, dict) and raw_payload.get("posted_at") is None:
        ingest_meta = dict(raw_payload.get("_ingest") or {})
        ingest_meta["posted_at_fallback"] = "scraped_at"
        raw_payload["_ingest"] = ingest_meta
    payload = {
        "post_id": str(getattr(post, "post_id", "") or "").strip(),
        "thread_item_id": str(getattr(post, "post_id", "") or "").strip(),
        "username": str(getattr(post, "username", account) or "").strip() or account,
        "user_id": None,
        "text": text,
        "media_type": "mixed" if len(media_urls) > 1 else ("image" if media_urls else "text"),
        "media_urls": media_urls,
        "thumbnail_url": thumbnail_url,
        "likes": int(getattr(post, "likes", 0) or 0),
        "replies_count": int(getattr(post, "replies", 0) or 0),
        "reposts": int(getattr(post, "reposts", 0) or 0),
        "quotes": int(getattr(post, "quotes", 0) or 0),
        "views": int(getattr(post, "views", 0) or 0),
        "posted_at": posted_at,
        "scraped_at": scraped_at,
        "raw_data": raw_payload,
        "source_account": account,
    }
    _apply_assignment_payload(payload, context)
    if job_id:
        payload["job_id"] = job_id
    if _platform_posts_has_column("threads", "hashtags", conn=conn):
        payload["hashtags"] = hashtags
    if _platform_posts_has_column("threads", "mentions", conn=conn):
        payload["mentions"] = mentions
    if _platform_posts_has_column("threads", "user_avatar_url", conn=conn):
        payload["user_avatar_url"] = str(getattr(post, "user_avatar_url", "") or "").strip() or None
    if media_urls or thumbnail_url:
        payload["media_mirror_status"] = "pending"
        payload["media_mirror_error"] = None
    return _pg_upsert("meta_threads_posts", payload, conflict_col="post_id", conn=conn)


def _upsert_meta_threads_comment_tree(
    context: SeasonContext,
    *,
    job_id: str | None,
    run_id: str | None,
    account: str,
    post_id: str,
    comment: Any,
    source_scope: str = "network",
    parent_comment_db_id: str | None = None,
    observed_comment_ids: set[str] | None = None,
    persist_stats: dict[str, int] | None = None,
    conn: Any | None = None,
) -> int:
    if persist_stats is not None:
        persist_stats["comments_fetched"] = int(persist_stats.get("comments_fetched") or 0) + 1
    comment_external_id = str(getattr(comment, "comment_id", "") or "").strip()
    if observed_comment_ids is not None and comment_external_id:
        observed_comment_ids.add(comment_external_id)
    if not comment_external_id:
        return 0
    media_urls = [str(url).strip() for url in (getattr(comment, "media_urls", []) or []) if str(url).strip()]
    scraped_at = _now_utc()
    created_at = _parse_platform_time(getattr(comment, "created_at", None)) or scraped_at
    raw_payload = comment.to_dict() if hasattr(comment, "to_dict") else {}
    if isinstance(raw_payload, dict) and raw_payload.get("created_at") is None:
        ingest_meta = dict(raw_payload.get("_ingest") or {})
        ingest_meta["created_at_fallback"] = "scraped_at"
        raw_payload["_ingest"] = ingest_meta
    interaction_type = _threads_interaction_type(
        is_reply=getattr(comment, "is_reply", None),
        raw_data=getattr(comment, "raw_data", None),
    )
    is_reply_interaction = interaction_type != "quote"
    if isinstance(raw_payload, dict):
        raw_payload["_interaction_type"] = interaction_type
        raw_payload["interaction_type"] = interaction_type
        raw_payload["is_quote"] = interaction_type == "quote"
        raw_payload["is_reply"] = is_reply_interaction
    payload = {
        "comment_id": comment_external_id,
        "post_id": post_id,
        "parent_comment_id": parent_comment_db_id,
        "parent_source_comment_id": str(getattr(comment, "parent_source_comment_id", "") or "").strip() or None,
        "username": str(getattr(comment, "username", "") or "").strip() or account,
        "user_id": None,
        "text": str(getattr(comment, "text", "") or ""),
        "likes": int(getattr(comment, "likes", 0) or 0),
        "is_reply": is_reply_interaction,
        "reply_count": int(getattr(comment, "reply_count", 0) or 0),
        "created_at": created_at,
        "scraped_at": scraped_at,
        "raw_data": raw_payload,
        "season_id": context.season_id,
        "source_account": account,
        "media_urls": media_urls,
    }
    if job_id:
        payload["job_id"] = job_id
    if media_urls:
        payload["media_mirror_status"] = "pending"
        payload["media_mirror_error"] = None
    if _comment_lifecycle_supported("meta_threads_comments"):
        payload["is_missing"] = False
        payload["missing_at"] = None
        payload["last_seen_at"] = scraped_at
        if run_id is not None:
            payload["last_seen_run_id"] = run_id

    row = _pg_upsert("meta_threads_comments", payload, conflict_col="comment_id", conn=conn)
    comment_db_id = (row or {}).get("id")
    if persist_stats is not None and row:
        persist_stats["comments_upserted"] = int(persist_stats.get("comments_upserted") or 0) + 1
    if row:
        try:
            mirror_job_id = _enqueue_threads_comment_media_mirror_job(
                context,
                run_id=run_id,
                source_scope=source_scope,
                account=account,
                comment_row=row,
                parent_job_id=job_id,
                conn=conn,
            )
            if mirror_job_id and persist_stats is not None:
                persist_stats["comment_media_mirror_jobs_enqueued"] = (
                    int(persist_stats.get("comment_media_mirror_jobs_enqueued") or 0) + 1
                )
        except Exception:
            if persist_stats is not None:
                persist_stats["comment_media_mirror_job_enqueue_errors"] = (
                    int(persist_stats.get("comment_media_mirror_job_enqueue_errors") or 0) + 1
                )
            logger.exception(
                "[threads] Failed to enqueue comment media mirror for comment %s",
                comment_external_id,
            )
    total = 1 if row else 0
    for reply in getattr(comment, "replies", []) or []:
        total += _upsert_meta_threads_comment_tree(
            context,
            job_id=job_id,
            run_id=run_id,
            account=account,
            post_id=post_id,
            comment=reply,
            source_scope=source_scope,
            parent_comment_db_id=comment_db_id,
            observed_comment_ids=observed_comment_ids,
            persist_stats=persist_stats,
            conn=conn,
        )
    return total


def _record_threads_comment_fetch_accounting(
    *,
    post_db_id: str,
    row: Mapping[str, Any],
    fetch_meta: Mapping[str, Any],
    conn: Any,
) -> dict[str, int] | None:
    normalized_post_id = str(post_db_id or "").strip()
    if not normalized_post_id:
        return None

    unavailable_replies = _normalize_non_negative_int(fetch_meta.get("unavailable_reply_count"))
    quote_fetch_reason = str(fetch_meta.get("quote_fetch_reason") or "").strip()
    quote_fetch_unavailable = quote_fetch_reason == "threads_quotes_fetch_unavailable"
    if unavailable_replies <= 0 and not quote_fetch_unavailable:
        return None

    with pg.db_cursor(conn=conn, label="threads-comment-fetch-accounting-counts") as cur:
        counts_row = (
            pg.fetch_one_with_cursor(
                cur,
                """
            select
              count(*)::int as total_count,
              sum(
                case
                  when (
                    coalesce(c.is_reply, true) = false
                    or lower(
                      coalesce(
                        c.raw_data ->> '_interaction_type',
                        c.raw_data ->> 'interaction_type',
                        c.raw_data ->> 'type',
                        ''
                      )
                    ) in ('quote', 'quoted', 'quoted_post', 'reshare_quote')
                    or lower(coalesce(c.raw_data ->> 'is_quote', 'false')) = 'true'
                    or lower(coalesce(c.raw_data ->> 'is_quote_post', 'false')) = 'true'
                    or (coalesce(c.raw_data, '{}'::jsonb) ? 'quote_post')
                    or (coalesce(c.raw_data, '{}'::jsonb) ? 'quoted_post')
                  )
                  then 1
                  else 0
                end
              )::int as quote_count
            from social.meta_threads_comments c
            where c.post_id = %s::uuid
            """,
                [normalized_post_id],
            )
            or {}
        )

    active_total = _normalize_non_negative_int(counts_row.get("total_count"))
    active_quotes = _normalize_non_negative_int(counts_row.get("quote_count"))
    active_replies = max(0, active_total - active_quotes)
    reported_replies_before = max(
        _normalize_non_negative_int(row.get("replies_count")),
        _normalize_non_negative_int(fetch_meta.get("root_direct_reply_count")),
    )
    reported_quotes_before = _normalize_non_negative_int(row.get("quotes"))
    target_replies = active_replies if unavailable_replies > 0 else max(reported_replies_before, active_replies)
    target_quotes = active_quotes if quote_fetch_unavailable else max(reported_quotes_before, active_quotes)
    accounting_payload = {
        "source": "threads_comment_fetch",
        "accounted_at": _iso(_now_utc()),
        "reported_replies_before": reported_replies_before,
        "reported_quotes_before": reported_quotes_before,
        "active_replies": active_replies,
        "active_quotes": active_quotes,
        "unavailable_replies": max(0, reported_replies_before - active_replies),
        "quote_fetch_reason": quote_fetch_reason or None,
        "reply_pagination_stop_reason": str(fetch_meta.get("reply_pagination_stop_reason") or "") or None,
    }
    with pg.db_cursor(conn=conn, label="threads-comment-fetch-accounting-update") as cur:
        pg.fetch_one_with_cursor(
            cur,
            """
            update social.meta_threads_posts
            set
              replies_count = %s,
              quotes = %s,
              raw_data = coalesce(raw_data, '{}'::jsonb)
                || jsonb_build_object('_comment_fetch_accounting', %s::jsonb)
            where id = %s::uuid
            returning id::text
            """,
            [target_replies, target_quotes, json.dumps(accounting_payload), normalized_post_id],
        )
    return {
        "target_replies": target_replies,
        "target_quotes": target_quotes,
        "active_replies": active_replies,
        "active_quotes": active_quotes,
        "unavailable_replies": accounting_payload["unavailable_replies"],
    }


def _ingest_threads(
    context: SeasonContext,
    *,
    run_id: str | None,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    stage: str = "posts",
) -> tuple[int, int, dict[str, Any]]:
    from trr_backend.socials.threads.posts_scrapling.proxy import select_threads_posts_proxy
    from trr_backend.socials.threads.scraper import ThreadsScrapeConfig, ThreadsScraper

    proxy_config = select_threads_posts_proxy()
    scraper = ThreadsScraper(
        cookies=_load_threads_cookies(),
        proxy_url=proxy_config.api_proxy_url if proxy_config else None,
    )
    retrieval_meta: dict[str, Any] = {
        "threads_authenticated": bool(scraper.cookies),
        "selected_proxy_fingerprint": proxy_config.fingerprint if proxy_config else "none",
    }
    post_count = 0
    comment_count = 0
    matched_posts = 0
    mirror_jobs_enqueued = 0
    pk_resolve_failures = 0
    comment_fetch_reason_hist: Counter[str] = Counter()
    quote_fetch_count = 0
    saved_replies_count = 0
    saved_quotes_count = 0
    comment_fetch_accounting_adjustments = 0
    comment_fetch_unavailable_replies = 0
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {"phase": f"{stage}_start", "pages_scanned": 0, "posts_checked": 0, "matched_posts": 0}

    def _iter_threads_comments(nodes: list[Any]) -> Any:
        for node in nodes:
            yield node
            child_nodes = getattr(node, "replies", None) or []
            if child_nodes:
                yield from _iter_threads_comments(list(child_nodes))

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=stage,
            platform="threads",
            account=account,
            scraped_posts=post_count,
            scraped_comments=comment_count,
            posts_upserted=matched_posts,
            comments_upserted=comment_count,
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)

    if stage == "posts" and opts.ingest_mode == "details_refresh":
        return _run_existing_post_details_refresh(
            context,
            platform="threads",
            run_id=run_id,
            account=account,
            opts=opts,
            job_id=job_id,
            activity=activity,
            flush_progress=_flush_progress,
        )

    if stage == "comments":
        target_source_ids = _target_source_ids_for_platform(opts, "threads")
        existing_posts = _load_existing_posts(
            "threads",
            context,
            account,
            opts.date_start,
            opts.date_end,
            source_ids=target_source_ids,
        )
        for row in existing_posts:
            source_id = str(row.get("post_id") or "")
            post_db_id = str(row.get("id") or "")
            if not source_id or not post_db_id:
                continue
            fetch_target = _threads_primary_post_fetch_target(
                source_id=source_id,
                account=account,
                post_url=str(row.get("url") or "").strip(),
                raw_data=row.get("raw_data"),
            )
            comments = scraper.fetch_comments(
                fetch_target,
                max_comments=opts.max_comments_per_post,
                fetch_replies=opts.fetch_replies,
            )
            reason = str(getattr(scraper, "last_comment_fetch_reason", "") or "").strip()
            if reason:
                comment_fetch_reason_hist[reason] += 1
                if reason == "threads_pk_resolve_failed":
                    pk_resolve_failures += 1
            fetch_meta = dict(getattr(scraper, "last_comment_fetch_meta", {}) or {})
            quote_fetch_count += _normalize_non_negative_int(fetch_meta.get("quote_count"))
            for comment in _iter_threads_comments(comments):
                interaction_type = _threads_interaction_type(
                    is_reply=getattr(comment, "is_reply", None),
                    raw_data=getattr(comment, "raw_data", None),
                )
                if interaction_type == "quote":
                    saved_quotes_count += 1
                else:
                    saved_replies_count += 1
            local_stats = _new_comment_persist_stats()
            observed_comment_ids: set[str] = set()
            with pg.db_connection() as conn:
                if target_source_ids is not None:
                    _update_platform_post_field(
                        platform="threads",
                        post_id=post_db_id,
                        field="season_id",
                        value=context.season_id,
                        conn=conn,
                    )
                    _update_platform_post_field(
                        platform="threads",
                        post_id=post_db_id,
                        field="show_id",
                        value=context.show_id,
                        conn=conn,
                    )
                for comment in comments:
                    _upsert_meta_threads_comment_tree(
                        context,
                        job_id=job_id,
                        run_id=run_id,
                        account=account,
                        post_id=post_db_id,
                        comment=comment,
                        source_scope=opts.source_scope,
                        observed_comment_ids=observed_comment_ids,
                        persist_stats=local_stats,
                        conn=conn,
                    )
                accounting_result = _record_threads_comment_fetch_accounting(
                    post_db_id=post_db_id,
                    row=row,
                    fetch_meta=fetch_meta,
                    conn=conn,
                )
                if accounting_result:
                    comment_fetch_accounting_adjustments += 1
                    comment_fetch_unavailable_replies += _normalize_non_negative_int(
                        accounting_result.get("unavailable_replies")
                    )
            post_count += 1
            matched_posts += 1
            comment_count += int(local_stats.get("comments_upserted") or 0)
            activity["phase"] = "comments_fetch"
            activity["posts_checked"] = post_count
            activity["matched_posts"] = matched_posts
            _flush_progress()
    else:
        config = ThreadsScrapeConfig(
            username=account,
            date_start=opts.date_start,
            date_end=opts.date_end,
            delay_seconds=max(0.5, float(os.getenv("SOCIAL_THREADS_DELAY_SEC", "1.0"))),
            max_pages=opts.max_posts_per_target if opts.max_posts_per_target > 0 else None,
        )

        def _on_progress(payload: dict[str, Any]) -> None:
            activity["phase"] = str(payload.get("phase") or "scrape_posts")
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
            activity["matched_posts"] = _normalize_non_negative_int(payload.get("matched_posts"))
            _flush_progress()

        posts = scraper.scrape(config, progress_cb=_on_progress)
        retrieval_meta.update(dict(getattr(scraper, "last_retrieval_meta", {}) or {}))
        for post in posts:
            post_count += 1
            text = str(getattr(post, "text", "") or "")
            if not _threads_text_topic_match(
                text=text,
                raw_data=getattr(post, "raw_data", None),
                hashtags=hashtags,
                keywords=keywords,
            ):
                _flush_progress()
                continue
            local_stats = _new_comment_persist_stats()
            observed_comment_ids: set[str] = set()
            mirror_job_id: str | None = None
            comments: list[Any] = []
            fetch_meta: dict[str, Any] = {}
            if opts.max_comments_per_post > 0:
                fetch_target = _threads_primary_post_fetch_target(
                    source_id=str(getattr(post, "post_id", "") or "").strip(),
                    account=account,
                    post_url=str(getattr(post, "url", "") or "").strip(),
                    raw_data=getattr(post, "raw_data", None),
                )
                comments = scraper.fetch_comments(
                    fetch_target,
                    max_comments=opts.max_comments_per_post,
                    fetch_replies=opts.fetch_replies,
                )
                reason = str(getattr(scraper, "last_comment_fetch_reason", "") or "").strip()
                if reason:
                    comment_fetch_reason_hist[reason] += 1
                    if reason == "threads_pk_resolve_failed":
                        pk_resolve_failures += 1
                fetch_meta = dict(getattr(scraper, "last_comment_fetch_meta", {}) or {})
                quote_fetch_count += _normalize_non_negative_int(fetch_meta.get("quote_count"))
                for comment in _iter_threads_comments(comments):
                    interaction_type = _threads_interaction_type(
                        is_reply=getattr(comment, "is_reply", None),
                        raw_data=getattr(comment, "raw_data", None),
                    )
                    if interaction_type == "quote":
                        saved_quotes_count += 1
                    else:
                        saved_replies_count += 1
            with pg.db_connection(label="threads-post-sync") as conn:
                upserted = _upsert_meta_threads_post(context, job_id=job_id, account=account, post=post, conn=conn)
                if not upserted:
                    continue
                for comment in comments:
                    _upsert_meta_threads_comment_tree(
                        context,
                        job_id=job_id,
                        run_id=run_id,
                        account=account,
                        post_id=str(upserted["id"]),
                        comment=comment,
                        source_scope=opts.source_scope,
                        observed_comment_ids=observed_comment_ids,
                        persist_stats=local_stats,
                        conn=conn,
                    )
                accounting_result = _record_threads_comment_fetch_accounting(
                    post_db_id=str(upserted["id"]),
                    row=upserted,
                    fetch_meta=fetch_meta,
                    conn=conn,
                )
                if accounting_result:
                    comment_fetch_accounting_adjustments += 1
                    comment_fetch_unavailable_replies += _normalize_non_negative_int(
                        accounting_result.get("unavailable_replies")
                    )
                mirror_job_id = _enqueue_platform_media_mirror_job(
                    context,
                    platform="threads",
                    run_id=run_id,
                    source_scope=opts.source_scope,
                    account=account,
                    post_row=upserted,
                    week_index=None,
                    parent_job_id=job_id,
                    conn=conn,
                )
            matched_posts += 1
            comment_count += int(local_stats.get("comments_upserted") or 0)
            if mirror_job_id:
                mirror_jobs_enqueued += 1
            activity["phase"] = "posts_upsert"
            activity["matched_posts"] = matched_posts
            _flush_progress()

    activity["phase"] = f"{stage}_end"
    _flush_progress(force=True)
    retrieval_meta["media_mirror_jobs_enqueued"] = mirror_jobs_enqueued
    retrieval_meta["scrape_counters"] = {"posts": post_count, "comments": comment_count}
    retrieval_meta["persist_counters"] = {"posts_upserted": matched_posts, "comments_upserted": comment_count}
    retrieval_meta["threads_ingest_telemetry"] = {
        "pk_resolve_failures": pk_resolve_failures,
        "comment_fetch_reasons": dict(comment_fetch_reason_hist),
        "quote_fetch_count": quote_fetch_count,
        "saved_replies_count": saved_replies_count,
        "saved_quotes_count": saved_quotes_count,
        "comment_fetch_accounting_adjustments": comment_fetch_accounting_adjustments,
        "comment_fetch_unavailable_replies": comment_fetch_unavailable_replies,
    }
    retrieval_meta = _merge_source_runtime(retrieval_meta, scraper)
    return post_count, comment_count, retrieval_meta


def _retry_backoff_seconds(attempt_count: int) -> int:
    return max(5, min(300, 5 * (2 ** max(0, attempt_count - 1))))


def _platform_delay_env_name(platform: str) -> str:
    return f"SOCIAL_{str(platform or '').strip().upper()}_DELAY_SEC"


def _resolve_platform_base_delay_seconds(platform: str, *, default: float = 0.35) -> float:
    return _resolve_non_negative_float_env(_platform_delay_env_name(platform), default)


def _resolve_platform_delay_seconds(
    *,
    platform: str,
    attempt_count: int = 1,
    last_error_code: str | None = None,
    default: float = 0.35,
) -> float:
    base = _resolve_platform_base_delay_seconds(platform, default=default)
    error_code = str(last_error_code or "").strip().lower()
    attempt = max(1, int(attempt_count or 1))
    if error_code in {"rate_limited", "blocked", "network"} and attempt > 1:
        return min(5.0, base * (1.5 ** max(1, attempt - 1)))
    return base


def _safe_percent(numerator: int | float, denominator: int | float, *, precision: int = 1) -> float | None:
    den = float(denominator)
    if den <= 0:
        return None
    num = max(0.0, float(numerator))
    pct = (num * 100.0) / den
    return round(min(100.0, pct), precision)


def _median_int(values: list[int]) -> int:
    if not values:
        return 0
    ordered = sorted(int(value) for value in values)
    mid = len(ordered) // 2
    if len(ordered) % 2 == 1:
        return ordered[mid]
    return int(round((ordered[mid - 1] + ordered[mid]) / 2.0))


def _normalize_job_error_code(
    *,
    raw_error_code: str | None,
    error_message: str | None,
    error_class: str | None,
) -> str:
    haystack = " ".join(
        token.strip().lower() for token in [raw_error_code or "", error_message or "", error_class or ""] if token
    )
    if not haystack:
        return "UNKNOWN"

    if any(marker in haystack for marker in ("429", "rate limit", "rate_limited", "throttle", "quota")):
        return "RATE_LIMIT"
    if "blocked" in haystack:
        return "BLOCKED"
    if any(
        marker in haystack
        for marker in (
            "auth",
            "unauthorized",
            "forbidden",
            "login",
            "cookie",
            "token",
            "credential",
            "permission",
        )
    ):
        return "AUTH"
    if any(
        marker in haystack
        for marker in (
            "json",
            "decode",
            "parse",
            "parser",
            "schema",
            "validation",
            "keyerror",
            "valueerror",
            "typeerror",
            "indexerror",
        )
    ):
        return "PARSER"
    if any(
        marker in haystack
        for marker in (
            "network",
            "connection",
            "timeout",
            "timed out",
            "dns",
            "ssl",
            "502",
            "503",
            "504",
            "refused",
            "reset",
            "unreachable",
            "fetch failed",
        )
    ):
        return "NETWORK"
    return "UNKNOWN"


def _classify_job_error(exc: Exception) -> tuple[str, str, bool]:
    message = str(exc).lower()
    error_class = exc.__class__.__name__
    transient_markers = (
        "timeout",
        "temporar",
        "connection",
        "network",
        "429",
        "http_500",
        "502",
        "503",
        "504",
        "rate limit",
        "json",
        "decode",
        "unexpected",
        "login_required",
    )
    if _is_retryable_mirror_reason(message) or any(marker in message for marker in transient_markers):
        return "transient_error", error_class, True
    return "fatal_error", error_class, False


def _run_platform_media_mirror_stage(
    *,
    context: SeasonContext,
    platform: str,
    job_id: str,
    config: dict[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    def _heartbeat() -> None:
        _touch_job_heartbeat(job_id)

    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    source_id_column = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    posted_at_column = PLATFORM_POSTED_AT_COLUMN.get(normalized_platform)
    if not table or not source_id_column or not posted_at_column:
        raise ValueError(f"mirror_platform_not_supported:{platform}")

    post_id = str(config.get("post_id") or "").strip()
    if not post_id:
        raise ValueError("mirror_missing_post_id")

    thumbnail_expr = (
        "coalesce(nullif(p.media_urls ->> 0, ''), '') as thumbnail_url"
        if normalized_platform == "twitter"
        else "coalesce(nullif(p.thumbnail_url, ''), '') as thumbnail_url"
    )
    media_urls_expr = (
        "p.media_urls as media_urls"
        if _platform_posts_has_column(normalized_platform, "media_urls")
        else "'[]'::jsonb as media_urls"
    )
    asset_manifest_expr = (
        "coalesce(to_jsonb(p) -> 'asset_manifest', '{}'::jsonb) as asset_manifest"
        if _platform_posts_has_column(normalized_platform, "asset_manifest")
        else "'{}'::jsonb as asset_manifest"
    )
    username_expr = (
        "coalesce(nullif(p.channel_title, ''), nullif(p.source_account, ''), '') as post_username"
        if normalized_platform == "youtube"
        else "coalesce(nullif(p.username, ''), nullif(p.source_account, ''), '') as post_username"
    )

    post_row = pg.fetch_one(
        f"""
        select
          p.id::text as id,
          p.{source_id_column} as source_id,
          {thumbnail_expr},
          {media_urls_expr},
          {asset_manifest_expr},
          {username_expr},
          coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data,
          p.{posted_at_column} as posted_at,
          coalesce(to_jsonb(p) ->> 'hosted_thumbnail_url', '') as hosted_thumbnail_url,
          coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(p) ->> 'media_mirror_status', '') as media_mirror_status,
          coalesce(to_jsonb(p) ->> 'media_mirror_error', '') as media_mirror_error,
          coalesce(to_jsonb(p) ->> 'user_avatar_url', '') as user_avatar_url,
          coalesce(to_jsonb(p) ->> 'hosted_user_avatar_url', '') as hosted_user_avatar_url,
          coalesce(to_jsonb(p) ->> 'owner_profile_pic_url', '') as owner_profile_pic_url,
          coalesce(to_jsonb(p) ->> 'hosted_owner_profile_pic_url', '') as hosted_owner_profile_pic_url,
          coalesce(to_jsonb(p) -> 'hosted_tagged_profile_pics', '{{}}'::jsonb) as hosted_tagged_profile_pics
        from social.{table} p
        where p.id = %s::uuid
        """,
        [post_id],
    )
    _heartbeat()
    if not post_row:
        raise ValueError(f"mirror_post_not_found:{post_id}")

    repair_reasons = _platform_post_repair_reasons(normalized_platform, post_row)
    need_media_asset_repair = _platform_post_needs_media_asset_repair(normalized_platform, post_row)
    need_meta_refresh = _platform_post_has_stale_media_asset_meta(post_row)

    if not repair_reasons:
        hosted_media_urls = _as_text_list(post_row.get("hosted_media_urls"))
        hosted_thumbnail_url = str(post_row.get("hosted_thumbnail_url") or "").strip() or None
        mirrored_count = len(hosted_media_urls) + (1 if hosted_thumbnail_url else 0)
        return (
            1,
            mirrored_count,
            {
                "activity": {"phase": "media_mirror_skipped", "last_progress_at": _iso(_now_utc())},
                "mirror": {
                    "status": "skipped",
                    "error": None,
                    "reason": "already_mirrored",
                    "repair_reasons": [],
                    "selected_source": None,
                    "attempts": [],
                },
            },
        )

    source_id = str(post_row.get("source_id") or "").strip()
    source_thumbnail_url, source_media_urls = _platform_post_source_urls(normalized_platform, post_row)
    source_media_asset_meta: dict[str, Any] = {}

    # Compute structured display name for S3 file naming
    _show_slug = _resolve_show_slug(context)
    _post_username = _resolve_post_username(normalized_platform, post_row)
    _posted_at_dt = _coerce_dt(post_row.get("posted_at"))
    _post_number = (
        _compute_daily_post_number(normalized_platform, context.season_id, _post_username, _posted_at_dt, source_id)
        if _posted_at_dt
        else 1
    )
    _display_name = _build_post_display_name(
        show_slug=_show_slug,
        username=_post_username,
        platform=normalized_platform,
        post_number=_post_number,
    )

    mirror_selected_source: str | None = None
    mirror_attempts: list[dict[str, Any]] = []
    mirror_status = str(post_row.get("media_mirror_status") or "").strip().lower()
    raw_data = post_row.get("raw_data") if isinstance(post_row.get("raw_data"), dict) else {}
    resolved_avatar_hint = ""
    source_media_needs_quality_repair = _source_media_urls_need_quality_repair(
        platform=normalized_platform,
        source_media_urls=source_media_urls,
    )
    if normalized_platform == "instagram" and need_media_asset_repair:
        media_meta = (raw_data or {}).get("media_retrieval_meta") if isinstance(raw_data, dict) else None
        if isinstance(media_meta, dict):
            mirror_selected_source = str(media_meta.get("selected_source") or "") or None
            mirror_attempts = _normalize_instagram_mirror_attempts(media_meta.get("attempts"))

        needs_re_resolve = (
            (not source_thumbnail_url and not source_media_urls)
            or mirror_status
            in {
                "failed",
                "partial",
            }
            or source_media_needs_quality_repair
        )
        if needs_re_resolve and source_id:
            _heartbeat()
            try:
                resolution_payload = _resolve_instagram_media_for_shortcode(shortcode=source_id)
                _heartbeat()
                resolved_media_urls = _normalize_unique_terms(
                    [str(url).strip() for url in (resolution_payload.get("media_urls") or []) if str(url).strip()]
                )
                resolved_thumbnail_url = str(resolution_payload.get("thumbnail_url") or "").strip()
                mirror_selected_source = str(resolution_payload.get("source") or "") or mirror_selected_source
                mirror_attempts = _normalize_instagram_mirror_attempts(resolution_payload.get("attempts"))
                source_media_asset_meta = dict(resolution_payload.get("media_asset_meta") or {})
                if resolved_thumbnail_url or resolved_media_urls:
                    source_thumbnail_url = resolved_thumbnail_url or (
                        resolved_media_urls[0] if resolved_media_urls else ""
                    )
                    source_media_urls = resolved_media_urls
                    _update_instagram_post_source_media_fields(
                        post_id=post_id,
                        thumbnail_url=source_thumbnail_url or FIELD_UNSET,
                        media_urls=source_media_urls or FIELD_UNSET,
                    )
            except Exception as exc:  # noqa: BLE001
                if not mirror_attempts:
                    mirror_attempts = [
                        {
                            "source": "api_media_info",
                            "success": False,
                            "reason_code": "instagram_api_failed",
                            "http_status": None,
                            "selected_url_count": 0,
                            "error_type": exc.__class__.__name__,
                            "error_message": str(exc)[:240],
                        }
                    ]
    elif normalized_platform == "tiktok" and need_media_asset_repair:
        needs_re_resolve = (
            (not source_media_urls)
            or mirror_status
            in {
                "failed",
                "partial",
            }
            or source_media_needs_quality_repair
        )
        if needs_re_resolve and source_id:
            _heartbeat()
            try:
                canonical_url = str(raw_data.get("url") or "").strip() if isinstance(raw_data, dict) else ""
                if not canonical_url and isinstance(raw_data, dict):
                    username = str(raw_data.get("username") or "").strip().lstrip("@")
                    if username:
                        canonical_url = f"https://www.tiktok.com/@{username}/video/{source_id}"
                allow_ytdlp = bool(source_media_needs_quality_repair or not source_media_urls)
                resolution_payload = _resolve_tiktok_media_for_video_id(
                    video_id=source_id,
                    canonical_url=canonical_url or None,
                    allow_ytdlp=allow_ytdlp,
                    validate_download_url=False,
                )
                _heartbeat()
                resolved_media_urls = _normalize_unique_terms(
                    [str(url).strip() for url in (resolution_payload.get("media_urls") or []) if str(url).strip()]
                )
                resolved_thumbnail_url = str(resolution_payload.get("thumbnail_url") or "").strip()
                mirror_selected_source = str(resolution_payload.get("source") or "") or mirror_selected_source
                mirror_attempts = _normalize_instagram_mirror_attempts(resolution_payload.get("attempts"))
                source_media_asset_meta = dict(resolution_payload.get("media_asset_meta") or {})
                if resolved_thumbnail_url:
                    source_thumbnail_url = resolved_thumbnail_url
                    # Persist resolved thumbnail back to the post row so it's
                    # available to the week-detail query even before S3 mirroring.
                    try:
                        _update_platform_post_field(
                            platform="tiktok",
                            post_id=post_id,
                            field="thumbnail_url",
                            value=resolved_thumbnail_url,
                        )
                    except Exception:  # noqa: BLE001
                        pass
                # Persist resolved author avatar if the resolver captured one.
                resolved_avatar_url = str(resolution_payload.get("author_avatar_url") or "").strip()
                if resolved_avatar_url:
                    resolved_avatar_hint = resolved_avatar_url
                if resolved_avatar_url:
                    try:
                        _update_platform_post_field(
                            platform="tiktok",
                            post_id=post_id,
                            field="user_avatar_url",
                            value=resolved_avatar_url,
                        )
                    except Exception:  # noqa: BLE001
                        pass
                if allow_ytdlp and canonical_url:
                    # Prefer canonical page URL so media download can use yt-dlp fallback.
                    source_media_urls = [canonical_url]
                elif resolved_media_urls:
                    source_media_urls = resolved_media_urls
                elif canonical_url:
                    source_media_urls = [canonical_url]
            except Exception as exc:  # noqa: BLE001
                if not mirror_attempts:
                    mirror_attempts = [
                        {
                            "source": "watch_page_json",
                            "success": False,
                            "reason_code": "tiktok_media_resolve_failed",
                            "http_status": None,
                            "selected_url_count": 0,
                            "error_type": exc.__class__.__name__,
                            "error_message": str(exc)[:240],
                        }
                    ]
    elif normalized_platform == "youtube" and need_media_asset_repair:
        needs_re_resolve = (
            (not source_media_urls)
            or mirror_status
            in {
                "failed",
                "partial",
            }
            or source_media_needs_quality_repair
        )
        if needs_re_resolve and source_id:
            _heartbeat()
            try:
                resolution_payload = _resolve_youtube_media_for_video_id(video_id=source_id)
                _heartbeat()
                resolved_media_urls = _normalize_unique_terms(
                    [str(url).strip() for url in (resolution_payload.get("media_urls") or []) if str(url).strip()]
                )
                resolved_thumbnail_url = str(resolution_payload.get("thumbnail_url") or "").strip()
                mirror_selected_source = str(resolution_payload.get("source") or "") or mirror_selected_source
                mirror_attempts = _normalize_instagram_mirror_attempts(resolution_payload.get("attempts"))
                source_media_asset_meta = dict(resolution_payload.get("media_asset_meta") or {})
                resolved_avatar_hint = str(resolution_payload.get("author_avatar_url") or "").strip()
                if resolved_thumbnail_url:
                    source_thumbnail_url = resolved_thumbnail_url
                canonical_watch_url = f"https://www.youtube.com/watch?v={source_id}" if source_id else ""
                if resolved_media_urls and not _source_media_urls_need_quality_repair(
                    platform="youtube",
                    source_media_urls=resolved_media_urls,
                ):
                    source_media_urls = resolved_media_urls
                elif canonical_watch_url:
                    source_media_urls = [canonical_watch_url]
            except Exception as exc:  # noqa: BLE001
                if not mirror_attempts:
                    mirror_attempts = [
                        {
                            "source": "watch_page_streaming_data",
                            "success": False,
                            "reason_code": "youtube_media_resolve_failed",
                            "http_status": None,
                            "selected_url_count": 0,
                            "error_type": exc.__class__.__name__,
                            "error_message": str(exc)[:240],
                        }
                    ]
    elif normalized_platform == "twitter" and need_media_asset_repair:
        source_has_video = any(_is_video_like_media_url(url) for url in source_media_urls)
        source_has_only_thumb_placeholders = bool(source_media_urls) and all(
            _is_twitter_thumb_placeholder_url(url) for url in source_media_urls
        )
        needs_re_resolve = (
            (not source_media_urls)
            or (mirror_status in {"failed", "partial"})
            or (source_has_only_thumb_placeholders and not source_has_video)
            or source_media_needs_quality_repair
        )
        if needs_re_resolve and source_id:
            _heartbeat()
            try:
                from trr_backend.socials.twitter import TwitterScraper

                twitter_cookies, twitter_bearer = _load_twitter_auth()
                twikit_creds = _load_twikit_credentials()
                if not twitter_cookies.get("ct0") and twikit_creds:
                    if twikit_creds.get("auth_token") and twikit_creds.get("ct0"):
                        twitter_cookies = {
                            **twitter_cookies,
                            "auth_token": twikit_creds["auth_token"],
                            "ct0": twikit_creds["ct0"],
                        }
                scraper = TwitterScraper(
                    cookies=twitter_cookies,
                    bearer_token=twitter_bearer,
                    twikit_credentials=twikit_creds,
                )
                summary = _fetch_and_apply_twitter_metric_summary(scraper=scraper, tweet_id=source_id) or {}
                _heartbeat()
                resolved_media_urls = _merge_twitter_media_urls(
                    source_media_urls,
                    list(summary.get("media_urls") or []),
                )
                if resolved_media_urls:
                    source_media_urls = resolved_media_urls
                    source_thumbnail_url = _select_thumbnail_candidate(
                        resolved_media_urls,
                        fallback=source_thumbnail_url,
                    )
                    mirror_selected_source = "merged_tweet_summary"
                    mirror_attempts = [
                        {
                            "source": "merged_tweet_summary",
                            "success": True,
                            "reason_code": None,
                            "http_status": None,
                            "selected_url_count": len(resolved_media_urls),
                            "error_type": None,
                            "error_message": None,
                        }
                    ]
            except Exception as exc:  # noqa: BLE001
                if not mirror_attempts:
                    mirror_attempts = [
                        {
                            "source": "merged_tweet_summary",
                            "success": False,
                            "reason_code": "twitter_media_resolve_failed",
                            "http_status": None,
                            "selected_url_count": 0,
                            "error_type": exc.__class__.__name__,
                            "error_message": str(exc)[:240],
                        }
                    ]
    elif normalized_platform == "threads" and need_media_asset_repair:
        needs_re_resolve = (
            (not source_media_urls) or (mirror_status in {"failed", "partial"}) or source_media_needs_quality_repair
        )
        if needs_re_resolve and source_id:
            _heartbeat()
            try:
                from trr_backend.socials.threads.media_resolver import resolve_threads_media

                raw_data = config.get("_raw_data")
                if not isinstance(raw_data, dict) or not raw_data:
                    raw_data = post_row.get("raw_data") if isinstance(post_row.get("raw_data"), dict) else {}
                resolution = resolve_threads_media(_as_string_mapping(raw_data), validate_urls=False)
                _heartbeat()
                if resolution.media_urls:
                    source_media_urls = resolution.media_urls
                    source_thumbnail_url = resolution.thumbnail_url or _select_thumbnail_candidate(
                        resolution.media_urls,
                        fallback=source_thumbnail_url,
                    )
                    mirror_selected_source = resolution.source or "threads_graphql_post_data"
                    source_media_asset_meta = dict(getattr(resolution, "media_asset_meta", {}) or {})
                    mirror_attempts = [a for a in resolution.attempts if a.get("success")]
                    if not mirror_attempts:
                        mirror_attempts = resolution.attempts[:1] or [
                            {
                                "source": "threads_graphql_post_data",
                                "success": True,
                                "reason_code": None,
                                "http_status": None,
                                "selected_url_count": len(resolution.media_urls),
                                "error_type": None,
                                "error_message": None,
                            }
                        ]
            except Exception as exc:  # noqa: BLE001
                if not mirror_attempts:
                    mirror_attempts = [
                        {
                            "source": "threads_graphql_post_data",
                            "success": False,
                            "reason_code": "threads_media_resolve_failed",
                            "http_status": None,
                            "selected_url_count": 0,
                            "error_type": exc.__class__.__name__,
                            "error_message": str(exc)[:240],
                        }
                    ]
    attempt_count = max(1, _normalize_non_negative_int(config.get("_attempt_count")))
    now_utc = _now_utc()
    if need_media_asset_repair:
        reuse_result = _try_build_social_media_reuse_result_from_existing_hashes(
            context=context,
            platform=normalized_platform,
            post_row=post_row,
            generated_at=cast(str, _iso(now_utc)),
        )
        if reuse_result:
            _update_platform_post_media_mirror_fields(
                platform=normalized_platform,
                post_id=post_id,
                hosted_thumbnail_url=(
                    reuse_result.get("hosted_thumbnail_url")
                    if reuse_result.get("hosted_thumbnail_url") is not None
                    else FIELD_UNSET
                ),
                hosted_media_urls=list(reuse_result.get("hosted_media_urls") or []),
                media_mirror_status="mirrored",
                media_mirror_error=None,
                media_mirror_last_attempt_at=now_utc,
                media_mirror_attempt_count=attempt_count,
                media_mirror_last_job_id=job_id,
            )
            _update_platform_post_media_asset_meta(
                platform=normalized_platform,
                post_id=post_id,
                media_asset_meta=dict(reuse_result.get("asset_manifest") or {}),
            )
            _heartbeat()
            return (
                1,
                int(reuse_result.get("mirrored_count") or 0),
                {
                    "activity": {"phase": "media_mirror_end", "last_progress_at": _iso(now_utc)},
                    "mirror": {
                        "status": "mirrored",
                        "error": None,
                        "selected_source": "exact_sha256_reuse",
                        "attempts": [],
                        "storage_summary": {
                            "original_bytes": int(reuse_result.get("original_bytes") or 0),
                            "variant_bytes": int(reuse_result.get("variant_bytes") or 0),
                            "object_count": int(reuse_result.get("object_count") or 0),
                            "variant_count": int(reuse_result.get("variant_count") or 0),
                            "cdn_url_count": int(reuse_result.get("cdn_url_count") or 0),
                        },
                        "media_reuse": (reuse_result.get("asset_manifest") or {}).get("media_reuse"),
                    },
                },
            )
    if need_media_asset_repair:
        _update_platform_post_media_mirror_fields(
            platform=normalized_platform,
            post_id=post_id,
            media_mirror_status="pending",
            media_mirror_last_attempt_at=now_utc,
            media_mirror_attempt_count=attempt_count,
            media_mirror_last_job_id=job_id,
        )
        _heartbeat()
    source_asset_records: list[dict[str, Any]] = []
    source_assets_raw = source_media_asset_meta.get("source_assets")
    if isinstance(source_assets_raw, list):
        source_asset_records = [
            dict(item) for item in source_assets_raw if isinstance(item, dict) and str(item.get("url") or "").strip()
        ]
    if not source_asset_records:
        source_asset_records = [
            {
                "url": str(url).strip(),
                "type": "video" if _is_video_like_media_url(str(url).strip()) else "image",
                "width": None,
                "height": None,
                "resolution": None,
                "fps": None,
                "bitrate": None,
                "duration_seconds": None,
            }
            for url in source_media_urls
            if str(url).strip()
        ]
    thumbnail_source = source_media_asset_meta.get("thumbnail_source")
    if not isinstance(thumbnail_source, dict):
        thumbnail_source = (
            {
                "url": source_thumbnail_url,
                "type": "thumbnail",
                "width": None,
                "height": None,
                "resolution": None,
            }
            if source_thumbnail_url
            and not (
                normalized_platform == "youtube"
                and (
                    source_thumbnail_url in source_media_urls
                    or _is_page_like_media_url(source_thumbnail_url)
                    or _is_video_like_media_url(source_thumbnail_url)
                )
            )
            else None
        )

    source_media_still_needs_quality_repair = _source_media_urls_need_quality_repair(
        platform=normalized_platform,
        source_media_urls=source_media_urls,
    )
    source_media_supports_ytdlp = _source_media_urls_support_ytdlp_mirror(
        platform=normalized_platform,
        source_media_urls=source_media_urls,
    )
    missing_source_media = (not source_thumbnail_url and not source_media_urls) or (
        source_media_still_needs_quality_repair and not source_media_supports_ytdlp
    )
    youtube_media_missing = normalized_platform == "youtube" and (
        not source_media_urls or (source_media_still_needs_quality_repair and not source_media_supports_ytdlp)
    )
    if need_media_asset_repair and (missing_source_media or youtube_media_missing):
        if source_media_still_needs_quality_repair:
            missing_reason = f"{normalized_platform}_media_unresolved"
        elif normalized_platform == "instagram":
            missing_reason = "instagram_media_not_found"
        elif normalized_platform == "tiktok":
            missing_reason = "tiktok_media_not_found"
        elif normalized_platform == "youtube":
            missing_reason = "youtube_media_not_found"
        elif normalized_platform == "threads":
            missing_reason = "threads_media_not_found"
        else:
            missing_reason = "no_source_media"
        if normalized_platform == "instagram" and not mirror_attempts:
            mirror_attempts = [
                {
                    "source": "api_media_info",
                    "success": False,
                    "reason_code": "instagram_media_not_found",
                    "http_status": None,
                    "selected_url_count": 0,
                    "error_type": None,
                    "error_message": None,
                }
            ]
        if normalized_platform == "youtube" and not mirror_attempts:
            mirror_attempts = [
                {
                    "source": "watch_page_streaming_data",
                    "success": False,
                    "reason_code": "youtube_media_not_found",
                    "http_status": None,
                    "selected_url_count": 0,
                    "error_type": None,
                    "error_message": None,
                }
            ]
        if normalized_platform == "tiktok" and not mirror_attempts:
            mirror_attempts = [
                {
                    "source": "watch_page_json",
                    "success": False,
                    "reason_code": "tiktok_media_not_found",
                    "http_status": None,
                    "selected_url_count": 0,
                    "error_type": None,
                    "error_message": None,
                }
            ]
        quarantine_failed_hosted_media = _repair_reasons_target_bad_hosted_media(repair_reasons)
        _update_platform_post_media_mirror_fields(
            platform=normalized_platform,
            post_id=post_id,
            hosted_thumbnail_url=None if quarantine_failed_hosted_media else FIELD_UNSET,
            hosted_media_urls=[] if quarantine_failed_hosted_media else FIELD_UNSET,
            media_mirror_status="failed",
            media_mirror_error=missing_reason,
            media_mirror_last_attempt_at=now_utc,
            media_mirror_attempt_count=attempt_count,
            media_mirror_last_job_id=job_id,
        )
        return (
            1,
            0,
            {
                "activity": {"phase": "media_mirror_end", "last_progress_at": _iso(now_utc)},
                "mirror": {
                    "status": "failed",
                    "error": missing_reason,
                    "selected_source": mirror_selected_source,
                    "attempts": mirror_attempts,
                    "storage_summary": {
                        "original_bytes": 0,
                        "variant_bytes": 0,
                        "object_count": 0,
                        "variant_count": 0,
                        "cdn_url_count": 0,
                    },
                },
            },
        )

    week_index_raw = config.get("week_index")
    week_index: int | None = None
    if week_index_raw is not None and str(week_index_raw).strip():
        try:
            week_index = int(week_index_raw)
        except (TypeError, ValueError):
            week_index = None

    if week_index is None:
        posted_at = _coerce_dt(post_row.get("posted_at"))
        if posted_at is not None:
            try:
                windows, _ = _resolve_week_windows(
                    context,
                    timezone="America/New_York",
                    source_scope=str(config.get("source_scope") or "network"),
                    now_utc=_now_utc(),
                )
                week_window = _week_for_timestamp(posted_at, windows=windows, timezone="America/New_York")
                week_index = week_window.week_index if week_window else None
            except Exception:  # noqa: BLE001
                week_index = None

    mirror_post = {
        "id": post_id,
        "shortcode": source_id,
        "video_id": source_id,
        "tweet_id": source_id,
        "thumbnail_url": source_thumbnail_url,
        "media_urls": source_media_urls,
    }
    if need_media_asset_repair:
        _tweet_url = f"https://x.com/i/status/{source_id}" if normalized_platform == "twitter" and source_id else None
        mirror_kwargs = {
            "platform": normalized_platform,
            "post": SimpleNamespace(**mirror_post),
            "week_index": week_index,
            "display_name": _display_name,
            "tweet_url": _tweet_url,
            "progress_cb": _heartbeat,
        }
        try:
            result = _mirror_platform_media_to_s3_result(context, **mirror_kwargs)
        except TypeError as exc:
            if "progress_cb" not in str(exc):
                raise
            mirror_kwargs.pop("progress_cb", None)
            result = _mirror_platform_media_to_s3_result(context, **mirror_kwargs)
        _heartbeat()
        quarantine_failed_hosted_media = _should_quarantine_hosted_media_after_mirror_result(
            result=result,
            repair_reasons=repair_reasons,
        )
        next_hosted_thumbnail_url: str | None | object = (
            result.get("hosted_thumbnail_url") if result.get("hosted_thumbnail_url") is not None else FIELD_UNSET
        )
        next_hosted_media_urls: list[str] | object = (
            list(result.get("hosted_media_urls") or []) if result.get("hosted_media_urls") else FIELD_UNSET
        )
        if quarantine_failed_hosted_media:
            if next_hosted_thumbnail_url is FIELD_UNSET:
                next_hosted_thumbnail_url = None
            if next_hosted_media_urls is FIELD_UNSET:
                next_hosted_media_urls = []
        _update_platform_post_media_mirror_fields(
            platform=normalized_platform,
            post_id=post_id,
            hosted_thumbnail_url=next_hosted_thumbnail_url,
            hosted_media_urls=next_hosted_media_urls,
            media_mirror_status=str(result.get("status") or "") or None,
            media_mirror_error=str(result.get("error") or "") or None,
            media_mirror_last_attempt_at=now_utc,
            media_mirror_attempt_count=attempt_count,
            media_mirror_last_job_id=job_id,
        )
        hosted_media_urls = [str(url).strip() for url in (result.get("hosted_media_urls") or []) if str(url).strip()]
        hosted_thumbnail_url = str(result.get("hosted_thumbnail_url") or "").strip() or None
    else:
        hosted_media_urls = _as_text_list(post_row.get("hosted_media_urls"))
        hosted_thumbnail_url = str(post_row.get("hosted_thumbnail_url") or "").strip() or None
        result = {
            "status": "up_to_date",
            "error": None,
            "mirrored_count": len(hosted_media_urls) + (1 if hosted_thumbnail_url else 0),
            "source_count": len(source_media_urls) + (1 if source_thumbnail_url else 0),
            "retryable_error": False,
        }
    hosted_assets = [
        {
            "url": hosted_url,
            "type": "video" if _is_video_like_media_url(hosted_url) else "image",
            "width": None,
            "height": None,
            "resolution": None,
            "fps": None,
            "bitrate": None,
            "duration_seconds": None,
        }
        for hosted_url in hosted_media_urls
    ]
    thumbnail_hosted = (
        {
            "url": hosted_thumbnail_url,
            "type": "thumbnail",
            "width": None,
            "height": None,
            "resolution": None,
        }
        if hosted_thumbnail_url
        else None
    )
    if need_media_asset_repair or need_meta_refresh:
        result_manifest = result.get("asset_manifest") if isinstance(result.get("asset_manifest"), dict) else {}
        storage_summary = dict(result_manifest.get("storage_summary") or {}) if result_manifest else {}
        media_asset_meta = {
            **dict(result_manifest or {}),
            "selection_policy": str(
                (result_manifest or {}).get("selection_policy") or "best_per_role_with_cover_display_variants"
            ),
            "selected_source": mirror_selected_source,
            "source_assets": source_asset_records,
            "thumbnail_source": thumbnail_source,
            "hosted_assets": hosted_assets,
            "thumbnail_hosted": thumbnail_hosted,
            "storage_summary": {
                **storage_summary,
                "original_bytes": _normalize_non_negative_int(result.get("original_bytes")),
                "variant_bytes": _normalize_non_negative_int(result.get("variant_bytes")),
                "object_count": _normalize_non_negative_int(result.get("object_count")),
                "variant_count": _normalize_non_negative_int(result.get("variant_count")),
                "cdn_url_count": _normalize_non_negative_int(result.get("cdn_url_count")),
            },
            "updated_at": _iso(now_utc),
        }
        _update_platform_post_media_asset_meta(
            platform=normalized_platform,
            post_id=post_id,
            media_asset_meta=media_asset_meta,
        )

    if bool(result.get("retryable_error")) and str(result.get("status") or "") in {"partial", "failed"}:
        raise RuntimeError(str(result.get("error") or "media_mirror_retryable"))

    avatar_recovery_result = _recover_platform_post_source_avatar(
        platform=normalized_platform,
        post_id=post_id,
        post_row=post_row,
        source_id=source_id,
        fallback_avatar_url=resolved_avatar_hint or None,
    )

    # Profile picture mirroring (Instagram only, migration 0147)
    profile_pic_result: dict[str, Any] | None = None
    if normalized_platform == "instagram" and _instagram_posts_has_column("hosted_owner_profile_pic_url"):
        try:
            # Build a lightweight post object with the detail attributes from raw_data
            profile_post = SimpleNamespace(
                owner_detail=None,
                tagged_users_detail=[],
                collaborators_detail=[],
                mentions=[],
            )
            # Extract owner detail from raw_data
            rd = raw_data if isinstance(raw_data, dict) else {}
            owner_detail_raw = rd.get("owner_detail")
            if isinstance(owner_detail_raw, dict) and owner_detail_raw.get("username"):
                profile_post.owner_detail = SimpleNamespace(**owner_detail_raw)
                if (
                    not getattr(profile_post.owner_detail, "profile_pic_url", None)
                    and str(post_row.get("owner_profile_pic_url") or "").strip()
                ):
                    profile_post.owner_detail.profile_pic_url = str(post_row.get("owner_profile_pic_url") or "").strip()
            elif rd.get("username"):
                profile_post.owner_detail = SimpleNamespace(
                    username=str(rd.get("username") or ""),
                    profile_pic_url=str(post_row.get("owner_profile_pic_url") or "").strip() or None,
                    full_name=None,
                    user_id=None,
                    is_verified=None,
                )

            for attr in ("tagged_users_detail", "collaborators_detail"):
                detail_list = rd.get(attr)
                if isinstance(detail_list, list):
                    setattr(
                        profile_post,
                        attr,
                        [SimpleNamespace(**u) for u in detail_list if isinstance(u, dict) and u.get("username")],
                    )
            profile_post.mentions = _as_text_list(
                rd.get("mentions") if isinstance(rd, dict) else [],
                prefix="@",
                strip_prefix="@",
            )

            include_comment_avatars = _env_truthy("SOCIAL_INSTAGRAM_MEDIA_MIRROR_COMMENT_AVATARS", default=False)
            has_any_profile_target = (
                (profile_post.owner_detail and getattr(profile_post.owner_detail, "profile_pic_url", None))
                or any(getattr(u, "profile_pic_url", None) for u in profile_post.tagged_users_detail)
                or any(getattr(u, "profile_pic_url", None) for u in profile_post.collaborators_detail)
                or bool(profile_post.mentions)
                or (include_comment_avatars and bool(post_id))
            )
            if has_any_profile_target:
                profile_pic_result = _mirror_instagram_profile_pics_for_post(
                    post_row,
                    post=profile_post,
                    progress_cb=_heartbeat,
                )
                _update_instagram_profile_pic_mirror_fields(
                    post_id=post_id,
                    hosted_owner_profile_pic_url=profile_pic_result.get("hosted_owner_profile_pic_url"),
                    hosted_tagged_profile_pics=profile_pic_result.get("hosted_tagged_profile_pics"),
                    profile_pic_mirror_status=profile_pic_result.get("profile_pic_mirror_status"),
                    profile_pic_mirror_error=profile_pic_result.get("profile_pic_mirror_error"),
                )
        except Exception as exc:  # noqa: BLE001
            logger.warning("Failed to mirror Instagram profile pics for post %s: %s", post_id, exc)

    # Cross-platform author avatar mirroring (migration 0164)
    # Mirrors one avatar per account; content-addressed S3 keys preserve old avatars.
    avatar_mirror_result: dict[str, Any] | None = None
    if normalized_platform != "instagram" and _platform_posts_has_column(normalized_platform, "hosted_user_avatar_url"):
        existing_hosted_avatar = str(post_row.get("hosted_user_avatar_url") or "").strip()
        source_avatar = str(
            _resolve_post_avatar_url(
                hosted_avatar_url=None,
                direct_avatar_url=post_row.get("user_avatar_url"),
                raw_data=post_row.get("raw_data"),
            )
            or ""
        ).strip()
        if source_avatar:
            try:
                post_username = str(post_row.get("post_username") or "").strip()
                hosted_avatar = _mirror_post_author_avatar_to_s3(
                    platform=normalized_platform,
                    username=post_username or source_id or "unknown",
                    source_avatar_url=source_avatar,
                    progress_cb=_heartbeat,
                )
                if hosted_avatar:
                    if hosted_avatar != existing_hosted_avatar:
                        _update_post_hosted_avatar(
                            platform=normalized_platform,
                            post_id=post_id,
                            hosted_user_avatar_url=hosted_avatar,
                        )
                    avatar_mirror_result = {
                        "hosted_url": hosted_avatar,
                        "status": ("mirrored" if hosted_avatar != existing_hosted_avatar else "up_to_date"),
                    }
                else:
                    avatar_mirror_result = {"hosted_url": None, "status": "failed"}
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "Failed to mirror %s avatar for post %s: %s",
                    normalized_platform,
                    post_id,
                    exc,
                )
                avatar_mirror_result = {"hosted_url": None, "status": "failed", "error": str(exc)[:240]}

    if not need_media_asset_repair:
        auxiliary_error = None
        profile_status = str((profile_pic_result or {}).get("profile_pic_mirror_status") or "").strip().lower()
        avatar_status = str((avatar_mirror_result or {}).get("status") or "").strip().lower()
        if profile_status == "failed":
            auxiliary_error = str((profile_pic_result or {}).get("profile_pic_mirror_error") or "").strip()
        if not auxiliary_error and avatar_status == "failed":
            auxiliary_error = str((avatar_mirror_result or {}).get("error") or "avatar_mirror_failed").strip()
        _update_platform_post_media_mirror_fields(
            platform=normalized_platform,
            post_id=post_id,
            media_mirror_status="failed" if auxiliary_error else str(result.get("status") or "up_to_date"),
            media_mirror_error=auxiliary_error or None,
            media_mirror_last_attempt_at=now_utc,
            media_mirror_attempt_count=attempt_count,
            media_mirror_last_job_id=job_id,
        )

    mirrored_assets = _normalize_non_negative_int(result.get("mirrored_count"))
    source_asset_count = _normalize_non_negative_int(result.get("source_count"))
    metadata = {
        "activity": {"phase": "media_mirror_end", "last_progress_at": _iso(now_utc)},
        "mirror": {
            "platform": normalized_platform,
            "post_id": post_id,
            "source_id": source_id,
            "status": str(result.get("status") or ""),
            "error": str(result.get("error") or "") or None,
            "mirrored_assets": mirrored_assets,
            "source_assets": source_asset_count,
            "week_index": week_index,
            "selected_source": mirror_selected_source,
            "attempts": mirror_attempts,
            "storage_summary": {
                "original_bytes": _normalize_non_negative_int(result.get("original_bytes")),
                "variant_bytes": _normalize_non_negative_int(result.get("variant_bytes")),
                "object_count": _normalize_non_negative_int(result.get("object_count")),
                "variant_count": _normalize_non_negative_int(result.get("variant_count")),
                "cdn_url_count": _normalize_non_negative_int(result.get("cdn_url_count")),
            },
        },
    }
    if profile_pic_result:
        metadata["profile_pic_mirror"] = {
            "status": profile_pic_result.get("profile_pic_mirror_status"),
            "error": profile_pic_result.get("profile_pic_mirror_error"),
            "owner_mirrored": bool(profile_pic_result.get("hosted_owner_profile_pic_url")),
            "tagged_mirrored": len(profile_pic_result.get("hosted_tagged_profile_pics") or {}),
        }
    if avatar_recovery_result:
        metadata["avatar_recovery"] = {
            "status": avatar_recovery_result.get("status"),
            "persisted": bool(avatar_recovery_result.get("persisted")),
            "recovery_source": avatar_recovery_result.get("recovery_source"),
            "error": avatar_recovery_result.get("error"),
        }
    if avatar_mirror_result:
        metadata["avatar_mirror"] = {
            "status": avatar_mirror_result.get("status"),
            "mirrored": bool(avatar_mirror_result.get("hosted_url")),
            "error": avatar_mirror_result.get("error"),
        }
    metadata["mirror"]["repair_reasons"] = repair_reasons
    return 1, mirrored_assets, metadata


def _run_tiktok_comment_media_mirror_stage(
    *,
    context: SeasonContext,
    job_id: str,
    config: dict[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    if not _tiktok_comments_has_column("media_urls"):
        return (
            0,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "skipped",
                    "error": "tiktok_comment_media_columns_missing",
                },
            },
        )

    comment_id = str(config.get("comment_id") or "").strip()
    comment_db_id = str(config.get("comment_db_id") or "").strip()
    if not comment_id and not comment_db_id:
        raise ValueError("comment_media_mirror_missing_comment_id")

    comment_row = pg.fetch_one(
        """
        select
          c.id::text as id,
          c.comment_id,
          c.post_id::text as post_id,
          coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
          coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status,
          coalesce(to_jsonb(c) ->> 'media_mirror_error', '') as media_mirror_error,
          p.video_id as video_id,
          p.posted_at
        from social.tiktok_comments c
        left join social.tiktok_posts p on p.id = c.post_id
        where c.season_id = %s
          and (
            (%s <> '' and c.comment_id = %s)
            or (%s <> '' and c.id = nullif(%s, '')::uuid)
          )
        order by c.created_at desc nulls last
        limit 1
        """,
        [context.season_id, comment_id, comment_id, comment_db_id, comment_db_id],
    )
    if not comment_row:
        raise ValueError("comment_media_mirror_comment_not_found")

    if not _tiktok_comment_needs_media_mirror(comment_row):
        return (
            1,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "up_to_date",
                    "comment_id": str(comment_row.get("comment_id") or ""),
                    "source_count": len(_as_text_list(comment_row.get("media_urls"))),
                    "mirrored_count": len(_as_text_list(comment_row.get("hosted_media_urls"))),
                },
            },
        )

    source_media_urls = _normalize_unique_terms(_as_text_list(comment_row.get("media_urls")))
    if not source_media_urls:
        _update_tiktok_comment_media_mirror_fields(
            comment_id=str(comment_row.get("comment_id") or ""),
            media_mirror_status="failed",
            media_mirror_error="tiktok_comment_media_not_found",
            media_mirror_last_attempt_at=_now_utc(),
            media_mirror_last_job_id=job_id,
        )
        return (
            1,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "failed",
                    "error": "tiktok_comment_media_not_found",
                    "comment_id": str(comment_row.get("comment_id") or ""),
                    "source_count": 0,
                    "mirrored_count": 0,
                },
            },
        )

    attempt_count = max(1, _normalize_non_negative_int(config.get("_attempt_count")))
    now_utc = _now_utc()
    _update_tiktok_comment_media_mirror_fields(
        comment_id=str(comment_row.get("comment_id") or ""),
        media_mirror_status="pending",
        media_mirror_last_attempt_at=now_utc,
        media_mirror_attempt_count=attempt_count,
        media_mirror_last_job_id=job_id,
    )

    week_index_raw = config.get("week_index")
    week_index: int | None = None
    if week_index_raw is not None and str(week_index_raw).strip():
        try:
            week_index = int(week_index_raw)
        except (TypeError, ValueError):
            week_index = None
    if week_index is None:
        posted_at = _coerce_dt(comment_row.get("posted_at"))
        if posted_at is not None:
            try:
                windows, _ = _resolve_week_windows(
                    context,
                    timezone="America/New_York",
                    source_scope=str(config.get("source_scope") or "network"),
                    now_utc=_now_utc(),
                )
                week_window = _week_for_timestamp(posted_at, windows=windows, timezone="America/New_York")
                week_index = week_window.week_index if week_window else None
            except Exception:  # noqa: BLE001
                week_index = None

    mirror_comment = SimpleNamespace(
        id=str(comment_row.get("id") or ""),
        video_id=f"comment-{str(comment_row.get('comment_id') or '')}",
        thumbnail_url="",
        media_urls=source_media_urls,
    )
    result = _mirror_platform_media_to_s3_result(
        context,
        platform="tiktok",
        post=mirror_comment,
        week_index=week_index,
        prefer_first_media_as_thumbnail=False,
    )
    _update_tiktok_comment_media_mirror_fields(
        comment_id=str(comment_row.get("comment_id") or ""),
        hosted_media_urls=list(result.get("hosted_media_urls") or []),
        media_mirror_status=str(result.get("status") or "") or None,
        media_mirror_error=str(result.get("error") or "") or None,
        media_mirror_last_attempt_at=now_utc,
        media_mirror_attempt_count=attempt_count,
        media_mirror_last_job_id=job_id,
    )
    if bool(result.get("retryable_error")) and str(result.get("status") or "") in {"partial", "failed"}:
        raise RuntimeError(str(result.get("error") or "comment_media_mirror_retryable"))

    mirrored_assets = _normalize_non_negative_int(result.get("mirrored_count"))
    metadata = {
        "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(now_utc)},
        "comment_media_mirror": {
            "platform": "tiktok",
            "comment_id": str(comment_row.get("comment_id") or ""),
            "post_id": str(comment_row.get("post_id") or ""),
            "status": str(result.get("status") or ""),
            "error": str(result.get("error") or "") or None,
            "source_count": _normalize_non_negative_int(result.get("source_count")),
            "mirrored_count": mirrored_assets,
            "week_index": week_index,
        },
    }
    return 1, mirrored_assets, metadata


def _run_twitter_comment_media_mirror_stage(
    *,
    context: SeasonContext,
    job_id: str,
    config: dict[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    if not _platform_posts_has_column("twitter", "media_urls"):
        return (
            0,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "skipped",
                    "error": "twitter_comment_media_columns_missing",
                },
            },
        )

    comment_id = str(config.get("comment_id") or "").strip()
    comment_db_id = str(config.get("comment_db_id") or "").strip()
    if not comment_id and not comment_db_id:
        raise ValueError("comment_media_mirror_missing_comment_id")

    comment_row = pg.fetch_one(
        """
        select
          c.id::text as id,
          c.tweet_id as comment_id,
          c.reply_to_tweet_id,
          c.quoted_tweet_id,
          coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
          coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status,
          coalesce(to_jsonb(c) ->> 'media_mirror_error', '') as media_mirror_error,
          root.created_at as root_created_at
        from social.twitter_tweets c
        left join social.twitter_tweets root
          on root.tweet_id = coalesce(c.reply_to_tweet_id, c.quoted_tweet_id)
         and root.is_reply = false
        where c.season_id = %s
          and (c.is_reply = true or c.is_quote = true)
          and (
            (%s <> '' and c.tweet_id = %s)
            or (%s <> '' and c.id = nullif(%s, '')::uuid)
          )
        order by c.created_at desc nulls last
        limit 1
        """,
        [context.season_id, comment_id, comment_id, comment_db_id, comment_db_id],
    )
    if not comment_row:
        raise ValueError("comment_media_mirror_comment_not_found")

    if not _twitter_comment_needs_media_mirror(comment_row):
        return (
            1,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "up_to_date",
                    "comment_id": str(comment_row.get("comment_id") or ""),
                    "source_count": len(_as_text_list(comment_row.get("media_urls"))),
                    "mirrored_count": len(_as_text_list(comment_row.get("hosted_media_urls"))),
                },
            },
        )

    source_media_urls = _normalize_unique_terms(_as_text_list(comment_row.get("media_urls")))
    if not source_media_urls:
        _update_twitter_comment_media_mirror_fields(
            comment_id=str(comment_row.get("comment_id") or ""),
            media_mirror_status="failed",
            media_mirror_error="twitter_comment_media_not_found",
            media_mirror_last_attempt_at=_now_utc(),
            media_mirror_last_job_id=job_id,
        )
        return (
            1,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "failed",
                    "error": "twitter_comment_media_not_found",
                    "comment_id": str(comment_row.get("comment_id") or ""),
                    "source_count": 0,
                    "mirrored_count": 0,
                },
            },
        )

    attempt_count = max(1, _normalize_non_negative_int(config.get("_attempt_count")))
    now_utc = _now_utc()
    _update_twitter_comment_media_mirror_fields(
        comment_id=str(comment_row.get("comment_id") or ""),
        media_mirror_status="pending",
        media_mirror_last_attempt_at=now_utc,
        media_mirror_attempt_count=attempt_count,
        media_mirror_last_job_id=job_id,
    )

    week_index_raw = config.get("week_index")
    week_index: int | None = None
    if week_index_raw is not None and str(week_index_raw).strip():
        try:
            week_index = int(week_index_raw)
        except (TypeError, ValueError):
            week_index = None
    if week_index is None:
        root_created_at = _coerce_dt(comment_row.get("root_created_at"))
        if root_created_at is not None:
            try:
                windows, _ = _resolve_week_windows(
                    context,
                    timezone="America/New_York",
                    source_scope=str(config.get("source_scope") or "network"),
                    now_utc=_now_utc(),
                )
                week_window = _week_for_timestamp(root_created_at, windows=windows, timezone="America/New_York")
                week_index = week_window.week_index if week_window else None
            except Exception:  # noqa: BLE001
                week_index = None

    mirror_comment = SimpleNamespace(
        id=str(comment_row.get("id") or ""),
        tweet_id=str(comment_row.get("comment_id") or ""),
        thumbnail_url="",
        media_urls=source_media_urls,
    )
    result = _mirror_platform_media_to_s3_result(
        context,
        platform="twitter",
        post=mirror_comment,
        week_index=week_index,
        prefer_first_media_as_thumbnail=False,
    )
    _update_twitter_comment_media_mirror_fields(
        comment_id=str(comment_row.get("comment_id") or ""),
        hosted_media_urls=list(result.get("hosted_media_urls") or []),
        media_mirror_status=str(result.get("status") or "") or None,
        media_mirror_error=str(result.get("error") or "") or None,
        media_mirror_last_attempt_at=now_utc,
        media_mirror_attempt_count=attempt_count,
        media_mirror_last_job_id=job_id,
    )
    if bool(result.get("retryable_error")) and str(result.get("status") or "") in {"partial", "failed"}:
        raise RuntimeError(str(result.get("error") or "comment_media_mirror_retryable"))

    mirrored_assets = _normalize_non_negative_int(result.get("mirrored_count"))
    metadata = {
        "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(now_utc)},
        "comment_media_mirror": {
            "platform": "twitter",
            "comment_id": str(comment_row.get("comment_id") or ""),
            "status": str(result.get("status") or ""),
            "error": str(result.get("error") or "") or None,
            "source_count": _normalize_non_negative_int(result.get("source_count")),
            "mirrored_count": mirrored_assets,
            "week_index": week_index,
        },
    }
    return 1, mirrored_assets, metadata


def _run_generic_comment_media_mirror_stage(
    *,
    context: SeasonContext,
    platform: str,
    job_id: str,
    config: dict[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    schema = _comment_media_platform_schema(platform)
    normalized_platform = (platform or "").strip().lower()
    if not schema:
        raise ValueError(f"Unsupported comment media mirror platform: {normalized_platform}")
    comment_table, post_table, posted_at_column = schema
    if not _column_exists("social", comment_table, "media_urls"):
        return (
            0,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "skipped",
                    "error": f"{normalized_platform}_comment_media_columns_missing",
                },
            },
        )

    comment_id = str(config.get("comment_id") or "").strip()
    comment_db_id = str(config.get("comment_db_id") or "").strip()
    post_id = str(config.get("post_id") or "").strip()
    if normalized_platform == "instagram":
        if not comment_db_id and (not comment_id or not post_id):
            raise ValueError("comment_media_mirror_missing_comment_id")
    elif not comment_id and not comment_db_id:
        raise ValueError("comment_media_mirror_missing_comment_id")

    if normalized_platform == "instagram":
        comment_sql = f"""
        select
          c.id::text as id,
          c.comment_id,
          c.post_id::text as post_id,
          coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
          coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status,
          coalesce(to_jsonb(c) ->> 'media_mirror_error', '') as media_mirror_error,
          coalesce(to_jsonb(c) -> 'raw_data', jsonb_build_object()) as raw_data,
          p.{posted_at_column} as post_created_at
        from social.{comment_table} c
        left join social.{post_table} p on p.id = c.post_id
        where (
          (%s <> '' and c.id = nullif(%s, '')::uuid)
          or (%s <> '' and %s <> '' and c.comment_id = %s and c.post_id = nullif(%s, '')::uuid)
        )
        order by c.created_at desc nulls last
        limit 1
        """
        comment_params = [comment_db_id, comment_db_id, comment_id, post_id, comment_id, post_id]
    else:
        comment_sql = f"""
        select
          c.id::text as id,
          c.comment_id,
          c.post_id::text as post_id,
          coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
          coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(c) ->> 'media_mirror_status', '') as media_mirror_status,
          coalesce(to_jsonb(c) ->> 'media_mirror_error', '') as media_mirror_error,
          coalesce(to_jsonb(c) -> 'raw_data', jsonb_build_object()) as raw_data,
          p.{posted_at_column} as post_created_at
        from social.{comment_table} c
        left join social.{post_table} p on p.id = c.post_id
        where (
          (%s <> '' and c.comment_id = %s)
          or (%s <> '' and c.id = nullif(%s, '')::uuid)
        )
        order by c.created_at desc nulls last
        limit 1
        """
        comment_params = [comment_id, comment_id, comment_db_id, comment_db_id]

    comment_row = pg.fetch_one(comment_sql, comment_params)
    if not comment_row:
        raise ValueError("comment_media_mirror_comment_not_found")

    if not _platform_comment_media_needs_mirror(normalized_platform, comment_row):
        return (
            1,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "up_to_date",
                    "comment_id": str(comment_row.get("comment_id") or ""),
                    "source_count": len(_as_text_list(comment_row.get("media_urls"))),
                    "mirrored_count": len(_as_text_list(comment_row.get("hosted_media_urls"))),
                },
            },
        )

    source_media_urls = _normalize_unique_terms(_as_text_list(comment_row.get("media_urls")))
    if normalized_platform == "threads" and not source_media_urls:
        raw_data = comment_row.get("raw_data") if isinstance(comment_row.get("raw_data"), dict) else {}
        if raw_data:
            try:
                from trr_backend.socials.threads.media_resolver import resolve_threads_media

                resolution = resolve_threads_media(raw_data, validate_urls=False)
                source_media_urls = _normalize_unique_terms(list(resolution.media_urls or []))
            except Exception:
                logger.debug(
                    "[threads] Failed to re-resolve comment media from persisted raw_data for comment_id=%s",
                    str(comment_row.get("comment_id") or ""),
                    exc_info=True,
                )
    if not source_media_urls:
        missing_reason = (
            "threads_comment_media_non_repairable"
            if normalized_platform == "threads"
            and not (isinstance(comment_row.get("raw_data"), dict) and comment_row.get("raw_data"))
            else f"{normalized_platform}_comment_media_not_found"
        )
        _update_platform_comment_media_mirror_fields(
            platform=normalized_platform,
            comment_id=str(comment_row.get("comment_id") or ""),
            post_id=str(comment_row.get("post_id") or post_id),
            comment_db_id=str(comment_row.get("id") or comment_db_id),
            media_mirror_status="failed",
            media_mirror_error=missing_reason,
            media_mirror_last_attempt_at=_now_utc(),
            media_mirror_last_job_id=job_id,
        )
        return (
            1,
            0,
            {
                "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(_now_utc())},
                "comment_media_mirror": {
                    "status": "failed",
                    "error": missing_reason,
                    "comment_id": str(comment_row.get("comment_id") or ""),
                    "source_count": 0,
                    "mirrored_count": 0,
                },
            },
        )

    attempt_count = max(1, _normalize_non_negative_int(config.get("_attempt_count")))
    now_utc = _now_utc()
    _update_platform_comment_media_mirror_fields(
        platform=normalized_platform,
        comment_id=str(comment_row.get("comment_id") or ""),
        post_id=str(comment_row.get("post_id") or post_id),
        comment_db_id=str(comment_row.get("id") or comment_db_id),
        media_mirror_status="pending",
        media_mirror_last_attempt_at=now_utc,
        media_mirror_attempt_count=attempt_count,
        media_mirror_last_job_id=job_id,
    )

    week_index_raw = config.get("week_index")
    week_index: int | None = None
    if week_index_raw is not None and str(week_index_raw).strip():
        try:
            week_index = int(week_index_raw)
        except (TypeError, ValueError):
            week_index = None
    if week_index is None:
        post_created_at = _coerce_dt(comment_row.get("post_created_at"))
        if post_created_at is not None:
            try:
                windows, _ = _resolve_week_windows(
                    context,
                    timezone="America/New_York",
                    source_scope=str(config.get("source_scope") or "network"),
                    now_utc=_now_utc(),
                )
                week_window = _week_for_timestamp(post_created_at, windows=windows, timezone="America/New_York")
                week_index = week_window.week_index if week_window else None
            except Exception:  # noqa: BLE001
                week_index = None

    mirror_comment = SimpleNamespace(
        id=str(comment_row.get("id") or ""),
        post_id=str(comment_row.get("post_id") or ""),
        thumbnail_url="",
        media_urls=source_media_urls,
    )
    result = _mirror_platform_media_to_s3_result(
        context,
        platform=normalized_platform,
        post=mirror_comment,
        week_index=week_index,
        prefer_first_media_as_thumbnail=False,
    )
    _update_platform_comment_media_mirror_fields(
        platform=normalized_platform,
        comment_id=str(comment_row.get("comment_id") or ""),
        post_id=str(comment_row.get("post_id") or post_id),
        comment_db_id=str(comment_row.get("id") or comment_db_id),
        hosted_media_urls=list(result.get("hosted_media_urls") or []),
        media_mirror_status=str(result.get("status") or "") or None,
        media_mirror_error=str(result.get("error") or "") or None,
        media_mirror_last_attempt_at=now_utc,
        media_mirror_attempt_count=attempt_count,
        media_mirror_last_job_id=job_id,
    )
    if bool(result.get("retryable_error")) and str(result.get("status") or "") in {"partial", "failed"}:
        raise RuntimeError(str(result.get("error") or "comment_media_mirror_retryable"))

    mirrored_assets = _normalize_non_negative_int(result.get("mirrored_count"))
    metadata = {
        "activity": {"phase": "comment_media_mirror_end", "last_progress_at": _iso(now_utc)},
        "comment_media_mirror": {
            "platform": normalized_platform,
            "comment_id": str(comment_row.get("comment_id") or ""),
            "post_id": str(comment_row.get("post_id") or ""),
            "status": str(result.get("status") or ""),
            "error": str(result.get("error") or "") or None,
            "source_count": _normalize_non_negative_int(result.get("source_count")),
            "mirrored_count": mirrored_assets,
            "week_index": week_index,
        },
    }
    return 1, mirrored_assets, metadata


def _run_instagram_media_mirror_stage(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.media_mirror import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["_run_instagram_media_mirror_stage"](*args, **kwargs)


def _run_platform_stage(
    *,
    context: SeasonContext,
    run_id: str | None,
    platform: str,
    stage: str,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    config: dict[str, Any] | None = None,
) -> tuple[int, int, dict[str, Any]]:
    normalized_platform = (platform or "").strip().lower()
    normalized_config = dict(config or {})
    if stage not in {"posts", "comments", INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE}:
        raise ValueError(f"Unsupported ingest stage: {stage}")

    if stage == INSTAGRAM_MEDIA_MIRROR_STAGE:
        return _run_platform_media_mirror_stage(
            context=context,
            platform=normalized_platform,
            job_id=job_id,
            config=dict(config or {}),
        )
    if stage == COMMENT_MEDIA_MIRROR_STAGE:
        if normalized_platform == "youtube":
            raise ValueError("youtube_comment_media_mirror_obsolete")
        if normalized_platform == "tiktok":
            return _run_tiktok_comment_media_mirror_stage(
                context=context,
                job_id=job_id,
                config=dict(config or {}),
            )
        if normalized_platform == "twitter":
            return _run_twitter_comment_media_mirror_stage(
                context=context,
                job_id=job_id,
                config=dict(config or {}),
            )
        if normalized_platform in {"instagram", "facebook", "threads"}:
            return _run_generic_comment_media_mirror_stage(
                context=context,
                platform=normalized_platform,
                job_id=job_id,
                config=dict(config or {}),
            )
        raise ValueError(f"Unsupported comment media mirror platform: {normalized_platform}")

    if stage == "posts":
        enable_comments_in_posts_stage = (
            (normalized_platform == "tiktok" and bool(normalized_config.get("tiktok_comments_in_posts_stage")))
            or (normalized_platform == "twitter" and bool(normalized_config.get("twitter_comments_in_posts_stage")))
            or (
                normalized_platform == "threads"
                and "comments"
                in set(
                    _normalize_optional_social_account_catalog_backfill_selected_tasks(
                        normalized_config.get("effective_selected_tasks")
                    )
                )
            )
        ) and opts.max_comments_per_post > 0
        stage_opts = (
            opts if enable_comments_in_posts_stage else replace(opts, max_comments_per_post=0, fetch_replies=False)
        )
        if normalized_platform == "instagram":
            return _ingest_instagram(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=stage_opts,
                job_id=job_id,
                stage=stage,
            )
        if normalized_platform == "tiktok":
            return _ingest_tiktok(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=stage_opts,
                job_id=job_id,
                stage=stage,
                job_config=normalized_config,
            )
        if normalized_platform == "youtube":
            return _ingest_youtube(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=stage_opts,
                job_id=job_id,
                stage=stage,
                job_config=config,
            )
        if normalized_platform == "twitter":
            return _ingest_twitter(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=stage_opts,
                job_id=job_id,
                include_reply_records=False,
                hydrate_audience_replies=enable_comments_in_posts_stage,
                stage=stage,
                job_config=config,
            )
        if normalized_platform == "facebook":
            return _ingest_facebook(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=stage_opts,
                job_id=job_id,
                stage=stage,
            )
        if normalized_platform == "threads":
            return _ingest_threads(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=stage_opts,
                job_id=job_id,
                stage=stage,
            )
    else:
        if opts.max_comments_per_post <= 0:
            return 0, 0, {}
        if normalized_platform == "instagram":
            posts, comments, meta = _ingest_instagram(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                stage=stage,
            )
            return posts, comments, meta
        if normalized_platform == "tiktok":
            posts, comments, meta = _ingest_tiktok(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                stage=stage,
                job_config=normalized_config,
            )
            return posts, comments, meta
        if normalized_platform == "youtube":
            posts, comments, meta = _ingest_youtube(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                stage=stage,
                job_config=config,
            )
            return posts, comments, meta
        if normalized_platform == "twitter":
            posts, comments, meta = _ingest_twitter(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                include_reply_records=False,
                hydrate_audience_replies=True,
                stage=stage,
                job_config=config,
            )
            return posts, comments, meta
        if normalized_platform == "facebook":
            posts, comments, meta = _ingest_facebook(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                stage=stage,
            )
            return posts, comments, meta
        if normalized_platform == "threads":
            posts, comments, meta = _ingest_threads(
                context,
                run_id=run_id,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                stage=stage,
            )
            return posts, comments, meta

    raise RuntimeError(f"Platform {normalized_platform} ingest is not supported")


def _merge_source_runtime(
    retrieval_meta: dict[str, Any],
    scraper: Any | None,
) -> dict[str, Any]:
    merged = dict(retrieval_meta or {})
    runtime_meta = dict(getattr(scraper, "runtime_metadata", {}) or {})
    if runtime_meta:
        merged["source_runtime"] = runtime_meta
    return merged


def _run_platform_stage_via_crawlee(
    *,
    context: SeasonContext,
    run_id: str | None,
    platform: str,
    stage: str,
    account: str,
    hashtags: list[str],
    keywords: list[str],
    opts: IngestOptions,
    job_id: str,
    config: dict[str, Any],
    runtime_config: Any,
    auth_preflight: AuthPreflightResult,
) -> tuple[int, int, dict[str, Any]]:
    normalized_platform = (platform or "").strip().lower()

    def runner() -> tuple[int, int, dict[str, Any]]:
        return _run_platform_stage(
            context=context,
            run_id=run_id,
            platform=normalized_platform,
            stage=stage,
            account=account,
            hashtags=hashtags,
            keywords=keywords,
            opts=opts,
            job_id=job_id,
            config=config,
        )

    if normalized_platform == "instagram":
        from trr_backend.socials.instagram.crawlee_adapter import run_stage_with_crawlee

        return run_stage_with_crawlee(
            stage=stage,
            account=account,
            config=config,
            runtime_config=runtime_config,
            auth_preflight=auth_preflight,
            stage_runner=runner,
        )
    if normalized_platform == "tiktok":
        from trr_backend.socials.tiktok.crawlee_adapter import run_stage_with_crawlee

        return run_stage_with_crawlee(
            stage=stage,
            account=account,
            config=config,
            runtime_config=runtime_config,
            auth_preflight=auth_preflight,
            stage_runner=runner,
        )
    if normalized_platform == "twitter":
        from trr_backend.socials.twitter.crawlee_adapter import run_stage_with_crawlee

        return run_stage_with_crawlee(
            stage=stage,
            account=account,
            config=config,
            runtime_config=runtime_config,
            auth_preflight=auth_preflight,
            stage_runner=runner,
        )
    if normalized_platform == "youtube":
        from trr_backend.socials.youtube.crawlee_adapter import run_stage_with_crawlee

        return run_stage_with_crawlee(
            stage=stage,
            account=account,
            config=config,
            runtime_config=runtime_config,
            auth_preflight=auth_preflight,
            stage_runner=runner,
        )
    if normalized_platform == "facebook":
        from trr_backend.socials.facebook.crawlee_adapter import run_stage_with_crawlee

        return run_stage_with_crawlee(
            stage=stage,
            account=account,
            config=config,
            runtime_config=runtime_config,
            auth_preflight=auth_preflight,
            stage_runner=runner,
        )
    if normalized_platform == "threads":
        from trr_backend.socials.threads.crawlee_adapter import run_stage_with_crawlee

        return run_stage_with_crawlee(
            stage=stage,
            account=account,
            config=config,
            runtime_config=runtime_config,
            auth_preflight=auth_preflight,
            stage_runner=runner,
        )
    raise RuntimeError(f"Platform {normalized_platform} ingest is not supported")


def _load_shared_account_source_row(
    *,
    source_scope: str,
    platform: str,
    account_handle: str,
) -> dict[str, Any] | None:
    normalized_account = _normalize_account_handle(account_handle) or str(account_handle or "").strip()
    return pg.fetch_one(
        """
        select
          id::text as id,
          platform,
          source_scope,
          account_handle,
          is_active,
          scrape_priority,
          metadata,
          last_scrape_status,
          last_scrape_run_id::text as last_scrape_run_id,
          last_scrape_job_id::text as last_scrape_job_id,
          last_scrape_at,
          last_classified_at,
          updated_by,
          created_at,
          updated_at
        from social.shared_account_sources
        where source_scope = %s
          and platform = %s
          and account_handle = %s
        limit 1
        """,
        [source_scope, platform, normalized_account],
    )


def _touch_shared_account_source(
    *,
    source_scope: str,
    platform: str,
    account_handle: str,
    run_id: str | None = None,
    job_id: str | None = None,
    last_scrape_status: str | None = None,
    last_classified_at: datetime | None = None,
    metadata_updates: Mapping[str, Any] | None = None,
) -> None:
    normalized_account = _normalize_account_handle(account_handle) or str(account_handle or "").strip()
    pg.execute(
        """
        update social.shared_account_sources
        set
          last_scrape_status = coalesce(%s, last_scrape_status),
          last_scrape_run_id = coalesce(%s::uuid, last_scrape_run_id),
          last_scrape_job_id = coalesce(%s::uuid, last_scrape_job_id),
          last_scrape_at = case when %s is not null then now() else last_scrape_at end,
          last_classified_at = coalesce(%s, last_classified_at),
          metadata = case
            when %s::jsonb = '{}'::jsonb then metadata
            else coalesce(metadata, '{}'::jsonb) || %s::jsonb
          end,
          updated_at = now()
        where source_scope = %s
          and platform = %s
          and account_handle = %s
        """,
        [
            last_scrape_status,
            run_id,
            job_id,
            last_scrape_status,
            last_classified_at,
            _json_dumps(_metadata_dict(metadata_updates)),
            _json_dumps(_metadata_dict(metadata_updates)),
            source_scope,
            platform,
            normalized_account,
        ],
    )


def _social_profile_cache_ttl_seconds() -> int:
    return max(
        30,
        _normalize_non_negative_int(
            os.getenv("SOCIAL_PROFILE_TOTAL_POSTS_CACHE_TTL_SEC")
            or SOCIAL_PROFILE_TOTAL_POSTS_CACHE_TTL_SECONDS_DEFAULT
        ),
    )


def _run_async_sync(awaitable: Any) -> Any:
    loop = asyncio.new_event_loop()
    try:
        return loop.run_until_complete(awaitable)
    finally:
        loop.close()


def _merge_tiktok_profile_snapshots(*snapshots: Mapping[str, Any] | None) -> dict[str, Any]:
    merged: dict[str, Any] = {}
    for snapshot in snapshots:
        metadata = _metadata_dict(snapshot)
        if not metadata:
            continue
        for key in ("username", "sec_uid", "display_name", "bio", "avatar_url", "profile_url"):
            value = str(metadata.get(key) or "").strip()
            if value and not str(merged.get(key) or "").strip():
                merged[key] = value
        for key in ("follower_count", "following_count", "total_posts"):
            if metadata.get(key) is None:
                continue
            merged[key] = max(
                _normalize_non_negative_int(merged.get(key)), _normalize_non_negative_int(metadata.get(key))
            )
        if bool(metadata.get("is_verified")):
            merged["is_verified"] = True
    return merged


def _merge_social_profile_snapshots(*snapshots: Mapping[str, Any] | None) -> dict[str, Any]:
    merged: dict[str, Any] = {}
    for snapshot in snapshots:
        metadata = _metadata_dict(snapshot)
        if not metadata:
            continue
        for key in ("username", "display_name", "bio", "avatar_url", "profile_url", "channel_id"):
            value = str(metadata.get(key) or "").strip()
            if value and not str(merged.get(key) or "").strip():
                merged[key] = value
        for key in ("follower_count", "following_count", "total_posts"):
            if metadata.get(key) is None:
                continue
            merged[key] = max(
                _normalize_non_negative_int(merged.get(key)), _normalize_non_negative_int(metadata.get(key))
            )
        if bool(metadata.get("is_verified")):
            merged["is_verified"] = True
    return merged


def _snapshot_without_total_posts(snapshot: Mapping[str, Any] | None) -> dict[str, Any]:
    metadata = dict(_metadata_dict(snapshot))
    metadata.pop("total_posts", None)
    return metadata


def _tiktok_profile_snapshot_from_analysis_rows(
    rows: Sequence[Mapping[str, Any]], account_handle: str
) -> dict[str, Any]:
    for row in rows:
        row_json = _metadata_dict(row)
        raw_data = _metadata_dict(row_json.get("raw_data"))
        author = _metadata_dict(raw_data.get("author"))
        display_name = str(
            row_json.get("nickname")
            or author.get("nickname")
            or author.get("nickName")
            or raw_data.get("nickname")
            or ""
        ).strip()
        avatar_url = _best_profile_avatar_url(
            [
                row_json.get("user_avatar_url"),
                row_json.get("avatar_url"),
                *_extract_avatar_url_candidates_from_raw_data(raw_data),
            ]
        )
        snapshot = {
            "username": _normalize_account_handle(author.get("uniqueId") or author.get("unique_id") or account_handle),
            "display_name": display_name or None,
            "avatar_url": avatar_url,
            "is_verified": bool(
                author.get("verified") or author.get("isVerified") or raw_data.get("verified") or False
            ),
            "profile_url": _platform_profile_url_for_handle("tiktok", account_handle),
        }
        if any(snapshot.values()):
            return snapshot
    return {}


