def _cached_live_profile_snapshot(platform: str, account_handle: str) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if normalized_platform not in {"tiktok", "twitter", "youtube"} or not normalized_account:
        return {}

    ttl_seconds = _social_profile_cache_ttl_seconds()
    cache_key = (normalized_platform, normalized_account)
    now_monotonic = time_module.monotonic()
    with _SOCIAL_PROFILE_SNAPSHOT_CACHE_LOCK:
        cached = _SOCIAL_PROFILE_SNAPSHOT_CACHE.get(cache_key)
        if cached and cached[0] > now_monotonic:
            return dict(cached[1])

    snapshot: dict[str, Any] = {}
    try:
        if normalized_platform == "tiktok":
            from trr_backend.socials.tiktok import TikTokScraper

            scraper = TikTokScraper(cookies=_load_tiktok_cookies())
            try:
                user_data = scraper.fetch_user_detail(normalized_account, 0.0)
            except Exception:  # noqa: BLE001
                logger.warning(
                    "[tiktok] live profile snapshot user-detail enrichment failed for @%s",
                    normalized_account,
                )
                user_data = None
            try:
                html_data = scraper._fetch_profile_html(normalized_account, 0.0)  # noqa: SLF001
            except Exception:  # noqa: BLE001
                logger.warning("[tiktok] live profile snapshot html enrichment failed for @%s", normalized_account)
                html_data = None
            try:
                snapshot = scraper.build_profile_snapshot(normalized_account, user_data=user_data, html_data=html_data)
            except Exception:  # noqa: BLE001
                logger.warning("[tiktok] live profile snapshot build failed for @%s", normalized_account)
                snapshot = {}
            if not _normalize_non_negative_int(snapshot.get("total_posts")) and isinstance(html_data, dict):
                try:
                    html_items, _ = scraper._extract_posts_from_html_data(html_data, normalized_account)  # noqa: SLF001
                except Exception:  # noqa: BLE001
                    logger.warning("[tiktok] live profile snapshot html parsing failed for @%s", normalized_account)
                    html_items = []
                if html_items:
                    snapshot["total_posts"] = max(
                        _normalize_non_negative_int(snapshot.get("total_posts")),
                        len(html_items),
                    )
        elif normalized_platform == "twitter":
            twitter_cookies, _twitter_bearer = _load_twitter_auth_from_sources()
            credentials = _load_twikit_credentials(twitter_cookies)
            scraper = TwitterScraper(
                cookies=twitter_cookies,
                bearer_token=_twitter_bearer,
                twikit_credentials=credentials,
            )
            snapshot = scraper.fetch_user_profile_summary(normalized_account, delay=0.0) or {}

            if not snapshot:
                # twikit is an optional dependency only required by the cookie/guest fallback
                # below. Import it lazily so the GraphQL-first happy path above still resolves a
                # snapshot in environments where twikit is not installed.
                twikit_module, twikit_guest_module = map(importlib.import_module, ("twikit", "twikit.guest"))
                twikit_client, twikit_guest_client = twikit_module.Client, twikit_guest_module.GuestClient

                async def _load_snapshot() -> dict[str, Any]:
                    client: Any = None
                    try:
                        auth_token = str((credentials or {}).get("auth_token") or "").strip()
                        ct0 = str((credentials or {}).get("ct0") or "").strip()
                        username = str((credentials or {}).get("username") or "").strip()
                        email = str((credentials or {}).get("email") or "").strip()
                        password = str((credentials or {}).get("password") or "").strip()
                        if auth_token and ct0:
                            client = twikit_client("en-US")
                            client.set_cookies({"auth_token": auth_token, "ct0": ct0})
                        elif username and password:
                            client = twikit_client("en-US")
                            await client.login(
                                auth_info_1=username,
                                auth_info_2=email or username,
                                password=password,
                            )
                        else:
                            client = twikit_guest_client("en-US")
                            await client.activate()
                        user = await client.get_user_by_screen_name(normalized_account)
                        return {
                            "username": _normalize_account_handle(
                                getattr(user, "screen_name", None) or normalized_account
                            ),
                            "display_name": str(getattr(user, "name", "") or "").strip() or None,
                            "bio": str(getattr(user, "description", "") or "").strip() or None,
                            "avatar_url": _best_profile_avatar_url([getattr(user, "profile_image_url", None)]),
                            "profile_url": _platform_profile_url_for_handle("twitter", normalized_account),
                            "follower_count": _normalize_non_negative_int(getattr(user, "followers_count", None))
                            or None,
                            "following_count": _normalize_non_negative_int(getattr(user, "following_count", None))
                            or None,
                            "total_posts": _normalize_non_negative_int(getattr(user, "statuses_count", None)) or None,
                            "is_verified": bool(
                                getattr(user, "verified", False) or getattr(user, "is_blue_verified", False)
                            ),
                        }
                    finally:
                        http_client = getattr(client, "http", None)
                        if http_client is not None and hasattr(http_client, "aclose"):
                            await http_client.aclose()

                snapshot = _run_async_sync(_load_snapshot())
        elif normalized_platform == "youtube":
            from trr_backend.socials.youtube import YouTubeDataApiClient, YouTubeScraper

            youtube_api = YouTubeDataApiClient()
            api_identity = youtube_api.resolve_channel(normalized_account) if youtube_api.enabled() else None
            snapshot = _youtube_profile_snapshot_from_api_identity(api_identity, account_handle=normalized_account)
            scraper = YouTubeScraper()
            resolved_identity = scraper.resolve_channel_identity(normalized_account, delay=0.0)
            resolved_meta = _metadata_dict(resolved_identity)
            resolved_handle = _normalize_account_handle(resolved_meta.get("canonical_handle") or normalized_account)
            about_snapshot = scraper.resolve_channel_about_snapshot(resolved_handle or normalized_account, delay=0.0)
            snapshot = _merge_social_profile_snapshots(snapshot, about_snapshot)
            if resolved_handle:
                snapshot.setdefault("username", resolved_handle)
                snapshot.setdefault("profile_url", _platform_profile_url_for_handle("youtube", resolved_handle))
            resolved_channel_id = str(resolved_meta.get("channel_id") or "").strip()
            if resolved_channel_id and not str(snapshot.get("channel_id") or "").strip():
                snapshot["channel_id"] = resolved_channel_id
    except Exception:  # noqa: BLE001
        logger.debug(
            "Failed resolving live profile snapshot for %s @%s",
            normalized_platform,
            normalized_account,
            exc_info=True,
        )

    with _SOCIAL_PROFILE_SNAPSHOT_CACHE_LOCK:
        _SOCIAL_PROFILE_SNAPSHOT_CACHE[cache_key] = (now_monotonic + ttl_seconds, dict(snapshot))
    return snapshot


def _cached_live_profile_snapshot_cached_only(platform: str, account_handle: str) -> dict[str, Any]:
    normalized_platform = _normalize_platform_name(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if normalized_platform not in {"tiktok", "twitter", "youtube"} or not normalized_account:
        return {}

    cache_key = (normalized_platform, normalized_account)
    now_monotonic = time_module.monotonic()
    with _SOCIAL_PROFILE_SNAPSHOT_CACHE_LOCK:
        cached = _SOCIAL_PROFILE_SNAPSHOT_CACHE.get(cache_key)
        if cached and cached[0] > now_monotonic:
            return dict(cached[1])
    return {}


def _facebook_profile_snapshot_from_posts(posts: Sequence[Any], account_handle: str) -> dict[str, Any]:
    normalized_account = _normalize_account_handle(account_handle) or account_handle
    display_name = next(
        (
            str(getattr(post, "username", "") or "").strip()
            for post in posts
            if str(getattr(post, "username", "") or "").strip()
        ),
        None,
    )
    avatar_url = _best_profile_avatar_url(
        [
            next(
                (
                    str(getattr(post, "user_avatar_url", "") or "").strip()
                    for post in posts
                    if str(getattr(post, "user_avatar_url", "") or "").strip()
                ),
                None,
            )
        ]
    )
    snapshot = {
        "username": normalized_account,
        "display_name": display_name,
        "avatar_url": avatar_url,
        "profile_url": _platform_profile_url_for_handle("facebook", normalized_account),
    }
    return {key: value for key, value in snapshot.items() if value}


def _is_catalog_platform(platform: str) -> bool:
    return _normalize_platform_name(platform) in set(CATALOG_SUPPORTED_PLATFORMS)


def _shared_catalog_mode(config: Mapping[str, Any] | None) -> bool:
    return (
        str((config or {}).get("pipeline_ingest_mode") or "").strip().lower()
        == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
    )


def _shared_catalog_progress_pages_scanned(retrieval_meta: Mapping[str, Any] | None) -> int:
    meta = _metadata_dict(retrieval_meta)
    direct = _normalize_non_negative_int(meta.get("pages_scanned"))
    surface_sum = (
        _normalize_non_negative_int(meta.get("videos_pages_scanned"))
        + _normalize_non_negative_int(meta.get("shorts_pages_scanned"))
        + _normalize_non_negative_int(meta.get("posts_pages_scanned"))
    )
    return max(direct, surface_sum)


def _shared_catalog_progress_posts_checked(retrieval_meta: Mapping[str, Any] | None, *, matched_posts: int) -> int:
    meta = _metadata_dict(retrieval_meta)
    return max(
        _normalize_non_negative_int(meta.get("posts_checked")),
        _normalize_non_negative_int(meta.get("checked_renderers")),
        max(0, int(matched_posts)),
    )


def _shared_catalog_progress_total_posts(retrieval_meta: Mapping[str, Any] | None) -> int | None:
    meta = _metadata_dict(retrieval_meta)
    profile_snapshot = _metadata_dict(meta.get("profile_snapshot"))
    total_posts = max(
        _normalize_non_negative_int(meta.get("total_posts")),
        _normalize_non_negative_int(profile_snapshot.get("total_posts")),
    )
    return total_posts or None


def _persist_shared_catalog_posts_with_progress(
    *,
    platform: str,
    run_id: str | None,
    account_handle: str,
    items: Sequence[Any],
    retrieval_meta: MutableMapping[str, Any],
    upsert_item: Callable[[Any], dict[str, Any] | None],
    progress_cb: Callable[[dict[str, Any]], None] | None = None,
) -> list[dict[str, Any]]:
    progress_interval = _shared_catalog_progress_interval_posts()
    pages_scanned = _shared_catalog_progress_pages_scanned(retrieval_meta)
    matched_posts = len(items)
    posts_checked = _shared_catalog_progress_posts_checked(retrieval_meta, matched_posts=matched_posts)
    total_posts = _shared_catalog_progress_total_posts(retrieval_meta)
    rows: list[dict[str, Any]] = []

    def _emit_persist_progress(saved_posts: int, *, force: bool = False) -> None:
        if not progress_cb:
            return
        if not force and saved_posts > 0 and saved_posts % progress_interval != 0:
            return
        payload: dict[str, Any] = {
            "phase": "persist_catalog_posts",
            "pages_scanned": pages_scanned,
            "posts_checked": posts_checked,
            "matched_posts": matched_posts,
            "saved_posts": max(0, int(saved_posts)),
        }
        if total_posts is not None:
            payload["total_posts"] = total_posts
        progress_cb(payload)

    _emit_persist_progress(0, force=True)
    for index, item in enumerate(items, start=1):
        row = upsert_item(item)
        if row:
            rows.append(row)
        _emit_persist_progress(len(rows), force=index == len(items))

    retrieval_meta["pages_scanned"] = pages_scanned
    retrieval_meta["posts_checked"] = posts_checked
    if total_posts is not None:
        retrieval_meta["total_posts"] = total_posts
    retrieval_meta["persist_counters"] = {
        "posts_upserted": len(rows),
        "comments_upserted": 0,
    }
    return rows


def _shared_catalog_base_query_parts(platform: str) -> tuple[str, str, str]:
    normalized_platform = _normalize_platform_name(platform)
    table = cast(Mapping[str, str], PLATFORM_CATALOG_POST_TABLES).get(normalized_platform)
    source_id_column = cast(Mapping[str, str], PLATFORM_CATALOG_SOURCE_ID_COLUMN).get(normalized_platform)
    posted_at_column = cast(Mapping[str, str], PLATFORM_CATALOG_POSTED_AT_COLUMN).get(normalized_platform)
    if not table or not source_id_column or not posted_at_column:
        raise ValueError(f"Unsupported shared catalog platform: {platform}")
    return table, source_id_column, posted_at_column


def _shared_catalog_post_url(
    platform: str,
    *,
    account_handle: str,
    source_id: str,
    explicit: str | None,
    post_format: object | None = None,
    media_type: object | None = None,
    raw_data: Mapping[str, object] | None = None,
) -> str | None:
    if explicit and explicit.startswith(("http://", "https://")):
        return explicit
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform == "instagram" and source_id:
        return instagram_post_permalink(
            source_id,
            post_format=post_format,
            media_type=media_type,
            raw_data=raw_data,
        )
    if normalized_platform == "tiktok" and source_id:
        return f"https://www.tiktok.com/@{account_handle}/video/{source_id}"
    if normalized_platform == "twitter" and source_id:
        return f"https://x.com/{account_handle}/status/{source_id}"
    if normalized_platform == "youtube" and source_id:
        return f"https://www.youtube.com/watch?v={source_id}"
    if normalized_platform == "facebook" and source_id:
        return f"https://www.facebook.com/{account_handle}/posts/{source_id}"
    if normalized_platform == "threads" and source_id:
        return f"https://www.threads.com/@{account_handle}/post/{source_id}"
    return None


def _shared_catalog_payload_base(
    *,
    source_id: str,
    account_handle: str,
    posted_at: datetime | None,
    permalink: str | None,
    title: str | None = None,
    caption: str | None = None,
    description: str | None = None,
    text: str | None = None,
    media_type: str | None = None,
    media_urls: list[str] | None = None,
    thumbnail_url: str | None = None,
    hashtags: list[str] | None = None,
    mentions: list[str] | None = None,
    collaborators: list[str] | None = None,
    profile_tags: list[str] | None = None,
    likes: int | None = None,
    comments_count: int | None = None,
    views: int | None = None,
    shares: int | None = None,
    retweets: int | None = None,
    replies_count: int | None = None,
    quotes: int | None = None,
    raw_data: dict[str, Any] | None = None,
    run_id: str | None = None,
    # Instagram enrichment fields (populated by IG-specific upsert only)
    music_info: dict[str, Any] | None = None,
    audio_url: str | None = None,
    paid_partnership: bool = False,
    child_posts_data: list[dict[str, Any]] | None = None,
    owner_username: str | None = None,
    video_play_count: int | None = None,
    video_duration: float | None = None,
) -> dict[str, Any]:
    now_utc = _now_utc()
    return {
        "source_id": source_id,
        "source_account": account_handle,
        "posted_at": posted_at,
        "permalink": permalink,
        "title": title,
        "caption": caption,
        "description": description,
        "text": text,
        "media_type": media_type,
        "media_urls": media_urls or [],
        "thumbnail_url": thumbnail_url,
        "hashtags": hashtags or [],
        "mentions": mentions or [],
        "collaborators": collaborators or [],
        "profile_tags": profile_tags or [],
        "likes": _normalize_non_negative_int(likes),
        "comments_count": _normalize_non_negative_int(comments_count),
        "views": _normalize_non_negative_int(views),
        "shares": _normalize_non_negative_int(shares),
        "retweets": _normalize_non_negative_int(retweets),
        "replies_count": _normalize_non_negative_int(replies_count),
        "quotes": _normalize_non_negative_int(quotes),
        "raw_data": raw_data or {},
        "last_backfill_run_id": run_id,
        "last_seen_at": now_utc,
        "updated_at": now_utc,
        "music_info": music_info or {},
        "audio_url": audio_url,
        "paid_partnership": paid_partnership,
        "child_posts_data": child_posts_data or [],
        "owner_username": owner_username,
        "video_play_count": _normalize_non_negative_int(video_play_count),
        "video_duration": video_duration,
    }


