def _dedupe_catalog_comments_source_ids(source_ids: Sequence[Any] | None) -> list[str]:
    ordered: list[str] = []
    seen: set[str] = set()
    for source_id in source_ids or []:
        normalized = str(source_id or "").strip()
        if not normalized or normalized in seen:
            continue
        ordered.append(normalized)
        seen.add(normalized)
    return ordered


_COMMENTS_STREAMING_ENQUEUE_LAG_MAX_MS = 24 * 60 * 60 * 1000
_COMMENTS_STREAMING_ENQUEUE_LAG_CUMULATIVE_MAX_MS = 30 * _COMMENTS_STREAMING_ENQUEUE_LAG_MAX_MS
_COMMENTS_STREAMING_ENQUEUE_ATTEMPT_MAX = 1_000_000
_COMMENTS_STREAMING_HISTORY_LIMIT = 12


def _bounded_comments_streaming_enqueue_lag_ms(
    requested_at: datetime | None,
    completed_at: datetime | None,
) -> int:
    if requested_at is None or completed_at is None:
        return 0
    elapsed_ms = int(round(max(0.0, (completed_at - requested_at).total_seconds() * 1000)))
    return min(elapsed_ms, _COMMENTS_STREAMING_ENQUEUE_LAG_MAX_MS)


def _catalog_comments_streaming_enqueue_lag_updates(
    run_config: Mapping[str, Any],
    *,
    enqueue_requested_at: datetime | None,
    enqueue_completed_at: datetime | None,
    targets_seen: int,
    targets_enqueued: int,
) -> dict[str, Any]:
    if enqueue_requested_at is None or enqueue_completed_at is None:
        return {}
    lag_ms = _bounded_comments_streaming_enqueue_lag_ms(enqueue_requested_at, enqueue_completed_at)
    prior_total_lag_ms = _normalize_non_negative_int(run_config.get("comments_streaming_total_enqueue_lag_ms"))
    prior_max_lag_ms = _normalize_non_negative_int(run_config.get("comments_streaming_max_enqueue_lag_ms"))
    prior_attempts = _normalize_non_negative_int(run_config.get("comments_streaming_enqueue_attempt_count"))
    return {
        "comments_streaming_last_enqueue_requested_at": _iso(enqueue_requested_at),
        "comments_streaming_last_enqueue_completed_at": _iso(enqueue_completed_at),
        "comments_streaming_last_enqueue_lag_ms": lag_ms,
        "comments_streaming_total_enqueue_lag_ms": min(
            prior_total_lag_ms + lag_ms,
            _COMMENTS_STREAMING_ENQUEUE_LAG_CUMULATIVE_MAX_MS,
        ),
        "comments_streaming_max_enqueue_lag_ms": min(
            max(prior_max_lag_ms, lag_ms),
            _COMMENTS_STREAMING_ENQUEUE_LAG_MAX_MS,
        ),
        "comments_streaming_enqueue_attempt_count": min(
            prior_attempts + 1,
            _COMMENTS_STREAMING_ENQUEUE_ATTEMPT_MAX,
        ),
        "comments_streaming_last_enqueue_targets_seen": _normalize_non_negative_int(targets_seen),
        "comments_streaming_last_enqueue_targets_enqueued": _normalize_non_negative_int(targets_enqueued),
    }


def _catalog_comments_streaming_history_updates(
    run_config: Mapping[str, Any],
    updates: Mapping[str, Any],
    *,
    state: str,
    enqueue_targets_seen: int = 0,
    enqueue_targets_enqueued: int = 0,
) -> list[dict[str, Any]]:
    prior_entries: list[dict[str, Any]] = []
    raw_history = run_config.get("comments_streaming_history")
    if isinstance(raw_history, list):
        prior_entries = [
            _metadata_dict(item)
            for item in raw_history[-(_COMMENTS_STREAMING_HISTORY_LIMIT - 1) :]
            if isinstance(item, Mapping)
        ]
    append_result = _metadata_dict(updates.get("comments_streaming_last_append_result"))
    reconcile_result = _metadata_dict(updates.get("comments_streaming_last_reconcile_result"))
    entry: dict[str, Any] = {
        "recorded_at": updates.get("comments_streaming_last_updated_at") or _iso(_now_utc()),
        "state": str(state or "").strip().lower() or None,
        "comments_run_id": updates.get("comments_run_id") or run_config.get("comments_run_id"),
        "targets_seen_total": _normalize_non_negative_int(updates.get("comments_streaming_targets_seen")),
        "targets_enqueued_total": _normalize_non_negative_int(updates.get("comments_streaming_targets_enqueued")),
        "targets_skipped_duplicate_total": _normalize_non_negative_int(
            updates.get("comments_streaming_targets_skipped_duplicate")
        ),
        "append_failures_total": _normalize_non_negative_int(updates.get("comments_streaming_append_failures")),
        "enqueue_targets_seen": _normalize_non_negative_int(enqueue_targets_seen),
        "enqueue_targets_enqueued": _normalize_non_negative_int(enqueue_targets_enqueued),
        "last_batch_source_ids_count": _normalize_non_negative_int(
            updates.get("comments_streaming_last_batch_source_ids_count")
        ),
        "last_enqueue_lag_ms": _normalize_non_negative_int(updates.get("comments_streaming_last_enqueue_lag_ms")),
    }
    if append_result:
        entry["append_result"] = {
            "created_job_count": _normalize_non_negative_int(append_result.get("created_job_count")),
            "targets_enqueued": _normalize_non_negative_int(append_result.get("targets_enqueued")),
            "targets_skipped_duplicate": _normalize_non_negative_int(append_result.get("targets_skipped_duplicate")),
            "reason": str(append_result.get("reason") or "").strip() or None,
        }
    if reconcile_result:
        entry["reconcile_result"] = {
            "targets_seen": _normalize_non_negative_int(reconcile_result.get("targets_seen")),
            "targets_enqueued": _normalize_non_negative_int(reconcile_result.get("targets_enqueued")),
            "targets_skipped_duplicate": _normalize_non_negative_int(reconcile_result.get("targets_skipped_duplicate")),
            "state": str(reconcile_result.get("state") or "").strip() or None,
        }
    if updates.get("comments_streaming_last_error"):
        entry["error"] = str(updates.get("comments_streaming_last_error") or "").strip()
    if updates.get("comments_streaming_last_conflict"):
        entry["conflict"] = str(updates.get("comments_streaming_last_conflict") or "").strip()
    return [*prior_entries, entry][-_COMMENTS_STREAMING_HISTORY_LIMIT:]


def _catalog_comments_streaming_counter_updates(
    run_config: Mapping[str, Any],
    *,
    state: str,
    targets_seen_delta: int = 0,
    targets_enqueued_delta: int = 0,
    targets_skipped_duplicate_delta: int = 0,
    append_failures_delta: int = 0,
    enqueue_requested_at: datetime | None = None,
    enqueue_completed_at: datetime | None = None,
    enqueue_targets_seen: int = 0,
    enqueue_targets_enqueued: int = 0,
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    now_iso = _iso(_now_utc())
    updates: dict[str, Any] = {
        "comments_streaming_enabled": True,
        "comments_streaming_state": state,
        "comments_streaming_source": "catalog_batch_persist",
        "comments_streaming_targets_seen": _normalize_non_negative_int(
            run_config.get("comments_streaming_targets_seen")
        )
        + max(0, int(targets_seen_delta or 0)),
        "comments_streaming_targets_enqueued": _normalize_non_negative_int(
            run_config.get("comments_streaming_targets_enqueued")
        )
        + max(0, int(targets_enqueued_delta or 0)),
        "comments_streaming_targets_skipped_duplicate": _normalize_non_negative_int(
            run_config.get("comments_streaming_targets_skipped_duplicate")
        )
        + max(0, int(targets_skipped_duplicate_delta or 0)),
        "comments_streaming_append_failures": _normalize_non_negative_int(
            run_config.get("comments_streaming_append_failures")
        )
        + max(0, int(append_failures_delta or 0)),
        "comments_streaming_last_updated_at": now_iso,
    }
    if state == "started":
        updates.setdefault("comments_streaming_started_at", run_config.get("comments_streaming_started_at") or now_iso)
    if state == "completed":
        updates["comments_streaming_completed_at"] = now_iso
    updates.update(
        _catalog_comments_streaming_enqueue_lag_updates(
            run_config,
            enqueue_requested_at=enqueue_requested_at,
            enqueue_completed_at=enqueue_completed_at,
            targets_seen=enqueue_targets_seen,
            targets_enqueued=enqueue_targets_enqueued,
        )
    )
    if extra:
        updates.update(dict(extra))
    updates["comments_streaming_history"] = _catalog_comments_streaming_history_updates(
        run_config,
        updates,
        state=state,
        enqueue_targets_seen=enqueue_targets_seen,
        enqueue_targets_enqueued=enqueue_targets_enqueued,
    )
    return updates


def _catalog_comments_streaming_batch_size(run_config: Mapping[str, Any]) -> int:
    configured = _normalize_non_negative_int(
        run_config.get("comments_target_batch_size")
    ) or _normalize_non_negative_int(
        run_config.get("comments_streaming_target_batch_size"),
    )
    return max(1, configured or 1)


def _feed_instagram_catalog_comment_targets_from_batch(
    *,
    run_id: str | None,
    account_handle: str,
    source_scope: str,
    source_ids: Sequence[Any] | None,
    dispatch_immediately: bool = True,
) -> dict[str, Any]:
    normalized_run_id = str(run_id or "").strip()
    targets = _dedupe_catalog_comments_source_ids(source_ids)
    if not normalized_run_id or not targets:
        return {
            "run_id": normalized_run_id or None,
            "targets_seen": len(targets),
            "targets_enqueued": 0,
            "reason": "run_id_or_targets_required",
        }
    enqueue_requested_at: datetime | None = None
    try:
        run_row = _load_catalog_run_row_by_id(normalized_run_id)
        run_config = _metadata_dict(run_row.get("config"))
        if not bool(run_config.get("comments_streaming_enabled")):
            return {
                "run_id": normalized_run_id,
                "targets_seen": len(targets),
                "targets_enqueued": 0,
                "reason": "comments_streaming_disabled",
            }
        normalized_account = _normalize_social_account_profile_handle(
            run_config.get("comments_streaming_account_handle") or account_handle
        )
        effective_source_scope = str(run_config.get("comments_streaming_source_scope") or source_scope or "network")
        launch_group_id = str(run_config.get("comments_streaming_launch_group_id") or "").strip() or None
        comments_worker_count = _normalize_non_negative_int(run_config.get("comments_streaming_worker_count")) or None
        comments_enable_media_followups = bool(run_config.get("comments_streaming_enable_media_followups"))
        comments_run_id = str(run_config.get("comments_run_id") or "").strip()
        comments_batch_size = _catalog_comments_streaming_batch_size(run_config)
        attached_followups = _normalize_attached_followups(run_config.get("attached_followups"))

        if not comments_run_id:
            enqueue_requested_at = _now_utc()
            comments_result = start_social_account_comments_scrape(
                "instagram",
                normalized_account,
                mode="profile",
                source_scope=effective_source_scope,
                max_posts=None,
                max_comments_per_post=None,
                refresh_policy="stale_or_missing",
                initiated_by="catalog_batch_comments_stream",
                comments_load_strategy="public_relay",
                comments_enable_media_followups=comments_enable_media_followups,
                launch_group_id=launch_group_id,
                dispatch_immediately=dispatch_immediately,
                skip_launch_auth_probe=True,
                target_source_ids=targets,
                comments_worker_count=comments_worker_count,
                comments_target_batch_size=comments_batch_size,
                cancel_active_before_relaunch=False,
            )
            enqueue_completed_at = _now_utc()
            comments_run_id = str((comments_result or {}).get("run_id") or "").strip()
            target_count = _normalize_non_negative_int((comments_result or {}).get("target_source_ids_count")) or len(
                targets
            )
            updates = _catalog_comments_streaming_counter_updates(
                run_config,
                state="started",
                targets_seen_delta=len(targets),
                targets_enqueued_delta=target_count,
                enqueue_requested_at=enqueue_requested_at,
                enqueue_completed_at=enqueue_completed_at,
                enqueue_targets_seen=len(targets),
                enqueue_targets_enqueued=target_count,
                extra={
                    "comments_run_id": comments_run_id or None,
                    "attached_followups": {
                        **attached_followups,
                        "comments": _build_attached_comments_followup(
                            run_id=comments_run_id or None,
                            status=str((comments_result or {}).get("status") or "").strip().lower() or "pending",
                            source="catalog_streaming",
                            state="pending",
                        ),
                    },
                    "comments_streaming_last_batch_source_ids_count": len(targets),
                },
            )
            _merge_catalog_run_config(run_id=normalized_run_id, metadata_updates=updates)
            return {
                "run_id": normalized_run_id,
                "comments_run_id": comments_run_id or None,
                "targets_seen": len(targets),
                "targets_enqueued": target_count,
                "state": "started",
                "start_result": comments_result,
            }

        enqueue_requested_at = _now_utc()
        append_result = append_instagram_comments_catalog_stream_targets_to_active_run(
            run_id=comments_run_id,
            account_handle=normalized_account,
            target_source_ids=targets,
            batch_size=comments_batch_size,
            initiated_by="catalog_batch_comments_stream",
            dispatch_immediately=dispatch_immediately,
            catalog_run_id=normalized_run_id,
            comments_enable_media_followups=comments_enable_media_followups,
        )
        enqueue_completed_at = _now_utc()
        skipped_duplicates = _as_text_list(append_result.get("skipped_duplicate_target_source_ids"))
        target_rows = list(append_result.get("target_rows") or [])
        targets_enqueued = len(target_rows)
        append_reason = str(append_result.get("reason") or "").strip()
        append_failed = bool(append_reason and append_reason not in {"all_targets_already_represented"})
        state = "failed" if append_failed else "appending"
        updates = _catalog_comments_streaming_counter_updates(
            run_config,
            state=state,
            targets_seen_delta=len(targets),
            targets_enqueued_delta=targets_enqueued,
            targets_skipped_duplicate_delta=len(skipped_duplicates),
            append_failures_delta=1 if append_failed else 0,
            enqueue_requested_at=enqueue_requested_at,
            enqueue_completed_at=enqueue_completed_at,
            enqueue_targets_seen=len(targets),
            enqueue_targets_enqueued=targets_enqueued,
            extra={
                "comments_streaming_last_batch_source_ids_count": len(targets),
                "comments_streaming_last_append_result": {
                    "comments_run_id": comments_run_id,
                    "created_job_count": _normalize_non_negative_int(append_result.get("created_job_count")),
                    "targets_enqueued": targets_enqueued,
                    "targets_skipped_duplicate": len(skipped_duplicates),
                    "reason": append_reason or None,
                },
            },
        )
        _merge_catalog_run_config(run_id=normalized_run_id, metadata_updates=updates)
        return {
            "run_id": normalized_run_id,
            "comments_run_id": comments_run_id,
            "targets_seen": len(targets),
            "targets_enqueued": targets_enqueued,
            "targets_skipped_duplicate": len(skipped_duplicates),
            "state": state,
            "append_result": append_result,
        }
    except SocialIngestConflictError as exc:
        if exc.code != "SOCIAL_ACCOUNT_COMMENTS_RUN_ALREADY_ACTIVE":
            raise
        active_comments_run_id = str(exc.detail.get("run_id") or "").strip()
        if not active_comments_run_id:
            raise
        conflict_run_row = _load_catalog_run_row_by_id(normalized_run_id)
        conflict_run_config = _metadata_dict(conflict_run_row.get("config"))
        _merge_catalog_run_config(
            run_id=normalized_run_id,
            metadata_updates={
                "comments_run_id": active_comments_run_id,
                **_catalog_comments_streaming_counter_updates(
                    conflict_run_config,
                    state="appending",
                    targets_seen_delta=0,
                    extra={"comments_streaming_last_conflict": exc.code},
                ),
            },
        )
        return _feed_instagram_catalog_comment_targets_from_batch(
            run_id=normalized_run_id,
            account_handle=account_handle,
            source_scope=source_scope,
            source_ids=targets,
            dispatch_immediately=dispatch_immediately,
        )
    except Exception as exc:  # noqa: BLE001
        logger.exception(
            "[shared-account] failed streaming Instagram catalog comments targets: run_id=%s account=%s targets=%s",
            normalized_run_id,
            account_handle,
            len(targets),
        )
        try:
            run_row = _load_catalog_run_row_by_id(normalized_run_id)
            run_config = _metadata_dict(run_row.get("config"))
            _merge_catalog_run_config(
                run_id=normalized_run_id,
                metadata_updates=_catalog_comments_streaming_counter_updates(
                    run_config,
                    state="failed",
                    targets_seen_delta=len(targets),
                    append_failures_delta=1,
                    enqueue_requested_at=enqueue_requested_at,
                    enqueue_completed_at=_now_utc() if enqueue_requested_at is not None else None,
                    enqueue_targets_seen=len(targets),
                    enqueue_targets_enqueued=0,
                    extra={"comments_streaming_last_error": str(exc)},
                ),
            )
        except Exception:
            logger.debug(
                "[shared-account] failed recording comments streaming failure: run_id=%s",
                normalized_run_id,
                exc_info=True,
            )
        return {
            "run_id": normalized_run_id,
            "targets_seen": len(targets),
            "targets_enqueued": 0,
            "state": "failed",
            "error": str(exc),
        }


def _instagram_catalog_comments_streaming_saved_source_ids(
    *,
    run_id: str,
) -> list[str]:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return []
    rows = pg.fetch_all(
        """
        select distinct source_id
        from social.instagram_account_catalog_posts
        where last_backfill_run_id = %s::uuid
          and nullif(source_id, '') is not null
        order by source_id
        """,
        [normalized_run_id],
    )
    return _dedupe_catalog_comments_source_ids([row.get("source_id") for row in rows])


def reconcile_instagram_catalog_comments_streaming_targets(
    *,
    run_id: str,
    dispatch_immediately: bool = True,
) -> dict[str, Any] | None:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return None
    run_row = _load_catalog_run_row_by_id(normalized_run_id)
    run_config = _metadata_dict(run_row.get("config"))
    if not bool(run_config.get("comments_streaming_enabled")):
        return None
    account_handle = _normalize_social_account_profile_handle(
        run_config.get("comments_streaming_account_handle") or run_config.get("account")
    )
    source_scope = str(run_config.get("comments_streaming_source_scope") or run_row.get("source_scope") or "network")
    source_ids = _instagram_catalog_comments_streaming_saved_source_ids(run_id=normalized_run_id)
    feed_result = _feed_instagram_catalog_comment_targets_from_batch(
        run_id=normalized_run_id,
        account_handle=account_handle,
        source_scope=source_scope,
        source_ids=source_ids,
        dispatch_immediately=dispatch_immediately,
    )
    refreshed_row = _load_catalog_run_row_by_id(normalized_run_id)
    refreshed_config = _metadata_dict(refreshed_row.get("config"))
    if str(feed_result.get("state") or "").strip().lower() != "failed":
        updates = _catalog_comments_streaming_counter_updates(
            refreshed_config,
            state="completed",
            extra={
                "comments_streaming_reconciled_at": _iso(_now_utc()),
                "comments_streaming_reconciled_source_ids": len(source_ids),
                "comments_streaming_last_reconcile_result": {
                    "targets_seen": _normalize_non_negative_int(feed_result.get("targets_seen")),
                    "targets_enqueued": _normalize_non_negative_int(feed_result.get("targets_enqueued")),
                    "targets_skipped_duplicate": _normalize_non_negative_int(
                        feed_result.get("targets_skipped_duplicate")
                    ),
                    "state": str(feed_result.get("state") or "").strip() or None,
                },
            },
        )
        _merge_catalog_run_config(run_id=normalized_run_id, metadata_updates=updates)
    return {
        "run_id": normalized_run_id,
        "source_ids_reconciled": len(source_ids),
        **feed_result,
    }


def _persist_shared_catalog_posts_batch(
    *,
    platform: str,
    run_id: str | None,
    account_handle: str,
    posts: Sequence[Any],
    job_id: str | None = None,
    source_scope: str = "network",
    enable_media_followups: bool = False,
    progress_callback: Callable[[dict[str, Any]], None] | None = None,
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    normalized_platform = _normalize_platform_name(platform)
    if normalized_platform == "instagram" and posts:
        _raise_if_shared_account_stage_cancelled(
            run_id=run_id,
            job_id=job_id,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            platform=normalized_platform,
            account_handle=account_handle,
            phase="before_catalog_upsert",
        )
        catalog_rows = _batch_upsert_shared_catalog_instagram_posts(
            run_id=run_id,
            account_handle=account_handle,
            posts=list(posts),
        )
        if progress_callback is not None:
            progress_callback(
                {
                    "phase": "catalog_batch_upserted",
                    "catalog_posts_upserted": len(catalog_rows),
                    "total": len(posts),
                }
            )
        _sync_instagram_canonical_catalog_posts(catalog_rows, progress_callback=progress_callback)
        _raise_if_shared_account_stage_cancelled(
            run_id=run_id,
            job_id=job_id,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            platform=normalized_platform,
            account_handle=account_handle,
            phase="after_catalog_upsert",
        )
        if job_id is None and not enable_media_followups:
            source_ids = [sid for row in catalog_rows if (sid := str(_platform_source_id(platform, row)).strip())]
            deduped_source_ids = sorted(set(source_ids))
            _feed_instagram_catalog_comment_targets_from_batch(
                run_id=run_id,
                account_handle=account_handle,
                source_scope=source_scope,
                source_ids=deduped_source_ids,
            )
            return (
                catalog_rows,
                deduped_source_ids,
                {
                    "catalog_posts_upserted": len(catalog_rows),
                    "materialized_posts_upserted": 0,
                    "media_mirror_jobs_enqueued": 0,
                },
            )
        materialized_rows: list[dict[str, Any]] = []
        media_mirror_jobs_enqueued = 0
        try:
            with pg.db_connection(label="instagram-shared-catalog-materialize") as conn:
                _raise_if_shared_account_stage_cancelled(
                    run_id=run_id,
                    job_id=job_id,
                    stage=SHARED_ACCOUNT_POSTS_STAGE,
                    platform=normalized_platform,
                    account_handle=account_handle,
                    phase="before_materialize_posts",
                    conn=conn,
                )
                materialized_rows = _batch_upsert_instagram_posts(
                    None,
                    job_id=job_id,
                    account=account_handle,
                    posts=list(posts),
                    conn=conn,
                )
                if progress_callback is not None:
                    progress_callback(
                        {
                            "phase": "catalog_materialized_posts",
                            "materialized_posts_upserted": len(materialized_rows),
                            "total": len(posts),
                        }
                    )
                _raise_if_shared_account_stage_cancelled(
                    run_id=run_id,
                    job_id=job_id,
                    stage=SHARED_ACCOUNT_POSTS_STAGE,
                    platform=normalized_platform,
                    account_handle=account_handle,
                    phase="after_materialize_posts",
                    conn=conn,
                )
                if enable_media_followups and materialized_rows:
                    _raise_if_shared_account_stage_cancelled(
                        run_id=run_id,
                        job_id=job_id,
                        stage=SHARED_ACCOUNT_POSTS_STAGE,
                        platform=normalized_platform,
                        account_handle=account_handle,
                        phase="before_media_enqueue",
                        conn=conn,
                    )
                    media_mirror_jobs_enqueued = len(
                        _bulk_enqueue_platform_media_mirror_jobs(
                            None,
                            platform="instagram",
                            run_id=run_id,
                            source_scope=source_scope,
                            account=account_handle,
                            post_rows=materialized_rows,
                            week_index=None,
                            parent_job_id=job_id,
                            conn=conn,
                        )
                    )
                    if progress_callback is not None:
                        progress_callback(
                            {
                                "phase": "catalog_media_followups_enqueued",
                                "media_mirror_jobs_enqueued": media_mirror_jobs_enqueued,
                                "materialized_posts_upserted": len(materialized_rows),
                            }
                        )
        except pg.DatabaseServiceUnavailableError:
            if job_id is not None:
                raise
            logger.warning(
                (
                    "[shared-account] instagram catalog materialization deferred "
                    "for account=%s run_id=%s because the database is unavailable"
                ),
                account_handle,
                run_id,
            )
        rows = materialized_rows or catalog_rows
        source_ids = [sid for row in rows if (sid := str(_platform_source_id(platform, row)).strip())]
        deduped_source_ids = sorted(set(source_ids))
        _feed_instagram_catalog_comment_targets_from_batch(
            run_id=run_id,
            account_handle=account_handle,
            source_scope=source_scope,
            source_ids=deduped_source_ids,
        )
        return (
            rows,
            deduped_source_ids,
            {
                "catalog_posts_upserted": len(catalog_rows),
                "materialized_posts_upserted": len(materialized_rows),
                "media_mirror_jobs_enqueued": media_mirror_jobs_enqueued,
            },
        )

    rows: list[dict[str, Any]] = []
    source_ids_list: list[str] = []
    for post in posts:
        row = _upsert_shared_catalog_post(
            platform=platform,
            run_id=run_id,
            account_handle=account_handle,
            post=post,
        )
        if row:
            rows.append(row)
            source_id = _platform_source_id(platform, row)
            if source_id:
                source_ids_list.append(source_id)
    deduped_source_ids = sorted({str(source_id).strip() for source_id in source_ids_list if str(source_id).strip()})
    return (
        rows,
        deduped_source_ids,
        {
            "catalog_posts_upserted": len(rows),
            "materialized_posts_upserted": 0,
            "media_mirror_jobs_enqueued": 0,
        },
    )


def _normalize_shared_catalog_posts_batch_result(
    value: Any,
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    if isinstance(value, tuple):
        if len(value) == 3:
            rows, source_ids, persist_meta = value
        elif len(value) == 2:
            rows, source_ids = value
            persist_meta = {}
        else:
            raise ValueError("shared catalog post batch result must contain 2 or 3 items")
    else:
        raise ValueError("shared catalog post batch result must be a tuple")
    return list(rows or []), list(source_ids or []), dict(persist_meta or {})


def _shared_posts_frontier_max_attempts() -> int:
    # The sequential frontier walk can exceed the Modal function window several
    # times on large accounts; per-page cursor progress is durable, so allow
    # more attempts than the queue default of 3.
    return _resolve_positive_int_env(
        "TRR_SOCIAL_SHARED_POSTS_FRONTIER_MAX_ATTEMPTS",
        SOCIAL_SHARED_POSTS_FRONTIER_MAX_ATTEMPTS_DEFAULT,
        minimum=1,
    )


def _run_shared_account_discovery_frontier_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    job_id: str,
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    followup_worker_id = _inline_fallback_followup_worker_id(config, worker_id=worker_id)
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": "history_bootstrap_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
        "saved_posts": 0,
    }
    expected_total_posts = _shared_account_expected_total_posts_from_config(
        config,
        platform=platform,
        account_handle=account_handle,
    )
    catalog_oldest_post_at = _catalog_oldest_stored_post_at(platform, account_handle)

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=SHARED_ACCOUNT_DISCOVERY_STAGE,
            platform=platform,
            account=account_handle,
            scraped_posts=_normalize_non_negative_int(activity.get("posts_checked")),
            scraped_comments=0,
            posts_upserted=_normalize_non_negative_int(activity.get("saved_posts")),
            comments_upserted=0,
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)
    resume_cursor = str(config.get("resume_frontier_cursor") or "").strip() or None
    resume_snapshot = _metadata_dict(config.get("resume_frontier_snapshot"))
    auth_allowed, auth_reason = _shared_instagram_frontier_auth_validation(config)
    if resume_cursor:
        resumed_total_posts = max(
            expected_total_posts,
            _normalize_non_negative_int(resume_snapshot.get("total_posts")),
        )
        resumed_posts_checked = _normalize_non_negative_int(resume_snapshot.get("posts_checked"))
        resumed_posts_saved = _normalize_non_negative_int(resume_snapshot.get("posts_saved"))
        resumed_pages_scanned = _normalize_non_negative_int(resume_snapshot.get("pages_scanned"))
        resumed_transport = (
            str(resume_snapshot.get("last_transport") or config.get("frontier_transport") or "public").strip().lower()
        )
        frontier = _ensure_shared_account_run_frontier(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            strategy=CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
            status="queued",
            next_cursor=resume_cursor,
            total_posts=resumed_total_posts,
            posts_checked=resumed_posts_checked,
            posts_saved=resumed_posts_saved,
            pages_scanned=resumed_pages_scanned,
            last_transport=resumed_transport,
            retry_count=0,
            exhausted=False,
            metadata={
                "auth_allowed": auth_allowed,
                "auth_reason": auth_reason,
                "bootstrap_job_id": job_id,
                "resumed_from_run_id": resume_snapshot.get("run_id"),
                "resumed_from_frontier_id": resume_snapshot.get("id"),
                "resumed_cursor": resume_cursor,
            },
        )
        next_job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            config={
                "stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "shared_account_source_id": config.get("shared_account_source_id"),
                "pipeline_ingest_mode": config.get("pipeline_ingest_mode"),
                "partition_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                "runner_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                "runner_count": _normalize_non_negative_int(config.get("runner_count"))
                or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                "max_posts_per_target": 0,
                "expected_total_posts": resumed_total_posts or None,
                "required_worker_lane": config.get("required_worker_lane"),
                "required_execution_backend": config.get("required_execution_backend"),
                "allow_local_dev_inline_bypass": bool(config.get("allow_local_dev_inline_bypass")),
                "frontier_auth_allowed": auth_allowed,
                "frontier_auth_reason": auth_reason,
                "frontier_transport": resumed_transport,
                "date_start": config.get("date_start"),
                "date_end": config.get("date_end"),
                "catalog_action": str(config.get("catalog_action") or "").strip().lower() or None,
                "catalog_action_scope": str(config.get("catalog_action_scope") or "").strip().lower() or None,
                "selected_tasks": config.get("selected_tasks"),
                "effective_selected_tasks": config.get("effective_selected_tasks"),
                "details_refresh_skip_detail_fetch": config.get("details_refresh_skip_detail_fetch"),
                "details_refresh_force_detail_fetch": config.get("details_refresh_force_detail_fetch"),
                "details_refresh_skip_media_followups": config.get("details_refresh_skip_media_followups"),
                "comments_worker_count": config.get("comments_worker_count"),
                "tiktok_comments_in_posts_stage": bool(config.get("tiktok_comments_in_posts_stage")),
                "tiktok_direct_comment_api_override": bool(config.get("tiktok_direct_comment_api_override")),
                "twitter_comments_in_posts_stage": bool(config.get("twitter_comments_in_posts_stage")),
            },
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=101,
            worker_id=followup_worker_id,
            preclaim=bool(followup_worker_id),
            max_attempts=_shared_posts_frontier_max_attempts(),
        )
        activity.update(
            {
                "phase": "history_bootstrap_resume",
                "pages_scanned": resumed_pages_scanned,
                "posts_checked": resumed_posts_checked,
                "matched_posts": resumed_posts_saved,
                "saved_posts": resumed_posts_saved,
                "total_posts": resumed_total_posts or None,
            }
        )
        _flush_progress(force=True)
        return (
            0,
            0,
            {
                "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                "platform": platform,
                "account": account_handle,
                "partition_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                "discovered_partition_count": 0,
                "frontier_bootstrap_completed": True,
                "resumed_from_cursor": True,
                "frontier_job_id": next_job_id,
                "frontier": {
                    "status": frontier.get("status"),
                    "next_cursor_present": bool(frontier.get("next_cursor")),
                    "pages_scanned": resumed_pages_scanned,
                    "posts_checked": resumed_posts_checked,
                    "posts_saved": resumed_posts_saved,
                    "expected_total_posts": resumed_total_posts or None,
                    "transport": resumed_transport,
                },
                "retrieval_meta": {
                    "resumed_from_run_id": resume_snapshot.get("run_id"),
                    "resumed_from_frontier_id": resume_snapshot.get("id"),
                },
                "expected_total_posts": resumed_total_posts or None,
                "activity": dict(activity),
                "pipeline_ingest_mode": str(
                    config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                ),
            },
        )
    activity["phase"] = "history_bootstrap_fetching_first_page"
    _flush_progress(force=True)
    preferred_transport, allow_public_fallback = _shared_instagram_frontier_transport_preferences(
        config,
        auth_allowed=auth_allowed,
    )
    page_posts, page_info, retrieval_meta, selected_transport = _fetch_shared_instagram_graphql_posts_page(
        account_handle=account_handle,
        cursor=None,
        delay_seconds=_shared_instagram_graphql_delay_seconds(jitter=True),
        preferred_transport=preferred_transport,
        allow_public_fallback=allow_public_fallback,
        auth_allowed=auth_allowed,
    )
    if not page_posts:
        error_code = str(retrieval_meta.get("error_code") or "instagram_graphql_initial_request_failed").strip().lower()
        raise SharedStageRuntimeError(
            f"Instagram @{account_handle} history bootstrap failed: {error_code}",
            error_code=error_code,
            retryable=bool(retrieval_meta.get("retryable", True)),
            error_class=str(retrieval_meta.get("error_class") or "SharedStageRuntimeError"),
            runtime_metadata={"retrieval_meta": retrieval_meta},
        )
    activity["phase"] = "history_bootstrap_saving_first_page"
    activity["posts_checked"] = len(page_posts)
    _flush_progress(force=True)
    bounded_start = _coerce_dt(config.get("date_start"))
    bounded_end = _coerce_dt(config.get("date_end"))
    bounded_window = _catalog_backfill_has_bounded_window(date_start=bounded_start, date_end=bounded_end)
    posts_to_persist, crossed_bounded_start = _filter_shared_instagram_posts_for_window(
        page_posts,
        date_start=bounded_start,
        date_end=bounded_end,
    )

    def _on_bootstrap_persist_progress(payload: dict[str, Any]) -> None:
        activity["phase"] = str(payload.get("phase") or "history_bootstrap_persisting_first_page")
        activity["persist_progress"] = payload
        _flush_progress(force=True)

    rows, _source_ids, persist_meta = _normalize_shared_catalog_posts_batch_result(
        _persist_shared_catalog_posts_batch(
            platform=platform,
            run_id=run_id,
            account_handle=account_handle,
            posts=posts_to_persist,
            job_id=job_id,
            source_scope=source_scope,
            enable_media_followups=not bool(config.get("details_refresh_skip_media_followups")),
            progress_callback=_on_bootstrap_persist_progress,
        )
    )
    pages_scanned = 1
    posts_checked = len(page_posts)
    saved_posts = len(rows)
    oldest_posted_at_seen, newest_posted_at_seen = _shared_instagram_posted_at_bounds(page_posts)
    total_posts = max(
        expected_total_posts,
        _normalize_non_negative_int(retrieval_meta.get("total_posts")),
    )
    next_cursor = str(page_info.get("end_cursor") or "").strip() or None
    has_more_source_pages = bool(page_info.get("has_next_page")) and bool(next_cursor)
    has_next = has_more_source_pages and not crossed_bounded_start
    frontier_stop_reason = (
        "bounded_window_start_reached" if crossed_bounded_start else "source_exhausted" if not has_next else None
    )
    frontier_metadata = {
        "auth_allowed": auth_allowed,
        "auth_reason": auth_reason,
        "bootstrap_job_id": job_id,
        "date_start": _iso(bounded_start),
        "date_end": _iso(bounded_end),
        "bounded_window": bounded_window,
        "bounded_window_start_reached": crossed_bounded_start,
        "bounded_window_next_cursor": next_cursor if crossed_bounded_start and has_more_source_pages else None,
        # Bootstrap is page 1 from the top, so the lossless resume point is "from top".
        "bounded_window_resume_cursor": None,
        "last_error_code": retrieval_meta.get("error_code"),
        "last_error_class": retrieval_meta.get("error_class"),
        "last_error_message": retrieval_meta.get("error_message"),
        "frontier_stop_reason": frontier_stop_reason,
        "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
        "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
        "newest_posted_at_seen": _iso(newest_posted_at_seen),
    }
    if persist_meta.get("media_mirror_jobs_enqueued"):
        retrieval_meta["media_mirror_jobs_enqueued"] = persist_meta["media_mirror_jobs_enqueued"]
    completion_gap_reason = (
        None
        if bounded_window
        else _shared_account_frontier_completion_gap_reason(
            expected_total_posts=total_posts,
            posts_checked=posts_checked,
            catalog_oldest_post_at=catalog_oldest_post_at,
            oldest_posted_at_seen=oldest_posted_at_seen,
        )
    )
    activity["phase"] = "history_bootstrap_creating_frontier"
    activity["saved_posts"] = saved_posts
    activity["total_posts"] = total_posts or None
    _flush_progress(force=True)
    frontier = _ensure_shared_account_run_frontier(
        run_id=run_id,
        platform=platform,
        account_handle=account_handle,
        strategy=CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
        status="queued" if has_next else ("retrying" if completion_gap_reason else "completed"),
        next_cursor=next_cursor if has_next else None,
        total_posts=total_posts,
        posts_checked=posts_checked,
        posts_saved=saved_posts,
        pages_scanned=pages_scanned,
        last_transport=selected_transport,
        retry_count=0,
        exhausted=not has_next and not bool(completion_gap_reason),
        metadata=frontier_metadata,
    )
    activity.update(
        {
            "phase": "history_bootstrap_end",
            "pages_scanned": pages_scanned,
            "posts_checked": posts_checked,
            "matched_posts": saved_posts,
            "saved_posts": saved_posts,
            "total_posts": total_posts or None,
        }
    )
    next_job_id: str | None = None
    if has_next:
        next_job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            config={
                "stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "shared_account_source_id": config.get("shared_account_source_id"),
                "pipeline_ingest_mode": config.get("pipeline_ingest_mode"),
                "partition_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                "runner_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                "runner_count": _normalize_non_negative_int(config.get("runner_count"))
                or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                "max_posts_per_target": 0,
                "expected_total_posts": total_posts or None,
                "required_worker_lane": config.get("required_worker_lane"),
                "required_execution_backend": config.get("required_execution_backend"),
                "allow_local_dev_inline_bypass": bool(config.get("allow_local_dev_inline_bypass")),
                "frontier_auth_allowed": auth_allowed,
                "frontier_auth_reason": auth_reason,
                "frontier_transport": selected_transport,
                "date_start": config.get("date_start"),
                "date_end": config.get("date_end"),
                "catalog_action": str(config.get("catalog_action") or "").strip().lower() or None,
                "catalog_action_scope": str(config.get("catalog_action_scope") or "").strip().lower() or None,
                "selected_tasks": config.get("selected_tasks"),
                "effective_selected_tasks": config.get("effective_selected_tasks"),
                "details_refresh_skip_detail_fetch": config.get("details_refresh_skip_detail_fetch"),
                "details_refresh_force_detail_fetch": config.get("details_refresh_force_detail_fetch"),
                "details_refresh_skip_media_followups": config.get("details_refresh_skip_media_followups"),
                "comments_worker_count": config.get("comments_worker_count"),
                "tiktok_comments_in_posts_stage": bool(config.get("tiktok_comments_in_posts_stage")),
                "tiktok_direct_comment_api_override": bool(config.get("tiktok_direct_comment_api_override")),
                "twitter_comments_in_posts_stage": bool(config.get("twitter_comments_in_posts_stage")),
            },
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=101,
            worker_id=followup_worker_id,
            preclaim=bool(followup_worker_id),
            max_attempts=_shared_posts_frontier_max_attempts(),
        )
    elif completion_gap_reason:
        raise SharedStageRuntimeError(
            (
                f"Instagram @{account_handle} history bootstrap ended before full-history coverage was proven: "
                f"{completion_gap_reason}"
            ),
            error_code="catalog_incomplete",
            retryable=True,
            runtime_metadata={
                "retrieval_meta": {
                    **dict(retrieval_meta or {}),
                    "expected_total_posts": total_posts,
                    "observed_posts_checked": posts_checked,
                    "observed_posts_saved": saved_posts,
                    "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                    "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                    "newest_posted_at_seen": _iso(newest_posted_at_seen),
                    "frontier_stop_reason": completion_gap_reason,
                },
                "frontier": frontier,
            },
        )
    _flush_progress(force=True)
    return (
        saved_posts,
        0,
        {
            "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
            "platform": platform,
            "account": account_handle,
            "partition_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
            "discovered_partition_count": 0,
            "frontier_bootstrap_completed": True,
            "frontier_job_id": next_job_id,
            "frontier": {
                "status": frontier.get("status"),
                "next_cursor_present": bool(frontier.get("next_cursor")),
                "pages_scanned": pages_scanned,
                "posts_checked": posts_checked,
                "posts_saved": saved_posts,
                "expected_total_posts": total_posts or None,
                "transport": selected_transport,
            },
            "retrieval_meta": retrieval_meta,
            "expected_total_posts": total_posts or None,
            "activity": dict(activity),
            "pipeline_ingest_mode": str(
                config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
            ),
        },
    )


def _discover_instagram_cursor_partitions(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.instagram.catalog_ingest import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["_discover_instagram_cursor_partitions"](*args, **kwargs)


def _bootstrap_shared_tiktok_account_context(
    *,
    account_handle: str,
    delay_seconds: float = 0.35,
    scraper: Any | None = None,
    direct_comment_api_enabled_override: bool | None = None,
) -> dict[str, Any]:
    from trr_backend.socials.tiktok import TikTokScraper

    scraper_kwargs: dict[str, Any] = {"cookies": _load_tiktok_cookies()}
    if direct_comment_api_enabled_override is not None:
        scraper_kwargs["direct_comment_api_enabled_override"] = direct_comment_api_enabled_override
    tiktok_scraper = scraper or TikTokScraper(**scraper_kwargs)
    try:
        user_data = tiktok_scraper.fetch_user_detail(account_handle, delay_seconds)
    except Exception:  # noqa: BLE001
        logger.warning("[tiktok] shared-account user-detail enrichment failed for @%s", account_handle)
        user_data = None
    try:
        html_data = tiktok_scraper._fetch_profile_html(account_handle, delay_seconds)  # noqa: SLF001
    except Exception:  # noqa: BLE001
        logger.warning("[tiktok] shared-account html enrichment failed for @%s", account_handle)
        html_data = None
    try:
        html_items, html_sec_uid = tiktok_scraper._extract_posts_from_html_data(html_data or {}, account_handle)  # noqa: SLF001
    except Exception:  # noqa: BLE001
        logger.warning("[tiktok] shared-account html parsing failed for @%s", account_handle)
        html_items, html_sec_uid = [], None
    try:
        profile_snapshot = tiktok_scraper.build_profile_snapshot(
            account_handle,
            user_data=user_data,
            html_data=html_data,
        )
    except Exception:  # noqa: BLE001
        logger.warning("[tiktok] shared-account profile snapshot build failed for @%s", account_handle)
        profile_snapshot = {}
    sec_uid = str(profile_snapshot.get("sec_uid") or html_sec_uid or "").strip() or None
    total_posts = max(
        _normalize_non_negative_int(profile_snapshot.get("total_posts")),
        len(html_items),
    )
    if total_posts > 0:
        profile_snapshot["total_posts"] = total_posts
    if sec_uid:
        profile_snapshot["sec_uid"] = sec_uid
    return {
        "scraper": tiktok_scraper,
        "user_data": user_data,
        "html_data": html_data,
        "html_items": html_items,
        "sec_uid": sec_uid,
        "profile_snapshot": profile_snapshot,
        "total_posts": total_posts,
    }


def _apply_tiktok_profile_snapshot_to_post(post: Any, snapshot: Mapping[str, Any] | None) -> Any:
    metadata = _metadata_dict(snapshot)
    if not metadata:
        return post
    if not getattr(post, "author_nickname", None) and str(metadata.get("display_name") or "").strip():
        post.author_nickname = str(metadata.get("display_name") or "").strip()
    if not getattr(post, "user_avatar_url", None) and str(metadata.get("avatar_url") or "").strip():
        post.user_avatar_url = str(metadata.get("avatar_url") or "").strip()
    if not getattr(post, "username", None) and str(metadata.get("username") or "").strip():
        post.username = str(metadata.get("username") or "").strip()
    return post


def _shared_tiktok_catalog_effective_tasks(config: Mapping[str, Any]) -> set[str]:
    tasks = _normalize_optional_social_account_catalog_backfill_selected_tasks(
        config.get("effective_selected_tasks")
    ) or _normalize_optional_social_account_catalog_backfill_selected_tasks(config.get("selected_tasks"))
    if tasks:
        return set(tasks)
    if not _shared_catalog_mode(config):
        return set()
    task_hint_present = any(
        key in config
        for key in (
            "details_refresh_skip_detail_fetch",
            "details_refresh_skip_media_followups",
            "tiktok_comments_in_posts_stage",
            "tiktok_direct_comment_api_override",
        )
    )
    if not task_hint_present:
        return set()

    inferred: list[str] = []
    if not bool(config.get("details_refresh_skip_detail_fetch")):
        inferred.append("post_details")
    if bool(config.get("tiktok_comments_in_posts_stage")):
        inferred.append("comments")
    if not bool(config.get("details_refresh_skip_media_followups")):
        inferred.append("media")
    return set(_normalize_optional_social_account_catalog_backfill_selected_tasks(inferred) or inferred)


def _shared_tiktok_catalog_comments_enabled(config: Mapping[str, Any]) -> bool:
    return "comments" in _shared_tiktok_catalog_effective_tasks(config) and bool(
        config.get("tiktok_comments_in_posts_stage")
    )


def _shared_tiktok_catalog_direct_comment_override(config: Mapping[str, Any]) -> bool | None:
    if _shared_tiktok_catalog_comments_enabled(config) and bool(config.get("tiktok_direct_comment_api_override")):
        return True
    return None


def _shared_tiktok_catalog_comment_delay_seconds() -> float:
    raw = str(os.getenv("SOCIAL_TIKTOK_CATALOG_COMMENT_DELAY_SECONDS") or "").strip()
    if not raw:
        return 0.35
    try:
        return max(0.05, float(raw))
    except ValueError:
        return 0.35


def _shared_tiktok_catalog_max_comments_per_post(config: Mapping[str, Any]) -> int:
    for key in ("max_comments_per_post", "catalog_max_comments_per_post"):
        if config.get(key) is not None:
            return _normalize_non_negative_int(config.get(key))
    return 0


def _shared_tiktok_comment_fetch_timeout_seconds(config: Mapping[str, Any]) -> int:
    for key in ("comment_fetch_timeout_seconds", "tiktok_comment_fetch_timeout_seconds"):
        if config.get(key) is not None:
            value = _normalize_non_negative_int(config.get(key))
            return max(5, value) if value > 0 else 0
    return max(5, _resolve_positive_int_env("SOCIAL_TIKTOK_COMMENT_FETCH_TIMEOUT_SECONDS", 180, minimum=5))


def _normalize_uuid_text(value: Any) -> str | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    try:
        return str(UUID(raw))
    except (TypeError, ValueError, AttributeError):
        return None


