def _enqueue_shared_classify_jobs_batched(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    source_ids: Sequence[Any],
    pipeline_ingest_mode: str,
    worker_id: str | None = None,
    conn: Any | None = None,
) -> list[str]:
    job_ids: list[str] = []
    for batch_index, source_id_batch in enumerate(_chunk_unique_source_ids(source_ids), start=1):
        job_ids.append(
            _create_job(
                None,
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                job_type=POST_CLASSIFY_JOB_TYPE,
                stage=POST_CLASSIFY_STAGE,
                config={
                    "stage": POST_CLASSIFY_STAGE,
                    "platform": platform,
                    "source_scope": source_scope,
                    "account": account_handle,
                    "source_ids": source_id_batch,
                    "pipeline_ingest_mode": pipeline_ingest_mode,
                    "batch_index": batch_index,
                    "batch_total_source_ids": len(source_id_batch),
                    "batch_strategy": "size_bounded",
                },
                initiated_by=None,
                status="queued" if is_queue_enabled() else "pending",
                priority=150,
                worker_id=worker_id,
                preclaim=bool(worker_id),
                conn=conn,
            )
        )
    return job_ids


def _maybe_enqueue_shared_catalog_classify_jobs_after_fetch(
    *,
    run_id: str,
    source_scope: str,
    run_config: Mapping[str, Any] | None = None,
    conn: Any | None = None,
) -> int:
    config = _metadata_dict(run_config)
    ingest_mode = _resolve_pipeline_ingest_mode(config.get("pipeline_ingest_mode"))
    if ingest_mode != SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
        return 0
    if bool(config.get("catalog_followups_disabled")):
        return 0
    if _metadata_dict(config.get("comment_anchor_source_ids")):
        return 0

    job_rows = pg.fetch_all(
        """
        select
          platform,
          lower(coalesce(config->>'account', '')) as account_handle,
          lower(coalesce(config->>'stage', metadata->>'stage', job_type, '')) as stage,
          lower(coalesce(status, '')) as status,
          coalesce(items_found, 0)::int as items_found,
          metadata,
          error_message,
          last_error_code
        from social.scrape_jobs
        where run_id = %s::uuid
          and lower(coalesce(config->>'stage', metadata->>'stage', job_type, '')) in (%s, %s, %s, %s, %s)
        """,
        [
            run_id,
            SHARED_ACCOUNT_DISCOVERY_STAGE,
            SHARED_ACCOUNT_POSTS_STAGE,
            TIKTOK_POSTS_SCRAPLING_STAGE,
            THREADS_POSTS_SCRAPLING_STAGE,
            POST_CLASSIFY_STAGE,
        ],
        conn=conn,
    )
    if not job_rows:
        return 0

    fetch_rows = [
        row for row in job_rows if str(row.get("stage") or "").strip().lower() in set(SHARED_ACCOUNT_FETCH_STAGES)
    ]
    if not fetch_rows:
        return 0
    if any(
        str(row.get("status") or "").strip().lower() in {"queued", "pending", "retrying", "running", "cancelling"}
        for row in fetch_rows
    ):
        return 0
    if any(str(row.get("status") or "").strip().lower() == "failed" for row in fetch_rows):
        return 0
    if any(_shared_catalog_fetch_row_has_terminal_error(row) for row in fetch_rows):
        return 0

    existing_classify = {
        (_normalize_platform_name(row.get("platform")) or "", str(row.get("account_handle") or "").strip().lower())
        for row in job_rows
        if str(row.get("stage") or "").strip().lower() == POST_CLASSIFY_STAGE
        and str(row.get("status") or "").strip().lower() != "cancelled"
    }
    fetch_targets = sorted(
        {
            (_normalize_platform_name(row.get("platform")) or "", str(row.get("account_handle") or "").strip().lower())
            for row in fetch_rows
            if (_normalize_platform_name(row.get("platform")) or "") and str(row.get("account_handle") or "").strip()
        }
    )

    created_jobs = 0
    for platform, account_handle in fetch_targets:
        if (platform, account_handle) in existing_classify:
            continue
        target_fetch_rows = [
            row
            for row in fetch_rows
            if (_normalize_platform_name(row.get("platform")) or "") == platform
            and str(row.get("account_handle") or "").strip().lower() == account_handle
        ]
        if _shared_catalog_fetch_rows_are_empty_result(target_fetch_rows):
            continue
        source_ids = sorted(
            {
                _platform_source_id(platform, row)
                for row in _shared_post_rows_for_account(
                    platform=platform,
                    account_handle=account_handle,
                    source_scope=source_scope,
                    unassigned_only=True,
                    conn=conn,
                )
                if isinstance(row, dict) and _platform_source_id(platform, row)
            }
        )
        if not source_ids:
            continue
        created_jobs += len(
            _enqueue_shared_classify_jobs_batched(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                source_ids=source_ids,
                pipeline_ingest_mode=ingest_mode,
                worker_id=None,
                conn=conn,
            )
        )
    return created_jobs


def _shared_catalog_fetch_rows_are_empty_result(rows: Sequence[Mapping[str, Any]]) -> bool:
    saw_empty_result = False
    for row in rows:
        if str(row.get("status") or "").strip().lower() != "completed":
            return False
        metadata = _metadata_dict(row.get("metadata"))
        retrieval_meta = _metadata_dict(metadata.get("retrieval_meta"))
        activity = _metadata_dict(metadata.get("activity"))
        empty_reason = str(
            retrieval_meta.get("empty_result_reason") or metadata.get("empty_result_reason") or ""
        ).strip()
        if empty_reason:
            saw_empty_result = True
        if (
            _normalize_non_negative_int(row.get("items_found")) > 0
            or _normalize_non_negative_int(activity.get("saved_posts")) > 0
            or _normalize_non_negative_int(activity.get("matched_posts")) > 0
        ):
            return False
    return saw_empty_result


def _shared_catalog_fetch_row_has_terminal_error(row: Mapping[str, Any]) -> bool:
    status = str(row.get("status") or "").strip().lower()
    if status in {"queued", "pending", "retrying", "running", "cancelling"}:
        return False
    metadata = _metadata_dict(row.get("metadata"))
    retrieval_meta = _metadata_dict(metadata.get("retrieval_meta"))
    if status == "completed":
        activity = _metadata_dict(metadata.get("activity"))
        persist_counters = _metadata_dict(metadata.get("persist_counters"))
        frontier = _metadata_dict(metadata.get("frontier"))
        frontier_status = str(frontier.get("status") or "").strip().lower()
        if (
            _normalize_non_negative_int(row.get("items_found")) > 0
            or _normalize_non_negative_int(activity.get("saved_posts")) > 0
            or _normalize_non_negative_int(activity.get("matched_posts")) > 0
            or _normalize_non_negative_int(persist_counters.get("posts_upserted")) > 0
            or bool(str(metadata.get("frontier_job_id") or "").strip())
            or frontier_status in {"queued", "pending", "retrying", "running"}
        ):
            return False
    error_code = (
        str(metadata.get("error_code") or retrieval_meta.get("error_code") or row.get("last_error_code") or "")
        .strip()
        .lower()
    )
    error_marker = str(metadata.get("error") or "").strip().lower()
    error_message = str(metadata.get("error_message") or row.get("error_message") or "").strip()
    recovery_reason = (
        str(metadata.get("recovery_reason") or retrieval_meta.get("recovery_reason") or "").strip().lower()
    )
    if (
        status == "completed"
        and error_code == "tiktok_discovery_empty_first_page"
        and recovery_reason == "tiktok_empty_body_transport_failure"
        and bool(metadata.get("fallback_direct_job_enqueued"))
    ):
        return False
    if status == "completed" and bool(retrieval_meta.get("completion_tolerance_applied")):
        return False
    return bool(error_code or error_marker or error_message)


def _shared_catalog_fetch_has_terminal_error(run_id: str, *, conn: Any | None = None) -> bool:
    job_rows = pg.fetch_all(
        """
        select
          lower(coalesce(config->>'stage', metadata->>'stage', job_type, '')) as stage,
          lower(coalesce(status, '')) as status,
          metadata,
          error_message,
          last_error_code
        from social.scrape_jobs
        where run_id = %s::uuid
          and lower(coalesce(config->>'stage', metadata->>'stage', job_type, '')) in (%s, %s, %s, %s)
        """,
        [
            run_id,
            SHARED_ACCOUNT_DISCOVERY_STAGE,
            SHARED_ACCOUNT_POSTS_STAGE,
            TIKTOK_POSTS_SCRAPLING_STAGE,
            THREADS_POSTS_SCRAPLING_STAGE,
        ],
        conn=conn,
    )
    fetch_rows = [
        row for row in job_rows if str(row.get("stage") or "").strip().lower() in set(SHARED_ACCOUNT_FETCH_STAGES)
    ]
    return any(_shared_catalog_fetch_row_has_terminal_error(row) for row in fetch_rows)


