def _enqueue_shared_discovery_job(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    shared_account_source_id: Any,
    pipeline_ingest_mode: str,
    runner_count: int,
    expected_total_posts: int | None = None,
    runner_strategy: str | None = None,
    partition_strategy: str | None = None,
    required_worker_lane: str | None = None,
    required_execution_backend: str | None = None,
    allow_local_dev_inline_bypass: bool = False,
    frontier_auth_allowed: bool | None = None,
    frontier_auth_reason: str | None = None,
    transport_preference: str | None = None,
    allow_public_transport_fallback: bool | None = None,
    resume_frontier_cursor: str | None = None,
    resume_frontier_snapshot: Mapping[str, Any] | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
    catalog_action: str | None = None,
    catalog_action_scope: str | None = None,
    selected_tasks: Sequence[Any] | None = None,
    effective_selected_tasks: Sequence[Any] | None = None,
    details_refresh_skip_detail_fetch: bool | None = None,
    details_refresh_force_detail_fetch: bool | None = None,
    details_refresh_skip_media_followups: bool | None = None,
    comments_worker_count: int | None = None,
    tiktok_comments_in_posts_stage: bool = False,
    tiktok_direct_comment_api_override: bool = False,
    twitter_comments_in_posts_stage: bool = False,
    initiated_by: str | None = None,
    worker_id: str | None = None,
    priority: int = 100,
    recovery_depth: int = 0,
) -> str:
    normalized_resume_cursor = str(resume_frontier_cursor or "").strip() or None
    normalized_selected_tasks = _normalize_optional_social_account_catalog_backfill_selected_tasks(selected_tasks)
    normalized_effective_tasks = (
        _normalize_optional_social_account_catalog_backfill_selected_tasks(effective_selected_tasks)
        or normalized_selected_tasks
    )
    return _create_job(
        None,
        run_id=run_id,
        platform=platform,
        source_scope=source_scope,
        job_type=SHARED_ACCOUNT_DISCOVERY_JOB_TYPE,
        stage=SHARED_ACCOUNT_DISCOVERY_STAGE,
        config={
            "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
            "platform": platform,
            "source_scope": source_scope,
            "account": account_handle,
            "shared_account_source_id": shared_account_source_id,
            "runner_count": runner_count,
            "runner_strategy": str(runner_strategy or "full_history_cursor_breakpoints").strip().lower(),
            "partition_strategy": str(partition_strategy or CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY)
            .strip()
            .lower(),
            "pipeline_ingest_mode": pipeline_ingest_mode,
            "expected_total_posts": _normalize_non_negative_int(expected_total_posts),
            "required_worker_lane": str(required_worker_lane or "").strip().lower() or None,
            "required_execution_backend": str(required_execution_backend or "").strip().lower() or None,
            "allow_local_dev_inline_bypass": bool(allow_local_dev_inline_bypass),
            "frontier_auth_allowed": frontier_auth_allowed,
            "frontier_auth_reason": str(frontier_auth_reason or "").strip().lower() or None,
            "transport_preference": str(transport_preference or "").strip().lower() or None,
            "allow_public_transport_fallback": allow_public_transport_fallback,
            "resume_frontier_cursor": normalized_resume_cursor,
            "resume_frontier_snapshot": dict(resume_frontier_snapshot or {}) if normalized_resume_cursor else None,
            "date_start": _iso(date_start),
            "date_end": _iso(date_end),
            "catalog_action": str(catalog_action or "").strip().lower() or None,
            "catalog_action_scope": str(catalog_action_scope or "").strip().lower() or None,
            "selected_tasks": normalized_selected_tasks or None,
            "effective_selected_tasks": normalized_effective_tasks or None,
            "details_refresh_skip_detail_fetch": (
                bool(details_refresh_skip_detail_fetch) if details_refresh_skip_detail_fetch is not None else None
            ),
            "details_refresh_force_detail_fetch": (
                bool(details_refresh_force_detail_fetch) if details_refresh_force_detail_fetch is not None else None
            ),
            "details_refresh_skip_media_followups": (
                bool(details_refresh_skip_media_followups) if details_refresh_skip_media_followups is not None else None
            ),
            "comments_worker_count": _normalize_non_negative_int(comments_worker_count) or None,
            "tiktok_comments_in_posts_stage": bool(tiktok_comments_in_posts_stage),
            "tiktok_direct_comment_api_override": bool(tiktok_direct_comment_api_override),
            "twitter_comments_in_posts_stage": bool(twitter_comments_in_posts_stage),
            "recovery_depth": max(0, int(recovery_depth)),
        },
        initiated_by=initiated_by,
        status="queued" if is_queue_enabled() else "pending",
        priority=priority,
        worker_id=worker_id,
        preclaim=bool(worker_id),
    )


def _run_shared_account_discovery_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    job_id: str,
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    if _shared_account_uses_frontier_strategy(config, platform=platform):
        return _run_shared_account_discovery_frontier_stage(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            account_handle=account_handle,
            config=config,
            job_id=job_id,
            worker_id=worker_id,
        )
    followup_worker_id = _inline_fallback_followup_worker_id(config, worker_id=worker_id)
    progress_state = _new_job_progress_state()
    runner_count = max(
        1,
        _normalize_non_negative_int(config.get("runner_count")) or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
    )
    activity: dict[str, Any] = {
        "phase": f"{SHARED_ACCOUNT_DISCOVERY_STAGE}_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
        "saved_posts": 0,
    }

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=SHARED_ACCOUNT_DISCOVERY_STAGE,
            platform=platform,
            account=account_handle,
            scraped_posts=_normalize_non_negative_int(activity.get("posts_checked")),
            scraped_comments=0,
            posts_upserted=_normalize_non_negative_int(activity.get("saved_posts")),
            comments_upserted=0,
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    def _on_discovery_progress(payload: dict[str, Any]) -> None:
        activity["phase"] = str(payload.get("phase") or "discover_history")
        activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
        activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
        activity["matched_posts"] = _normalize_non_negative_int(payload.get("discovered_partitions"))
        if payload.get("total_posts") is not None:
            activity["total_posts"] = _normalize_non_negative_int(payload.get("total_posts"))
        _flush_progress(force=False)

    _flush_progress(force=True)
    auth_allowed, auth_reason = (
        _shared_instagram_frontier_auth_validation(config) if platform == "instagram" else (True, None)
    )
    # Pre-compute values needed by the eager partition dispatch callback.
    expected_total_posts = _shared_account_expected_total_posts_from_config(
        config,
        platform=platform,
        account_handle=account_handle,
    )
    scheduler_lanes = _catalog_backfill_run_scheduler_lanes(runner_count)
    dispatched_partitions: dict[str, tuple[dict[str, Any], str]] = {}

    def _on_partition_discovered(
        partition: SharedAccountCursorPartition,
        expected_partition_count: int | None,
    ) -> None:
        """Eagerly dispatch a partition job as soon as its boundary is discovered."""
        shard_total_estimate = max(1, expected_partition_count or 1)
        p_key = _shared_account_partition_key(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            shard_index=partition.shard_index,
            cursor_start=partition.cursor_start,
            cursor_end=partition.cursor_end,
        )
        partition_row = _upsert_shared_account_run_partition(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
            partition_key=p_key,
            shard_index=partition.shard_index,
            shard_total=shard_total_estimate,
            cursor_start=partition.cursor_start,
            cursor_end=partition.cursor_end,
            boundary_start_at=partition.boundary_start_at,
            boundary_end_at=partition.boundary_end_at,
            status="discovered",
            metadata=partition.metadata,
        )
        partition_metadata = _metadata_dict(partition_row.get("metadata"))
        shard_job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            config={
                "stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "shared_account_source_id": config.get("shared_account_source_id"),
                "pipeline_ingest_mode": config.get("pipeline_ingest_mode"),
                "partition_strategy": CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                "partition_id": partition_row.get("id"),
                "partition_key": partition_row.get("partition_key"),
                "cursor_start": partition_row.get("cursor_start"),
                "cursor_end": partition_row.get("cursor_end"),
                "boundary_start_at": _iso(_coerce_dt(partition_row.get("boundary_start_at"))),
                "boundary_end_at": _iso(_coerce_dt(partition_row.get("boundary_end_at"))),
                "shard_index": partition_row.get("shard_index"),
                "shard_total": shard_total_estimate,
                "runner_lane": scheduler_lanes[int(partition_row.get("shard_index") or 0) % len(scheduler_lanes)],
                "runner_count": runner_count,
                "runner_strategy": "full_history_cursor_breakpoints",
                "max_posts_per_target": 0,
                "discovery_total_posts": None,
                "expected_total_posts": expected_total_posts,
                "sec_uid": partition_metadata.get("sec_uid"),
                "profile_snapshot": None,
                "selected_tasks": config.get("selected_tasks"),
                "effective_selected_tasks": config.get("effective_selected_tasks"),
                "details_refresh_skip_detail_fetch": config.get("details_refresh_skip_detail_fetch"),
                "details_refresh_force_detail_fetch": config.get("details_refresh_force_detail_fetch"),
                "details_refresh_skip_media_followups": config.get("details_refresh_skip_media_followups"),
                "tiktok_comments_in_posts_stage": bool(config.get("tiktok_comments_in_posts_stage")),
                "tiktok_direct_comment_api_override": bool(config.get("tiktok_direct_comment_api_override")),
                "twitter_comments_in_posts_stage": bool(config.get("twitter_comments_in_posts_stage")),
                "required_worker_lane": config.get("required_worker_lane"),
                "required_execution_backend": config.get("required_execution_backend"),
                "allow_local_dev_inline_bypass": bool(config.get("allow_local_dev_inline_bypass")),
                "frontier_auth_allowed": auth_allowed if platform == "instagram" else None,
                "frontier_auth_reason": auth_reason if platform == "instagram" else None,
            },
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=max(1, 100 + partition.shard_index),
            worker_id=followup_worker_id,
            preclaim=bool(followup_worker_id),
        )
        _upsert_shared_account_run_partition(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
            partition_key=str(partition_row.get("partition_key") or ""),
            shard_index=int(partition_row.get("shard_index") or 0),
            shard_total=shard_total_estimate,
            cursor_start=partition_row.get("cursor_start"),
            cursor_end=partition_row.get("cursor_end"),
            boundary_start_at=_coerce_dt(partition_row.get("boundary_start_at")),
            boundary_end_at=_coerce_dt(partition_row.get("boundary_end_at")),
            status="queued",
            job_id=shard_job_id,
            metadata=partition_metadata,
        )
        dispatched_partitions[p_key] = (partition_row, shard_job_id)

    partitions, discovery_meta = _discover_shared_account_cursor_partitions(
        platform=platform,
        account_handle=account_handle,
        runner_count=runner_count,
        auth_allowed=auth_allowed,
        progress_cb=_on_discovery_progress,
        partition_callback=_on_partition_discovered,
    )
    activity["phase"] = "discovery_enqueue_shards"
    activity["pages_scanned"] = _normalize_non_negative_int(discovery_meta.get("pages_scanned"))
    activity["posts_checked"] = _normalize_non_negative_int(discovery_meta.get("posts_checked"))
    activity["matched_posts"] = len(partitions)
    if discovery_meta.get("total_posts") is not None:
        activity["total_posts"] = _normalize_non_negative_int(discovery_meta.get("total_posts"))
    elif expected_total_posts > 0:
        activity["total_posts"] = expected_total_posts
    profile_snapshot = _metadata_dict(discovery_meta.get("profile_snapshot"))
    if profile_snapshot:
        _touch_shared_account_source(
            source_scope=source_scope,
            platform=platform,
            account_handle=account_handle,
            run_id=run_id or None,
            job_id=job_id,
            metadata_updates={"profile_snapshot": profile_snapshot},
        )
    if not partitions:
        # Only attempt recovery if discovery actually scanned some posts.
        # If we got 0 posts on the first page, Instagram is blocking us —
        # retrying with a new discovery job won't help, just fail cleanly.
        discovery_checked = _normalize_non_negative_int(discovery_meta.get("posts_checked"))
        recovery_depth = _normalize_non_negative_int(config.get("recovery_depth"))
        if (
            discovery_checked > 0
            and recovery_depth <= 0
            and _shared_account_prefers_partitioned_backfill_recovery(config, platform=platform)
        ):
            recovery_job_id = _enqueue_shared_discovery_job(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                shared_account_source_id=config.get("shared_account_source_id"),
                pipeline_ingest_mode=str(
                    config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                ),
                runner_count=max(1, runner_count),
                expected_total_posts=expected_total_posts,
                runner_strategy="full_history_cursor_breakpoints",
                partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                required_worker_lane=str(config.get("required_worker_lane") or "").strip().lower() or None,
                required_execution_backend=str(config.get("required_execution_backend") or "").strip().lower() or None,
                allow_local_dev_inline_bypass=bool(config.get("allow_local_dev_inline_bypass")),
                frontier_auth_allowed=auth_allowed if platform == "instagram" else None,
                frontier_auth_reason=auth_reason if platform == "instagram" else None,
                transport_preference="authenticated" if platform == "instagram" and auth_allowed else None,
                allow_public_transport_fallback=False if platform == "instagram" and auth_allowed else None,
                date_start=_coerce_dt(config.get("date_start")),
                date_end=_coerce_dt(config.get("date_end")),
                catalog_action=str(config.get("catalog_action") or "").strip().lower() or None,
                catalog_action_scope=str(config.get("catalog_action_scope") or "").strip().lower() or None,
                selected_tasks=config.get("selected_tasks"),
                effective_selected_tasks=config.get("effective_selected_tasks"),
                details_refresh_skip_detail_fetch=config.get("details_refresh_skip_detail_fetch"),
                details_refresh_force_detail_fetch=config.get("details_refresh_force_detail_fetch"),
                details_refresh_skip_media_followups=config.get("details_refresh_skip_media_followups"),
                tiktok_comments_in_posts_stage=bool(config.get("tiktok_comments_in_posts_stage")),
                tiktok_direct_comment_api_override=bool(config.get("tiktok_direct_comment_api_override")),
                twitter_comments_in_posts_stage=bool(config.get("twitter_comments_in_posts_stage")),
                initiated_by=None,
                worker_id=followup_worker_id,
                priority=100,
                recovery_depth=_normalize_non_negative_int(config.get("recovery_depth")) + 1,
            )
            activity["phase"] = "discovery_partition_recovery_enqueued"
            activity["queued_jobs"] = 1
            _flush_progress(force=True)
            return (
                0,
                0,
                {
                    "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                    "platform": platform,
                    "account": account_handle,
                    "partition_strategy": CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                    "discovered_partition_count": 0,
                    "recovery_job_enqueued": True,
                    "recovery_job_id": recovery_job_id,
                    "recovery_job_stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                    "recovery_reason": "no_partitions_discovered",
                    "retrieval_meta": discovery_meta,
                    "expected_total_posts": expected_total_posts,
                    "activity": dict(activity),
                    "pipeline_ingest_mode": str(
                        config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                    ),
                },
            )
        # Only create frontier fallback if discovery actually checked some posts.
        # If the first page returned nothing, Instagram is blocking — don't spin up
        # more jobs that will also fail.
        if discovery_checked == 0:
            if platform == "tiktok":
                if _tiktok_discovery_empty_body_transport_failure(discovery_meta) and recovery_depth <= 0:
                    recovery_expected_total_posts = max(
                        expected_total_posts,
                        _best_known_social_account_total_posts(
                            platform,
                            account_handle,
                            materialized_total_posts=expected_total_posts,
                            catalog_total_posts=_shared_catalog_total_posts(platform, account_handle),
                            allow_live_refresh=False,
                        ),
                    )
                    fallback_posts_stage = _shared_account_posts_stage_for_platform(platform)
                    fallback_job_id = _create_job(
                        None,
                        run_id=run_id,
                        platform=platform,
                        source_scope=source_scope,
                        job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
                        stage=fallback_posts_stage,
                        config={
                            "stage": fallback_posts_stage,
                            "platform": platform,
                            "source_scope": source_scope,
                            "account": account_handle,
                            "shared_account_source_id": config.get("shared_account_source_id"),
                            "pipeline_ingest_mode": config.get("pipeline_ingest_mode"),
                            "partition_strategy": None,
                            "runner_strategy": "single_runner_fallback",
                            "runner_count": 1,
                            "max_posts_per_target": 0,
                            "discovery_total_posts": discovery_meta.get("total_posts"),
                            "expected_total_posts": recovery_expected_total_posts,
                            "completion_target_posts": _normalize_non_negative_int(discovery_meta.get("total_posts"))
                            or expected_total_posts
                            or recovery_expected_total_posts,
                            "discovery_fallback_reason": "tiktok_empty_body_transport_failure",
                            "recovery_reason": "tiktok_empty_body_transport_failure",
                            "profile_snapshot": profile_snapshot,
                            "selected_tasks": config.get("selected_tasks"),
                            "effective_selected_tasks": config.get("effective_selected_tasks"),
                            "details_refresh_skip_detail_fetch": config.get("details_refresh_skip_detail_fetch"),
                            "details_refresh_force_detail_fetch": config.get("details_refresh_force_detail_fetch"),
                            "details_refresh_skip_media_followups": config.get("details_refresh_skip_media_followups"),
                            "tiktok_comments_in_posts_stage": bool(config.get("tiktok_comments_in_posts_stage")),
                            "tiktok_direct_comment_api_override": bool(
                                config.get("tiktok_direct_comment_api_override")
                            ),
                            "twitter_comments_in_posts_stage": bool(config.get("twitter_comments_in_posts_stage")),
                            "required_worker_lane": config.get("required_worker_lane"),
                            "required_execution_backend": config.get("required_execution_backend"),
                            "allow_local_dev_inline_bypass": bool(config.get("allow_local_dev_inline_bypass")),
                            "recovery_depth": recovery_depth + 1,
                        },
                        initiated_by=None,
                        status="queued" if is_queue_enabled() else "pending",
                        priority=100,
                        worker_id=followup_worker_id,
                        preclaim=bool(followup_worker_id),
                        max_attempts=3,
                    )
                    activity["phase"] = "discovery_transport_recovery_enqueued"
                    activity["queued_jobs"] = 1
                    _flush_progress(force=True)
                    return (
                        0,
                        0,
                        {
                            "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                            "platform": platform,
                            "account": account_handle,
                            "partition_strategy": None,
                            "discovered_partition_count": 0,
                            "fallback_direct_job_enqueued": True,
                            "fallback_job_id": fallback_job_id,
                            "fallback_job_stage": fallback_posts_stage,
                            "recovery_reason": "tiktok_empty_body_transport_failure",
                            "retrieval_meta": discovery_meta,
                            "expected_total_posts": recovery_expected_total_posts,
                            "activity": dict(activity),
                            "pipeline_ingest_mode": str(
                                config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                            ),
                        },
                    )
                activity["phase"] = "shared_account_discovery_failed"
                message = (
                    f"TikTok returned no posts for @{account_handle} on the first page. "
                    "The post-list response body was empty or unusable."
                )
                logger.error(
                    "TikTok discovery got 0 posts for @%s on the first page; failing discovery without fallback",
                    account_handle,
                )
                raise SharedStageRuntimeError(
                    message,
                    error_code="tiktok_discovery_empty_first_page",
                    retryable=False,
                    error_class="TikTokDiscoveryEmptyFirstPage",
                    runtime_metadata={
                        "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                        "platform": platform,
                        "account": account_handle,
                        "discovered_partition_count": 0,
                        "retrieval_meta": discovery_meta,
                        "expected_total_posts": expected_total_posts,
                        "activity": dict(activity),
                        "pipeline_ingest_mode": str(
                            config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                        ),
                    },
                )
            logger.warning(
                "Discovery got 0 posts for @%s — Instagram likely blocking. Skipping frontier fallback.",
                account_handle,
            )
            return (
                0,
                0,
                {
                    "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                    "platform": platform,
                    "account": account_handle,
                    "discovered_partition_count": 0,
                    "error": "discovery_empty_first_page",
                    "error_message": (
                        f"Instagram returned no posts for @{account_handle} on the first page. "
                        "The account may be blocked or rate-limited from this IP."
                    ),
                    "retrieval_meta": discovery_meta,
                },
            )
        fallback_posts_stage = _shared_account_posts_stage_for_platform(platform)
        fallback_job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=fallback_posts_stage,
            config={
                "stage": fallback_posts_stage,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "shared_account_source_id": config.get("shared_account_source_id"),
                "pipeline_ingest_mode": config.get("pipeline_ingest_mode"),
                "partition_strategy": CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                "runner_strategy": "single_runner_fallback",
                "runner_count": 1,
                "max_posts_per_target": 0,
                "discovery_total_posts": discovery_meta.get("total_posts"),
                "expected_total_posts": expected_total_posts,
                "discovery_fallback_reason": "no_partitions_discovered",
                "profile_snapshot": profile_snapshot,
                "selected_tasks": config.get("selected_tasks"),
                "effective_selected_tasks": config.get("effective_selected_tasks"),
                "details_refresh_skip_detail_fetch": config.get("details_refresh_skip_detail_fetch"),
                "details_refresh_force_detail_fetch": config.get("details_refresh_force_detail_fetch"),
                "details_refresh_skip_media_followups": config.get("details_refresh_skip_media_followups"),
                "tiktok_comments_in_posts_stage": bool(config.get("tiktok_comments_in_posts_stage")),
                "tiktok_direct_comment_api_override": bool(config.get("tiktok_direct_comment_api_override")),
                "twitter_comments_in_posts_stage": bool(config.get("twitter_comments_in_posts_stage")),
                "required_worker_lane": config.get("required_worker_lane"),
                "required_execution_backend": config.get("required_execution_backend"),
                "allow_local_dev_inline_bypass": bool(config.get("allow_local_dev_inline_bypass")),
                "frontier_auth_allowed": auth_allowed if platform == "instagram" else None,
                "frontier_auth_reason": auth_reason if platform == "instagram" else None,
                "transport_preference": "authenticated" if platform == "instagram" else None,
                "allow_public_transport_fallback": False if platform == "instagram" else None,
                "recovery_depth": _normalize_non_negative_int(config.get("recovery_depth")) + 1,
            },
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=100,
            worker_id=followup_worker_id,
            preclaim=bool(followup_worker_id),
        )
        activity["phase"] = "discovery_frontier_recovery_enqueued"
        activity["queued_jobs"] = 1
        _flush_progress(force=True)
        return (
            0,
            0,
            {
                "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                "platform": platform,
                "account": account_handle,
                "partition_strategy": CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                "discovered_partition_count": 0,
                "fallback_direct_job_enqueued": True,
                "fallback_job_id": fallback_job_id,
                "fallback_job_stage": fallback_posts_stage,
                "recovery_reason": "no_partitions_discovered",
                "retrieval_meta": discovery_meta,
                "expected_total_posts": expected_total_posts,
                "activity": dict(activity),
                "pipeline_ingest_mode": str(
                    config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                ),
            },
        )
    # Reconcile shard_total on early-dispatched partitions now that the final count
    # is known, and dispatch any partitions that the callback did not handle.
    final_shard_total = max(1, len(partitions))
    created_partition_count = len(dispatched_partitions)
    logger.info(
        "Discovery reconciliation for run %s account=%s platform=%s: "
        "partitions_from_discovery=%s eagerly_dispatched=%s "
        "remaining_to_dispatch=%s",
        run_id,
        account_handle,
        platform,
        len(partitions),
        len(dispatched_partitions),
        max(0, len(partitions) - len(dispatched_partitions)),
    )
    for partition in partitions:
        p_key = _shared_account_partition_key(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            shard_index=partition.shard_index,
            cursor_start=partition.cursor_start,
            cursor_end=partition.cursor_end,
        )
        if p_key in dispatched_partitions:
            # Already dispatched during discovery — reconcile shard_total if needed.
            partition_row, shard_job_id = dispatched_partitions[p_key]
            if int(partition_row.get("shard_total") or 0) != final_shard_total:
                _upsert_shared_account_run_partition(
                    run_id=run_id,
                    platform=platform,
                    account_handle=account_handle,
                    partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                    partition_key=str(partition_row.get("partition_key") or ""),
                    shard_index=int(partition_row.get("shard_index") or 0),
                    shard_total=final_shard_total,
                    cursor_start=partition_row.get("cursor_start"),
                    cursor_end=partition_row.get("cursor_end"),
                    boundary_start_at=_coerce_dt(partition_row.get("boundary_start_at")),
                    boundary_end_at=_coerce_dt(partition_row.get("boundary_end_at")),
                    status="queued",
                    job_id=shard_job_id,
                    metadata=_metadata_dict(partition_row.get("metadata")),
                )
            continue
        # Fallback: dispatch partitions not handled by the callback (e.g. TikTok).
        partition_row = _upsert_shared_account_run_partition(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
            partition_key=p_key,
            shard_index=partition.shard_index,
            shard_total=final_shard_total,
            cursor_start=partition.cursor_start,
            cursor_end=partition.cursor_end,
            boundary_start_at=partition.boundary_start_at,
            boundary_end_at=partition.boundary_end_at,
            status="discovered",
            metadata=partition.metadata,
        )
        partition_metadata = _metadata_dict(partition_row.get("metadata"))
        shard_job_id = _create_job(
            None,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            config={
                "stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "shared_account_source_id": config.get("shared_account_source_id"),
                "pipeline_ingest_mode": config.get("pipeline_ingest_mode"),
                "partition_strategy": CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                "partition_id": partition_row.get("id"),
                "partition_key": partition_row.get("partition_key"),
                "cursor_start": partition_row.get("cursor_start"),
                "cursor_end": partition_row.get("cursor_end"),
                "boundary_start_at": _iso(_coerce_dt(partition_row.get("boundary_start_at"))),
                "boundary_end_at": _iso(_coerce_dt(partition_row.get("boundary_end_at"))),
                "shard_index": partition_row.get("shard_index"),
                "shard_total": partition_row.get("shard_total"),
                "runner_lane": scheduler_lanes[int(partition_row.get("shard_index") or 0) % len(scheduler_lanes)],
                "runner_count": runner_count,
                "runner_strategy": "full_history_cursor_breakpoints",
                "max_posts_per_target": 0,
                "discovery_total_posts": discovery_meta.get("total_posts"),
                "expected_total_posts": expected_total_posts,
                "sec_uid": partition_metadata.get("sec_uid"),
                "profile_snapshot": profile_snapshot,
                "selected_tasks": config.get("selected_tasks"),
                "effective_selected_tasks": config.get("effective_selected_tasks"),
                "details_refresh_skip_detail_fetch": config.get("details_refresh_skip_detail_fetch"),
                "details_refresh_force_detail_fetch": config.get("details_refresh_force_detail_fetch"),
                "details_refresh_skip_media_followups": config.get("details_refresh_skip_media_followups"),
                "tiktok_comments_in_posts_stage": bool(config.get("tiktok_comments_in_posts_stage")),
                "tiktok_direct_comment_api_override": bool(config.get("tiktok_direct_comment_api_override")),
                "twitter_comments_in_posts_stage": bool(config.get("twitter_comments_in_posts_stage")),
                "required_worker_lane": config.get("required_worker_lane"),
                "required_execution_backend": config.get("required_execution_backend"),
                "allow_local_dev_inline_bypass": bool(config.get("allow_local_dev_inline_bypass")),
                "frontier_auth_allowed": auth_allowed if platform == "instagram" else None,
                "frontier_auth_reason": auth_reason if platform == "instagram" else None,
            },
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=max(1, 100 + int(partition_row.get("shard_index") or 0)),
            worker_id=followup_worker_id,
            preclaim=bool(followup_worker_id),
        )
        _upsert_shared_account_run_partition(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
            partition_key=str(partition_row.get("partition_key") or ""),
            shard_index=int(partition_row.get("shard_index") or 0),
            shard_total=max(1, int(partition_row.get("shard_total") or final_shard_total)),
            cursor_start=partition_row.get("cursor_start"),
            cursor_end=partition_row.get("cursor_end"),
            boundary_start_at=_coerce_dt(partition_row.get("boundary_start_at")),
            boundary_end_at=_coerce_dt(partition_row.get("boundary_end_at")),
            status="queued",
            job_id=shard_job_id,
            metadata=partition_metadata,
        )
        created_partition_count += 1
    activity["phase"] = "shared_account_discovery_end"
    activity["saved_posts"] = created_partition_count
    _flush_progress(force=True)
    return (
        0,
        0,
        {
            "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
            "platform": platform,
            "account": account_handle,
            "partition_strategy": CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
            "discovered_partition_count": created_partition_count,
            "retrieval_meta": discovery_meta,
            "expected_total_posts": expected_total_posts,
            "activity": dict(activity),
            "pipeline_ingest_mode": str(
                config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
            ),
        },
    )


def _run_shared_account_frontier_posts_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    job_id: str,
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    ingest_mode = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    frontier = _get_shared_account_run_frontier(run_id=run_id, platform=platform, account_handle=account_handle)
    lease_holder = str(worker_id or job_id or f"job:{job_id}").strip()
    claimed_frontier = _claim_shared_account_run_frontier(
        run_id=run_id,
        platform=platform,
        account_handle=account_handle,
        lease_owner=lease_holder,
    )
    if not claimed_frontier:
        raise SharedStageRuntimeError(
            f"Shared-account frontier for @{account_handle} is already leased.",
            error_code=SHARED_ACCOUNT_FRONTIER_LEASE_UNAVAILABLE_ERROR_CODE,
            retryable=True,
            runtime_metadata={"frontier": frontier},
        )

    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": "catalog_fetch_start",
        "pages_scanned": _normalize_non_negative_int(claimed_frontier.get("pages_scanned")),
        "posts_checked": _normalize_non_negative_int(claimed_frontier.get("posts_checked")),
        "matched_posts": _normalize_non_negative_int(claimed_frontier.get("posts_saved")),
        "saved_posts": _normalize_non_negative_int(claimed_frontier.get("posts_saved")),
    }
    total_pages_scanned = _normalize_non_negative_int(claimed_frontier.get("pages_scanned"))
    total_posts_checked = _normalize_non_negative_int(claimed_frontier.get("posts_checked"))
    total_posts_saved = _normalize_non_negative_int(claimed_frontier.get("posts_saved"))
    expected_total_posts = max(
        _normalize_non_negative_int(claimed_frontier.get("total_posts")),
        _shared_account_expected_total_posts_from_config(
            config,
            platform=platform,
            account_handle=account_handle,
        ),
    )
    if expected_total_posts > 0:
        activity["total_posts"] = expected_total_posts

    def _flush_progress(*, force: bool = False) -> None:
        _emit_job_progress(
            job_id=job_id,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            platform=platform,
            account=account_handle,
            scraped_posts=total_posts_checked,
            scraped_comments=0,
            posts_upserted=total_posts_saved,
            comments_upserted=0,
            activity=activity,
            progress_state=progress_state,
            force=force,
        )

    _flush_progress(force=True)
    next_cursor = str(claimed_frontier.get("next_cursor") or "").strip() or None
    frontier_metadata = _metadata_dict(claimed_frontier.get("metadata"))
    catalog_oldest_post_at = _coerce_dt(
        frontier_metadata.get("catalog_oldest_post_at")
    ) or _catalog_oldest_stored_post_at(
        platform,
        account_handle,
    )
    oldest_posted_at_seen = _coerce_dt(frontier_metadata.get("oldest_posted_at_seen"))
    newest_posted_at_seen = _coerce_dt(frontier_metadata.get("newest_posted_at_seen"))
    auth_allowed, auth_reason = (
        _shared_instagram_frontier_auth_state(config, frontier_metadata=frontier_metadata)
        if platform == "instagram"
        else (True, None)
    )
    selected_transport = (
        str(config.get("frontier_transport") or "").strip().lower()
        or str(claimed_frontier.get("last_transport") or "").strip().lower()
        or "public"
    )
    allow_public_fallback = True
    if platform == "instagram":
        preferred_transport, allow_public_fallback = _shared_instagram_frontier_transport_preferences(
            config,
            auth_allowed=auth_allowed,
        )
        if selected_transport not in {"authenticated", "public"}:
            selected_transport = preferred_transport
        configured_allow_public_fallback = _metadata_dict(config).get("allow_public_transport_fallback")
        if (
            selected_transport == "authenticated"
            and not auth_allowed
            and allow_public_fallback
            and auth_reason == "operator_public_transport_recovery"
        ):
            selected_transport = "public"
        if selected_transport == "public" and not isinstance(configured_allow_public_fallback, bool):
            allow_public_fallback = True
    bounded_start = _coerce_dt(config.get("date_start"))
    bounded_end = _coerce_dt(config.get("date_end"))
    bounded_window = _catalog_backfill_has_bounded_window(date_start=bounded_start, date_end=bounded_end)
    last_retrieval_meta: dict[str, Any] = {}
    seen_cursors: set[str] = set()
    frontier_release_status: str | None = None

    try:
        if platform == "instagram" and next_cursor and not auth_allowed and selected_transport == "authenticated":
            error_code = _shared_instagram_frontier_auth_error_code(auth_reason)
            error_message = (
                f"Shared-account frontier auth blocked for @{account_handle}: {auth_reason or 'auth_blocked'}"
            )
            claimed_frontier = _update_shared_account_run_frontier(
                run_id=run_id,
                platform=platform,
                account_handle=account_handle,
                status="failed",
                exhausted=False,
                retry_count=_normalize_non_negative_int(claimed_frontier.get("retry_count")),
                last_transport=selected_transport,
                lease_owner=lease_holder,
                lease_expires_at=_shared_account_frontier_lease_deadline(platform),
                expected_lease_owner=lease_holder,
                metadata_updates={
                    "auth_allowed": False,
                    "auth_reason": auth_reason,
                    "last_error_code": error_code,
                    "last_error_class": SharedStageRuntimeError.__name__,
                    "last_error_message": error_message,
                    "frontier_stop_reason": auth_reason or "auth_blocked",
                    "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                    "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                    "newest_posted_at_seen": _iso(newest_posted_at_seen),
                    "cooldown_until": None,
                    "graphql_cursor": next_cursor,
                },
            )
            frontier_release_status = "failed"
            raise SharedStageRuntimeError(
                error_message,
                error_code=error_code,
                retryable=False,
                runtime_metadata={
                    "retrieval_meta": {
                        "error_code": error_code,
                        "error_class": SharedStageRuntimeError.__name__,
                        "error_message": auth_reason or "auth_blocked",
                        "retryable": False,
                        "graphql_cursor": next_cursor,
                        "auth_allowed": False,
                        "auth_reason": auth_reason,
                        "transport": selected_transport,
                    },
                    "frontier": claimed_frontier,
                },
            )
        while next_cursor:
            if next_cursor in seen_cursors:
                _update_shared_account_run_frontier(
                    run_id=run_id,
                    platform=platform,
                    account_handle=account_handle,
                    status="failed",
                    exhausted=False,
                    retry_count=_normalize_non_negative_int(claimed_frontier.get("retry_count")) + 1,
                    expected_lease_owner=lease_holder,
                    metadata_updates={
                        "last_error_code": "instagram_graphql_cursor_loop",
                        "frontier_stop_reason": "repeating_cursor",
                        "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                        "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                        "newest_posted_at_seen": _iso(newest_posted_at_seen),
                        "graphql_cursor": next_cursor,
                    },
                )
                raise SharedStageRuntimeError(
                    f"Instagram @{account_handle} frontier loop detected at cursor {next_cursor}",
                    error_code="instagram_graphql_cursor_loop",
                    retryable=True,
                    runtime_metadata={"frontier": claimed_frontier},
                )
            seen_cursors.add(next_cursor)
            # tp-1/tp-2: remember the cursor that FETCHES this page. If this page
            # crosses the bounded-window start, this (not the page's end_cursor) is
            # the lossless skip-ahead resume point — a future older-year run that
            # seeds it re-fetches this straddling page and re-filters, so the worst
            # case is harmless overlap, never dropped boundary posts.
            page_fetch_cursor = next_cursor

            _raise_if_shared_account_stage_cancelled(
                run_id=run_id,
                job_id=job_id,
                stage=SHARED_ACCOUNT_POSTS_STAGE,
                platform=platform,
                account_handle=account_handle,
                phase="before_frontier_page_fetch",
            )
            activity.update(
                {
                    "phase": "catalog_fetch_page_request",
                    "pages_scanned": total_pages_scanned,
                    "posts_checked": total_posts_checked,
                    "matched_posts": total_posts_saved,
                    "saved_posts": total_posts_saved,
                    "total_posts": expected_total_posts or None,
                }
            )
            _flush_progress(force=True)
            page_posts, page_info, retrieval_meta, selected_transport = _fetch_shared_instagram_graphql_posts_page(
                account_handle=account_handle,
                cursor=next_cursor,
                delay_seconds=_shared_instagram_graphql_delay_seconds(jitter=True),
                preferred_transport=selected_transport,
                allow_public_fallback=allow_public_fallback,
                auth_allowed=auth_allowed,
            )
            _raise_if_shared_account_stage_cancelled(
                run_id=run_id,
                job_id=job_id,
                stage=SHARED_ACCOUNT_POSTS_STAGE,
                platform=platform,
                account_handle=account_handle,
                phase="after_frontier_page_fetch",
            )
            last_retrieval_meta = dict(retrieval_meta or {})
            if not page_posts:
                retrieval_error_code = str(
                    retrieval_meta.get("error_code") or "instagram_graphql_cursor_request_failed"
                ).strip()
                retrieval_retryable = bool(retrieval_meta.get("retryable", True))
                if _shared_account_retry_uses_frontier_recovery(
                    config,
                    platform=platform,
                    error_code=retrieval_error_code,
                ):
                    retrieval_retryable = True
                    retrieval_meta = {
                        **dict(retrieval_meta or {}),
                        "retryable": True,
                        "retryable_source": "shared_account_frontier_recovery",
                    }
                frontier_release_status = "retrying" if retrieval_retryable else "failed"
                retry_count = _normalize_non_negative_int(claimed_frontier.get("retry_count")) + 1
                cooldown_until = _iso(_now_utc() + timedelta(seconds=_retry_backoff_seconds(retry_count)))
                _update_shared_account_run_frontier(
                    run_id=run_id,
                    platform=platform,
                    account_handle=account_handle,
                    status="retrying" if retrieval_retryable else "failed",
                    retry_count=retry_count,
                    last_transport=selected_transport,
                    lease_owner=lease_holder,
                    lease_expires_at=_shared_account_frontier_lease_deadline(platform),
                    expected_lease_owner=lease_holder,
                    metadata_updates={
                        "last_error_code": retrieval_meta.get("error_code"),
                        "last_error_class": retrieval_meta.get("error_class"),
                        "last_error_message": retrieval_meta.get("error_message"),
                        "frontier_stop_reason": str(retrieval_meta.get("error_code") or "request_failed")
                        .strip()
                        .lower()
                        or "request_failed",
                        "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                        "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                        "newest_posted_at_seen": _iso(newest_posted_at_seen),
                        "cooldown_until": cooldown_until,
                        "graphql_cursor": retrieval_meta.get("graphql_cursor") or next_cursor,
                    },
                )
                raise SharedStageRuntimeError(
                    (f"Shared-account frontier fetch failed for @{account_handle}: {retrieval_error_code}"),
                    error_code=retrieval_error_code,
                    retryable=retrieval_retryable,
                    error_class=str(retrieval_meta.get("error_class") or "SharedStageRuntimeError"),
                    runtime_metadata={"retrieval_meta": retrieval_meta, "frontier": claimed_frontier},
                )

            _clear_posts_auth_cooldown_after_success(
                platform=platform,
                stage=SHARED_ACCOUNT_POSTS_STAGE,
                job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
                account_handle=account_handle,
                metadata=last_retrieval_meta,
            )
            _raise_if_shared_account_stage_cancelled(
                run_id=run_id,
                job_id=job_id,
                stage=SHARED_ACCOUNT_POSTS_STAGE,
                platform=platform,
                account_handle=account_handle,
                phase="before_frontier_page_persist",
            )
            page_posts_to_persist, crossed_bounded_start = _filter_shared_instagram_posts_for_window(
                page_posts,
                date_start=bounded_start,
                date_end=bounded_end,
            )

            def _on_frontier_persist_progress(payload: dict[str, Any]) -> None:
                activity["phase"] = str(payload.get("phase") or "catalog_page_persisting")
                activity["persist_progress"] = payload
                _flush_progress(force=True)

            page_rows, _source_ids, persist_meta = _normalize_shared_catalog_posts_batch_result(
                _persist_shared_catalog_posts_batch(
                    platform=platform,
                    run_id=run_id,
                    account_handle=account_handle,
                    posts=page_posts_to_persist,
                    job_id=job_id,
                    source_scope=source_scope,
                    enable_media_followups=not bool(config.get("details_refresh_skip_media_followups")),
                    progress_callback=_on_frontier_persist_progress,
                )
            )
            _raise_if_shared_account_stage_cancelled(
                run_id=run_id,
                job_id=job_id,
                stage=SHARED_ACCOUNT_POSTS_STAGE,
                platform=platform,
                account_handle=account_handle,
                phase="after_frontier_page_persist",
            )
            total_pages_scanned += 1
            total_posts_checked += len(page_posts)
            total_posts_saved += len(page_rows)
            if persist_meta.get("media_mirror_jobs_enqueued"):
                last_retrieval_meta["media_mirror_jobs_enqueued"] = _normalize_non_negative_int(
                    last_retrieval_meta.get("media_mirror_jobs_enqueued")
                ) + _normalize_non_negative_int(persist_meta.get("media_mirror_jobs_enqueued"))
            page_oldest_posted_at, page_newest_posted_at = _shared_instagram_posted_at_bounds(page_posts)
            if page_oldest_posted_at is not None and (
                oldest_posted_at_seen is None or page_oldest_posted_at < oldest_posted_at_seen
            ):
                oldest_posted_at_seen = page_oldest_posted_at
            if page_newest_posted_at is not None and (
                newest_posted_at_seen is None or page_newest_posted_at > newest_posted_at_seen
            ):
                newest_posted_at_seen = page_newest_posted_at
            discovered_total_posts = _normalize_non_negative_int(retrieval_meta.get("total_posts"))
            if discovered_total_posts > expected_total_posts:
                expected_total_posts = discovered_total_posts
            next_cursor = str(page_info.get("end_cursor") or "").strip() or None
            has_more_source_pages = bool(page_info.get("has_next_page")) and bool(next_cursor)
            bounded_window_completed = bool(bounded_window and crossed_bounded_start)
            exhausted = bounded_window_completed or not has_more_source_pages
            frontier_stop_reason = (
                "bounded_window_start_reached"
                if bounded_window_completed
                else "source_exhausted"
                if exhausted
                else None
            )
            claimed_frontier = _update_shared_account_run_frontier(
                run_id=run_id,
                platform=platform,
                account_handle=account_handle,
                status="completed" if exhausted else "running",
                next_cursor=None if exhausted else next_cursor,
                total_posts=expected_total_posts,
                posts_checked=total_posts_checked,
                posts_saved=total_posts_saved,
                pages_scanned=total_pages_scanned,
                last_transport=selected_transport,
                lease_owner=lease_holder,
                lease_expires_at=_shared_account_frontier_lease_deadline(platform),
                exhausted=exhausted,
                expected_lease_owner=lease_holder,
                metadata_updates={
                    "date_start": _iso(bounded_start),
                    "date_end": _iso(bounded_end),
                    "bounded_window": bounded_window,
                    "bounded_window_start_reached": bounded_window_completed,
                    "bounded_window_next_cursor": next_cursor
                    if bounded_window_completed and has_more_source_pages
                    else None,
                    # Lossless skip-ahead resume point (re-fetches the straddling page).
                    "bounded_window_resume_cursor": page_fetch_cursor if bounded_window_completed else None,
                    "last_error_code": None,
                    "last_error_class": None,
                    "last_error_message": None,
                    "frontier_stop_reason": frontier_stop_reason,
                    "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                    "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                    "newest_posted_at_seen": _iso(newest_posted_at_seen),
                    "cooldown_until": None,
                },
            )
            if not claimed_frontier:
                frontier_release_status = None
                raise SharedStageRuntimeError(
                    f"Shared-account frontier lease lost for @{account_handle}.",
                    error_code="shared_account_frontier_lease_lost",
                    retryable=True,
                    runtime_metadata={
                        "frontier": {
                            "run_id": run_id,
                            "platform": platform,
                            "account_handle": account_handle,
                            "expected_lease_owner": lease_holder,
                        }
                    },
                )
            frontier_release_status = "completed" if bool(claimed_frontier.get("exhausted")) else None
            activity.update(
                {
                    "phase": "catalog_fetch_page",
                    "pages_scanned": total_pages_scanned,
                    "posts_checked": total_posts_checked,
                    "matched_posts": total_posts_saved,
                    "saved_posts": total_posts_saved,
                    "total_posts": expected_total_posts or None,
                }
            )
            _flush_progress(force=True)
            completion_gap_reason = (
                _shared_account_frontier_completion_gap_reason(
                    expected_total_posts=expected_total_posts,
                    posts_checked=total_posts_checked,
                    catalog_oldest_post_at=catalog_oldest_post_at,
                    oldest_posted_at_seen=oldest_posted_at_seen,
                )
                if exhausted and not bounded_window
                else None
            )
            if completion_gap_reason and not exhausted:
                # Real early termination: hand the cursor back so the retried
                # attempt resumes the walk where it stopped.
                _update_shared_account_run_frontier(
                    run_id=run_id,
                    platform=platform,
                    account_handle=account_handle,
                    status="retrying",
                    next_cursor=next_cursor,
                    exhausted=False,
                    retry_count=_normalize_non_negative_int(claimed_frontier.get("retry_count")) + 1,
                    lease_owner=lease_holder,
                    lease_expires_at=_shared_account_frontier_lease_deadline(platform),
                    expected_lease_owner=lease_holder,
                    metadata_updates={
                        "last_error_code": "catalog_incomplete",
                        "expected_total_posts": expected_total_posts,
                        "observed_posts_checked": total_posts_checked,
                        "observed_posts_saved": total_posts_saved,
                        "frontier_stop_reason": completion_gap_reason,
                        "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                        "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                        "newest_posted_at_seen": _iso(newest_posted_at_seen),
                    },
                )
                frontier_release_status = None
                raise SharedStageRuntimeError(
                    (
                        f"Shared-account frontier ended before full-history coverage was proven for @{account_handle}: "
                        f"{completion_gap_reason}"
                    ),
                    error_code="catalog_incomplete",
                    retryable=True,
                    runtime_metadata={
                        "retrieval_meta": {
                            **dict(last_retrieval_meta or {}),
                            "expected_total_posts": expected_total_posts,
                            "observed_posts_checked": total_posts_checked,
                            "observed_posts_saved": total_posts_saved,
                            "catalog_oldest_post_at": _iso(catalog_oldest_post_at),
                            "oldest_posted_at_seen": _iso(oldest_posted_at_seen),
                            "newest_posted_at_seen": _iso(newest_posted_at_seen),
                            "frontier_stop_reason": completion_gap_reason,
                        }
                    },
                )
            if completion_gap_reason:
                # The cursor walk exhausted naturally, so a status=retrying hand-off
                # would re-enter with no cursor and silently no-op (the profile total
                # can exceed reachable posts, e.g. deleted posts). Complete instead
                # and keep the gap visible to operators on the frontier row.
                claimed_frontier = _update_shared_account_run_frontier(
                    run_id=run_id,
                    platform=platform,
                    account_handle=account_handle,
                    lease_owner=lease_holder,
                    lease_expires_at=_shared_account_frontier_lease_deadline(platform),
                    expected_lease_owner=lease_holder,
                    metadata_updates={
                        "completion_gap_reason": completion_gap_reason,
                        "expected_total_posts": expected_total_posts,
                        "observed_posts_checked": total_posts_checked,
                        "observed_posts_saved": total_posts_saved,
                    },
                )
                last_retrieval_meta.update(
                    {
                        "completion_gap_reason": completion_gap_reason,
                        "expected_total_posts": expected_total_posts,
                        "observed_posts_checked": total_posts_checked,
                        "observed_posts_saved": total_posts_saved,
                    }
                )
                activity["completion_gap_reason"] = completion_gap_reason
                logger.warning(
                    (
                        "[shared-account] frontier exhausted with completion gap for @%s: "
                        "reason=%s expected_total=%s posts_checked=%s posts_saved=%s run_id=%s"
                    ),
                    account_handle,
                    completion_gap_reason,
                    expected_total_posts,
                    total_posts_checked,
                    total_posts_saved,
                    run_id,
                )
                frontier_release_status = "completed"
                _flush_progress(force=True)
                break
            if exhausted:
                break
    finally:
        _release_shared_account_run_frontier(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            lease_owner=lease_holder,
            status=frontier_release_status,
        )

    activity["phase"] = "catalog_fetch_end"
    activity["pages_scanned"] = total_pages_scanned
    activity["posts_checked"] = total_posts_checked
    activity["matched_posts"] = total_posts_saved
    activity["saved_posts"] = total_posts_saved
    if expected_total_posts > 0:
        activity["total_posts"] = expected_total_posts
    _flush_progress(force=True)
    _touch_shared_account_source(
        source_scope=source_scope,
        platform=platform,
        account_handle=account_handle,
        run_id=run_id or None,
        job_id=job_id,
        last_scrape_status="completed",
        metadata_updates={"profile_snapshot": _metadata_dict(last_retrieval_meta.get("profile_snapshot"))},
    )
    return (
        total_posts_saved,
        0,
        {
            "stage": SHARED_ACCOUNT_POSTS_STAGE,
            "platform": platform,
            "account": account_handle,
            "persist_counters": {"posts_upserted": total_posts_saved, "comments_upserted": 0},
            "activity": dict(activity),
            "retrieval_meta": {
                **dict(last_retrieval_meta or {}),
                "pages_scanned": total_pages_scanned,
                "posts_checked": total_posts_checked,
                "total_posts": expected_total_posts or None,
                "persist_counters": {"posts_upserted": total_posts_saved, "comments_upserted": 0},
            },
            "frontier": _shared_account_frontier_progress(
                run_id=run_id,
                platform=platform,
                account_handle=account_handle,
            ),
            "frontier_classify_jobs_enqueued": 0,
            "expected_total_posts": expected_total_posts or None,
            "pipeline_ingest_mode": ingest_mode,
        },
    )


def _run_shared_account_posts_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    job_id: str,
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    if _shared_account_uses_frontier_strategy(config, platform=platform):
        return _run_shared_account_frontier_posts_stage(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            account_handle=account_handle,
            config=config,
            job_id=job_id,
            worker_id=worker_id,
        )
    ingest_mode = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    if str(config.get("partition_id") or "").strip():
        _update_shared_account_partition_status_for_job(
            job_id=job_id,
            status="running",
            metadata_updates={"source": "shared_account_posts_stage_start"},
        )
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": f"{SHARED_ACCOUNT_POSTS_STAGE}_start",
        "pages_scanned": 0,
        "posts_checked": 0,
        "matched_posts": 0,
        "saved_posts": 0,
    }
    scraped_posts = 0
    scraped_comments = 0
    matched_posts = 0
    saved_posts = 0
    saved_comments = 0

    def _flush_progress(*, force: bool = False) -> bool:
        return _emit_job_progress(
            job_id=job_id,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            platform=platform,
            account=account_handle,
            scraped_posts=scraped_posts,
            scraped_comments=scraped_comments,
            posts_upserted=saved_posts,
            comments_upserted=saved_comments,
            activity=activity,
            progress_state=progress_state,
            worker_id=worker_id,
            force=force,
        )

    def _on_scrape_progress(payload: dict[str, Any]) -> None:
        nonlocal scraped_posts, scraped_comments, matched_posts, saved_posts, saved_comments
        prior_saved_posts = saved_posts
        prior_saved_comments = saved_comments
        activity["phase"] = str(payload.get("phase") or SHARED_ACCOUNT_POSTS_STAGE)
        if payload.get("pages_scanned") is not None:
            activity["pages_scanned"] = _normalize_non_negative_int(payload.get("pages_scanned"))
        if payload.get("posts_checked") is not None:
            activity["posts_checked"] = _normalize_non_negative_int(payload.get("posts_checked"))
        if payload.get("matched_posts") is not None:
            activity["matched_posts"] = _normalize_non_negative_int(payload.get("matched_posts"))
        if payload.get("saved_posts") is not None:
            activity["saved_posts"] = _normalize_non_negative_int(payload.get("saved_posts"))
        if payload.get("scraped_comments") is not None:
            activity["scraped_comments"] = _normalize_non_negative_int(payload.get("scraped_comments"))
        if payload.get("comments_upserted") is not None:
            activity["comments_upserted"] = _normalize_non_negative_int(payload.get("comments_upserted"))
        if payload.get("total_posts") is not None:
            activity["total_posts"] = _normalize_non_negative_int(payload.get("total_posts"))
        if payload.get("current_source_id") is not None:
            current_source_id = str(payload.get("current_source_id") or "").strip()
            if current_source_id:
                activity["current_source_id"] = current_source_id
        scraped_posts = max(scraped_posts, _normalize_non_negative_int(payload.get("posts_checked")))
        scraped_comments = max(scraped_comments, _normalize_non_negative_int(payload.get("scraped_comments")))
        matched_posts = max(matched_posts, _normalize_non_negative_int(payload.get("matched_posts")))
        saved_posts = max(saved_posts, _normalize_non_negative_int(payload.get("saved_posts")))
        saved_comments = max(saved_comments, _normalize_non_negative_int(payload.get("comments_upserted")))
        force = (
            payload.get("saved_posts") is not None
            and _normalize_non_negative_int(payload.get("saved_posts")) > prior_saved_posts
        ) or (
            payload.get("comments_upserted") is not None
            and _normalize_non_negative_int(payload.get("comments_upserted")) > prior_saved_comments
        )
        if not _flush_progress(force=force):
            _touch_job_heartbeat(job_id, worker_id=worker_id)
        _raise_if_shared_account_stage_cancelled(
            run_id=run_id,
            job_id=job_id,
            stage=SHARED_ACCOUNT_POSTS_STAGE,
            platform=platform,
            account_handle=account_handle,
            phase=str(activity.get("phase") or "scrape_progress"),
        )

    _flush_progress(force=True)
    _raise_if_shared_account_stage_cancelled(
        run_id=run_id,
        job_id=job_id,
        stage=SHARED_ACCOUNT_POSTS_STAGE,
        platform=platform,
        account_handle=account_handle,
        phase="before_scrape",
    )
    rows, retrieval_meta = _scrape_shared_posts_for_account(
        run_id=run_id,
        platform=platform,
        account_handle=account_handle,
        config=config,
        job_id=job_id,
        progress_cb=_on_scrape_progress,
    )
    _raise_if_shared_account_stage_cancelled(
        run_id=run_id,
        job_id=job_id,
        stage=SHARED_ACCOUNT_POSTS_STAGE,
        platform=platform,
        account_handle=account_handle,
        phase="after_scrape",
    )
    scraped_posts = max(scraped_posts, _normalize_non_negative_int(retrieval_meta.get("posts_checked")), len(rows))
    matched_posts = max(
        matched_posts,
        _normalize_non_negative_int((retrieval_meta.get("persist_counters") or {}).get("posts_upserted")),
        len(rows),
    )
    saved_posts = max(
        saved_posts,
        _normalize_non_negative_int((retrieval_meta.get("persist_counters") or {}).get("posts_upserted")),
        len(rows),
    )
    persist_counters = _metadata_dict(retrieval_meta.get("persist_counters"))
    scraped_comments = max(
        scraped_comments,
        _normalize_non_negative_int(retrieval_meta.get("comments_fetched")),
        _normalize_non_negative_int(persist_counters.get("comments_fetched")),
    )
    saved_comments = max(saved_comments, _normalize_non_negative_int(persist_counters.get("comments_upserted")))
    retrieval_error_code = (
        str(retrieval_meta.get("error_code") or retrieval_meta.get("last_error_code") or "").strip().lower()
    )
    retrieval_error_class = str(
        retrieval_meta.get("error_class") or retrieval_meta.get("last_error_class") or SharedStageRuntimeError.__name__
    ).strip()
    retrieval_retryable = bool(retrieval_meta.get("retryable"))
    if retrieval_error_code and _shared_account_retry_uses_frontier_recovery(
        config,
        platform=platform,
        error_code=retrieval_error_code,
    ):
        retrieval_retryable = True
    if retrieval_error_code:
        raise SharedStageRuntimeError(
            (
                f"Shared-account posts stage failed for @{account_handle}: "
                f"{retrieval_error_code} after checking {scraped_posts} posts"
            ),
            error_code=retrieval_error_code,
            retryable=retrieval_retryable,
            error_class=retrieval_error_class,
            runtime_metadata={"retrieval_meta": dict(retrieval_meta or {})},
        )
    expected_total_posts = max(
        _normalize_non_negative_int(config.get("discovery_total_posts")),
        _shared_account_expected_total_posts_from_config(
            config,
            platform=platform,
            account_handle=account_handle,
        ),
    )
    completion_target_posts = expected_total_posts
    configured_completion_target_posts = _normalize_non_negative_int(config.get("completion_target_posts"))
    if configured_completion_target_posts > 0:
        completion_target_posts = configured_completion_target_posts
    normalized_platform = _normalize_platform_name(platform)
    catalog_action_scope = str(config.get("catalog_action_scope") or "").strip().lower()
    is_catalog_details_refresh = (
        normalized_platform == "instagram"
        and _shared_catalog_mode(config)
        and str(config.get("ingest_mode") or "").strip().lower() == "details_refresh"
        and catalog_action_scope in {"", "full_history"}
    )
    runner_strategy = str(config.get("runner_strategy") or "").strip().lower()
    bounded_start = _coerce_dt(config.get("date_start"))
    bounded_end = _coerce_dt(config.get("date_end"))
    is_bounded_instagram_direct_scan = (
        normalized_platform == "instagram"
        and _shared_catalog_mode(config)
        and runner_strategy in {"", "single_runner"}
        and bounded_start is not None
        and _catalog_backfill_has_bounded_window(date_start=bounded_start, date_end=bounded_end)
    )
    if is_bounded_instagram_direct_scan:
        oldest_seen = _coerce_dt(retrieval_meta.get("oldest_posted_at_seen"))
        stop_reason = str(retrieval_meta.get("stop_reason") or retrieval_meta.get("last_stop_reason") or "").strip()
        stop_reason = stop_reason.lower()
        direct_total_posts = _normalize_non_negative_int(retrieval_meta.get("total_posts"))
        reached_requested_start = bool(oldest_seen is not None and oldest_seen <= cast(datetime, bounded_start))
        source_exhausted = bool(direct_total_posts > 0 and scraped_posts >= direct_total_posts)
        explicit_start_stop = stop_reason in {
            "date_start_reached",
            "before_date_start",
            "bounded_window_start_reached",
        }
        if not (reached_requested_start or source_exhausted or explicit_start_stop):
            raise SharedStageRuntimeError(
                (
                    f"Instagram bounded direct scan ended before @{account_handle} reached the requested start date: "
                    f"oldest_seen={_iso(oldest_seen)} requested_start={_iso(bounded_start)} "
                    f"stop_reason={stop_reason or 'unknown'} checked={scraped_posts}"
                ),
                error_code="catalog_incomplete",
                retryable=True,
                runtime_metadata={
                    "retrieval_meta": {
                        **dict(retrieval_meta or {}),
                        "completion_failure_reason": "bounded_direct_scan_start_not_reached",
                        "requested_date_start": _iso(bounded_start),
                        "requested_date_end": _iso(bounded_end),
                        "oldest_posted_at_seen": _iso(oldest_seen),
                        "observed_posts_checked": scraped_posts,
                        "observed_posts_saved": saved_posts,
                        "stop_reason": stop_reason or None,
                    }
                },
            )
    if is_catalog_details_refresh:
        details_refresh_rows_seen = _normalize_non_negative_int(retrieval_meta.get("details_refresh_rows_seen"))
        details_refresh_shard_count = max(
            _normalize_non_negative_int(config.get("details_refresh_shard_count")),
            _normalize_non_negative_int(retrieval_meta.get("details_refresh_shard_count")),
        )
        if runner_strategy == "parallel_detail_refresh" and details_refresh_shard_count > 1:
            details_refresh_completion_target = max(
                details_refresh_rows_seen,
                _normalize_non_negative_int((retrieval_meta.get("persist_counters") or {}).get("posts_upserted")),
                len(rows),
            )
        else:
            details_refresh_completion_target = max(
                details_refresh_rows_seen,
                _normalize_non_negative_int(retrieval_meta.get("completion_target_posts")),
                _normalize_non_negative_int((retrieval_meta.get("persist_counters") or {}).get("posts_upserted")),
                len(rows),
            )
        if details_refresh_completion_target > 0:
            completion_target_posts = details_refresh_completion_target
    is_single_runner_fallback = runner_strategy == "single_runner_fallback"
    is_tiktok_empty_body_fallback = (
        platform == "tiktok"
        and is_single_runner_fallback
        and str(config.get("recovery_reason") or "").strip().lower() == "tiktok_empty_body_transport_failure"
    )
    if is_tiktok_empty_body_fallback:
        observed_current_total_posts = _normalize_non_negative_int(retrieval_meta.get("total_posts"))
        if observed_current_total_posts > 0:
            completion_target_posts = (
                min(completion_target_posts, observed_current_total_posts)
                if completion_target_posts > 0
                else observed_current_total_posts
            )
    observed_completion_posts = max(scraped_posts, saved_posts)
    missing_posts = max(completion_target_posts - observed_completion_posts, 0) if completion_target_posts > 0 else 0
    completion_tolerance_posts = 3 if is_tiktok_empty_body_fallback and completion_target_posts > 0 else 0
    completion_tolerance_applied = (
        is_tiktok_empty_body_fallback and missing_posts > 0 and missing_posts <= completion_tolerance_posts
    )
    retrieval_source = str(retrieval_meta.get("source") or "").strip().lower()
    is_incomplete_threads_profile_fallback = (
        normalized_platform == "threads"
        and _shared_catalog_mode(config)
        and retrieval_source in {"public_meta_fallback", "playwright_profile_discovery"}
        and completion_target_posts > 0
        and missing_posts > 0
        and not (
            retrieval_source == "playwright_profile_discovery"
            and bool(retrieval_meta.get("profile_discovery_complete"))
        )
    )
    retrieval_mode = str(retrieval_meta.get("retrieval_mode") or retrieval_source).strip().lower()
    is_incomplete_twitter_fallback = (
        normalized_platform == "twitter"
        and _shared_catalog_mode(config)
        and retrieval_mode in {"syndication", "twikit", "playwright"}
        and completion_target_posts > 0
        and missing_posts > 0
        and not bool(retrieval_meta.get("complete"))
    )
    if (
        (
            is_single_runner_fallback
            or is_catalog_details_refresh
            or is_incomplete_threads_profile_fallback
            or is_incomplete_twitter_fallback
        )
        and completion_target_posts > 0
        and missing_posts > 0
        and not completion_tolerance_applied
    ):
        failure_context = (
            "details refresh"
            if is_catalog_details_refresh
            else "threads profile fallback"
            if is_incomplete_threads_profile_fallback
            else "twitter fallback"
            if is_incomplete_twitter_fallback
            else "fallback"
        )
        raise SharedStageRuntimeError(
            (
                f"Shared-account {failure_context} ended early for @{account_handle}: "
                f"checked {scraped_posts} of {completion_target_posts} discovered posts"
            ),
            error_code="catalog_incomplete",
            retryable=True,
            runtime_metadata={
                "retrieval_meta": {
                    **dict(retrieval_meta or {}),
                    "completion_failure_reason": (
                        "details_refresh_missing_catalog_posts"
                        if is_catalog_details_refresh
                        else "threads_fallback_missing_catalog_posts"
                        if is_incomplete_threads_profile_fallback
                        else "twitter_fallback_missing_catalog_posts"
                        if is_incomplete_twitter_fallback
                        else "fallback_missing_catalog_posts"
                    ),
                    "expected_total_posts": expected_total_posts,
                    "completion_target_posts": completion_target_posts,
                    "observed_posts_checked": scraped_posts,
                    "observed_posts_saved": saved_posts,
                    "completion_missing_posts": missing_posts,
                    "completion_tolerance_posts": completion_tolerance_posts,
                }
            },
        )
    activity["phase"] = "shared_account_posts_end"
    activity["posts_checked"] = scraped_posts
    activity["matched_posts"] = matched_posts
    activity["saved_posts"] = saved_posts
    if scraped_comments:
        activity["scraped_comments"] = scraped_comments
    if saved_comments:
        activity["comments_upserted"] = saved_comments
    if retrieval_meta.get("total_posts") is not None:
        activity["total_posts"] = _normalize_non_negative_int(retrieval_meta.get("total_posts"))
    elif expected_total_posts > 0:
        activity["total_posts"] = expected_total_posts
    retrieval_meta["expected_total_posts"] = expected_total_posts or None
    retrieval_meta["completion_target_posts"] = completion_target_posts or None
    retrieval_meta["observed_posts_checked"] = scraped_posts
    retrieval_meta["observed_posts_saved"] = saved_posts
    retrieval_meta["completion_missing_posts"] = missing_posts
    retrieval_meta["completion_tolerance_posts"] = completion_tolerance_posts
    if completion_tolerance_applied:
        retrieval_meta["completion_tolerance_applied"] = True
    retrieval_meta["activity"] = dict(activity)
    _flush_progress(force=True)
    source_ids = sorted(
        {
            _platform_source_id(platform, row)
            for row in rows
            if isinstance(row, dict) and _platform_source_id(platform, row)
        }
    )
    _touch_shared_account_source(
        source_scope=source_scope,
        platform=platform,
        account_handle=account_handle,
        run_id=run_id or None,
        job_id=job_id,
        last_scrape_status="completed",
        metadata_updates={"profile_snapshot": _metadata_dict(retrieval_meta.get("profile_snapshot"))},
    )
    metadata = {
        "stage": SHARED_ACCOUNT_POSTS_STAGE,
        "platform": platform,
        "account": account_handle,
        "source_ids": source_ids,
        "classify_jobs_enqueued": 0,
        "persist_counters": {
            **persist_counters,
            "posts_upserted": len(rows),
            "comments_upserted": saved_comments,
        },
        "activity": dict(activity),
        "retrieval_meta": retrieval_meta,
        "expected_total_posts": expected_total_posts or None,
        "pipeline_ingest_mode": ingest_mode,
    }
    if str(config.get("partition_id") or "").strip():
        metadata["partition_id"] = str(config.get("partition_id") or "")
    return len(rows), saved_comments, metadata


