def _run_shared_post_classify_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
    job_id: str,
    worker_id: str | None = None,
) -> tuple[int, int, dict[str, Any]]:
    post_classify_started_at = time_module.monotonic()
    source_ids = [str(item or "").strip() for item in (config.get("source_ids") or []) if str(item or "").strip()]
    ingest_mode = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    progress_state = _new_job_progress_state()
    activity: dict[str, Any] = {
        "phase": "post_classify_start",
        "posts_checked": 0,
        "matched_posts": 0,
    }
    processed_rows = 0
    matched_count = 0
    ambiguous_count = 0
    unmatched_count = 0
    needs_review_count = 0
    last_heartbeat_touch_at: float | None = None

    def _touch_classify_heartbeat(*, force: bool = False) -> bool:
        nonlocal last_heartbeat_touch_at
        now_monotonic = time_module.monotonic()
        if (
            not force
            and last_heartbeat_touch_at is not None
            and now_monotonic - last_heartbeat_touch_at < POST_CLASSIFY_HEARTBEAT_MIN_INTERVAL_SECONDS
        ):
            return False
        _touch_job_heartbeat(job_id, worker_id=worker_id)
        last_heartbeat_touch_at = now_monotonic
        return True

    def _flush_progress(*, force: bool = False) -> bool:
        return _emit_job_progress(
            job_id=job_id,
            stage=POST_CLASSIFY_STAGE,
            platform=platform,
            account=account_handle,
            scraped_posts=processed_rows,
            scraped_comments=0,
            posts_upserted=matched_count,
            comments_upserted=0,
            activity=activity,
            progress_state=progress_state,
            worker_id=worker_id,
            force=force,
        )

    def _record_progress(*, force: bool = False) -> None:
        activity["phase"] = "post_classify_running"
        activity["posts_checked"] = processed_rows
        activity["matched_posts"] = matched_count
        if not _flush_progress(force=force):
            _touch_classify_heartbeat()

    _flush_progress(force=True)

    if ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:

        def _on_catalog_progress(counts: dict[str, int]) -> None:
            nonlocal processed_rows, matched_count, ambiguous_count, unmatched_count, needs_review_count
            matched_count = _normalize_non_negative_int(counts.get("assigned"))
            ambiguous_count = _normalize_non_negative_int(counts.get("ambiguous"))
            needs_review_count = _normalize_non_negative_int(counts.get("needs_review"))
            unmatched_count = _normalize_non_negative_int(counts.get("unassigned"))
            processed_rows = matched_count + ambiguous_count + needs_review_count + unmatched_count
            _record_progress()

        def _heartbeat() -> None:
            _touch_classify_heartbeat()

        counts = _classify_shared_catalog_rows(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            account_handle=account_handle,
            source_ids=source_ids or None,
            progress_cb=_on_catalog_progress,
            heartbeat_cb=_heartbeat,
        )
        matched_count = _normalize_non_negative_int(counts.get("assigned"))
        ambiguous_count = _normalize_non_negative_int(counts.get("ambiguous"))
        needs_review_count = _normalize_non_negative_int(counts.get("needs_review"))
        unmatched_count = _normalize_non_negative_int(counts.get("unassigned"))
        processed_rows = matched_count + ambiguous_count + needs_review_count + unmatched_count
        _touch_shared_account_source(
            source_scope=source_scope,
            platform=platform,
            account_handle=account_handle,
            last_classified_at=_now_utc(),
        )
        activity["phase"] = "post_classify_end"
        activity["posts_checked"] = processed_rows
        activity["matched_posts"] = matched_count
        post_classify_runtime_seconds = round(time_module.monotonic() - post_classify_started_at, 3)
        activity["runtime_seconds"] = post_classify_runtime_seconds
        _flush_progress(force=True)
        metadata = {
            "stage": POST_CLASSIFY_STAGE,
            "platform": platform,
            "account": account_handle,
            "post_classify_runtime_seconds": post_classify_runtime_seconds,
            "matched_count": matched_count,
            "ambiguous_count": ambiguous_count,
            "unmatched_count": unmatched_count,
            "needs_review_count": needs_review_count,
            "activity": dict(activity),
            "pipeline_ingest_mode": ingest_mode,
        }
        return processed_rows, 0, metadata
    rows = _shared_post_rows_for_account(
        platform=platform,
        account_handle=account_handle,
        source_scope=source_scope,
        source_ids=source_ids or None,
        unassigned_only=False,
    )
    targets = _list_matchable_seasons(source_scope=source_scope, platform=platform)
    matched_source_ids: list[str] = []
    matched_season_ids: set[str] = set()
    for row in rows:
        source_id = str(row.get("source_id") or "").strip()
        post_row_id = str(row.get("id") or "").strip()
        source_account = (
            _normalize_account_handle(row.get("source_account")) or str(row.get("source_account") or "").strip()
        )
        matches: list[dict[str, Any]] = []
        for target_index, target in enumerate(targets):
            is_match, score, reason = _shared_row_matches_target(platform=platform, row=row, target=target)
            if not is_match:
                continue
            context = target["context"]
            evidence = _normalized_social_post_evidence_payload(
                platform=platform,
                row=row,
                target=target,
                status="candidate",
                score=score,
                reason=reason,
            )
            matches.append(
                {
                    "season_id": context.season_id,
                    "show_id": context.show_id,
                    "show_name": context.show_name,
                    "season_number": context.season_number,
                    "score": score,
                    "reason": reason,
                    "confidence_tier": evidence["match"]["confidence_tier"],
                    "signals": evidence["match"]["signals"],
                    "_target_index": target_index,
                }
            )
        matches.sort(key=lambda item: (-int(item.get("score") or 0), int(item.get("season_number") or 0)))
        candidate_matches = [_compact_social_candidate_match(match) for match in matches]
        if len(matches) == 1 or (
            len(matches) > 1 and int(matches[0].get("score") or 0) > int(matches[1].get("score") or 0)
        ):
            winner = matches[0]
            winner_target_index = max(0, int(winner.get("_target_index") or 0))
            winner_target = targets[winner_target_index] if winner_target_index < len(targets) else {}
            winner_evidence = _normalized_social_post_evidence_payload(
                platform=platform,
                row=row,
                target=winner_target,
                status="matched",
                score=int(winner.get("score") or 0),
                reason=str(winner.get("reason") or "auto_matched"),
                candidate_matches=candidate_matches,
            )
            _upsert_shared_post_match_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                matched_show_id=str(winner.get("show_id") or "") or None,
                matched_season_id=str(winner.get("season_id") or "") or None,
                status="matched",
                score=int(winner.get("score") or 0),
                reason=str(winner.get("reason") or "auto_matched"),
                candidate_matches=candidate_matches,
                metadata={"account_handle": account_handle, "evidence": winner_evidence},
                run_id=run_id,
            )
            _resolve_shared_review_queue_record(
                platform=platform,
                source_scope=source_scope,
                source_id=source_id,
                resolution_action="auto_matched",
                resolved_show_id=str(winner.get("show_id") or "") or None,
                resolved_season_id=str(winner.get("season_id") or "") or None,
            )
            matched_source_ids.append(source_id)
            matched_season_ids.add(str(winner.get("season_id") or ""))
        elif matches:
            ambiguous_count += 1
            top_match = matches[0]
            top_target_index = max(0, int(top_match.get("_target_index") or 0))
            top_target = targets[top_target_index] if top_target_index < len(targets) else {}
            ambiguous_evidence = _normalized_social_post_evidence_payload(
                platform=platform,
                row=row,
                target=top_target,
                status="ambiguous",
                score=int(top_match.get("score") or 0),
                reason="ambiguous_match",
                candidate_matches=candidate_matches,
            )
            _upsert_shared_post_match_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                status="ambiguous",
                score=int(matches[0].get("score") or 0),
                reason="ambiguous_match",
                candidate_matches=candidate_matches,
                metadata={"account_handle": account_handle, "evidence": ambiguous_evidence},
                run_id=run_id,
            )
            _upsert_shared_review_queue_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                review_reason="ambiguous_match",
                run_id=run_id,
                payload={
                    "account_handle": account_handle,
                    "candidate_matches": candidate_matches,
                    "evidence": ambiguous_evidence,
                },
            )
        else:
            unmatched_count += 1
            unmatched_evidence = _normalized_social_post_evidence_payload(
                platform=platform,
                row=row,
                status="unmatched",
                score=0,
                reason="no_season_match",
                candidate_matches=[],
            )
            _upsert_shared_post_match_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                status="unmatched",
                score=0,
                reason="no_season_match",
                candidate_matches=[],
                metadata={
                    "account_handle": account_handle,
                    "retained_unassigned": True,
                    "evidence": unmatched_evidence,
                },
                run_id=run_id,
            )
            _upsert_shared_review_queue_record(
                platform=platform,
                source_scope=source_scope,
                post_row_id=post_row_id,
                source_id=source_id,
                source_account=source_account,
                review_reason="unmatched",
                run_id=run_id,
                payload={"account_handle": account_handle, "candidate_matches": [], "evidence": unmatched_evidence},
            )
        processed_rows += 1
        matched_count = len(matched_source_ids)
        _record_progress()
    _touch_shared_account_source(
        source_scope=source_scope,
        platform=platform,
        account_handle=account_handle,
        last_classified_at=_now_utc(),
    )
    if matched_source_ids:
        _enqueue_shared_materialize_job(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            account_handle=account_handle,
            matched_source_ids=matched_source_ids,
            season_ids=sorted(season_id for season_id in matched_season_ids if season_id),
            pipeline_ingest_mode=ingest_mode,
            worker_id=worker_id,
        )
    activity["phase"] = "post_classify_end"
    activity["posts_checked"] = processed_rows
    activity["matched_posts"] = matched_count
    post_classify_runtime_seconds = round(time_module.monotonic() - post_classify_started_at, 3)
    activity["runtime_seconds"] = post_classify_runtime_seconds
    _flush_progress(force=True)
    metadata = {
        "stage": POST_CLASSIFY_STAGE,
        "platform": platform,
        "account": account_handle,
        "post_classify_runtime_seconds": post_classify_runtime_seconds,
        "matched_source_ids": matched_source_ids,
        "matched_count": matched_count,
        "ambiguous_count": ambiguous_count,
        "unmatched_count": unmatched_count,
        "activity": dict(activity),
        "pipeline_ingest_mode": ingest_mode,
    }
    return processed_rows, 0, metadata


def _run_shared_season_materialize_stage(
    *,
    run_id: str,
    platform: str,
    source_scope: str,
    account_handle: str,
    config: Mapping[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    ingest_mode = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    source_ids = [str(item or "").strip() for item in (config.get("source_ids") or []) if str(item or "").strip()]
    if not source_ids:
        return (
            0,
            0,
            {
                "stage": SEASON_MATERIALIZE_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "skipped": True,
                "reason": "no_source_ids",
            },
        )
    rows = pg.fetch_all(
        """
        select
          id::text as id,
          source_id,
          matched_show_id::text as matched_show_id,
          matched_season_id::text as matched_season_id,
          status
        from social.shared_post_matches
        where platform = %s
          and source_scope = %s
          and status = 'matched'
          and source_id = any(%s)
        """,
        [platform, source_scope, source_ids or []],
    )
    materialized = 0
    refresh_season_ids: set[str] = set()
    for row in rows:
        source_id = str(row.get("source_id") or "").strip()
        matched_season_id = str(row.get("matched_season_id") or "").strip()
        matched_show_id = str(row.get("matched_show_id") or "").strip()
        if not source_id or not matched_season_id or not matched_show_id:
            continue
        target_context = get_season_context(matched_season_id)
        post_rows = _shared_post_rows_for_account(
            platform=platform,
            account_handle=account_handle,
            source_scope=source_scope,
            source_ids=[source_id],
            unassigned_only=False,
        )
        if not post_rows:
            continue
        post_row = post_rows[0]
        post_id = str(post_row.get("id") or "").strip()
        if not post_id:
            continue
        _update_platform_post_field(platform=platform, post_id=post_id, field="season_id", value=matched_season_id)
        _update_platform_post_field(platform=platform, post_id=post_id, field="show_id", value=matched_show_id)
        comments_job_config = {
            "run_id": run_id,
            "season_id": matched_season_id,
            "show_id": matched_show_id,
            "platform": platform,
            "source_scope": source_scope,
            "stage": "comments",
            "account": account_handle,
            "hashtags": [],
            "keywords": [],
            "sync_strategy": "incremental",
            "max_posts_per_target": 0,
            "max_comments_per_post": max(
                1, _resolve_positive_int_env("SOCIAL_SHARED_DEFAULT_MAX_COMMENTS_PER_POST", 50, minimum=1)
            ),
            "max_replies_per_post": 100,
            "fetch_replies": True,
            "ingest_mode": "comments_only",
            "comment_refresh_policy": DEFAULT_COMMENT_REFRESH_POLICY,
            "comment_anchor_source_ids": {platform: [source_id]},
            "pipeline_ingest_mode": ingest_mode,
        }
        _create_job(
            target_context,
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            job_type="comments",
            stage="comments",
            config=comments_job_config,
            initiated_by=None,
            status="queued" if is_queue_enabled() else "pending",
            priority=200,
        )
        try:
            _enqueue_platform_media_mirror_job(
                target_context,
                platform=platform,
                run_id=run_id,
                source_scope=source_scope,
                account=account_handle,
                post_row=post_row,
                week_index=None,
                parent_job_id=f"shared-materialize:{source_id}",
                conn=None,
            )
        except Exception:  # noqa: BLE001
            logger.exception("Failed to enqueue media mirror during shared materialization: %s %s", platform, source_id)
        materialized += 1
        refresh_season_ids.add(matched_season_id)
    if refresh_season_ids:
        _enqueue_shared_analytics_refresh_job(
            run_id=run_id,
            platform=platform,
            source_scope=source_scope,
            season_ids=sorted(refresh_season_ids),
            pipeline_ingest_mode=ingest_mode,
        )
    metadata = {
        "stage": SEASON_MATERIALIZE_STAGE,
        "platform": platform,
        "account": account_handle,
        "materialized_count": materialized,
        "season_ids": sorted(refresh_season_ids),
        "activity": {"phase": "season_materialize_end", "last_progress_at": _iso(_now_utc())},
        "pipeline_ingest_mode": ingest_mode,
    }
    return materialized, 0, metadata


def _run_shared_analytics_refresh_stage(
    *,
    config: Mapping[str, Any],
) -> tuple[int, int, dict[str, Any]]:
    season_ids = [str(item or "").strip() for item in (config.get("season_ids") or []) if str(item or "").strip()]
    ingest_mode = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    _invalidate_week_detail_cache_after_run_terminal_status()
    metadata = {
        "stage": ANALYTICS_REFRESH_STAGE,
        "season_ids": season_ids,
        "activity": {"phase": "analytics_refresh_end", "last_progress_at": _iso(_now_utc())},
        "pipeline_ingest_mode": ingest_mode,
    }
    return len(season_ids), 0, metadata


def _execute_shared_claimed_job(job: Mapping[str, Any], *, worker_id: str | None = None) -> dict[str, Any]:
    job_id = str(job.get("id") or "").strip()
    run_id = str(job.get("run_id") or "").strip()
    config = dict(job.get("config") or {})
    followup_worker_id = _inline_fallback_followup_worker_id(config, worker_id=worker_id)
    stage = str(config.get("stage") or (job.get("metadata") or {}).get("stage") or "").strip().lower()
    ingest_mode = str(config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    platform = _normalize_platform_name(job.get("platform"))
    source_scope = str(config.get("source_scope") or job.get("source_scope") or "network").strip().lower()
    account_handle = _resolve_shared_account_handle(job, config)
    dispatch_backend = ""
    try:
        if not account_handle:
            raise SharedStageRuntimeError(
                "Shared-account ingest job is missing an account handle.",
                error_code="shared_account_handle_missing",
                retryable=False,
                runtime_metadata={
                    "shared_account_source_id": config.get("shared_account_source_id"),
                    "platform": platform,
                    "job_id": job_id,
                },
            )
        dispatch_metadata = _job_dispatch_metadata(job)
        dispatch_backend = str(dispatch_metadata.get("dispatch_backend") or "").strip().lower()
        modal_claim = dispatch_backend == "modal" or str(worker_id or "").strip().lower().startswith("modal:")
        if _job_requires_modal_executor(config, platform=platform) and not modal_claim:
            raise SharedStageRuntimeError(
                f"Shared-account instagram catalog backfill for @{account_handle} cannot run on the local executor.",
                error_code=INSTAGRAM_LOCAL_EXECUTOR_BLOCKED_ERROR_CODE,
                retryable=True,
                runtime_metadata={
                    "required_execution_backend": "modal",
                    "dispatch_backend": dispatch_backend or "local",
                    "platform": platform,
                    "account": account_handle,
                },
            )
        if _job_requires_trusted_local_worker_lane(config, platform=platform) and dispatch_backend == "modal":
            raise SharedStageRuntimeError(
                f"Shared-account instagram catalog backfill for @{account_handle} cannot run on the remote executor.",
                error_code=INSTAGRAM_REMOTE_EXECUTOR_BLOCKED_ERROR_CODE,
                retryable=True,
                runtime_metadata={
                    "required_worker_lane": TRUSTED_LOCAL_WORKER_LANE,
                    "dispatch_backend": "modal",
                    "platform": platform,
                    "account": account_handle,
                },
            )
        _maybe_auto_supersede_catalog_runtime_for_job(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            source_scope=source_scope,
        )
        try:
            cancelled_result = _abort_claimed_job_if_cancelled(
                job_id=job_id,
                run_id=run_id,
                stage=stage,
                platform=platform,
                account=account_handle,
            )
        except pg.DatabaseServiceUnavailableError as cancel_exc:
            logger.warning(
                "[shared-account] cancel-state check deferred for job=%s stage=%s account=%s error=%s",
                job_id,
                stage,
                account_handle,
                cancel_exc,
            )
            cancelled_result = None
        if cancelled_result is not None:
            return cancelled_result
        if stage == SHARED_ACCOUNT_DISCOVERY_STAGE:
            posts_count, comments_count, metadata = _run_shared_account_discovery_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                job_id=job_id,
                worker_id=worker_id,
            )
        elif stage == SHARED_ACCOUNT_POSTS_STAGE:
            posts_count, comments_count, metadata = _run_shared_account_posts_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                job_id=job_id,
                worker_id=worker_id,
            )
        elif platform == "instagram" and stage == INSTAGRAM_PROFILE_SNAPSHOT_STAGE:
            posts_count, comments_count, metadata = _run_instagram_profile_snapshot_stage(
                run_id=run_id,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                job_id=job_id,
            )
        elif platform == "instagram" and stage == INSTAGRAM_PROFILE_FOLLOWING_STAGE:
            posts_count, comments_count, metadata = _run_instagram_profile_following_stage(
                run_id=run_id,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                job_id=job_id,
            )
        elif stage == POST_CLASSIFY_STAGE:
            posts_count, comments_count, metadata = _run_shared_post_classify_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
                job_id=job_id,
                worker_id=worker_id,
            )
        elif stage == SEASON_MATERIALIZE_STAGE:
            posts_count, comments_count, metadata = _run_shared_season_materialize_stage(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                config=config,
            )
        elif stage == ANALYTICS_REFRESH_STAGE:
            posts_count, comments_count, metadata = _run_shared_analytics_refresh_stage(config=config)
        else:
            raise ValueError(f"Unsupported shared ingest stage: {stage}")
        _maybe_auto_supersede_catalog_runtime_for_job(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            source_scope=source_scope,
        )
        try:
            cancelled_result = _abort_claimed_job_if_cancelled(
                job_id=job_id,
                run_id=run_id,
                stage=stage,
                platform=platform,
                account=account_handle,
            )
        except pg.DatabaseServiceUnavailableError as cancel_exc:
            logger.warning(
                "[shared-account] post-stage cancel-state check deferred for job=%s stage=%s account=%s error=%s",
                job_id,
                stage,
                account_handle,
                cancel_exc,
            )
            cancelled_result = None
        if cancelled_result is not None:
            return cancelled_result
        _clear_posts_auth_cooldown_after_success(
            platform=platform,
            stage=stage,
            job_type=job.get("job_type"),
            account_handle=account_handle,
            metadata=metadata,
        )
        _finish_job(
            job_id,
            status="completed",
            items_found=posts_count + comments_count,
            metadata=metadata,
        )
    except Exception as exc:  # noqa: BLE001
        runtime_error_code = str(getattr(exc, "error_code", "") or "").strip().lower()
        runtime_error_class = str(getattr(exc, "error_class", "") or "").strip()
        runtime_retryable = getattr(exc, "retryable", None)
        runtime_metadata = _metadata_dict(getattr(exc, "runtime_metadata", None))
        error_code = _shared_account_normalize_runtime_error_code(
            runtime_error_code or "shared_stage_failed",
            config=config,
            runtime_metadata=runtime_metadata,
            dispatch_backend=dispatch_backend,
            worker_id=worker_id,
        )
        error_class = runtime_error_class or exc.__class__.__name__
        attempt_count = int(job.get("attempt_count") or 1)
        max_attempts = int(job.get("max_attempts") or 1)
        database_capacity_error = _shared_account_error_is_database_capacity(error_class, exc)
        if error_code == "shared_stage_failed" and database_capacity_error:
            error_code = "database_capacity"
        cancelled_error = error_code in {
            SHARED_ACCOUNT_STAGE_CANCELLED_ERROR_CODE,
            SHARED_ACCOUNT_POSTS_CANCELLED_ERROR_CODE,
        } or bool(runtime_metadata.get("cancelled"))
        can_retry = (
            (bool(runtime_retryable) and attempt_count < max_attempts)
            if runtime_retryable is not None
            else (attempt_count < max_attempts)
        )
        if cancelled_error:
            can_retry = False
        if stage == POST_CLASSIFY_STAGE and database_capacity_error and not can_retry:
            prior_metadata = _metadata_dict(job.get("metadata"))
            retry_count = _normalize_non_negative_int(prior_metadata.get("post_classify_db_transient_retry_count"))
            retry_limit = _post_classify_db_transient_retry_limit()
            if retry_count < retry_limit:
                can_retry = True
                runtime_metadata["post_classify_db_transient_retry_count"] = retry_count + 1
                runtime_metadata["post_classify_db_transient_retry_limit"] = retry_limit
        if (
            error_code == "instagram_modal_initial_empty_page"
            and _normalize_non_negative_int(config.get("initial_empty_page_retry_count"))
            >= _shared_account_initial_empty_page_retry_limit()
        ):
            can_retry = False
        next_available_at = _now_utc() + timedelta(seconds=_retry_backoff_seconds(attempt_count)) if can_retry else None
        cooldown_payload = _record_posts_auth_cooldown_if_applicable(
            platform=platform,
            stage=stage,
            job_type=job.get("job_type"),
            account_handle=account_handle,
            error_code=error_code,
            error_message=str(exc),
            metadata=runtime_metadata,
        )
        if can_retry:
            next_available_at = _defer_retry_until_posts_auth_cooldown(
                platform=platform,
                stage=stage,
                job_type=job.get("job_type"),
                account_handle=account_handle,
                next_available_at=next_available_at,
                metadata=runtime_metadata,
            )
        elif cooldown_payload:
            cooldown_until = _coerce_dt(cooldown_payload.get("cooldown_until"))
            if cooldown_until is not None:
                next_available_at = cooldown_until
        retry_config_updates = (
            _shared_account_retry_config_updates(
                config,
                platform=platform,
                stage=stage,
                error_code=error_code,
            )
            if can_retry
            else {}
        )
        if _shared_instagram_cursor_auth_repair_required(
            platform=platform,
            stage=stage,
            error_code=error_code,
            config=config,
            retry_config_updates=retry_config_updates,
        ):
            can_retry = False
            next_available_at = None
            error_code = "instagram_graphql_cursor_auth_repair_required"
            error_class = "InstagramAuthRepairRequired"
            repair_required_at = _iso(_now_utc())
            retry_config_updates = {
                **retry_config_updates,
                "instagram_auth_repair_required": True,
                "instagram_auth_repair_required_at": repair_required_at,
                "instagram_auth_repair_reason": "repeated_cursor_auth_failure",
                "auth_repair_repairable_reason": "repeated_cursor_auth_failure",
            }
            runtime_metadata.update(
                {
                    "instagram_auth_repair_required": True,
                    "auth_repair_required_at": repair_required_at,
                    "auth_repair_reason": "repeated_cursor_auth_failure",
                    "cursor_auth_repair_threshold": _shared_instagram_cursor_auth_repair_threshold(),
                    "retryable": False,
                }
            )
        retry_requeue: dict[str, Any] | None = None
        if can_retry and error_code == "instagram_modal_initial_empty_page":
            try:
                assert_worker_available_when_queue_enabled(
                    required_execution_backend="modal",
                    platform=platform,
                )
            except SocialWorkerUnavailableError as worker_exc:
                runtime_metadata["worker_health"] = _metadata_dict(worker_exc.worker_health)
                unavailable_reason = _shared_account_authenticated_modal_worker_unavailable_reason(
                    worker_exc.worker_health
                )
                if unavailable_reason:
                    error_code = "no_authenticated_modal_workers"
                    error_class = worker_exc.__class__.__name__
                    can_retry = False
                    retry_config_updates = {}
                    next_available_at = None
        if (
            can_retry
            and stage == SHARED_ACCOUNT_POSTS_STAGE
            and error_code != "instagram_modal_initial_empty_page"
            and not _shared_account_error_is_database_capacity(error_class, exc)
            and _shared_account_prefers_partitioned_backfill_recovery(
                config,
                platform=platform,
            )
        ):
            recovery_frontier_auth_allowed = retry_config_updates.get(
                "frontier_auth_allowed",
                config.get("frontier_auth_allowed"),
            )
            recovery_frontier_auth_reason = retry_config_updates.get(
                "frontier_auth_reason",
                config.get("frontier_auth_reason"),
            )
            recovery_transport_preference = (
                str(
                    retry_config_updates.get("transport_preference")
                    or retry_config_updates.get("frontier_transport")
                    or config.get("transport_preference")
                    or config.get("frontier_transport")
                    or ""
                )
                .strip()
                .lower()
                or None
            )
            recovery_allow_public_transport_fallback = (
                retry_config_updates["allow_public_transport_fallback"]
                if "allow_public_transport_fallback" in retry_config_updates
                else config.get("allow_public_transport_fallback")
            )
            if (
                platform == "instagram"
                and recovery_frontier_auth_allowed is True
                and recovery_transport_preference == "authenticated"
            ):
                recovery_allow_public_transport_fallback = False
            expected_total_posts = _shared_account_expected_total_posts_from_config(
                config,
                platform=platform,
                account_handle=account_handle,
            )
            try:
                recovery_job_id = _enqueue_shared_discovery_job(
                    run_id=run_id,
                    platform=platform,
                    source_scope=source_scope,
                    account_handle=account_handle,
                    shared_account_source_id=config.get("shared_account_source_id"),
                    pipeline_ingest_mode=ingest_mode,
                    runner_count=max(
                        1,
                        _normalize_non_negative_int(config.get("runner_count"))
                        or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                    ),
                    expected_total_posts=expected_total_posts,
                    runner_strategy="full_history_cursor_breakpoints",
                    partition_strategy=CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                    required_worker_lane=str(config.get("required_worker_lane") or "").strip().lower() or None,
                    required_execution_backend=str(config.get("required_execution_backend") or "").strip().lower()
                    or None,
                    allow_local_dev_inline_bypass=bool(config.get("allow_local_dev_inline_bypass")),
                    frontier_auth_allowed=recovery_frontier_auth_allowed if platform == "instagram" else None,
                    frontier_auth_reason=recovery_frontier_auth_reason if platform == "instagram" else None,
                    transport_preference=recovery_transport_preference if platform == "instagram" else None,
                    allow_public_transport_fallback=(
                        recovery_allow_public_transport_fallback if platform == "instagram" else None
                    ),
                    date_start=_coerce_dt(config.get("date_start")),
                    date_end=_coerce_dt(config.get("date_end")),
                    catalog_action=str(config.get("catalog_action") or "").strip().lower() or None,
                    catalog_action_scope=str(config.get("catalog_action_scope") or "").strip().lower() or None,
                    selected_tasks=config.get("selected_tasks"),
                    effective_selected_tasks=config.get("effective_selected_tasks"),
                    details_refresh_skip_detail_fetch=config.get("details_refresh_skip_detail_fetch"),
                    details_refresh_force_detail_fetch=config.get("details_refresh_force_detail_fetch"),
                    details_refresh_skip_media_followups=config.get("details_refresh_skip_media_followups"),
                    tiktok_comments_in_posts_stage=bool(config.get("tiktok_comments_in_posts_stage")),
                    tiktok_direct_comment_api_override=bool(config.get("tiktok_direct_comment_api_override")),
                    twitter_comments_in_posts_stage=bool(config.get("twitter_comments_in_posts_stage")),
                    initiated_by=None,
                    worker_id=followup_worker_id,
                    priority=100,
                    recovery_depth=_normalize_non_negative_int(config.get("recovery_depth")) + 1,
                )
            except pg.DatabaseServiceUnavailableError as enqueue_exc:
                logger.warning(
                    "[shared-account] recovery discovery enqueue deferred for run=%s stage=%s account=%s error=%s",
                    run_id,
                    stage,
                    account_handle,
                    enqueue_exc,
                )
            else:
                retry_requeue = {
                    "job_id": recovery_job_id,
                    "stage": SHARED_ACCOUNT_DISCOVERY_STAGE,
                    "runner_strategy": "full_history_cursor_breakpoints",
                    "partition_strategy": CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY,
                }
                retry_config_updates = {}
                next_available_at = None
        if retry_config_updates:
            updated_config = _update_job_config(job_id, config_updates=retry_config_updates)
            if updated_config:
                config = updated_config
        _record_shared_account_frontier_retry_details(
            run_id=run_id,
            platform=platform,
            account_handle=account_handle,
            stage=stage,
            job_id=job_id,
            attempt_count=attempt_count,
            max_attempts=max_attempts,
            error_code=error_code,
            error_class=error_class,
            error_message=str(exc),
            can_retry=can_retry,
            next_available_at=next_available_at,
            metadata=runtime_metadata,
        )
        try:
            existing_job = (
                pg.fetch_one(
                    "select items_found, metadata from social.scrape_jobs where id = %s",
                    [job_id],
                )
                or {}
            )
        except pg.DatabaseServiceUnavailableError as fetch_exc:
            logger.warning(
                "[shared-account] existing job metadata fetch deferred for job=%s stage=%s account=%s error=%s",
                job_id,
                stage,
                account_handle,
                fetch_exc,
            )
            existing_job = {}
        metadata = _metadata_dict(existing_job.get("metadata"))
        metadata.update(
            {
                "stage": stage,
                "platform": platform,
                "account": account_handle,
                "pipeline_ingest_mode": ingest_mode,
                "error": str(exc),
                "error_code": error_code,
                "error_class": error_class,
                "retryable": can_retry,
            }
        )
        if retry_requeue:
            metadata["retry_requeue"] = retry_requeue
        if retry_config_updates:
            metadata["retry_config_updates"] = retry_config_updates
        metadata.update(runtime_metadata)
        activity = _metadata_dict(metadata.get("activity"))
        activity["phase"] = "cancelled" if cancelled_error else "requeued" if retry_requeue else "failed"
        activity["last_progress_at"] = _iso(_now_utc())
        metadata["activity"] = activity
        try:
            _finish_job(
                job_id,
                status="cancelled" if cancelled_error or retry_requeue else ("retrying" if can_retry else "failed"),
                items_found=_normalize_non_negative_int(existing_job.get("items_found")),
                error_message=str(exc),
                metadata=metadata,
                last_error_code=error_code,
                last_error_class=error_class,
                next_available_at=next_available_at,
            )
        except Exception:  # noqa: BLE001
            logger.exception(
                "CRITICAL: _finish_job() failed for job_id=%s — job stuck in running state",
                job_id,
            )
        if cancelled_error:
            logger.info(
                "Shared social ingest job cancelled: job_id=%s stage=%s platform=%s phase=%s",
                job_id,
                stage,
                platform,
                _metadata_dict(runtime_metadata.get("activity")).get("cancelled_phase"),
            )
        else:
            logger.exception("Shared social ingest job failed: job_id=%s stage=%s platform=%s", job_id, stage, platform)
    finally:
        if run_id:
            _finalize_run_status(run_id)
    return _load_current_job_row(job_id)


def _execute_shared_claimed_job_adapter(
    job: Mapping[str, Any],
    *,
    worker_id: str | None = None,
) -> dict[str, Any]:
    return _execute_shared_claimed_job(job, worker_id=worker_id)


configure_shared_claimed_job_executor(_execute_shared_claimed_job_adapter)


def _job_stage_from_row(job: Mapping[str, Any]) -> str:
    config = dict(job.get("config") or {})
    metadata = dict(job.get("metadata") or {})
    return (
        _normalize_social_job_stage_for_stale(config.get("stage") or metadata.get("stage") or job.get("job_type"))
        or "unknown"
    )


def _dispatch_request_is_fresh(job: Mapping[str, Any]) -> bool:
    dispatch = _job_dispatch_metadata(job)
    remote_status = _modal_invocation_status(dispatch)
    if remote_status and remote_status != "unknown" and not _modal_invocation_is_nonterminal(remote_status):
        return False
    requested_at = _coerce_dt(dispatch.get("dispatch_requested_at"))
    if requested_at is None:
        return False
    return (_now_utc() - requested_at) < timedelta(seconds=_modal_dispatch_retry_delay_seconds())


def _list_candidate_jobs_for_modal_dispatch(*, run_id: str | None = None, limit: int = 200) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 500))
    sql = """
        with due_jobs as (
        select
          j.id::text as id,
          j.run_id::text as run_id,
          j.platform,
          j.job_type,
          j.status,
          j.priority,
          j.created_at,
          j.available_at,
          j.config,
          j.metadata,
          row_number() over (
            partition by coalesce(run_id::text, ''),
              lower(coalesce(j.platform, '')),
              lower(coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type, 'unknown'))
            order by j.priority asc, j.created_at asc
          ) as queue_rank
        from social.scrape_jobs j
        left join social.scrape_runs r on r.id = j.run_id
        where j.status in ('queued', 'pending', 'retrying')
          and j.available_at <= now()
          and (%s::uuid is null or j.run_id = %s::uuid)
          and (
            %s::uuid is not null
            or j.run_id is null
            or r.id is null
            or (
              (
                lower(coalesce(r.config->>'pause_after_current', '')) not in ('1', 'true', 'yes', 'on')
                and lower(
                  coalesce(r.config #>> '{dispatch_control,pause_after_current}', '')
                ) not in ('1', 'true', 'yes', 'on')
              )
              or (
                coalesce(r.config #>> '{dispatch_control,resume_after}', r.config->>'resume_after', '')
                  ~ (
                    '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
                    '([T ][0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?'
                    '([+-][0-9]{2}:?[0-9]{2}|Z)?)?$'
                  )
                and replace(
                  coalesce(r.config #>> '{dispatch_control,resume_after}', r.config->>'resume_after'),
                  'Z',
                  '+00:00'
                )::timestamptz <= now()
              )
            )
          )
        )
        select
          id,
          run_id,
          platform,
          job_type,
          status,
          priority,
          created_at,
          available_at,
          config,
          metadata
        from due_jobs
        order by queue_rank asc, priority asc, created_at asc
        limit %s
    """
    rows = pg.fetch_all(sql, [run_id, run_id, run_id, safe_limit])
    return [row for row in rows if _job_blocked_by_posts_auth_cooldown(row) is None]


MEDIA_MIRROR_DRAIN_STOP_RULE_ERROR_CODES = {
    "checkpoint",
    "checkpoint_required",
    "instagram_graphql_cursor_unauthorized",
    "instagram_graphql_cursor_forbidden",
    "instagram_graphql_cursor_auth_repair_required",
    "instagram_posts_auth_unavailable",
    "instagram_comments_auth_unavailable",
    "instagram_auth_repair_required",
}


def _media_mirror_drain_stages(stage: str | None) -> list[str]:
    normalized = str(stage or INSTAGRAM_MEDIA_MIRROR_STAGE).strip().lower()
    if normalized == "all":
        return [INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE]
    if normalized not in {INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE}:
        raise ValueError("stage must be media_mirror, comment_media_mirror, or all")
    return [normalized]


def _media_mirror_account_filter_sql(alias: str = "j") -> str:
    return f"""
        lower(coalesce(
          nullif(trim({alias}.config->>'account'), ''),
          nullif(trim({alias}.config->>'account_handle'), ''),
          nullif(trim({alias}.config->>'source_account'), ''),
          nullif(trim({alias}.config->>'username'), ''),
          nullif(trim({alias}.metadata->>'account'), ''),
          nullif(trim({alias}.metadata->>'account_handle'), ''),
          nullif(trim({alias}.metadata->>'source_account'), ''),
          nullif(trim({alias}.metadata->>'username'), ''),
          ''
        ))
    """


def _media_mirror_stage_sql(alias: str = "j") -> str:
    return f"lower(coalesce({alias}.config->>'stage', {alias}.metadata->>'stage', {alias}.job_type, 'unknown'))"


def _normalize_media_mirror_drain_account(account_handle: str | None) -> str:
    normalized = _normalize_account_handle(account_handle) or str(account_handle or "").strip().lower().lstrip("@")
    if not normalized:
        raise ValueError("account_handle is required")
    return normalized


def get_media_mirror_account_drain_status(
    *,
    run_id: str,
    account_handle: str,
    stage: str = INSTAGRAM_MEDIA_MIRROR_STAGE,
    stale_after_seconds: int = 900,
    oldest_limit: int = 10,
) -> dict[str, Any]:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        raise ValueError("run_id is required")
    normalized_account = _normalize_media_mirror_drain_account(account_handle)
    stages = _media_mirror_drain_stages(stage)
    safe_stale_after = max(30, int(stale_after_seconds or 900))
    safe_oldest_limit = max(1, min(int(oldest_limit or 10), 50))
    stage_expr = _media_mirror_stage_sql("j")
    account_expr = _media_mirror_account_filter_sql("j")
    status_rows = pg.fetch_all(
        f"""
        select
          j.status,
          {stage_expr} as stage,
          count(*)::int as total,
          min(extract(epoch from (now() - coalesce(j.available_at, j.created_at)))::int)
            filter (where j.status in ('queued', 'pending', 'retrying')) as youngest_queued_age_seconds,
          max(extract(epoch from (now() - coalesce(j.available_at, j.created_at)))::int)
            filter (where j.status in ('queued', 'pending', 'retrying')) as oldest_queued_age_seconds
        from social.scrape_jobs j
        where j.platform = 'instagram'
          and j.run_id = %s::uuid
          and {account_expr} = %s::text
          and {stage_expr} = any(%s::text[])
        group by 1, 2
        """,
        [normalized_run_id, normalized_account, stages],
    )
    by_status: dict[str, int] = {}
    by_stage: dict[str, dict[str, int]] = {}
    oldest_queued_age_seconds = 0
    for row in status_rows:
        row_status = str(row.get("status") or "unknown").strip().lower() or "unknown"
        row_stage = _normalize_social_job_stage_for_stale(row.get("stage")) or "unknown"
        total = _normalize_non_negative_int(row.get("total"))
        by_status[row_status] = by_status.get(row_status, 0) + total
        by_stage.setdefault(row_stage, {})[row_status] = by_stage.setdefault(row_stage, {}).get(row_status, 0) + total
        oldest_queued_age_seconds = max(
            oldest_queued_age_seconds,
            _normalize_non_negative_int(row.get("oldest_queued_age_seconds")),
        )
    oldest_rows = pg.fetch_all(
        f"""
        select
          j.id::text as id,
          j.run_id::text as run_id,
          j.status,
          {stage_expr} as stage,
          nullif(coalesce(j.config->>'source_id', j.config->>'shortcode', ''), '') as source_id,
          nullif(j.config->>'post_id', '') as post_id,
          j.created_at,
          j.available_at,
          extract(epoch from (now() - coalesce(j.available_at, j.created_at)))::int as queued_age_seconds
        from social.scrape_jobs j
        where j.platform = 'instagram'
          and j.run_id = %s::uuid
          and {account_expr} = %s::text
          and {stage_expr} = any(%s::text[])
          and j.status in ('queued', 'pending', 'retrying')
        order by coalesce(j.available_at, j.created_at) asc, j.created_at asc
        limit %s
        """,
        [normalized_run_id, normalized_account, stages, safe_oldest_limit],
    )
    recent_failure_rows = pg.fetch_all(
        f"""
        select
          coalesce(j.last_error_code, '') as last_error_code,
          coalesce(j.last_error_class, '') as last_error_class,
          count(*)::int as total
        from social.scrape_jobs j
        where j.platform = 'instagram'
          and j.run_id = %s::uuid
          and {account_expr} = %s::text
          and {stage_expr} = any(%s::text[])
          and j.status in ('failed', 'retrying')
          and coalesce(j.completed_at, j.created_at) >= now() - interval '30 minutes'
        group by 1, 2
        order by total desc
        limit 10
        """,
        [normalized_run_id, normalized_account, stages],
    )
    stale_running_row = pg.fetch_one(
        f"""
        select count(*)::int as total
        from social.scrape_jobs j
        where j.platform = 'instagram'
          and j.run_id = %s::uuid
          and {account_expr} = %s::text
          and {stage_expr} = any(%s::text[])
          and j.status = 'running'
          and coalesce(j.heartbeat_at, j.started_at, j.claimed_at, j.created_at)
            < now() - (%s * interval '1 second')
        """,
        [normalized_run_id, normalized_account, stages, safe_stale_after],
    )
    remaining_count = sum(by_status.get(status, 0) for status in ("queued", "pending", "retrying", "running"))
    stop_rule_failures = [
        {
            "last_error_code": str(row.get("last_error_code") or "").strip() or None,
            "last_error_class": str(row.get("last_error_class") or "").strip() or None,
            "total": _normalize_non_negative_int(row.get("total")),
        }
        for row in recent_failure_rows
        if str(row.get("last_error_code") or "").strip().lower() in MEDIA_MIRROR_DRAIN_STOP_RULE_ERROR_CODES
        or "checkpoint" in str(row.get("last_error_class") or "").strip().lower()
    ]
    return {
        "run_id": normalized_run_id,
        "account_handle": normalized_account,
        "stage": stage,
        "stages": stages,
        "by_status": by_status,
        "by_stage": by_stage,
        "remaining_count": remaining_count,
        "oldest_queued_age_seconds": oldest_queued_age_seconds,
        "unresolved_stale_running_count": _normalize_non_negative_int((stale_running_row or {}).get("total")),
        "recent_failures": [
            {
                "last_error_code": str(row.get("last_error_code") or "").strip() or None,
                "last_error_class": str(row.get("last_error_class") or "").strip() or None,
                "total": _normalize_non_negative_int(row.get("total")),
            }
            for row in recent_failure_rows
        ],
        "stop_rule_failures": stop_rule_failures,
        "oldest_jobs": [
            {
                "id": str(row.get("id") or "").strip(),
                "run_id": str(row.get("run_id") or "").strip() or None,
                "status": str(row.get("status") or "").strip().lower() or "unknown",
                "stage": _normalize_social_job_stage_for_stale(row.get("stage")) or "unknown",
                "source_id": str(row.get("source_id") or "").strip() or None,
                "post_id": str(row.get("post_id") or "").strip() or None,
                "created_at": _iso(_coerce_dt(row.get("created_at"))),
                "available_at": _iso(_coerce_dt(row.get("available_at"))),
                "queued_age_seconds": _normalize_non_negative_int(row.get("queued_age_seconds")),
            }
            for row in oldest_rows
        ],
    }


def _list_candidate_media_mirror_jobs_for_account_dispatch(
    *,
    run_id: str,
    account_handle: str,
    stages: list[str],
    limit: int = 50,
) -> list[dict[str, Any]]:
    safe_limit = max(1, min(int(limit), 500))
    normalized_account = _normalize_media_mirror_drain_account(account_handle)
    stage_expr = _media_mirror_stage_sql("j")
    account_expr = _media_mirror_account_filter_sql("j")
    rows = pg.fetch_all(
        f"""
        select
          j.id::text as id,
          j.run_id::text as run_id,
          j.platform,
          j.job_type,
          j.status,
          j.priority,
          j.created_at,
          j.available_at,
          j.config,
          j.metadata
        from social.scrape_jobs j
        where j.platform = 'instagram'
          and j.run_id = %s::uuid
          and {account_expr} = %s::text
          and {stage_expr} = any(%s::text[])
          and j.status in ('queued', 'pending', 'retrying')
          and j.available_at <= now()
        order by coalesce(j.available_at, j.created_at) asc, j.priority asc, j.created_at asc
        limit %s
        """,
        [str(run_id), normalized_account, stages, safe_limit],
    )
    return [row for row in rows if _job_blocked_by_posts_auth_cooldown(row) is None]


def _dispatch_media_mirror_account_jobs(
    *,
    run_id: str,
    account_handle: str,
    stages: list[str],
    limit: int,
) -> dict[str, Any]:
    safe_limit = max(1, min(int(limit or _modal_dispatch_limit()), SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX))
    candidates = _list_candidate_media_mirror_jobs_for_account_dispatch(
        run_id=run_id,
        account_handle=account_handle,
        stages=stages,
        limit=max(safe_limit * 4, 50),
    )
    running_counts = cast(tuple[Any, ...], _current_modal_dispatch_running_counts())
    if len(running_counts) == 4:
        running_by_stage, running_by_stage_platform, running_by_run, running_by_run_stage_platform = running_counts
        active_accounts_by_stage_platform = {}
    else:
        (
            running_by_stage,
            running_by_stage_platform,
            running_by_run,
            running_by_run_stage_platform,
            active_accounts_by_stage_platform,
        ) = running_counts
    dispatched_job_ids: list[str] = []
    dispatch_attempts = 0
    for job in candidates:
        if len(dispatched_job_ids) >= safe_limit:
            break
        stage = _job_stage_from_row(job)
        if stage not in stages:
            continue
        platform = _normalize_platform_name(job.get("platform")) or "unknown"
        if platform != "instagram":
            continue
        job_config = _metadata_dict(job.get("config"))
        candidate_account = _resolve_dispatch_account_handle(job_config)
        if (
            _normalize_account_handle(candidate_account) or str(candidate_account or "").strip().lower().lstrip("@")
        ) != account_handle:
            continue
        if _job_required_lane_blocks_modal_dispatch(job_config, platform=platform):
            continue
        if _dispatch_request_is_fresh(job):
            continue
        capacity_stage = _modal_dispatch_capacity_stage(stage)
        sp_key = (capacity_stage, platform)
        if running_by_stage.get(capacity_stage, 0) >= _modal_dispatch_stage_global_cap(stage):
            continue
        effective_cap = _modal_dispatch_effective_platform_cap(
            stage,
            platform,
            active_account_count=max(1, len(active_accounts_by_stage_platform.get(sp_key, set()))),
            job_config=job_config,
        )
        if effective_cap is not None and running_by_stage_platform.get(sp_key, 0) >= effective_cap:
            continue
        job_id = str(job.get("id") or "").strip()
        if not job_id:
            continue
        job_dispatch = _job_dispatch_metadata(job)
        dispatch_attempt_count = _dispatch_metadata_attempt_count(job_dispatch) + 1
        lease_expires_at = _now_utc() + timedelta(
            seconds=_resolve_stale_seconds_for_job(platform=platform, stage=stage, has_queue_fields=True)
        )
        dispatch_attempts += 1
        _touch_job_dispatch_metadata(
            job_id,
            dispatch_backend="modal",
            dispatch_requested_at=_now_utc(),
            dispatch_attempt_count=dispatch_attempt_count,
            lease_expires_at=lease_expires_at,
            last_dispatch_error=None,
            last_dispatch_error_code=None,
            last_dispatch_error_at=None,
            remote_invocation_status=None,
            remote_invocation_checked_at=None,
            remote_task_id=None,
            remote_pending_since=None,
            remote_blocked_reason=None,
            dispatch_blocked_failure_count=0,
            dispatch_blocked_first_seen_at=None,
        )
        dispatch_result = dispatch_social_job(job_id=job_id, stage=stage)
        if not dispatch_result.get("dispatched"):
            continue
        _touch_job_dispatch_metadata(
            job_id,
            dispatch_backend="modal",
            dispatch_requested_at=_now_utc(),
            dispatch_attempt_count=dispatch_attempt_count,
            remote_invocation_id=str(dispatch_result.get("call_id") or "").strip() or None,
            remote_function_name=str(dispatch_result.get("function_name") or "").strip() or None,
            lease_expires_at=lease_expires_at,
            last_dispatch_error=None,
            last_dispatch_error_code=None,
            last_dispatch_error_at=None,
            remote_invocation_status="unknown",
            remote_invocation_checked_at=None,
            remote_task_id=None,
            remote_pending_since=None,
            remote_blocked_reason=None,
            dispatch_blocked_failure_count=0,
            dispatch_blocked_first_seen_at=None,
        )
        dispatched_job_ids.append(job_id)
        running_by_stage[capacity_stage] = running_by_stage.get(capacity_stage, 0) + 1
        running_by_stage_platform[sp_key] = running_by_stage_platform.get(sp_key, 0) + 1
        running_by_run[str(run_id)] = running_by_run.get(str(run_id), 0) + 1
        active_accounts_by_stage_platform.setdefault(sp_key, set()).add(account_handle)
    return {"dispatched_job_ids": dispatched_job_ids, "dispatch_attempts": dispatch_attempts}


def drain_media_mirror_account_jobs(
    *,
    run_id: str,
    account_handle: str,
    stage: str = INSTAGRAM_MEDIA_MIRROR_STAGE,
    stale_after_seconds: int = 900,
    recover_limit: int = 25,
    dispatch_limit: int = 8,
    dry_run: bool = False,
) -> dict[str, Any]:
    normalized_run_id = str(run_id or "").strip()
    normalized_account = _normalize_media_mirror_drain_account(account_handle)
    stages = _media_mirror_drain_stages(stage)
    before = get_media_mirror_account_drain_status(
        run_id=normalized_run_id,
        account_handle=normalized_account,
        stage=stage,
        stale_after_seconds=stale_after_seconds,
    )
    recovered_job_ids: list[str] = []
    recovered_by_stage: dict[str, list[str]] = {}
    if not dry_run:
        for stage_name in stages:
            recovered = recover_stale_running_jobs(
                run_id=normalized_run_id,
                stage=stage_name,
                platform="instagram",
                account_handle=normalized_account,
                stale_after_seconds=stale_after_seconds,
                limit=recover_limit,
            )
            stage_job_ids = [str(row.get("id") or "").strip() for row in recovered if str(row.get("id") or "").strip()]
            recovered_by_stage[stage_name] = stage_job_ids
            recovered_job_ids.extend(stage_job_ids)
    after_recovery = get_media_mirror_account_drain_status(
        run_id=normalized_run_id,
        account_handle=normalized_account,
        stage=stage,
        stale_after_seconds=stale_after_seconds,
    )
    stop_reason: str | None = None
    if dry_run:
        stop_reason = "dry_run"
    elif not is_queue_enabled():
        stop_reason = "queue_disabled"
    elif not is_modal_remote_executor_enabled():
        stop_reason = "remote_executor_not_modal"
    elif _run_pause_after_current_requested(normalized_run_id):
        stop_reason = "pause_after_current"
    elif after_recovery.get("unresolved_stale_running_count"):
        stop_reason = "unresolved_stale_running_jobs"
    elif after_recovery.get("stop_rule_failures"):
        stop_reason = "recent_stop_rule_failures"
    else:
        resolution = _modal_social_dispatch_resolution()
        if not bool(resolution.get("resolved")):
            stop_reason = str(resolution.get("reason") or "").strip() or "modal_dispatch_unavailable"
    dispatch = {"dispatched_job_ids": [], "dispatch_attempts": 0}
    if stop_reason is None:
        dispatch = _dispatch_media_mirror_account_jobs(
            run_id=normalized_run_id,
            account_handle=normalized_account,
            stages=stages,
            limit=dispatch_limit,
        )
    after = get_media_mirror_account_drain_status(
        run_id=normalized_run_id,
        account_handle=normalized_account,
        stage=stage,
        stale_after_seconds=stale_after_seconds,
    )
    dispatched_job_ids = [
        str(job_id).strip() for job_id in dispatch.get("dispatched_job_ids", []) if str(job_id).strip()
    ]
    if stop_reason is None and not dispatched_job_ids and after.get("remaining_count"):
        stop_reason = "no_dispatch_capacity"
    next_recommended_action = (
        "inspect_stop_reason"
        if stop_reason and stop_reason != "dry_run"
        else "run_bounded_batch"
        if dry_run and before.get("remaining_count")
        else "refresh_status"
    )
    if not stop_reason and after.get("remaining_count"):
        next_recommended_action = "run_next_batch"
    elif not stop_reason:
        next_recommended_action = "complete"
    return {
        "ok": stop_reason is None or stop_reason == "dry_run",
        "dry_run": bool(dry_run),
        "run_id": normalized_run_id,
        "account_handle": normalized_account,
        "stage": stage,
        "stages": stages,
        "before": before,
        "after": after,
        "after_recovery": after_recovery,
        "recovered_job_ids": recovered_job_ids,
        "recovered_by_stage": recovered_by_stage,
        "recovered_count": len(recovered_job_ids),
        "dispatched_job_ids": dispatched_job_ids,
        "dispatch_attempts": _normalize_non_negative_int(dispatch.get("dispatch_attempts")),
        "dispatch": dispatch,
        "stop_reason": stop_reason,
        "next_recommended_action": next_recommended_action,
    }


def _current_modal_dispatch_running_counts() -> tuple[
    dict[str, int],
    dict[tuple[str, str], int],
    dict[str, int],
    dict[tuple[str, str, str], int],
    dict[tuple[str, str], set[str]],
]:
    rows = pg.fetch_all(
        """
        select
          coalesce(run_id::text, '') as run_id,
          lower(coalesce(config->>'stage', metadata->>'stage', job_type, 'unknown')) as stage,
          lower(coalesce(platform, 'unknown')) as platform,
          coalesce(config->>'pipeline_ingest_mode', '') as pipeline_ingest_mode,
          lower(coalesce(
            nullif(trim(config->>'account'), ''),
            nullif(trim(config->>'account_handle'), ''),
            nullif(trim(config->>'source_account'), ''),
            nullif(trim(config->>'username'), ''),
            nullif(trim(config->>'shared_account_source_id'), ''),
            ''
          )) as account_handle,
          count(*)::int as total
        from social.scrape_jobs
        where status = 'running'
        group by 1, 2, 3, 4, 5
        """
    )
    by_stage: dict[str, int] = {}
    by_stage_platform: dict[tuple[str, str], int] = {}
    by_run: dict[str, int] = {}
    by_run_stage_platform: dict[tuple[str, str, str], int] = {}
    active_accounts_by_stage_platform: dict[tuple[str, str], set[str]] = {}
    for row in rows:
        stage = _modal_dispatch_capacity_stage(row.get("stage"))
        platform = _normalize_platform_name(row.get("platform")) or "unknown"
        run_id = str(row.get("run_id") or "").strip()
        ingest_mode = _resolve_pipeline_ingest_mode(row.get("pipeline_ingest_mode"))
        account = str(row.get("account_handle") or "").strip()
        total = int(row.get("total") or 0)
        by_stage[stage] = by_stage.get(stage, 0) + total
        by_stage_platform[(stage, platform)] = by_stage_platform.get((stage, platform), 0) + total
        if account:
            sp_key = (stage, platform)
            if sp_key not in active_accounts_by_stage_platform:
                active_accounts_by_stage_platform[sp_key] = set()
            active_accounts_by_stage_platform[sp_key].add(account)
        if run_id:
            by_run[run_id] = by_run.get(run_id, 0) + total
            if ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
                key = (run_id, stage, platform)
                by_run_stage_platform[key] = by_run_stage_platform.get(key, 0) + total
    return by_stage, by_stage_platform, by_run, by_run_stage_platform, active_accounts_by_stage_platform


def _run_pause_after_current_requested(run_id: str | None) -> bool:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id or not _relation_exists("social.scrape_runs"):
        return False
    try:
        row = pg.fetch_one(
            """
            select config
            from social.scrape_runs
            where id = %s
            """,
            [normalized_run_id],
        )
    except Exception:
        logger.debug("Failed to load scrape run pause state: run_id=%s", normalized_run_id, exc_info=True)
        return False
    config = _metadata_dict((row or {}).get("config"))
    dispatch_control = _metadata_dict(config.get("dispatch_control"))
    pause_requested = _metadata_value_truthy(config.get("pause_after_current")) or _metadata_value_truthy(
        dispatch_control.get("pause_after_current")
    )
    if not pause_requested:
        return False
    resume_after = _coerce_dt(dispatch_control.get("resume_after") or config.get("resume_after"))
    if resume_after is not None and resume_after <= _now_utc():
        _clear_expired_run_dispatch_pause(
            run_id=normalized_run_id,
            config=config,
            dispatch_control=dispatch_control,
            resume_after=resume_after,
        )
        return False
    return True


def _clear_expired_run_dispatch_pause(
    *,
    run_id: str,
    config: Mapping[str, Any],
    dispatch_control: Mapping[str, Any],
    resume_after: datetime,
) -> bool:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return False
    now_iso = _iso(_now_utc())
    resumed_control = {
        **_metadata_dict(dispatch_control),
        "pause_after_current": False,
        "resume_after": None,
        "auto_resumed_at": now_iso,
        "auto_resume_reason": "resume_after_elapsed",
        "expired_resume_after": _iso(resume_after),
    }
    config_updates = {
        "pause_after_current": False,
        "resume_after": None,
        "dispatch_control": resumed_control,
    }
    summary_updates = {
        "dispatch_control": resumed_control,
    }
    try:
        row = pg.fetch_one(
            """
            update social.scrape_runs
            set
              config = coalesce(config, '{}'::jsonb) || %s::jsonb,
              summary = coalesce(summary, '{}'::jsonb) || %s::jsonb
            where id = %s::uuid
            returning id::text as id
            """,
            [json.dumps(config_updates), json.dumps(summary_updates), normalized_run_id],
        )
        return bool(row)
    except Exception:
        logger.debug("Failed to clear expired dispatch pause: run_id=%s", normalized_run_id, exc_info=True)
        return False


def dispatch_due_social_jobs(*, run_id: str | None = None, limit: int | None = None) -> dict[str, Any]:
    safe_limit = max(1, min(int(limit or _modal_dispatch_limit()), SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX))
    if not is_queue_enabled():
        return {"dispatched_job_ids": [], "dispatch_attempts": 0, "reason": "queue_disabled"}
    if not is_modal_remote_executor_enabled():
        return {"dispatched_job_ids": [], "dispatch_attempts": 0, "reason": "remote_executor_not_modal"}
    if _run_pause_after_current_requested(run_id):
        _touch_modal_social_dispatcher_heartbeat(
            metadata_updates={
                "dispatch_enabled": True,
                "last_dispatch_blocked_reason": "pause_after_current",
                "last_dispatch_error": None,
                "last_dispatch_error_code": None,
            }
        )
        return {"dispatched_job_ids": [], "dispatch_attempts": 0, "reason": "pause_after_current"}
    recovered_capacity = (
        recover_failed_instagram_comments_capacity_jobs(run_id=run_id, limit=max(safe_limit, 25)) if run_id else []
    )
    recovered_blocked = recover_dispatch_blocked_no_progress_jobs(limit=max(safe_limit, 25))
    resolution = _modal_social_dispatch_resolution()
    ready = bool(resolution.get("resolved"))
    reason = str(resolution.get("reason") or "").strip() or None
    if not ready:
        _touch_modal_social_dispatcher_heartbeat(
            metadata_updates={
                "dispatch_enabled": False,
                "last_dispatch_error": reason,
                "last_dispatch_error_code": reason,
                "last_dispatch_blocked_reason": reason,
                "last_dispatch_error_at": _iso(_now_utc()),
            }
        )
        return {
            "dispatched_job_ids": [],
            "dispatch_attempts": 0,
            "reason": reason,
            "recovered_dispatch_blocked_job_ids": [
                str(row.get("id") or "").strip() for row in recovered_blocked if str(row.get("id") or "").strip()
            ],
            "recovered_capacity_job_ids": [
                str(row.get("id") or "").strip() for row in recovered_capacity if str(row.get("id") or "").strip()
            ],
        }

    recovered_unclaimed = recover_stale_unclaimed_dispatched_jobs(
        run_id=run_id,
        limit=max(safe_limit, 25),
    )

    candidates = _list_candidate_jobs_for_modal_dispatch(run_id=run_id, limit=max(safe_limit * 4, 50))
    running_counts = cast(tuple[Any, ...], _current_modal_dispatch_running_counts())
    if len(running_counts) == 4:
        (
            running_by_stage,
            running_by_stage_platform,
            running_by_run,
            running_by_run_stage_platform,
        ) = running_counts
        active_accounts_by_stage_platform = {}
    else:
        (
            running_by_stage,
            running_by_stage_platform,
            running_by_run,
            running_by_run_stage_platform,
            active_accounts_by_stage_platform,
        ) = running_counts
    priority_recovery_override_slots = _modal_comment_recovery_priority_override_slots()
    priority_recovery_running_count = (
        _current_modal_priority_comment_recovery_running_count() if priority_recovery_override_slots > 0 else 0
    )
    dispatched_job_ids: list[str] = []
    dispatch_attempts = 0

    for job in candidates:
        if len(dispatched_job_ids) >= safe_limit:
            break
        stage = _job_stage_from_row(job)
        capacity_stage = _modal_dispatch_capacity_stage(stage)
        platform = _normalize_platform_name(job.get("platform")) or "unknown"
        status = str(job.get("status") or "").strip().lower()
        job_run_id = str(job.get("run_id") or "").strip()
        if job_run_id and _run_pause_after_current_requested(job_run_id):
            continue
        job_config = _metadata_dict(job.get("config"))
        job_dispatch = _job_dispatch_metadata(job)
        job_ingest_mode = _resolve_pipeline_ingest_mode(job_config.get("pipeline_ingest_mode"))
        priority_recovery_job = _job_is_priority_comment_recovery(job, job_config, stage=stage)
        priority_recovery_override_allowed = (
            priority_recovery_job and priority_recovery_running_count < priority_recovery_override_slots
        )
        if _job_blocked_by_posts_auth_cooldown(job) is not None:
            continue
        if _job_required_lane_blocks_modal_dispatch(job_config, platform=platform):
            continue
        existing_remote_invocation_id = str(job_dispatch.get("remote_invocation_id") or "").strip()
        terminal_remote_invocation = False
        if existing_remote_invocation_id:
            refreshed_lease_expires_at = _now_utc() + timedelta(
                seconds=_resolve_stale_seconds_for_job(
                    platform=platform,
                    stage=stage,
                    has_queue_fields=True,
                )
            )
            inspection = _refresh_remote_modal_invocation_state(
                job,
                lease_expires_at=refreshed_lease_expires_at,
            )
            inspection_status = str(inspection.get("status") or "").strip().lower()
            if _modal_invocation_is_nonterminal(inspection_status):
                if (
                    inspection_status == "pending"
                    and status in {"queued", "pending", "retrying"}
                    and _modal_pending_capacity_invocation_is_stale(job_dispatch, inspection)
                ):
                    job_id_for_clear = str(job.get("id") or "").strip()
                    if not job_id_for_clear:
                        continue
                    job_dispatch = _clear_stale_pending_modal_dispatch(job_id_for_clear, job_dispatch)
                    existing_remote_invocation_id = ""
                else:
                    if priority_recovery_job:
                        priority_recovery_running_count += 1
                    running_by_stage[capacity_stage] = running_by_stage.get(capacity_stage, 0) + 1
                    running_by_stage_platform[(capacity_stage, platform)] = (
                        running_by_stage_platform.get((capacity_stage, platform), 0) + 1
                    )
                    nonterminal_account = _resolve_dispatch_account_handle(job_config)
                    if nonterminal_account:
                        active_accounts_by_stage_platform.setdefault((capacity_stage, platform), set()).add(
                            nonterminal_account
                        )
                    if job_run_id:
                        running_by_run[job_run_id] = running_by_run.get(job_run_id, 0) + 1
                        if job_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
                            key = (job_run_id, capacity_stage, platform)
                            running_by_run_stage_platform[key] = running_by_run_stage_platform.get(key, 0) + 1
                    continue
            if existing_remote_invocation_id and inspection_status == "unknown":
                job_id_for_clear = str(job.get("id") or "").strip()
                if status in {"queued", "pending", "retrying"} and job_id_for_clear:
                    _touch_job_dispatch_metadata(
                        job_id_for_clear,
                        dispatch_backend=str(job_dispatch.get("dispatch_backend") or "modal"),
                        dispatch_requested_at=_coerce_dt(job_dispatch.get("dispatch_requested_at")),
                        dispatch_attempt_count=_dispatch_metadata_attempt_count(job_dispatch),
                        remote_invocation_id=None,
                        lease_expires_at=None,
                        remote_invocation_status="unknown",
                        remote_invocation_checked_at=_now_utc(),
                        remote_task_id=None,
                        remote_pending_since=None,
                        remote_blocked_reason=None,
                    )
                    job_dispatch = {
                        **job_dispatch,
                        "remote_invocation_id": None,
                        "lease_expires_at": None,
                        "remote_invocation_status": "unknown",
                    }
                else:
                    continue
            elif existing_remote_invocation_id:
                terminal_remote_invocation = True
                job_dispatch = {
                    **job_dispatch,
                    "remote_invocation_status": inspection_status,
                    "remote_invocation_checked_at": inspection.get("checked_at"),
                    "remote_blocked_reason": str(inspection.get("reason") or "").strip() or None,
                }
        if not terminal_remote_invocation and _dispatch_request_is_fresh(job):
            continue
        if (
            running_by_stage.get(capacity_stage, 0) >= _modal_dispatch_stage_global_cap(stage)
            and not priority_recovery_override_allowed
        ):
            continue
        # Compute prospective account count: existing active accounts + this candidate
        candidate_account = _resolve_dispatch_account_handle(job_config)
        sp_key = (capacity_stage, platform)
        existing_accounts = active_accounts_by_stage_platform.get(sp_key, set())
        if (
            candidate_account
            and capacity_stage in {SHARED_ACCOUNT_DISCOVERY_STAGE, SHARED_ACCOUNT_POSTS_STAGE}
            and candidate_account in existing_accounts
            and not _job_allows_parallel_same_account_dispatch(job_config)
        ):
            continue
        prospective_accounts = existing_accounts | {candidate_account} if candidate_account else existing_accounts
        effective_cap = _modal_dispatch_effective_platform_cap(
            stage,
            platform,
            active_account_count=len(prospective_accounts) if prospective_accounts else 1,
            job_config=job_config,
        )
        if (
            effective_cap is not None
            and running_by_stage_platform.get(sp_key, 0) >= effective_cap
            and not priority_recovery_override_allowed
        ):
            continue
        if job_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE and job_run_id:
            if running_by_run.get(job_run_id, 0) >= _resolve_catalog_run_in_flight_cap():
                continue
            if capacity_stage == SHARED_ACCOUNT_POSTS_STAGE:
                platform_run_cap = _modal_dispatch_effective_platform_cap(
                    stage,
                    platform,
                    active_account_count=1,
                    job_config=job_config,
                )
                if (
                    platform_run_cap is not None
                    and running_by_run_stage_platform.get((job_run_id, capacity_stage, platform), 0) >= platform_run_cap
                ):
                    continue

        job_id = str(job.get("id") or "").strip()
        if not job_id:
            continue
        dispatch_attempts += 1
        dispatch_attempt_count = _dispatch_metadata_attempt_count(job_dispatch) + 1
        blocked_failure_count = _dispatch_metadata_blocked_failure_count(job_dispatch)
        blocked_first_seen_at = _coerce_dt(job_dispatch.get("dispatch_blocked_first_seen_at"))
        lease_expires_at = _now_utc() + timedelta(
            seconds=_resolve_stale_seconds_for_job(
                platform=platform,
                stage=stage,
                has_queue_fields=True,
            )
        )
        _touch_job_dispatch_metadata(
            job_id,
            dispatch_backend="modal",
            dispatch_requested_at=_now_utc(),
            dispatch_attempt_count=dispatch_attempt_count,
            lease_expires_at=lease_expires_at,
            last_dispatch_error=None,
            last_dispatch_error_code=None,
            last_dispatch_error_at=None,
            remote_invocation_status=None,
            remote_invocation_checked_at=None,
            remote_task_id=None,
            remote_pending_since=None,
            remote_blocked_reason=None,
            dispatch_blocked_failure_count=0,
            dispatch_blocked_first_seen_at=None,
        )
        dispatch_kwargs: dict[str, Any] = {"job_id": job_id, "stage": stage}
        if priority_recovery_override_allowed:
            dispatch_kwargs["priority_recovery"] = True
        dispatch_result = dispatch_social_job(**dispatch_kwargs)
        if dispatch_result.get("dispatched"):
            _touch_job_dispatch_metadata(
                job_id,
                dispatch_backend="modal",
                dispatch_requested_at=_now_utc(),
                dispatch_attempt_count=dispatch_attempt_count,
                remote_invocation_id=str(dispatch_result.get("call_id") or "").strip() or None,
                remote_function_name=str(dispatch_result.get("function_name") or "").strip() or None,
                lease_expires_at=lease_expires_at,
                last_dispatch_error=None,
                last_dispatch_error_code=None,
                last_dispatch_error_at=None,
                remote_invocation_status="unknown",
                remote_invocation_checked_at=None,
                remote_task_id=None,
                remote_pending_since=None,
                remote_blocked_reason=None,
                dispatch_blocked_failure_count=0,
                dispatch_blocked_first_seen_at=None,
            )
            dispatched_job_ids.append(job_id)
            running_by_stage[capacity_stage] = running_by_stage.get(capacity_stage, 0) + 1
            running_by_stage_platform[(capacity_stage, platform)] = (
                running_by_stage_platform.get((capacity_stage, platform), 0) + 1
            )
            if candidate_account:
                active_accounts_by_stage_platform.setdefault((capacity_stage, platform), set()).add(candidate_account)
            if job_run_id:
                running_by_run[job_run_id] = running_by_run.get(job_run_id, 0) + 1
                if job_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
                    key = (job_run_id, capacity_stage, platform)
                    running_by_run_stage_platform[key] = running_by_run_stage_platform.get(key, 0) + 1
            if priority_recovery_override_allowed:
                priority_recovery_running_count += 1
        else:
            dispatch_reason = str(dispatch_result.get("reason") or "dispatch_failed")
            dispatch_reason_code = str(dispatch_result.get("reason_code") or "").strip().lower() or (
                _normalize_dispatch_blocked_reason(
                    last_dispatch_error_code="modal_dispatch_failed",
                    last_dispatch_error=dispatch_reason,
                )
            )
            blocked_failure_count = max(1, blocked_failure_count + 1)
            blocked_first_seen_at = blocked_first_seen_at or _now_utc()
            blocked_for_seconds = max(0, int((_now_utc() - blocked_first_seen_at).total_seconds()))
            _touch_job_dispatch_metadata(
                job_id,
                dispatch_backend="modal",
                dispatch_requested_at=_now_utc(),
                dispatch_attempt_count=dispatch_attempt_count,
                lease_expires_at=None,
                last_dispatch_error=dispatch_reason,
                last_dispatch_error_code="modal_dispatch_failed",
                last_dispatch_error_at=_now_utc(),
                remote_invocation_status="unknown",
                remote_invocation_checked_at=_now_utc(),
                remote_task_id=None,
                remote_pending_since=None,
                remote_blocked_reason=dispatch_reason_code,
                dispatch_blocked_failure_count=blocked_failure_count,
                dispatch_blocked_first_seen_at=blocked_first_seen_at,
            )
            if (
                blocked_failure_count >= _resolve_modal_dispatch_blocked_failure_limit()
                or blocked_for_seconds >= _resolve_modal_dispatch_no_progress_seconds()
            ):
                _finish_job(
                    job_id,
                    status="failed",
                    items_found=_normalize_non_negative_int(job.get("items_found")),
                    error_message=dispatch_reason,
                    metadata={
                        "dispatch": {
                            **job_dispatch,
                            "dispatch_backend": "modal",
                            "dispatch_requested_at": _iso(_now_utc()),
                            "dispatch_attempt_count": dispatch_attempt_count,
                            "last_dispatch_error": dispatch_reason,
                            "last_dispatch_error_code": "modal_dispatch_failed",
                            "last_dispatch_error_at": _iso(_now_utc()),
                            "remote_invocation_status": "failed",
                            "remote_invocation_checked_at": _iso(_now_utc()),
                            "remote_blocked_reason": dispatch_reason_code,
                            "dispatch_blocked_failure_count": blocked_failure_count,
                            "dispatch_blocked_first_seen_at": _iso(blocked_first_seen_at),
                            "dispatch_blocked_terminalized_at": _iso(_now_utc()),
                        }
                    },
                    last_error_code="modal_dispatch_blocked",
                    last_error_class="ModalDispatchBlocked",
                )
                if job_run_id:
                    _finalize_run_status(job_run_id, force_recompute=True)

    heartbeat_updates: dict[str, Any] = {
        "dispatch_enabled": True,
        "active_invocations": sum(running_by_stage.values()),
    }
    if dispatched_job_ids:
        heartbeat_updates.update(
            {
                "last_dispatch_success_at": _iso(_now_utc()),
                "last_dispatch_error": None,
                "last_dispatch_error_code": None,
                "last_dispatch_blocked_reason": None,
            }
        )
    _touch_modal_social_dispatcher_heartbeat(metadata_updates=heartbeat_updates)
    return {
        "dispatched_job_ids": dispatched_job_ids,
        "dispatch_attempts": dispatch_attempts,
        "recovered_unclaimed_job_ids": [
            str(row.get("id") or "").strip() for row in recovered_unclaimed if str(row.get("id") or "").strip()
        ],
        "recovered_dispatch_blocked_job_ids": [
            str(row.get("id") or "").strip() for row in recovered_blocked if str(row.get("id") or "").strip()
        ],
        "recovered_capacity_job_ids": [
            str(row.get("id") or "").strip() for row in recovered_capacity if str(row.get("id") or "").strip()
        ],
        "reason": None,
    }


def _dispatch_due_social_jobs_in_background(*, run_id: str) -> None:
    normalized_run_id = str(run_id or "").strip()
    if not normalized_run_id:
        return

    def _runner() -> None:
        try:
            dispatch_due_social_jobs(run_id=normalized_run_id)
        except Exception:  # noqa: BLE001
            logger.exception("[modal-dispatch] background dispatch failed run_id=%s", normalized_run_id)

    Thread(
        target=_runner,
        name=f"dispatch-social-jobs:{normalized_run_id[:24]}",
        daemon=True,
    ).start()


def claim_and_process_social_job(*, job_id: str, worker_id: str) -> dict[str, Any]:
    claimed = _claim_job_by_id(job_id=job_id, worker_id=worker_id)
    if not claimed:
        return {
            "job_id": job_id,
            "claimed": False,
            "job": _load_current_job_row(job_id),
        }
    run_id = str(claimed.get("run_id") or "").strip() or None
    if run_id:
        _set_run_status(run_id, "running")
    _mark_claimed_modal_dispatch_running(claimed)
    result = process_claimed_job(claimed, worker_id=worker_id)
    dispatch_due_social_jobs(run_id=run_id, limit=1)
    return {
        "job_id": job_id,
        "claimed": True,
        "job": result,
    }


def recover_and_dispatch_due_social_jobs(*, limit: int | None = None) -> dict[str, Any]:
    recovered = recover_stale_running_jobs(limit=max(1, min(int(limit or _modal_dispatch_limit()), 250)))
    recovered_unclaimed = recover_stale_unclaimed_dispatched_jobs(
        limit=max(1, min(int(limit or _modal_dispatch_limit()), 250))
    )
    dispatch_summary = dispatch_due_social_jobs(limit=limit)
    return {
        "recovered_jobs": [str(row.get("id") or "").strip() for row in recovered],
        "recovered_unclaimed_jobs": [
            str(row.get("id") or "").strip() for row in recovered_unclaimed if str(row.get("id") or "").strip()
        ],
        **dispatch_summary,
    }


def _claim_next_jobs(
    *,
    worker_id: str | None = None,
    run_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
    limit: int = 1,
) -> list[dict[str, Any]]:
    if not worker_id:
        logger.warning("_claim_next_jobs called without worker_id; capability filter requires worker registration")
        return []
    safe_limit = max(1, min(int(limit), SOCIAL_JOB_CLAIM_BATCH_SIZE_MAX))
    run_in_flight_cap = _resolve_run_in_flight_cap()
    youtube_run_in_flight_cap = _resolve_youtube_run_in_flight_cap()
    stale_after_seconds = _resolve_positive_int_env(
        "SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS",
        SOCIAL_WORKER_HEARTBEAT_STALE_SECONDS_DEFAULT,
        minimum=5,
    )
    authoritative_modal_runtime = _resolve_authoritative_catalog_runtime_version(required_execution_backend="modal")
    authoritative_modal_backend = _runtime_version_backend(authoritative_modal_runtime)
    authoritative_modal_image = str(authoritative_modal_runtime.get("modal_image") or "").strip() or None
    authoritative_modal_commit = str(authoritative_modal_runtime.get("commit_sha") or "").strip() or None
    authoritative_modal_label = _runtime_version_label(authoritative_modal_runtime)
    media_runtime_json, comment_media_runtime_json = _claimed_media_runtime_versions()
    catalog_supported_platforms = sorted(set(CATALOG_SUPPORTED_PLATFORMS))
    modal_required_sql = """
              (
                lower(coalesce(j.config->>'required_execution_backend', '')) = 'modal'
                or (
                  lower(coalesce(j.config->>'pipeline_ingest_mode', '')) = 'shared_account_catalog_backfill'
                  and j.platform = any(%s::text[])
                  and lower(coalesce(j.config->>'allow_local_dev_inline_bypass', 'false'))
                    not in ('true', '1', 'yes', 'on')
                )
              )
    """
    return pg.fetch_all(
        f"""
        with worker_caps as (
          select
            coalesce(
              supported_platforms,
              array['instagram', 'tiktok', 'twitter', 'youtube', 'facebook', 'threads']
            ) as platforms,
            nullif(lower(coalesce(metadata->>'worker_lane', '')), '') as worker_lane,
            coalesce((metadata->'auth_capabilities'->>'instagram_authenticated')::boolean, false)
              as instagram_authenticated,
            coalesce(
              nullif(lower(coalesce(metadata->>'execution_backend_canonical', '')), ''),
              case
                when lower(coalesce(worker_id, '')) like 'modal:%%' then 'modal'
                else 'local'
              end
            ) as execution_backend_canonical
          from social.scrape_workers
          where worker_id = %s
        ),
        stale_worker_window as (
          select make_interval(secs => %s) as max_staleness
        ),
        healthy_instagram_auth_workers as (
          select count(*)::int as healthy_auth_workers
          from social.scrape_workers
          where last_seen_at >= now() - (select max_staleness from stale_worker_window)
            and status in ('starting', 'idle', 'working')
            and 'instagram' = any(
              coalesce(
                supported_platforms,
                array['instagram', 'tiktok', 'twitter', 'youtube', 'facebook', 'threads']
              )
            )
            and coalesce((metadata->'auth_capabilities'->>'instagram_authenticated')::boolean, false)
        ),
        run_in_flight as (
          select run_id::text as run_id, count(*)::int as in_flight
          from social.scrape_jobs
          where status = 'running'
            and run_id is not null
          group by run_id
        ),
        run_platform_in_flight as (
          select run_id::text as run_id, platform, count(*)::int as in_flight
          from social.scrape_jobs
          where status = 'running'
            and run_id is not null
          group by run_id, platform
        ),
        eligible as (
          select
            j.id,
            j.priority,
            j.created_at,
            row_number() over (
              partition by coalesce(j.run_id::text, j.id::text)
              order by j.priority asc, j.created_at asc
            ) as run_rank,
            coalesce(rif.in_flight, 0)::int as in_flight,
            coalesce(rpif.in_flight, 0)::int as platform_in_flight
          from social.scrape_jobs j
          left join run_in_flight rif on rif.run_id = j.run_id::text
          left join run_platform_in_flight rpif
            on rpif.run_id = j.run_id::text
           and rpif.platform = j.platform
          where j.status in ('queued', 'pending', 'retrying')
            and j.available_at <= now()
            and {_job_posts_auth_cooldown_sql_exclusion("j")}
            and (%s::uuid is null or j.run_id = %s::uuid)
            and (
              %s::text is null
              or coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s::text
            )
            and (%s::text is null or j.platform = %s::text)
            and exists (
              select 1
              from worker_caps wc
              where j.platform = any(wc.platforms)
            )
            and (
              nullif(lower(coalesce(j.config->>'required_worker_lane', '')), '') is null
              or exists (
                select 1
                from worker_caps wc
                where wc.worker_lane = nullif(lower(coalesce(j.config->>'required_worker_lane', '')), '')
              )
            )
            and (
              not {modal_required_sql}
              or exists (
                select 1
                from worker_caps wc
                where wc.execution_backend_canonical = 'modal'
              )
            )
            and (
              not {modal_required_sql}
              or (
                nullif(j.config->'required_runtime_version'->>'modal_image', '') is null
                and nullif(j.config->'required_runtime_version'->>'commit_sha', '') is null
                and nullif(j.config->'required_runtime_version'->>'label', '') is null
                and nullif(lower(coalesce(j.config->'required_runtime_version'->>'execution_backend', '')), '') is null
              )
              or (
                %s::text is not null
                and (
                  (
                    nullif(j.config->'required_runtime_version'->>'modal_image', '') is not null
                    and j.config->'required_runtime_version'->>'modal_image' = %s::text
                  )
                  or (
                    nullif(j.config->'required_runtime_version'->>'modal_image', '') is null
                    and nullif(j.config->'required_runtime_version'->>'commit_sha', '') is not null
                    and j.config->'required_runtime_version'->>'commit_sha' = %s::text
                  )
                  or (
                    nullif(j.config->'required_runtime_version'->>'modal_image', '') is null
                    and nullif(j.config->'required_runtime_version'->>'commit_sha', '') is null
                    and nullif(j.config->'required_runtime_version'->>'label', '') is not null
                    and (
                      j.config->'required_runtime_version'->>'label' = %s::text
                      or (
                        lower(j.config->'required_runtime_version'->>'label') in ('modal', 'local')
                        and lower(j.config->'required_runtime_version'->>'label') = %s::text
                      )
                    )
                  )
                  or (
                    nullif(j.config->'required_runtime_version'->>'modal_image', '') is null
                    and nullif(j.config->'required_runtime_version'->>'commit_sha', '') is null
                    and nullif(j.config->'required_runtime_version'->>'label', '') is null
                    and lower(coalesce(j.config->'required_runtime_version'->>'execution_backend', '')) = %s::text
                  )
                )
              )
            )
            and (
              j.platform <> 'instagram'
              or exists (
                select 1
                from worker_caps wc
                where wc.instagram_authenticated
              )
              or (select hiw.healthy_auth_workers from healthy_instagram_auth_workers hiw) = 0
            )
            and (
              j.worker_id is null
              or j.worker_id = %s::text
              or (j.worker_id is not null and %s::text is not null and %s::text like j.worker_id || '%%')
              or exists (
                select 1
                from social.scrape_workers owning_worker
                where owning_worker.worker_id = j.worker_id
                  and (
                    owning_worker.status = 'stopped'
                    or owning_worker.last_seen_at < now() - (select max_staleness from stale_worker_window)
                  )
              )
              or not exists (
                select 1
                from social.scrape_workers owning_worker
                where owning_worker.worker_id = j.worker_id
              )
            )
            and (
              j.platform <> 'youtube'
              or j.run_id is null
              or coalesce(rpif.in_flight, 0) < %s
              or not exists (
                select 1
                from social.scrape_jobs other
                where other.status in ('queued', 'pending', 'retrying')
                  and other.available_at <= now()
                  and other.run_id = j.run_id
                  and other.platform <> 'youtube'
              )
            )
            and (j.run_id is null or coalesce(rif.in_flight, 0) < %s)
        ),
        candidate as (
          select id
          from eligible
          order by run_rank asc, priority asc, created_at asc
          limit %s
        )
        update social.scrape_jobs as j
        set
          status = 'running',
          started_at = coalesce(j.started_at, now()),
          claimed_at = now(),
          heartbeat_at = now(),
          worker_id = coalesce(%s, j.worker_id),
          attempt_count = j.attempt_count + 1,
          error_message = null,
          last_error_code = null,
          last_error_class = null,
          config = case
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'media_mirror'
              then coalesce(j.config, '{{}}'::jsonb) || jsonb_build_object(
                'required_runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'comment_media_mirror'
              then coalesce(j.config, '{{}}'::jsonb) || jsonb_build_object(
                'required_runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            else j.config
          end,
          metadata = case
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'media_mirror'
              then coalesce(j.metadata, '{{}}'::jsonb) || jsonb_build_object(
                'runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            when coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = 'comment_media_mirror'
              then coalesce(j.metadata, '{{}}'::jsonb) || jsonb_build_object(
                'runtime_version', %s::jsonb,
                'claimed_runtime_version', %s::jsonb,
                'claimed_runtime_refreshed_at', now()
              )
            else j.metadata
          end
        from candidate
        where j.id = candidate.id
          and j.status in ('queued', 'pending', 'retrying')
        returning
          j.id::text,
          j.run_id::text as run_id,
          j.platform,
          j.job_type,
          j.status,
          j.config,
          j.metadata,
          j.attempt_count,
          j.max_attempts,
          j.source_scope,
          j.season_id::text as season_id,
          j.last_error_code
        """,
        [
            worker_id,
            stale_after_seconds,
            run_id,
            run_id,
            stage,
            stage,
            platform,
            platform,
            catalog_supported_platforms,
            catalog_supported_platforms,
            authoritative_modal_backend,
            authoritative_modal_image,
            authoritative_modal_commit,
            authoritative_modal_label,
            authoritative_modal_backend,
            authoritative_modal_backend,
            worker_id,
            worker_id,
            worker_id,
            youtube_run_in_flight_cap,
            run_in_flight_cap,
            safe_limit,
            worker_id,
            media_runtime_json,
            media_runtime_json,
            comment_media_runtime_json,
            comment_media_runtime_json,
            media_runtime_json,
            media_runtime_json,
            comment_media_runtime_json,
            comment_media_runtime_json,
        ],
    )


def _claim_next_job(
    *,
    worker_id: str | None = None,
    run_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any] | None:
    claimed = _claim_next_jobs(worker_id=worker_id, run_id=run_id, stage=stage, platform=platform, limit=1)
    return claimed[0] if claimed else None


def _execute_claimed_job(job: dict[str, Any], *, worker_id: str | None = None) -> dict[str, Any]:
    job_id = str(job.get("id") or "")
    run_id = str(job.get("run_id") or "")
    platform = _normalize_platform_name(job.get("platform"))
    config: dict[str, Any] = {}
    stage = str((job.get("metadata") or {}).get("stage") or "posts")
    account = ""
    crawlee_active_execution = False
    crawlee_fallback_to_legacy = False
    auth_preflight: AuthPreflightResult | None = None

    try:
        config = dict(job.get("config") or {})
        config["_attempt_count"] = max(1, int(job.get("attempt_count") or 1))
        config["_max_attempts"] = max(1, int(job.get("max_attempts") or 1))
        config["_last_error_code"] = str(job.get("last_error_code") or "").strip().lower() or None
        stage = str(config.get("stage") or ((job.get("metadata") or {}).get("stage")) or "posts")
        from trr_backend.socials.pipelines.job_handlers import resolve_platform_job_handler

        platform_handler = resolve_platform_job_handler(platform, stage)
        if platform_handler is not None:
            return platform_handler.execute(job, worker_id=worker_id)
        if stage in {
            SHARED_ACCOUNT_DISCOVERY_STAGE,
            SHARED_ACCOUNT_POSTS_STAGE,
            INSTAGRAM_PROFILE_SNAPSHOT_STAGE,
            INSTAGRAM_PROFILE_FOLLOWING_STAGE,
            POST_CLASSIFY_STAGE,
            SEASON_MATERIALIZE_STAGE,
            ANALYTICS_REFRESH_STAGE,
        }:
            return _execute_shared_claimed_job(job, worker_id=worker_id)
        season_id = str(config.get("season_id") or job.get("season_id") or "").strip()
        if stage in {INSTAGRAM_MEDIA_MIRROR_STAGE, COMMENT_MEDIA_MIRROR_STAGE}:
            context = _resolve_media_mirror_stage_context(
                platform,
                stage=stage,
                config=config,
            )
        else:
            context = get_season_context(season_id)
        if platform not in SUPPORTED_PLATFORMS:
            logger.warning(
                "Worker %s does not support platform %s; releasing job %s back to queue",
                worker_id,
                platform,
                job_id,
            )
            _finish_job(
                job_id,
                status="retrying",
                items_found=0,
                error_message=f"Platform {platform} ingest is not supported by this worker",
                last_error_code="platform_not_supported",
                last_error_class="WorkerCapabilityMismatch",
                next_available_at=_now_utc(),
            )
            # Undo the attempt_count bump since this isn't a real attempt failure
            pg.execute(
                "UPDATE social.scrape_jobs SET attempt_count = greatest(0, attempt_count - 1) WHERE id = %s",
                [job_id],
            )
            return (
                pg.fetch_one(
                    (
                        "SELECT id::text, run_id::text as run_id, platform, job_type, "
                        "status, items_found, error_message, metadata "
                        "FROM social.scrape_jobs WHERE id = %s"
                    ),
                    [job_id],
                )
                or {}
            )
        sync_strategy = str(config.get("sync_strategy") or "incremental").strip().lower()
        if sync_strategy not in SUPPORTED_SYNC_STRATEGIES:
            sync_strategy = "incremental"
        raw_max_posts = config.get("max_posts_per_target")
        raw_max_comments = config.get("max_comments_per_post")
        raw_max_replies = config.get("max_replies_per_post")
        raw_mode = str(config.get("ingest_mode") or "posts_and_comments")
        raw_comment_refresh_policy = config.get("comment_refresh_policy")
        raw_comment_anchor_source_ids = config.get("comment_anchor_source_ids")
        raw_sound_ids = config.get("sound_ids")
        raw_fetch_replies = bool(config.get("fetch_replies", True))
        normalized_max_posts = None if raw_max_posts is None else max(0, int(raw_max_posts))
        normalized_max_comments = None if raw_max_comments is None else max(0, int(raw_max_comments))
        normalized_max_replies = None if raw_max_replies is None else max(0, int(raw_max_replies))
        resolved_posts, resolved_comments, resolved_replies, resolved_fetch_replies = _resolve_depth_defaults(
            max_posts_per_target=normalized_max_posts,
            max_comments_per_post=normalized_max_comments,
            max_replies_per_post=normalized_max_replies,
            fetch_replies=raw_fetch_replies,
        )
        normalized_mode = (raw_mode or "posts_and_comments").strip().lower()
        if normalized_mode in {"posts_only", "details_refresh"}:
            resolved_comments = 0
            resolved_replies = 0
            resolved_fetch_replies = False
        elif normalized_mode == "comments_only":
            resolved_posts = 0
        normalized_comment_refresh_policy = _normalize_comment_refresh_policy(raw_comment_refresh_policy)
        normalized_comment_anchor_source_ids: dict[str, set[str]] = {}
        if isinstance(raw_comment_anchor_source_ids, list):
            normalized_source_ids = {
                str(item or "").strip() for item in raw_comment_anchor_source_ids if str(item or "").strip()
            }
            if len(normalized_source_ids) <= MAX_COMMENT_ANCHOR_SOURCE_IDS_PER_PLATFORM:
                normalized_comment_anchor_source_ids[platform] = normalized_source_ids
        elif isinstance(raw_comment_anchor_source_ids, dict):
            normalized_comment_anchor_source_ids, _ = _normalize_comment_anchor_source_ids(
                raw_comment_anchor_source_ids,
                allowed_platforms={platform},
            )
        normalized_sound_ids = _normalize_tiktok_sound_ids(raw_sound_ids)
        opts = IngestOptions(
            platforms=None,
            source_scope=str(config.get("source_scope") or job.get("source_scope") or "network"),
            sync_strategy=sync_strategy,
            max_posts_per_target=resolved_posts,
            max_comments_per_post=resolved_comments,
            max_replies_per_post=resolved_replies,
            fetch_replies=resolved_fetch_replies,
            ingest_mode=normalized_mode,
            date_start=_coerce_dt(config.get("date_start")),
            date_end=_coerce_dt(config.get("date_end")),
            comment_refresh_policy=normalized_comment_refresh_policy,
            comment_anchor_source_ids=normalized_comment_anchor_source_ids or None,
            sound_ids=normalized_sound_ids or None,
            comments_enable_media_followups=bool(config.get("comments_enable_media_followups")),
            details_refresh_skip_detail_fetch=bool(config.get("details_refresh_skip_detail_fetch")),
            details_refresh_force_detail_fetch=bool(config.get("details_refresh_force_detail_fetch")),
            details_refresh_skip_media_followups=bool(config.get("details_refresh_skip_media_followups")),
        )
        account = str(config.get("account") or "")
        hashtags = [str(item).strip().lstrip("#") for item in (config.get("hashtags") or []) if str(item).strip()]
        keywords = [str(item).strip() for item in (config.get("keywords") or []) if str(item).strip()]
        use_crawlee = (
            should_use_crawlee(platform) and stage in {"posts", "comments"} and normalized_mode != "details_refresh"
        )
        if platform == "instagram" and _instagram_public_first_scrape_mode_enabled(config):
            use_crawlee = False
        runtime_config = build_runtime_config(platform)
        cancelled_result = _abort_claimed_job_if_cancelled(
            job_id=job_id,
            run_id=run_id,
            stage=stage,
            platform=platform,
            account=account,
        )
        if cancelled_result is not None:
            return cancelled_result
        _touch_job_heartbeat(job_id, worker_id=worker_id)
        if use_crawlee:
            twitter_cookies: dict[str, str] | None = None
            twitter_bearer: str | None = None
            if platform == "twitter":
                twitter_cookies, twitter_bearer = _load_twitter_auth()
            auth_preflight = check_platform_auth(
                platform=platform,
                instagram_cookies=_load_instagram_cookies() if platform == "instagram" else None,
                tiktok_cookies=_load_tiktok_cookies() if platform == "tiktok" else None,
                facebook_cookies=_load_facebook_cookies() if platform == "facebook" else None,
                threads_cookies=_load_threads_cookies() if platform == "threads" else None,
                twitter_cookies=twitter_cookies,
                twitter_bearer=twitter_bearer,
                twikit_credentials=_load_twikit_credentials() if platform == "twitter" else None,
            )
            if not auth_preflight.ok:
                strict_auth = runtime_config.auth_strict or is_auth_strict_for_platform(platform)
                if platform == "instagram" and not strict_auth:
                    crawlee_fallback_to_legacy = True
                    posts_count, comments_count, retrieval_meta = _run_platform_stage(
                        context=context,
                        run_id=run_id or None,
                        platform=platform,
                        stage=stage,
                        account=account,
                        hashtags=hashtags,
                        keywords=keywords,
                        opts=opts,
                        job_id=job_id,
                        config=config,
                    )
                    retrieval_meta = dict(retrieval_meta or {})
                    retrieval_meta["crawler_runtime"] = {
                        "engine": "legacy_fallback_after_auth_preflight",
                        "platform": platform,
                        "stage": stage,
                        "request_mode": normalized_mode,
                        "crawlee_available": True,
                        "max_concurrency": runtime_config.max_concurrency,
                        "max_retries": runtime_config.max_retries,
                        "requests_total": 0,
                        "requests_handled": 0,
                        "retries_total": 0,
                        "blocked_events": 0,
                        "session_rotations": 0,
                        "max_proxy_tier_used": 0,
                        "crawlee_request_count": 0,
                        "crawlee_retry_count": 0,
                        "crawlee_session_pool_used": False,
                    }
                    retrieval_meta["auth_context"] = build_auth_context(
                        auth_preflight,
                        fallback_to_legacy=True,
                    )
                else:
                    raise AuthPreflightError(auth_preflight)
            else:
                crawlee_active_execution = True
                posts_count, comments_count, retrieval_meta = _run_platform_stage_via_crawlee(
                    context=context,
                    run_id=run_id or None,
                    platform=platform,
                    stage=stage,
                    account=account,
                    hashtags=hashtags,
                    keywords=keywords,
                    opts=opts,
                    job_id=job_id,
                    config=config,
                    runtime_config=runtime_config,
                    auth_preflight=auth_preflight,
                )
        else:
            posts_count, comments_count, retrieval_meta = _run_platform_stage(
                context=context,
                run_id=run_id or None,
                platform=platform,
                stage=stage,
                account=account,
                hashtags=hashtags,
                keywords=keywords,
                opts=opts,
                job_id=job_id,
                config=config,
            )
        persist_counters = {
            "posts_upserted": _normalize_non_negative_int(
                (retrieval_meta.get("persist_counters") or {}).get("posts_upserted")
            ),
            "comments_upserted": _normalize_non_negative_int(
                (retrieval_meta.get("persist_counters") or {}).get("comments_upserted")
            ),
        }
        activity = dict(retrieval_meta.get("activity") or {})
        if not activity:
            activity = {"phase": f"{stage}_end", "last_progress_at": _iso(_now_utc())}
        fetch_counters = _comment_stats_payload(dict(retrieval_meta.get("comment_stats") or {}))
        crawler_runtime = dict(retrieval_meta.get("crawler_runtime") or {})
        auth_context = dict(retrieval_meta.get("auth_context") or {})
        source_runtime = dict(retrieval_meta.get("source_runtime") or {})
        base_metadata = {
            "stage": stage,
            "stage_counters": {"posts": posts_count, "comments": comments_count},
            "persist_counters": persist_counters,
            "activity": activity,
            "fetch_counters": fetch_counters,
            "platform": platform,
            "account": account,
            "crawler_runtime": crawler_runtime,
            "auth_context": auth_context,
            "source_runtime": source_runtime,
            "retrieval_meta": retrieval_meta,
        }
        run_is_cancelled = False
        if run_id:
            run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
            run_is_cancelled = str(run_state.get("status") or "") == "cancelled"
        if run_is_cancelled:
            _finish_job(
                job_id,
                status="cancelled",
                items_found=posts_count + comments_count,
                metadata=base_metadata,
            )
            return (
                pg.fetch_one(
                    """
                select
                  id::text,
                  run_id::text as run_id,
                  platform,
                  job_type,
                  status,
                  items_found,
                  error_message,
                  metadata
                from social.scrape_jobs
                where id = %s
                """,
                    [job_id],
                )
                or {}
            )
        _finish_job(
            job_id,
            status="completed",
            items_found=posts_count + comments_count,
            metadata=base_metadata,
        )
    except Exception as exc:  # noqa: BLE001
        run_is_cancelled = False
        if run_id:
            run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
            run_is_cancelled = str(run_state.get("status") or "") == "cancelled"
        if run_is_cancelled:
            _finish_job(
                job_id,
                status="cancelled",
                items_found=0,
                error_message="Cancelled by user request",
                metadata={
                    "stage": stage,
                    "platform": platform,
                    "account": account,
                },
            )
            if run_id:
                _finalize_run_status(run_id)
            return (
                pg.fetch_one(
                    """
                select
                  id::text,
                  run_id::text as run_id,
                  platform,
                  job_type,
                  status,
                  items_found,
                  error_message,
                  metadata
                from social.scrape_jobs
                where id = %s
                """,
                    [job_id],
                )
                or {}
            )
        runtime_error_code = str(getattr(exc, "error_code", "") or "").strip().lower()
        runtime_error_class = str(getattr(exc, "error_class", "") or "").strip()
        runtime_retryable = getattr(exc, "retryable", None)
        runtime_metadata = getattr(exc, "runtime_metadata", None)
        if runtime_error_code:
            error_code = runtime_error_code
            error_class = runtime_error_class or exc.__class__.__name__
            transient = (
                bool(runtime_retryable)
                if runtime_retryable is not None
                else error_code
                in {
                    "blocked",
                    "rate_limited",
                    "network",
                }
            )
        elif crawlee_active_execution:
            error_code, error_class, transient = classify_exception(exc)
        else:
            error_code, error_class, transient = _classify_job_error(exc)
        attempt_count = int(job.get("attempt_count") or 1)
        max_attempts = int(job.get("max_attempts") or 1)
        can_retry = transient and attempt_count < max_attempts
        next_available_at = _now_utc() + timedelta(seconds=_retry_backoff_seconds(attempt_count)) if can_retry else None
        existing_job = (
            pg.fetch_one(
                "select items_found, metadata from social.scrape_jobs where id = %s",
                [job_id],
            )
            or {}
        )
        existing_metadata = dict(existing_job.get("metadata") or {})
        existing_activity = dict(existing_metadata.get("activity") or {})
        existing_activity["phase"] = "failed"
        existing_activity["last_progress_at"] = _iso(_now_utc())
        existing_metadata.update(
            {
                "stage": stage,
                "platform": platform,
                "account": account,
                "error": str(exc),
                "error_code": error_code,
                "error_class": error_class,
                "job_error_code": _normalize_job_error_code(
                    raw_error_code=error_code,
                    error_message=str(exc),
                    error_class=error_class,
                ),
                "failure_reason_code": error_code,
                "retryable": can_retry,
                "activity": existing_activity,
            }
        )
        if isinstance(runtime_metadata, dict):
            if isinstance(runtime_metadata.get("crawler_runtime"), dict):
                existing_metadata["crawler_runtime"] = runtime_metadata["crawler_runtime"]
            if isinstance(runtime_metadata.get("auth_context"), dict):
                existing_metadata["auth_context"] = runtime_metadata["auth_context"]
        elif auth_preflight is not None:
            existing_metadata["auth_context"] = build_auth_context(
                auth_preflight,
                fallback_to_legacy=crawlee_fallback_to_legacy,
            )
        if can_retry:
            next_available_at = _defer_retry_until_posts_auth_cooldown(
                platform=platform,
                stage=stage,
                job_type=job.get("job_type"),
                account_handle=account,
                next_available_at=next_available_at,
                metadata=existing_metadata,
            )
        _finish_job(
            job_id,
            status="retrying" if can_retry else "failed",
            items_found=_normalize_non_negative_int(existing_job.get("items_found")),
            error_message=str(exc),
            metadata=existing_metadata,
            last_error_code=error_code,
            last_error_class=error_class,
            next_available_at=next_available_at,
        )
        logger.exception("Social ingest job failed: job_id=%s stage=%s platform=%s", job_id, stage, platform)
    finally:
        if run_id:
            _finalize_run_status(run_id)

    return (
        pg.fetch_one(
            """
        select
          id::text,
          run_id::text as run_id,
          platform,
          job_type,
          status,
          items_found,
          error_message,
          metadata
        from social.scrape_jobs
        where id = %s
        """,
            [job_id],
        )
        or {}
    )


def _fetch_next_preclaimed_job(
    *,
    worker_id: str,
    run_id: str,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any] | None:
    """Fetch the next pre-claimed running job owned by this worker (no status change needed)."""
    return pg.fetch_one(
        f"""
        select
          id::text,
          run_id::text as run_id,
          platform,
          job_type,
          status,
          config,
          metadata,
          attempt_count,
          max_attempts,
          source_scope,
          season_id::text as season_id
        from social.scrape_jobs j
        where status = 'running'
          and {_job_posts_auth_cooldown_sql_exclusion("j")}
          and run_id = %s::uuid
          and (
            worker_id = %s
            or (%s::text is not null and %s::text like worker_id || '%%')
          )
          and (
            %s::text is null
            or coalesce(config->>'stage', metadata->>'stage', job_type) = %s::text
          )
          and (%s::text is null or platform = %s::text)
        order by priority asc, created_at asc
        limit 1
        """,
        [run_id, worker_id, worker_id, worker_id, stage, stage, platform, platform],
    )


def _stage_claim_candidates(stage: str | None) -> tuple[str | None, ...]:
    normalized = str(stage or "").strip().lower() if stage is not None else None
    if normalized == SHARED_ACCOUNT_POSTS_STAGE:
        return (
            SHARED_ACCOUNT_POSTS_STAGE,
            TIKTOK_POSTS_SCRAPLING_STAGE,
            THREADS_POSTS_SCRAPLING_STAGE,
        )
    return (stage,)


def _resolve_youtube_narrow_window_page_cap(
    *,
    date_start: datetime | None,
    date_end: datetime | None,
) -> int | None:
    span_days = _window_span_days(date_start=date_start, date_end=date_end)
    if span_days is None or span_days > 45:
        return None
    default_cap = 4 if span_days <= 14 else 6
    return _resolve_positive_int_env(
        "SOCIAL_YOUTUBE_NARROW_WINDOW_MAX_PAGES",
        default_cap,
        minimum=1,
    )


def execute_run(
    run_id: str,
    *,
    worker_id: str | None = None,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any]:
    platform = _normalize_platform_name(platform) or None
    _set_run_status(run_id, "running")
    claim_stage_candidates = _stage_claim_candidates(stage)
    claim_batch_sizes = {
        claim_stage: _resolve_job_claim_batch_size(stage=claim_stage) for claim_stage in claim_stage_candidates
    }
    claim_batch_size = max(claim_batch_sizes.values(), default=_resolve_job_claim_batch_size(stage=stage))
    max_jobs = _resolve_positive_int_env("SOCIAL_EXECUTE_RUN_MAX_JOBS", 1000, minimum=1)
    max_runtime_seconds = _resolve_positive_int_env("SOCIAL_EXECUTE_RUN_MAX_RUNTIME_SECONDS", 3600, minimum=60)
    run_deadline = _now_utc() + timedelta(seconds=max_runtime_seconds)
    processed_jobs = 0
    guardrail_metadata: dict[str, Any] | None = None
    claimed_jobs: list[dict[str, Any]] = []
    while True:
        if processed_jobs >= max_jobs:
            guardrail_metadata = {
                "reason": "max_jobs",
                "processed_jobs": processed_jobs,
                "max_jobs": max_jobs,
            }
            logger.warning(
                "Stopping social execute_run for run_id=%s after max_jobs=%s",
                run_id,
                max_jobs,
            )
            break
        if _now_utc() >= run_deadline:
            guardrail_metadata = {
                "reason": "max_runtime_seconds",
                "processed_jobs": processed_jobs,
                "max_runtime_seconds": max_runtime_seconds,
            }
            logger.warning(
                "Stopping social execute_run for run_id=%s after max_runtime_seconds=%s",
                run_id,
                max_runtime_seconds,
            )
            break
        if not claimed_jobs:
            for claim_stage in claim_stage_candidates:
                claimed_jobs = _claim_next_jobs(
                    worker_id=worker_id,
                    run_id=run_id,
                    stage=claim_stage,
                    platform=platform,
                    limit=min(claim_batch_size, claim_batch_sizes.get(claim_stage) or claim_batch_size),
                )
                if claimed_jobs:
                    break
        job = claimed_jobs.pop(0) if claimed_jobs else None
        if not job and worker_id:
            for claim_stage in claim_stage_candidates:
                job = _fetch_next_preclaimed_job(
                    worker_id=worker_id,
                    run_id=run_id,
                    stage=claim_stage,
                    platform=platform,
                )
                if job:
                    break
        if not job:
            break
        run_state = pg.fetch_one("select status from social.scrape_runs where id = %s", [run_id]) or {}
        if str(run_state.get("status")) == "cancelled":
            _finish_job(str(job.get("id")), status="cancelled", items_found=0, metadata={"stage": "cancelled"})
            processed_jobs += 1
            continue
        _execute_claimed_job(job, worker_id=worker_id)
        processed_jobs += 1

    if guardrail_metadata:
        logger.warning("social execute_run guardrail triggered: %s", guardrail_metadata)
    _finalize_run_status(run_id)
    return (
        pg.fetch_one(
            """
        select
          id::text,
          season_id::text as season_id,
          show_id::text as show_id,
          source_scope,
          status,
          config,
          summary,
          created_at,
          started_at,
          completed_at,
          cancelled_at
        from social.scrape_runs
        where id = %s
        """,
            [run_id],
        )
        or {}
    )


def process_next_queued_job(
    *,
    worker_id: str,
    stage: str | None = None,
    platform: str | None = None,
) -> dict[str, Any] | None:
    platform = _normalize_platform_name(platform) or None
    job = _claim_next_job(worker_id=worker_id, run_id=None, stage=stage, platform=platform)
    if not job:
        return None
    return _execute_claimed_job(job, worker_id=worker_id)


def claim_next_queued_jobs(
    *,
    worker_id: str,
    stage: str | None = None,
    platform: str | None = None,
    run_id: str | None = None,
    limit: int | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_platform_name(platform) or None
    safe_limit = _resolve_job_claim_batch_size(limit, stage=stage)
    claimed_jobs = _claim_next_jobs(
        worker_id=worker_id,
        run_id=run_id,
        stage=stage,
        platform=normalized_platform,
        limit=safe_limit,
    )
    for claimed_run_id in sorted(
        {str(job.get("run_id") or "").strip() for job in claimed_jobs if str(job.get("run_id") or "").strip()}
    ):
        _set_run_status(claimed_run_id, "running")
    return claimed_jobs


def process_claimed_job(job: dict[str, Any], *, worker_id: str | None = None) -> dict[str, Any]:
    return _execute_claimed_job(job, worker_id=worker_id)


def ingest_season(
    season_id: str,
    *,
    platforms: list[str] | None,
    accounts_override: list[str] | None = None,
    hashtags_override: list[str] | None = None,
    keywords_override: list[str] | None = None,
    source_scope: str,
    sync_strategy: str = "incremental",
    max_posts_per_target: int | None,
    max_comments_per_post: int | None,
    max_replies_per_post: int | None = 100,
    fetch_replies: bool,
    ingest_mode: str = "posts_and_comments",
    date_start: datetime | None,
    date_end: datetime | None,
    comment_refresh_policy: str = DEFAULT_COMMENT_REFRESH_POLICY,
    comment_anchor_source_ids: dict[str, list[str]] | None = None,
    sound_ids: list[str] | None = None,
    runner_strategy: str | None = None,
    runner_count: int | None = None,
    window_shard_hours: int | None = None,
    runner_b_start_offset_hours: int | None = None,
    day_weight_profile: str | None = None,
    priority_mode: str | None = None,
    youtube_source_mode: str | None = None,
    youtube_force_reindex: bool = False,
    youtube_force_media_refresh: bool = False,
    youtube_force_comment_refresh: bool = False,
    week_index: int | None = None,
    window_timezone: str | None = None,
    run_scope_label: str | None = None,
    client_session_id: str | None = None,
    client_workflow_id: str | None = None,
    orchestration_metadata: Mapping[str, Any] | None = None,
    initiated_by: str | None,
    inline_worker_id: str | None = None,
) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    context = get_season_context(season_id)
    source_scope = normalize_source_scope(source_scope)

    normalized_mode = (ingest_mode or "posts_and_comments").strip().lower()
    if normalized_mode not in SUPPORTED_INGEST_MODES:
        raise ValueError(f"Unsupported ingest mode: {ingest_mode}")
    normalized_sync_strategy = (sync_strategy or "incremental").strip().lower()
    if normalized_sync_strategy not in SUPPORTED_SYNC_STRATEGIES:
        raise ValueError(f"Unsupported sync strategy: {sync_strategy}")
    normalized_comment_refresh_policy = (comment_refresh_policy or DEFAULT_COMMENT_REFRESH_POLICY).strip().lower()
    if normalized_comment_refresh_policy not in SUPPORTED_COMMENT_REFRESH_POLICIES:
        raise ValueError(f"Unsupported comment refresh policy: {comment_refresh_policy}")
    normalized_youtube_source_mode = _normalize_youtube_source_mode(youtube_source_mode)

    platform_filter = set(_resolve_requested_platforms(platforms)) if platforms is not None else set()
    normalized_comment_anchor_source_ids, overflow_platforms = _normalize_comment_anchor_source_ids(
        comment_anchor_source_ids,
        allowed_platforms=(platform_filter or None),
    )

    normalized_hashtags_override = _normalize_terms(hashtags_override, strip_prefix="#")
    normalized_keywords_override = _normalize_terms(keywords_override)
    normalized_sound_ids = _normalize_tiktok_sound_ids(sound_ids or [])
    normalized_accounts_override: list[str] = []
    invalid_overrides: list[str] = []
    for raw_account in [str(item or "").strip() for item in (accounts_override or []) if str(item or "").strip()]:
        normalized = _normalize_account_handle(raw_account)
        if not normalized:
            invalid_overrides.append(raw_account)
            continue
        if normalized in normalized_accounts_override:
            continue
        normalized_accounts_override.append(normalized)
    if invalid_overrides:
        raise SocialIngestValidationError(
            "INVALID_ACCOUNT_HANDLE",
            f"Invalid account handle override(s): {', '.join(sorted(set(invalid_overrides)))}",
        )

    resolved_posts, resolved_comments, resolved_replies, resolved_fetch_replies = _resolve_depth_defaults(
        max_posts_per_target=max_posts_per_target,
        max_comments_per_post=max_comments_per_post,
        max_replies_per_post=max_replies_per_post,
        fetch_replies=fetch_replies,
    )
    if normalized_mode in {"posts_only", "details_refresh"}:
        resolved_comments = 0
        resolved_replies = 0
        resolved_fetch_replies = False
    elif normalized_mode == "comments_only":
        # Comments-only runs should not cap anchor iteration by default.
        resolved_posts = 0

    stage_plan = (
        ["posts"]
        if normalized_mode in {"posts_only", "details_refresh"}
        else ["comments"]
        if normalized_mode == "comments_only"
        else ["posts", "comments"]
    )

    opts = IngestOptions(
        platforms=platform_filter or None,
        source_scope=source_scope,
        sync_strategy=normalized_sync_strategy,
        max_posts_per_target=resolved_posts,
        max_comments_per_post=resolved_comments,
        max_replies_per_post=resolved_replies,
        fetch_replies=resolved_fetch_replies,
        ingest_mode=normalized_mode,
        date_start=date_start,
        date_end=date_end,
        comment_refresh_policy=normalized_comment_refresh_policy,
        comment_anchor_source_ids=normalized_comment_anchor_source_ids or None,
        sound_ids=normalized_sound_ids or None,
        youtube_source_mode=normalized_youtube_source_mode,
        youtube_force_reindex=bool(youtube_force_reindex),
        youtube_force_media_refresh=bool(youtube_force_media_refresh),
        youtube_force_comment_refresh=bool(youtube_force_comment_refresh),
    )
    targets_payload = get_targets(season_id, source_scope=source_scope)
    targets_by_platform: dict[str, dict[str, list[str]]] = {}
    configured_target_platforms: set[str] = set()
    for target in targets_payload.get("targets", []):
        if not target.get("is_active", True):
            continue
        target_platform = _normalize_platform_name(target.get("platform"))
        if target_platform not in SUPPORTED_PLATFORMS:
            logger.warning(
                "Skipping ingest target with unsupported platform token: %s (season=%s source_scope=%s)",
                target.get("platform"),
                context.season_id,
                source_scope,
            )
            continue
        if platform_filter and target_platform not in platform_filter:
            continue
        configured_target_platforms.add(target_platform)
        bucket = targets_by_platform.setdefault(target_platform, {"accounts": [], "hashtags": [], "keywords": []})
        bucket["accounts"].extend(
            [str(item or "").strip() for item in (target.get("accounts") or []) if str(item or "").strip()]
        )
        bucket["hashtags"].extend(
            [str(item or "").strip() for item in (target.get("hashtags") or []) if str(item or "").strip()]
        )
        bucket["keywords"].extend(
            [str(item or "").strip() for item in (target.get("keywords") or []) if str(item or "").strip()]
        )

    for platform_name in sorted(platform_filter):
        targets_by_platform.setdefault(platform_name, {"accounts": [], "hashtags": [], "keywords": []})

    fallback_hashtags, fallback_keywords = _derive_show_terms(context.show_name)
    include_default_hashtags = len(normalized_hashtags_override) == 0
    include_default_keywords = len(normalized_keywords_override) == 0
    effective_targets: list[dict[str, Any]] = []
    invalid_target_accounts: list[str] = []
    for platform, values in sorted(targets_by_platform.items()):
        authoritative_override = _use_authoritative_account_override(
            context=context,
            source_scope=source_scope,
            platform=platform,
            normalized_accounts_override=normalized_accounts_override,
        )
        raw_accounts = [*(values.get("accounts") or []), *normalized_accounts_override]
        normalized_accounts: list[str] = []
        seen_accounts: set[str] = set()
        for raw_account in raw_accounts:
            normalized_account = _normalize_account_handle(raw_account)
            if not normalized_account:
                if str(raw_account or "").strip():
                    invalid_target_accounts.append(f"{platform}:{raw_account}")
                continue
            if platform == "instagram" and not _is_valid_instagram_account_handle(normalized_account):
                invalid_target_accounts.append(f"{platform}:{raw_account}")
                continue
            if normalized_account in seen_accounts:
                continue
            seen_accounts.add(normalized_account)
            normalized_accounts.append(normalized_account)

        hashtags = _normalize_unique_terms(
            [
                *_normalize_terms(values.get("hashtags"), strip_prefix="#"),
                *normalized_hashtags_override,
                *(fallback_hashtags if include_default_hashtags else []),
            ]
        )
        keywords = _normalize_unique_terms(
            [
                *_normalize_terms(values.get("keywords")),
                *normalized_keywords_override,
                *(fallback_keywords if include_default_keywords else []),
            ]
        )
        if not authoritative_override:
            if platform == "instagram":
                normalized_accounts = _ensure_rhoslc_instagram_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_instagram_hashtags(context, hashtags)
            elif platform == "twitter":
                normalized_accounts = _ensure_rhoslc_twitter_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_twitter_hashtags(context, hashtags)
            normalized_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=normalized_accounts,
            )
            if not normalized_accounts and platform in platform_filter and platform in configured_target_platforms:
                default_accounts = _default_platform_accounts(platform)
                if default_accounts:
                    logger.info(
                        "No %s accounts configured for season=%s; using default accounts: %s",
                        platform,
                        context.season_id,
                        default_accounts,
                    )
                    normalized_accounts = default_accounts
            if platform == "instagram":
                normalized_accounts = _ensure_rhoslc_instagram_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_instagram_hashtags(context, hashtags)
            elif platform == "twitter":
                normalized_accounts = _ensure_rhoslc_twitter_accounts(context, normalized_accounts)
                hashtags = _ensure_rhoslc_twitter_hashtags(context, hashtags)
            normalized_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=normalized_accounts,
            )
        if normalized_accounts:
            effective_targets.append(
                {
                    "platform": platform,
                    "accounts": normalized_accounts,
                    "hashtags": hashtags,
                    "keywords": keywords,
                }
            )

    if invalid_target_accounts:
        raise SocialIngestValidationError(
            "INVALID_ACCOUNT_HANDLE",
            f"Invalid account handle(s): {', '.join(sorted(set(invalid_target_accounts)))}",
        )
    if not effective_targets:
        raise SocialIngestValidationError(
            "NO_INGEST_TARGETS",
            "No executable ingest targets after applying active targets and overrides",
        )

    target_account_count = sum(
        len([str(item).strip() for item in (target.get("accounts") or []) if str(item).strip()])
        for target in effective_targets
    )
    resolved_runner_strategy, resolved_runner_count, resolved_window_shard_hours = _coerce_targeted_window_schedule(
        platforms=opts.platforms,
        account_count=target_account_count,
        ingest_mode=opts.ingest_mode,
        date_start=opts.date_start,
        date_end=opts.date_end,
        runner_strategy=runner_strategy,
        runner_count=runner_count,
        window_shard_hours=window_shard_hours,
    )
    schedule = _build_ingest_shard_schedule(
        date_start=opts.date_start,
        date_end=opts.date_end,
        runner_strategy=resolved_runner_strategy,
        runner_count=resolved_runner_count,
        window_shard_hours=resolved_window_shard_hours,
        runner_b_start_offset_hours=runner_b_start_offset_hours,
        day_weight_profile=day_weight_profile,
        priority_mode=priority_mode,
    )

    execution_metadata = _configured_execution_metadata()
    run_config = {
        "pipeline_ingest_mode": LEGACY_SEASON_TARGETED_INGEST_MODE,
        "season_id": context.season_id,
        "show_id": context.show_id,
        "source_scope": source_scope,
        "run_scope": _ingest_run_scope_type(
            week_index=week_index,
            date_start=opts.date_start,
            date_end=opts.date_end,
        ),
        "window_label": str(run_scope_label or "").strip() or None,
        "week_index": int(week_index) if week_index is not None else None,
        "window_timezone": str(window_timezone or "America/New_York").strip() or "America/New_York",
        "platforms": sorted(platform_filter) if platform_filter else "all",
        "accounts_override": normalized_accounts_override,
        "hashtags_override": normalized_hashtags_override,
        "keywords_override": normalized_keywords_override,
        "date_start": _iso(opts.date_start),
        "date_end": _iso(opts.date_end),
        "sync_strategy": opts.sync_strategy,
        "max_posts_per_target": opts.max_posts_per_target,
        "max_comments_per_post": opts.max_comments_per_post,
        "max_replies_per_post": opts.max_replies_per_post,
        "fetch_replies": opts.fetch_replies,
        "ingest_mode": opts.ingest_mode,
        "comment_refresh_policy": opts.comment_refresh_policy,
        "comment_anchor_source_ids": _serialize_comment_anchor_source_ids(opts.comment_anchor_source_ids),
        "comment_anchor_source_ids_overflow_platforms": sorted(overflow_platforms),
        "sound_ids": list(opts.sound_ids or []),
        "runner_strategy": schedule.strategy,
        "runner_count": schedule.runner_count,
        "window_shard_hours": schedule.window_shard_hours,
        "runner_b_start_offset_hours": schedule.runner_b_offset_hours,
        "day_weight_profile": schedule.day_weight_profile,
        "priority_mode": schedule.priority_mode,
        "youtube_source_mode": opts.youtube_source_mode,
        "youtube_force_reindex": opts.youtube_force_reindex,
        "youtube_force_media_refresh": opts.youtube_force_media_refresh,
        "youtube_force_comment_refresh": opts.youtube_force_comment_refresh,
        "client_session_id": str(client_session_id or "").strip() or None,
        "client_workflow_id": str(client_workflow_id or "").strip() or None,
        **execution_metadata,
    }
    if orchestration_metadata:
        run_config.update({str(key): value for key, value in orchestration_metadata.items()})
    run_id = _create_run(
        context,
        source_scope=source_scope,
        initiated_by=initiated_by,
        config=run_config,
        status="queued",
    )

    queue_enabled = is_queue_enabled()
    initial_job_status = "queued" if queue_enabled else "pending"
    job_ids: list[str] = []
    skipped_comment_jobs = 0
    created_total_jobs = 0
    created_completed_jobs = 0
    created_failed_jobs = 0
    created_active_jobs = 0
    created_items_found_total = 0
    created_stage_counts: dict[str, dict[str, int]] = {}
    posts_shards = list(schedule.shards)
    if normalized_mode != "comments_only" and not posts_shards:
        fallback_start = _coerce_dt(opts.date_start)
        fallback_end = _coerce_dt(opts.date_end)
        if fallback_start and fallback_end and fallback_end < fallback_start:
            fallback_end = fallback_start
        if fallback_start is None:
            fallback_start = _now_utc()
        if fallback_end is None or fallback_end < fallback_start:
            fallback_end = fallback_start
        posts_shards = [
            IngestTimeShard(
                shard_index=0,
                window_start=fallback_start,
                window_end=fallback_end,
                runner_lane="A",
                priority_score=0.0,
                day_offset=0,
                day_weight=1.0,
            )
        ]
    shard_priority_by_index: dict[int, int] = {}
    for rank, shard in enumerate(
        sorted(posts_shards, key=lambda candidate: (candidate.priority_score, candidate.shard_index))
    ):
        shard_priority_by_index[shard.shard_index] = 100 + rank
    runner_b_available_at: datetime | None = None
    if schedule.run_start is not None and schedule.runner_b_offset_hours > 0 and schedule.runner_count > 1:
        runner_b_available_at = schedule.run_start + timedelta(hours=schedule.runner_b_offset_hours)

    comment_lane_index = 0
    with nullcontext(None) as enqueue_conn:
        for target in effective_targets:
            platform = str(target.get("platform") or "")
            target_posts_shards = _build_platform_posts_shards(
                platform=platform,
                schedule=schedule,
                date_start=opts.date_start,
                date_end=opts.date_end,
            )
            if normalized_mode != "comments_only" and not target_posts_shards:
                target_posts_shards = list(posts_shards)
            target_shard_priority_by_index: dict[int, int] = {}
            for rank, shard in enumerate(
                sorted(target_posts_shards, key=lambda candidate: (candidate.priority_score, candidate.shard_index))
            ):
                target_shard_priority_by_index[shard.shard_index] = 100 + rank
            ordered_target_posts_shards = sorted(
                target_posts_shards,
                key=lambda candidate: (candidate.priority_score, candidate.shard_index),
            )
            accounts = [str(item).strip() for item in (target.get("accounts") or []) if str(item).strip()]
            hashtags = _normalize_unique_terms(
                [str(item).strip().lstrip("#") for item in (target.get("hashtags") or []) if str(item).strip()]
            )
            keywords = _normalize_unique_terms(
                [str(item).strip() for item in (target.get("keywords") or []) if str(item).strip()]
            )
            platform_source_ids = normalized_comment_anchor_source_ids.get(platform)
            platform_has_explicit_targets = platform in normalized_comment_anchor_source_ids
            platform_source_ids_list = sorted(platform_source_ids) if platform_source_ids is not None else None
            account_specs: list[dict[str, Any]] = []
            for account in accounts:
                base_config = {
                    "run_id": run_id,
                    "season_id": context.season_id,
                    "show_id": context.show_id,
                    "platform": platform,
                    "source_scope": source_scope,
                    "run_scope": run_config["run_scope"],
                    "window_label": run_config["window_label"],
                    "week_index": run_config["week_index"],
                    "window_timezone": run_config["window_timezone"],
                    "account": account,
                    "hashtags": hashtags,
                    "keywords": keywords,
                    "date_start": _iso(opts.date_start),
                    "date_end": _iso(opts.date_end),
                    "sync_strategy": opts.sync_strategy,
                    "max_posts_per_target": opts.max_posts_per_target,
                    "max_comments_per_post": opts.max_comments_per_post,
                    "max_replies_per_post": opts.max_replies_per_post,
                    "fetch_replies": opts.fetch_replies,
                    "ingest_mode": opts.ingest_mode,
                    "comment_refresh_policy": opts.comment_refresh_policy,
                    "sound_ids": list(opts.sound_ids or []),
                    "runner_strategy": schedule.strategy,
                    "runner_count": schedule.runner_count,
                    "window_shard_hours": schedule.window_shard_hours,
                    "runner_b_start_offset_hours": schedule.runner_b_offset_hours,
                    "day_weight_profile": schedule.day_weight_profile,
                    "priority_mode": schedule.priority_mode,
                    "youtube_source_mode": opts.youtube_source_mode,
                    "youtube_force_reindex": opts.youtube_force_reindex,
                    "youtube_force_media_refresh": opts.youtube_force_media_refresh,
                    "youtube_force_comment_refresh": opts.youtube_force_comment_refresh,
                    "client_session_id": str(client_session_id or "").strip() or None,
                    "client_workflow_id": str(client_workflow_id or "").strip() or None,
                    **execution_metadata,
                }
                if orchestration_metadata:
                    base_config.update({str(key): value for key, value in orchestration_metadata.items()})
                if platform_has_explicit_targets:
                    base_config["comment_anchor_source_ids"] = platform_source_ids_list
                comment_job_specs: list[dict[str, Any]] = []
                if normalized_mode in {"posts_and_comments", "comments_only"} and opts.max_comments_per_post > 0:
                    if (
                        normalized_mode == "comments_only"
                        and opts.comment_refresh_policy == "missing_only"
                        and platform_has_explicit_targets
                        and not platform_source_ids_list
                    ):
                        skipped_comment_jobs += 1
                        continue

                    # --- Comment job splitting: divide posts across N parallel jobs ---
                    comment_split_count = _resolve_positive_int_env(
                        "SOCIAL_COMMENT_JOB_SPLIT_COUNT",
                        3,
                        minimum=1,
                    )
                    comment_split_min_posts = comment_split_count * 2  # need at least 2 posts per bucket

                    # Only split if no explicit anchor targets and platform is supported
                    split_buckets: list[list[str]] | None = None
                    if (
                        not platform_has_explicit_targets
                        and comment_split_count > 1
                        and platform in {"instagram", "tiktok", "youtube", "twitter", "facebook", "threads"}
                    ):
                        source_id_col_map = {
                            "instagram": "shortcode",
                            "tiktok": "video_id",
                            "youtube": "video_id",
                            "twitter": "tweet_id",
                            "facebook": "post_id",
                            "threads": "post_id",
                        }
                        ts_col_map = {
                            "instagram": "posted_at",
                            "tiktok": "posted_at",
                            "youtube": "published_at",
                            "twitter": "created_at",
                            "facebook": "posted_at",
                            "threads": "posted_at",
                        }
                        table_map_split = {
                            "instagram": "instagram_posts",
                            "tiktok": "tiktok_posts",
                            "youtube": "youtube_videos",
                            "twitter": "twitter_tweets",
                            "facebook": "facebook_posts",
                            "threads": "meta_threads_posts",
                        }
                        sid_col = source_id_col_map[platform]
                        ts_col = ts_col_map[platform]
                        tbl = table_map_split[platform]
                        acct_expr = "ltrim(lower(coalesce(nullif(source_account, ''), nullif(username, ''), '')), '@')"
                        if platform == "youtube":
                            acct_expr = (
                                "ltrim(lower(coalesce(nullif(source_account, ''), nullif(channel_title, ''), '')), '@')"
                            )
                        norm_acct = _normalize_account_handle(account)
                        split_conditions = [
                            "season_id = %s",
                            f"{acct_expr} = %s",
                        ]
                        split_params: list[Any] = [context.season_id, norm_acct]
                        if opts.date_start:
                            split_conditions.append(f"{ts_col} >= %s")
                            split_params.append(opts.date_start)
                        if opts.date_end:
                            split_conditions.append(f"{ts_col} <= %s")
                            split_params.append(opts.date_end)
                        if platform == "twitter":
                            split_conditions.append("coalesce(is_reply, false) = false")
                            split_conditions.append("coalesce(is_quote, false) = false")
                        split_where = " AND ".join(split_conditions)
                        split_sql = (
                            f"SELECT {sid_col} AS source_id, coalesce(comments_count, 0) AS comments_count"
                            f" FROM social.{tbl}"
                            f" WHERE {split_where}"
                            f" ORDER BY coalesce(comments_count, 0) DESC, {sid_col} ASC"
                        )
                        try:
                            split_rows = pg.fetch_all(split_sql, split_params)
                        except Exception:
                            logger.debug(
                                "Comment split query failed for %s/%s, falling back to single job",
                                platform,
                                account,
                                exc_info=True,
                            )
                            split_rows = []

                        if len(split_rows) >= comment_split_min_posts:
                            split_buckets = [[] for _ in range(comment_split_count)]
                            for idx, row in enumerate(split_rows):
                                split_buckets[idx % comment_split_count].append(str(row.get("source_id") or ""))
                            # Remove any empty buckets
                            split_buckets = [b for b in split_buckets if b]

                    if split_buckets and len(split_buckets) > 1:
                        for bucket_idx, bucket_source_ids in enumerate(split_buckets):
                            comment_job_specs.append(
                                {
                                    "config": {
                                        **base_config,
                                        "stage": "comments",
                                        "comment_anchor_source_ids": sorted(bucket_source_ids),
                                        "comment_split_index": bucket_idx,
                                        "comment_split_total": len(split_buckets),
                                    }
                                }
                            )
                    else:
                        # Fallback: single comment job (not enough posts to split, or split disabled)
                        comment_job_specs.append({"config": {**base_config, "stage": "comments"}})
                account_specs.append(
                    {
                        "platform": platform,
                        "account": account,
                        "base_config": base_config,
                        "comment_job_specs": comment_job_specs,
                    }
                )
            if normalized_mode != "comments_only":
                for shard in ordered_target_posts_shards:
                    available_at = (
                        runner_b_available_at
                        if shard.runner_lane == "B" and runner_b_available_at is not None
                        else None
                    )
                    for account_spec in account_specs:
                        base_config = dict(account_spec.get("base_config") or {})
                        created_total_jobs += 1
                        job_ids.append(
                            _create_job(
                                context,
                                run_id=run_id,
                                platform=platform,
                                source_scope=source_scope,
                                job_type="posts",
                                stage="posts",
                                config={
                                    **base_config,
                                    "stage": "posts",
                                    "date_start": _iso(shard.window_start),
                                    "date_end": _iso(shard.window_end),
                                    "window_start": _iso(shard.window_start),
                                    "window_end": _iso(shard.window_end),
                                    "shard_index": shard.shard_index,
                                    "runner_lane": shard.runner_lane,
                                    "priority_score": shard.priority_score,
                                    "day_offset": shard.day_offset,
                                    "day_weight": shard.day_weight,
                                    "platform_window_shard_hours": max(
                                        1,
                                        int(max(1.0, (shard.window_end - shard.window_start).total_seconds() / 3600.0)),
                                    ),
                                },
                                initiated_by=initiated_by,
                                status=initial_job_status,
                                priority=target_shard_priority_by_index.get(shard.shard_index, 100),
                                worker_id=inline_worker_id,
                                preclaim=bool(inline_worker_id),
                                available_at=available_at,
                                conn=enqueue_conn,
                                track_run_counters=False,
                            )
                        )
                        if _status_is_active(initial_job_status):
                            created_active_jobs += 1
                            created_stage_counts = _increment_stage_counter(
                                created_stage_counts,
                                stage="posts",
                                key="active",
                                delta=1,
                            )
                        created_stage_counts = _increment_stage_counter(
                            created_stage_counts,
                            stage="posts",
                            key="total",
                            delta=1,
                        )
            max_comment_jobs = max(
                (len(list(account_spec.get("comment_job_specs") or [])) for account_spec in account_specs),
                default=0,
            )
            for bucket_index in range(max_comment_jobs):
                for account_index, account_spec in enumerate(account_specs):
                    comment_job_specs = list(account_spec.get("comment_job_specs") or [])
                    if bucket_index >= len(comment_job_specs):
                        continue
                    lane = "A"
                    if schedule.runner_count > 1:
                        lane = "B" if ((comment_lane_index + account_index) % 2 == 1) else "A"
                    available_at = runner_b_available_at if lane == "B" and runner_b_available_at is not None else None
                    comment_job_config = dict(comment_job_specs[bucket_index].get("config") or {})
                    comment_job_config["runner_lane"] = lane
                    job_ids.append(
                        _create_job(
                            context,
                            run_id=run_id,
                            platform=platform,
                            source_scope=source_scope,
                            job_type="comments",
                            stage="comments",
                            config=comment_job_config,
                            initiated_by=initiated_by,
                            status=initial_job_status,
                            priority=200,
                            worker_id=inline_worker_id,
                            preclaim=bool(inline_worker_id),
                            available_at=available_at,
                            conn=enqueue_conn,
                            track_run_counters=False,
                        )
                    )
                    comment_lane_index += 1
                    created_total_jobs += 1
                    if _status_is_active(initial_job_status):
                        created_active_jobs += 1
                    created_stage_counts = _increment_stage_counter(
                        created_stage_counts,
                        stage="comments",
                        key="total",
                        delta=1,
                    )
                    if _status_is_active(initial_job_status):
                        created_stage_counts = _increment_stage_counter(
                            created_stage_counts,
                            stage="comments",
                            key="active",
                            delta=1,
                        )

    if not job_ids:
        try:
            normalized_run_id = str(UUID(str(run_id)))
        except (ValueError, TypeError, AttributeError):
            normalized_run_id = None
        if normalized_run_id:
            try:
                pg.fetch_one(
                    "delete from social.scrape_runs where id = %s::uuid returning id::text", [normalized_run_id]
                )
            except Exception:
                logger.debug(
                    "Unable to cleanup empty ingest run %s due to database unavailability",
                    normalized_run_id,
                    exc_info=True,
                )
        raise SocialIngestValidationError(
            "NO_INGEST_TARGETS",
            "No ingest jobs were created for the requested targets and options",
        )

    if _run_counter_columns_ready():
        with pg.db_connection() as conn:
            summary = _persist_run_counters_and_summary(
                conn=conn,
                run_id=run_id,
                total_jobs=created_total_jobs,
                completed_jobs=created_completed_jobs,
                failed_jobs=created_failed_jobs,
                active_jobs=created_active_jobs,
                items_found_total=created_items_found_total,
                stage_counts=created_stage_counts,
            )
    else:
        summary = _update_run_summary(run_id)
    if skipped_comment_jobs:
        summary = dict(summary or {})
        summary["skipped_comment_jobs"] = skipped_comment_jobs
    if queue_enabled and is_modal_remote_executor_enabled():
        dispatch_due_social_jobs(run_id=run_id)
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "source_scope": source_scope,
        "run_id": run_id,
        "status": "queued" if queue_enabled else "pending",
        "stages": stage_plan,
        "queued_or_started_jobs": len(job_ids),
        "summary": summary,
        "execution_owner": execution_metadata["execution_owner"],
        "execution_mode_canonical": execution_metadata["execution_mode_canonical"],
        "execution_backend_canonical": execution_metadata["execution_backend_canonical"],
        "ingest_mode": LEGACY_SEASON_TARGETED_INGEST_MODE,
    }


def ingest_shared_accounts(
    *,
    platforms: list[str] | None = None,
    source_scope: str = "network",
    accounts_override: list[str] | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
    pipeline_ingest_mode: str = SHARED_ACCOUNT_ASYNC_INGEST_MODE,
    initiated_by: str | None = None,
    inline_worker_id: str | None = None,
    allow_local_dev_inline_bypass: bool = False,
    execution_preference: Literal["auto", "prefer_local_inline"] = "auto",
    allow_ephemeral_accounts_override_sources: bool = False,
    resume_frontier_cursor: str | None = None,
    resume_frontier_snapshot: Mapping[str, Any] | None = None,
    catalog_action: str | None = None,
    catalog_action_scope: str | None = None,
    social_account_post_details_only: bool = False,
    details_refresh_skip_detail_fetch: bool | None = None,
    details_refresh_force_detail_fetch: bool | None = None,
    details_refresh_worker_count: int | None = None,
    comments_worker_count: int | None = None,
    comments_enable_media_followups: bool | None = None,
    details_refresh_skip_media_followups: bool | None = None,
    tiktok_comments_in_posts_stage: bool = False,
    tiktok_direct_comment_api_override: bool = False,
    twitter_comments_in_posts_stage: bool = False,
    comment_anchor_source_ids: dict[str, list[str]] | None = None,
    selected_tasks: Sequence[Any] | None = None,
    effective_selected_tasks: Sequence[Any] | None = None,
    launch_group_id: str | None = None,
    existing_run_id: str | None = None,
    defer_initial_dispatch: bool = False,
) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    requested_source_scope = _normalize_source_scope_input(source_scope)
    source_scope = normalize_source_scope(source_scope)
    normalized_ingest_mode = str(pipeline_ingest_mode or SHARED_ACCOUNT_ASYNC_INGEST_MODE).strip().lower()
    normalized_execution_preference = str(execution_preference or "auto").strip().lower() or "auto"
    if normalized_execution_preference not in {"auto", "prefer_local_inline"}:
        normalized_execution_preference = "auto"
    if normalized_execution_preference == "prefer_local_inline" and not allow_local_dev_inline_bypass:
        raise SocialIngestValidationError(
            "SOCIAL_LOCAL_INLINE_PREFERENCE_UNAVAILABLE",
            "execution_preference=prefer_local_inline requires an approved local inline execution bypass.",
        )
    if normalized_ingest_mode not in SUPPORTED_PIPELINE_INGEST_MODES:
        raise ValueError(f"Unsupported shared ingest mode: {pipeline_ingest_mode}")
    normalized_platforms = set(_resolve_requested_platforms(platforms)) if platforms else set(SUPPORTED_PLATFORMS)
    if normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
        normalized_platforms &= set(CATALOG_SUPPORTED_PLATFORMS)
        if platforms and not normalized_platforms:
            raise SocialIngestValidationError(
                "NO_SUPPORTED_CATALOG_PLATFORMS",
                "Catalog backfill supports instagram, tiktok, twitter, youtube, facebook, and threads only",
            )
    normalized_comment_anchor_source_ids, comment_anchor_overflow_platforms = _normalize_comment_anchor_source_ids(
        comment_anchor_source_ids,
        allowed_platforms=normalized_platforms,
    )
    serialized_comment_anchor_source_ids = _serialize_comment_anchor_source_ids(
        normalized_comment_anchor_source_ids or None
    )
    has_targeted_comment_anchors = any(normalized_comment_anchor_source_ids.values())
    configured_sources = get_shared_account_sources(
        source_scope=source_scope,
        include_inactive=False,
        platforms=sorted(normalized_platforms),
    )
    sources = list(configured_sources.get("sources") or [])
    override_accounts = {
        _normalize_account_handle(item) for item in (accounts_override or []) if _normalize_account_handle(item)
    }
    if override_accounts:
        matched_override_pairs: set[tuple[str, str]] = set()
        filtered_sources: list[dict[str, Any]] = []
        for row in sources:
            platform = _normalize_platform_name(row.get("platform"))
            account_handle = _normalize_account_handle(row.get("account_handle"))
            if not platform or not account_handle or account_handle not in override_accounts:
                continue
            filtered_sources.append(row)
            matched_override_pairs.add((platform, account_handle))
        sources = filtered_sources
        if allow_ephemeral_accounts_override_sources:
            missing_override_pairs = [
                (platform, account_handle)
                for platform in sorted(normalized_platforms)
                for account_handle in sorted(override_accounts)
                if (platform, account_handle) not in matched_override_pairs
            ]
            if missing_override_pairs:
                sources.extend(
                    _build_ephemeral_shared_account_override_sources(
                        source_scope=requested_source_scope,
                        platform_account_pairs=missing_override_pairs,
                    )
                )
    if not sources:
        raise SocialIngestValidationError(
            "NO_SHARED_ACCOUNT_SOURCES", "No active shared account sources are configured"
        )

    bounded_start = _coerce_dt(date_start)
    bounded_end = _coerce_dt(date_end)
    bounded_window = _catalog_backfill_has_bounded_window(date_start=bounded_start, date_end=bounded_end)
    details_refresh_only = bool(social_account_post_details_only)
    effective_details_refresh_skip_detail_fetch = (
        bool(details_refresh_skip_detail_fetch) if details_refresh_skip_detail_fetch is not None else False
    )
    effective_details_refresh_force_detail_fetch = (
        bool(details_refresh_force_detail_fetch) if details_refresh_force_detail_fetch is not None else False
    )
    detail_refresh_shard_count = (
        max(
            1,
            min(
                _normalize_non_negative_int(details_refresh_worker_count)
                or _resolve_int_env_with_bounds(
                    "SOCIAL_INSTAGRAM_DETAILS_REFRESH_LOCAL_WORKERS",
                    _resolve_int_env_with_bounds("TRR_DB_POOL_MAXCONN", 4, minimum=1, maximum=4),
                    minimum=1,
                    maximum=12,
                ),
                12,
            ),
        )
        if (
            normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
            and details_refresh_only
            and effective_details_refresh_force_detail_fetch
            and "instagram" in normalized_platforms
        )
        else 1
    )
    normalized_comments_worker_count = (
        max(
            1,
            min(_normalize_non_negative_int(comments_worker_count) or 0, 24),
        )
        if _normalize_non_negative_int(comments_worker_count)
        else None
    )
    effective_details_refresh_skip_media_followups = (
        bool(details_refresh_skip_media_followups)
        if details_refresh_skip_media_followups is not None
        else details_refresh_only
    )
    normalized_selected_tasks_for_config = _normalize_optional_social_account_catalog_backfill_selected_tasks(
        selected_tasks
    )
    normalized_effective_tasks_for_config = (
        _normalize_optional_social_account_catalog_backfill_selected_tasks(effective_selected_tasks)
        or normalized_selected_tasks_for_config
    )
    if (
        normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
        and not normalized_selected_tasks_for_config
    ):
        inferred_tasks: list[str] = []
        if not effective_details_refresh_skip_detail_fetch:
            inferred_tasks.append("post_details")
        if bool(tiktok_comments_in_posts_stage) or bool(twitter_comments_in_posts_stage):
            inferred_tasks.append("comments")
        if not effective_details_refresh_skip_media_followups:
            inferred_tasks.append("media")
        normalized_selected_tasks_for_config = (
            _normalize_optional_social_account_catalog_backfill_selected_tasks(inferred_tasks) or []
        )
        normalized_effective_tasks_for_config = normalized_selected_tasks_for_config
    catalog_task_config: dict[str, Any] = {}
    if normalized_selected_tasks_for_config:
        catalog_task_config["selected_tasks"] = normalized_selected_tasks_for_config
    if normalized_effective_tasks_for_config:
        catalog_task_config["effective_selected_tasks"] = normalized_effective_tasks_for_config
    catalog_followups_disabled = bool(details_refresh_only and effective_details_refresh_skip_media_followups)
    full_history_partition_enabled = (
        normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
        and not bounded_window
        and not details_refresh_only
        and not has_targeted_comment_anchors
    )
    normalized_catalog_action = str(catalog_action or "").strip().lower() or None
    normalized_catalog_action_scope = str(catalog_action_scope or "").strip().lower() or None
    resume_frontier_requested = normalized_catalog_action == "resume_tail" or bool(
        str(resume_frontier_cursor or "").strip()
    )

    expected_total_posts_by_account: dict[str, int] = {}
    catalog_total_posts_by_account: dict[str, int] = {}
    force_tiktok_local_inline_source_keys: set[tuple[str, str]] = set()
    modal_executor_required = False
    for row in sources:
        platform = _normalize_platform_name(row.get("platform"))
        account_handle = _normalize_account_handle(row.get("account_handle"))
        if not platform or not account_handle:
            continue
        source_key = (platform, account_handle)
        if (
            platform == "tiktok"
            and normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
            and full_history_partition_enabled
            and bool(allow_local_dev_inline_bypass)
            and normalized_execution_preference == "prefer_local_inline"
        ):
            force_tiktok_local_inline_source_keys.add(source_key)
        if normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
            catalog_total_posts = _shared_catalog_total_posts(platform, account_handle)
            allow_live_total_refresh = not details_refresh_only
            if platform == "instagram" and bounded_window:
                # This value is only an estimate used for launch planning. For
                # bounded Instagram backfills, stored catalog/history totals are
                # enough to choose the frontier lane, while the profile total query
                # joins against assignment tables and can hit statement_timeout on
                # high-volume profiles during launch finalization.
                allow_live_total_refresh = False
                materialized_total_posts = (
                    _shared_catalog_total_posts_for_window(
                        platform,
                        account_handle,
                        date_start=bounded_start,
                        date_end=bounded_end,
                    )
                    or catalog_total_posts
                )
            else:
                materialized_total_posts = _social_account_profile_total_posts(platform, account_handle)
            expected_total_posts = _best_known_social_account_total_posts(
                platform,
                account_handle,
                materialized_total_posts=materialized_total_posts,
                catalog_total_posts=catalog_total_posts,
                allow_live_refresh=allow_live_total_refresh,
            )
            catalog_total_posts_by_account[_shared_account_expected_total_posts_key(platform, account_handle)] = (
                catalog_total_posts
            )
            if expected_total_posts > 0:
                expected_total_posts_by_account[_shared_account_expected_total_posts_key(platform, account_handle)] = (
                    expected_total_posts
                )
        modal_executor_required = modal_executor_required or _shared_account_catalog_requires_modal_executor(
            platform=platform,
            pipeline_ingest_mode=normalized_ingest_mode,
        )

    effective_modal_executor_required = modal_executor_required and not allow_local_dev_inline_bypass

    if effective_modal_executor_required and is_queue_enabled():
        modal_required_platforms = sorted(
            {
                _normalize_platform_name(row.get("platform"))
                for row in sources
                if _shared_account_catalog_requires_modal_executor(
                    platform=row.get("platform"),
                    pipeline_ingest_mode=normalized_ingest_mode,
                )
            }
        )
        for modal_platform in modal_required_platforms:
            modal_account = next(
                (
                    _normalize_account_handle(row.get("account_handle"))
                    or str(row.get("account_handle") or "").strip().lower().lstrip("@")
                    for row in sources
                    if _normalize_platform_name(row.get("platform")) == modal_platform
                ),
                None,
            )
            assert_worker_available_when_queue_enabled(
                required_execution_backend="modal",
                platform=modal_platform,
                account_handle=modal_account,
            )

    catalog_runner_count = 1
    catalog_runner_strategy = "single_runner"
    catalog_partition_strategy: str | None = None
    partition_eligible_sources = [
        row
        for row in sources
        if (
            (_normalize_platform_name(row.get("platform")) or "")
            and (_normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip())
            and (
                (
                    _normalize_platform_name(row.get("platform")) or "",
                    _normalize_account_handle(row.get("account_handle"))
                    or str(row.get("account_handle") or "").strip(),
                )
                not in force_tiktok_local_inline_source_keys
            )
        )
    ]
    catalog_window_shard_days_by_platform: dict[str, int] = {}
    catalog_total_shards_by_platform: dict[str, int] = {}
    catalog_source_shards: dict[tuple[str, str], list[IngestTimeShard]] = {}
    bounded_frontier_source_keys: set[tuple[str, str]] = set()
    if normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE and bounded_window:
        candidate_shards: dict[tuple[str, str], list[IngestTimeShard]] = {}
        for row in sources:
            platform = _normalize_platform_name(row.get("platform"))
            account_handle = (
                _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip()
            )
            if not platform or not account_handle:
                continue
            if _shared_account_prefers_frontier_strategy(
                platform=platform,
                pipeline_ingest_mode=normalized_ingest_mode,
                bounded_window=True,
                resume_frontier_requested=resume_frontier_requested,
                expected_total_posts=expected_total_posts_by_account.get(
                    _shared_account_expected_total_posts_key(platform, account_handle)
                ),
                catalog_total_posts=catalog_total_posts_by_account.get(
                    _shared_account_expected_total_posts_key(platform, account_handle)
                ),
            ):
                bounded_frontier_source_keys.add((platform, account_handle))
                catalog_total_shards_by_platform[platform] = catalog_total_shards_by_platform.get(platform, 0) + 1
                continue
            source_shards = _build_catalog_backfill_shards(
                platform=platform,
                date_start=bounded_start,
                date_end=bounded_end,
                runner_count=CATALOG_BACKFILL_MULTI_RUNNER_COUNT,
            )
            candidate_shards[(platform, account_handle)] = source_shards
            catalog_total_shards_by_platform[platform] = catalog_total_shards_by_platform.get(platform, 0) + len(
                source_shards
            )
            if len(source_shards) > 1:
                first_shard = source_shards[0]
                shard_days = max(
                    1,
                    int((first_shard.window_end - first_shard.window_start).total_seconds() // 86400) + 1,
                )
                existing_days = catalog_window_shard_days_by_platform.get(platform)
                if existing_days is None or shard_days < existing_days:
                    catalog_window_shard_days_by_platform[platform] = shard_days
        catalog_source_shards = candidate_shards
        if bounded_frontier_source_keys and not candidate_shards:
            catalog_runner_count = CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT
            catalog_runner_strategy = CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
            catalog_partition_strategy = CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
        elif any(len(source_shards) > 1 for source_shards in candidate_shards.values()) or len(candidate_shards) > 1:
            catalog_runner_count = CATALOG_BACKFILL_MULTI_RUNNER_COUNT
            if bounded_frontier_source_keys:
                catalog_runner_strategy = "hybrid_frontier_window_shards"
                catalog_partition_strategy = "hybrid_frontier_window_shards"
            else:
                catalog_runner_strategy = "adaptive_dual_runner"
                catalog_partition_strategy = CATALOG_FULL_HISTORY_DATE_WINDOW_PARTITION_STRATEGY
    elif full_history_partition_enabled and partition_eligible_sources:
        if all(
            _shared_account_prefers_frontier_strategy(
                platform=row.get("platform"),
                pipeline_ingest_mode=normalized_ingest_mode,
                bounded_window=bounded_window,
                resume_frontier_requested=resume_frontier_requested,
                expected_total_posts=expected_total_posts_by_account.get(
                    _shared_account_expected_total_posts_key(
                        _normalize_platform_name(row.get("platform")) or "",
                        _normalize_account_handle(row.get("account_handle"))
                        or str(row.get("account_handle") or "").strip(),
                    )
                ),
                catalog_total_posts=catalog_total_posts_by_account.get(
                    _shared_account_expected_total_posts_key(
                        _normalize_platform_name(row.get("platform")) or "",
                        _normalize_account_handle(row.get("account_handle"))
                        or str(row.get("account_handle") or "").strip(),
                    )
                ),
            )
            for row in partition_eligible_sources
        ):
            catalog_runner_count = CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT
            catalog_runner_strategy = CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
            catalog_partition_strategy = CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
        elif any(_catalog_full_history_partition_supported(row.get("platform")) for row in partition_eligible_sources):
            catalog_runner_count = CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT
            catalog_runner_strategy = "full_history_cursor_breakpoints"
            catalog_partition_strategy = CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY
    if force_tiktok_local_inline_source_keys and not partition_eligible_sources:
        catalog_runner_count = 1
        catalog_runner_strategy = "single_runner_fallback"
        catalog_partition_strategy = None
    if details_refresh_only and effective_details_refresh_force_detail_fetch and detail_refresh_shard_count > 1:
        catalog_runner_count = detail_refresh_shard_count
        catalog_runner_strategy = "parallel_detail_refresh"
        catalog_partition_strategy = "details_refresh_shards"

    run_config = {
        "pipeline_ingest_mode": normalized_ingest_mode,
        "ingest_mode_override": "details_refresh" if details_refresh_only else None,
        "catalog_followups_disabled": catalog_followups_disabled,
        "details_refresh_skip_detail_fetch": effective_details_refresh_skip_detail_fetch,
        "details_refresh_force_detail_fetch": effective_details_refresh_force_detail_fetch,
        "details_refresh_worker_count": detail_refresh_shard_count if detail_refresh_shard_count > 1 else None,
        "comments_worker_count": normalized_comments_worker_count,
        "details_refresh_shard_count": detail_refresh_shard_count if detail_refresh_shard_count > 1 else None,
        "details_refresh_skip_media_followups": effective_details_refresh_skip_media_followups,
        "tiktok_comments_in_posts_stage": bool(tiktok_comments_in_posts_stage),
        "tiktok_direct_comment_api_override": bool(tiktok_direct_comment_api_override),
        "twitter_comments_in_posts_stage": bool(twitter_comments_in_posts_stage),
        **catalog_task_config,
        "source_scope": source_scope,
        "platforms": sorted(normalized_platforms),
        "accounts_override": sorted(override_accounts),
        "date_start": _iso(date_start),
        "date_end": _iso(date_end),
        "runner_strategy": catalog_runner_strategy,
        "runner_count": catalog_runner_count,
        "partition_strategy": catalog_partition_strategy,
        "catalog_total_shards_by_platform": catalog_total_shards_by_platform,
        "catalog_window_shard_days_by_platform": catalog_window_shard_days_by_platform,
        "expected_total_posts_by_account": expected_total_posts_by_account,
        "expected_total_posts": (
            next(iter(expected_total_posts_by_account.values())) if len(expected_total_posts_by_account) == 1 else None
        ),
        "required_execution_backend": "modal" if effective_modal_executor_required else None,
        "allow_local_dev_inline_bypass": bool(allow_local_dev_inline_bypass),
        "execution_preference": normalized_execution_preference,
        "resume_frontier_cursor": str(resume_frontier_cursor or "").strip() or None,
        "launch_group_id": str(launch_group_id or "").strip() or None,
        "catalog_action": normalized_catalog_action,
        "catalog_action_scope": normalized_catalog_action_scope,
        "comment_anchor_source_ids": serialized_comment_anchor_source_ids,
        "comment_anchor_source_ids_overflow_platforms": sorted(comment_anchor_overflow_platforms),
        **_configured_execution_metadata(),
    }
    creator_runtime_version = dict(_resolve_runtime_version_stamp())
    effective_required_runtime_version = _resolve_effective_runtime_version(
        required_execution_backend=run_config.get("required_execution_backend")
    )
    if effective_required_runtime_version:
        run_config["required_runtime_version"] = effective_required_runtime_version
    elif str(run_config.get("required_execution_backend") or "").strip().lower() != "modal":
        run_config["required_runtime_version"] = creator_runtime_version
    if creator_runtime_version:
        run_config["created_by_runtime_version"] = creator_runtime_version
    run_id = str(existing_run_id or "").strip()
    if run_id:
        _merge_catalog_run_config(
            run_id=run_id,
            metadata_updates=run_config,
        )
    else:
        run_id = _create_run(
            None,
            source_scope=source_scope,
            initiated_by=initiated_by,
            config=run_config,
            status="queued",
        )
    initial_job_status = "queued" if is_queue_enabled() else "pending"
    job_ids: list[str] = []
    discovery_jobs_created = False
    sorted_sources = sorted(
        sources,
        key=lambda row: (
            max(1, int(row.get("scrape_priority") or 100)),
            _normalize_platform_name(row.get("platform")) or "",
            _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip(),
        ),
    )

    if normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE and catalog_source_shards:
        sources_with_shards: list[dict[str, Any]] = []
        max_shard_depth = 0
        for row in sorted_sources:
            platform = _normalize_platform_name(row.get("platform"))
            account_handle = (
                _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip()
            )
            if not platform or not account_handle:
                continue
            source_shards = list(catalog_source_shards.get((platform, account_handle)) or [])
            if not source_shards:
                continue
            max_shard_depth = max(max_shard_depth, len(source_shards))
            sources_with_shards.append(
                {
                    "row": row,
                    "platform": platform,
                    "account_handle": account_handle,
                    "priority": max(1, int(row.get("scrape_priority") or 100)),
                    "shards": source_shards,
                }
            )

        for row in sorted_sources:
            platform = _normalize_platform_name(row.get("platform"))
            account_handle = (
                _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip()
            )
            if not platform or not account_handle or (platform, account_handle) not in bounded_frontier_source_keys:
                continue
            job_id = _enqueue_shared_discovery_job(
                run_id=run_id,
                platform=platform,
                source_scope=source_scope,
                account_handle=account_handle,
                shared_account_source_id=row.get("id"),
                pipeline_ingest_mode=normalized_ingest_mode,
                runner_count=CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                expected_total_posts=_shared_account_expected_total_posts_from_config(
                    {"expected_total_posts_by_account": expected_total_posts_by_account},
                    platform=platform,
                    account_handle=account_handle,
                ),
                runner_strategy=CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                partition_strategy=CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                required_worker_lane=None,
                required_execution_backend=(
                    "modal"
                    if (
                        not allow_local_dev_inline_bypass
                        and _shared_account_catalog_requires_modal_executor(
                            platform=platform,
                            pipeline_ingest_mode=normalized_ingest_mode,
                        )
                    )
                    else None
                ),
                allow_local_dev_inline_bypass=bool(allow_local_dev_inline_bypass),
                resume_frontier_cursor=resume_frontier_cursor,
                resume_frontier_snapshot=resume_frontier_snapshot,
                date_start=date_start,
                date_end=date_end,
                catalog_action=normalized_catalog_action,
                catalog_action_scope=normalized_catalog_action_scope,
                selected_tasks=normalized_selected_tasks_for_config,
                effective_selected_tasks=normalized_effective_tasks_for_config,
                details_refresh_skip_detail_fetch=effective_details_refresh_skip_detail_fetch,
                details_refresh_force_detail_fetch=effective_details_refresh_force_detail_fetch,
                comments_worker_count=normalized_comments_worker_count,
                details_refresh_skip_media_followups=effective_details_refresh_skip_media_followups,
                tiktok_comments_in_posts_stage=bool(platform == "tiktok" and tiktok_comments_in_posts_stage),
                tiktok_direct_comment_api_override=bool(platform == "tiktok" and tiktok_direct_comment_api_override),
                twitter_comments_in_posts_stage=bool(platform == "twitter" and twitter_comments_in_posts_stage),
                initiated_by=initiated_by,
                worker_id=inline_worker_id,
                priority=max(1, int(row.get("scrape_priority") or 100)),
            )
            job_ids.append(job_id)
            discovery_jobs_created = True

        for shard_depth in range(max_shard_depth):
            for source in sources_with_shards:
                source_shards = cast("list[IngestTimeShard]", source["shards"])
                if shard_depth >= len(source_shards):
                    continue
                shard = source_shards[shard_depth]
                platform = cast("str", source["platform"])
                account_handle = cast("str", source["account_handle"])
                row = cast("dict[str, Any]", source["row"])
                base_priority = cast("int", source["priority"])
                platform_comment_anchor_ids = sorted(normalized_comment_anchor_source_ids.get(platform) or [])
                platform_comment_anchor_config = (
                    {"comment_anchor_source_ids": {platform: platform_comment_anchor_ids}}
                    if platform_comment_anchor_ids
                    else {}
                )
                shared_posts_stage = _shared_account_posts_stage_for_platform(platform)
                base_shard_config = {
                    "stage": shared_posts_stage,
                    "shared_account_stage": SHARED_ACCOUNT_POSTS_STAGE,
                    "platform": platform,
                    "source_scope": source_scope,
                    "account": account_handle,
                    "date_start": _iso(shard.window_start),
                    "date_end": _iso(shard.window_end),
                    "window_start": _iso(shard.window_start),
                    "window_end": _iso(shard.window_end),
                    "shard_index": shard.shard_index,
                    "shard_total": len(source_shards),
                    "runner_lane": shard.runner_lane,
                    "runner_strategy": catalog_runner_strategy,
                    "runner_count": catalog_runner_count,
                    "shared_account_source_id": row.get("id"),
                    "ingest_mode": "details_refresh" if details_refresh_only else None,
                    "max_posts_per_target": 0,
                    "pipeline_ingest_mode": normalized_ingest_mode,
                    "catalog_followups_disabled": catalog_followups_disabled,
                    "details_refresh_skip_detail_fetch": effective_details_refresh_skip_detail_fetch,
                    "details_refresh_force_detail_fetch": effective_details_refresh_force_detail_fetch,
                    "details_refresh_worker_count": detail_refresh_shard_count
                    if detail_refresh_shard_count > 1
                    else None,
                    "comments_worker_count": normalized_comments_worker_count,
                    "details_refresh_skip_media_followups": effective_details_refresh_skip_media_followups,
                    "tiktok_comments_in_posts_stage": bool(platform == "tiktok" and tiktok_comments_in_posts_stage),
                    "tiktok_direct_comment_api_override": bool(
                        platform == "tiktok" and tiktok_direct_comment_api_override
                    ),
                    "twitter_comments_in_posts_stage": bool(platform == "twitter" and twitter_comments_in_posts_stage),
                    "youtube_comments_in_posts_stage": bool(
                        platform == "youtube" and "comments" in normalized_effective_tasks_for_config
                    ),
                    **platform_comment_anchor_config,
                    **catalog_task_config,
                    "launch_group_id": str(launch_group_id or "").strip() or None,
                    "required_execution_backend": (
                        "modal"
                        if (
                            not allow_local_dev_inline_bypass
                            and _shared_account_catalog_requires_modal_executor(
                                platform=platform,
                                pipeline_ingest_mode=normalized_ingest_mode,
                            )
                        )
                        else None
                    ),
                    "allow_local_dev_inline_bypass": bool(allow_local_dev_inline_bypass),
                    "catalog_action": normalized_catalog_action,
                    "catalog_action_scope": normalized_catalog_action_scope,
                    "expected_total_posts": _shared_account_expected_total_posts_from_config(
                        {"expected_total_posts_by_account": expected_total_posts_by_account},
                        platform=platform,
                        account_handle=account_handle,
                    ),
                }
                for surface_index, shard_config in enumerate(
                    _expand_youtube_surface_job_configs(platform, base_shard_config)
                ):
                    job_id = _create_job(
                        None,
                        run_id=run_id,
                        platform=platform,
                        source_scope=source_scope,
                        job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
                        stage=shared_posts_stage,
                        config=shard_config,
                        initiated_by=initiated_by,
                        status=initial_job_status,
                        priority=max(1, base_priority + shard_depth + surface_index),
                        worker_id=inline_worker_id,
                        preclaim=bool(inline_worker_id),
                        track_run_counters=False,
                    )
                    job_ids.append(job_id)
    else:
        for row in sorted_sources:
            platform = _normalize_platform_name(row.get("platform"))
            account_handle = (
                _normalize_account_handle(row.get("account_handle")) or str(row.get("account_handle") or "").strip()
            )
            if not platform or not account_handle:
                continue
            platform_comment_anchor_ids = sorted(normalized_comment_anchor_source_ids.get(platform) or [])
            platform_comment_anchor_config = (
                {"comment_anchor_source_ids": {platform: platform_comment_anchor_ids}}
                if platform_comment_anchor_ids
                else {}
            )
            force_tiktok_local_inline_direct = (platform, account_handle) in force_tiktok_local_inline_source_keys
            shared_posts_stage = _shared_account_posts_stage_for_platform(platform)
            job_config = {
                "stage": shared_posts_stage,
                "shared_account_stage": SHARED_ACCOUNT_POSTS_STAGE,
                "platform": platform,
                "source_scope": source_scope,
                "account": account_handle,
                "date_start": _iso(date_start),
                "date_end": _iso(date_end),
                "shared_account_source_id": row.get("id"),
                "ingest_mode": "details_refresh" if details_refresh_only else None,
                "pipeline_ingest_mode": normalized_ingest_mode,
                "catalog_followups_disabled": catalog_followups_disabled,
                "details_refresh_skip_detail_fetch": effective_details_refresh_skip_detail_fetch,
                "details_refresh_force_detail_fetch": effective_details_refresh_force_detail_fetch,
                "details_refresh_worker_count": detail_refresh_shard_count if detail_refresh_shard_count > 1 else None,
                "comments_worker_count": normalized_comments_worker_count,
                "details_refresh_skip_media_followups": effective_details_refresh_skip_media_followups,
                "tiktok_comments_in_posts_stage": bool(platform == "tiktok" and tiktok_comments_in_posts_stage),
                "tiktok_direct_comment_api_override": bool(platform == "tiktok" and tiktok_direct_comment_api_override),
                "twitter_comments_in_posts_stage": bool(platform == "twitter" and twitter_comments_in_posts_stage),
                "youtube_comments_in_posts_stage": bool(
                    platform == "youtube" and "comments" in normalized_effective_tasks_for_config
                ),
                **platform_comment_anchor_config,
                **catalog_task_config,
                "launch_group_id": str(launch_group_id or "").strip() or None,
                "required_execution_backend": (
                    "modal"
                    if (
                        not allow_local_dev_inline_bypass
                        and _shared_account_catalog_requires_modal_executor(
                            platform=platform,
                            pipeline_ingest_mode=normalized_ingest_mode,
                        )
                    )
                    else None
                ),
                "allow_local_dev_inline_bypass": bool(allow_local_dev_inline_bypass),
                "catalog_action": normalized_catalog_action,
                "catalog_action_scope": normalized_catalog_action_scope,
                "expected_total_posts": _shared_account_expected_total_posts_from_config(
                    {"expected_total_posts_by_account": expected_total_posts_by_account},
                    platform=platform,
                    account_handle=account_handle,
                ),
            }
            if normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE:
                job_config["max_posts_per_target"] = 0
                if details_refresh_only and platform == "instagram":
                    job_config["completion_target_posts"] = _normalize_non_negative_int(
                        catalog_total_posts_by_account.get(
                            _shared_account_expected_total_posts_key(platform, account_handle)
                        )
                    )
            if (
                normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                and details_refresh_only
                and effective_details_refresh_force_detail_fetch
                and platform == "instagram"
                and detail_refresh_shard_count > 1
            ):
                scheduler_lanes = _catalog_backfill_run_scheduler_lanes(detail_refresh_shard_count)
                for shard_index in range(detail_refresh_shard_count):
                    runner_lane = scheduler_lanes[shard_index]
                    shard_config = {
                        **job_config,
                        "details_refresh_shard_index": shard_index,
                        "details_refresh_shard_count": detail_refresh_shard_count,
                        "runner_lane": runner_lane,
                        "required_worker_lane": runner_lane.lower(),
                        "runner_strategy": "parallel_detail_refresh",
                        "runner_count": detail_refresh_shard_count,
                        "partition_strategy": "details_refresh_shards",
                    }
                    job_id = _create_job(
                        None,
                        run_id=run_id,
                        platform=platform,
                        source_scope=source_scope,
                        job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
                        stage=shared_posts_stage,
                        config=shard_config,
                        initiated_by=initiated_by,
                        status=initial_job_status,
                        priority=max(1, int(row.get("scrape_priority") or 100) + shard_index),
                        worker_id=inline_worker_id,
                        preclaim=bool(inline_worker_id),
                        track_run_counters=False,
                    )
                    job_ids.append(job_id)
                continue
            if force_tiktok_local_inline_direct:
                job_config["runner_strategy"] = "single_runner_fallback"
                job_config["runner_count"] = 1
                job_config["partition_strategy"] = None
                job_config["required_execution_backend"] = None
            bounded_frontier_direct = (platform, account_handle) in bounded_frontier_source_keys
            if (
                normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                and (full_history_partition_enabled or bounded_frontier_direct)
                and not force_tiktok_local_inline_direct
                and (
                    _shared_account_catalog_frontier_supported(
                        platform=platform,
                        pipeline_ingest_mode=normalized_ingest_mode,
                        bounded_window=bounded_window,
                    )
                    or _catalog_full_history_partition_supported(platform)
                )
            ):
                use_frontier_strategy = _shared_account_prefers_frontier_strategy(
                    platform=platform,
                    pipeline_ingest_mode=normalized_ingest_mode,
                    bounded_window=bounded_window,
                    resume_frontier_requested=resume_frontier_requested,
                    expected_total_posts=expected_total_posts_by_account.get(
                        _shared_account_expected_total_posts_key(platform, account_handle)
                    ),
                    catalog_total_posts=catalog_total_posts_by_account.get(
                        _shared_account_expected_total_posts_key(platform, account_handle)
                    ),
                )
                job_id = _enqueue_shared_discovery_job(
                    run_id=run_id,
                    platform=platform,
                    source_scope=source_scope,
                    account_handle=account_handle,
                    shared_account_source_id=row.get("id"),
                    pipeline_ingest_mode=normalized_ingest_mode,
                    runner_count=catalog_runner_count,
                    expected_total_posts=_shared_account_expected_total_posts_from_config(
                        {"expected_total_posts_by_account": expected_total_posts_by_account},
                        platform=platform,
                        account_handle=account_handle,
                    ),
                    runner_strategy=(
                        CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
                        if use_frontier_strategy
                        else "full_history_cursor_breakpoints"
                    ),
                    partition_strategy=(
                        CATALOG_FULL_HISTORY_FRONTIER_STRATEGY
                        if use_frontier_strategy
                        else CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY
                    ),
                    required_worker_lane=job_config.get("required_worker_lane"),
                    required_execution_backend=job_config.get("required_execution_backend"),
                    allow_local_dev_inline_bypass=bool(job_config.get("allow_local_dev_inline_bypass")),
                    resume_frontier_cursor=resume_frontier_cursor,
                    resume_frontier_snapshot=resume_frontier_snapshot,
                    date_start=date_start,
                    date_end=date_end,
                    catalog_action=normalized_catalog_action,
                    catalog_action_scope=normalized_catalog_action_scope,
                    selected_tasks=normalized_selected_tasks_for_config,
                    effective_selected_tasks=normalized_effective_tasks_for_config,
                    details_refresh_skip_detail_fetch=effective_details_refresh_skip_detail_fetch,
                    details_refresh_force_detail_fetch=effective_details_refresh_force_detail_fetch,
                    comments_worker_count=normalized_comments_worker_count,
                    details_refresh_skip_media_followups=effective_details_refresh_skip_media_followups,
                    tiktok_comments_in_posts_stage=bool(platform == "tiktok" and tiktok_comments_in_posts_stage),
                    tiktok_direct_comment_api_override=bool(
                        platform == "tiktok" and tiktok_direct_comment_api_override
                    ),
                    twitter_comments_in_posts_stage=bool(platform == "twitter" and twitter_comments_in_posts_stage),
                    initiated_by=initiated_by,
                    worker_id=inline_worker_id,
                    priority=max(1, int(row.get("scrape_priority") or 100)),
                )
                discovery_jobs_created = True
            else:
                for surface_index, expanded_job_config in enumerate(
                    _expand_youtube_surface_job_configs(platform, job_config)
                ):
                    job_id = _create_job(
                        None,
                        run_id=run_id,
                        platform=platform,
                        source_scope=source_scope,
                        job_type=SHARED_ACCOUNT_POSTS_JOB_TYPE,
                        stage=shared_posts_stage,
                        config=expanded_job_config,
                        initiated_by=initiated_by,
                        status=initial_job_status,
                        priority=max(1, int(row.get("scrape_priority") or 100) + surface_index),
                        worker_id=inline_worker_id,
                        preclaim=bool(inline_worker_id),
                        track_run_counters=False,
                    )
                    job_ids.append(job_id)
                continue
            job_ids.append(job_id)
    if not job_ids:
        raise SocialIngestValidationError("NO_SHARED_ACCOUNT_SOURCES", "No shared account jobs were created")
    if _run_counter_columns_ready():
        with pg.db_connection() as conn:
            summary = _persist_run_counters_and_summary(
                conn=conn,
                run_id=run_id,
                total_jobs=len(job_ids),
                completed_jobs=0,
                failed_jobs=0,
                active_jobs=len(job_ids) if _status_is_active(initial_job_status) else 0,
                items_found_total=0,
                stage_counts={
                    (
                        SHARED_ACCOUNT_DISCOVERY_STAGE
                        if (
                            normalized_ingest_mode == SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                            and discovery_jobs_created
                        )
                        else SHARED_ACCOUNT_POSTS_STAGE
                    ): {
                        "total": len(job_ids),
                        "completed": 0,
                        "failed": 0,
                        "active": len(job_ids) if _status_is_active(initial_job_status) else 0,
                    },
                },
            )
    else:
        summary = _update_run_summary(run_id)
    if is_queue_enabled() and is_modal_remote_executor_enabled():
        if defer_initial_dispatch:
            _dispatch_due_social_jobs_in_background(run_id=run_id)
        else:
            dispatch_due_social_jobs(run_id=run_id)
    return {
        "run_id": run_id,
        "status": initial_job_status,
        "source_scope": source_scope,
        "ingest_mode": normalized_ingest_mode,
        "shared_scrape_status": {"status": initial_job_status, "job_count": len(job_ids)},
        "classification_status": None,
        "materialization_status": None,
        "review_queue_count": (
            list_shared_review_queue(source_scope=source_scope, review_status="open", limit=1).get("count", 0)
            if normalized_ingest_mode == SHARED_ACCOUNT_ASYNC_INGEST_MODE
            else 0
        ),
        "summary": summary,
        "execution_owner": run_config["execution_owner"],
        "execution_mode_canonical": run_config["execution_mode_canonical"],
        "execution_backend_canonical": run_config["execution_backend_canonical"],
        "catalog_action": normalized_catalog_action,
        "catalog_action_scope": normalized_catalog_action_scope,
    }


def list_shared_runs(
    *,
    limit: int = 50,
    status: str | None = None,
    source_scope: str | None = None,
    run_id: str | None = None,
) -> list[dict[str, Any]]:
    from trr_backend.socials.control_plane.shared_accounts import list_shared_runs as impl

    source_scope = normalize_source_scope(source_scope) if source_scope is not None else None
    return impl(limit=limit, status=status, source_scope=source_scope, run_id=run_id)


def cancel_shared_run(
    run_id: str,
    *,
    cancelled_by: str | None = None,
    reconcile_summary: bool = True,
    conn: Any | None = None,
) -> dict[str, Any]:
    run_row = pg.fetch_one(
        """
        select id::text as id
        from social.scrape_runs
        where id = %s::uuid
          and coalesce(config->>'pipeline_ingest_mode', '') in (%s, %s)
        """,
        [run_id, SHARED_ACCOUNT_ASYNC_INGEST_MODE, SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE],
        conn=conn,
    )
    if not run_row:
        raise ValueError("Shared run not found")
    pg.fetch_one(
        """
        update social.scrape_runs
        set
          status = 'cancelled',
          cancelled_at = now(),
          completed_at = now(),
          summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object('cancelled_by', %s)
        where id = %s::uuid
        returning id::text
        """,
        [cancelled_by, run_id],
        conn=conn,
    )
    features = _scrape_jobs_features(conn=conn)
    has_queue_fields = bool(features.get("has_queue_fields"))
    returning_queue_fields = (
        "worker_id, claimed_at" if has_queue_fields else "null::text as worker_id, null::timestamptz as claimed_at"
    )
    cancelled_jobs = pg.execute_returning(
        f"""
        update social.scrape_jobs
        set
          status = 'cancelled',
          completed_at = now(),
          error_message = coalesce(error_message, 'Cancelled by user request')
        where run_id = %s::uuid
          and status in ('queued', 'pending', 'retrying', 'running', 'cancelling')
        returning id::text as id, {returning_queue_fields}
        """,
        [run_id],
        conn=conn,
    )
    cancelled_job_ids = [str(row.get("id") or "").strip() for row in cancelled_jobs if str(row.get("id") or "").strip()]
    claimed_jobs_cancelled = sum(
        1 for row in cancelled_jobs if str(row.get("worker_id") or "").strip() or row.get("claimed_at") is not None
    )
    for row in cancelled_jobs:
        job_id = str(row.get("id") or "").strip()
        if job_id:
            _clear_worker_heartbeat_for_job(
                job_id=job_id,
                status="idle",
                metadata={"source": "cancel_shared_run", "job_status": "cancelled"},
            )
    _cancel_shared_account_run_partitions(run_id, conn=conn)
    _cancel_shared_account_run_frontiers(run_id, conn=conn)
    summary = _update_run_summary(run_id, force_recompute=True, conn=conn) if reconcile_summary else None
    _invalidate_queue_status_cache()
    if claimed_jobs_cancelled > 0:
        message = (
            f"Cancel accepted. Marked {len(cancelled_job_ids)} job(s) cancelled; "
            f"{claimed_jobs_cancelled} already had a worker claim, so in-flight post/detail "
            "saves may finish before the worker stops."
        )
    elif cancelled_job_ids:
        message = f"Cancel accepted. Marked {len(cancelled_job_ids)} queued job(s) cancelled."
    else:
        message = (
            "Cancel accepted. No queued jobs were available to cancel; if a worker already claimed the run, "
            "in-flight post/detail saves may finish before it stops."
        )
    return {
        "run_id": run_id,
        "status": "cancelled",
        "cancelled_jobs": len(cancelled_job_ids),
        "claimed_jobs_cancelled": claimed_jobs_cancelled,
        "message": message,
        "summary": summary,
    }


def reconcile_cancelled_shared_run(run_id: str) -> dict[str, Any]:
    summary = _update_run_summary(run_id, force_recompute=True)
    _invalidate_queue_status_cache()
    return {"run_id": run_id, "status": "cancelled", "summary": summary}


def list_canonical_week_windows(
    season_id: str,
    *,
    timezone: str = "America/New_York",
    source_scope: str = "network",
    now_utc: datetime | None = None,
) -> list[dict[str, Any]]:
    context = get_season_context(season_id)
    week_windows, _ = _resolve_week_windows(
        context,
        timezone=timezone,
        source_scope=source_scope,
        now_utc=now_utc or _now_utc(),
    )
    payload: list[dict[str, Any]] = []
    for window in week_windows:
        payload.append(
            {
                "week_index": int(window.week_index),
                "label": _week_window_label(window, timezone=timezone),
                "week_type": str(window.week_type),
                "episode_number": int(window.episode_number) if window.episode_number is not None else None,
                "start_local": window.start_local.isoformat(),
                "end_local": window.end_local.isoformat(),
                "date_start": _iso(window.start_local.astimezone(UTC)),
                "date_end": _iso(window.end_local.astimezone(UTC)),
            }
        )
    return payload


def orchestrate_season_ingest(
    season_id: str,
    *,
    platforms: list[str] | None,
    source_scope: str,
    timezone: str = "America/New_York",
    week_index: int | None = None,
    sync_strategy: str = "incremental",
    max_posts_per_target: int | None,
    max_comments_per_post: int | None,
    max_replies_per_post: int | None = 100,
    fetch_replies: bool,
    ingest_mode: str = "posts_and_comments",
    comment_refresh_policy: str = DEFAULT_COMMENT_REFRESH_POLICY,
    comment_anchor_source_ids: dict[str, list[str]] | None = None,
    sound_ids: list[str] | None = None,
    runner_strategy: str | None = None,
    runner_count: int | None = None,
    window_shard_hours: int | None = None,
    runner_b_start_offset_hours: int | None = None,
    day_weight_profile: str | None = None,
    priority_mode: str | None = None,
    youtube_source_mode: str | None = None,
    youtube_force_reindex: bool = False,
    youtube_force_media_refresh: bool = False,
    youtube_force_comment_refresh: bool = False,
    accounts_override: list[str] | None = None,
    hashtags_override: list[str] | None = None,
    keywords_override: list[str] | None = None,
    client_session_id: str | None = None,
    client_workflow_id: str | None = None,
    resume_existing: bool = True,
    initiated_by: str | None = None,
) -> dict[str, Any]:
    normalized_platforms = _resolve_requested_platforms(platforms)
    if not normalized_platforms:
        normalized_platforms = sorted(SUPPORTED_PLATFORMS)

    canonical_windows = list_canonical_week_windows(
        season_id,
        timezone=timezone,
        source_scope=source_scope,
    )
    if week_index is not None:
        selected_windows = [
            window for window in canonical_windows if int(window.get("week_index") or -1) == int(week_index)
        ]
        if not selected_windows:
            raise ValueError(f"Week {week_index} is not available for this season")
    else:
        selected_windows = canonical_windows
    if not selected_windows:
        raise ValueError("No canonical season weeks are available for orchestration")

    orchestration_scope = (
        "single_week_single_platform"
        if len(selected_windows) == 1 and len(normalized_platforms) == 1
        else "single_week_all_platforms"
        if len(selected_windows) == 1
        else "full_season_single_platform"
        if len(normalized_platforms) == 1
        else "full_season_all_platforms"
    )

    normalized_workflow_id = str(client_workflow_id or "").strip()
    if not normalized_workflow_id:
        request_fingerprint = hashlib.sha1(
            json.dumps(
                {
                    "season_id": season_id,
                    "source_scope": source_scope,
                    "timezone": timezone,
                    "platforms": normalized_platforms,
                    "weeks": [int(window.get("week_index") or 0) for window in selected_windows],
                    "sync_strategy": sync_strategy,
                    "ingest_mode": ingest_mode,
                    "comment_refresh_policy": comment_refresh_policy,
                    "accounts_override": list(accounts_override or []),
                    "hashtags_override": list(hashtags_override or []),
                    "keywords_override": list(keywords_override or []),
                    "sound_ids": list(sound_ids or []),
                },
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()[:16]
        normalized_workflow_id = f"social-orch-{request_fingerprint}"

    existing_runs_by_slot: dict[str, dict[str, Any]] = {}
    if resume_existing:
        for row in list_runs(season_id, limit=250, client_workflow_id=normalized_workflow_id):
            slot_key = str(row.get("orchestration_slot_key") or "").strip()
            if slot_key and slot_key not in existing_runs_by_slot:
                existing_runs_by_slot[slot_key] = row

    created_runs: list[dict[str, Any]] = []
    reused_runs: list[dict[str, Any]] = []
    requested_runs: list[dict[str, Any]] = []
    slot_position = 0
    total_slots = len(selected_windows) * len(normalized_platforms)

    for window in selected_windows:
        current_week_index = int(window.get("week_index") or 0)
        window_label = str(window.get("label") or f"Week {current_week_index}").strip()
        for platform in normalized_platforms:
            slot_position += 1
            slot_key = f"week:{current_week_index}|platform:{platform}"
            requested_runs.append(
                {
                    "slot_key": slot_key,
                    "week_index": current_week_index,
                    "week_label": window_label,
                    "platform": platform,
                }
            )
            existing_run = existing_runs_by_slot.get(slot_key)
            if existing_run and str(existing_run.get("status") or "").strip().lower() not in {"failed", "cancelled"}:
                reused_runs.append(existing_run)
                continue

            run_payload = ingest_season(
                season_id,
                platforms=[platform],
                accounts_override=accounts_override,
                hashtags_override=hashtags_override,
                keywords_override=keywords_override,
                source_scope=source_scope,
                sync_strategy=sync_strategy,
                max_posts_per_target=max_posts_per_target,
                max_comments_per_post=max_comments_per_post,
                max_replies_per_post=max_replies_per_post,
                fetch_replies=fetch_replies,
                ingest_mode=ingest_mode,
                date_start=_coerce_dt(window.get("date_start")),
                date_end=_coerce_dt(window.get("date_end")),
                comment_refresh_policy=comment_refresh_policy,
                comment_anchor_source_ids=comment_anchor_source_ids,
                sound_ids=sound_ids,
                runner_strategy=runner_strategy,
                runner_count=runner_count,
                window_shard_hours=window_shard_hours,
                runner_b_start_offset_hours=runner_b_start_offset_hours,
                day_weight_profile=day_weight_profile,
                priority_mode=priority_mode,
                youtube_source_mode=youtube_source_mode,
                youtube_force_reindex=youtube_force_reindex,
                youtube_force_media_refresh=youtube_force_media_refresh,
                youtube_force_comment_refresh=youtube_force_comment_refresh,
                week_index=current_week_index,
                window_timezone=timezone,
                run_scope_label=window_label,
                client_session_id=client_session_id,
                client_workflow_id=normalized_workflow_id,
                orchestration_metadata={
                    "orchestration_id": normalized_workflow_id,
                    "orchestration_scope": orchestration_scope,
                    "orchestration_slot_key": slot_key,
                    "orchestration_position": slot_position,
                    "orchestration_total_runs": total_slots,
                    "orchestration_week_index": current_week_index,
                    "orchestration_platform": platform,
                    "orchestration_week_label": window_label,
                },
                initiated_by=initiated_by,
                inline_worker_id=None,
            )
            created_runs.append(
                {
                    "run_id": str(run_payload.get("run_id") or "").strip() or None,
                    "status": str(run_payload.get("status") or "").strip() or None,
                    "execution_owner": str(run_payload.get("execution_owner") or "").strip() or None,
                    "execution_mode_canonical": (
                        str(run_payload.get("execution_mode_canonical") or "").strip() or None
                    ),
                    "slot_key": slot_key,
                    "week_index": current_week_index,
                    "week_label": window_label,
                    "platform": platform,
                }
            )

    return {
        "season_id": season_id,
        "orchestration_id": normalized_workflow_id,
        "scope": orchestration_scope,
        "resume_existing": bool(resume_existing),
        "weeks": selected_windows,
        "platforms": normalized_platforms,
        "requested_runs": requested_runs,
        "created_runs": created_runs,
        "reused_runs": reused_runs,
        "total_requested_runs": total_slots,
        "created_count": len(created_runs),
        "reused_count": len(reused_runs),
        **_configured_execution_metadata(),
    }


def preview_ingest_schedule(
    season_id: str,
    *,
    platforms: list[str] | None,
    source_scope: str,
    accounts_override: list[str] | None = None,
    ingest_mode: str = "posts_and_comments",
    max_comments_per_post: int | None = None,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
    runner_strategy: str | None = None,
    runner_count: int | None = None,
    window_shard_hours: int | None = None,
    runner_b_start_offset_hours: int | None = None,
    day_weight_profile: str | None = None,
    priority_mode: str | None = None,
    week_index: int | None = None,
    window_timezone: str | None = None,
    run_scope_label: str | None = None,
) -> dict[str, Any]:
    context = get_season_context(season_id)
    source_scope = normalize_source_scope(source_scope)
    normalized_mode = (ingest_mode or "posts_and_comments").strip().lower()
    if normalized_mode not in SUPPORTED_INGEST_MODES:
        raise ValueError(f"Unsupported ingest mode: {ingest_mode}")
    requested_platforms = _resolve_requested_platforms(platforms)

    normalized_accounts_override: list[str] = []
    invalid_overrides: list[str] = []
    for raw_account in [str(item or "").strip() for item in (accounts_override or []) if str(item or "").strip()]:
        normalized = _normalize_account_handle(raw_account)
        if not normalized:
            invalid_overrides.append(raw_account)
            continue
        if normalized in normalized_accounts_override:
            continue
        normalized_accounts_override.append(normalized)
    if invalid_overrides:
        raise SocialIngestValidationError(
            "INVALID_ACCOUNT_HANDLE",
            f"Invalid account handle override(s): {', '.join(sorted(set(invalid_overrides)))}",
        )

    schedule = _build_ingest_shard_schedule(
        date_start=date_start,
        date_end=date_end,
        runner_strategy=runner_strategy,
        runner_count=runner_count,
        window_shard_hours=window_shard_hours,
        runner_b_start_offset_hours=runner_b_start_offset_hours,
        day_weight_profile=day_weight_profile,
        priority_mode=priority_mode,
    )
    projected_shards = list(schedule.shards)
    if normalized_mode != "comments_only" and not projected_shards:
        fallback_start = _coerce_dt(date_start) or _now_utc()
        fallback_end = _coerce_dt(date_end)
        if fallback_end is None or fallback_end < fallback_start:
            fallback_end = fallback_start
        projected_shards = [
            IngestTimeShard(
                shard_index=0,
                window_start=fallback_start,
                window_end=fallback_end,
                runner_lane="A",
                priority_score=0.0,
                day_offset=0,
                day_weight=1.0,
            )
        ]

    account_map = _target_accounts_by_platform(season_id, source_scope=source_scope, context=context)
    effective_accounts_by_platform: dict[str, list[str]] = {}
    for platform in requested_platforms:
        authoritative_override = _use_authoritative_account_override(
            context=context,
            source_scope=source_scope,
            platform=platform,
            normalized_accounts_override=normalized_accounts_override,
        )
        merged_accounts = _normalize_unique_terms(
            [
                *sorted(account_map.get(platform, set())),
                *normalized_accounts_override,
            ]
        )
        if not authoritative_override:
            if platform == "instagram":
                merged_accounts = _ensure_rhoslc_instagram_accounts(context, merged_accounts)
            elif platform == "twitter":
                merged_accounts = _ensure_rhoslc_twitter_accounts(context, merged_accounts)
            merged_accounts = _ensure_bravo_core_platform_accounts(
                source_scope=source_scope,
                platform=platform,
                accounts=merged_accounts,
            )
            if not merged_accounts:
                merged_accounts = _default_platform_accounts(platform)
        effective_accounts_by_platform[platform] = merged_accounts

    projected_posts_jobs = 0
    projected_comments_jobs = 0
    per_platform_counts: dict[str, dict[str, int]] = {}
    for platform in requested_platforms:
        account_count = len(effective_accounts_by_platform.get(platform) or [])
        posts_jobs = account_count * (len(projected_shards) if normalized_mode != "comments_only" else 0)
        comments_jobs = (
            account_count
            if normalized_mode in {"posts_and_comments", "comments_only"} and int(max_comments_per_post or 0) > 0
            else 0
        )
        projected_posts_jobs += posts_jobs
        projected_comments_jobs += comments_jobs
        per_platform_counts[platform] = {
            "accounts": account_count,
            "posts_jobs": posts_jobs,
            "comments_jobs": comments_jobs,
        }

    day_weights_payload = {f"D+{offset}": round(weight, 4) for offset, weight in sorted(schedule.day_weights.items())}
    dominant_day = max(schedule.day_weights.items(), key=lambda item: item[1])[0] if schedule.day_weights else 0
    lane_a = [shard for shard in projected_shards if shard.runner_lane == "A"]
    lane_b = [shard for shard in projected_shards if shard.runner_lane == "B"]
    return {
        "season_id": context.season_id,
        "show_id": context.show_id,
        "season_number": context.season_number,
        "source_scope": source_scope,
        "scope": {
            "type": _ingest_run_scope_type(
                week_index=week_index,
                date_start=_coerce_dt(date_start),
                date_end=_coerce_dt(date_end),
            ),
            "label": str(run_scope_label or "").strip() or None,
            "week_index": int(week_index) if week_index is not None else None,
            "timezone": str(window_timezone or "America/New_York").strip() or "America/New_York",
        },
        "ingest_mode": normalized_mode,
        "scheduler": {
            "strategy": schedule.strategy,
            "runner_count": schedule.runner_count,
            "window_shard_hours": schedule.window_shard_hours,
            "runner_b_start_offset_hours": schedule.runner_b_offset_hours,
            "day_weight_profile": schedule.day_weight_profile,
            "priority_mode": schedule.priority_mode,
            "busiest_day": f"D+{dominant_day}",
            "day_weights": day_weights_payload,
        },
        "date_window": {
            "start": _iso(_coerce_dt(date_start)),
            "end": _iso(_coerce_dt(date_end)),
        },
        "projected_counts": {
            "posts_jobs": projected_posts_jobs,
            "comments_jobs": projected_comments_jobs,
            "total_jobs": projected_posts_jobs + projected_comments_jobs,
            "by_platform": per_platform_counts,
        },
        "lanes": {
            "A": [
                {
                    "shard_index": shard.shard_index,
                    "window_start": _iso(shard.window_start),
                    "window_end": _iso(shard.window_end),
                    "priority_score": shard.priority_score,
                    "day_offset": shard.day_offset,
                    "day_weight": shard.day_weight,
                }
                for shard in lane_a
            ],
            "B": [
                {
                    "shard_index": shard.shard_index,
                    "window_start": _iso(shard.window_start),
                    "window_end": _iso(shard.window_end),
                    "priority_score": shard.priority_score,
                    "day_offset": shard.day_offset,
                    "day_weight": shard.day_weight,
                }
                for shard in lane_b
            ],
        },
    }


def cancel_run(season_id: str, run_id: str, *, cancelled_by: str | None = None) -> dict[str, Any]:
    _assert_social_queue_schema_ready()
    run_row = pg.fetch_one(
        """
        select id::text, season_id::text, status
        from social.scrape_runs
        where id = %s and season_id = %s
        """,
        [run_id, season_id],
    )
    if not run_row:
        raise ValueError("Run not found")

    pg.fetch_one(
        """
        update social.scrape_runs
        set
          status = 'cancelling',
          cancelled_at = now(),
          completed_at = null,
          summary = coalesce(summary, '{}'::jsonb) || jsonb_build_object('cancelled_by', %s)
        where id = %s
        returning id::text
        """,
        [cancelled_by, run_id],
    )
    cancelled_jobs = pg.execute_returning(
        """
        update social.scrape_jobs
        set
          status = case
            when status in ('running', 'cancelling') then 'cancelling'
            else 'cancelled'
          end,
          completed_at = case
            when status in ('running', 'cancelling') then completed_at
            else now()
          end,
          error_message = coalesce(error_message, 'Cancelled by user request'),
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
            'cancel_reason', 'run_cancelled_by_admin',
            'cancelled_by', %s::text,
            'cancelled_at', now()
          )
        where run_id = %s
          and status in ('queued', 'pending', 'retrying', 'running', 'cancelling')
        returning id::text, run_id::text as run_id, status
        """,
        [cancelled_by, run_id],
    )
    affected_job_ids = [str(row.get("id") or "").strip() for row in cancelled_jobs if str(row.get("id") or "").strip()]
    terminal_cancelled_job_ids = [
        str(row.get("id") or "").strip()
        for row in cancelled_jobs
        if str(row.get("id") or "").strip() and str(row.get("status") or "").strip().lower() == "cancelled"
    ]
    cancelling_job_ids = [
        str(row.get("id") or "").strip()
        for row in cancelled_jobs
        if str(row.get("id") or "").strip() and str(row.get("status") or "").strip().lower() == "cancelling"
    ]
    for job_id in terminal_cancelled_job_ids:
        _clear_worker_heartbeat_for_job(
            job_id=job_id,
            status="idle",
            metadata={"source": "cancel_run", "job_status": "cancelled"},
        )
    summary = _finalize_run_status(run_id, force_recompute=True)
    final_status = "cancelling" if cancelling_job_ids else "cancelled"
    if final_status == "cancelled":
        _invalidate_week_detail_cache_after_run_terminal_status()
    return {
        "run_id": run_id,
        "season_id": season_id,
        "status": final_status,
        "cancelled_jobs": len(affected_job_ids),
        "cancelled_job_ids": affected_job_ids,
        "cancelling_jobs": len(cancelling_job_ids),
        "cancelling_job_ids": cancelling_job_ids,
        "summary": summary,
    }


def requeue_media_mirror_jobs(
    season_id: str,
    *,
    platform: str,
    source_scope: str = "network",
    limit: int = 1000,
    failed_only: bool = False,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
) -> dict[str, Any]:
    normalized_platform = (platform or "").strip().lower()
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    source_id_column = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    posted_at_column = PLATFORM_POSTED_AT_COLUMN.get(normalized_platform)
    if not table or not source_id_column or not posted_at_column:
        raise ValueError(f"Unsupported platform: {platform}")

    context = get_season_context(season_id)
    safe_limit = max(1, min(int(limit), 5000))
    account_expr = (
        "coalesce(nullif(p.source_account, ''), nullif(p.channel_title, ''), '')"
        if normalized_platform == "youtube"
        else "coalesce(nullif(p.source_account, ''), nullif(p.username, ''), '')"
    )
    thumbnail_expr = (
        "coalesce(nullif(p.media_urls ->> 0, ''), '')"
        if normalized_platform == "twitter"
        else "coalesce(nullif(p.thumbnail_url, ''), '')"
    )
    media_urls_expr = "p.media_urls" if _platform_posts_has_column(normalized_platform, "media_urls") else "'[]'::jsonb"
    start_dt = _coerce_dt(date_start)
    end_dt = _coerce_dt(date_end)
    if start_dt and end_dt and end_dt < start_dt:
        end_dt = start_dt
    window_filter = ""
    params: list[Any] = [season_id]
    if start_dt:
        window_filter += f" and p.{posted_at_column} >= %s"
        params.append(start_dt)
    if end_dt:
        window_filter += f" and p.{posted_at_column} <= %s"
        params.append(end_dt)
    params.append(safe_limit)
    rows = pg.fetch_all(
        f"""
        select
          p.id::text as id,
          p.{source_id_column} as source_id,
          {account_expr} as account,
          p.{posted_at_column} as posted_at,
          {thumbnail_expr} as thumbnail_url,
          {media_urls_expr} as media_urls,
          coalesce(to_jsonb(p) ->> 'hosted_thumbnail_url', '') as hosted_thumbnail_url,
          coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
          coalesce(to_jsonb(p) ->> 'media_mirror_status', '') as media_mirror_status,
          coalesce(to_jsonb(p) ->> 'media_mirror_error', '') as media_mirror_error,
          coalesce(to_jsonb(p) ->> 'user_avatar_url', '') as user_avatar_url,
          coalesce(to_jsonb(p) ->> 'hosted_user_avatar_url', '') as hosted_user_avatar_url,
          coalesce(to_jsonb(p) ->> 'owner_profile_pic_url', '') as owner_profile_pic_url,
          coalesce(to_jsonb(p) ->> 'hosted_owner_profile_pic_url', '') as hosted_owner_profile_pic_url,
          coalesce(to_jsonb(p) -> 'hosted_tagged_profile_pics', '{{}}'::jsonb) as hosted_tagged_profile_pics,
          coalesce(to_jsonb(p) -> 'asset_manifest', '{{}}'::jsonb) as asset_manifest,
          coalesce(to_jsonb(p) -> 'raw_data', '{{}}'::jsonb) as raw_data
        from social.{table} p
        where p.season_id = %s
          {window_filter}
        order by coalesce(p.{posted_at_column}, p.scraped_at) desc
        limit %s
        """,
        params,
    )

    try:
        week_windows, _ = _resolve_week_windows(
            context,
            timezone="America/New_York",
            source_scope=source_scope,
            now_utc=_now_utc(),
        )
    except Exception:  # noqa: BLE001
        week_windows = []

    scanned = 0
    queued = 0
    skipped = 0
    failed = 0
    with pg.db_connection() as conn:
        for row in rows:
            scanned += 1
            mirror_status = str(row.get("media_mirror_status") or "").strip().lower()
            if failed_only and mirror_status not in {"failed", "partial"}:
                skipped += 1
                continue
            if not _platform_post_needs_media_mirror(normalized_platform, row, conn=conn):
                skipped += 1
                continue
            week_index: int | None = None
            posted_at = _coerce_dt(row.get("posted_at"))
            if posted_at and week_windows:
                week_window = _week_for_timestamp(posted_at, windows=week_windows, timezone="America/New_York")
                week_index = week_window.week_index if week_window else None
            try:
                job_id = _enqueue_platform_media_mirror_job(
                    context,
                    platform=normalized_platform,
                    run_id=None,
                    source_scope=source_scope,
                    account=str(row.get("account") or ""),
                    post_row=row,
                    week_index=week_index,
                    parent_job_id=f"manual-{normalized_platform}-mirror-requeue",
                    conn=conn,
                )
            except Exception:  # noqa: BLE001
                failed += 1
                logger.exception(
                    "[%s] Failed to enqueue mirror requeue job for post=%s source_id=%s",
                    normalized_platform,
                    str(row.get("id") or ""),
                    str(row.get("source_id") or ""),
                )
                continue
            if job_id:
                queued += 1
            else:
                skipped += 1
    return {
        "season_id": season_id,
        "platform": normalized_platform,
        "source_scope": source_scope,
        "failed_only": bool(failed_only),
        "window_applied": bool(start_dt or end_dt),
        "window": {
            "start": _iso(start_dt),
            "end": _iso(end_dt),
        },
        "eligible_in_window": len(rows),
        "scanned": scanned,
        "queued_jobs": queued,
        "skipped": skipped,
        "failed": failed,
    }


