# Post detail — all comments for a single post, threaded


def _thread_comments(flat: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Group flat comment list into threaded tree: top-level first, replies nested."""
    by_id: dict[Any, dict[str, Any]] = {}
    roots: list[dict[str, Any]] = []
    for c in flat:
        node = {**c, "replies": []}
        by_id[c["id"]] = node

    for c in flat:
        node = by_id[c["id"]]
        parent = c.get("parent_comment_id")
        if parent and parent in by_id:
            by_id[parent]["replies"].append(node)
        else:
            roots.append(node)

    return roots


def _normalize_week_totals_payload(
    totals: Mapping[str, Any] | None, *, total_posts: int | None = None
) -> dict[str, Any]:
    source = totals if isinstance(totals, Mapping) else {}
    posts_value = int(total_posts if total_posts is not None else source.get("posts") or 0)
    return {
        "posts": posts_value,
        "total_comments": int(source.get("total_comments") or 0),
        "total_engagement": int(source.get("total_engagement") or 0),
        "expected_comments_total": int(source.get("expected_comments_total") or 0),
        "saved_comments_total": int(source.get("saved_comments_total") or 0),
        "comments_saved_pct": float(source.get("comments_saved_pct") or 0.0),
    }


def _serialize_comment_tree(node: dict[str, Any]) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "comment_id": node.get("comment_id") or "",
        "author": node.get("author") or "",
        "text": node.get("text") or "",
        "likes": node.get("likes", 0),
        "is_reply": node.get("is_reply", False),
        "reply_count": node.get("reply_count", 0),
        "created_at": _iso(node.get("created_at")),
        "replies": [_serialize_comment_tree(r) for r in node.get("replies", [])],
    }
    comment_row_id = str(node.get("id") or "").strip() or None
    if comment_row_id:
        payload["id"] = comment_row_id
    parent_comment_id = str(node.get("parent_comment_id") or "").strip() or None
    if parent_comment_id:
        payload["parent_comment_id"] = parent_comment_id
    media_urls = _as_text_list(node.get("media_urls"))
    hosted_media_urls = _as_text_list(node.get("hosted_media_urls"))
    if media_urls:
        payload["media_urls"] = media_urls
    if hosted_media_urls:
        payload["hosted_media_urls"] = hosted_media_urls
    media_mirror_status = str(node.get("media_mirror_status") or "").strip() or None
    if media_mirror_status:
        payload["media_mirror_status"] = media_mirror_status

    for key in (
        "comment_language",
        "aweme_id",
        "parent_source_comment_id",
        "is_author_liked",
        "author_full_name",
        "author_profile_pic_url",
        "hosted_author_profile_pic_url",
        "author_profile_pic_url_hd",
        "author_is_verified",
        "parent_comment_external_id",
        "reply_depth",
        "source_snapshot_type",
    ):
        if key in node:
            payload[key] = node.get(key)

    user_payload = {
        "id": str(node.get("user_id") or "").strip() or None,
        "username": str(node.get("author") or "").strip() or None,
        "display_name": str(
            node.get("display_name") or node.get("nickname") or node.get("author_full_name") or ""
        ).strip()
        or None,
        "url": str(node.get("user_url") or "").strip() or None,
        "bio": str(node.get("user_bio") or "").strip() or None,
        "avatar_url": str(
            node.get("hosted_author_profile_pic_url")
            or node.get("author_profile_pic_url")
            or node.get("user_avatar_url")
            or ""
        ).strip()
        or None,
        "source_avatar_url": str(node.get("author_profile_pic_url") or "").strip() or None,
        "profile_pic_url_hd": str(node.get("author_profile_pic_url_hd") or "").strip() or None,
        "is_verified": node.get("author_is_verified"),
        "region": str(node.get("user_region") or "").strip() or None,
        "language": str(node.get("user_language") or "").strip() or None,
    }
    if any(value for value in user_payload.values()):
        payload["user"] = user_payload
    return payload


def _social_discussion_item_sort_key(item: Mapping[str, Any]) -> tuple[int, datetime, str]:
    created_at = _social_account_profile_row_datetime(item.get("created_at"))
    return (
        1 if created_at is not None else 0,
        created_at or datetime.min.replace(tzinfo=UTC),
        str(item.get("comment_id") or item.get("id") or "").strip(),
    )


def _append_social_discussion_nodes(
    target: list[dict[str, Any]],
    nodes: Sequence[Mapping[str, Any]] | None,
    *,
    platform: str,
    post_id: str | None,
    post_source_id: str | None,
    post_url: str | None,
    discussion_kind: Literal["comment", "quote"],
) -> None:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    for node in nodes or []:
        user = _metadata_dict(node.get("user"))
        author = str(node.get("author") or user.get("username") or "").strip() or None
        item: dict[str, Any] = {
            "id": str(node.get("id") or node.get("comment_id") or "").strip(),
            "comment_id": str(node.get("comment_id") or "").strip(),
            "post_id": str(post_id or "").strip() or None,
            "post_source_id": str(post_source_id or "").strip() or None,
            "post_url": post_url,
            "discussion_kind": discussion_kind,
            "platform": normalized_platform,
            "username": author,
            "author": author,
            "display_name": str(node.get("display_name") or user.get("display_name") or "").strip() or None,
            "text": str(node.get("text") or ""),
            "likes": _normalize_non_negative_int(node.get("likes")),
            "is_reply": bool(node.get("is_reply")) if discussion_kind == "comment" else False,
            "created_at": node.get("created_at"),
            "parent_comment_id": str(node.get("parent_comment_id") or "").strip() or None,
            "reply_count": _normalize_non_negative_int(node.get("reply_count")),
            "url": str(node.get("url") or "").strip() or None,
        }
        for key in (
            "media_urls",
            "hosted_media_urls",
            "media_mirror_status",
            "comment_language",
            "aweme_id",
            "parent_source_comment_id",
            "is_author_liked",
            "retweets",
            "reposts",
            "quotes",
            "views",
        ):
            if key in node:
                item[key] = node.get(key)
        if user:
            item["user"] = user
        target.append(item)
        replies = node.get("replies")
        if isinstance(replies, list) and replies:
            _append_social_discussion_nodes(
                target,
                replies,
                platform=normalized_platform,
                post_id=post_id,
                post_source_id=post_source_id,
                post_url=post_url,
                discussion_kind=discussion_kind,
            )


def _social_discussion_items_from_post_detail(
    platform: str,
    detail_payload: Mapping[str, Any],
    *,
    post_id: str | None = None,
    post_source_id: str | None = None,
    post_url: str | None = None,
) -> list[dict[str, Any]]:
    items: list[dict[str, Any]] = []
    _append_social_discussion_nodes(
        items,
        detail_payload.get("comments") if isinstance(detail_payload.get("comments"), list) else [],
        platform=platform,
        post_id=post_id,
        post_source_id=post_source_id,
        post_url=post_url,
        discussion_kind="comment",
    )
    _append_social_discussion_nodes(
        items,
        detail_payload.get("quotes") if isinstance(detail_payload.get("quotes"), list) else [],
        platform=platform,
        post_id=post_id,
        post_source_id=post_source_id,
        post_url=post_url,
        discussion_kind="quote",
    )
    return sorted(items, key=_social_discussion_item_sort_key, reverse=True)


def _fetch_instagram_post_comment_detail_payload(
    post_id: str | None,
    *,
    source_id: str | None = None,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    """Return threaded Instagram comments by materialized post id for account catalog detail reads."""
    normalized_post_id = str(post_id or "").strip()
    if not normalized_post_id:
        return None
    sql = """
        select c.id, c.comment_id, c.parent_comment_id,
               c.username as author,
               c.user_id,
               nullif(coalesce(to_jsonb(c) ->> 'author_full_name', ''), '') as author_full_name,
               nullif(coalesce(to_jsonb(c) ->> 'author_profile_pic_url', ''), '') as author_profile_pic_url,
               nullif(
                 coalesce(to_jsonb(c) ->> 'hosted_author_profile_pic_url', ''),
                 ''
               ) as hosted_author_profile_pic_url,
               nullif(coalesce(to_jsonb(c) ->> 'author_profile_pic_url_hd', ''), '') as author_profile_pic_url_hd,
               case
                 when lower(coalesce(to_jsonb(c) ->> 'author_is_verified', '')) in ('true', 'false')
                 then (to_jsonb(c) ->> 'author_is_verified')::boolean
                 else null
               end as author_is_verified,
               nullif(
                 coalesce(to_jsonb(c) ->> 'parent_comment_external_id', ''),
                 ''
               ) as parent_comment_external_id,
               nullif(coalesce(to_jsonb(c) ->> 'source_snapshot_type', ''), '') as source_snapshot_type,
               case
                 when coalesce(to_jsonb(c) ->> 'reply_depth', '') ~ '^[0-9]+$'
                 then (to_jsonb(c) ->> 'reply_depth')::int
                 else null
               end as reply_depth,
               c.text,
               coalesce(c.likes, 0) as likes,
               coalesce(c.is_reply, false) as is_reply,
               coalesce(c.reply_count, 0) as reply_count,
               coalesce(to_jsonb(c) -> 'media_urls', '[]'::jsonb) as media_urls,
               coalesce(to_jsonb(c) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
               nullif(coalesce(to_jsonb(c) ->> 'media_mirror_status', ''), '') as media_mirror_status,
               c.created_at
        from social.instagram_comments c
        where c.post_id = %s
          and coalesce(c.is_missing, false) = false
        order by c.likes desc nulls last, c.created_at asc
    """
    if conn is not None:
        with pg.db_cursor(conn=conn, label="instagram_post_comment_detail") as cur:
            comments = pg.fetch_all_with_cursor(cur, sql, [normalized_post_id])
    else:
        comments = pg.fetch_all(sql, [normalized_post_id])
    return {
        "platform": "instagram",
        "source_id": str(source_id or "").strip() or None,
        "total_comments_in_db": len(comments),
        "comments": [_serialize_comment_tree(node) for node in _thread_comments(comments)],
    }


