_SOCIAL_ACCOUNT_PROFILE_DEFAULT_PAGE_SIZE = 25
_SOCIAL_ACCOUNT_PROFILE_MAX_PAGE_SIZE = 100
_SOCIAL_ACCOUNT_PROFILE_HANDLE_ALIASES = {
    "wwhlbravo": "bravowwhl",
}
_SOCIAL_ACCOUNT_PROFILE_SHARED_HASHTAG_ASSIGNMENT_PLATFORMS = (
    "instagram",
    "tiktok",
    "twitter",
    "youtube",
    "facebook",
    "threads",
)
_SOCIAL_ACCOUNT_PROFILE_SHOW_EXTERNAL_ID_KEYS: dict[str, tuple[str, ...]] = {
    "facebook": ("facebook_handle", "facebook", "facebook_id"),
    "instagram": ("instagram_handle", "instagram", "instagram_id"),
    "threads": ("threads_handle", "threads", "threads_id"),
    "tiktok": ("tiktok_handle", "tiktok", "tiktok_id"),
    "twitter": ("twitter_handle", "twitter", "x_handle", "twitter_id", "x_id"),
    "youtube": ("youtube_handle", "youtube", "youtube_id"),
}


def _normalize_social_account_profile_platform(platform: Any) -> str:
    normalized = _normalize_platform_name(platform)
    if normalized not in SUPPORTED_PLATFORMS:
        supported = ", ".join(SUPPORTED_PLATFORMS)
        raise ValueError(
            f"INVALID_PLATFORM_FILTER: Unsupported platform '{platform}'. Supported platforms: {supported}"
        )
    return normalized


def _normalize_social_account_profile_handle(account_handle: Any) -> str:
    normalized = _normalize_account_handle(account_handle)
    if not normalized or not GENERIC_ACCOUNT_HANDLE_RE.match(normalized):
        raise ValueError("Invalid account handle.")
    return _SOCIAL_ACCOUNT_PROFILE_HANDLE_ALIASES.get(normalized, normalized)


def _normalize_social_account_profile_hashtag(value: Any) -> str:
    normalized = str(value or "").strip().lower().lstrip("#")
    normalized = re.sub(r"[^a-z0-9_]+", "", normalized)
    if not normalized:
        raise ValueError("Invalid hashtag.")
    return normalized


def _social_account_profile_post_url(platform: str, row: Mapping[str, Any], *, account_handle: str) -> str | None:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    explicit = _first_non_empty_str(
        row.get("post_url"),
        row.get("permalink"),
        row.get("permalink_url"),
        row.get("canonical_url"),
        row.get("url"),
        row.get("link"),
    )
    if explicit and explicit.startswith(("http://", "https://")):
        return explicit

    if normalized_platform == "instagram":
        shortcode = str(row.get("shortcode") or row.get("source_id") or "").strip()
        if shortcode:
            return f"https://www.instagram.com/p/{shortcode}/"
    elif normalized_platform == "tiktok":
        video_id = str(row.get("video_id") or row.get("source_id") or "").strip()
        if video_id:
            return f"https://www.tiktok.com/@{account_handle}/video/{video_id}"
    elif normalized_platform == "twitter":
        tweet_id = str(row.get("tweet_id") or row.get("source_id") or "").strip()
        if tweet_id:
            return f"https://x.com/{account_handle}/status/{tweet_id}"
    elif normalized_platform == "youtube":
        video_id = str(row.get("video_id") or "").strip()
        if video_id:
            return f"https://www.youtube.com/watch?v={video_id}"
    elif normalized_platform == "facebook":
        post_id = str(row.get("post_id") or row.get("source_id") or "").strip()
        if post_id:
            return f"https://www.facebook.com/{account_handle}/posts/{post_id}"
    elif normalized_platform == "threads":
        post_id = str(row.get("post_id") or row.get("source_id") or "").strip()
        if post_id:
            return f"https://www.threads.com/@{account_handle}/post/{post_id}"
    return None


def _social_account_profile_title_text(platform: str, row: Mapping[str, Any]) -> str | None:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "youtube":
        return _first_non_empty_str(row.get("title"))
    return _first_non_empty_str(row.get("title"), row.get("headline"))


def _social_account_profile_content_text(platform: str, row: Mapping[str, Any]) -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "instagram":
        raw_data = _metadata_dict(row.get("raw_data"))
        raw_caption = raw_data.get("caption")
        raw_caption_text = raw_caption.get("text") if isinstance(raw_caption, Mapping) else raw_caption
        return str(
            _first_non_empty_str(
                row.get("caption"),
                row.get("text"),
                raw_caption_text,
                raw_data.get("caption_text"),
                raw_data.get("text"),
            )
            or ""
        )
    if normalized_platform == "tiktok":
        raw_data = _metadata_dict(row.get("raw_data"))
        return str(
            _first_non_empty_str(
                row.get("description"),
                row.get("caption"),
                row.get("text"),
                raw_data.get("description"),
                raw_data.get("caption"),
                raw_data.get("text"),
            )
            or ""
        )
    if normalized_platform == "twitter":
        return str(_first_non_empty_str(row.get("text"), row.get("full_text")) or "")
    if normalized_platform == "youtube":
        return str(_first_non_empty_str(row.get("description"), row.get("title")) or "")
    if normalized_platform == "facebook":
        return str(_first_non_empty_str(row.get("caption"), row.get("text"), row.get("message")) or "")
    if normalized_platform == "threads":
        return str(_first_non_empty_str(row.get("text"), row.get("caption")) or "")
    return str(_first_non_empty_str(row.get("text"), row.get("caption"), row.get("description")) or "")


def _social_account_profile_hashtags_for_row(platform: str, row: Mapping[str, Any]) -> list[str]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    token_text = " ".join(
        filter(
            None,
            [
                _social_account_profile_title_text(normalized_platform, row),
                _social_account_profile_content_text(normalized_platform, row),
            ],
        )
    )
    stored = _json_text_list(row.get("hashtags"), strip_prefix="#")
    if normalized_platform == "youtube":
        stored = _normalize_unique_terms([*stored, *_as_text_list(row.get("tags"), strip_prefix="#")])
    if stored:
        return stored
    return _normalize_unique_terms(_parse_hashtags(token_text))


def _normalize_social_account_profile_handle_term(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    candidate = raw.lstrip("@").strip()
    candidate = candidate.lstrip("([{<'\"“‘")
    candidate = candidate.rstrip(".,:;!?)]}>'\"”’")
    normalized = _normalize_account_handle(candidate)
    return f"@{normalized}" if normalized else ""


def _canonicalize_social_account_profile_mention_identity(value: Any) -> str:
    raw = str(value or "").strip().lower()
    if not raw:
        return ""
    raw = raw.lstrip("@#")
    return re.sub(r"[^a-z0-9]+", "", raw)


def _normalize_social_account_profile_hashtag_term(value: Any) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    candidate = raw.lstrip("#").strip()
    candidate = candidate.lstrip("([{<'\"“‘")
    candidate = candidate.rstrip(".,:;!?)]}>'\"”’")
    try:
        normalized = _normalize_social_account_profile_hashtag(candidate)
    except ValueError:
        return ""
    return normalized


def _parse_social_account_profile_display_mentions(text: str | None) -> list[str]:
    if not text:
        return []
    matches = re.findall(r"(?<![\w.])@([A-Za-z0-9_.]+(?:\s+[A-Z][A-Za-z0-9_.]*){0,3})", text)
    values: list[str] = []
    for match in matches:
        candidate = f"@{str(match or '').strip()}"
        candidate = candidate.rstrip(".,:;!?)]}>'\"”’")
        if candidate and candidate != "@":
            values.append(candidate)
    return _normalize_unique_terms(values)


def _social_account_profile_display_mention_alias(display_mention: str | None) -> str:
    raw = str(display_mention or "").strip()
    if not raw:
        return ""
    first_token = raw.lstrip("@").split()[0].strip()
    return _normalize_social_account_profile_handle_term(first_token)


def _build_social_account_profile_known_handle_identity_index(
    platform: str,
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, set[str]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform != "tiktok":
        return {}
    known_handles: dict[str, set[str]] = defaultdict(set)
    for row in rows:
        row_hashtag_identities = {
            _canonicalize_social_account_profile_mention_identity(value)
            for value in _social_account_profile_hashtags_for_row(normalized_platform, row)
            if _canonicalize_social_account_profile_mention_identity(value)
        }
        for value in _as_text_list(row.get("mentions")):
            normalized = _normalize_social_account_profile_handle_term(value)
            if not normalized:
                continue
            identity = _canonicalize_social_account_profile_mention_identity(normalized)
            handle = _normalize_account_handle(normalized)
            if identity and identity in row_hashtag_identities:
                continue
            if identity and handle:
                known_handles[identity].add(handle)
    return known_handles


def _social_account_profile_mentions_for_row(
    platform: str,
    row: Mapping[str, Any],
    *,
    known_handle_identity_index: Mapping[str, set[str]] | None = None,
) -> list[str]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    mention_values = _as_text_list(row.get("mentions"))
    stored = [
        normalized
        for normalized in (_normalize_social_account_profile_handle_term(value) for value in mention_values)
        if normalized
    ]
    token_text = " ".join(
        filter(
            None,
            [
                _social_account_profile_title_text(normalized_platform, row),
                _social_account_profile_content_text(normalized_platform, row),
            ],
        )
    )
    parsed = _normalize_unique_terms(_parse_mentions(token_text))
    if normalized_platform != "tiktok":
        if stored:
            return _normalize_unique_terms(stored)
        return parsed

    hashtag_identities = {
        _canonicalize_social_account_profile_mention_identity(value)
        for value in _social_account_profile_hashtags_for_row(normalized_platform, row)
        if _canonicalize_social_account_profile_mention_identity(value)
    }
    resolved_handles: list[str] = []
    suppressed_aliases: set[str] = set()
    suppressed_joined_identities: set[str] = set()
    for display_mention in _parse_social_account_profile_display_mentions(token_text):
        identity = _canonicalize_social_account_profile_mention_identity(display_mention)
        candidates = sorted((known_handle_identity_index or {}).get(identity) or [])
        if len(candidates) != 1:
            continue
        resolved_handle = _normalize_social_account_profile_handle_term(candidates[0])
        if not resolved_handle:
            continue
        resolved_handles.append(resolved_handle)
        resolved_identity = _canonicalize_social_account_profile_mention_identity(resolved_handle)
        alias_handle = _social_account_profile_display_mention_alias(display_mention)
        if alias_handle and alias_handle.lower() != resolved_handle.lower():
            suppressed_aliases.add(alias_handle.lower())
        if resolved_identity:
            suppressed_joined_identities.add(f"{resolved_identity}and")

    combined = [*stored, *parsed, *resolved_handles]
    repaired_handles: list[str] = []
    for value in combined:
        normalized_value = _normalize_social_account_profile_handle_term(value)
        if not normalized_value:
            continue
        identity = _canonicalize_social_account_profile_mention_identity(normalized_value)
        if identity.endswith("and"):
            trimmed_identity = identity[: -len("and")]
            candidates = sorted((known_handle_identity_index or {}).get(trimmed_identity) or [])
            if len(candidates) == 1 and trimmed_identity in hashtag_identities:
                repaired_handles.append(_normalize_social_account_profile_handle_term(candidates[0]))
                continue
        repaired_handles.append(normalized_value)
    if suppressed_aliases or suppressed_joined_identities:
        repaired_handles = [
            value
            for value in repaired_handles
            if str(value or "").strip().lower() not in suppressed_aliases
            and _canonicalize_social_account_profile_mention_identity(value) not in suppressed_joined_identities
        ]
    repaired_handles = [
        value
        for value in repaired_handles
        if (
            _canonicalize_social_account_profile_mention_identity(value) not in hashtag_identities
            or _canonicalize_social_account_profile_mention_identity(value)
            in set((known_handle_identity_index or {}).keys())
        )
    ]
    return _normalize_unique_terms(repaired_handles)


def _social_account_profile_collaborators_for_row(row: Mapping[str, Any]) -> list[str]:
    collaborator_values = _as_text_list(row.get("collaborators"))
    collaborators = [
        normalized
        for normalized in (_normalize_social_account_profile_handle_term(value) for value in collaborator_values)
        if normalized
    ]
    for detail in _as_json_object_list(row.get("collaborators_detail")):
        handle = _normalize_social_account_profile_handle_term(_detail_handle_from_payload(detail))
        if handle:
            collaborators.append(handle)
    return _normalize_unique_terms(collaborators)


def _social_account_profile_tags_for_row(_platform: str, row: Mapping[str, Any]) -> list[str]:
    profile_tag_values = _as_text_list(row.get("profile_tags"))
    profile_tags = [
        normalized
        for normalized in (_normalize_social_account_profile_handle_term(value) for value in profile_tag_values)
        if normalized
    ]
    return _normalize_unique_terms(profile_tags)


def _social_account_profile_search_terms_for_post_item(item: Mapping[str, Any]) -> dict[str, Any]:
    text_fields = [
        str(item.get("title") or ""),
        str(item.get("content") or ""),
        str(item.get("excerpt") or ""),
        str(item.get("show_name") or ""),
        str(item.get("url") or ""),
    ]
    hashtag_values = item.get("hashtags") or []
    mention_values = item.get("mentions") or []
    collaborator_values = item.get("collaborators") or []
    tag_values = item.get("tags") or []
    hashtags = [
        normalized
        for normalized in (_normalize_social_account_profile_hashtag_term(value) for value in hashtag_values)
        if normalized
    ]
    mentions = [
        normalized
        for normalized in (_normalize_social_account_profile_handle_term(value) for value in mention_values)
        if normalized
    ]
    collaborators = [
        normalized
        for normalized in (_normalize_social_account_profile_handle_term(value) for value in collaborator_values)
        if normalized
    ]
    tags = [
        normalized
        for normalized in (_normalize_social_account_profile_handle_term(value) for value in tag_values)
        if normalized
    ]
    handles = _normalize_unique_terms([*mentions, *collaborators, *tags])
    return {
        "text": " ".join(text_fields).lower(),
        "hashtags": {value.lower() for value in hashtags},
        "handles": {value.lower() for value in handles},
        "handle_words": {value.lstrip("@").lower() for value in handles},
    }


def _social_account_profile_post_matches_search(item: Mapping[str, Any], query: str) -> bool:
    normalized_query = str(query or "").strip().lower()
    if not normalized_query:
        return True
    search_terms = _social_account_profile_search_terms_for_post_item(item)
    if normalized_query.startswith("@"):
        exact_handle = _normalize_social_account_profile_handle_term(normalized_query).lower()
        return bool(exact_handle and exact_handle in search_terms["handles"])
    if normalized_query.startswith("#"):
        exact_hashtag = _normalize_social_account_profile_hashtag_term(normalized_query).lower()
        return bool(exact_hashtag and exact_hashtag in search_terms["hashtags"])
    if normalized_query in search_terms["text"]:
        return True
    return normalized_query in search_terms["hashtags"] or normalized_query in search_terms["handle_words"]


_INSTAGRAM_PROFILE_REPOST_METRIC_KEYS = (
    "media_repost_count",
    "reshare_count",
    "reshareCount",
    "repost_count",
    "repostCount",
    "share_count",
    "shareCount",
    "shares",
)
_INSTAGRAM_PROFILE_VIDEO_VIEW_METRIC_KEYS = (
    "video_view_count",
    "videoViewCount",
    "view_count",
    "viewCount",
    "views",
    "video_play_count",
    "videoPlayCount",
    "play_count",
)


def _optional_non_negative_int(value: Any) -> int | None:
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, str) and not value.strip():
        return None
    try:
        if isinstance(value, float) and not value.is_integer():
            return None
        parsed = int(str(value).replace(",", "").strip() if isinstance(value, str) else value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed >= 0 else None


def _instagram_profile_metric_containers(row: Mapping[str, Any]) -> list[Mapping[str, Any]]:
    containers: list[Mapping[str, Any]] = [row]
    raw_data = _metadata_dict(row.get("raw_data"))
    if raw_data:
        containers.append(raw_data)
        node = raw_data.get("node")
        if isinstance(node, Mapping):
            containers.append(node)
        items = raw_data.get("items")
        if isinstance(items, list):
            containers.extend(item for item in items if isinstance(item, Mapping))
    return containers


def _instagram_profile_first_metric(row: Mapping[str, Any], aliases: Sequence[str]) -> int | None:
    containers = _instagram_profile_metric_containers(row)
    for alias in aliases:
        for container in containers:
            if alias not in container:
                continue
            parsed = _optional_non_negative_int(container.get(alias))
            if parsed is not None:
                return parsed
    return None


def _social_account_profile_metric_payload(platform: str, row: Mapping[str, Any]) -> dict[str, int | None]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    likes = _normalize_non_negative_int(row.get("likes"))
    comments = _normalize_non_negative_int(row.get("comments_count"))
    views = _normalize_non_negative_int(row.get("views"))
    shares = _normalize_non_negative_int(row.get("shares"))
    retweets = _normalize_non_negative_int(row.get("retweets"))
    replies = _normalize_non_negative_int(row.get("replies_count"))
    quotes = _normalize_non_negative_int(row.get("quotes"))
    if normalized_platform == "instagram":
        reposts = _instagram_profile_first_metric(row, _INSTAGRAM_PROFILE_REPOST_METRIC_KEYS)
        if reposts is None:
            reposts = shares
        video_views = _instagram_profile_first_metric(row, _INSTAGRAM_PROFILE_VIDEO_VIEW_METRIC_KEYS)
        if video_views is None:
            video_views = views
        return {
            "likes": likes,
            "comments_count": comments,
            "views": views,
            "video_views": video_views,
            "shares": reposts,
            "reposts": reposts,
            "retweets": retweets,
            "replies_count": replies,
            "quotes": quotes,
            "saves": None,
            "engagement": likes + comments + reposts + retweets + replies + quotes,
        }
    engagement = likes + comments + shares + retweets + replies + quotes
    payload: dict[str, int | None] = {
        "likes": likes,
        "comments_count": comments,
        "views": views,
        "shares": shares,
        "retweets": retweets,
        "replies_count": replies,
        "quotes": quotes,
        "engagement": engagement,
    }
    if normalized_platform == "youtube":
        payload["engagement"] = likes + comments
    return cast(dict[str, int | None], payload)


def _social_account_profile_post_item(
    platform: str,
    row: Mapping[str, Any],
    *,
    account_handle: str,
    known_handle_identity_index: Mapping[str, set[str]] | None = None,
) -> dict[str, Any]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    metrics = _social_account_profile_metric_payload(platform, row)
    hashtags = _social_account_profile_hashtags_for_row(platform, row)
    collaborators = _social_account_profile_collaborators_for_row(row)
    tags = _social_account_profile_tags_for_row(platform, row)
    title = _social_account_profile_title_text(platform, row)
    content = _social_account_profile_content_text(platform, row)
    excerpt = content[:280].strip()
    source_media_urls = _as_text_list(row.get("source_media_urls")) or _as_text_list(row.get("media_urls"))
    hosted_media_urls = _as_text_list(row.get("hosted_media_urls"))
    thumbnail_url = _first_non_empty_str(row.get("thumbnail_url"))
    source_thumbnail_url = _first_non_empty_str(row.get("source_thumbnail_url"), thumbnail_url)
    hosted_thumbnail_url = _first_non_empty_str(row.get("hosted_thumbnail_url"))
    media_selection = _effective_post_media_selection(
        normalized_platform,
        row,
        source_thumbnail_url=source_thumbnail_url,
        source_media_urls=source_media_urls,
        hosted_thumbnail_url=hosted_thumbnail_url,
        hosted_media_urls=hosted_media_urls,
    )
    effective_hosted_media_urls = list(media_selection["hosted_media_urls"])
    effective_hosted_thumbnail_url = media_selection["hosted_thumbnail_url"]
    media_urls = list(media_selection["media_urls"])
    post_format = _first_non_empty_str(row.get("post_format"), row.get("media_type"))
    display_thumbnail = _build_display_thumbnail_payload(
        asset_manifest=_extract_platform_post_asset_manifest(normalized_platform, dict(row)),
        hosted_thumbnail_url=effective_hosted_thumbnail_url,
        source_thumbnail_url=source_thumbnail_url,
        hosted_media_urls=effective_hosted_media_urls,
        source_media_urls=source_media_urls,
    )
    payload = {
        "id": str(row.get("id") or ""),
        "source_id": str(row.get("source_id") or ""),
        "platform": normalized_platform,
        "account_handle": account_handle,
        "title": title,
        "content": content,
        "excerpt": excerpt if excerpt else title,
        "url": _social_account_profile_post_url(platform, row, account_handle=account_handle),
        "profile_url": _platform_profile_url_for_handle(platform, account_handle),
        "posted_at": row.get("posted_at"),
        "show_id": str(row.get("show_id") or "") or None,
        "show_name": row.get("show_name"),
        "show_slug": row.get("show_slug"),
        "season_id": str(row.get("season_id") or "") or None,
        "season_number": _normalize_non_negative_int(row.get("season_number")) or None,
        "hashtags": hashtags,
        "mentions": _social_account_profile_mentions_for_row(
            platform,
            row,
            known_handle_identity_index=known_handle_identity_index,
        ),
        "collaborators": collaborators,
        "tags": tags,
        "metrics": metrics,
        **display_thumbnail,
    }
    if media_selection["thumbnail_url"]:
        payload["thumbnail_url"] = media_selection["thumbnail_url"]
    if source_thumbnail_url:
        payload["source_thumbnail_url"] = source_thumbnail_url
    if effective_hosted_thumbnail_url:
        payload["hosted_thumbnail_url"] = effective_hosted_thumbnail_url
    if source_media_urls:
        payload["source_media_urls"] = source_media_urls
    if effective_hosted_media_urls:
        payload["hosted_media_urls"] = effective_hosted_media_urls
    if media_urls:
        payload["media_urls"] = media_urls
    if post_format:
        payload["post_format"] = post_format
    if "saved_comments" in row or normalized_platform in {"instagram", "tiktok", "twitter", "youtube"}:
        payload["saved_comments"] = _normalize_non_negative_int(row.get("saved_comments"))
    return payload


def _social_account_profile_row_sort_value(value: Any) -> str:
    if isinstance(value, datetime):
        candidate = value
        if candidate.tzinfo is None:
            candidate = candidate.replace(tzinfo=UTC)
        else:
            candidate = candidate.astimezone(UTC)
        return candidate.isoformat()
    normalized = str(value or "").strip()
    if not normalized:
        return ""
    if normalized.endswith("Z"):
        return f"{normalized[:-1]}+00:00"
    return normalized


def _social_account_profile_row_datetime(value: Any) -> datetime | None:
    if isinstance(value, datetime):
        return value.astimezone(UTC) if value.tzinfo else value.replace(tzinfo=UTC)
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    return parsed.astimezone(UTC) if parsed.tzinfo else parsed.replace(tzinfo=UTC)


def _social_account_profile_post_sort_value(row: Mapping[str, Any], sort_by: str) -> Any:
    if sort_by == "post":
        return str(row.get("source_id") or "").strip().casefold()
    if sort_by == "created":
        return _social_account_profile_row_datetime(row.get("posted_at")) or datetime.min.replace(tzinfo=UTC)
    if sort_by == "caption":
        return str(
            _first_non_empty_str(
                row.get("caption"),
                row.get("description"),
                row.get("text"),
                row.get("title"),
            )
            or ""
        ).casefold()
    if sort_by == "post_total":
        return _normalize_non_negative_int(row.get("comments_count"))
    if sort_by == "saved_comments":
        return _normalize_non_negative_int(row.get("saved_comments"))
    if sort_by == "missing_comments":
        if "missing_comments" in row:
            return _normalize_non_negative_int(row.get("missing_comments"))
        return max(
            _normalize_non_negative_int(row.get("comments_count"))
            - _normalize_non_negative_int(row.get("saved_comments")),
            0,
        )
    if sort_by == "likes":
        return _normalize_non_negative_int(row.get("likes"))
    return _social_account_profile_row_datetime(row.get("posted_at")) or datetime.min.replace(tzinfo=UTC)


def _sort_social_account_profile_post_rows(
    rows: Sequence[Mapping[str, Any]],
    *,
    sort_by: str | None,
    sort_dir: str | None,
) -> list[dict[str, Any]]:
    normalized_sort_by = _normalize_social_account_profile_post_sort_by(sort_by)
    normalized_sort_dir = _normalize_social_account_profile_post_sort_dir(sort_dir)
    return sorted(
        (dict(row) for row in rows),
        key=lambda row: (
            _social_account_profile_post_sort_value(row, normalized_sort_by),
            _social_account_profile_row_datetime(row.get("posted_at")) or datetime.min.replace(tzinfo=UTC),
            str(row.get("id") or ""),
        ),
        reverse=normalized_sort_dir == "desc",
    )


def _social_account_profile_row_matches_search(
    platform: str,
    row: Mapping[str, Any],
    *,
    account_handle: str,
    search: str | None,
    known_handle_identity_index: Mapping[str, set[str]] | None = None,
) -> bool:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_search = str(search or "").strip().lower()
    if not normalized_search:
        return True

    hashtags = {
        _normalize_social_account_profile_hashtag_term(value)
        for value in _social_account_profile_hashtags_for_row(normalized_platform, row)
    }
    hashtags.discard("")
    handles = {
        _normalize_social_account_profile_handle_term(value)
        for value in [
            *_social_account_profile_mentions_for_row(
                normalized_platform,
                row,
                known_handle_identity_index=known_handle_identity_index,
            ),
            *_social_account_profile_collaborators_for_row(row),
            *_social_account_profile_tags_for_row(normalized_platform, row),
        ]
    }
    handles.discard("")

    if normalized_search.startswith("@"):
        exact_handle = _normalize_social_account_profile_handle_term(normalized_search)
        if not exact_handle:
            return False
        search_identity = _canonicalize_social_account_profile_mention_identity(exact_handle)
        handle_identities = {_canonicalize_social_account_profile_mention_identity(value) for value in handles if value}
        return exact_handle in handles or (bool(search_identity) and search_identity in handle_identities)

    if normalized_search.startswith("#"):
        exact_hashtag = _normalize_social_account_profile_hashtag_term(normalized_search)
        return bool(exact_hashtag) and exact_hashtag in hashtags

    text_haystack = " ".join(
        filter(
            None,
            [
                _social_account_profile_title_text(normalized_platform, row),
                _social_account_profile_content_text(normalized_platform, row),
                str(row.get("show_name") or "").strip(),
                _social_account_profile_post_url(normalized_platform, row, account_handle=account_handle),
            ],
        )
    ).lower()
    if normalized_search in text_haystack:
        return True

    search_identity = _canonicalize_social_account_profile_mention_identity(normalized_search)
    handle_identities = {_canonicalize_social_account_profile_mention_identity(value) for value in handles if value}
    return (
        normalized_search in hashtags
        or normalized_search in handles
        or (bool(search_identity) and search_identity in handle_identities)
    )


def _social_account_profile_base_query_parts(platform: str) -> tuple[str, str, str]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    table = PLATFORM_POST_TABLES.get(normalized_platform)
    source_id_column = PLATFORM_SOURCE_ID_COLUMN.get(normalized_platform)
    posted_at_column = PLATFORM_POSTED_AT_COLUMN.get(normalized_platform)
    if not table or not source_id_column or not posted_at_column:
        raise ValueError(f"INVALID_PLATFORM_FILTER: Unsupported platform '{platform}'")
    return table, source_id_column, posted_at_column


def _social_account_profile_search_title_sql(platform: str, alias: str = "p") -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "youtube":
        return f"coalesce({alias}.title, '')"
    return "''"


def _social_account_profile_search_content_sql(platform: str, alias: str = "p") -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "instagram":
        return f"coalesce({alias}.caption, '')"
    if normalized_platform == "tiktok":
        return (
            f"coalesce({alias}.description, {alias}.raw_data ->> 'description', {alias}.raw_data ->> 'caption', "
            f"{alias}.raw_data ->> 'text', '')"
        )
    if normalized_platform == "twitter":
        return f"coalesce({alias}.text, '')"
    if normalized_platform == "youtube":
        return f"coalesce({alias}.description, {alias}.title, '')"
    if normalized_platform == "facebook":
        return f"coalesce({alias}.caption, {alias}.raw_data ->> 'text', {alias}.raw_data ->> 'message', '')"
    if normalized_platform == "threads":
        return f"coalesce({alias}.text, {alias}.raw_data ->> 'caption', '')"
    return "''"


def _social_account_profile_search_url_sql(platform: str, alias: str = "p") -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "instagram":
        return (
            f"case when nullif({alias}.shortcode, '') is not null "
            f"then 'https://www.instagram.com/p/' || {alias}.shortcode || '/' "
            "else '' end"
        )
    if normalized_platform == "tiktok":
        return (
            f"case when nullif({alias}.video_id, '') is not null "
            f"and nullif(lower({alias}.source_account), '') is not null "
            f"then 'https://www.tiktok.com/@' || lower({alias}.source_account) "
            f"|| '/video/' || {alias}.video_id else '' end"
        )
    if normalized_platform == "twitter":
        return (
            f"case when nullif({alias}.tweet_id, '') is not null "
            f"and nullif(lower({alias}.source_account), '') is not null "
            f"then 'https://x.com/' || lower({alias}.source_account) "
            f"|| '/status/' || {alias}.tweet_id else '' end"
        )
    if normalized_platform == "youtube":
        return (
            f"case when nullif({alias}.video_id, '') is not null "
            f"then 'https://www.youtube.com/watch?v=' || {alias}.video_id else '' end"
        )
    if normalized_platform == "facebook":
        return (
            f"case when nullif({alias}.post_id, '') is not null "
            f"and nullif(lower({alias}.source_account), '') is not null "
            f"then 'https://www.facebook.com/' || lower({alias}.source_account) "
            f"|| '/posts/' || {alias}.post_id else '' end"
        )
    if normalized_platform == "threads":
        return (
            f"case when nullif({alias}.post_id, '') is not null "
            f"and nullif(lower({alias}.source_account), '') is not null "
            f"then 'https://www.threads.com/@' || lower({alias}.source_account) "
            f"|| '/post/' || {alias}.post_id else '' end"
        )
    return "''"


def _social_account_profile_search_hashtag_array_exprs(platform: str, alias: str = "p") -> tuple[str, ...]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "youtube":
        return (f"{alias}.hashtags", f"{alias}.tags")
    return (f"{alias}.hashtags",)


def _social_account_profile_search_handle_array_exprs(platform: str, alias: str = "p") -> tuple[str, ...]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "instagram":
        return (f"{alias}.mentions", f"{alias}.collaborators", f"{alias}.profile_tags")
    return (f"{alias}.mentions",)


def _social_account_profile_exact_jsonb_term_sql(
    array_exprs: Sequence[str],
    *,
    term_sql: str,
) -> str:
    if not array_exprs:
        return "false"
    return " or ".join(
        f"""
        exists (
          select 1
          from jsonb_array_elements_text(coalesce({array_expr}, '[]'::jsonb)) as term(value)
          where {term_sql.replace("__TERM_VALUE__", "term.value")} = %s
        )
        """
        for array_expr in array_exprs
    )


SocialAccountProfileSummaryDetail = Literal["full", "distribution", "lite"]


def _normalize_social_account_profile_summary_detail(
    detail: str | None,
) -> SocialAccountProfileSummaryDetail:
    normalized = str(detail or "lite").strip().lower()
    if normalized == "full":
        return "full"
    if normalized == "distribution":
        return "distribution"
    return "lite"


def _social_account_profile_search_sql_parts(
    platform: str,
    *,
    search: str | None = None,
    alias: str = "p",
    show_alias: str = "sh",
) -> tuple[str, list[Any]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_search = str(search or "").strip().lower()
    if not normalized_search:
        return "", []

    precomputed_search_supported = all(
        _platform_posts_has_column(normalized_platform, column)
        for column in ("search_text", "search_hashtags", "search_handles", "search_handle_identities")
    )
    if precomputed_search_supported:
        if normalized_search.startswith("@"):
            exact_handle = _normalize_social_account_profile_handle_term(normalized_search).lstrip("@").lower()
            identity = _canonicalize_social_account_profile_mention_identity(exact_handle)
            if not exact_handle:
                return "and false", []
            clauses = [f"%s = any(coalesce({alias}.search_handles, array[]::text[]))"]
            params: list[Any] = [exact_handle]
            if identity:
                clauses.append(f"%s = any(coalesce({alias}.search_handle_identities, array[]::text[]))")
                params.append(identity)
            return f"and ({' or '.join(clauses)})", params

        if normalized_search.startswith("#"):
            exact_hashtag = _normalize_social_account_profile_hashtag_term(normalized_search).lower()
            if not exact_hashtag:
                return "and false", []
            return f"and (%s = any(coalesce({alias}.search_hashtags, array[]::text[])))", [exact_hashtag]

        normalized_identity = _canonicalize_social_account_profile_mention_identity(normalized_search)
        clauses = [
            f"lower(concat_ws(' ', coalesce({alias}.search_text, ''), coalesce({show_alias}.name, ''))) like %s",
            f"%s = any(coalesce({alias}.search_hashtags, array[]::text[]))",
            f"%s = any(coalesce({alias}.search_handles, array[]::text[]))",
        ]
        params = [f"%{normalized_search}%", normalized_search, normalized_search]
        if normalized_identity:
            clauses.append(f"%s = any(coalesce({alias}.search_handle_identities, array[]::text[]))")
            params.append(normalized_identity)
        return f"and ({' or '.join(clauses)})", params

    normalized_handle_sql = (
        "nullif("
        "regexp_replace("
        "lower(regexp_replace(coalesce(__TERM_VALUE__, ''), '^@+', '')), "
        "'[^a-z0-9._-]+', '', 'g'"
        "), '')"
    )
    normalized_hashtag_sql = (
        "nullif("
        "regexp_replace("
        "lower(regexp_replace(coalesce(__TERM_VALUE__, ''), '^#+', '')), "
        "'[^a-z0-9]+', '', 'g'"
        "), '')"
    )
    hashtag_array_exprs = _social_account_profile_search_hashtag_array_exprs(normalized_platform, alias=alias)
    handle_array_exprs = _social_account_profile_search_handle_array_exprs(normalized_platform, alias=alias)

    if normalized_search.startswith("@"):
        exact_handle = _normalize_social_account_profile_handle_term(normalized_search).lstrip("@").lower()
        if not exact_handle:
            return "and false", []
        clause = _social_account_profile_exact_jsonb_term_sql(handle_array_exprs, term_sql=normalized_handle_sql)
        if not clause:
            return "and false", []
        return f"and ({clause})", [exact_handle] * len(handle_array_exprs)

    if normalized_search.startswith("#"):
        exact_hashtag = _normalize_social_account_profile_hashtag_term(normalized_search).lower()
        if not exact_hashtag:
            return "and false", []
        clause = _social_account_profile_exact_jsonb_term_sql(hashtag_array_exprs, term_sql=normalized_hashtag_sql)
        if not clause:
            return "and false", []
        return f"and ({clause})", [exact_hashtag] * len(hashtag_array_exprs)

    text_expr = (
        f"lower(concat_ws(' ', "
        f"{_social_account_profile_search_title_sql(normalized_platform, alias=alias)}, "
        f"{_social_account_profile_search_content_sql(normalized_platform, alias=alias)}, "
        f"coalesce({show_alias}.name, ''), "
        f"{_social_account_profile_search_url_sql(normalized_platform, alias=alias)}"
        f"))"
    )
    hashtag_clause = _social_account_profile_exact_jsonb_term_sql(hashtag_array_exprs, term_sql=normalized_hashtag_sql)
    handle_clause = _social_account_profile_exact_jsonb_term_sql(handle_array_exprs, term_sql=normalized_handle_sql)
    clauses = [f"{text_expr} like %s"]
    params: list[Any] = [f"%{normalized_search}%"]
    if hashtag_clause:
        clauses.append(hashtag_clause)
        params.extend([normalized_search] * len(hashtag_array_exprs))
    if handle_clause:
        clauses.append(handle_clause)
        params.extend([normalized_search] * len(handle_array_exprs))
    return f"and ({' or '.join(clauses)})", params


def _fetch_social_account_profile_source_rows(
    platform: str,
    account_handle: str,
    *,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    sql = """
        select
          id::text as id,
          source_scope,
          platform,
          account_handle,
          is_active,
          scrape_priority,
          metadata,
          last_scrape_run_id::text as last_scrape_run_id,
          last_scrape_job_id::text as last_scrape_job_id,
          last_scrape_status,
          last_scrape_at,
          last_classified_at,
          updated_by,
          created_at,
          updated_at
        from social.shared_account_sources
        where platform = %s
          and account_handle = %s
        order by case when source_scope = 'network' then 0 else 1 end, scrape_priority asc, created_at desc
        """
    if conn is None:
        rows = pg.fetch_all(sql, [normalized_platform, normalized_account])
    else:
        with pg.db_cursor(conn=conn, label="profile_source_rows") as cur:
            rows = pg.fetch_all_with_cursor(cur, sql, [normalized_platform, normalized_account])
    if rows:
        return rows
    external_id_keys = _SOCIAL_ACCOUNT_PROFILE_SHOW_EXTERNAL_ID_KEYS.get(normalized_platform, ())
    if external_id_keys:
        show_match_clauses = " or ".join(["lower(coalesce(sh.external_ids ->> %s, '')) = %s"] * len(external_id_keys))
        show_match_params: list[Any] = []
        for key in external_id_keys:
            show_match_params.extend([key, normalized_account])
        show_sql = f"""
            select
              sh.id::text as show_id,
              sh.name as show_name,
              sh.slug as show_slug
            from core.shows sh
            where {show_match_clauses}
            order by sh.name asc, sh.id asc
        """
        if conn is None:
            show_rows = pg.fetch_all(show_sql, show_match_params)
        else:
            with pg.db_cursor(conn=conn, label="profile_source_rows_show_external_ids") as cur:
                show_rows = pg.fetch_all_with_cursor(cur, show_sql, show_match_params)
        if show_rows:
            resolved_rows: list[dict[str, Any]] = []
            for rank, show in enumerate(show_rows, start=1):
                show_name = str(show.get("show_name") or "").strip()
                metadata = {
                    "is_ephemeral_show_external_id": True,
                    "show_id": show.get("show_id"),
                    "show_name": show.get("show_name"),
                    "show_slug": show.get("show_slug"),
                    "network_name": show_name or normalized_account,
                }
                profile_contract = _shared_profile_contract(
                    source_scope="bravo",
                    platform=normalized_platform,
                    account_handle=normalized_account,
                    metadata=metadata,
                )
                resolved_rows.append(
                    {
                        "id": f"show-external-id:{normalized_platform}:{normalized_account}:{show.get('show_id')}",
                        "source_scope": "bravo",
                        "platform": normalized_platform,
                        "account_handle": normalized_account,
                        "is_active": True,
                        "scrape_priority": rank * 10,
                        "metadata": {**metadata, **profile_contract},
                        "last_scrape_run_id": None,
                        "last_scrape_job_id": None,
                        "last_scrape_status": None,
                        "last_scrape_at": None,
                        "last_classified_at": None,
                        "updated_by": None,
                        "created_at": None,
                        "updated_at": None,
                    }
                )
            return resolved_rows
    return [
        row
        for row in _shared_source_defaults(source_scope="network")
        if _normalize_platform_name(row.get("platform")) == normalized_platform
        and _normalize_social_account_profile_handle(row.get("account_handle")) == normalized_account
    ]


def _instagram_catalog_profile_rows_select_sql() -> str:
    return """
            select
              p.id::text as id,
              p.source_id as source_id,
              p.assigned_show_id::text as show_id,
              p.assigned_season_id::text as season_id,
              p.source_account,
              p.posted_at,
              p.assignment_status,
              p.assignment_source,
              p.candidate_matches,
              s.season_number,
              sh.name as show_name,
              sh.slug as show_slug,
              p.*
            from social.instagram_account_catalog_posts p
            left join core.seasons s on s.id = p.assigned_season_id
            left join core.shows sh on sh.id = coalesce(p.assigned_show_id, s.show_id)
    """


def _fetch_instagram_owner_catalog_rows(
    account_handle: str,
    *,
    limit: int | None = None,
    posted_since: datetime | None = None,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_posted_since: datetime | None = None
    if posted_since is not None:
        normalized_posted_since = (
            posted_since.astimezone(UTC) if posted_since.tzinfo else posted_since.replace(tzinfo=UTC)
        )
    params: list[Any] = [normalized_account]
    posted_since_clause = ""
    if normalized_posted_since is not None:
        posted_since_clause = "and p.posted_at >= %s"
        params.append(normalized_posted_since)
    limit_clause = ""
    if limit is not None:
        limit_clause = "limit %s"
        params.append(max(1, int(limit)))
    account_match_clause = _instagram_account_match_sql(alias="p")
    try:
        query = f"""
            {_instagram_catalog_profile_rows_select_sql()}
            where {account_match_clause}
              {posted_since_clause}
            order by p.posted_at desc nulls last, p.id desc
            {limit_clause}
            """
        if conn is not None:
            with pg.db_cursor(conn=conn, label="instagram_owner_catalog_rows") as cur:
                return pg.fetch_all_with_cursor(cur, query, params)
        return pg.fetch_all(query, params)
    except psycopg_errors.UndefinedTable:
        return []


def _fetch_instagram_collaborator_catalog_rows(
    account_handle: str,
    *,
    limit: int | None = None,
    posted_since: datetime | None = None,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_posted_since: datetime | None = None
    if posted_since is not None:
        normalized_posted_since = (
            posted_since.astimezone(UTC) if posted_since.tzinfo else posted_since.replace(tzinfo=UTC)
        )
    params: list[Any] = [normalized_account, normalized_account]
    posted_since_clause = ""
    if normalized_posted_since is not None:
        posted_since_clause = "and m.posted_at >= %s"
        params.append(normalized_posted_since)
    limit_clause = ""
    if limit is not None:
        limit_clause = "limit %s"
        params.append(max(1, int(limit)))
    try:
        query = f"""
            {_instagram_catalog_profile_rows_select_sql()}
            join social.instagram_account_catalog_post_collaborators m
              on m.catalog_post_id = p.id
            where m.collaborator_handle = %s
              and lower(p.source_account) <> %s
              {posted_since_clause}
            order by m.posted_at desc nulls last, m.catalog_post_id desc
            {limit_clause}
            """
        if conn is not None:
            with pg.db_cursor(conn=conn, label="instagram_collaborator_catalog_rows") as cur:
                return pg.fetch_all_with_cursor(cur, query, params)
        return pg.fetch_all(query, params)
    except psycopg_errors.UndefinedTable:
        return []


def _fetch_instagram_touching_catalog_rows(
    account_handle: str,
    *,
    limit: int | None = None,
    posted_since: datetime | None = None,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    owner_rows = _fetch_instagram_owner_catalog_rows(
        account_handle,
        limit=limit,
        posted_since=posted_since,
        conn=conn,
    )
    if limit is not None and len(owner_rows) >= max(1, int(limit)):
        return owner_rows[: max(1, int(limit))]

    collaborator_limit = None if limit is None else max(1, int(limit) - len(owner_rows))
    collaborator_rows = _fetch_instagram_collaborator_catalog_rows(
        account_handle,
        limit=collaborator_limit,
        posted_since=posted_since,
        conn=conn,
    )
    combined_rows = [*owner_rows, *collaborator_rows]
    combined_rows.sort(
        key=lambda row: (
            _social_account_profile_row_sort_value(row.get("posted_at")),
            str(row.get("id") or ""),
        ),
        reverse=True,
    )
    if limit is not None:
        return combined_rows[: max(1, int(limit))]
    return combined_rows


def _instagram_social_account_profile_has_any_dataset_rows(account_handle: str) -> bool:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_account:
        return False
    if _fetch_social_account_profile_rows("instagram", normalized_account, limit=1):
        return True
    return bool(_fetch_instagram_touching_catalog_rows(normalized_account, limit=1))


def _instagram_social_account_profile_has_materialized_rows(
    account_handle: str,
    *,
    conn: Any | None = None,
) -> bool:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_account:
        return False
    owner_match_clause = _instagram_owner_account_match_sql(alias="p")
    sql = f"""
        select 1
        from social.instagram_posts p
        where {owner_match_clause}
        limit 1
        """
    if conn is None:
        row = pg.fetch_one(sql, [normalized_account]) or {}
    else:
        with pg.db_cursor(conn=conn, label="instagram_profile_has_materialized_rows") as cur:
            row = pg.fetch_one_with_cursor(cur, sql, [normalized_account]) or {}
    return bool(row)


def _instagram_social_account_profile_has_collaborator_catalog_rows(
    account_handle: str,
    *,
    conn: Any | None = None,
) -> bool:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_account:
        return False

    sql = """
            select 1
            from social.instagram_account_catalog_post_collaborators m
            join social.instagram_account_catalog_posts p
              on p.id = m.catalog_post_id
            where m.collaborator_handle = %s
              and lower(p.source_account) <> %s
            limit 1
            """
    try:
        if conn is None:
            row = pg.fetch_one(sql, [normalized_account, normalized_account]) or {}
        else:
            with pg.db_cursor(conn=conn, label="instagram_profile_has_collaborator_catalog_rows") as cur:
                row = pg.fetch_one_with_cursor(cur, sql, [normalized_account, normalized_account]) or {}
    except psycopg_errors.UndefinedTable:
        return False
    return bool(row)


def _instagram_social_account_profile_dataset_rows(
    account_handle: str,
    *,
    search: str | None = None,
    limit: int | None = None,
    posted_since: datetime | None = None,
    collaborator_posted_since: datetime | None = None,
    conn: Any | None = None,
    comments_only: bool = False,
    sort_by: str | None = None,
    sort_dir: str | None = None,
) -> list[dict[str, Any]]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    fetch_limit = max(1, int(limit)) if limit is not None else None
    materialized_rows = _call_profile_summary_loader_with_conn(
        _fetch_social_account_profile_rows,
        "instagram",
        normalized_account,
        limit=fetch_limit,
        posted_since=posted_since,
        conn=conn,
    )
    owner_catalog_rows = _call_profile_summary_loader_with_conn(
        _fetch_instagram_owner_catalog_rows,
        normalized_account,
        limit=fetch_limit,
        posted_since=posted_since,
        conn=conn,
    )
    owner_backed_rows = _dedupe_social_account_profile_dataset_rows(
        [
            *_annotate_instagram_social_account_profile_dataset_rows(
                materialized_rows,
                source_surface="materialized",
                match_mode="owner",
                priority=3,
            ),
            *_annotate_instagram_social_account_profile_dataset_rows(
                owner_catalog_rows,
                source_surface="catalog",
                match_mode="owner",
                priority=2,
            ),
        ]
    )

    collaborator_catalog_rows: list[dict[str, Any]] = []
    if fetch_limit is None or len(owner_backed_rows) < fetch_limit:
        collaborator_limit = None if fetch_limit is None else max(1, fetch_limit - len(owner_backed_rows))
        collaborator_catalog_rows = _call_profile_summary_loader_with_conn(
            _fetch_instagram_collaborator_catalog_rows,
            normalized_account,
            limit=collaborator_limit,
            posted_since=collaborator_posted_since if collaborator_posted_since is not None else posted_since,
            conn=conn,
        )

    dataset_rows = _dedupe_social_account_profile_dataset_rows(
        [
            *owner_backed_rows,
            *_annotate_instagram_social_account_profile_dataset_rows(
                collaborator_catalog_rows,
                source_surface="catalog",
                match_mode="collaborator",
                priority=1,
            ),
        ]
    )
    post_ids = [str(row.get("id") or "").strip() for row in dataset_rows if str(row.get("id") or "").strip()]
    saved_comment_counts: dict[str, int] = {}
    saved_comment_breakdowns: dict[str, dict[str, int]] = {}
    if post_ids:
        if comments_only:
            saved_comment_breakdowns = _call_profile_summary_loader_with_conn(
                _count_stored_instagram_comment_breakdown,
                post_ids,
                conn=conn,
            )
            saved_comment_counts = {
                post_id: _normalize_non_negative_int(breakdown.get("saved_comments"))
                for post_id, breakdown in saved_comment_breakdowns.items()
            }
        else:
            saved_comment_counts = _call_profile_summary_loader_with_conn(
                _count_stored_comments,
                post_ids,
                "instagram",
                conn=conn,
            )
    enriched_rows: list[dict[str, Any]] = []
    for row in dataset_rows:
        normalized_row = dict(row)
        row_id = str(normalized_row.get("id") or "").strip()
        comment_breakdown = saved_comment_breakdowns.get(row_id) or {}
        if comment_breakdown:
            normalized_row["saved_parent_comments"] = _normalize_non_negative_int(
                comment_breakdown.get("saved_parent_comments")
            )
            normalized_row["saved_child_replies"] = _normalize_non_negative_int(
                comment_breakdown.get("saved_child_replies")
            )
            normalized_row["classified_missing_comments"] = _normalize_non_negative_int(
                comment_breakdown.get("classified_missing_comments")
            )
        normalized_row["saved_comments"] = _normalize_non_negative_int(saved_comment_counts.get(row_id, 0))
        if comments_only:
            reported_comments = _normalize_non_negative_int(normalized_row.get("comments_count"))
            if max(reported_comments, _normalize_non_negative_int(normalized_row.get("saved_comments"))) <= 0:
                continue
        enriched_rows.append(normalized_row)

    known_handle_identity_index = _build_social_account_profile_known_handle_identity_index("instagram", enriched_rows)
    dataset_rows = [
        row
        for row in enriched_rows
        if _social_account_profile_row_matches_search(
            "instagram",
            row,
            account_handle=normalized_account,
            search=search,
            known_handle_identity_index=known_handle_identity_index,
        )
    ]
    dataset_rows = _sort_social_account_profile_post_rows(dataset_rows, sort_by=sort_by, sort_dir=sort_dir)
    if fetch_limit is not None:
        return dataset_rows[:fetch_limit]
    return dataset_rows


def _normalize_social_account_profile_comment_filter(value: str | None) -> str | None:
    normalized = str(value or "").strip().lower()
    if not normalized or normalized == "all":
        return None
    if normalized not in SOCIAL_ACCOUNT_PROFILE_COMMENT_FILTERS:
        allowed = ", ".join(sorted(SOCIAL_ACCOUNT_PROFILE_COMMENT_FILTERS))
        raise ValueError(f"Unsupported comments post filter: {value}. Expected one of: {allowed}")
    return normalized


def _normalize_social_account_profile_post_sort_by(value: str | None) -> str:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return "missing_comments"
    if normalized not in SOCIAL_ACCOUNT_PROFILE_POST_SORT_FIELDS:
        allowed = ", ".join(sorted(SOCIAL_ACCOUNT_PROFILE_POST_SORT_FIELDS))
        raise ValueError(f"Unsupported social account post sort: {value}. Expected one of: {allowed}")
    return normalized


def _normalize_social_account_profile_post_sort_dir(value: str | None) -> str:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return "desc"
    if normalized not in SOCIAL_ACCOUNT_PROFILE_POST_SORT_DIRECTIONS:
        raise ValueError(f"Unsupported social account post sort direction: {value}. Expected asc or desc")
    return normalized


def _comments_only_profile_order_by_sql(
    *,
    sort_by: str | None,
    sort_dir: str | None,
    missing_comments_sql: str | None = None,
) -> str:
    normalized_sort_by = _normalize_social_account_profile_post_sort_by(sort_by)
    normalized_sort_dir = _normalize_social_account_profile_post_sort_dir(sort_dir)
    direction = "asc" if normalized_sort_dir == "asc" else "desc"
    missing_comments_expr = (
        str(missing_comments_sql)
        if missing_comments_sql
        else (
            "greatest(greatest(coalesce(filtered_rows.comments_count, 0), 0) - "
            "greatest(coalesce(filtered_rows.saved_comments, 0), 0), 0)"
        )
    )
    sort_expressions = {
        "post": "lower(nullif(filtered_rows.source_id, ''))",
        "created": "filtered_rows.posted_at",
        "caption": (
            "lower(coalesce(nullif(filtered_rows.caption, ''), nullif(filtered_rows.description, ''), "
            "nullif(filtered_rows.text, ''), nullif(filtered_rows.title, ''), ''))"
        ),
        "post_total": "greatest(coalesce(filtered_rows.comments_count, 0), 0)",
        "saved_comments": "greatest(coalesce(filtered_rows.saved_comments, 0), 0)",
        "missing_comments": missing_comments_expr,
        "likes": "greatest(coalesce(filtered_rows.likes, 0), 0)",
    }
    primary = sort_expressions[normalized_sort_by]
    if normalized_sort_by == "created":
        return f"{primary} {direction} nulls last, filtered_rows.id {direction}"
    return f"{primary} {direction} nulls last, filtered_rows.posted_at desc nulls last, filtered_rows.id desc"


_INCOMPLETE_COMMENT_TARGET_ALLOWED_MISSING_COMMENTS = 1


def _comments_only_profile_filter_where_sql(
    *,
    comment_filter: str | None,
    reported_comments_sql: str,
    saved_comments_sql: str,
    accounted_comments_sql: str | None = None,
    reported_comments_is_normalized: bool = False,
) -> str:
    reported_comments = (
        str(reported_comments_sql)
        if reported_comments_is_normalized
        else f"greatest(coalesce({reported_comments_sql}, 0), 0)"
    )
    saved_comments = f"greatest(coalesce({saved_comments_sql}, 0), 0)"
    accounted_comments = (
        f"greatest(coalesce({accounted_comments_sql}, 0), 0)" if accounted_comments_sql else saved_comments
    )
    if comment_filter == "commentable":
        return f"{reported_comments} > 0"
    if comment_filter == "not_commentable":
        return f"{reported_comments} = 0"
    if comment_filter == "incomplete":
        missing_comments = f"greatest({reported_comments} - {accounted_comments}, 0)"
        return f"{reported_comments} > 0 and {missing_comments} > {_INCOMPLETE_COMMENT_TARGET_ALLOWED_MISSING_COMMENTS}"
    return f"greatest({reported_comments}, {saved_comments}) > 0"


def _comments_only_profile_search_where_sql(search: str | None, *, alias: str) -> tuple[str, list[Any]]:
    normalized_search = str(search or "").strip().lower()
    if not normalized_search:
        return "", []
    pattern = f"%{normalized_search}%"
    return (
        f"""
        and (
          lower(coalesce({alias}.source_id, '')) like %s
          or lower(coalesce({alias}.shortcode, '')) like %s
          or lower(coalesce({alias}.caption, '')) like %s
          or lower(coalesce({alias}.description, '')) like %s
          or lower(coalesce({alias}.text, '')) like %s
          or lower(coalesce({alias}.title, '')) like %s
          or lower(coalesce({alias}.show_name, '')) like %s
        )
        """,
        [pattern, pattern, pattern, pattern, pattern, pattern, pattern],
    )


def _instagram_post_comment_rollups_available(*, conn: Any | None = None) -> bool:
    return _relation_exists("social.instagram_post_comment_rollups", conn=conn)


def _instagram_comments_only_saved_counts_cte_sql(*, source_cte: str, use_rollup: bool) -> str:
    if use_rollup:
        return f"""
        saved_comment_counts as materialized (
          select
            r.post_id::text as profile_row_id,
            coalesce(r.active_comment_count, 0)::int as saved_parent_comments,
            0::int as saved_child_replies,
            coalesce(r.active_comment_count, 0)::int as saved_comments,
            coalesce(r.missing_comment_count, 0)::int as classified_missing_comments
          from social.instagram_post_comment_rollups r
          join {source_cte} d
            on d.profile_row_id is not null
           and r.post_id = d.profile_row_id::uuid
        )
        """
    return """
        saved_comment_counts as materialized (
          select
            c.post_id::text as profile_row_id,
            count(*) filter (
              where {active_condition} and not ({fb_crosspost_condition}) and not {reply_condition}
            )::int as saved_parent_comments,
            count(*) filter (
              where {active_condition} and not ({fb_crosspost_condition}) and {reply_condition}
            )::int as saved_child_replies,
            count(*) filter (
              where {active_condition} and not ({fb_crosspost_condition})
            )::int as saved_comments,
            count(*) filter (
              where {missing_condition} and not ({fb_crosspost_condition})
            )::int as classified_missing_comments
          from social.instagram_comments c
          join {source_cte} d
            on d.profile_row_id is not null
           and c.post_id = d.profile_row_id::uuid
          group by c.post_id
        )
    """


def _fetch_materialized_comments_only_profile_rows_page(
    platform: str,
    account_handle: str,
    *,
    page: int,
    page_size: int,
    search: str | None = None,
    comment_filter: str | None = None,
    sort_by: str | None = None,
    sort_dir: str | None = None,
    conn: Any | None = None,
) -> tuple[list[dict[str, Any]], int]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform not in {"instagram", "tiktok", "twitter", "youtube"}:
        raise ValueError(f"Unsupported comments-only fast path platform: {platform}")
    if normalized_platform == "instagram":
        return _fetch_instagram_comments_only_profile_rows_page(
            account_handle,
            page=page,
            page_size=page_size,
            search=search,
            comment_filter=comment_filter,
            sort_by=sort_by,
            sort_dir=sort_dir,
            conn=conn,
        )
    table, source_id_column, posted_at_column = _social_account_profile_base_query_parts(normalized_platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    safe_page = max(1, int(page))
    safe_page_size = max(1, min(int(page_size), _SOCIAL_ACCOUNT_PROFILE_MAX_PAGE_SIZE))
    safe_offset = (safe_page - 1) * safe_page_size
    posted_at_projection = f"p.{posted_at_column} as posted_at," if posted_at_column != "posted_at" else ""
    order_by_sql = _comments_only_profile_order_by_sql(
        sort_by=sort_by,
        sort_dir=sort_dir,
        missing_comments_sql=(
            "greatest(coalesce(filtered_rows.missing_comments, 0), 0)" if normalized_platform == "twitter" else None
        ),
    )

    base_rows_sql = f"""
        with base_rows as (
          select
            p.id::text as profile_row_id,
            p.show_id::text as show_id,
            p.season_id::text as season_id,
            p.source_account,
            p.{source_id_column} as source_id,
            {posted_at_projection}
            s.season_number,
            sh.name as show_name,
            sh.slug as show_slug,
            p.*
          from social.{table} p
          left join core.seasons s on s.id = p.season_id
          left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
          where {_social_account_profile_owner_match_sql(normalized_platform, alias="p")}
        )
    """
    params: list[Any] = [normalized_account]
    if normalized_platform == "twitter":
        active_filter = (
            "and coalesce(t.is_missing, false) = false"
            if _comment_lifecycle_supported("twitter_tweets", conn=conn)
            else ""
        )
        saved_counts_sql = f"""
            {base_rows_sql},
            reply_counts as (
              select
                t.reply_to_tweet_id::text as join_key,
                count(*)::int as reply_count
              from social.twitter_tweets t
              join base_rows p on p.source_id = t.reply_to_tweet_id
              where t.is_reply = true
                and nullif(t.reply_to_tweet_id, '') is not null
                {active_filter}
              group by t.reply_to_tweet_id
            ),
            quote_counts as (
              select
                t.quoted_tweet_id::text as join_key,
                count(*)::int as quote_count
              from social.twitter_tweets t
              join base_rows p on p.source_id = t.quoted_tweet_id
              where t.is_quote = true
                and nullif(t.quoted_tweet_id, '') is not null
                {active_filter}
              group by t.quoted_tweet_id
            ),
            saved_comment_counts as (
              select
                coalesce(reply_counts.join_key, quote_counts.join_key) as join_key,
                coalesce(reply_counts.reply_count, 0) + coalesce(quote_counts.quote_count, 0) as saved_comments
              from reply_counts
              full outer join quote_counts using (join_key)
            ),
            filtered_rows as (
              select
                base_rows.*,
                (
                  coalesce(base_rows.replies_count, 0)
                  + coalesce(base_rows.quotes, 0)
                )::bigint as comments_count,
                coalesce(saved_comment_counts.saved_comments, 0)::int as saved_comments,
                greatest(
                  coalesce(base_rows.replies_count, 0)
                  + coalesce(base_rows.quotes, 0)
                  - coalesce(saved_comment_counts.saved_comments, 0),
                  0
                )::int as missing_comments
              from base_rows
              left join saved_comment_counts on saved_comment_counts.join_key = base_rows.source_id
              where greatest(
                coalesce(base_rows.replies_count, 0) + coalesce(base_rows.quotes, 0),
                coalesce(saved_comment_counts.saved_comments, 0)
              ) > 0
            )
        """
    else:
        comment_table = PLATFORM_COMMENT_TABLES[normalized_platform]
        fk_col = "post_id" if normalized_platform in {"instagram", "tiktok"} else "video_id"
        active_filter = (
            "and coalesce(c.is_missing, false) = false"
            if _comment_lifecycle_supported(comment_table, conn=conn)
            else ""
        )
        saved_counts_sql = f"""
            {base_rows_sql},
            saved_comment_counts as (
              select
                c.{fk_col}::text as join_key,
                count(*)::int as saved_comments
              from social.{comment_table} c
              join base_rows p on p.profile_row_id = c.{fk_col}::text
              where 1 = 1
                {active_filter}
              group by c.{fk_col}
            ),
            filtered_rows as (
              select
                base_rows.*,
                coalesce(saved_comment_counts.saved_comments, 0)::int as saved_comments
              from base_rows
              left join saved_comment_counts on saved_comment_counts.join_key = base_rows.profile_row_id
              where greatest(
                coalesce(base_rows.comments_count, 0),
                coalesce(saved_comment_counts.saved_comments, 0)
              ) > 0
            )
        """

    total_sql = f"""
        {saved_counts_sql}
        select count(*)::int as total
        from filtered_rows
    """
    page_sql = f"""
        {saved_counts_sql}
        select *
        from filtered_rows
        order by {order_by_sql}
        limit %s offset %s
    """
    total_params = list(params)
    page_params = [*params, safe_page_size, safe_offset]
    if conn is None:
        total_row = pg.fetch_one(total_sql, total_params) or {}
        rows = pg.fetch_all(page_sql, page_params)
    else:
        with pg.db_cursor(conn=conn, label=f"{normalized_platform}_comments_only_profile_total") as cur:
            total_row = pg.fetch_one_with_cursor(cur, total_sql, total_params) or {}
        with pg.db_cursor(conn=conn, label=f"{normalized_platform}_comments_only_profile_rows") as cur:
            rows = pg.fetch_all_with_cursor(cur, page_sql, page_params)
    return rows, _normalize_non_negative_int(total_row.get("total"))


def _instagram_catalog_collaborator_membership_available(*, conn: Any | None = None) -> bool:
    sql = """
        select to_regclass('social.instagram_account_catalog_post_collaborators') is not null as available
    """
    if conn is None:
        row = pg.fetch_one(sql, []) or {}
    else:
        with pg.db_cursor(conn=conn, label="instagram_catalog_collaborator_membership_available") as cur:
            row = pg.fetch_one_with_cursor(cur, sql, []) or {}
    return bool(row.get("available"))


def _fetch_instagram_owner_comments_only_profile_rows_page(
    account_handle: str,
    *,
    page: int,
    page_size: int,
    search: str | None = None,
    comment_filter: str | None = None,
    sort_by: str | None = None,
    sort_dir: str | None = None,
    conn: Any | None = None,
) -> tuple[list[dict[str, Any]], int]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_comment_filter = _normalize_social_account_profile_comment_filter(comment_filter)
    safe_page = max(1, int(page))
    safe_page_size = max(1, min(int(page_size), _SOCIAL_ACCOUNT_PROFILE_MAX_PAGE_SIZE))
    safe_offset = (safe_page - 1) * safe_page_size
    order_by_sql = _comments_only_profile_order_by_sql(
        sort_by=sort_by,
        sort_dir=sort_dir,
        missing_comments_sql="greatest(coalesce(filtered_rows.missing_comments, 0), 0)",
    )
    owner_match_clause = _instagram_owner_account_match_sql(alias="p")
    lifecycle_supported = _comment_lifecycle_supported("instagram_comments", conn=conn)
    use_comment_rollups = _instagram_post_comment_rollups_available(conn=conn)
    active_condition = "c.is_missing is not true" if lifecycle_supported else "true"
    missing_condition = "c.is_missing is true" if lifecycle_supported else "false"
    fb_crosspost_condition = "coalesce(c.source_snapshot_type, '') = 'fb_crosspost'"
    parent_external_expr = "nullif(coalesce(c.parent_comment_external_id, ''), '')"
    reply_depth_expr = "coalesce(c.reply_depth, 0)"
    reply_condition = f"""
        (
          coalesce(c.is_reply, false)
          or c.parent_comment_id is not null
          or {parent_external_expr} is not null
          or ({reply_depth_expr}) > 0
        )
    """
    reported_comments_expr = _instagram_reported_comments_sql("p")
    facebook_comments_expr = _instagram_external_facebook_comments_sql("p")
    accounted_comments_sql = (
        "coalesce(saved_comment_counts.saved_parent_comments, 0) + "
        "coalesce(saved_comment_counts.saved_child_replies, 0) + "
        "coalesce(candidate_rows.facebook_comments, 0) + "
        "coalesce(saved_comment_counts.classified_missing_comments, 0)"
    )
    filter_where_sql = _comments_only_profile_filter_where_sql(
        comment_filter=normalized_comment_filter,
        reported_comments_sql="candidate_rows.comments_count",
        saved_comments_sql="saved_comment_counts.saved_comments",
        accounted_comments_sql=accounted_comments_sql,
        reported_comments_is_normalized=True,
    )
    search_where_sql, search_params = _comments_only_profile_search_where_sql(search, alias="candidate_rows")
    candidate_rows_sql = f"""
        with candidate_rows as materialized (
          select
            p.id::text as id,
            p.id::text as profile_row_id,
            p.show_id::text as show_id,
            p.season_id::text as season_id,
            p.source_account,
            p.shortcode as source_id,
            p.shortcode as shortcode,
            p.posted_at,
            s.season_number,
            sh.name as show_name,
            sh.slug as show_slug,
            null::text as title,
            p.caption,
            null::text as description,
            null::text as text,
            p.media_type,
            coalesce(p.media_urls, '[]'::jsonb) as media_urls,
            nullif(p.thumbnail_url, '') as thumbnail_url,
            coalesce(p.hashtags, '[]'::jsonb) as hashtags,
            coalesce(p.mentions, '[]'::jsonb) as mentions,
            coalesce(p.collaborators, '[]'::jsonb) as collaborators,
            coalesce(p.profile_tags, '[]'::jsonb) as profile_tags,
            coalesce(p.likes, 0)::bigint as likes,
            {reported_comments_expr}::bigint as comments_count,
            {facebook_comments_expr}::bigint as facebook_comments,
            p.fb_comment_count,
            p.facebook_crosspost_observed_at,
            p.facebook_crosspost_source,
            p.facebook_post_id,
            p.facebook_post_url,
            coalesce(p.views, 0)::bigint as views,
            p.media_repost_count::bigint as media_repost_count,
            coalesce(p.media_repost_count, 0)::bigint as shares,
            0::bigint as retweets,
            0::bigint as replies_count,
            0::bigint as quotes,
            coalesce(p.raw_data, '{{}}'::jsonb) as raw_data,
            'materialized'::text as _profile_source_surface,
            'owner'::text as _profile_match_mode,
            3::int as _profile_dataset_priority
          from social.instagram_posts p
          left join core.seasons s on s.id = p.season_id
          left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
          where {owner_match_clause}
            and nullif(p.shortcode, '') is not null
        ),
        {
        _instagram_comments_only_saved_counts_cte_sql(
            source_cte="candidate_rows",
            use_rollup=use_comment_rollups,
        ).format(
            active_condition=active_condition,
            fb_crosspost_condition=fb_crosspost_condition,
            reply_condition=reply_condition,
            missing_condition=missing_condition,
            source_cte="candidate_rows",
        )
    },
        filtered_rows as materialized (
          select
            candidate_rows.*,
            coalesce(saved_comment_counts.saved_parent_comments, 0)::int as saved_parent_comments,
            coalesce(saved_comment_counts.saved_child_replies, 0)::int as saved_child_replies,
            coalesce(saved_comment_counts.saved_comments, 0)::int as saved_comments,
            coalesce(saved_comment_counts.classified_missing_comments, 0)::int as classified_missing_comments,
            greatest(
              coalesce(candidate_rows.comments_count, 0)
              - coalesce(saved_comment_counts.saved_comments, 0)
              - coalesce(saved_comment_counts.classified_missing_comments, 0)
              - coalesce(candidate_rows.facebook_comments, 0),
              0
            )::int as missing_comments
          from candidate_rows
          left join saved_comment_counts
            on saved_comment_counts.profile_row_id = candidate_rows.profile_row_id
          where {filter_where_sql}
            {search_where_sql}
        )
    """
    params = [normalized_account, *search_params]
    total_sql = f"""
        {candidate_rows_sql}
        select count(*)::int as total
        from filtered_rows
    """
    page_sql = f"""
        {candidate_rows_sql}
        select
          *
        from filtered_rows
        order by {order_by_sql}
        limit %s offset %s
    """
    if conn is None:
        total_row = pg.fetch_one(total_sql, params) or {}
        rows = pg.fetch_all(page_sql, [*params, safe_page_size, safe_offset])
    else:
        with pg.db_cursor(conn=conn, label="instagram_comments_only_profile_total") as cur:
            total_row = pg.fetch_one_with_cursor(cur, total_sql, params) or {}
        with pg.db_cursor(conn=conn, label="instagram_comments_only_profile_rows") as cur:
            rows = pg.fetch_all_with_cursor(cur, page_sql, [*params, safe_page_size, safe_offset])
    total = _normalize_non_negative_int(total_row.get("total"))
    return rows, total


def _fetch_instagram_comments_only_profile_rows_page(
    account_handle: str,
    *,
    page: int,
    page_size: int,
    search: str | None = None,
    comment_filter: str | None = None,
    sort_by: str | None = None,
    sort_dir: str | None = None,
    conn: Any | None = None,
) -> tuple[list[dict[str, Any]], int]:
    normalized_comment_filter = _normalize_social_account_profile_comment_filter(comment_filter)
    if not _instagram_catalog_collaborator_membership_available(conn=conn):
        return _fetch_instagram_owner_comments_only_profile_rows_page(
            account_handle,
            page=page,
            page_size=page_size,
            search=search,
            comment_filter=normalized_comment_filter,
            sort_by=sort_by,
            sort_dir=sort_dir,
            conn=conn,
        )

    normalized_account = _normalize_social_account_profile_handle(account_handle)
    safe_page = max(1, int(page))
    safe_page_size = max(1, min(int(page_size), _SOCIAL_ACCOUNT_PROFILE_MAX_PAGE_SIZE))
    safe_offset = (safe_page - 1) * safe_page_size
    order_by_sql = _comments_only_profile_order_by_sql(
        sort_by=sort_by,
        sort_dir=sort_dir,
        missing_comments_sql="greatest(coalesce(filtered_rows.missing_comments, 0), 0)",
    )
    owner_match_clause = _instagram_owner_account_match_sql(alias="p")
    lifecycle_supported = _comment_lifecycle_supported("instagram_comments", conn=conn)
    use_comment_rollups = _instagram_post_comment_rollups_available(conn=conn)
    active_condition = "c.is_missing is not true" if lifecycle_supported else "true"
    missing_condition = "c.is_missing is true" if lifecycle_supported else "false"
    fb_crosspost_condition = "coalesce(c.source_snapshot_type, '') = 'fb_crosspost'"
    parent_external_expr = "nullif(coalesce(c.parent_comment_external_id, ''), '')"
    reply_depth_expr = "coalesce(c.reply_depth, 0)"
    reply_condition = f"""
        (
          coalesce(c.is_reply, false)
          or c.parent_comment_id is not null
          or {parent_external_expr} is not null
          or ({reply_depth_expr}) > 0
        )
    """
    reported_comments_expr = _instagram_reported_comments_sql("p")
    facebook_comments_expr = _instagram_external_facebook_comments_sql("p")
    catalog_facebook_comments_expr = _instagram_external_facebook_comments_sql("p", fb_comment_count_expr="null::text")
    accounted_comments_sql = (
        "coalesce(saved_comment_counts.saved_parent_comments, 0) + "
        "coalesce(saved_comment_counts.saved_child_replies, 0) + "
        "coalesce(d.facebook_comments, 0) + "
        "coalesce(saved_comment_counts.classified_missing_comments, 0)"
    )
    filter_where_sql = _comments_only_profile_filter_where_sql(
        comment_filter=normalized_comment_filter,
        reported_comments_sql="d.comments_count",
        saved_comments_sql="saved_comment_counts.saved_comments",
        accounted_comments_sql=accounted_comments_sql,
        reported_comments_is_normalized=True,
    )
    search_where_sql, search_params = _comments_only_profile_search_where_sql(search, alias="d")
    candidate_rows_sql = f"""
        with owner_rows as materialized (
          select
            p.id::text as id,
            p.id::text as profile_row_id,
            p.show_id::text as show_id,
            p.season_id::text as season_id,
            p.source_account,
            p.shortcode as source_id,
            p.shortcode as shortcode,
            p.posted_at,
            s.season_number,
            sh.name as show_name,
            sh.slug as show_slug,
            null::text as title,
            p.caption,
            null::text as description,
            null::text as text,
            p.media_type,
            coalesce(p.media_urls, '[]'::jsonb) as media_urls,
            nullif(p.thumbnail_url, '') as thumbnail_url,
            coalesce(p.media_urls, '[]'::jsonb) as source_media_urls,
            coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
            nullif(p.thumbnail_url, '') as source_thumbnail_url,
            nullif(coalesce(to_jsonb(p) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
            nullif(coalesce(to_jsonb(p) ->> 'post_format', ''), '') as post_format,
            coalesce(p.hashtags, '[]'::jsonb) as hashtags,
            coalesce(p.mentions, '[]'::jsonb) as mentions,
            coalesce(p.collaborators, '[]'::jsonb) as collaborators,
            coalesce(to_jsonb(p) -> 'collaborators_detail', '[]'::jsonb) as collaborators_detail,
            coalesce(p.profile_tags, '[]'::jsonb) as profile_tags,
            coalesce(p.likes, 0)::bigint as likes,
            {reported_comments_expr}::bigint as comments_count,
            {facebook_comments_expr}::bigint as facebook_comments,
            p.fb_comment_count,
            p.facebook_crosspost_observed_at,
            p.facebook_crosspost_source,
            p.facebook_post_id,
            p.facebook_post_url,
            coalesce(p.views, 0)::bigint as views,
            p.media_repost_count::bigint as media_repost_count,
            coalesce(p.media_repost_count, 0)::bigint as shares,
            0::bigint as retweets,
            0::bigint as replies_count,
            0::bigint as quotes,
            coalesce(p.raw_data, '{{}}'::jsonb) as raw_data,
            null::text as permalink,
            'materialized'::text as _profile_source_surface,
            'owner'::text as _profile_match_mode,
            3::int as _profile_dataset_priority
          from social.instagram_posts p
          left join core.seasons s on s.id = p.season_id
          left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
          where {owner_match_clause}
            and nullif(p.shortcode, '') is not null
        ),
        collaborator_rows as materialized (
          select
            p.id::text as id,
            materialized_post.id::text as profile_row_id,
            p.assigned_show_id::text as show_id,
            p.assigned_season_id::text as season_id,
            p.source_account,
            p.source_id as source_id,
            p.source_id as shortcode,
            p.posted_at,
            s.season_number,
            sh.name as show_name,
            sh.slug as show_slug,
            p.title,
            p.caption,
            p.description,
            p.text,
            p.media_type,
            coalesce(p.media_urls, '[]'::jsonb) as media_urls,
            nullif(p.thumbnail_url, '') as thumbnail_url,
            coalesce(p.media_urls, '[]'::jsonb) as source_media_urls,
            coalesce(to_jsonb(p) -> 'hosted_media_urls', '[]'::jsonb) as hosted_media_urls,
            nullif(p.thumbnail_url, '') as source_thumbnail_url,
            nullif(coalesce(to_jsonb(p) ->> 'hosted_thumbnail_url', ''), '') as hosted_thumbnail_url,
            nullif(coalesce(to_jsonb(p) ->> 'post_format', ''), '') as post_format,
            coalesce(p.hashtags, '[]'::jsonb) as hashtags,
            coalesce(p.mentions, '[]'::jsonb) as mentions,
            coalesce(p.collaborators, '[]'::jsonb) as collaborators,
            coalesce(to_jsonb(p) -> 'collaborators_detail', p.raw_data -> 'collaborators_detail', '[]'::jsonb)
              as collaborators_detail,
            coalesce(p.profile_tags, '[]'::jsonb) as profile_tags,
            coalesce(p.likes, 0)::bigint as likes,
            {reported_comments_expr}::bigint as comments_count,
            {catalog_facebook_comments_expr}::bigint as facebook_comments,
            null::integer as fb_comment_count,
            null::timestamptz as facebook_crosspost_observed_at,
            null::text as facebook_crosspost_source,
            null::text as facebook_post_id,
            null::text as facebook_post_url,
            coalesce(p.views, 0)::bigint as views,
            null::bigint as media_repost_count,
            coalesce(p.shares, 0)::bigint as shares,
            coalesce(p.retweets, 0)::bigint as retweets,
            coalesce(p.replies_count, 0)::bigint as replies_count,
            coalesce(p.quotes, 0)::bigint as quotes,
            coalesce(p.raw_data, '{{}}'::jsonb) as raw_data,
            p.permalink,
            'catalog'::text as _profile_source_surface,
            'collaborator'::text as _profile_match_mode,
            1::int as _profile_dataset_priority
          from social.instagram_account_catalog_post_collaborators m
          join social.instagram_account_catalog_posts p
            on p.id = m.catalog_post_id
          left join social.instagram_posts materialized_post
            on materialized_post.shortcode = p.source_id
          left join core.seasons s on s.id = p.assigned_season_id
          left join core.shows sh on sh.id = coalesce(p.assigned_show_id, s.show_id)
          where m.collaborator_handle = %s
            and lower(p.source_account) <> %s
            and nullif(p.source_id, '') is not null
        ),
        deduped_rows as materialized (
          select distinct on (source_id)
            *
          from (
            select * from owner_rows
            union all
            select * from collaborator_rows
          ) candidate_rows
          order by
            source_id,
            _profile_dataset_priority desc,
            posted_at desc nulls last,
            id desc
        ),
        {
        _instagram_comments_only_saved_counts_cte_sql(
            source_cte="deduped_rows",
            use_rollup=use_comment_rollups,
        ).format(
            active_condition=active_condition,
            fb_crosspost_condition=fb_crosspost_condition,
            reply_condition=reply_condition,
            missing_condition=missing_condition,
            source_cte="deduped_rows",
        )
    },
        filtered_rows as materialized (
          select
            d.*,
            coalesce(saved_comment_counts.saved_parent_comments, 0)::int as saved_parent_comments,
            coalesce(saved_comment_counts.saved_child_replies, 0)::int as saved_child_replies,
            coalesce(saved_comment_counts.saved_comments, 0)::int as saved_comments,
            coalesce(saved_comment_counts.classified_missing_comments, 0)::int as classified_missing_comments,
            greatest(
              coalesce(d.comments_count, 0)
              - coalesce(saved_comment_counts.saved_comments, 0)
              - coalesce(saved_comment_counts.classified_missing_comments, 0)
              - coalesce(d.facebook_comments, 0),
              0
            )::int as missing_comments
          from deduped_rows d
          left join saved_comment_counts
            on saved_comment_counts.profile_row_id = d.profile_row_id
          where {filter_where_sql}
            {search_where_sql}
        )
    """
    params = [normalized_account, normalized_account, normalized_account, *search_params]
    page_sql = f"""
        {candidate_rows_sql}
        select *, count(*) over()::int as _total_count
        from filtered_rows
        order by {order_by_sql}
        limit %s offset %s
    """
    if conn is None:
        rows = pg.fetch_all(page_sql, [*params, safe_page_size, safe_offset])
        total_row = {}
        if rows and rows[0].get("_total_count") is not None:
            total_row = {"total": rows[0].get("_total_count")}
        else:
            total_sql = f"""
                {candidate_rows_sql}
                select count(*)::int as total
                from filtered_rows
            """
            total_row = pg.fetch_one(total_sql, params) or {}
    else:
        with pg.db_cursor(conn=conn, label="instagram_comments_only_profile_rows") as cur:
            rows = pg.fetch_all_with_cursor(cur, page_sql, [*params, safe_page_size, safe_offset])
        total_row = {}
        if rows and rows[0].get("_total_count") is not None:
            total_row = {"total": rows[0].get("_total_count")}
        else:
            total_sql = f"""
                {candidate_rows_sql}
                select count(*)::int as total
                from filtered_rows
            """
            with pg.db_cursor(conn=conn, label="instagram_comments_only_profile_total") as cur:
                total_row = pg.fetch_one_with_cursor(cur, total_sql, params) or {}
    total = _normalize_non_negative_int(total_row.get("total"))
    return rows, total


def _annotate_instagram_social_account_profile_dataset_rows(
    rows: Sequence[Mapping[str, Any]],
    *,
    source_surface: str,
    match_mode: str,
    priority: int,
) -> list[dict[str, Any]]:
    return [
        {
            **dict(row),
            "_profile_source_surface": source_surface,
            "_profile_match_mode": match_mode,
            "_profile_dataset_priority": priority,
        }
        for row in rows
    ]


def _dedupe_social_account_profile_dataset_rows(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    best_rows_by_key: dict[str, dict[str, Any]] = {}
    for row in rows:
        normalized_row = dict(row)
        source_id = str(normalized_row.get("source_id") or "").strip()
        dedupe_key = source_id or f"{normalized_row.get('_profile_source_surface')}:{normalized_row.get('id')}"
        existing = best_rows_by_key.get(dedupe_key)
        if existing is None:
            best_rows_by_key[dedupe_key] = normalized_row
            continue
        next_priority = int(normalized_row.get("_profile_dataset_priority") or 0)
        current_priority = int(existing.get("_profile_dataset_priority") or 0)
        if next_priority > current_priority:
            best_rows_by_key[dedupe_key] = normalized_row
            continue
        if next_priority == current_priority and _social_account_profile_row_sort_value(
            normalized_row.get("posted_at")
        ) > _social_account_profile_row_sort_value(existing.get("posted_at")):
            best_rows_by_key[dedupe_key] = normalized_row
    return list(best_rows_by_key.values())


def _timed_social_account_profile_summary_query(
    *,
    platform: str,
    account_handle: str,
    query_name: str,
    loader: Callable[[], Any],
    fallback: Callable[[Exception], Any] | None = None,
) -> Any:
    started_at = time_module.perf_counter()
    try:
        result = loader()
    except Exception as exc:
        elapsed_ms = int((time_module.perf_counter() - started_at) * 1000)
        status = "fallback" if fallback is not None else "error"
        logger.info(
            (
                "Social account profile summary query completed: platform=%s account=%s "
                "query=%s status=%s elapsed_ms=%s error=%s"
            ),
            platform,
            account_handle,
            query_name,
            status,
            elapsed_ms,
            exc,
        )
        if fallback is None:
            raise
        return fallback(exc)
    elapsed_ms = int((time_module.perf_counter() - started_at) * 1000)
    logger.info(
        "Social account profile summary query completed: platform=%s account=%s query=%s status=ok elapsed_ms=%s",
        platform,
        account_handle,
        query_name,
        elapsed_ms,
    )
    return result


def _lite_social_account_catalog_run(row: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "job_id": row.get("job_id"),
        "run_id": row.get("run_id"),
        "status": row.get("status"),
        "created_at": row.get("created_at"),
        "started_at": row.get("started_at"),
        "completed_at": row.get("completed_at"),
        "error_message": row.get("error_message"),
        "catalog_action": row.get("catalog_action"),
        "catalog_action_scope": row.get("catalog_action_scope"),
        "launch_group_id": row.get("launch_group_id"),
        "launch_state": row.get("launch_state"),
        "selected_tasks": row.get("selected_tasks") or [],
        "effective_selected_tasks": row.get("effective_selected_tasks") or [],
        "comments_run_id": row.get("comments_run_id"),
        "attached_followups": row.get("attached_followups") or {},
    }


def _call_profile_summary_loader_with_conn(
    loader: Callable[..., Any],
    /,
    *args: Any,
    conn: Any | None = None,
    **kwargs: Any,
) -> Any:
    if conn is None:
        return loader(*args, **kwargs)
    try:
        return loader(*args, conn=conn, **kwargs)
    except TypeError as exc:
        if "unexpected keyword argument 'conn'" not in str(exc):
            raise
        return loader(*args, **kwargs)


def _call_with_optional_conn(
    loader: Callable[..., Any],
    /,
    *args: Any,
    conn: Any | None = None,
    **kwargs: Any,
) -> Any:
    if conn is None:
        return loader(*args, **kwargs)
    return loader(*args, conn=conn, **kwargs)


def _social_account_profile_summary_connection(label: str):
    return pg.db_read_connection(label=label, pool_name="social_profile")


def _social_profile_perf_enabled() -> bool:
    return _env_truthy("TRR_SOCIAL_PROFILE_PERF_DEBUG", default=False)


@contextmanager
def _social_profile_perf_span(breakdown: dict[str, float], key: str):
    started_at = time_module.perf_counter()
    try:
        yield
    finally:
        elapsed_ms = (time_module.perf_counter() - started_at) * 1000.0
        breakdown[key] = breakdown.get(key, 0.0) + elapsed_ms


def _log_social_profile_perf(
    *,
    route: str,
    platform: str,
    handle: str,
    breakdown: Mapping[str, float],
) -> None:
    if not _social_profile_perf_enabled():
        return
    timings_ms = {key: float(value) for key, value in breakdown.items()}
    total_ms = sum(float(value) for value in breakdown.values())
    logger.info(
        "[social-profile-perf] route=%s platform=%s handle=%s total_ms=%.1f timings_ms=%s",
        route,
        platform,
        handle,
        total_ms,
        timings_ms,
    )


def _social_account_profile_summary_totals_from_rows(
    platform: str,
    account_handle: str,
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    items = [_social_account_profile_post_item(platform, row, account_handle=account_handle) for row in rows]
    posted_values = [
        _social_account_profile_row_sort_value(item.get("posted_at"))
        for item in items
        if _social_account_profile_row_sort_value(item.get("posted_at"))
    ]
    return {
        "total_posts": len(items),
        "total_engagement": sum(
            _normalize_non_negative_int(item.get("metrics", {}).get("engagement")) for item in items
        ),
        "total_views": sum(_normalize_non_negative_int(item.get("metrics", {}).get("views")) for item in items),
        "first_post_at": min(posted_values) if posted_values else None,
        "last_post_at": max(posted_values) if posted_values else None,
    }


def _merge_social_account_profile_summary_totals(
    totals: Mapping[str, Any] | None,
    fallback_totals: Mapping[str, Any],
) -> dict[str, Any]:
    merged = dict(totals or {})
    for key in ("total_posts", "total_engagement", "total_views", "first_post_at", "last_post_at"):
        if merged.get(key) is None:
            merged[key] = fallback_totals.get(key)
    return merged


def _social_account_profile_total_posts(
    platform: str,
    account_handle: str,
    *,
    search: str | None = None,
    conn: Any | None = None,
) -> int:
    return _materialized_social_account_total_posts(platform, account_handle, search=search, conn=conn)


def _materialized_social_account_total_posts(
    platform: str,
    account_handle: str,
    *,
    date_start: datetime | None = None,
    date_end: datetime | None = None,
    search: str | None = None,
    conn: Any | None = None,
) -> int:
    table, _, _ = _social_account_profile_base_query_parts(platform)
    _, _, posted_at_column = _social_account_profile_base_query_parts(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    owner_match_clause = _social_account_profile_owner_match_sql(platform, alias="p")
    search_clause, search_params = _social_account_profile_search_sql_parts(platform, search=search)
    start_dt = _coerce_dt(date_start)
    end_dt = _coerce_dt(date_end)
    date_clauses: list[str] = []
    date_params: list[Any] = []
    if start_dt is not None:
        date_clauses.append(f"and p.{posted_at_column} >= %s")
        date_params.append(start_dt)
    if end_dt is not None:
        date_clauses.append(f"and p.{posted_at_column} < %s")
        date_params.append(end_dt)
    sql = f"""
        select count(*)::int as total
        from social.{table} p
        left join core.seasons s on s.id = p.season_id
        left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
        where {owner_match_clause}
          {search_clause}
          {" ".join(date_clauses)}
        """
    params = [normalized_account, *search_params, *date_params]
    if conn is None:
        row = pg.fetch_one(sql, params) or {}
    else:
        with pg.db_cursor(conn=conn, label="materialized_social_account_total_posts") as cur:
            row = pg.fetch_one_with_cursor(cur, sql, params) or {}
    return _normalize_non_negative_int(row.get("total"))


def _social_account_profile_analysis_rows(
    platform: str,
    account_handle: str,
    *,
    limit: int | None = None,
    posted_since: datetime | None = None,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if normalized_platform == "instagram":
        collaborator_posted_since = posted_since
        if collaborator_posted_since is None:
            collaborator_posted_since = _now_utc() - timedelta(
                days=_INSTAGRAM_SOCIAL_ACCOUNT_PROFILE_SUMMARY_COLLABORATOR_LOOKBACK_DAYS
            )
        rows = _call_profile_summary_loader_with_conn(
            _instagram_social_account_profile_dataset_rows,
            normalized_account,
            limit=limit,
            posted_since=posted_since,
            collaborator_posted_since=collaborator_posted_since,
            conn=conn,
        )
        if limit is not None:
            return rows[: max(1, int(limit))]
        return rows
    if normalized_platform in set(CATALOG_SUPPORTED_PLATFORMS):
        catalog_rows = _call_profile_summary_loader_with_conn(
            _fetch_shared_catalog_rows,
            normalized_platform,
            normalized_account,
            limit=limit,
            conn=conn,
        )
        if catalog_rows:
            return catalog_rows
    return _call_profile_summary_loader_with_conn(
        _fetch_social_account_profile_rows,
        normalized_platform,
        normalized_account,
        limit=limit,
        projection="summary",
        posted_since=posted_since,
        conn=conn,
    )


def _social_account_profile_summary_raw_data_sql(platform: str, alias: str = "p") -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    row_json = f"to_jsonb({alias})"
    if normalized_platform == "tiktok":
        return (
            "jsonb_strip_nulls(jsonb_build_object("
            f"'author', coalesce({row_json} -> 'raw_data' -> 'author', '{{}}'::jsonb), "
            f"'description', {row_json} -> 'raw_data' -> 'description', "
            f"'caption', {row_json} -> 'raw_data' -> 'caption', "
            f"'text', {row_json} -> 'raw_data' -> 'text', "
            f"'verified', {row_json} -> 'raw_data' -> 'verified', "
            f"'user_avatar_url', {row_json} -> 'raw_data' -> 'user_avatar_url'"
            "))"
        )
    if normalized_platform == "twitter":
        return (
            "jsonb_strip_nulls(jsonb_build_object("
            f"'username', {row_json} -> 'raw_data' -> 'username', "
            f"'display_name', {row_json} -> 'raw_data' -> 'display_name', "
            f"'full_name', {row_json} -> 'raw_data' -> 'full_name', "
            f"'user_avatar_url', {row_json} -> 'raw_data' -> 'user_avatar_url', "
            f"'user_verified', {row_json} -> 'raw_data' -> 'user_verified', "
            f"'is_verified', {row_json} -> 'raw_data' -> 'is_verified', "
            f"'user_profile_url', {row_json} -> 'raw_data' -> 'user_profile_url'"
            "))"
        )
    if normalized_platform == "threads":
        return (
            "jsonb_strip_nulls(jsonb_build_object("
            f"'username', {row_json} -> 'raw_data' -> 'username', "
            f"'full_name', {row_json} -> 'raw_data' -> 'full_name', "
            f"'user_avatar_url', {row_json} -> 'raw_data' -> 'user_avatar_url', "
            f"'is_verified', {row_json} -> 'raw_data' -> 'is_verified', "
            f"'user_profile_url', {row_json} -> 'raw_data' -> 'user_profile_url', "
            f"'caption', {row_json} -> 'raw_data' -> 'caption'"
            "))"
        )
    if normalized_platform == "facebook":
        return (
            "jsonb_strip_nulls(jsonb_build_object("
            f"'username', {row_json} -> 'raw_data' -> 'username', "
            f"'user_avatar_url', {row_json} -> 'raw_data' -> 'user_avatar_url', "
            f"'text', {row_json} -> 'raw_data' -> 'text', "
            f"'message', {row_json} -> 'raw_data' -> 'message'"
            "))"
        )
    if normalized_platform == "youtube":
        return (
            "jsonb_strip_nulls(jsonb_build_object("
            f"'canonical_handle', {row_json} -> 'raw_data' -> 'canonical_handle', "
            f"'channel_title', {row_json} -> 'raw_data' -> 'channel_title', "
            f"'resolved_channel_title', {row_json} -> 'raw_data' -> 'resolved_channel_title', "
            f"'user_avatar_url', {row_json} -> 'raw_data' -> 'user_avatar_url', "
            f"'resolved_channel_avatar_url', {row_json} -> 'raw_data' -> 'resolved_channel_avatar_url', "
            f"'channel_id', {row_json} -> 'raw_data' -> 'channel_id', "
            f"'canonical_channel_id', {row_json} -> 'raw_data' -> 'canonical_channel_id'"
            "))"
        )
    return "'{}'::jsonb"


def _fetch_social_account_profile_rows(
    platform: str,
    account_handle: str,
    *,
    limit: int | None = None,
    offset: int = 0,
    search: str | None = None,
    projection: Literal["detail", "summary"] = "detail",
    posted_since: datetime | None = None,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    table, source_id_column, posted_at_column = _social_account_profile_base_query_parts(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    owner_match_clause = _social_account_profile_owner_match_sql(platform, alias="p")
    params: list[Any] = [normalized_account]
    posted_since_clause = ""
    if posted_since is not None:
        normalized_posted_since = (
            posted_since.astimezone(UTC) if posted_since.tzinfo else posted_since.replace(tzinfo=UTC)
        )
        posted_since_clause = f"and p.{posted_at_column} >= %s"
        params.append(normalized_posted_since)
    search_clause, search_params = _social_account_profile_search_sql_parts(platform, search=search)
    params.extend(search_params)
    limit_clause = ""
    if limit is not None:
        safe_limit = max(1, min(int(limit), _SOCIAL_ACCOUNT_PROFILE_MAX_PAGE_SIZE))
        limit_clause = "limit %s offset %s"
        params.extend([safe_limit, max(0, int(offset))])
    if projection == "summary":
        summary_raw_data_sql = _social_account_profile_summary_raw_data_sql(platform, alias="p")
        select_fields = f"""
          p.id::text as id,
          p.show_id::text as show_id,
          p.season_id::text as season_id,
          p.source_account,
          p.{source_id_column} as source_id,
          p.{posted_at_column} as posted_at,
          s.season_number,
          sh.name as show_name,
          sh.slug as show_slug,
          to_jsonb(p) ->> 'shortcode' as shortcode,
          to_jsonb(p) ->> 'video_id' as video_id,
          to_jsonb(p) ->> 'tweet_id' as tweet_id,
          to_jsonb(p) ->> 'post_id' as post_id,
          to_jsonb(p) ->> 'title' as title,
          to_jsonb(p) ->> 'headline' as headline,
          to_jsonb(p) ->> 'caption' as caption,
          to_jsonb(p) ->> 'description' as description,
          to_jsonb(p) ->> 'text' as text,
          to_jsonb(p) ->> 'full_text' as full_text,
          to_jsonb(p) ->> 'message' as message,
          to_jsonb(p) ->> 'username' as username,
          to_jsonb(p) ->> 'display_name' as display_name,
          to_jsonb(p) ->> 'channel_title' as channel_title,
          to_jsonb(p) ->> 'channel_id' as channel_id,
          to_jsonb(p) ->> 'user_avatar_url' as user_avatar_url,
          to_jsonb(p) ->> 'user_profile_url' as user_profile_url,
          to_jsonb(p) ->> 'user_verified' as user_verified,
          to_jsonb(p) ->> 'likes' as likes,
          to_jsonb(p) ->> 'comments_count' as comments_count,
          to_jsonb(p) ->> 'views' as views,
          to_jsonb(p) ->> 'video_view_count' as video_view_count,
          to_jsonb(p) ->> 'video_play_count' as video_play_count,
          to_jsonb(p) ->> 'media_repost_count' as media_repost_count,
          to_jsonb(p) ->> 'shares' as shares,
          to_jsonb(p) ->> 'retweets' as retweets,
          to_jsonb(p) ->> 'replies_count' as replies_count,
          to_jsonb(p) ->> 'quotes' as quotes,
          coalesce(to_jsonb(p) -> 'hashtags', '[]'::jsonb) as hashtags,
          coalesce(to_jsonb(p) -> 'tags', '[]'::jsonb) as tags,
          coalesce(to_jsonb(p) -> 'mentions', '[]'::jsonb) as mentions,
          coalesce(to_jsonb(p) -> 'collaborators', '[]'::jsonb) as collaborators,
          coalesce(to_jsonb(p) -> 'collaborators_detail', '[]'::jsonb) as collaborators_detail,
          coalesce(to_jsonb(p) -> 'profile_tags', '[]'::jsonb) as profile_tags,
          {summary_raw_data_sql} as raw_data
        """
    else:
        select_fields = f"""
          p.id::text as id,
          p.show_id::text as show_id,
          p.season_id::text as season_id,
          p.source_account,
          p.{source_id_column} as source_id,
          p.{posted_at_column} as posted_at,
          s.season_number,
          sh.name as show_name,
          sh.slug as show_slug,
          p.*
        """
    query = f"""
        select
          {select_fields}
        from social.{table} p
        left join core.seasons s on s.id = p.season_id
        left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
        where {owner_match_clause}
          {posted_since_clause}
          {search_clause}
        order by p.{posted_at_column} desc nulls last, p.id desc
        {limit_clause}
        """
    if conn is not None:
        with pg.db_cursor(conn=conn, label="social_account_profile_rows") as cur:
            return pg.fetch_all_with_cursor(cur, query, params)
    return pg.fetch_all(query, params)


def _fetch_instagram_social_account_profile_entity_rows(
    account_handle: str,
    *,
    posted_since: datetime | None = None,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    owner_match_clause = _social_account_profile_owner_match_sql("instagram", alias="p")
    params: list[Any] = [normalized_account]
    posted_since_clause = ""
    if posted_since is not None:
        normalized_posted_since = (
            posted_since.astimezone(UTC) if posted_since.tzinfo else posted_since.replace(tzinfo=UTC)
        )
        posted_since_clause = "and p.posted_at >= %s"
        params.append(normalized_posted_since)
    query = f"""
        select
          p.id::text as id,
          p.show_id::text as show_id,
          p.season_id::text as season_id,
          p.source_account,
          p.shortcode as source_id,
          p.shortcode as shortcode,
          p.posted_at,
          s.season_number,
          sh.name as show_name,
          sh.slug as show_slug,
          null::text as title,
          p.caption,
          null::text as description,
          null::text as text,
          coalesce(p.hashtags, '[]'::jsonb) as hashtags,
          coalesce(p.mentions, '[]'::jsonb) as mentions,
          coalesce(p.collaborators, '[]'::jsonb) as collaborators,
          coalesce(p.collaborators_detail, '[]'::jsonb) as collaborators_detail,
          coalesce(p.profile_tags, '[]'::jsonb) as profile_tags
        from social.instagram_posts p
        left join core.seasons s on s.id = p.season_id
        left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
        where {owner_match_clause}
          and nullif(p.shortcode, '') is not null
          {posted_since_clause}
        order by p.posted_at desc nulls last, p.id desc
        """
    if conn is not None:
        with pg.db_cursor(conn=conn, label="instagram_profile_entity_rows") as cur:
            return pg.fetch_all_with_cursor(cur, query, params)
    return pg.fetch_all(query, params)


def _fetch_social_account_profile_materialized_row(
    platform: str,
    account_handle: str,
    *,
    source_id: str,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    table, source_id_column, posted_at_column = _social_account_profile_base_query_parts(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_source_id = str(source_id or "").strip()
    if not normalized_source_id:
        return None
    owner_match_clause = _social_account_profile_owner_match_sql(platform, alias="p")
    query = f"""
        select
          p.id::text as id,
          p.show_id::text as show_id,
          p.season_id::text as season_id,
          p.source_account,
          p.{source_id_column} as source_id,
          p.{posted_at_column} as posted_at,
          s.season_number,
          sh.name as show_name,
          sh.slug as show_slug,
          p.*
        from social.{table} p
        left join core.seasons s on s.id = p.season_id
        left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
        where {owner_match_clause}
          and p.{source_id_column} = %s
        order by p.{posted_at_column} desc nulls last, p.id desc
        limit 1
        """
    params = [normalized_account, normalized_source_id]
    if conn is not None:
        with pg.db_cursor(conn=conn, label="social_account_profile_post_row") as cur:
            return pg.fetch_one_with_cursor(cur, query, params)
    return pg.fetch_one(query, params)


def _assert_social_account_profile_exists(
    platform: str,
    account_handle: str,
    *,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    source_rows = _call_profile_summary_loader_with_conn(
        _fetch_social_account_profile_source_rows,
        normalized_platform,
        normalized_account,
        conn=conn,
    )
    if source_rows:
        return source_rows

    if normalized_platform == "instagram" and _call_profile_summary_loader_with_conn(
        _instagram_social_account_profile_has_materialized_rows,
        normalized_account,
        conn=conn,
    ):
        return source_rows

    catalog_total_posts = (
        _call_profile_summary_loader_with_conn(
            _shared_catalog_total_posts,
            normalized_platform,
            normalized_account,
            conn=conn,
        )
        if normalized_platform in set(CATALOG_SUPPORTED_PLATFORMS)
        else 0
    )
    if catalog_total_posts > 0:
        return source_rows

    if normalized_platform == "instagram" and _call_profile_summary_loader_with_conn(
        _instagram_social_account_profile_has_collaborator_catalog_rows,
        normalized_account,
        conn=conn,
    ):
        return source_rows

    total_posts = _call_profile_summary_loader_with_conn(
        _social_account_profile_total_posts,
        normalized_platform,
        normalized_account,
        conn=conn,
    )
    if total_posts <= 0 and catalog_total_posts <= 0 and not source_rows:
        raise LookupError("Social account profile not found.")
    return source_rows


def _fetch_social_account_profile_assignment_rows(
    platform: str,
    account_handle: str,
    *,
    include_all_platform_scopes: bool = False,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    del include_all_platform_scopes
    try:
        sql = """
            select
              a.id::text as id,
              null::text as platform,
              null::text as account_handle,
              a.normalized_hashtag,
              a.display_hashtag,
              a.show_id::text as show_id,
              a.season_id::text as season_id,
              'global'::text as assignment_scope,
              a.updated_by,
              a.created_at,
              a.updated_at,
              sh.name as show_name,
              sh.slug as show_slug
            from social.hashtag_assignments a
            join core.shows sh on sh.id = a.show_id
            order by
              a.normalized_hashtag asc,
              sh.name asc
            """
        params: list[Any] = []
        if conn is None:
            return pg.fetch_all(sql, params)
        with pg.db_cursor(conn=conn, label="profile_assignment_rows") as cur:
            return pg.fetch_all_with_cursor(cur, sql, params)
    except psycopg_errors.UndefinedTable:
        try:
            sql = """
                select
                  a.id::text as id,
                  a.platform,
                  a.account_handle,
                  a.normalized_hashtag,
                  a.display_hashtag,
                  a.show_id::text as show_id,
                  a.season_id::text as season_id,
                  'platform'::text as assignment_scope,
                  a.updated_by,
                  a.created_at,
                  a.updated_at,
                  sh.name as show_name,
                  sh.slug as show_slug
                from social.account_hashtag_assignments a
                join core.shows sh on sh.id = a.show_id
                where (a.platform = %s and a.account_handle = %s)
                  or (
                    a.account_handle = %s
                    and a.platform = any(%s::text[])
                  )
                order by a.normalized_hashtag asc, case when a.platform = %s then 0 else 1 end, sh.name asc
                """
            params = [
                normalized_platform,
                normalized_account,
                normalized_account,
                list(_SOCIAL_ACCOUNT_PROFILE_SHARED_HASHTAG_ASSIGNMENT_PLATFORMS),
                normalized_platform,
            ]
            if conn is None:
                return pg.fetch_all(sql, params)
            with pg.db_cursor(conn=conn, label="legacy_profile_assignment_rows") as cur:
                return pg.fetch_all_with_cursor(cur, sql, params)
        except psycopg_errors.UndefinedTable:
            pass
        logger.warning(
            "social.hashtag_assignments is not migrated yet; admin social profile hashtag lookups for %s/%s "
            "will return empty assignments until the canonical hashtag assignment migration is applied",
            normalized_platform,
            normalized_account,
        )
        return []


def _social_account_profile_engagement_sql(platform: str, alias: str = "p") -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform == "instagram":
        return f"(coalesce({alias}.likes, 0) + coalesce({alias}.comments_count, 0))"
    if normalized_platform == "tiktok":
        return f"(coalesce({alias}.likes, 0) + coalesce({alias}.comments_count, 0) + coalesce({alias}.shares, 0))"
    if normalized_platform == "twitter":
        return (
            f"(coalesce({alias}.likes, 0) + coalesce({alias}.retweets, 0) + "
            f"coalesce({alias}.replies_count, 0) + coalesce({alias}.quotes, 0))"
        )
    if normalized_platform == "youtube":
        return f"(coalesce({alias}.likes, 0) + coalesce({alias}.comments_count, 0))"
    if normalized_platform == "facebook":
        return f"(coalesce({alias}.likes, 0) + coalesce({alias}.comments_count, 0) + coalesce({alias}.shares, 0))"
    return f"(coalesce({alias}.likes, 0) + coalesce({alias}.comments_count, 0))"


def _social_account_profile_views_sql(platform: str, alias: str = "p") -> str:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    if normalized_platform in {"instagram", "tiktok", "youtube", "twitter"}:
        return f"coalesce({alias}.views, 0)"
    return "0"


def _social_account_profile_summary_totals(
    platform: str,
    account_handle: str,
    *,
    conn: Any | None = None,
) -> dict[str, Any]:
    table, _, posted_at_column = _social_account_profile_base_query_parts(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    owner_match_clause = _social_account_profile_owner_match_sql(platform, alias="p")
    engagement_expr = _social_account_profile_engagement_sql(platform)
    views_expr = _social_account_profile_views_sql(platform)
    sql = f"""
        select
          count(*)::int as total_posts,
          coalesce(sum({engagement_expr}), 0)::bigint as total_engagement,
          coalesce(sum({views_expr}), 0)::bigint as total_views,
          min(p.{posted_at_column}) as first_post_at,
          max(p.{posted_at_column}) as last_post_at
        from social.{table} p
        where {owner_match_clause}
        """
    if conn is None:
        return pg.fetch_one(sql, [normalized_account]) or {}
    with pg.db_cursor(conn=conn, label="social_account_profile_summary_totals") as cur:
        return pg.fetch_one_with_cursor(cur, sql, [normalized_account]) or {}


def _social_account_profile_grouped_counts(
    platform: str,
    account_handle: str,
    *,
    group_by: Literal["show", "season"],
) -> list[dict[str, Any]]:
    table, _, _ = _social_account_profile_base_query_parts(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    owner_match_clause = _social_account_profile_owner_match_sql(platform, alias="p")
    engagement_expr = _social_account_profile_engagement_sql(platform)
    if group_by == "show":
        sql = f"""
            select
              sh.id::text as show_id,
              sh.name as show_name,
              sh.slug as show_slug,
              count(*)::int as post_count,
              coalesce(sum({engagement_expr}), 0)::bigint as engagement
            from social.{table} p
            left join core.seasons s on s.id = p.season_id
            left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
            where {owner_match_clause}
            group by sh.id, sh.name, sh.slug
            order by count(*) desc, sh.name asc
        """
    else:
        sql = f"""
            select
              s.id::text as season_id,
              s.season_number,
              sh.id::text as show_id,
              sh.name as show_name,
              sh.slug as show_slug,
              count(*)::int as post_count,
              coalesce(sum({engagement_expr}), 0)::bigint as engagement
            from social.{table} p
            left join core.seasons s on s.id = p.season_id
            left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
            where {owner_match_clause}
            group by s.id, s.season_number, sh.id, sh.name, sh.slug
            order by count(*) desc, sh.name asc, s.season_number asc
        """
    return [row for row in pg.fetch_all(sql, [normalized_account]) if row.get("show_id") or row.get("season_id")]


def _shared_catalog_grouped_counts(
    platform: str,
    account_handle: str,
    *,
    group_by: Literal["show", "season"],
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    table, _, _ = _shared_catalog_base_query_parts(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    engagement_expr = _social_account_profile_engagement_sql(platform)
    account_match_clause = _shared_catalog_account_match_sql(platform, alias="p")
    if group_by == "show":
        sql = f"""
            select
              sh.id::text as show_id,
              sh.name as show_name,
              sh.slug as show_slug,
              count(*)::int as post_count,
              coalesce(sum({engagement_expr}), 0)::bigint as engagement
            from social.{table} p
            left join core.seasons s on s.id = p.assigned_season_id
            left join core.shows sh on sh.id = coalesce(p.assigned_show_id, s.show_id)
            where {account_match_clause}
              and (p.assigned_show_id is not null or p.assigned_season_id is not null)
            group by sh.id, sh.name, sh.slug
            order by count(*) desc, sh.name asc
        """
    else:
        sql = f"""
            select
              s.id::text as season_id,
              s.season_number,
              sh.id::text as show_id,
              sh.name as show_name,
              sh.slug as show_slug,
              count(*)::int as post_count,
              coalesce(sum({engagement_expr}), 0)::bigint as engagement
            from social.{table} p
            left join core.seasons s on s.id = p.assigned_season_id
            left join core.shows sh on sh.id = coalesce(p.assigned_show_id, s.show_id)
            where {account_match_clause}
              and p.assigned_season_id is not null
            group by s.id, s.season_number, sh.id, sh.name, sh.slug
            order by count(*) desc, sh.name asc, s.season_number asc
        """
    if conn is None:
        rows = pg.fetch_all(sql, [normalized_account])
    else:
        with pg.db_cursor(conn=conn, label=f"shared_catalog_{group_by}_counts") as cur:
            rows = pg.fetch_all_with_cursor(cur, sql, [normalized_account])
    return [row for row in rows if row.get("show_id") or row.get("season_id")]


def _social_account_profile_grouped_counts_from_rows(
    platform: str,
    account_handle: str,
    rows: Sequence[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    return _serialize_social_account_profile_post_buckets(
        [dict(row) for row in rows],
        platform,
        account_handle=account_handle,
    )


def _group_social_account_profile_assignments(
    assignment_rows: list[dict[str, Any]],
) -> dict[str, list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {}
    seen: dict[str, set[tuple[str, str | None]]] = {}
    for row in assignment_rows:
        hashtag = _normalize_social_account_profile_hashtag(row.get("normalized_hashtag") or row.get("display_hashtag"))
        show_id = str(row.get("show_id") or "") or None
        if not show_id:
            continue
        season_id = str(row.get("season_id") or "") or None
        dedupe_key = (show_id, season_id)
        if dedupe_key in seen.setdefault(hashtag, set()):
            continue
        seen[hashtag].add(dedupe_key)
        grouped.setdefault(hashtag, []).append(
            {
                "id": str(row.get("id") or ""),
                "show_id": show_id,
                "show_name": row.get("show_name"),
                "show_slug": row.get("show_slug"),
                "season_id": season_id,
                "season_number": None,
                "assignment_scope": "global",
                "platform": None,
                "updated_by": row.get("updated_by"),
                "updated_at": row.get("updated_at"),
            }
        )
    return grouped


def get_social_hashtag_assignment_conflict_history(*, limit: int = 25) -> dict[str, Any]:
    safe_limit = max(1, min(int(limit or 25), 100))
    sql = """
        select
          c.id::text as id,
          c.normalized_hashtag,
          c.display_hashtag,
          c.distinct_show_count,
          c.legacy_assignments,
          c.resolution_action,
          c.resolved_at
        from social.hashtag_assignment_backfill_conflicts c
        order by c.resolved_at desc, c.normalized_hashtag asc
        limit %s
        """
    try:
        rows = pg.fetch_all(sql, [safe_limit])
    except psycopg_errors.UndefinedTable:
        rows = []
    return {
        "items": [
            {
                "id": str(row.get("id") or ""),
                "hashtag": str(row.get("normalized_hashtag") or ""),
                "display_hashtag": row.get("display_hashtag") or f"#{row.get('normalized_hashtag')}",
                "distinct_show_count": _normalize_non_negative_int(row.get("distinct_show_count")),
                "legacy_assignments": row.get("legacy_assignments") or [],
                "resolution_action": str(row.get("resolution_action") or "merged_global_show_set"),
                "resolved_at": row.get("resolved_at"),
            }
            for row in rows
        ],
        "limit": safe_limit,
    }


def _is_rhoslc_official_hashtag_assignment_candidate(
    *,
    account_handle: str,
    hashtag: str,
) -> bool:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    normalized_hashtag = _normalize_social_account_profile_hashtag(hashtag)
    return (
        normalized_account in _BRAVO_OFFICIAL_ACCOUNT_ALIASES and normalized_hashtag in _RHOSLC_AUTO_ASSIGNED_HASHTAGS
    )


def _infer_social_account_profile_show_assignments(
    *,
    account_handle: str,
    hashtag: str,
    observed_shows: Mapping[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    if not _is_rhoslc_official_hashtag_assignment_candidate(account_handle=account_handle, hashtag=hashtag):
        return []

    inferred: list[dict[str, Any]] = []
    for show in observed_shows.values():
        show_id = str(show.get("show_id") or "").strip()
        show_slug = str(show.get("show_slug") or "").strip().lower()
        show_name = str(show.get("show_name") or "").strip()
        if not show_id:
            continue
        if show_slug != "rhoslc" and not _show_name_is_rhoslc(show_name):
            continue
        inferred.append(
            {
                "id": None,
                "show_id": show_id,
                "show_name": show.get("show_name"),
                "show_slug": show.get("show_slug"),
                "season_id": None,
                "season_number": None,
                "updated_by": "system:auto-rhoslc",
                "updated_at": None,
                "is_inferred": True,
            }
        )
    return inferred


def _serialize_social_account_profile_show_buckets(
    buckets: dict[str, dict[str, Any]],
) -> list[dict[str, Any]]:
    items = list(buckets.values())
    items.sort(
        key=lambda item: (
            -_normalize_non_negative_int(item.get("post_count")),
            str(item.get("show_name") or "").lower(),
            _normalize_non_negative_int(item.get("season_number")),
        )
    )
    return items


def _serialize_social_account_profile_post_buckets(
    rows: list[dict[str, Any]],
    platform: str,
    *,
    account_handle: str,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    show_buckets: dict[str, dict[str, Any]] = {}
    season_buckets: dict[str, dict[str, Any]] = {}
    for row in rows:
        post = _social_account_profile_post_item(platform, row, account_handle=account_handle)
        metrics = post["metrics"]
        show_id = str(post.get("show_id") or "")
        if show_id:
            bucket = show_buckets.setdefault(
                show_id,
                {
                    "show_id": show_id,
                    "show_name": post.get("show_name"),
                    "show_slug": post.get("show_slug"),
                    "post_count": 0,
                    "engagement": 0,
                },
            )
            bucket["post_count"] = _normalize_non_negative_int(bucket.get("post_count")) + 1
            bucket["engagement"] = _normalize_non_negative_int(bucket.get("engagement")) + _normalize_non_negative_int(
                metrics.get("engagement")
            )
        season_id = str(post.get("season_id") or "")
        if season_id:
            bucket = season_buckets.setdefault(
                season_id,
                {
                    "season_id": season_id,
                    "season_number": post.get("season_number"),
                    "show_id": post.get("show_id"),
                    "show_name": post.get("show_name"),
                    "show_slug": post.get("show_slug"),
                    "post_count": 0,
                    "engagement": 0,
                },
            )
            bucket["post_count"] = _normalize_non_negative_int(bucket.get("post_count")) + 1
            bucket["engagement"] = _normalize_non_negative_int(bucket.get("engagement")) + _normalize_non_negative_int(
                metrics.get("engagement")
            )
    return _serialize_social_account_profile_show_buckets(show_buckets), _serialize_social_account_profile_show_buckets(
        season_buckets
    )


def _build_social_account_profile_hashtag_items(
    rows: list[dict[str, Any]],
    *,
    platform: str,
    account_handle: str,
    assignment_rows: list[dict[str, Any]] | None = None,
) -> list[dict[str, Any]]:
    grouped_assignments = _group_social_account_profile_assignments(assignment_rows or [])
    items: dict[str, dict[str, Any]] = {}
    for row in rows:
        hashtags = _social_account_profile_hashtags_for_row(platform, row)
        show_id = str(row.get("show_id") or "") or None
        show_name = row.get("show_name")
        show_slug = row.get("show_slug")
        season_id = str(row.get("season_id") or "") or None
        season_number = _normalize_non_negative_int(row.get("season_number")) or None
        posted_at = row.get("posted_at")
        source_id = str(row.get("source_id") or "") or None
        for hashtag in hashtags:
            normalized = _normalize_social_account_profile_hashtag(hashtag)
            item = items.setdefault(
                normalized,
                {
                    "hashtag": normalized,
                    "display_hashtag": f"#{normalized}",
                    "usage_count": 0,
                    "first_seen_at": None,
                    "latest_seen_at": None,
                    "latest_source_id": None,
                    "assigned_shows": [],
                    "assigned_seasons": [],
                    "assignments": grouped_assignments.get(normalized, []),
                    "observed_shows": {},
                    "observed_seasons": {},
                },
            )
            item["usage_count"] = _normalize_non_negative_int(item.get("usage_count")) + 1
            if posted_at and (item.get("first_seen_at") is None or posted_at < item.get("first_seen_at")):
                item["first_seen_at"] = posted_at
            if posted_at and (item.get("latest_seen_at") is None or posted_at > item.get("latest_seen_at")):
                item["latest_seen_at"] = posted_at
                item["latest_source_id"] = source_id
            if show_id:
                observed_show = item["observed_shows"].setdefault(
                    show_id,
                    {
                        "show_id": show_id,
                        "show_name": show_name,
                        "show_slug": show_slug,
                        "post_count": 0,
                    },
                )
                observed_show["post_count"] = _normalize_non_negative_int(observed_show.get("post_count")) + 1
            if season_id:
                observed_season = item["observed_seasons"].setdefault(
                    season_id,
                    {
                        "season_id": season_id,
                        "season_number": season_number,
                        "show_id": show_id,
                        "show_name": show_name,
                        "show_slug": show_slug,
                        "post_count": 0,
                    },
                )
                observed_season["post_count"] = _normalize_non_negative_int(observed_season.get("post_count")) + 1

    results: list[dict[str, Any]] = []
    for normalized, item in items.items():
        assignments = list(item.get("assignments") or [])
        if not assignments:
            assignments = _infer_social_account_profile_show_assignments(
                account_handle=account_handle,
                hashtag=normalized,
                observed_shows=dict(item.get("observed_shows") or {}),
            )
            item["assignments"] = assignments
        item["assigned_shows"] = _serialize_social_account_profile_show_buckets(
            {
                str(assignment.get("show_id") or ""): {
                    "show_id": assignment.get("show_id"),
                    "show_name": assignment.get("show_name"),
                    "show_slug": assignment.get("show_slug"),
                    "post_count": 1,
                }
                for assignment in assignments
                if assignment.get("show_id")
            }
        )
        item["assigned_seasons"] = _serialize_social_account_profile_show_buckets(
            {
                str(assignment.get("season_id") or ""): {
                    "season_id": assignment.get("season_id"),
                    "season_number": assignment.get("season_number"),
                    "show_id": assignment.get("show_id"),
                    "show_name": assignment.get("show_name"),
                    "show_slug": assignment.get("show_slug"),
                    "post_count": 1,
                }
                for assignment in assignments
                if assignment.get("season_id")
            }
        )
        item["observed_shows"] = _serialize_social_account_profile_show_buckets(dict(item.get("observed_shows") or {}))
        item["observed_seasons"] = _serialize_social_account_profile_show_buckets(
            dict(item.get("observed_seasons") or {})
        )
        item["platform"] = _normalize_social_account_profile_platform(platform)
        item["account_handle"] = account_handle
        results.append(item)
        del normalized
    results.sort(
        key=lambda item: (-_normalize_non_negative_int(item.get("usage_count")), str(item.get("hashtag") or "").lower())
    )
    return results


def _build_social_account_profile_entity_aggregates(
    rows: list[dict[str, Any]],
    *,
    platform: str,
    account_handle: str,
) -> dict[str, list[dict[str, Any]]]:
    entity_buckets: dict[str, dict[str, dict[str, Any]]] = {"collaborators": {}, "tags": {}, "mentions": {}}
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    known_handle_identity_index = _build_social_account_profile_known_handle_identity_index(platform, rows)
    for row in rows:
        post_id = str(row.get("id") or "")
        show_id = str(row.get("show_id") or "") or None
        show_name = row.get("show_name")
        show_slug = row.get("show_slug")
        season_id = str(row.get("season_id") or "") or None
        season_number = _normalize_non_negative_int(row.get("season_number")) or None
        posted_at = row.get("posted_at")

        for kind, handles in (
            ("collaborators", _social_account_profile_collaborators_for_row(row)),
            ("tags", _social_account_profile_tags_for_row(platform, row)),
            (
                "mentions",
                _social_account_profile_mentions_for_row(
                    platform,
                    row,
                    known_handle_identity_index=known_handle_identity_index,
                ),
            ),
        ):
            for raw_handle in handles:
                handle = _normalize_account_handle(raw_handle)
                if not handle or handle == normalized_account:
                    continue
                bucket = entity_buckets[kind].setdefault(
                    handle,
                    {
                        "handle": handle,
                        "platform": _normalize_social_account_profile_platform(platform),
                        "profile_url": _platform_profile_url_for_handle(platform, handle),
                        "usage_count": 0,
                        "latest_seen_at": None,
                        "post_ids": set(),
                        "shows": {},
                        "seasons": {},
                    },
                )
                bucket["usage_count"] = _normalize_non_negative_int(bucket.get("usage_count")) + 1
                bucket["post_ids"].add(post_id)
                if posted_at and (bucket.get("latest_seen_at") is None or posted_at > bucket.get("latest_seen_at")):
                    bucket["latest_seen_at"] = posted_at
                if show_id:
                    observed_show = bucket["shows"].setdefault(
                        show_id,
                        {
                            "show_id": show_id,
                            "show_name": show_name,
                            "show_slug": show_slug,
                            "post_count": 0,
                        },
                    )
                    observed_show["post_count"] = _normalize_non_negative_int(observed_show.get("post_count")) + 1
                if season_id:
                    observed_season = bucket["seasons"].setdefault(
                        season_id,
                        {
                            "season_id": season_id,
                            "season_number": season_number,
                            "show_id": show_id,
                            "show_name": show_name,
                            "show_slug": show_slug,
                            "post_count": 0,
                        },
                    )
                    observed_season["post_count"] = _normalize_non_negative_int(observed_season.get("post_count")) + 1

    serialized: dict[str, list[dict[str, Any]]] = {}
    for kind, buckets in entity_buckets.items():
        items: list[dict[str, Any]] = []
        for bucket in buckets.values():
            items.append(
                {
                    "handle": bucket.get("handle"),
                    "platform": bucket.get("platform"),
                    "profile_url": bucket.get("profile_url"),
                    "usage_count": _normalize_non_negative_int(bucket.get("usage_count")),
                    "post_count": len(bucket.get("post_ids") or set()),
                    "latest_seen_at": bucket.get("latest_seen_at"),
                    "shows": _serialize_social_account_profile_show_buckets(dict(bucket.get("shows") or {})),
                    "seasons": _serialize_social_account_profile_show_buckets(dict(bucket.get("seasons") or {})),
                }
            )
        items.sort(
            key=lambda item: (
                -_normalize_non_negative_int(item.get("usage_count")),
                str(item.get("handle") or "").lower(),
            )
        )
        serialized[kind] = items
    return serialized


def _social_account_profile_avatar_url(
    platform: str,
    account_handle: str,
    rows: list[dict[str, Any]],
    *,
    conn: Any | None = None,
) -> str | None:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if not normalized_platform or not normalized_account:
        return None

    registry_entry = _avatar_registry_lookup_any(
        platform=normalized_platform,
        account_handle=normalized_account,
        conn=conn,
    )
    preferred_hosted_url = str((registry_entry or {}).get("hosted_url") or "").strip()
    if preferred_hosted_url.startswith(("http://", "https://")):
        return preferred_hosted_url

    candidates: list[Any] = []
    if registry_entry:
        candidates.append(registry_entry.get("source_url"))
    if normalized_platform in {"tiktok", "youtube"}:
        candidates.append(
            _cached_live_profile_snapshot_cached_only(normalized_platform, normalized_account).get("avatar_url")
        )

    for row in rows:
        metadata = _metadata_dict(row.get("metadata"))
        profile_snapshot = _metadata_dict(metadata.get("profile_snapshot"))
        candidates.extend(
            [
                profile_snapshot.get("avatar_url"),
                row.get("hosted_user_avatar_url"),
                row.get("user_avatar_url"),
                row.get("avatar_url"),
                row.get("profile_pic_url"),
                row.get("profile_pic_url_hd"),
                row.get("owner_profile_pic_url"),
                row.get("owner_profile_pic_url_hd"),
                row.get("hosted_owner_profile_pic_url"),
            ]
        )
        candidates.extend(_extract_avatar_url_candidates_from_raw_data(row.get("raw_data")))

    return _best_profile_avatar_url(candidates)


def _social_account_comments_coverage_status_label(status: str | None) -> str:
    normalized_status = str(status or "").strip().lower()
    if not normalized_status:
        return "Idle"
    if normalized_status == "needs_refresh":
        return "Needs refresh"
    return normalized_status.replace("_", " ").capitalize()


def _resolve_social_account_comments_coverage_status(
    coverage: Mapping[str, Any] | None,
    *,
    recent_runs: Sequence[Mapping[str, Any]] | None,
    comments_saved_summary: Mapping[str, Any] | None,
    active_run: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    if not isinstance(coverage, Mapping):
        return None

    payload = dict(coverage)
    normalized_recent_runs = [dict(row) for row in (recent_runs or []) if isinstance(row, Mapping)]
    latest_run = normalized_recent_runs[0] if normalized_recent_runs else {}
    normalized_active_run = dict(active_run) if isinstance(active_run, Mapping) else {}
    active_status = str(normalized_active_run.get("status") or "").strip().lower() or None
    latest_status = str(latest_run.get("status") or "").strip().lower() or None
    if _normalize_non_negative_int(normalized_active_run.get("running_jobs")) > 0:
        active_status = "running"
    if _normalize_non_negative_int(latest_run.get("running_jobs")) > 0:
        latest_status = "running"

    missing_posts = _normalize_non_negative_int(payload.get("missing_posts"))
    stale_posts = _normalize_non_negative_int(payload.get("stale_posts"))
    eligible_posts = _normalize_non_negative_int(payload.get("eligible_posts"))
    saved_comment_posts = _normalize_non_negative_int((comments_saved_summary or {}).get("saved_comment_posts"))
    saved_comments = _normalize_non_negative_int((comments_saved_summary or {}).get("saved_comments"))

    if normalized_active_run and _status_is_active(active_status):
        effective_status = active_status or "running"
        historical_failure = False
    elif missing_posts == 0 and stale_posts == 0 and eligible_posts > 0:
        effective_status = "covered"
        historical_failure = False
    elif saved_comment_posts > 0 or saved_comments > 0:
        effective_status = "needs_refresh"
        historical_failure = latest_status == "failed"
    elif latest_status == "failed":
        effective_status = "failed"
        historical_failure = False
    else:
        effective_status = "idle"
        historical_failure = False

    payload.update(
        {
            "effective_status": effective_status,
            "effective_label": _social_account_comments_coverage_status_label(effective_status),
            "historical_failure": historical_failure,
            "last_attempt_status": latest_status,
            "last_attempt_at": latest_run.get("completed_at") or latest_run.get("created_at"),
            "active_run_id": str(normalized_active_run.get("run_id") or "").strip() or None,
        }
    )
    return payload


