def _social_account_comments_recent_runs(
    platform: str,
    account_handle: str,
    *,
    limit: int = 3,
    conn: Any | None = None,
) -> list[dict[str, Any]]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    sql = """
        select
          r.id::text as run_id,
          case
            when lower(coalesce(r.status, '')) in ('queued', 'pending', 'retrying', 'running')
              and count(*) filter (where lower(coalesce(j.status, '')) = 'running') > 0 then 'running'
            else lower(nullif(r.status, ''))
          end as status,
          lower(nullif(r.status, '')) as run_status,
          r.created_at,
          r.started_at,
          r.completed_at,
          max(j.id::text) as job_id,
          max(nullif(j.error_message, '')) as error_message,
          count(*) filter (
            where lower(coalesce(r.status, '')) in ('queued', 'pending', 'retrying', 'running')
              and lower(coalesce(j.status, '')) = 'running'
          )::int as running_jobs,
          count(*) filter (
            where lower(coalesce(r.status, '')) in ('queued', 'pending', 'retrying', 'running')
              and lower(coalesce(j.status, '')) in ('queued', 'pending', 'retrying')
          )::int as queued_jobs,
          count(*) filter (where lower(coalesce(j.status, '')) = 'completed')::int as completed_jobs,
          count(*) filter (where lower(coalesce(j.status, '')) = 'failed')::int as failed_jobs
        from social.scrape_runs r
        join social.scrape_jobs j on j.run_id = r.id
        where j.platform = %s
          and coalesce(j.config->>'stage', j.metadata->>'stage', j.job_type) = %s
          and ltrim(lower(coalesce(j.config->>'account', j.metadata->>'account', '')), '@') = %s
        group by r.id, r.status, r.created_at, r.started_at, r.completed_at
        order by coalesce(r.started_at, r.created_at) desc, r.id desc
        limit %s
        """
    params = [normalized_platform, INSTAGRAM_COMMENTS_SCRAPLING_STAGE, normalized_account, max(1, int(limit))]
    if conn is None:
        rows = pg.fetch_all(sql, params)
    else:
        with pg.db_cursor(conn=conn, label="comments_recent_runs") as cur:
            rows = pg.fetch_all_with_cursor(cur, sql, params)
    return [
        {
            "run_id": str(row.get("run_id") or "").strip(),
            "job_id": str(row.get("job_id") or "").strip(),
            "status": str(row.get("status") or "").strip().lower() or None,
            "run_status": str(row.get("run_status") or "").strip().lower() or None,
            "created_at": row.get("created_at"),
            "started_at": row.get("started_at"),
            "completed_at": row.get("completed_at"),
            "error_message": row.get("error_message"),
            "running_jobs": _normalize_non_negative_int(row.get("running_jobs")),
            "queued_jobs": _normalize_non_negative_int(row.get("queued_jobs")),
            "completed_jobs": _normalize_non_negative_int(row.get("completed_jobs")),
            "failed_jobs": _normalize_non_negative_int(row.get("failed_jobs")),
        }
        for row in rows
        if str(row.get("run_id") or "").strip()
    ]


