def _catalog_runtime_supersession_lock_key(run_id: str) -> int:
    normalized_run_id = str(run_id or "").strip().lower()
    return int(hashlib.md5(f"catalog-runtime-supersession:{normalized_run_id}".encode()).hexdigest()[:15], 16) % (2**31)


def _load_catalog_run_row_by_id(run_id: str, *, conn: Any | None = None) -> dict[str, Any]:
    sql = """
        select
          id::text as id,
          id::text as run_id,
          season_id::text as season_id,
          status,
          source_scope,
          config,
          summary,
          created_at,
          started_at,
          completed_at
        from social.scrape_runs
        where id = %s::uuid
          and coalesce(config->>'pipeline_ingest_mode', '') = %s
        limit 1
    """
    params = [run_id, SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE]
    if conn is None:
        row = pg.fetch_one(sql, params)
    else:
        with pg.db_cursor(conn=conn, label="catalog_run_by_id") as cur:
            row = pg.fetch_one_with_cursor(cur, sql, params)
    return {
        "id": str((row or {}).get("id") or "").strip(),
        "run_id": str((row or {}).get("run_id") or "").strip(),
        "season_id": str((row or {}).get("season_id") or "").strip() or None,
        "status": str((row or {}).get("status") or "").strip().lower() or None,
        "source_scope": str((row or {}).get("source_scope") or "").strip() or None,
        "config": _metadata_dict((row or {}).get("config")),
        "summary": _metadata_dict((row or {}).get("summary")),
        "created_at": (row or {}).get("created_at"),
        "started_at": (row or {}).get("started_at"),
        "completed_at": (row or {}).get("completed_at"),
    }


def _merge_catalog_run_config_with_conn(
    *,
    conn: Any,
    run_id: str,
    metadata_updates: Mapping[str, Any],
) -> dict[str, Any]:
    with pg.db_cursor(conn=conn, label="catalog_run_config_merge") as cur:
        row = pg.fetch_one_with_cursor(
            cur,
            """
            update social.scrape_runs
            set config = coalesce(config, '{}'::jsonb) || %s::jsonb
            where id = %s::uuid
            returning
              id::text as id,
              status,
              config
            """,
            [_json_dumps(_metadata_dict(metadata_updates)), run_id],
        )
    _invalidate_queue_status_cache()
    return {
        "id": str((row or {}).get("id") or "").strip(),
        "status": str((row or {}).get("status") or "").strip().lower(),
        "config": _metadata_dict((row or {}).get("config")),
    }


def _find_catalog_replacement_run(
    *,
    platform: str,
    account_handle: str,
    superseded_run_id: str,
    conn: Any | None = None,
) -> dict[str, Any] | None:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    sql = """
        select
          r.id::text as run_id,
          r.status,
          r.config,
          r.summary,
          r.created_at,
          r.started_at,
          r.completed_at
        from social.scrape_runs r
        where coalesce(r.config->>'pipeline_ingest_mode', '') = %s
          and coalesce(r.config->>'superseded_run_id', '') = %s
          and %s = any(
            coalesce(
              array(
                select lower(trim(value::text, '"'))
                from jsonb_array_elements(coalesce(r.config->'platforms', '[]'::jsonb))
              ),
              array[]::text[]
            )
          )
          and %s = any(
            coalesce(
              array(
                select ltrim(lower(trim(value::text, '"')), '@')
                from jsonb_array_elements(coalesce(r.config->'accounts_override', '[]'::jsonb))
              ),
              array[]::text[]
            )
          )
        order by r.created_at desc, r.id desc
        limit 1
    """
    params = [SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE, superseded_run_id, normalized_platform, normalized_account]
    if conn is None:
        row = pg.fetch_one(sql, params)
    else:
        with pg.db_cursor(conn=conn, label="catalog_replacement_run") as cur:
            row = pg.fetch_one_with_cursor(cur, sql, params)
    if not row:
        return None
    return {
        "run_id": str(row.get("run_id") or "").strip(),
        "status": str(row.get("status") or "").strip().lower() or None,
        "config": _metadata_dict(row.get("config")),
        "summary": _metadata_dict(row.get("summary")),
        "created_at": row.get("created_at"),
        "started_at": row.get("started_at"),
        "completed_at": row.get("completed_at"),
    }


def _build_catalog_runtime_supersession_candidate(
    *,
    run_row: Mapping[str, Any],
    job_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    run_config = _metadata_dict(run_row.get("config"))
    return {
        "run_id": str(run_row.get("run_id") or run_row.get("id") or "").strip(),
        "run_status": str(run_row.get("status") or "").strip().lower() or None,
        "job_ids": [str(row.get("id") or "").strip() for row in job_rows if str(row.get("id") or "").strip()],
        "job_statuses": [
            str(row.get("status") or "").strip().lower() for row in job_rows if str(row.get("status") or "").strip()
        ],
        "job_types": [
            str(row.get("job_type") or "").strip().lower() for row in job_rows if str(row.get("job_type") or "").strip()
        ],
        "runner_strategy": str(run_config.get("runner_strategy") or "").strip().lower() or None,
        "partition_strategy": str(run_config.get("partition_strategy") or "").strip().lower() or None,
        "catalog_action": str(run_config.get("catalog_action") or "").strip().lower() or "backfill",
        "catalog_action_scope": str(run_config.get("catalog_action_scope") or "").strip().lower() or "full_history",
    }


def remediate_social_account_catalog_runtime_supersession(
    *,
    platform: str,
    account_handle: str,
    run_id: str | None = None,
    requeue_canary: bool = False,
    source_scope: str = "network",
    initiated_by: str | None = None,
    cancelled_by: str | None = None,
    superseded_by_runtime_version: Mapping[str, Any] | None = None,
    limit: int = 25,
) -> dict[str, Any]:
    normalized_platform = str(platform or "").strip().lower() or "instagram"
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    safe_limit = max(1, min(int(limit or 25), 100))
    normalized_run_id = (str(run_id).strip() if run_id else None) or None
    _assert_social_account_profile_exists(normalized_platform, normalized_account)

    candidate_run_rows: list[dict[str, Any]] = []
    if normalized_run_id:
        run_row = _load_social_account_catalog_run_row(
            platform=normalized_platform,
            account_handle=normalized_account,
            run_id=normalized_run_id,
        )
        candidate_run_rows.append(run_row)
    else:
        recent_runs = _catalog_recent_runs(normalized_platform, normalized_account, limit=safe_limit)
        for row in recent_runs:
            run_status = str(row.get("status") or "").strip().lower()
            if run_status not in {"queued", "pending", "retrying", "running", "cancelled"}:
                continue
            run_config = _metadata_dict(
                row.get("run_config") if row.get("run_config") is not None else row.get("config")
            )
            required_runtime_version = _metadata_dict(run_config.get("required_runtime_version"))
            if not required_runtime_version:
                continue
            candidate_run_rows.append(
                {
                    "id": str(row.get("run_id") or "").strip(),
                    "run_id": str(row.get("run_id") or "").strip(),
                    "status": run_status,
                    "source_scope": (
                        str(row.get("source_scope") or source_scope or "network").strip().lower() or "network"
                    ),
                    "config": run_config,
                    "summary": _metadata_dict(row.get("run_summary")),
                    "created_at": row.get("created_at"),
                    "started_at": row.get("started_at"),
                    "completed_at": row.get("completed_at"),
                }
            )

    candidate_runs: list[dict[str, Any]] = []
    cancelled_runs: list[dict[str, Any]] = []
    requeued_canary: dict[str, Any] | None = None

    for candidate_row in candidate_run_rows[:safe_limit]:
        candidate_run_id = str(candidate_row.get("run_id") or candidate_row.get("id") or "").strip()
        if not candidate_run_id:
            continue
        job_rows = _load_social_account_catalog_jobs(
            run_id=candidate_run_id,
            platform=normalized_platform,
            account_handle=normalized_account,
        )
        candidate_runs.append(
            _build_catalog_runtime_supersession_candidate(
                run_row=candidate_row,
                job_rows=job_rows,
            )
        )
        lock_key = _catalog_runtime_supersession_lock_key(candidate_run_id)
        lock_label = f"catalog-runtime-supersession:{candidate_run_id[:48]}"
        try:
            with pg.advisory_session_lock(lock_key, label=lock_label, pool_name="social_control") as lock_conn:
                locked_run = _load_catalog_run_row_by_id(candidate_run_id, conn=lock_conn)
                locked_config = _metadata_dict(locked_run.get("config"))
                existing_replacement = _find_catalog_replacement_run(
                    platform=normalized_platform,
                    account_handle=normalized_account,
                    superseded_run_id=candidate_run_id,
                    conn=lock_conn,
                )
                existing_replacement_id = (
                    str(locked_config.get("replacement_run_id") or "").strip()
                    or str((existing_replacement or {}).get("run_id") or "").strip()
                    or None
                )
                if existing_replacement_id:
                    _merge_catalog_run_config_with_conn(
                        conn=lock_conn,
                        run_id=candidate_run_id,
                        metadata_updates={
                            "cancel_reason": "runtime_superseded",
                            "supersession_handled": True,
                            "replacement_run_id": existing_replacement_id,
                            "auto_requeue_status": str(
                                (existing_replacement or {}).get("status")
                                or locked_config.get("auto_requeue_status")
                                or "queued"
                            )
                            .strip()
                            .lower(),
                        },
                    )
                    requeued_canary = {
                        "run_id": existing_replacement_id,
                        "status": str((existing_replacement or {}).get("status") or "").strip().lower() or None,
                    }
                    continue

                _merge_catalog_run_config_with_conn(
                    conn=lock_conn,
                    run_id=candidate_run_id,
                    metadata_updates={
                        "cancel_reason": "runtime_superseded",
                        "supersession_handled": True,
                        "superseded_by_runtime_version": _metadata_dict(superseded_by_runtime_version) or None,
                        "auto_requeue_status": "starting" if requeue_canary else "cancelled",
                    },
                )
                if str(locked_run.get("status") or "").strip().lower() != "cancelled":
                    cancelled_runs.append(
                        cancel_social_account_catalog_run(
                            platform=normalized_platform,
                            account_handle=normalized_account,
                            run_id=candidate_run_id,
                            cancelled_by=cancelled_by,
                            conn=lock_conn,
                        )
                    )
                if not requeue_canary:
                    continue
                try:
                    locked_run_config = _metadata_dict(locked_run.get("config"))
                    requeue_selected_tasks = _normalize_social_account_catalog_backfill_selected_tasks(
                        locked_run_config.get("selected_tasks")
                    )
                    requeue_source_scope = (
                        str(locked_run_config.get("source_scope") or source_scope or "network").strip().lower()
                        or "network"
                    )
                    requeue_catalog_scope = str(locked_run_config.get("catalog_action_scope") or "").strip().lower()
                    requeue_kwargs: dict[str, Any] = {
                        "platform": normalized_platform,
                        "account_handle": normalized_account,
                        "source_scope": requeue_source_scope,
                        "initiated_by": initiated_by,
                        "selected_tasks": requeue_selected_tasks,
                        # bug-2: preserve the superseded run's parallelism, media-followup
                        # toggle, and action/scope so the replacement does not silently
                        # degrade to single-worker, media-followups-off, or a re-derived
                        # scope. None preserves "unset" (launch applies its own default).
                        # NOTE: do NOT forward resume_frontier_cursor — it is not in the
                        # launch signature and would TypeError, cancelling the superseded
                        # run with no replacement.
                        "details_refresh_worker_count": _normalize_non_negative_int(
                            locked_run_config.get("details_refresh_worker_count")
                        )
                        or None,
                        "comments_worker_count": _normalize_non_negative_int(
                            locked_run_config.get("comments_worker_count")
                        )
                        or None,
                        "comments_enable_media_followups": locked_run_config.get("comments_enable_media_followups"),
                        "catalog_action": str(locked_run_config.get("catalog_action") or "").strip() or None,
                        "catalog_action_scope": requeue_catalog_scope or None,
                    }
                    if requeue_catalog_scope == "bounded_window":
                        requeue_kwargs["date_start"] = _coerce_dt(locked_run_config.get("date_start"))
                        requeue_kwargs["date_end"] = _coerce_dt(locked_run_config.get("date_end"))
                    requeue_result = launch_social_account_catalog_backfill(**requeue_kwargs)
                except Exception as exc:  # noqa: BLE001
                    _merge_catalog_run_config_with_conn(
                        conn=lock_conn,
                        run_id=candidate_run_id,
                        metadata_updates={
                            "auto_requeue_status": "failed",
                            "auto_requeue_error": str(exc),
                        },
                    )
                    raise
                replacement_run_id = str(requeue_result.get("run_id") or "").strip() or None
                if replacement_run_id:
                    _merge_catalog_run_config(
                        run_id=replacement_run_id,
                        metadata_updates={"superseded_run_id": candidate_run_id},
                    )
                _merge_catalog_run_config_with_conn(
                    conn=lock_conn,
                    run_id=candidate_run_id,
                    metadata_updates={
                        "replacement_run_id": replacement_run_id,
                        "auto_requeue_status": (
                            str(requeue_result.get("status") or "queued").strip().lower() or "queued"
                        ),
                    },
                )
                requeued_canary = requeue_result
        except pg.AdvisoryLockUnavailable:
            with pg.db_read_connection(label=lock_label) as read_conn:
                existing_replacement = _find_catalog_replacement_run(
                    platform=normalized_platform,
                    account_handle=normalized_account,
                    superseded_run_id=candidate_run_id,
                    conn=read_conn,
                )
            if existing_replacement:
                requeued_canary = {
                    "run_id": existing_replacement["run_id"],
                    "status": existing_replacement.get("status"),
                }
            continue
    return {
        "platform": normalized_platform,
        "account_handle": normalized_account,
        "candidate_job_count": sum(len(run.get("job_ids") or []) for run in candidate_runs),
        "candidate_runs": candidate_runs,
        "cancelled_runs": cancelled_runs,
        "requeued_canary": requeued_canary,
    }


def remediate_social_account_catalog_strategy_drift(
    *,
    platform: str,
    account_handle: str,
    run_id: str | None = None,
    requeue_canary: bool = False,
    source_scope: str = "network",
    initiated_by: str | None = None,
    cancelled_by: str | None = None,
    limit: int = 25,
) -> dict[str, Any]:
    return remediate_social_account_catalog_runtime_supersession(
        platform=platform,
        account_handle=account_handle,
        run_id=run_id,
        requeue_canary=requeue_canary,
        source_scope=source_scope,
        initiated_by=initiated_by,
        cancelled_by=cancelled_by,
        limit=limit,
    )


def dismiss_social_account_catalog_run(
    *,
    platform: str,
    account_handle: str,
    run_id: str,
    dismissed_by: str | None = None,
) -> dict[str, Any]:
    run_row = _load_social_account_catalog_run_row(
        platform=platform,
        account_handle=account_handle,
        run_id=run_id,
    )
    run_id = str(run_row.get("id") or "").strip()
    stored_status = str(run_row.get("status") or "").strip().lower()
    job_rows = _load_social_account_catalog_jobs(
        run_id=run_id,
        platform=platform,
        account_handle=account_handle,
    )
    status = _derive_run_progress_status(stored_status, job_rows)
    if status not in {"failed", "cancelled"}:
        progress_snapshot = get_social_account_catalog_run_progress(platform, account_handle, run_id)
        progress_status = str(progress_snapshot.get("run_status") or "").strip().lower()
        if progress_status in {"failed", "cancelled"}:
            status = progress_status
    if status not in {"failed", "cancelled"}:
        raise ValueError("Only failed or cancelled catalog runs can be dismissed.")
    run_config = _metadata_dict(run_row.get("config"))
    dismissed_at = str(run_config.get(_RUN_FAILURE_DISMISSED_AT_KEY) or "").strip()
    if dismissed_at:
        return {
            "run_id": run_id,
            "status": status,
            "dismissed": True,
            "dismissed_at": dismissed_at,
        }

    metadata_payload = {
        _RUN_FAILURE_DISMISSED_AT_KEY: _iso(_now_utc()),
        _RUN_FAILURE_DISMISSED_BY_KEY: dismissed_by,
    }
    run_failure_not_dismissed_sql = _run_failure_not_dismissed_sql("r")
    updated_row = pg.fetch_one(
        f"""
        update social.scrape_runs as r
        set config = coalesce(r.config, '{{}}'::jsonb) || %s::jsonb
        where r.id = %s::uuid
          and {run_failure_not_dismissed_sql}
        returning
          r.id::text as id,
          r.status,
          coalesce(r.config->>'{_RUN_FAILURE_DISMISSED_AT_KEY}', '') as dismissed_at
        """,
        [json.dumps(metadata_payload), run_id],
    )
    if not updated_row:
        raise ValueError("Only failed or cancelled catalog runs can be dismissed.")
    _invalidate_queue_status_cache()
    return {
        "run_id": str(updated_row.get("id") or "").strip(),
        "status": status,
        "dismissed": True,
        "dismissed_at": str(updated_row.get("dismissed_at") or "").strip()
        or metadata_payload[_RUN_FAILURE_DISMISSED_AT_KEY],
    }


def request_social_account_catalog_run_auth_repair(
    *,
    platform: str,
    account_handle: str,
    run_id: str,
    initiated_by: str | None = None,
) -> dict[str, Any]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    repair_environment = _catalog_run_auth_repair_environment(normalized_platform)
    repair_action = str(repair_environment.get("repair_action") or "").strip().lower() or None
    platform_label = normalized_platform.capitalize() or "Platform"
    if repair_action is None:
        raise SocialIngestValidationError(
            "CATALOG_RUN_AUTH_REPAIR_UNSUPPORTED",
            f"{platform_label} manual auth sync is not supported for this catalog run.",
        )
    if not bool(repair_environment.get("supported")):
        raise SocialIngestValidationError(
            "CATALOG_RUN_AUTH_REPAIR_UNSUPPORTED",
            f"{platform_label} manual auth sync can only be launched from a local TRR-Backend admin host.",
        )
    _load_social_account_catalog_run_row(
        platform=normalized_platform,
        account_handle=normalized_account,
        run_id=run_id,
    )
    progress = get_social_account_catalog_run_progress(normalized_platform, normalized_account, run_id)
    if str(progress.get("operational_state") or "").strip().lower() != "blocked_auth":
        raise SocialIngestValidationError(
            "CATALOG_RUN_AUTH_REPAIR_NOT_AVAILABLE",
            "This catalog run is not blocked on a repairable auth failure.",
        )
    repairable_reason = str(progress.get("repairable_reason") or "").strip().lower() or None
    resume_stage = str(progress.get("resume_stage") or "").strip().lower() or "discovery"
    repair_status = str(progress.get("repair_status") or "").strip().lower() or "idle"
    if repair_status != "running":
        _merge_catalog_run_config(
            run_id=run_id,
            metadata_updates={
                _RUN_AUTH_REPAIR_STATUS_KEY: "running",
                _RUN_AUTH_REPAIR_LAST_REQUESTED_AT_KEY: _iso(_now_utc()),
                _RUN_AUTH_REPAIR_LAST_REQUESTED_BY_KEY: initiated_by,
                _RUN_AUTH_REPAIR_STARTED_AT_KEY: _iso(_now_utc()),
                _RUN_AUTH_REPAIR_STARTED_BY_KEY: initiated_by,
                _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: None,
                _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: None,
                _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: None,
                _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: None,
                _RUN_AUTH_REPAIR_RESULT_KEY: None,
                _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
                _RUN_AUTH_REPAIR_RESUME_STAGE_KEY: resume_stage,
                _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: True,
            },
        )
    return {
        "run_id": run_id,
        "status": "accepted",
        "operational_state": "blocked_auth",
        "repair_action": repair_action,
        "repair_status": "running",
        "repairable_reason": repairable_reason,
        "auto_resume_pending": True,
        "resume_stage": resume_stage,
        "repair_environment": repair_environment,
    }


def execute_social_account_catalog_run_auth_repair(
    *,
    platform: str,
    account_handle: str,
    run_id: str,
    initiated_by: str | None = None,
    allow_cookie_refresh: bool = False,
) -> dict[str, Any]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    repair_environment = _catalog_run_auth_repair_environment(normalized_platform)
    repair_action = str(repair_environment.get("repair_action") or "").strip().lower() or None
    platform_label = normalized_platform.capitalize() or "Platform"
    if repair_action is None:
        raise SocialIngestValidationError(
            "CATALOG_RUN_AUTH_REPAIR_UNSUPPORTED",
            f"{platform_label} manual auth sync is not supported for this catalog run.",
        )
    if not bool(repair_environment.get("supported")):
        raise SocialIngestValidationError(
            "CATALOG_RUN_AUTH_REPAIR_UNSUPPORTED",
            f"{platform_label} manual auth sync can only be launched from a local TRR-Backend admin host.",
        )
    run_row = _load_social_account_catalog_run_row(
        platform=normalized_platform,
        account_handle=normalized_account,
        run_id=run_id,
    )
    progress = get_social_account_catalog_run_progress(normalized_platform, normalized_account, run_id)
    if (
        str(progress.get("operational_state") or "").strip().lower() != "blocked_auth"
        and str(progress.get("repair_status") or "").strip().lower() != "running"
    ):
        raise SocialIngestValidationError(
            "CATALOG_RUN_AUTH_REPAIR_NOT_AVAILABLE",
            "This catalog run is not blocked on a repairable auth failure.",
        )
    run_config = _metadata_dict(run_row.get("config"))
    source_scope = str(run_config.get("source_scope") or "network").strip().lower() or "network"
    repairable_reason = (
        str(progress.get("repairable_reason") or run_config.get(_RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY) or "")
        .strip()
        .lower()
        or None
    )
    modal_environment = str(repair_environment.get("modal_environment") or "").strip()
    if repair_action == "cookie_refresh":
        refresh_result = refresh_platform_cookies_interactive(
            normalized_platform,
            headless=True,
            timeout_seconds=180,
        )
        if not bool(_metadata_dict(refresh_result).get("success")):
            failure_reason = str(refresh_result.get("reason") or "repair_failed").strip().lower()
            _merge_catalog_run_config(
                run_id=run_id,
                metadata_updates={
                    _RUN_AUTH_REPAIR_STATUS_KEY: "failed",
                    _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: _iso(_now_utc()),
                    _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: initiated_by,
                    _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: failure_reason,
                    _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: failure_reason.replace("_", " "),
                    _RUN_AUTH_REPAIR_RESULT_KEY: refresh_result,
                    _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: False,
                    _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
                },
            )
            return {
                "ok": False,
                "run_id": run_id,
                "repair_status": "failed",
                "repairable_reason": repairable_reason,
                "failure_reason": failure_reason,
            }

        selected_tasks = _normalize_social_account_catalog_backfill_selected_tasks(run_config.get("selected_tasks"))
        result = launch_social_account_catalog_backfill(
            normalized_platform,
            normalized_account,
            source_scope=source_scope,
            date_start=_coerce_dt(run_config.get("date_start")),
            date_end=_coerce_dt(run_config.get("date_end")),
            initiated_by=initiated_by,
            inline_worker_id=None,
            allow_local_dev_inline_bypass=bool(run_config.get("allow_local_dev_inline_bypass")),
            execution_preference=str(run_config.get("execution_preference") or "auto").strip().lower() or "auto",
            selected_tasks=selected_tasks,
            existing_catalog_run_id=run_id,
            launch_group_id_override=str(run_config.get("launch_group_id") or "").strip() or None,
        )
        _merge_catalog_run_config(
            run_id=run_id,
            metadata_updates={
                _RUN_AUTH_REPAIR_STATUS_KEY: "succeeded",
                _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: _iso(_now_utc()),
                _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: initiated_by,
                _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: None,
                _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: None,
                _RUN_AUTH_REPAIR_RESULT_KEY: refresh_result,
                _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: False,
                _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
                _RUN_AUTH_REPAIR_RESUME_STAGE_KEY: "discovery",
                "selected_tasks": result.get("selected_tasks") or selected_tasks,
                "effective_selected_tasks": result.get("effective_selected_tasks") or selected_tasks,
            },
        )
        return {
            "ok": True,
            "run_id": run_id,
            "repair_status": "succeeded",
            "repairable_reason": repairable_reason,
            "resume_stage": "discovery",
        }
    try:
        with _shared_instagram_account_execution(normalized_account):
            repair_result = _instagram_auth_repair_module().run_repair(
                source_env=_TRR_BACKEND_REPO_ROOT / ".env",
                modal_environment=modal_environment,
                account_handle=normalized_account,
                allow_cookie_refresh=bool(allow_cookie_refresh),
                confirm_instagram_refresh=INSTAGRAM_AUTH_REFRESH_CONFIRMATION if allow_cookie_refresh else "",
            )
            if not bool(_metadata_dict(repair_result).get("ok")):
                failure_reason = str(repair_result.get("failure_reason") or "repair_failed").strip().lower()
                _merge_catalog_run_config(
                    run_id=run_id,
                    metadata_updates={
                        _RUN_AUTH_REPAIR_STATUS_KEY: "failed",
                        _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: _iso(_now_utc()),
                        _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: initiated_by,
                        _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: failure_reason,
                        _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: failure_reason.replace("_", " "),
                        _RUN_AUTH_REPAIR_RESULT_KEY: repair_result,
                        _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: False,
                        _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
                    },
                )
                return {
                    "ok": False,
                    "run_id": run_id,
                    "repair_status": "failed",
                    "repairable_reason": repairable_reason,
                    "failure_reason": failure_reason,
                }

            frontier = _get_shared_account_run_frontier(
                run_id=run_id,
                platform=normalized_platform,
                account_handle=normalized_account,
            )
            next_cursor = str(frontier.get("next_cursor") or "").strip() or None
            if next_cursor:
                resume_stage = "posts"
                enqueue_result = _coerce_shared_posts_enqueue_result(
                    _enqueue_shared_posts_job(
                        run_id=run_id,
                        platform=normalized_platform,
                        source_scope=source_scope,
                        account_handle=normalized_account,
                        shared_account_source_id=run_config.get("shared_account_source_id"),
                        pipeline_ingest_mode=str(
                            run_config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                        ),
                        runner_count=_normalize_non_negative_int(run_config.get("runner_count"))
                        or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                        expected_total_posts=_normalize_non_negative_int(frontier.get("total_posts")) or None,
                        runner_strategy=CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                        partition_strategy=CATALOG_FULL_HISTORY_FRONTIER_STRATEGY,
                        required_worker_lane=str(run_config.get("required_worker_lane") or "").strip().lower() or None,
                        required_execution_backend=str(run_config.get("required_execution_backend") or "")
                        .strip()
                        .lower()
                        or None,
                        allow_local_dev_inline_bypass=bool(run_config.get("allow_local_dev_inline_bypass")),
                        frontier_auth_allowed=True,
                        frontier_transport="authenticated",
                        transport_preference="authenticated",
                        allow_public_transport_fallback=False,
                        selected_tasks=run_config.get("selected_tasks"),
                        effective_selected_tasks=run_config.get("effective_selected_tasks"),
                        details_refresh_skip_detail_fetch=run_config.get("details_refresh_skip_detail_fetch"),
                        details_refresh_force_detail_fetch=run_config.get("details_refresh_force_detail_fetch"),
                        details_refresh_skip_media_followups=run_config.get("details_refresh_skip_media_followups"),
                        tiktok_comments_in_posts_stage=bool(run_config.get("tiktok_comments_in_posts_stage")),
                        tiktok_direct_comment_api_override=bool(run_config.get("tiktok_direct_comment_api_override")),
                        twitter_comments_in_posts_stage=bool(run_config.get("twitter_comments_in_posts_stage")),
                        initiated_by=initiated_by,
                    )
                )
                if not enqueue_result.queued:
                    failure_reason = (
                        "auth_cooldown_active"
                        if enqueue_result.status == "deferred_by_cooldown"
                        else "posts_requeue_failed"
                    )
                    repair_status = (
                        "deferred_by_cooldown" if enqueue_result.status == "deferred_by_cooldown" else "failed"
                    )
                    repair_payload = {
                        "ok": False,
                        "repair_result": repair_result,
                        "enqueue_status": enqueue_result.status,
                        "job_id": enqueue_result.job_id,
                        "auth_cooldown": enqueue_result.cooldown,
                        "error": enqueue_result.error,
                    }
                    _merge_catalog_run_config(
                        run_id=run_id,
                        metadata_updates={
                            _RUN_AUTH_REPAIR_STATUS_KEY: repair_status,
                            _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: _iso(_now_utc()),
                            _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: initiated_by,
                            _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: failure_reason,
                            _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: (
                                "Instagram posts requeue is deferred by auth cooldown."
                                if enqueue_result.status == "deferred_by_cooldown"
                                else (enqueue_result.error or "Instagram posts requeue failed.")
                            ),
                            _RUN_AUTH_REPAIR_RESULT_KEY: repair_payload,
                            _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: enqueue_result.status == "deferred_by_cooldown",
                            _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
                            _RUN_AUTH_REPAIR_RESUME_STAGE_KEY: resume_stage,
                        },
                    )
                    return {
                        "ok": False,
                        "run_id": run_id,
                        "repair_status": repair_status,
                        "repairable_reason": repairable_reason,
                        "resume_stage": resume_stage,
                        "failure_reason": failure_reason,
                        "auth_cooldown": enqueue_result.cooldown,
                    }
                _reactivate_catalog_run(run_id)
                _update_shared_account_run_frontier(
                    run_id=run_id,
                    platform=normalized_platform,
                    account_handle=normalized_account,
                    status="queued",
                    lease_owner=None,
                    lease_expires_at=None,
                    exhausted=False,
                    metadata_updates={
                        "auth_allowed": True,
                        "auth_reason": None,
                        "repair_repaired_at": _iso(_now_utc()),
                    },
                )
            else:
                resume_stage = "discovery"
                _reactivate_catalog_run(run_id)
                _enqueue_shared_discovery_job(
                    run_id=run_id,
                    platform=normalized_platform,
                    source_scope=source_scope,
                    account_handle=normalized_account,
                    shared_account_source_id=run_config.get("shared_account_source_id"),
                    pipeline_ingest_mode=str(
                        run_config.get("pipeline_ingest_mode") or SHARED_ACCOUNT_CATALOG_BACKFILL_INGEST_MODE
                    ),
                    runner_count=_normalize_non_negative_int(run_config.get("runner_count"))
                    or CATALOG_BACKFILL_FULL_HISTORY_RUNNER_COUNT,
                    expected_total_posts=_normalize_non_negative_int(run_config.get("expected_total_posts")) or None,
                    runner_strategy=str(
                        run_config.get("runner_strategy") or CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY
                    )
                    .strip()
                    .lower(),
                    partition_strategy=str(
                        run_config.get("partition_strategy") or CATALOG_FULL_HISTORY_CURSOR_PARTITION_STRATEGY
                    )
                    .strip()
                    .lower(),
                    required_worker_lane=str(run_config.get("required_worker_lane") or "").strip().lower() or None,
                    required_execution_backend=str(run_config.get("required_execution_backend") or "").strip().lower()
                    or None,
                    allow_local_dev_inline_bypass=bool(run_config.get("allow_local_dev_inline_bypass")),
                    frontier_auth_allowed=True,
                    frontier_auth_reason=None,
                    transport_preference="authenticated",
                    allow_public_transport_fallback=False,
                    date_start=_coerce_dt(run_config.get("date_start")),
                    date_end=_coerce_dt(run_config.get("date_end")),
                    selected_tasks=run_config.get("selected_tasks"),
                    effective_selected_tasks=run_config.get("effective_selected_tasks"),
                    details_refresh_skip_detail_fetch=run_config.get("details_refresh_skip_detail_fetch"),
                    details_refresh_force_detail_fetch=run_config.get("details_refresh_force_detail_fetch"),
                    details_refresh_skip_media_followups=run_config.get("details_refresh_skip_media_followups"),
                    tiktok_comments_in_posts_stage=bool(run_config.get("tiktok_comments_in_posts_stage")),
                    tiktok_direct_comment_api_override=bool(run_config.get("tiktok_direct_comment_api_override")),
                    twitter_comments_in_posts_stage=bool(run_config.get("twitter_comments_in_posts_stage")),
                    initiated_by=initiated_by,
                    priority=100,
                    recovery_depth=_normalize_non_negative_int(run_config.get("recovery_depth")) + 1,
                )
            _merge_catalog_run_config(
                run_id=run_id,
                metadata_updates={
                    _RUN_AUTH_REPAIR_STATUS_KEY: "succeeded",
                    _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: _iso(_now_utc()),
                    _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: initiated_by,
                    _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: None,
                    _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: None,
                    _RUN_AUTH_REPAIR_RESULT_KEY: repair_result,
                    _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: False,
                    _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
                    _RUN_AUTH_REPAIR_RESUME_STAGE_KEY: resume_stage,
                },
            )
            if is_queue_enabled() and is_modal_remote_executor_enabled():
                dispatch_due_social_jobs(run_id=run_id)
            return {
                "ok": True,
                "run_id": run_id,
                "repair_status": "succeeded",
                "repairable_reason": repairable_reason,
                "resume_stage": resume_stage,
            }
    except SocialIngestValidationError:
        raise
    except Exception as exc:  # noqa: BLE001
        logger.exception(
            "Instagram manual auth sync failed for run=%s platform=%s account=%s",
            run_id,
            normalized_platform,
            normalized_account,
        )
        failure_reason = type(exc).__name__.replace("Error", "").lower() or "repair_failed"
        _merge_catalog_run_config(
            run_id=run_id,
            metadata_updates={
                _RUN_AUTH_REPAIR_STATUS_KEY: "failed",
                _RUN_AUTH_REPAIR_COMPLETED_AT_KEY: _iso(_now_utc()),
                _RUN_AUTH_REPAIR_COMPLETED_BY_KEY: initiated_by,
                _RUN_AUTH_REPAIR_FAILURE_REASON_KEY: failure_reason,
                _RUN_AUTH_REPAIR_FAILURE_MESSAGE_KEY: str(exc),
                _RUN_AUTH_REPAIR_RESULT_KEY: {"ok": False, "failure_reason": failure_reason},
                _RUN_AUTH_REPAIR_AUTO_RESUME_PENDING_KEY: False,
                _RUN_AUTH_REPAIR_REPAIRABLE_REASON_KEY: repairable_reason,
            },
        )
        return {
            "ok": False,
            "run_id": run_id,
            "repair_status": "failed",
            "repairable_reason": repairable_reason,
            "failure_reason": failure_reason,
        }


def sync_recent_social_account_catalog(
    platform: str,
    account_handle: str,
    *,
    source_scope: str = "network",
    lookback_days: int = 1,
    initiated_by: str | None = None,
    inline_worker_id: str | None = None,
    allow_local_dev_inline_bypass: bool = False,
) -> dict[str, Any]:
    safe_lookback_days = max(1, min(int(lookback_days), 30))
    now_utc = _now_utc()
    return launch_social_account_catalog_backfill(
        platform,
        account_handle,
        source_scope=source_scope,
        date_start=now_utc - timedelta(days=safe_lookback_days),
        date_end=now_utc,
        initiated_by=initiated_by,
        inline_worker_id=inline_worker_id,
        allow_local_dev_inline_bypass=allow_local_dev_inline_bypass,
        catalog_action="sync_recent",
        catalog_action_scope="recent_window",
    )


def sync_newer_social_account_catalog(
    platform: str,
    account_handle: str,
    *,
    source_scope: str = "network",
    initiated_by: str | None = None,
    inline_worker_id: str | None = None,
    allow_local_dev_inline_bypass: bool = False,
) -> dict[str, Any]:
    """Fill the head gap: fetch all posts newer than the newest stored post."""
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    newest_at = _catalog_newest_stored_post_at(normalized_platform, normalized_account)
    if newest_at is None:
        raise SocialIngestValidationError(
            "NO_STORED_POSTS",
            "No stored posts found for this account. Run a full backfill first.",
        )
    now_utc = _now_utc()
    if newest_at >= now_utc:
        raise SocialIngestValidationError(
            "ALREADY_CURRENT",
            "Newest stored post is already at or beyond the current time.",
        )
    return launch_social_account_catalog_backfill(
        platform,
        account_handle,
        source_scope=source_scope,
        date_start=newest_at,
        date_end=now_utc,
        initiated_by=initiated_by,
        inline_worker_id=inline_worker_id,
        allow_local_dev_inline_bypass=allow_local_dev_inline_bypass,
        catalog_action="sync_newer",
        catalog_action_scope="head_gap",
    )


def resume_tail_social_account_catalog(
    platform: str,
    account_handle: str,
    *,
    source_scope: str = "network",
    initiated_by: str | None = None,
    inline_worker_id: str | None = None,
    allow_local_dev_inline_bypass: bool = False,
) -> dict[str, Any]:
    """Compatibility wrapper for the canonical Backfill Posts entrypoint."""
    selected_tasks = (
        list(SOCIAL_ACCOUNT_CATALOG_BACKFILL_SELECTED_TASKS)
        if _normalize_social_account_profile_platform(platform) == "instagram"
        else None
    )
    return launch_social_account_catalog_backfill(
        platform,
        account_handle,
        source_scope=source_scope,
        initiated_by=initiated_by,
        inline_worker_id=inline_worker_id,
        allow_local_dev_inline_bypass=allow_local_dev_inline_bypass,
        selected_tasks=selected_tasks,
    )


def resolve_social_account_catalog_review_queue_item(
    *,
    item_id: str,
    resolution_action: str,
    show_id: str | None = None,
    updated_by: str | None = None,
) -> dict[str, Any]:
    review_row = (
        pg.fetch_one(
            """
            select
              id::text as id,
              platform,
              source_scope,
              account_handle,
              normalized_hashtag
            from social.account_hashtag_review_queue
            where id = %s::uuid
            limit 1
            """,
            [item_id],
        )
        or {}
    )
    if not review_row:
        raise LookupError("Catalog review queue item not found.")
    normalized_action = str(resolution_action or "").strip().lower()
    if normalized_action not in {"assign_show", "mark_non_show"}:
        raise ValueError("Invalid catalog review resolution action.")
    platform = str(review_row.get("platform") or "")
    account_handle = str(review_row.get("account_handle") or "")
    hashtag = str(review_row.get("normalized_hashtag") or "")
    source_scope = str(review_row.get("source_scope") or "network")

    resolved_show_id = str(show_id or "").strip() or None
    if normalized_action == "assign_show" and not resolved_show_id:
        raise ValueError("show_id is required when assigning a show hashtag.")

    if normalized_action == "assign_show":
        put_social_account_profile_hashtags(
            platform,
            account_handle,
            hashtags=[
                {
                    "hashtag": hashtag,
                    "assignments": [
                        {
                            "show_id": resolved_show_id,
                        }
                    ],
                }
            ],
            updated_by=updated_by,
        )

    review_status = "resolved_non_show" if normalized_action == "mark_non_show" else "resolved_show_hashtag"
    pg.fetch_one(
        """
        update social.account_hashtag_review_queue
        set
          review_status = %s,
          resolved_show_id = %s::uuid,
          resolved_season_id = null,
          resolution_action = %s,
          resolved_at = now(),
          updated_by = %s,
          updated_at = now()
        where id = %s::uuid
        returning id::text
        """,
        [review_status, resolved_show_id, normalized_action, updated_by, item_id],
    )
    _classify_shared_catalog_rows(
        run_id="",
        platform=platform,
        source_scope=source_scope,
        account_handle=account_handle,
        source_ids=_catalog_source_ids_for_hashtag(platform, account_handle, hashtag),
    )
    return {
        "item_id": item_id,
        "review_status": review_status,
        "resolution_action": normalized_action,
        "resolved_show_id": resolved_show_id,
        "resolved_season_id": None,
    }


def _validate_social_account_profile_assignment_targets(
    hashtags: list[dict[str, Any]],
) -> dict[str, dict[str, Any]]:
    show_ids = sorted(
        {str(item.get("show_id") or "").strip() for item in hashtags if str(item.get("show_id") or "").strip()}
    )
    shows_by_id: dict[str, dict[str, Any]] = {}
    if show_ids:
        show_rows = pg.fetch_all(
            """
            select id::text as id, name, slug
            from core.shows
            where id = any(%s::uuid[])
            """,
            [show_ids],
        )
        shows_by_id = {str(row.get("id") or ""): row for row in show_rows if str(row.get("id") or "").strip()}
    missing_shows = [show_id for show_id in show_ids if show_id not in shows_by_id]
    if missing_shows:
        raise ValueError(f"Unknown show ids: {', '.join(missing_shows)}")
    return shows_by_id


def put_social_account_profile_hashtags(
    platform: str,
    account_handle: str,
    *,
    hashtags: list[dict[str, Any]],
    updated_by: str | None = None,
) -> dict[str, Any]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    _assert_social_account_profile_exists(normalized_platform, normalized_account)
    if not hashtags:
        raise ValueError("At least one hashtag payload item is required.")

    normalized_payload: list[dict[str, Any]] = []
    for item in hashtags:
        normalized_hashtag = _normalize_social_account_profile_hashtag(
            item.get("hashtag") or item.get("normalized_hashtag")
        )
        assignments_payload = list(item.get("assignments") or [])
        normalized_assignments: list[dict[str, Any]] = []
        for assignment in assignments_payload:
            assignment_scope = str(assignment.get("assignment_scope") or "global").strip().lower()
            assignment_platform = str(assignment.get("platform") or "").strip().lower()
            if assignment_scope != "global" or assignment_platform:
                raise ValueError(
                    "Platform-scoped hashtag assignments are not supported yet. "
                    "Use assignment_scope='global' and omit platform."
                )
            show_id = str(assignment.get("show_id") or "").strip()
            if not show_id:
                raise ValueError(f"Hashtag #{normalized_hashtag} is missing show_id for one assignment.")
            normalized_assignments.append(
                {
                    "show_id": show_id,
                    "season_id": None,
                }
            )
        normalized_payload.append(
            {
                "hashtag": normalized_hashtag,
                "display_hashtag": f"#{normalized_hashtag}",
                "assignments": normalized_assignments,
            }
        )

    flat_assignments = [
        {"show_id": assignment["show_id"], "season_id": assignment["season_id"]}
        for item in normalized_payload
        for assignment in item["assignments"]
    ]
    _validate_social_account_profile_assignment_targets(flat_assignments)

    hashtag_keys = [item["hashtag"] for item in normalized_payload]
    rows_to_insert: list[tuple[Any, ...]] = []
    seen_rows: set[tuple[str, str, str | None]] = set()
    for item in normalized_payload:
        for assignment in item["assignments"]:
            dedupe_key = (
                item["hashtag"],
                assignment["show_id"],
                assignment["season_id"],
            )
            if dedupe_key in seen_rows:
                continue
            seen_rows.add(dedupe_key)
            rows_to_insert.append(
                (
                    item["hashtag"],
                    item["display_hashtag"],
                    assignment["show_id"],
                    assignment["season_id"],
                    updated_by,
                )
            )
    with pg.db_connection() as conn:
        try:
            with pg.db_cursor(conn=conn) as cur:
                cur.execute(
                    """
                delete from social.hashtag_assignments
                where normalized_hashtag = any(%s)
                    """,
                    [hashtag_keys],
                )
            if rows_to_insert:
                pg.execute_values_no_return(
                    """
                    insert into social.hashtag_assignments (
                      normalized_hashtag,
                      display_hashtag,
                      show_id,
                      season_id,
                      updated_by
                    ) values %s
                    """,
                    rows_to_insert,
                    conn=conn,
                )
        except psycopg_errors.UndefinedTable as exc:
            raise ValueError(
                "Canonical social hashtag assignments schema is not migrated. "
                "Apply migration 20260629190000_canonical_social_hashtag_assignments.sql."
            ) from exc

    return get_social_account_profile_hashtags(normalized_platform, normalized_account)


def get_social_account_profile_collaborators_tags(*args: Any, **kwargs: Any) -> Any:
    from trr_backend.socials.read_models.account_profile.common import _LOCAL_ROOM_FUNCTIONS

    return _LOCAL_ROOM_FUNCTIONS["get_social_account_profile_collaborators_tags"](*args, **kwargs)


def preview_social_account_catalog_backfill_target(
    platform: str,
    account_handle: str,
    *,
    date_start: datetime,
    date_end: datetime,
) -> dict[str, Any]:
    normalized_platform = _normalize_social_account_profile_platform(platform)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    if normalized_platform not in set(CATALOG_SUPPORTED_PLATFORMS):
        raise ValueError("Catalog backfill is not supported for this platform.")
    bounded_start, bounded_end = _normalize_catalog_backfill_window(
        date_start=date_start,
        date_end=date_end,
    )
    assert bounded_start is not None and bounded_end is not None
    catalog_total = _shared_catalog_total_posts_for_window(
        normalized_platform,
        normalized_account,
        date_start=bounded_start,
        date_end=bounded_end,
    )
    materialized_total = _materialized_social_account_total_posts(
        normalized_platform,
        normalized_account,
        date_start=bounded_start,
        date_end=bounded_end,
    )
    return {
        "catalog_total": catalog_total,
        "materialized_total": materialized_total,
        "completion_target_posts": max(catalog_total, materialized_total),
        "completion_target_source": "bounded_catalog",
    }


def _instagram_payload_sidecar_sql(*, row_kind: str, row_alias: str, mode: str) -> tuple[str, str]:
    if mode == "legacy":
        return "", ""
    if row_kind == "mixed":
        return (
            f"""left join social.instagram_post_payloads payload_post_sidecar
              on {row_alias}._profile_source_surface = 'materialized'
             and payload_post_sidecar.post_id = {row_alias}.id::uuid
            left join social.instagram_account_catalog_post_payloads payload_catalog_sidecar
              on {row_alias}._profile_source_surface = 'catalog'
             and payload_catalog_sidecar.catalog_post_id = {row_alias}.id::uuid""",
            """,
          coalesce(payload_post_sidecar.raw_data, payload_catalog_sidecar.raw_data)
            as __payload_sidecar_raw_data,
          payload_post_sidecar.asset_manifest as __payload_sidecar_asset_manifest,
          coalesce(payload_post_sidecar.child_posts_data, payload_catalog_sidecar.child_posts_data)
            as __payload_sidecar_child_posts_data,
          (
            payload_post_sidecar.post_id is not null
            or payload_catalog_sidecar.catalog_post_id is not null
          ) as __payload_sidecar_present""",
        )
    if row_kind == "post":
        join = f"left join social.instagram_post_payloads payload_sidecar on payload_sidecar.post_id = {row_alias}.id"
        asset_projection = "payload_sidecar.asset_manifest"
        presence_projection = "payload_sidecar.post_id is not null"
    else:
        join = (
            "left join social.instagram_account_catalog_post_payloads payload_sidecar "
            f"on payload_sidecar.catalog_post_id = {row_alias}.id"
        )
        asset_projection = "null::jsonb"
        presence_projection = "payload_sidecar.catalog_post_id is not null"
    return (
        join,
        f""",
          payload_sidecar.raw_data as __payload_sidecar_raw_data,
          {asset_projection} as __payload_sidecar_asset_manifest,
          payload_sidecar.child_posts_data as __payload_sidecar_child_posts_data,
          ({presence_projection}) as __payload_sidecar_present""",
    )


def _log_instagram_payload_schema_unavailable(*, surface: str, entity_identity: Any) -> None:
    from trr_backend.socials.instagram.payload_compare import build_payload_compare_event

    logger.warning(
        "instagram payload sidecar schema unavailable: %s",
        build_payload_compare_event(
            surface=surface,
            entity_identity=entity_identity,
            legacy_payload={},
            new_payload={},
            sidecar_present=False,
            schema_unavailable=True,
        ),
    )


def _instagram_payload_rows_for_read(
    rows: Sequence[Mapping[str, Any]],
    *,
    row_kind: str,
    mode: str,
    surface: str,
) -> list[dict[str, Any]]:
    from trr_backend.socials.instagram import payload_sidecars
    from trr_backend.socials.instagram.payload_compare import (
        build_payload_compare_event,
        should_sample_payload_compare,
    )

    resolved_rows: list[dict[str, Any]] = []
    compare_legacy_payloads: list[dict[str, Any]] = []
    compare_new_payloads: list[dict[str, Any]] = []
    compare_identities: list[Any] = []
    compare_sidecar_presence: list[bool] = []
    for source_row in rows:
        row = dict(source_row)
        resolved_row_kind = row_kind
        if row_kind == "mixed":
            resolved_row_kind = (
                "catalog"
                if row.get("_row_kind") == "catalog" or row.get("_profile_source_surface") == "catalog"
                else "post"
            )
        payload_fields = (
            ("raw_data", "asset_manifest", "child_posts_data")
            if resolved_row_kind == "post"
            else ("raw_data", "child_posts_data")
        )
        sidecar_present = bool(row.get("__payload_sidecar_present"))
        legacy_payload = {field: row.get(field) for field in payload_fields}
        sidecar_payload = {
            "raw_data": row.get("__payload_sidecar_raw_data"),
            "asset_manifest": row.get("__payload_sidecar_asset_manifest"),
            "child_posts_data": row.get("__payload_sidecar_child_posts_data"),
        }
        new_payload = {
            field: payload_sidecars.payload_for_read_mode(
                legacy=legacy_payload.get(field),
                sidecar=sidecar_payload.get(field) if sidecar_present else None,
                mode="sidecar",
            )
            for field in payload_fields
        }
        identity = row.get("id") or row.get("source_id") or row.get("shortcode")
        if mode == "compare":
            compare_legacy_payloads.append(legacy_payload)
            compare_new_payloads.append(new_payload)
            compare_identities.append(identity)
            compare_sidecar_presence.append(sidecar_present)
        if mode == "sidecar":
            row.update(new_payload)
            if resolved_row_kind == "catalog":
                raw_data = (
                    cast(Mapping[str, Any], row.get("raw_data")) if isinstance(row.get("raw_data"), Mapping) else {}
                )
                if not row.get("hosted_media_urls") and isinstance(raw_data.get("hosted_media_urls"), list):
                    row["hosted_media_urls"] = raw_data["hosted_media_urls"]
                if not row.get("hosted_thumbnail_url") and raw_data.get("hosted_thumbnail_url"):
                    row["hosted_thumbnail_url"] = raw_data["hosted_thumbnail_url"]
                if not row.get("post_format") and raw_data.get("post_format"):
                    row["post_format"] = raw_data["post_format"]
                if not row.get("collaborators_detail") and isinstance(raw_data.get("collaborators_detail"), list):
                    row["collaborators_detail"] = raw_data["collaborators_detail"]
        for key in _INSTAGRAM_PAYLOAD_PRIVATE_KEYS:
            row.pop(key, None)
        resolved_rows.append(row)
    if (
        mode == "compare"
        and compare_identities
        and should_sample_payload_compare(
            surface=surface,
            entity_identity=compare_identities,
        )
    ):
        logger.info(
            "instagram payload compare: %s",
            build_payload_compare_event(
                surface=surface,
                entity_identity=compare_identities,
                legacy_payload=compare_legacy_payloads,
                new_payload=compare_new_payloads,
                sidecar_present=all(compare_sidecar_presence),
                schema_unavailable=False,
            ),
        )
    return resolved_rows


def _fetch_instagram_catalog_gallery_rows_page(
    account_handle: str,
    *,
    limit: int,
    offset: int = 0,
    statuses: list[str] | None = None,
    conn: Any | None = None,
    include_collaborators: bool | None = None,
    _payload_mode_override: str | None = None,
) -> tuple[list[dict[str, Any]], int]:
    """Fetch one narrow-key catalog page and its exact filtered total.

    The total rides on the same candidate scan as the page. An empty,
    out-of-range page has no window row, so only that case uses the narrow
    count-only fallback.
    """
    collaborators_available = (
        _instagram_catalog_gallery_collaborator_rows_available(conn=conn)
        if include_collaborators is None
        else include_collaborators
    )
    ctes_sql = _instagram_catalog_gallery_account_rows_cte_sql(
        statuses=statuses,
        include_collaborators=collaborators_available,
    )
    params = _instagram_catalog_gallery_account_rows_params(
        account_handle,
        statuses=statuses,
        include_collaborators=collaborators_available,
    )
    safe_limit = max(1, int(limit))
    safe_offset = max(0, int(offset))
    from trr_backend.socials.instagram import payload_sidecars

    payload_mode = _payload_mode_override or payload_sidecars.payload_read_mode()
    sidecar_join, sidecar_projection = _instagram_payload_sidecar_sql(
        row_kind="catalog",
        row_alias="p",
        mode=payload_mode,
    )
    query = f"""
            with {ctes_sql},
            page_keys as materialized (
              select
                id,
                posted_at,
                row_number() over (
                  order by posted_at desc nulls last, id desc
                )::int as page_rank,
                count(*) over()::int as total_count
              from touching_rows
              order by posted_at desc nulls last, id desc
              limit %s offset %s
            )
            select
              pk.page_rank,
              pk.total_count,
              p.id::text as id,
              p.source_id,
              p.assigned_show_id::text as show_id,
              p.assigned_season_id::text as season_id,
              p.source_account,
              p.posted_at,
              p.assignment_status,
              p.assignment_source,
              p.candidate_matches,
              s.season_number,
              sh.name as show_name,
              sh.slug as show_slug,
              p.title,
              p.caption,
              p.description,
              p.text,
              p.media_type,
              p.media_urls,
              p.thumbnail_url,
              p.hashtags,
              p.mentions,
              p.collaborators,
              p.profile_tags,
              p.likes,
              p.comments_count,
              p.views,
              p.shares,
              p.retweets,
              p.replies_count,
              p.quotes,
              p.raw_data,
              p.permalink
              {sidecar_projection}
            from page_keys pk
            join social.instagram_account_catalog_posts p on p.id = pk.id
            {sidecar_join}
            left join core.seasons s on s.id = p.assigned_season_id
            left join core.shows sh on sh.id = coalesce(p.assigned_show_id, s.show_id)
            order by pk.page_rank
            """
    try:
        query_params = [*params, safe_limit, safe_offset]
        if conn is not None:
            with pg.db_cursor(conn=conn, label="instagram_catalog_gallery_rows_page") as cur:
                rows = pg.fetch_all_with_cursor(cur, query, query_params)
        else:
            rows = pg.fetch_all(query, query_params)
    except psycopg_errors.UndefinedTable:
        if payload_mode != "legacy":
            _log_instagram_payload_schema_unavailable(
                surface="instagram.catalog.gallery",
                entity_identity=account_handle,
            )
            return _fetch_instagram_catalog_gallery_rows_page(
                account_handle,
                limit=limit,
                offset=offset,
                statuses=statuses,
                conn=conn,
                include_collaborators=collaborators_available,
                _payload_mode_override="legacy",
            )
        return [], 0
    rows = _instagram_payload_rows_for_read(
        rows,
        row_kind="catalog",
        mode=payload_mode,
        surface="instagram.catalog.gallery",
    )
    if rows:
        return rows, _normalize_non_negative_int(rows[0].get("total_count"))
    return [], _instagram_catalog_gallery_total_posts(
        account_handle,
        statuses=statuses,
        conn=conn,
        include_collaborators=collaborators_available,
    )


def _fetch_instagram_catalog_detail_rows(
    account_handle: str,
    *,
    source_id: str,
    conn: Any | None = None,
    _payload_mode_override: str | None = None,
) -> list[dict[str, Any]]:
    from trr_backend.socials.instagram import payload_sidecars

    payload_mode = _payload_mode_override or payload_sidecars.payload_read_mode()
    sidecar_join, sidecar_projection = _instagram_payload_sidecar_sql(
        row_kind="catalog", row_alias="p", mode=payload_mode
    )
    account_match = _shared_catalog_account_match_sql("instagram", alias="p")
    query = f"""
        select
          p.id::text as id,
          p.source_id,
          p.assigned_show_id::text as show_id,
          p.assigned_season_id::text as season_id,
          p.source_account,
          p.posted_at,
          p.assignment_status,
          p.assignment_source,
          p.candidate_matches,
          s.season_number,
          sh.name as show_name,
          sh.slug as show_slug,
          p.*
          {sidecar_projection}
        from social.instagram_account_catalog_posts p
        {sidecar_join}
        left join core.seasons s on s.id = p.assigned_season_id
        left join core.shows sh on sh.id = coalesce(p.assigned_show_id, s.show_id)
        where {account_match}
          and p.source_id = %s
        order by p.posted_at desc nulls last, p.id desc
        limit 1
    """
    params = [_normalize_social_account_profile_handle(account_handle), source_id]
    try:
        if conn is None:
            rows = pg.fetch_all(query, params)
        else:
            with pg.db_cursor(conn=conn, label="instagram_catalog_detail") as cur:
                rows = pg.fetch_all_with_cursor(cur, query, params)
    except psycopg_errors.UndefinedTable:
        if payload_mode == "legacy":
            return []
        _log_instagram_payload_schema_unavailable(
            surface="instagram.catalog.detail",
            entity_identity=source_id,
        )
        return _fetch_instagram_catalog_detail_rows(
            account_handle,
            source_id=source_id,
            conn=conn,
            _payload_mode_override="legacy",
        )
    return _instagram_payload_rows_for_read(
        rows,
        row_kind="catalog",
        mode=payload_mode,
        surface="instagram.catalog.detail",
    )


def _fetch_instagram_materialized_detail_row(
    account_handle: str,
    *,
    source_id: str,
    conn: Any | None = None,
    _payload_mode_override: str | None = None,
) -> dict[str, Any] | None:
    from trr_backend.socials.instagram import payload_sidecars

    payload_mode = _payload_mode_override or payload_sidecars.payload_read_mode()
    sidecar_join, sidecar_projection = _instagram_payload_sidecar_sql(row_kind="post", row_alias="p", mode=payload_mode)
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    owner_match_clause = _social_account_profile_owner_match_sql("instagram", alias="p")
    query = f"""
        select
          p.id::text as id,
          p.show_id::text as show_id,
          p.season_id::text as season_id,
          p.source_account,
          p.shortcode as source_id,
          p.posted_at,
          s.season_number,
          sh.name as show_name,
          sh.slug as show_slug,
          p.*
          {sidecar_projection}
        from social.instagram_posts p
        {sidecar_join}
        left join core.seasons s on s.id = p.season_id
        left join core.shows sh on sh.id = coalesce(p.show_id, s.show_id)
        where {owner_match_clause}
          and p.shortcode = %s
        order by p.posted_at desc nulls last, p.id desc
        limit 1
    """
    params = [normalized_account, source_id]
    try:
        if conn is None:
            row = pg.fetch_one(query, params)
        else:
            with pg.db_cursor(conn=conn, label="instagram_materialized_detail") as cur:
                row = pg.fetch_one_with_cursor(cur, query, params)
    except psycopg_errors.UndefinedTable:
        if payload_mode == "legacy":
            return None
        _log_instagram_payload_schema_unavailable(
            surface="instagram.profile.detail",
            entity_identity=source_id,
        )
        return _fetch_instagram_materialized_detail_row(
            account_handle,
            source_id=source_id,
            conn=conn,
            _payload_mode_override="legacy",
        )
    rows = _instagram_payload_rows_for_read(
        [row] if row else [],
        row_kind="post",
        mode=payload_mode,
        surface="instagram.profile.detail",
    )
    return rows[0] if rows else None


def _instagram_catalog_gallery_account_rows_cte_sql(
    *,
    statuses: list[str] | None = None,
    include_collaborators: bool = True,
) -> str:
    owner_status_clause = "and p.assignment_status = any(%s)" if statuses else ""
    if not include_collaborators:
        return f"""
            owner_rows as materialized (
              select
                p.id,
                p.posted_at
              from social.instagram_account_catalog_posts p
              where (
                lower(p.source_account) = %s
                or lower(p.owner_username) = %s
              )
                {owner_status_clause}
            ),
            touching_rows as materialized (
              select * from owner_rows
            )
            """

    collaborator_status_clause = "and p.assignment_status = any(%s)" if statuses else ""
    return f"""
            owner_rows as materialized (
              select
                p.id,
                p.posted_at
              from social.instagram_account_catalog_posts p
              where (
                lower(p.source_account) = %s
                or lower(p.owner_username) = %s
              )
                {owner_status_clause}
            ),
            collaborator_rows as materialized (
              select
                p.id,
                p.posted_at
              from social.instagram_account_catalog_post_collaborators m
              join social.instagram_account_catalog_posts p
                on p.id = m.catalog_post_id
              where m.collaborator_handle = %s
                and lower(coalesce(p.source_account, '')) <> %s
                and lower(coalesce(p.owner_username, '')) <> %s
                {collaborator_status_clause}
            ),
            touching_rows as materialized (
              select * from owner_rows
              union
              select * from collaborator_rows
            )
            """


def _instagram_catalog_gallery_account_rows_params(
    account_handle: str,
    *,
    statuses: list[str] | None = None,
    include_collaborators: bool = True,
) -> list[Any]:
    normalized_account = _normalize_social_account_profile_handle(account_handle)
    params: list[Any] = [normalized_account, normalized_account]
    if statuses:
        params.append(statuses)
    if include_collaborators:
        params.extend([normalized_account, normalized_account, normalized_account])
        if statuses:
            params.append(statuses)
    return params


def _instagram_catalog_gallery_collaborator_rows_available(*, conn: Any | None = None) -> bool:
    return _instagram_catalog_collaborator_membership_available(conn=conn)


def _instagram_catalog_gallery_total_posts(
    account_handle: str,
    *,
    statuses: list[str] | None = None,
    conn: Any | None = None,
    include_collaborators: bool | None = None,
) -> int:
    collaborators_available = (
        _instagram_catalog_gallery_collaborator_rows_available(conn=conn)
        if include_collaborators is None
        else include_collaborators
    )
    ctes_sql = _instagram_catalog_gallery_account_rows_cte_sql(
        statuses=statuses,
        include_collaborators=collaborators_available,
    )
    params = _instagram_catalog_gallery_account_rows_params(
        account_handle,
        statuses=statuses,
        include_collaborators=collaborators_available,
    )
    query = f"""
            with {ctes_sql}
            select count(*)::int as total
            from touching_rows
            """
    try:
        if conn is not None:
            with pg.db_cursor(conn=conn, label="instagram_catalog_gallery_total_posts") as cur:
                row = pg.fetch_one_with_cursor(cur, query, params) or {}
        else:
            row = pg.fetch_one(query, params) or {}
    except psycopg_errors.UndefinedTable:
        return 0
    return _normalize_non_negative_int(row.get("total"))


